P.entries["item:harpy-lieutenant-ring"] = {n="Перстень Лейтенанта Гарпій",s="Персні лейтенантів гарпій — грубі прикраси, які носять Убивці-Відьмокрилі на Сухих Пагорбах півночі Пусток. Ці знаки командування в зграї — доказ смерті для Дарсока Свіфтдаґґера на Перехресті.",h="Персні лейтенантів гарпій — грубі прикраси, які носять Убивці-Відьмокрилі на Сухих Пагорбах півночі Пусток.",kw={"перстень лейтенанта гарпій","гарпії","відьмокрилі","дарсок свіфтдаґґер","перехрестя","пустки"},ang={["class:Rogue"]="Дарсок Свіфтдаґґер віддає перевагу точним ударам по важливих цілях і цінує вбивць, здатних прослизнути в гнізда гарпій і знищити командирок просто там.",["faction:Horde"]="Гарпії-Відьмокрилі повсякчас турбують шляхи постачання між Дуротаром, Малгором і північними заставами; зламавши їхній провід, ви убезпечите шлях караванам Орди через Пустки."},sec={{t="Знаки звання",b="У матріархальній ієрархії гарпій-Відьмокрилих звання тримають жорстоко. Рядові нападниці, що турбують Пустки, б'ються майже без злагоди, а Убивці-Відьмокрилі — польові лейтенанти, що керують нападами на мандрівників Орди. Щоб вирізнитися й утвердити владу над підлеглими, ці досвідчені вбивці носять особливі персні. Для Дарсока Свіфтдаґґера й захисників Перехрестя зняти ці персні з полеглих гарпій — єдиний певний спосіб пересвідчитися, що середню ланку проводу зграї зламано."}},faq={{q="Хто носить ці персні?",a="Персні носять саме Вбивці Відьмокрилих — досвідчені гарпії, що служать лейтенантами в зграї Відьмокрилих на Сухих Пагорбах.",al={"хто дропає перстень лейтенанта гарпій","персні вбивць відьмокрилих","які гарпії мають персні"}},{q="Де знайти Вбивць Відьмокрилих?",a="Вбивці Відьмокрилих гніздяться на Сухих Пагорбах — скелястому піднесеному краї на далекій півночі Пусток, трохи на північний захід від Перехрестя.",al={"місце вбивць відьмокрилих","де лейтенанти гарпій","гарпії сухих пагорбів"}},{q="Навіщо вони Дарсоку Свіфтдаґґеру?",a="Дарсок хоче зруйнувати командний устрій гарпій. Знищення лейтенантів кидає їхні загони грабіжниць у хаос і карає зграю за напади на каравани й мандрівників Орди по всіх Пустках.",al={"навіщо збирати персні гарпій","персні дарсока свіфтдаґґера"}},{q="Чи носять ці персні звичайні гарпії-грабіжниці?",a="Ні. Звичайні грабіжниці — нижчі підлеглі. Персні означають командирське звання, і їх носять лише Вбивці Відьмокрилих.",al={"чи грабіжниці дропають персні","чи грабіжниці відьмокрилих мають персні"}}},fp="21,232,14.579.0,24.145.0,37.154.0,38.212.0,43.118.0"}
P.entries["item:head-of-arugal"] = {n="Голова Аруґала",s="Голова Аруґала — моторошний трофей, здобутий у божевільного архімага на вершині Фортеці Шадовфенг. Принесена Відступникам у Гробницю, вона — незаперечний доказ того, що володар місцевих воргенів упав.",h="Голова Аруґала — моторошний трофей, здобутий у божевільного архімага на вершині Фортеці Шадовфенг.",kw={"голова аруґала","архімаг аруґал","фортеця шадовфенг","срібнолісся","далар донвівер","воргени"},ang={["class:Mage"]="Відтята голова колишнього архімага Кірін-Тору — суворе застереження про божевілля й руїну, які неконтрольовані, відчайдушні виклики можуть накликати навіть на обдарованих чародіїв.",["race:Undead"]="Для Відступників голова Аруґала означає, що на їхньому південному порозі більше немає непередбачуваного чаклуна, і Срібнолісся тепер належить Темній Леді."},sec={{t="Трофей божевільного архімага",b="Архімаг Аруґал давно кидає темну тінь на Срібнолісся, керуючи вовкоподібними жахіттями з мурів Фортеці Шадовфенг. Здобути його відтяту голову — найвище доручення, яке дає Далар Донвівер у Гробниці. Для Відступників голова — куди більше, ніж моторошний трофей: вона означає, що усунуто могутнього чаклуна, чиї дикі звірі заважали Леді Сильвані цілком утвердити владу над Срібноліссям. Принесена Донвіверу, вона підтверджує, що мерзенне чаклунство архімага-ренегата нарешті відтято від цієї землі."}},faq={{q="Кому потрібна Голова Аруґала?",a="Голову вимагає Далар Донвівер, посланець у Гробниці в Срібноліссі, — у межах завдання «Аруґал мусить померти».",al={"кому потрібна голова аруґала","здати голову аруґала","хто бере голову аруґала"}},{q="Де здобути Голову Аруґала?",a="Її відтинають у самого Архімага Аруґала, що живе на найвищому шпилі Фортеці Шадовфенг над Селом Пайрвуд і лісами Срібнолісся.",al={"як отримати голову аруґала","дроп голови аруґала","де голова аруґала"}},{q="Чому Відступники хочуть смерті Аруґала?",a="Аруґал і його зграя диких воргенів не дають Відступникам перетворити Срібнолісся на безпечну стратегічну твердиню для Леді Сильвани й Андерсіті.",al={"чому вбити аруґала","чому відступники хочуть аруґала","чому далар хоче смерті аруґала"}},{q="Що стається, коли голову віддано?",a="Далар Донвівер присягається викорінити рештки мерзенних чарів Аруґала й оголошує, що Срібнолісся нарешті вирвалося з лещат божевільного чарівника.",al={"після смерті аруґала","результат завдання аруґал мусить померти"}}},fp="14,209,26.535.0,29.134.0,39.153.0,37.167.0,41.143.1"}
P.entries["item:head-of-bazil-thredd"] = {n="Голова Базіла Тредда",s="Відрубана голова Базіла Тредда — остаточний доказ того, що ватажка повстання у В'язниці знищено. Цей похмурий трофей, якого вимагає Наглядач Телвотер, кладе край організованій владі Братства Дефіас над підземною в'язницею Стормвінда.",h="Відрубана голова Базіла Тредда — остаточний доказ того, що ватажка повстання у В'язниці знищено.",kw={"голова базіла тредда","базіл тредд","наглядач телвотер","в'язниця стормвінда","братство дефіас","бунт"},ang={["faction:Alliance"]="Відрубана голова Тредда вгамовує паніку в столиці, доводячи, що правосуддя корони досі здатне дотягтися до самого серця бунтівної В'язниці."},sec={{t="Доказ кінця зради",b="Коли у В'язниці під Стормвіндом спалахнули заворушення, Базіл Тредд швидко став головним натхненником бунту. Засівши у своєму блоці камер разом з огром-охоронцем Окостом, Тредд спрямовував хаос із глибини підземних мурів. Не довіряючи стороннім і ледве тримаючи лад, Наглядач Телвотер зажадав голову Тредда як беззаперечний доказ його загибелі — й водночас як перевірку справжньої відданості шукача пригод Стормвіндові."}},faq={{q="Кому потрібна Голова Базіла Тредда?",a="Голову вимагає Наглядач Телвотер, що стоїть біля входу до В'язниці. Йому потрібен беззаперечний доказ, що ватажка вбито, — лише тоді він поділиться відомостями про спільників Тредда.",al={"кому потрібна голова тредда","куди здати голову тредда","видавець завдання голова тредда"}},{q="Хто такий Базіл Тредд?",a="Базіл Тредд — високопоставлений член Братства Дефіас, ув'язнений під Стормвіндом. Коли в'язні збунтувалися, він очолив заколот і керував ним із глибини східного блоку камер.",al={"хто такий базіл тредд","історія тредда","що зробив базіл"}},{q="Де знайти Базіла Тредда?",a="Базіл Тредд — у східному крилі В'язниці. Він засів у центральній камері в самому кінці блоку, а стереже його огр на ім'я Окіст.",al={"де тредд","місце тредда","як знайти базіла тредда"}}},fp="20,269,22.467.0,35.222.0,21.222.0,28.168.0"}
P.entries["item:head-of-deepfury"] = {n="Голова Діпф'юрі",s="Відрубана голова Кама Діпф'юрі — похмурий доказ того, що змовника з Темного Заліза, який стоїть за диверсією на Мосту Тандол, спіткав кінець. Його вбито серед заворушень у В'язниці Стормвінда, і ця смерть звершує особисту помсту дворфійських захисників Дун Модра.",h="Відрубана голова Кама Діпф'юрі — похмурий доказ того, що змовника з Темного Заліза, який стоїть за диверсією...",kw={"голова діпф'юрі","кам діпф'юрі","темне залізо","міст тандол","мотлі ґармасон","в'язниця стормвінда"},ang={["faction:Alliance"]="Ця нагорода показує дедалі більші тертя всередині Альянсу: людська юридична обережність у Стормвінді протиставлена суворому прикордонному правосуддю, якого вимагають горяни Айронфорджу.",["race:Dwarf"]="Для дворфів Айронфорджу голова Діпф'юрі — справа чистого кланового правосуддя: так сплачують кровний борг за зраду Темного Заліза на Мосту Тандол."},sec={{t="Правосуддя для змовника",b="Кама Діпф'юрі заарештували й замкнули у В'язниці Стормвінда з політичних міркувань: людська дипломатична бюрократія вберегла його від негайної страти. Для горян Айронфорджу, що стоять у Дун Модрі, така стриманість була неприйнятною. Відомості, які роздобув Роґґо, показали, що Діпф'юрі організував нищівний напад на Міст Тандол — напад, що забрав життя воїнів короля Маґні й рідних Лонґбрейда Похмурого. Обов'язок не дозволяє Мотлі Ґармасону покинути пост, тож він доручив звитяжцям Альянсу проникнути до збунтованої в'язниці й забрати голову Діпф'юрі — щоб справжня дворфійська помста звершилася там, де людська дипломатія схибила."}},faq={{q="Хто такий Кам Діпф'юрі?",a="Кам Діпф'юрі — підступний дворф із Темного Заліза, що допомагав готувати диверсію на Мосту Тандол — найважливішому сухопутному мості між Багнокраєм і Аратійським нагір'ям. Його змова забрала життя дворфів-захисників, зокрема брата Лонґбрейди Похмурого.",al={"історія кама діпф'юрі","хто такий діпф'юрі","передісторія кама діпф'юрі"}},{q="Чому Кама Діпф'юрі тримали у В'язниці, а не стратили?",a="Влада Стормвінда з політичних міркувань тримала Діпф'юрі живим. Людська бюрократія охоче залишила б його гнити в камері, але горяни Айронфорджа вважали таку поблажливість обурливою й вимагали крові.",al={"чому діпф'юрі у в'язниці","чому в'язниця"}},{q="Кому потрібна Голова Діпф'юрі?",a="Голову просить Мотлі Ґармасон — дворф із Дун Модра на півночі Багнокраю. Обов'язок честі тримає його на посту поруч із Лонґбрейдою Похмурим, тож Мотлі посилає шукача пригод завершити те, чого не може зробити сам.",al={"хто бере голову діпф'юрі","здати лють глибока"}},{q="Що дає принесена голова?",a="Відтята голова Діпф'юрі приносить розраду й справедливість скорботним дворфським родинам у Дун Модрі. Вона помщається за вбитого брата Лонґбрейди Похмурого й показує, що злочини проти Айронфорджа не поховати під людськими політичними іграми.",al={"чому принести голову діпф'юрі","результат люті глибокої"}}},fp="16,263,23.668.0,21.275.0,57.231.0,31.219.0,44.261.0"}
P.entries["item:head-of-gath-ilzogg"] = {n="Голова Ґат'Ілзоґґа",s="Відрубана голова Ґат'Ілзоґґа — незаперечний доказ того, що воєводу Блекрок убито. Здобути її — означає позбавити облогу Фортеці Кам'яної Варти проводу й принести Лейкширу таку жадану полегкість.",h="Відрубана голова Ґат'Ілзоґґа — незаперечний доказ того, що воєводу Блекрок убито.",kw={"ґат'ілзоґґ","голова ґат'ілзоґґа","блекрок","фортеця кам'яної варти","магістрат соломон","лейкшир"},ang={["faction:Alliance"]="Поки столицю відволікають внутрішні чвари, добровольцям Альянсу доводиться самим боронити Редрідж і знищувати ватажків Блекрок.",["race:Human"]="Для стормвіндців смерть Ґат'Ілзоґґа — це помста за вбитих невинних поселенців і за ганебне падіння Фортеці Кам'яної Варти."},sec={{t="Воєвода з ціною за голову",b="Ґат'Ілзоґґ очолив жорстокий наступ Блекрок, що захопив Фортецю Кам'яної Варти, вигнав її захисників і прирік навколишню долину на безперервні набіги. Лейкшир опинився на межі загибелі, а Стормвінд майже не надсилав підкріплення, тож Магістрат Соломон оголосив нагороду за голову воєводи. Убити Ґат'Ілзоґґа в укріплених верхніх ярусах Кам'яної Варти й забрати його голову означає розгромити місцеве командування Блекрок — це перший справжній крок до того, щоб повернути фортецю королівству."}},faq={{q="Хто такий Ґат'Ілзоґґ?",a="Ґат'Ілзоґґ — могутній воєвода орків Блекрок, що очолив захоплення Фортеці Кам'яної Варти й спрямовував набіги на поселення Гір Редріджу, поставивши Лейкшир на межу загибелі.",al={"хто такий ґат'ілзоґґ","історія ґат'ілзоґґа","бос стонвотчу"}},{q="Куди несуть голову, коли її здобуто?",a="Голову несуть просто Магістратові Соломону в ратушу Лейкширу як доказ, що нагороду з міської дошки розшуку заслужено.",al={"хто хоче голову","здати голову ґат'ілзоґґа","нагорода магістрата соломона"}},{q="Що смерть Ґат'Ілзоґґа означає для Лейкширу?",a="Його смерть позбавляє загарбників Блекрок головного тактика в Редріджі. Багато орків Блекрок досі засіли на Кам'яній Варті, але розірваний ланцюг командування дає місцевій обороні шанс утримати край.",al={"чи врятують лейкшир","значення вбивства ґат'ілзоґґа"}},{q="Де знайти Ґат'Ілзоґґа?",a="Він засів на горішніх ярусах Фортеці Кам'яної Варти, глибоко в захопленому укріпленні, разом зі своїми охоронцями й лейтенантами.",al={"де ґат'ілзоґґ","місце фортеці стонвотч"}}},fp="19,227,18.530.0,20.206.0,39.154.0,49.233.0,28.147.0"}
P.entries["item:head-of-grimson"] = {n="Голова Грімсона",s="Голова Ґрімсона — відтятий трофей, здобутий у Ґрімсона Блідого, зіпсованого наглядача Шахти Глибокого Елему в Срібноліссі. Принесена Даларові Донвіверу в Гробницю, вона — речовий доказ того, що верхівку шахти знищено. Захопивши шахту, Відступники здобувають цінні мінеральні багатства, щоб живити військові походи Варіматраса.",h="Голова Ґрімсона — відтятий трофей, здобутий у Ґрімсона Блідого, зіпсованого наглядача Шахти Глибокого Елему в...",kw={"голова ґрімсона","ґрімсон блідий","шахта глибокого елему","далар донвівер","варіматрас","срібнолісся"},ang={["profession:Mining"]="Шахта Глибокого Елему — одне з найбагатших родовищ Срібнолісся; тепер, коли божевільного наглядача немає, сира руда може текти в шляхи постачання Орди.",["race:Undead"]="Захоплення шахти виконує стратегічні накази верховного командування Андерсіті й доводить рішучість Відступників відвоювати важливі споруди Лордерона з рук божевільних решток."},sec={{t="Захопити Шахту Глибокого Елему",b="Поки Далар Донвівер у безпеці Гробниці вивчає тіньові чари Архімага Аруґала, розвідники Відступників, відомі як скрадачі смерті, помітили стратегічну загрозу, що назріває в південно-східних пагорбах. Темна магія Аруґала просочилася в Шахту Глибокого Елему, зіпсувала її робітників і довела наглядача, Ґрімсона Блідого, до божевілля. Щоб здобути підземні багатства для сил Варіматраса, Донвівер послав поборників зарубати Ґрімсона й принести його відтяту голову як незаперечний доказ того, що шахту звільнено від свавільної магії."},{t="Трофей для жахолорда",b="Для Відступників похмурі воєнні трофеї мають цілком практичну вагу. Голова Ґрімсона — запорука того, що підземних робітників Шахти Глибокого Елему зламано остаточно й будь-яка їхня вірність викривленому правлінню Аруґала скінчилася. Без Ґрімсона багаті рудні жили шахти можна видобувати й перековувати на зброю та обладунки, підтримуючи наступ Відступників через Срібнолісся й сусідні околиці Лордерона."}},faq={{q="Хто такий Ґрімсон Блідий?",a="Ґрімсон Блідий — наглядач Шахти Глибокого Елему на південно-східних пагорбах Срібнолісся. Під дією темної магії Архімага Аруґала, що ширилася краєм, Ґрімсон і його шахтарі піддалися її владі й перетворили шахту на зіпсовану твердиню — доки не втрутилися Відступники.",al={"хто такий ґрімсон","історія ґрімсона блідого","минуле ґрімсона"}},{q="Навіщо Даларові Донвіверу голова Ґрімсона?",a="Далару Донвіверу потрібен відчутний доказ, що зіпсованого наглядача знищено назавжди. Варіматрас прагне мінеральних багатств Шахти Глибокого Елему для воєнних потреб Відступників, а смерть Ґрімсона ламає опір зіпсованих шахтарів, що тримають тунелі.",al={"навіщо даларові голова ґрімсона","призначення голови ґрімсона","чому брати голову"}},{q="Де Шахта Глибокого Елему?",a="Шахта Глибокого Елему — на пагорбах на південний схід від Гробниці в Срібноліссі. Це важливе сховище копалин, за яке змагаються Відступники та зіпсовані рештки, підвладні магії Аруґала.",al={"де шахта глибокого елему","місце ґрімсона","місце шахти сільверпайну"}},{q="Яку роль у цьому завданні відіграє Варіматрас?",a="Варіматрас — воєначальник, що з Андерсіті керує поширенням Відступників по Лордерону. Ресурси Шахти Глибокого Елему прямо служать його стратегічним цілям — дають сировину для дедалі більшої воєнної машини в Срібноліссі.",al={"роль варіматраса","чому варіматрас хоче шахту","варіматрас сільверпайн"}}},fp="15,372,27.559.0,26.457.1,25.301.0,46.269.0,36.216.0,45.262.0"}
P.entries["item:head-of-kelris"] = {n="Голова Келріса",s="Відтята голова сутінкового володаря Келріса — незаперечний доказ того, що ватажок Молота Присмерку в Чорноглибинних Печерах загинув. Винесену зі спотворених руїн храму, її шукають представники Срібного Світанку, щоб підтвердити кінець його блюзнірських жертвоприношень.",h="Відтята голова сутінкового володаря Келріса — незаперечний доказ того, що ватажок Молота Присмерку в...",kw={"голова келріса","сутінковий володар келріс","молот присмерку","чорноглибинні печери","аку'май","срібний світанок"},ang={["faction:Alliance"]="Доставка голови Келріса Дозорцеві Світанку Селґорму в Дарнасус — помста за наругу над прадавнім храмом нічних ельфів, присвяченим Елуні.",["faction:Horde"]="Голова, принесена Башані Рунтотем у Тандер Блаф, здобуває довіру Кола Кенарія й доводить вашу відданість очищенню Калімдору від скверни."},sec={{t="Трофей руїни",b="У затоплених глибинах потонулого Храму Елуни сутінковий володар Келріс правив темні жертвоприношення Аку'маю — жахливому улюбленцеві Древніх Богів. Здобута голова Келріса кладе край його тиранічному проводу над сектантами Молота Присмерку та їхніми союзниками-нагами в печері. Моторошний трофей треба винести на поверхню, до цивілізованих земель, щоб запевнити очільників: криваві церемонії Келріса нарешті припинилися."},{t="Доказ для Світанку",b="Місяцями Срібний Світанок вважав Келріса мертвим чи зниклим, аж поки його зловісний вплив не виринув знову разом із тінями, що насуваються на Калімдор. Принесена посланцям у Дарнасусі чи Тандер Блафі, голова закриває давні нагороди й підтверджує, що його спроби кинути світ назад у первісний хаос зірвано."}},faq={{q="Хто такий сутінковий володар Келріс?",a="Келріс — ватажок секти Молота Присмерку, що засіла в Чорноглибинних Печерах. У союзі з нагами він влаштовував обрядові жертвопринесення невинних, щоб годувати Аку'май — гідру, слугу Древнього Бога, — прагнучи темної сили й прадавнього хаосу.",al={"хто такий келріс","історія келріса","сутінковий володар келріс"}},{q="Кому потрібна Голова Келріса?",a="Поборники Альянсу несуть голову Дозорцеві Світанку Селґорму в Дарнасус, а шукачі пригод Орди — Башані Рунтотем на Узвишшя Старійшин у Тандер Блафі. Дозорець Світанку Селґорм служить Срібному Світанку, а Башана Рунтотем належить до Кола Кенарія.",al={"хто бере голову келріса","здати голову келріса","кому віддати голову келріса"}},{q="Чому Срібний Світанок цікавиться Келрісом?",a="Срібний Світанок вистежує лихі загрози, що небезпечні для Азероту. Келріс був відомим лиходієм, який довго вислизав від них, а його поклоніння Древнім Богам і жертвопринесення невинних тяжко загрожували рівновазі Калімдору.",al={"чому срібний світанок келріс","срібний світанок чорноглибинні печери"}},{q="Де здобути голову?",a="Її відтинають від тіла сутінкового володаря Келріса в його святилищі в підземеллі Чорноглибинних Печер, під Узбережжям Зорам на березі Ашенвалю.",al={"де взяти голову келріса","місце голови келріса"}}},fp="14,294,16.422.0,18.339.0,29.249.0,29.262.0,43.224.0,27.173.0"}
P.entries["item:head-of-targorr"] = {n="Голова Тарґорра",s="Голова Тарґорра — похмурий доказ, якого вимагає Вартовий Бертон у Лейкширі, щоб переконатися в смерті Тарґорра Жахливого. Колись головний кат воєводи Блекрок Ґат'Ілзоґґа в Горах Редріджу, полонений орк був засуджений до смерті у В'язниці Стормвінда, але підозріле політичне втручання зупинило страту.",h="Голова Тарґорра — похмурий доказ, якого вимагає Вартовий Бертон у Лейкширі, щоб переконатися в смерті...",kw={"голова тарґорра","тарґорр жахливий","вартовий бертон","в'язниця стормвінда","ґат'ілзоґґ","лейкшир"},ang={["faction:Alliance"]="Для звитяжців Альянсу, що захищають Редрідж, смерть Тарґорра — помста за вбитих захисників Лейкширу й спосіб оминути продажну бюрократію вельмож Стормвінда.",["race:Human"]="Людські солдати й міські вартові мають із Тарґорром особисті рахунки за садистські тортури полонених воїнів королівства під час наступу Блекрок."},sec={{t="Відкладена страта",b="Тарґорр Жахливий здобув лиху славу по всьому Редріджу як жорстокий кат на службі воєводи клану Блекрок Ґат'Ілзоґґа. Він катував і вбивав захисників королівства Стормвінд, але зрештою його схопили й засудили до смерті у В'язниці Стормвінда. Проте бюрократичне втручання стормвіндських вельмож загадково зупинило виконання вироку, і місцеві вартові на кшталт Бертона запідозрили в столиці нечисту гру й корупцію."},{t="Прикордонне правосуддя",b="Побоюючись, що Тарґорра можуть використати як політичного пішака або що він якось влаштує втечу, Вартовий Бертон доручив сторонньому звитяжцеві проникнути до неспокійної в'язниці й завершити те, що суди відклали. Відрубана голова Тарґорра дозволила цілком оминути паралізоване правосуддя й принесла розраду скорботним родинам і обложеним захисникам Лейкширу, що постраждали від сокир ката."}},faq={{q="Хто такий Тарґорр Жахливий?",a="Тарґорр — сумнозвісний кат-орк із клану Блекрок у Редріджі. Він служив воєводі Ґат'Ілзоґґу й прославився тим, що катував і страчував полонених вояків і захисників Стормвінда.",al={"тарґорр","історія тарґорра","хто такий тарґорр"}},{q="Чому Тарґорра тримали живим у В'язниці?",a="Хоч його й засудили до смерті, стратити Тарґорра загадково завадили вельможі-бюрократи Стормвінда. Вартові в Лейкширі підозрюють політичну гру й корупцію і бояться, що орка тримають як козир у торгах.",al={"чому не стратити тарґорра","відстрочка тарґорра","суд у в'язниці"}},{q="Кому потрібна голова Тарґорра?",a="Відтяту голову просить Вартовий Бертон, що стоїть на мосту в Лейкширі. Бачивши різанину, яку Тарґорр учинив у Горах Редріджу, Бертон хоче мати беззаперечний доказ, що ката вже ніколи не звільнять.",al={"хто бере голову тарґорра","охоронець бертон","здати голову тарґорра"}},{q="Де знайти Тарґорра?",a="Тарґорр Жахливий ув'язнений у В'язниці Стормвінда — за залізними ґратами в центральних блоках камер, серед бунтівних в'язнів.",al={"місце тарґорра","знайти тарґорра","де у в'язниці"}}},fp="15,337,19.477.0,16.395.0,26.214.0,43.236.0,25.215.0,23.138.0"}
P.entries["item:head-of-vancleef"] = {n="Голова Ванкліфа",s="Відрубана голова Едвіна Венкліфа — моторошний і незаперечний доказ того, що ватажок Братства Дефіас загинув. Принесена з глибин Мертвих Копалень до Сентінел Гілла, вона знаменує тяжко здобуту відплату Народного ополчення.",h="Відрубана голова Едвіна Венкліфа — моторошний і незаперечний доказ того, що ватажок Братства Дефіас загинув.",kw={"голова венкліфа","едвін венкліф","братство дефіас","мертві копальні","сентінел гілл","народне ополчення"},ang={["class:Rogue"]="Едвін Венкліф був одним із найнебезпечніших майстрів-розбійників в історії людства; його голова ставить остаточну крапку в незрівнянній кар'єрі, збудованій на тінях і диверсіях.",["faction:Alliance"]="Голова Венкліфа дарує Народному ополченню очисну перемогу, але й підкреслює тривожну відсутність Дому Вельмож Стормвінда в найчорнішу годину Вестфолу."},sec={{t="Доказ падіння майстра",b="Місяцями Едвін Венкліф керував терором Братства Дефіас із найглибшого сховку Мертвих Копалень, під захистом озброєних до зубів розбійників, гоблінських інженерів і велетенського бойового корабля. Самими словами змучених поселенців Вестфолу не переконаєш, що їхній кошмар скінчився. Ґраян Стаутмантл, очільник Народного ополчення, вимагав незаперечного доказу, перш ніж оголосити край безпечним. Відрубана голова ватажка, винесена на денне світло, — відчутна запорука для виснажених захисників: той, хто задумав їхнє розорення, більше ніколи не загрожуватиме Вестфолу."},{t="Похмура перемога",b="Хоч Стаутмантл прагнув смерті Венкліфа заради блага Вестфолу, у цьому трофеї є важка урочистість. Колись Венкліф був шанованим майстром-будівничим, що відбудував Стормвінд після Першої війни, — доки зрада й невиплачені борги не штовхнули його разом із Гільдією Каменярів до розбійницького заколоту. Його відрубана голова вінчає похід місцевого ополчення Вестфолу, але водночас викриває неспроможність королівства дати раду власним негараздам: вершити найвище правосуддя довелося фермерам-добровольцям і заїжджим шукачам пригод."}},faq={{q="Кому потрібна Голова Ванкліфа?",a="Ґраян Стаутмантл, капітан Народного ополчення на Сентінел Гілл у Вестфолі, вимагає голову, щоб завершити довгу боротьбу з Братством Дефіас.",al={"кому віддати це","хто бере голову ванкліфа","куди голова ванкліфа"}},{q="Чому Ґраян Стаутмантл вимагає саме голову?",a="Братство Дефіас так довго тримало Вестфол за горло, що чуткам про смерть Венкліфа ніхто не повірить без беззаперечного речового доказу. Стаутмантлу потрібне незаперечне свідчення, щоб заспокоїти змучених фермерів і показати, що боротьба ополчення була не марна.",al={"чому брати голову","чому голова ванкліфа"}},{q="Де здобути голову?",a="Її забирають в Едвіна Венкліфа на його таємному броненосному кораблі, у самому кінці Мертвих Копалень під Мунбруком на південному заході Вестфолу.",al={"де взяти голову ванкліфа","як отримати голову ванкліфа"}},{q="Чи кінець Братству Дефіас, коли Венкліф загинув?",a="Стаутмантл вважає його смерть початком кінця братства, але відколоті ватаги, бандити-одинаки й прихильники досі тиняються Вестфолом, Лісом Елвінн і далі.",al={"чи дефіас знищено","що буде з дефіас"}}},fp="16,248,26.610.0,14.535.1,31.148.0,56.283.0,27.150.0,55.190.0"}
P.entries["item:heart-of-isha-awak"] = {n="Серце Іши Авак",s="Серце Іши Авак здобувають у могутнього морського чудовиська Іши Авак, Згуби Глибин Узбережжя Крамарів. Його шукає тауренський провидець Магрен Скайсір, і воно — доказ перемоги над одним із найгрізніших хижаків океану.",h="Серце Іши Авак здобувають у могутнього морського чудовиська Іши Авак, Згуби Глибин Узбережжя Крамарів.",kw={"серце іши авак","іша авак","згуба глибин","магрен скайсір","крамарське узбережжя","полювання"},ang={["class:Hunter"]="Вистежити й здолати Згубу Глибин під хвилями Узбережжя Крамарів — найвище випробування мисливської відваги в полюванні на водяну здобич.",["race:Tauren"]="Для тауренських мисливців гонитва за Ішею Авак — духовне єднання з найлютішими хижаками природи, за настановою старійшини Магрена Скайсіра."},sec={{t="Трофей Згуби Глибин",b="Біля залитих сонцем берегів Узбережжя Крамарів, на південь від Раджета, живе Іша Авак — величезний морський звір, якого шанують і бояться і моряки, і мешканці узбережжя. Відома як Згуба Глибин, ця істота забрала життя чималої кількості людей, що забрідали на узбережжя. Та для містика Магрена Скайсіра звір — радше шляхетний хижак, ніж безтямна загроза. Він вірить, що лютий дух Іши Авак живе просто в її серці, і доручає сміливим мисливцям пірнути в хвилі, здолати звіра в його власній стихії й здобути пульсуючий орган — і як трофей, і як духовну жертву."}},faq={{q="Що таке Серце Іши Авак?",a="Це серце Іши Авак — велетенського морського хижака-молотильника, що никає прибережними водами на південь від Раджета. Його здобувають на доказ того, що звіра вбито, для таурена-містика Магрена Скайсіра.",al={"серце іши авак","серце іша авак","що це за серце"}},{q="Кому потрібне Серце Іши Авак?",a="Магрен Скайсір, таурен-провидець, що отаборився на Торговому Узбережжі на південь від Раджета, просить мисливців принести серце, щоб ушанувати силу звіра й увібрати його дух.",al={"хто бере серце","кому віддати серце","магрен скайсір"}},{q="Де знайти Ішу Авак?",a="Іша Авак живе в океанських водах біля Торгового Узбережжя на сході Пусток і плаває на південь від гоблінського порту Раджет.",al={"місце іши авак","де іша авак","як знайти ішу авак"}},{q="Навіщо Магренові Скайсіру серце?",a="Магрен вважає Ішу Авак шляхетним мисливцем і гідним супротивником. Убивши звіра й тримаючи його серце, мисливець бере дух морської істоти в себе.",al={"чому вбити ішу авак","навіщо магрену серце"}}},fp="18,234,23.610.0,31.182.0,33.164.0,25.129.0,39.172.0"}
P.entries["item:heartswood"] = {n="Серцедерево",s="Серцедерево — деревина зі священного дерева, що вкоренилося серед Руїн Орділ'Арана на північному заході Ашенвалю. Воно виросло на місці останнього спочинку двох прадавніх закоханих, і його відлуння незгасної відданості робить його неодмінною принадою, щоб закликати сукуба.",h="Серцедерево — деревина зі священного дерева, що вкоренилося серед Руїн Орділ'Арана на північному заході...",kw={"серцедерево","руїни орділ'арана","анатера","латеріон","сукуб","чорнокнижник"},ang={["class:Warlock"]="Для чорнокнижників Альянсу здобути серцедерево — важливий обряд посвяти під проводом Ґакіна Зв'язувача Темряви: воно дає принаду для почуттів, потрібну, щоб примусити й підкорити собі сукуба-слугу.",["race:NightElf"]="Дерево — трагічний священний пам'ятник часів Війни Прадавніх, тож його осквернення чорнокнижниками й сектантами — гірка образа пам'яті полеглих предків."},sec={{t="Пам'ятник відданості",b="Серцедерево росте серед ельфійського каміння Руїн Орділ'Арана на північному заході Ашенвалю. За легендою, двоє закоханих, Анатера й Латеріон, полягли пліч-о-пліч під час згубної Війни Прадавніх тисячі років тому. На тій самій землі, де вони зробили останній подих, укоренилося незвичайне дерево, що розквітло як вічне свідчення їхньої відданості. Навіть через тисячоліття деревина з нього гуде пам'яттю незгасної пристрасті, тож вона дуже цікавить тих, хто вивчає душевні й духовні зв'язки."},{t="Знаряддя підкорення",b="Хоч серцедерево народилося з чистого почуття, воно привертає й темнішу увагу. Сукуби — демони, що живляться пристрастю, тугою й маніпуляцією почуттями, — нестримно тягнуться до речей, сповнених щирого, незгасного кохання. Чорнокнижники-люди й гноми за настановою Ґакіна Зв'язувача Темряви в Стормвінді шукають цю рідкісну деревину саме для того, щоб зробити обрядову принаду. Скориставшись природним відлунням жертви закоханих, чаклун може виманити сукуба з Нижнього Світу, затягти його в коло закликання й підкорити своїй волі."}},faq={{q="Що таке Серцедерево?",a="Серцедерево — деревина з дерева, що проросло в Ашенвалі, в Руїнах Ордил'Арана, на місці, де під час Війни Прадавніх разом загинули двоє закоханих нічних ельфів.",al={"дерево серцедерева","що таке серцедерево","історія серцедерева"}},{q="Хто такі Анатера й Латеріон?",a="Анатера й Латеріон — закохані, що пліч-о-пліч билися у Війні Прадавніх. Коли обоє полягли в бою, їхні останні обійми напоїли землю, і з неї виросло Серцедерево — вічний символ їхньої відданості.",al={"анатера та латеріон","закохані серцедерева","хто загинув біля серцедерева"}},{q="Навіщо чорнокнижникам Серцедерево?",a="Сукуби — демонічні істоти бажання й почуттєвих маніпуляцій. Серцедерево потужно відгукується на сутність незламного, вічного кохання, тож чорнокнижники використовують його як сильну принаду для душі, щоб спокусити й викликати сукуба в тілесний світ.",al={"чому чорнокнижники хочуть серцедерево","серцедерево сукуба","призначення серцедерева"}},{q="Де знайти Серцедерево?",a="Серцедерево — у Руїнах Ордил'Арана на північному заході лісу Ашенваль, біля кордону з Темним Узбережжям.",al={"місце серцедерева","де серцедерево","руїни орділ'арана серцедерево"}}},fp="10,260,22.556.0,21.537.1,19.192.0,32.238.0,32.254.0,30.141.0"}
P.entries["item:heartswood-core"] = {n="Осердя Серцедерева",s="Осердя Серцедерева — зачарований ритуальний осередок, вирізьблений із деревини прадавнього дерева. Його дає Ґакін Зв'язувач Темряви в Стормвінді, і воно спрямовує магію, потрібну, щоб пронизати Викривлений Нижній Світ й прикликати сукуба в таємне коло прикликання.",h="Осердя Серцедерева — зачарований ритуальний осередок, вирізьблений із деревини прадавнього дерева.",kw={"осердя серцедерева","ґакін","сукуб","чорнокнижник","прикликання","зарізане ягня"},ang={["class:Warlock"]="Осердя Серцедерева — необхідна навчальна реліквія для чорнокнижників Альянсу: знаряддя, через яке вони прикликають і підкоряють свого першого сукуба."},sec={{t="Осередок для Безодні",b="У темних криптах під таверною «Зарізане Ягня» у Кварталі магів Стормвінда чорнокнижники чинять обряди далеко від цікавих очей міської варти. Осердя Серцедерева — необхідний таємний провідник для початку ритуалу прив'язування. Виготовлене зі здобутого серцедерева, осердя містить досить залишкового магічного відлуння, щоб пронизати завісу між світами. Зосередивши свої темні мистецтва через деревину в освяченому колі прикликання, новачок може розірвати прохід до Викривленого Нижнього Світу й примусити сукуба перетнути межу між планами."},{t="Випробування прив'язування",b="Прикликати демона — лише половина боротьби; щоб ним керувати, треба довести цілковиту перевагу над його хитрою й спокусливою натурою. Ґакін довіряє Осердя Серцедерева перспективним практикам саме для того, щоб вони зустріли прикликаного демона в бою. Сукуби полюють на слабкість і легко долають кволий розум, тож ця зустріч — смертельно небезпечний обряд посвяти. Лише впокоривши нечисть і повернувши вичерпане осердя Ґакінові, майбутній чорнокнижник доводить, що його воля досить міцна, щоб назавжди прив'язати слугу."}},faq={{q="Для чого потрібне Осердя Серцедерева?",a="Чорнокнижники використовують Осердя Серцедерева як обрядовий реагент, щоб відчинити портал у колі виклику під корчмою «Зарізане Ягня». Портал змушує сукуба перейти з Викривленого Нижнього Світу в наш світ, щоб із ним можна було битися й прив'язати його.",al={"що робить осердя серцедерева","використання осердя серцедерева","призначення осердя серцедерева"}},{q="Хто дає Осердя Серцедерева?",a="Його дає Ґакін Зв'язувач Темряви — майстер-чорнокнижник, що навчає новачків у прихованих катакомбах під корчмою «Зарізане Ягня» в Кварталі магів Стормвінда.",al={"де взяти осердя серцедерева","хто дає осердя серцедерева"}},{q="Де треба використати осердя?",a="Осердя треба застосувати в рунічному колі виклику глибоко в склепах під корчмою «Зарізане Ягня», далеко під вулицями Стормвінда.",al={"місце осердя серцедерева","де викликати сукубу"}},{q="Що стається, коли обряд завершено?",a="Викликавши осердям сукуба, вам треба здолати демона в бою, щоб зламати його непокору. Коли його повернуто в порожнечу, віднесіть Осердя Серцедерева Ґакіну Зв'язувачу Темряви, щоб дізнатися таємницю, як викликати демона на власну волю.",al={"що робити після виклику","здати осердя серцедерева"}}},fp="15,258,22.573.0,20.527.1,37.232.0,33.169.0,28.151.0,42.241.0"}
P.entries["item:heavy-leaden-collection-phial"] = {n="Важка Свинцева Колекційна Колба",s="Важка Свинцева Колекційна Колба — захищена посудина для зразків, яку видає Оззі Тоґлвольт у Хараносі. Вона призначена, щоб безпечно відсмоктувати й зберігати вкрай нестійкі радіоактивні виділення мутантів із глибин Гномреґана для досліджень з очищення від зараження.",h="Важка Свинцева Колекційна Колба — захищена посудина для зразків, яку видає Оззі Тоґлвольт у Хараносі.",kw={"свинцева колба","оззі тоґлвольт","харанос","гномреґан","радіація","прокажені гноми"},ang={["profession:Engineering"]="Колба — спеціальне спорядження для збирання нестійких опадів; навіть із належною посудиною на це може піти кілька спроб.",["race:Gnome"]="Кожна крапля нестійких опадів у колбі — відчайдушний крок до повернення Гномреґана й до розуміння хімічного божевілля, що відібрало в гномів дім."},sec={{t="Захищена посудина",b="Важка Свинцева Колекційна Колба — посудина для зразків, якою відбирають нестійкі рештки з живих опромінених істот у Гномреґані. Утримати ці опади нелегко, тож, щоб зібрати придатний зразок, може знадобитися кілька спроб."},{t="Пошуки ліків",b="Оззі Тоґлвольт видає колбу в межах своїх досліджень, спрямованих на те, щоб обернути назад жахливі мутації прокажених гномів. Попереднім зразкам, узятим із трогів на поверхні, бракувало сили для дієвого хімічного аналізу. Застосовуючи свинцеву колбу на заразних потворах, як-от опромінених слизнях і причаєнцях у Залі Шестерень, дослідники сподіваються виокремити діючі складники отруйних опадів міста й створити дієву протиотруту."}},faq={{q="Для чого потрібна Важка Свинцева Колекційна Колба?",a="Нею висотують зосереджені радіоактивні виділення просто з живих опромінених істот у Гномреґані, щоб дати дослідникам у Хараносі чисті зразки для випробувань знезараження.",al={"що робить ця колба","призначення колби","що таке свинцева колба"}},{q="Хто дає Важку Свинцеву Колекційну Колбу?",a="Її дає гном-дослідник Оззі Тоґлвольт біля Хараноса в Дун Мороґу — для своїх пошуків ліків для опромінених і уражених прокажених гномів.",al={"хто дає колбу","де взяти колбу","видавець завдання колба"}},{q="Чому колба з важкого свинцю?",a="Її описано як важку свинцеву колбу, але як саме вона влаштована, не пояснено. Оззі застерігає, що втримати радіоактивні опади важко і що зразок швидко розпадеться.",al={"чому свинцева колба","чому важкий свинець"}},{q="З яких істот треба брати пробу колбою?",a="Її застосовують до живих світних потвор у глибинах Гномреґана — опромінених слизів, причаєнців і жахіть, що никають нижніми рівнями Зали Шестерень.",al={"на кого використати","цільові істоти","які монстри світяться"}}},fp="29,264,17.232.0,17.434.0,51.196.0,47.155.0,36.195.0,47.180.0"}
P.entries["item:hezrul-s-head"] = {n="Голова Гезрула",s="Голова Гезрула — моторошний трофей, здобутий у Гезрула Бладмарка, ватажка кентаврів-колкарів, що живуть у Пустках. Принесена Реґтарові Дезґейту на захід від Перехрестя, вона — незаперечний доказ того, що головний провід місцевих грабіжників упав.",h="Голова Гезрула — моторошний трофей, здобутий у Гезрула Бладмарка, ватажка кентаврів-колкарів, що живуть у...",kw={"голова гезрула","гезрул бладмарк","колкари","реґтар дезґейт","оаза буйних вод","кентаври"},ang={["faction:Horde"]="Голова ватажка колкарів убезпечує важливі права на воду в Оазі Буйних Вод і захищає мандрівників Орди, що перетинають посушливі Пустки.",["race:Orc"]="Реґтар Дезґейт вважає колкарів недисциплінованими головорізами, чию сиру лють легко долає орківська бойова дисципліна, тож цей трофей — свідчення справжньої бойової честі."},sec={{t="Колкари без голови",b="Кентаври-колкари агресивно тримають важливі оази по всіх посушливих Пустках, повсякчас загрожуючи шляхам постачання Орди й молодим поселенням. Гезрул Бладмарк керує своїм кланом з Оази Буйних Вод на півдні. Реґтар Дезґейт, досвідчений орк, якому доручено вберегти землі на захід від Перехрестя, розуміє: колкарі мають люту силу, але їм бракує справжньої дисципліни. Вимагаючи відтяту голову Гезрула, Реґтар прагне розколоти командування клану, посіяти безлад серед уцілілих бійців і зламати їхні злагоджені напади на Орду."}},faq={{q="Кому належить ця голова?",a="Голова належить Гезрулу Бладмарку — жорстокому й підступному ватажкові клану кентаврів Колкар, що заполонили центр Пусток.",al={"хто такий гезрул","особа гезрула","чия це голова"}},{q="Де знайти Гезрула Бладмарка?",a="Гезрул водить свою ватагу довкола Оази Буйних Вод, на південь від Перехрестя в Пустках.",al={"місце гезрула","де гезрул","знайти гезрула"}},{q="Кому потрібна Голова Гезрула?",a="Реґтар Дезґейт, орк із військової застави при дорозі на захід від Перехрестя, просить голову як доказ перемоги над вождем.",al={"здати голову гезрула","хто бере голову гезрула","реґтар деткейт"}},{q="Чому Орді потрібна його голова, а не просто вигнати його?",a="Орді потрібна цілковита певність, що Гезрул мертвий. Кентаври від природи мінливі й схильні до чвар, тож знищення верховного вождя руйнує їхній устрій командування й зменшує загрозу для Перехрестя.",al={"чому вбити гезрула","чому голова","загроза кентаврів"}}},fp="13,266,23.614.0,29.125.0,32.101.0,24.150.0,69.239.0"}
P.entries["item:high-potency-radioactive-fallout"] = {n="Високопотужні Радіоактивні Опади",s="Високопотужні Радіоактивні Опади — концентрований, нестійкий зразок опроміненого мулу, що отруює нижні глибини Гномреґана. Його збирають у важкі свинцеві посудини на замовлення гномів-дослідників, сподіваючись розгадати його склад і створити ліки для уражених прокажених гномів.",h="Високопотужні Радіоактивні Опади — концентрований, нестійкий зразок опроміненого мулу, що отруює нижні...",kw={"високопотужні радіоактивні опади","радіація","гномреґан","оззі тоґлвольт","прокажені гноми","свинцева колба"},ang={["profession:Engineering"]="Щоб зберігати й перевозити нестійкі ізотопи, що розпадаються, потрібні спеціальні свинцеві колби, які захищають носія від катастрофічного опромінення.",["race:Gnome"]="Кожна крапля отруйних опадів, зібрана в глибинах міста, — крихка надія обернути назад жахливу мутацію, що понівечила ваших родичів під час падіння Гномреґана."},sec={{t="Просто з джерела",b="Слабкі зразки радіації можна зішкребти із заражених падальників на поверхні, але справжнє серце катастрофи Гномреґана вимагає чогось значно концентрованішого. Дослідникам, що чатують біля полеглої столиці, потрібні сирі, нерозбавлені радіоактивні опади, узяті просто з живих опромінених потвор, причаєнців і слизнів, що повзають найнижчими ярусами Зали Шестерень. Оскільки цей в'язкий мул безперервно розпадається, його треба тримати в особливій свинцевій колбі й швидко доставити, доки зразок не втратив стійкості зовсім."},{t="Пошуки відновлення",b="Відчайдушна гонитва за такими смертоносними матеріалами має нагальну мету. Оззі Тоґлвольт і його колеги вірять, що розгадка таємниць опроміненого мулу — єдиний реальний шлях до ліків для прокажених гномів. Збожеволілі й спотворені отруйними викидами, наказаними під час вторгнення трогів, ці трагічні вцілілі досі живуть у справжньому кошмарі, тож навіть найнебезпечніші вилазки по зразки в руїни варті ризику."}},faq={{q="Звідки беруться ці радіоактивні опади?",a="Їх добувають просто з живих опромінених істот — опромінених слизів, жахіть і причаєнців, — що живуть глибоко на нижніх рівнях Зали Шестерень Гномреґана.",al={"де взяти опади","місце опадів","джерело радіоактивних опадів"}},{q="Навіщо потрібна ця проба?",a="Гномським дослідникам, зокрема Оззі Тоґлвольту, потрібна нерозбавлена, висококонцентрована проба випромінювання Гномреґана, щоб вивчити недугу й спробувати створити ліки для своїх зіпсованих родичів — прокажених гномів.",al={"хто хоче опади","призначення опадів","навіщо збирати опади"}},{q="Чому з ними треба поводитися так обережно?",a="Опади вкрай нестійкі й швидко розпадаються. Щоб безпечно їх перевезти, потрібна важка свинцева посудина, і доставити їх дослідникам треба раніше, ніж їхня сила вивітриться в непотрібний осад.",al={"розпад опадів","чому свинцева колба","нестабільні опади"}},{q="Чому не годився попередній осад із трогів?",a="Осад, зібраний із трогів на поверхні за межами міста, виявився надто слабким і нечистим для наукових випробувань. Дослідникам потрібне саме сире, зосереджене сяйво, яке є лише в істотах із глибин опроміненого міста.",al={"чому не троґи","троґи проти опадів","невдала попередня проба"}}},fp="32,288,21.557.0,24.468.0,46.174.0,26.218.0,36.218.0,45.253.0"}
P.entries["item:highborne-relic-classic"] = {n="Реліквія Високородних (класика)",s="Реліквії Високородних — давні магічні знаряддя, які відбирають у неспокійних духів, що блукають руїнами Амет'Арана на Темному Узбережжі. Просякнуті тим самим необачним тайним чаклунством, що колись зруйнувало давній Калімдор, вони потрібні вченим нічних ельфів — ті хочуть знищити реліквії, доки їхні приспані сили не наробили ще більше лиха.",h="Реліквії Високородних — давні магічні знаряддя, які відбирають у неспокійних духів, що блукають руїнами...",kw={"реліквія високородних","високородні","амет'аран","тундріс віндвівер","привиди","темне узбережжя"},ang={["class:Mage"]="Магам тайна майстерність реліквій може видатися захопливою, але місцева влада нічних ельфів не терпить жодних вагань щодо їхнього знищення.",["race:NightElf"]="Для нічних ельфів ці реліквії — похмуре нагадування про згубну тайну пиху, яка розірвала їхню давню цивілізацію."},sec={{t="Рештки Розколу",b="Десять тисяч років тому каста Високородних віддавалася безрозсудній тайній магії, що зрештою занапастила давній Калімдор. Сьогодні їхні колишні маєтки лежать у руїнах по всьому Темному Узбережжю. Серед поруйнованих колон Амет'Арана лісом блукають примари, що голосять і корчаться, безкінечно чіпляючись за знаряддя свого колишнього чаклунства. Ці реліквії — вперті вузли тайної скверни, затиснуті в руках привидів, які не хочуть випустити знаряддя власної загибелі."},{t="Очищення від тайної скверни",b="Для сучасного суспільства нічних ельфів, яке після Великого Розколу здебільшого зреклося тайної магії, такі артефакти — тяжка небезпека. Учені на кшталт Тундріса Віндвівера в Обердайні, спираючись на донесення Вартових, доручають мандрівникам вирвати ці реліквії з примарних рук проклятих духів. Зібрані реліквії старанно знищують, щоб давнє зло й катастрофічні помилки Високородних ніколи не повторилися."}},faq={{q="Звідки беруться Реліквії Високородних?",a="Їх забирають у примарних привидів, що блукають руїнами Амет'Аран на схід від головного шляху на півдні Темного Узбережжя. Прокляті, корчиві й лементливі духи Високородних носять їх серед прадавніх каменів.",al={"де знайти реліквії високородних","хто дропає реліквії високородних","місце реліквії"}},{q="Навіщо Тундрісу Віндвіверу ці реліквії?",a="Тундріс Віндвівер боїться магічної скверни, що досі чіпляється до цих прадавніх речей. Він збирає їх, щоб цілком розібрати й знищити, — аби ніхто не відродив небезпечного чаклунства Високородних.",al={"навіщо збирати реліквії","що буде з реліквіями","мета віндвівера"}},{q="Чому духи Високородних досі в Амет'Аран?",a="Ці духи — прадавня знать Високородних, що загинула, коли десять тисяч років тому світ розколовся. Прокляті власною пихою й незгасною прихильністю до магії, їхні неспокійні душі лишаються прив'язаними до руїн свого колишнього міста.",al={"чому духи в амет'аран","хто прокляті високородні","чому привиди на темному узбережжі"}},{q="Чи безпечно користуватися Реліквіями Високородних?",a="Ні. Нічні ельфи вважають їх оскверненими мерзенною, неприборканою магією, що спричинила Великий Розкол. Їхня приспана магія небезпечна, тому вчені вимагають їх знищити, а не вивчати.",al={"чи можна користуватися реліквіями","чи небезпечні реліквії"}}},fp="25,317,25.506.0,24.481.0,36.217.0,47.230.0,50.238.0,33.234.0"}
P.entries["item:highperch-venom-sac"] = {n="Отруйний Мішечок Хайперча",s="Отруйні Мішечки Хайперча добувають у диких віверн, що гніздяться на височенних шпилях Високосіду в Тисячі Голок. Орки цінують віверн як летючих скакунів, але дехто з аптекарів і торговців цінує їхні сильні жала навіть більше, ніж живих звірів.",h="Отруйні Мішечки Хайперча добувають у диких віверн, що гніздяться на височенних шпилях Високосіду в Тисячі...",kw={"отруйний мішечок","високосід","віверни","тисяча голок","фіора лонґірс","отрута"},ang={["class:Rogue"]="Висококонцентрована паралізувальна отрута неприручених віверн Тисячі Голок — одна з найсильніших природних отрут Калімдору.",["faction:Alliance"]="Удар по гніздах Високосіду служить Альянсу подвійно: це й цінні реагенти для торгівлі, і менше диких звірів, яких інакше могли б зловити й об'їздити для Орди."},sec={{t="Цінний урожай",b="На високих шпилях Тисячі Голок живуть чималі зграї диких віверн, особливо довкола піднесених скель Високосіду. Ці крилаті хижаки паралізують і вбивають здобич сильною отрутою, яку впорскують зазубреним хвостом. Орда часто приручає цих істот як вірних вітрокрилів, але їхні отруйні мішечки коштують напрочуд дорого серед алхіміків, мисливців і спритних торговців по всьому Калімдору."},{t="Далекий покупець",b="Хоча віверни живуть у глибоких каньйонах центрального Калімдору, їхньою отрутою цікавляться й на іншому кінці континенту. У тихому портовому містечку Обердайн нічна ельфійка Фіора Лонґірс щедро платить за свіжі мішечки, зібрані у виводків Високосіду. Їй потрібні мішечки, повні отрути, — такі зазвичай бувають лише в молодих віверн або плідних самиць, — і це живить торгівлю небезпечними реагентами далеко від природних пустельних угідь звірів."}},faq={{q="Які істоти носять ці отруйні мішечки?",a="Їх добувають просто з диких виверн, що живуть на Високосіді в Тисячі Голок, — виверн Високосіду, їхніх патріархів і подруг, а також матріархині Серцеріз.",al={"де падають мішечки отрути","хто дропає отруту хайперча","отрута виверни"}},{q="Навіщо Фіорі Лонґірс ця отрута на Темному Узбережжі?",a="Фіора Лонґірс знає, що отрута виверн надзвичайно цінна в певних торгових колах — часом вигідніша за самих верхових тварин. Вона доручає мандрівникам, що прямують на Високосід у Тисячі Голок, добути для торгівлі цілі мішечки.",al={"навіщо фіорі отрута","хто купує отруту в обердайні","хто купує отруту виверн"}},{q="Чи всі отруйні мішечки виверн однакові?",a="Сила й об'єм отрути різняться. Найцінніші мішечки — набряклі, аж розпирає від отрути; такі зазвичай мають молоді виверни чи плідні самиці.",al={"чи однакові мішечки виверн","якість отрути виверн"}},{q="Чим ставлення Орди до цих виверн відрізняється від Альянсу?",a="Орда переважно ловить і розводить виверн як верхових тварин і розвідників — вітрокрилів. Незалежні торговці й знайомі з Альянсу, що не мають своїх приборкувачів, натомість добувають зі звірів смертоносні хімічні реагенти.",al={"орда та виверни","чи орки використовують отруту"}}},fp="19,260,16.431.0,15.417.0,38.172.0,53.257.0,36.167.0,66.246.0"}
P.entries["item:highperch-wyvern-egg"] = {n="Яйце Віверни Хайперча",s="Яйця віверн Високосіду — кладки, зібрані в гніздовищах на високих столових горах Тисячі Голок. Їх шукають в Орді ті, хто прагне вирощувати й вишколювати нових крилатих їздових звірів — вітрокрилів.",h="Яйця віверн Високосіду — кладки, зібрані в гніздовищах на високих столових горах Тисячі Голок.",kw={"яйце віверни","високосід","віверни","вітрокрили","застава вільного вітру","елу"},ang={["class:Hunter"]="Щоб пробратися небезпечними висотами Високосіду, треба розуміти поведінку лютих хижаків: дорослі віверни боронять гнізда гострими як бритва кігтями й отруйними жалами.",["faction:Horde"]="Надійне повітряне сполучення життєво важливе для зв'язку й бойової готовності на неосяжних просторах Калімдору, тож роздобути свіжий молодняк віверн — справа стратегічної ваги."},sec={{t="Гнізда на столовій горі",b="Високе плато Високосід у Тисячі Голок — природний прихисток, де місцеві віверни гніздяться й виводять малят. Дістатися туди можна лише крутими звивистими стежками по стінах каньйону, а гніздовища люто стережуть дорослі звірі. Яйця, відкладені в цих гніздах, міцні й теплі; у них розвиваються малята, здатні призвичаїтися до суворого неба Калімдору."},{t="Нові вітрокрили",b="По всьому Калімдору попит на вишколених віверн щоразу випереджає пропозицію, адже Орда розширює мережі гінців і розвідників. На Заставі Вільного Вітру учні, як-от таурен Елу, шукають цілі яйця просто в диких гніздах. Вирощуючи малят від самої шкаралупи, доглядачі сподіваються викувати глибокий зв'язок, без якого не вишколити надійних крилатих скакунів для вершників Орди."}},faq={{q="Де знайти ці яйця?",a="Вони розкидані по гніздах на Високосіді — піднесеному плато біля південних скельних стін Тисячі Голок, куди веде стежка з дна каньйону.",al={"місця яєць","де знайти яйця виверн","місце яєць хайперча"}},{q="Навіщо Орда збирає яйця диких виверн?",a="Лави вітрокрилів Орди ростуть, і приборкувачі ледве встигають вишколити досить дорослих виверн. Учні, як-от Елу, збирають яйця, щоб вирощувати пташенят від народження, готуючи і звіра, і вершника до служби в повітрі.",al={"чому орда краде яйця виверн","для чого яйця","мета завдання з яйцем"}},{q="Чи нападають батьки-виверни на збирачів яєць?",a="Так. Дикі виверни люто боронять свої гнізда й нападають на кожного, хто вдереться на Високосід, щоб зазіхнути на їхні кладки.",al={"чи виверни нападають","чи виверни захищають яйця"}},{q="Хто приймає ці яйця на Заставі Вільного Вітру?",a="Елу, майбутній вершник вітрокрила, що мешкає нагорі Застави Вільного Вітру, збирає яйця, сподіваючись почати власний вишкіл верхового звіра.",al={"хто бере яйця виверн","застава вільного вітру"}}},fp="20,202,17.386.0,23.383.0,27.184.0,44.227.0,48.156.0,40.128.0"}
P.entries["item:hildelve-s-journal"] = {n="Щоденник Гільдельве",s="Щоденник Гільдельве — останній запис дворфійського пілота Гільдельве, знайдений біля його останків у крижаній пустці Дун Мороґу. Його закривавлені сторінки оповідають про фатальну зустріч із лютим ведмедем і передають передсмертне бажання помсти.",h="Щоденник Гільдельве — останній запис дворфійського пілота Гільдельве, знайдений біля його останків у крижаній...",kw={"щоденник гільдельве","гільдельве","дробкіготь","пілот гаммерфут","облогова бригада","ведмідь","помста","дун мороґ"},ang={["faction:Alliance"]="Повернення особистих речей полеглих вояків, як-от Гільдельве, зміцнює зв'язок між Альянсом та Облоговою Бригадою Айронфорджа.",["race:Dwarf"]="Щоденник ушановує незламний дух дворфійських пілотів, які кидають виклик морозу й диким звірам, щоб утримати висоти Каз Модану."},sec={{t="Останні слова пілота",b="Коли паровий танк зламався, дворфійський пілот Гільдельве лишив свого напарника Гаммерфута з машинами й сам вирушив у засніжені скелі Дун Мороґу на пошуки чуток про хіронову руду. Як свідчать записи в його щоденнику, його кілька днів вистежував, а потім підстеріг велетенський крижанокігтий ведмідь на ім'я Дробкіготь. Хоча Гільдельве бився хоробро й зумів відігнати звіра, він лишився тяжко пошматованим і безпорадним на лютому морозі. Щоденник описує його болісні останні години й завершується єдиним ясним проханням, перш ніж хижак повернувся його добити: хай той, хто знайде його тіло, помститься за його смерть, вистеживши Дробкігтя."},{t="Повернення до Облогової Бригади",b="Знайдений щоденник — гірке завершення історії для товариша Гільдельве, Пілота Гаммерфута, що стоїть біля Застави Північної Брами на сході Дун Мороґу. Як член Облогової Бригади Айронфорджа, Гаммерфут боявся найгіршого, коли Гільдельве не повернувся з пошуків руди. Передати йому щоденник разом із відрубаною лапою звіра — доказ того, що дух Гільдельве упокоївся, а його останню волю виконано."}},faq={{q="Хто такий Гільдельве?",a="Гільдельве — дворф, пілот парового танка з Облогової Бригади Айронфорджа. Коли його танк зламався, він сам вирушив у нетрі Дун Мороґа шукати хіронову руду й загинув від ведмедя Дробкігтя, так і не повернувшись.",al={"хто такий гільдельве","історія гільдельве","дворф-пілот гільдельве"}},{q="Хто такий Дробкіготь?",a="Дробкіготь — надзвичайно великий і лютий крижанокігтий ведмідь, що никає засніженими хребтами Дун Мороґа. Він напав на Гільдельве, коли той застряг, тяжко його покалічив, а згодом повернувся й добив.",al={"хто такий дробкіготь","хто вбив гільдельве","ведмідь що вбив гільдельве"}},{q="Хто отримує щоденник, коли його знайдено?",a="Щоденник доставляють Пілотові Гаммерфуту — пілотові облогових машин біля Застави Північної Брами на сході Дун Мороґа. Гаммерфут був близьким другом Гільдельве й шукав звістки про зниклого пілота.",al={"куди нести щоденник","хто отримує щоденник гільдельве","здати щоденник гільдельве"}},{q="Про що Гільдельве просить у щоденнику?",a="Знаючи, що рани смертельні, Гільдельве на останніх сторінках описав звіра, що напав на нього, і попросив мандрівника, який знайде його останки, вистежити Дробкігтя й помститися за його смерть.",al={"останнє бажання гільдельве","що в щоденнику","передсмертне бажання пілота"}}},fp="18,246,21.661.0,27.416.1,17.239.0,18.201.0,42.203.0,42.190.0"}
P.entries["item:hillsbrad-human-skull"] = {n="Людський Череп із Гілсбреда",s="Моторошний воєнний трофей, здобутий із полеглих людських захисників і городян по всьому Передгір'ю Гілсбреда. Ці черепи збирають Відступники з Таррен Мілла як похмурі пам'ятки нещадного наступу на місцеві людські поселення.",h="Моторошний воєнний трофей, здобутий із полеглих людських захисників і городян по всьому Передгір'ю Гілсбреда.",kw={"людський череп","гілсбред","таррен мілл","саутшор","відступники","самса"},ang={["faction:Alliance"]="Видовище того, як фермери й солдати Гілсбреда стають зібраними дрібничками, показує похмуру жорстокість походу Відступників у Лордероні.",["race:Undead"]="Для Відступників здобуття людських черепів у Гілсбреді — і солодка помста, і моторошне нагадування про живих братів, які їх цураються."},sec={{t="Трофеї запеклої війни",b="Поки вирує війна між Відступниками Таррен Мілла й людьми Саутшора та довколишніх поселень, відтяті черепи слугують наочним доказом різанини. Скрадачі смерті й солдати виконують методичну чистку, наказану Дарталією в Битві за Гілсбред, а інші вартові, прикуті до своїх постів, прагнуть і собі шматочка кривавої справи. Вартовий Смерті Самса охоче випрошує ці трофеї в бійців із передової, знаходячи збочену втіху в тому, щоб збирати рештки тих самих людей, серед яких Відступники колись жили за життя."}},faq={{q="Кому потрібні ці людські черепи?",a="Їх збирає Вартовий Смерті Самса — вартовий-Відступник у Таррен Міллі. Він заздрить воякам, яких посилають битися й грабувати Гілсбред, поки сам прикутий до варти, тож просить мандрівних шукачів пригод принести йому тридцять черепів до приватної колекції.",al={"хто хоче черепи","хто бере людські черепи","черепи охоронця самси"}},{q="Де збирають Людські Черепи з Гілсбреда?",a="Їх забирають у людей — бійців і робітників — по всьому Передгір'ю Гілсбреда, особливо довкола людських хуторів, копалень і міських укріплень, на які нападали під час походу на Гілсбред.",al={"де падають черепи","фарм людських черепів","хто дропає людські черепи"}},{q="Навіщо Відступники збирають людські рештки?",a="Окрім звичайної ненависті й чорного гумору, збирати трофеї з мертвих людей — поширена розвага серед Відступників. Вояки на кшталт Самси вважають черепи цінними дивовижами й утішним доказом близького падіння Гілсбреда.",al={"навіщо відступники збирають черепи","колекція черепів відступників"}}},fp="21,248,24.539.0,29.271.0,42.208.0,42.218.0"}
P.entries["item:hillsbrad-town-registry"] = {n="Міський Реєстр Гілсбреда",s="Міський Реєстр Гілсбреда — офіційна міська книга обліку, що зберігається в ратуші на Полях Гілсбреду. У ній записано вцілілих мешканців, землевласників і громадські справи поселення, тож під час наступу Відступників на людську твердиню вона стала важливою стратегічною ціллю.",h="Міський Реєстр Гілсбреда — офіційна міська книга обліку, що зберігається в ратуші на Полях Гілсбреду.",kw={"міський реєстр гілсбреда","реєстр","поля гілсбреду","магістрат бернсайд","таррен мілл","дарталія"},ang={["faction:Horde"]="Захоплення міського реєстру — вирішальний крок до того, щоб зламати людську владу в передгір'ї й закріпити твердиню Відступників у Таррен Міллі.",["race:Human"]="Книга засвідчує саме існування й права вцілілих мешканців Гілсбреда, тож її втрата — нищівний удар для місцевої громади."},sec={{t="Літопис непокори",b="Міський Реєстр Гілсбреда, що лежить у ратуші біля кафедри Магістрата Бернсайда, фіксує населення, домогосподарства й адміністративні права Гілсбреда. Поки Відступники з Таррен Мілла намагаються зламати людський опір у передгір'ї, Дарталія наказує поборникам Орди проникнути до ратуші, знищити раду й захопити цю книгу. Конфіскація реєстру позбавляє Гілсбред громадського ладу й дає Андерсіті цінні відомості про вцілілих мешканців та їхнє майно."}},faq={{q="Де зберігається Міський Реєстр Гілсбреда?",a="Реєстр лежить у ратуші на Полях Гілсбреду — в кутку біля сходів, що ведуть на поміст Магістрата Бернсайда.",al={"місце реєстру","де міський реєстр","знайти реєстр гілсбреда"}},{q="Чому Відступники хочуть його викрасти?",a="Верховний Екзекутор Дарталія прагне вщент зруйнувати людське врядування в передгір'ях. Викрадений реєстр позбавляє громаду важливих записів про мешканців і майно, а Відступникам дає докладні відомості про вцілілу громаду.",al={"чому красти реєстр","завдання реєстру дарталії","призначення реєстру"}},{q="Хто стереже реєстр?",a="Його стережуть Магістрат Бернсайд і радники Гілсбреда, що володіють захисною магією й гуртуються в ратуші та довкола неї.",al={"хто охороняє реєстр","захисники ратуші"}}},fp="23,301,20.524.0,42.150.0,37.261.0,24.135.0"}
P.entries["item:hollow-vulture-bone"] = {n="Порожниста Кістка Грифа",s="Порожнисті кістки грифів — легкі й міцні рештки скелетів падальників із Мерехтливих Низин. На Перегонах Міражу гоблінські механіки цінують їх як особливий будівельний матеріал, що полегшує ракетні автомобілі, не жертвуючи міцністю конструкції.",h="Порожнисті кістки грифів — легкі й міцні рештки скелетів падальників із Мерехтливих Низин.",kw={"порожниста кістка грифа","грифи","поззік","перегони міражу","мерехтливі низини","ракетні автомобілі"},ang={["class:Hunter"]="Грифи Мерехтливих Низин — витривалі падальники, тож вистежувати їх на сліпучому соляному дні — природна справа мисливця.",["profession:Engineering"]="Звичайні креслення покладаються на важке залізо й бронзу, а порожнисті пташині кістки показують той завзятий прагматизм, охочий зрізати кожну зайву унцію, на якому тримаються гоблінські гоночні винаходи."},sec={{t="Гоночні матеріали з солончаків",b="На солончаках швидкість — це все, а вага — її ворог. Звичайна інженерія тримається заліза й міді, але гоблінські механіки на Перегонах Міражу хапаються за все, що дає пустеля, аби здобути перевагу. Кістки грифів від природи порожнисті, проте напрочуд міцні — ідеальне співвідношення міцності й ваги для внутрішніх кронштейнів, кермових тяг і дрібних опор. Для головних майстрів на кшталт Поззіка збирати кістки місцевих падальників — практичний і дешевий спосіб відвоювати кілька секунд на трасі."}},faq={{q="Навіщо гоблінам кістки грифів?",a="Гоблінські інженери, як-от Поззік, використовують порожнисті кістки грифів, щоб полегшити свої ракетні машини. Пташині кістки від природи легкі й напрочуд міцні, тож ідеально підходять для кермових тяг і дрібних частин каркаса.",al={"навіщо кістки","навіщо гоблінам кістки","кістки поззіка"}},{q="Звідки ці кістки?",a="Їх добувають із солончакових падальників і солончакових грифів, що кружляють над Мерехтливими Низинами в Тисячі Голок, особливо довкола велетенських скелетів, розкиданих соляною пустелею.",al={"де знайти порожнисту кістку грифа","місце кістки грифа","як отримати кістки грифів"}},{q="Хто такий Поззік?",a="Поззік — гоблін-інженер і головний механік на Перегонах Міражу. Він невпинно налаштовує й переробляє ракетні машини, щоб змагатися з командою гномів, яку очолює Фіззл Брассболтс.",al={"хто такий поззік","гоночна траса поззіка","хто бере кістки"}}},fp="19,273,29.540.0,38.236.0,31.201.0,14.186.0"}
P.entries["item:honorary-picks"] = {n="Почесні Кайла",s="Почесні Кайла — в'язка обрядових інструментів, викуваних в Айронфорджі для молодих учнів-рудокопів із дворфів. Їх доручають мандрівникам, і ті грифонячими шляхами доставляють кайла Брокові Стоунсікеру в Телсамарі — на знак того, що його учні готові розробляти багаті рудні жили Лох Модану.",h="Почесні Кайла — в'язка обрядових інструментів, викуваних в Айронфорджі для молодих учнів-рудокопів із дворфів.",kw={"почесні кайла","брок стоунсікер","телсамар","лох модан","грифони","гірництво","айронфордж"},ang={["profession:Mining"]="Кожен рудокоп Каз Модану знає ціну доброму кайлу, а почесний інструмент знаменує справжній вступ новачка в ремесло.",["race:Dwarf"]="Для дворфа вручати учням у провінції інструменти, викувані в Айронфорджі, — шанована традиція родинності й ремесла."},sec={{t="Інструменти для нового покоління",b="У дворфійському суспільстві гірництво — щось набагато більше, ніж ремесло: це наріжний камінь культури, що підтримує вогонь у великих горнах і постачає королівство залізом і каменем. Почесні Кайла — офіційне визнання для молодих шукачів руди, що навчаються в Брока Стоунсікера в Телсамарі. Ці кайла, привезені просто з Айронфорджа, вручають учням, які довели свою відданість і готові братися за відкриті рудні поклади по всьому Лох Модану."},{t="Випробування грифонячих шляхів",b="Перевезення кайл має й іншу мету для горян і купців Альянсу: познайомити гінців із грифонячою мережею королівства. Вантаж везуть від Великої Кузні Айронфорджа просто до Ґріта Турдена, а звідти перелітають через гори до Торґрума Боррелсона в Телсамарі — і це показує, як тісно столиця пов'язана з віддаленими заставами завдяки швидкому повітряному сполученню."}},faq={{q="Для чого потрібні Почесні Кайла?",a="Почесні Кайла виготовляють для учнів гірничої справи Брока Стоунсікера в Лох Модані. Це церемоніальні, але цілком робочі знаряддя для учнів, готових добувати руду по всьому краю.",al={"що таке почесні кайла","використання почесних кайл","призначення почесних кайл"}},{q="Хто надсилає кайла і хто їх отримує?",a="Кайла готують в Айронфорджі й приносять Ґріту Турдену на грифонове сідало міста. Звідти їх перевозять на схід до Телсамара й особисто вручають наставникові гірничої справи Брокові Стоунсікеру.",al={"хто отримує почесні кайла","доставка почесних кайл","одержувач почесних кайл"}},{q="Чому кайла треба доставити грифоном?",a="Їх можна було б донести пішки через Перевал Північної Брами, але переліт у майстра грифонів Ґріта Турдена забезпечує швидку доставку й навчає мандрівників користуватися усталеними повітряними шляхами Альянсу між Айронфорджем і Лох Моданом.",al={"чому летіти з кайлами","чому грифоном","політ почесних кайл"}},{q="Чи Почесні Кайла — справжня зброя чи інструмент, який можна вдягнути?",a="Ні. Кур'єр несе їх лише як вантаж: вони призначені учням Брока Стоунсікера, які прагнуть випробувати їх на рудних покладах Лох Модану.",al={"чи можна одягти почесні кайла","чи предмет почесні кайла","чи придатні почесні кайла"}}},fp="14,291,29.450.0,25.403.0,37.200.0,43.197.0,49.244.0,61.167.0"}
P.entries["item:horn-of-arra-chea"] = {n="Ріг Арра'чеа",s="Ріг Арра'чеа — мисливський трофей, здобутий у легендарного кодо Арра'чеа, що блукає рівнинами Малгору. Здобутий на прохання Верховного Вождя Кайрна Бладгуфа, ріг є остаточним доказом того, що молодий мисливець має досить витримки й уміння вистежувати, щоб годувати шу'гало.",h="Ріг Арра'чеа — мисливський трофей, здобутий у легендарного кодо Арра'чеа, що блукає рівнинами Малгору.",kw={"ріг арра'чеа","арра'чеа","кодо","кайрн бладгуф","малгор","мисливець","тандер блаф"},ang={["class:Hunter"]="Вистежити Арра'чеа, що ходить колом широкими просторами Малгору, — перевірка основних навичок скрадання й виживання в дикій природі, які цінує кожен справжній мисливець.",["race:Tauren"]="Вручення цього рогу Верховному Вождеві Кайрну — важливий обряд посвяти, що підтверджує вашу готовність годувати й захищати свій народ на Тандер Блафі."},sec={{t="Випробування Вождя",b="Хоч складання перших Обрядів Земної Матері й дає юнакові належне місце на Тандер Блафі, Верховний Вождь Кайрн Бладгуф чекає, що його народ постійно доводитиме свою вартість. Для тауренів самобутність нерозривно пов'язана з полюванням і вічною гармонією із землею. Кайрн випробовує молодих мисливців, доручаючи їм вистежити Арра'чеа — величезного кодо-самітника, що блукає луками внизу. Здобути ріг Арра'чеа означає опанувати основу основ — мистецтво вистежувати здобич на великих відстанях."},{t="Годувальник племені",b="Принести ріг на високе узвишшя Тандер Блафа — не просто показ бойової сили: від цього залежить виживання всієї громади. У культурі тауренів жодна частина вбитого звіра не повинна пропасти. Показавши трофей, мисливець повідомляє Верховному Вождеві, де лежить звір, і загони збирачів швидко спускаються на рівнини, щоб забрати товсту шкуру й ситне м'ясо Арра'чеа для молодої столиці."}},faq={{q="Що таке Ріг Арра'чеа?",a="Це ріг, знятий з Арра'чеа — могутнього й невловимого кодо, що блукає рівнинами Малгору. Мисливці приносять його Кайрнові Бладгуфу як обряд посвяти, щоб довести своє вміння вистежувати.",al={"ріг арра'чеа","ріг арраче","що це за ріг"}},{q="Хто такий Арра'чеа?",a="Арра'чеа — славетний бик-кодо, що кружляє степами на північний схід від Тандер Блафа. Відомий своєю силою й широким шляхом кочування, він — грізна здобич для мисливців, які хочуть довести племені, чого вони варті.",al={"арра'чеа","хто такий арра'чеа","історія арра'чеа"}},{q="Чому Кайрн Бладгуф просить цей трофей?",a="Кайрн вважає, що повагу в Тандер Блафі треба раз у раз підтверджувати службою й умінням. Вистеживши й поваливши Арра'чеа, мисливець доводить відданість традиціям Земної Матері й дає громаді цінні припаси.",al={"чому кайрн хоче ріг","кайрн арра'чеа","ріг обряди землематері"}},{q="Що стається з рештою звіра після смерті?",a="За звичаєм тауренів, жодна частина вполюваної тварини не пропадає. Щойно ріг підтверджує здобич, Кайрн посилає в Малгор загін, щоб забрати шкуру й м'ясо для Тандер Блафа.",al={"м'ясо арра'чеа","традиція полювання тауренів","туша арра'чеа"}}},fp="17,304,18.522.0,23.435.0,30.192.0,17.226.0,46.273.0,57.227.0"}
P.entries["item:horn-of-awakening"] = {n="Ріг Пробудження",s="Ріг Пробудження — сурма, яку Керлоніан Евершейд тримає в скрині на півдні Темного Узбережжя. Нею будять сонного друїда щоразу, коли він засинає дорогою до Ашенвалю.",h="Ріг Пробудження — сурма, яку Керлоніан Евершейд тримає в скрині на півдні Темного Узбережжя.",kw={"ріг пробудження","керлоніан евершейд","друїд пазура","смарагдовий сон","пост маестри","темне узбережжя"},ang={["class:Druid"]="Друїди Пазура поколіннями спали в Курганних Притулках, спілкуючись зі Смарагдовим Сном, і повернення до світу наяву часто лишає їх приголомшеними й розгубленими.",["race:NightElf"]="Роги пробудження й традиційні сурми здавна були для нічних ельфів важливими знаряддями: ними будили сплячих вартових у часи раптових навал."},sec={{t="Ліки для сонних друїдів",b="Керлоніан Евершейд, Друїд Пазура, який нещодавно прокинувся після століть у Смарагдовому Сні, ніяк не може струсити з себе млявість у світі наяву. Вирушаючи на південь до Посту Маестри, він довіряє цей ріг мандрівникам, що погодяться його супроводжувати. Щоразу, коли на небезпечній лісовій стежці його зморює втома, дзвінкий звук рогу струшує його й піднімає на ноги, перш ніж дикі звірі чи культисти скористаються його сном."}},faq={{q="Де знайти Ріг Пробудження?",a="Ріг лежить у Скрині Керлоніана біля стоянки Керлоніана Евершейда на півдні Темного Узбережжя, біля кордону з Ашенвалем.",al={"місце рогу","де ріг пробудження","скриня керлоніана"}},{q="Чому Керлоніанові потрібен ріг, щоб не заснути?",a="Керлоніан довгі віки проспав у Смарагдовому Сні й тепер ледве звикає до смертного неспання: дорогою він раз у раз раптово поринає в глибоку дрімоту.",al={"чому керлоніан спить","чому він засинає","смарагдовий сон"}},{q="Куди намагається дістатися Керлоніан?",a="Він прямує до Посту Маестри на півночі Ашенвалю, щоб зустрітися з Ліладріс Мунрівер.",al={"куди йде керлоніан","куди він іде","ескорт поста маестри"}}},fp="17,208,26.465.0,37.130.0,47.173.0,32.101.0"}
P.entries["item:horn-of-echeyakee"] = {n="Ріг Ечеякі",s="Ріг Ечеякі — мисливський інструмент, який дає Серґра Даркторн на Перехресті. Якщо засурмити в нього серед прадавніх решток кодо на північний схід від поселення, з'явиться Біла Імла — легендарний білий хижак Пусток.",h="Ріг Ечеякі — мисливський інструмент, який дає Серґра Даркторн на Перехресті.",kw={"ріг ечеякі","ечеякі","біла імла","серґра даркторн","полювання","перехрестя"},ang={["class:Hunter"]="Для мисливців виклик Ечеякі — легендарний обряд посвяти, що протиставляє їхнє чуття хижакові, відомому по всіх Пустках майже бездоганною потайністю.",["race:Tauren"]="Полювання на Ечеякі має для тауренів духовну вагу: швидке, безболісне вбивство звіра вони бачать як утілення і милосердя, і суворої неминучості смерті."},sec={{t="Поклик Білої Імли",b="Ріг дають послушникам, що випробовують свою мисливську вправність, і його поклик лунає над саваною, викликаючи Ечеякі, чиє ім'я мовою таур-ае означає «Біла Імла». Відомого як король кішок савани, Ечеякі шанують тауренські мисливці і як милосердя, і як смерть: він б'є так швидко, що здобич не встигає відчути ні жаху, ні страждання. У ріг слід сурмити лише біля лігва великого хижака — вибіленого сонцем гнізда з велетенських кісток кодо, захованого за пагорбами на північний схід від Перехрестя."}},faq={{q="Що робить Ріг Ечеякі?",a="Ріг виманює Ечеякі — невловимого білого кота савани. Якщо засурмити в ріг біля велетенських кісток кодо на північний схід від Перехрестя, звір з'являється, і мисливець може з ним зійтися.",al={"використання рогу ечеякі","для чого ріг ечеякі"}},{q="Звідки береться ріг?",a="Серґра Даркторн, орчиха-мисливиця з Перехрестя в Пустках, довіряє ріг шукачам пригод, які хочуть довести свою скритність і вміння вистежувати.",al={"хто дає ріг","джерело рогу ечеякі"}},{q="Що означає ім'я Ечеякі?",a="Тауренською мовою, таур-ахе, «Ечеякі» означає «Білий Туман». Ім'я вшановує бліде хутро звіра й те, як він безшумно, мов туман, скрадається сухою травою, не видаючи себе.",al={"значення ечеякі","значення білої імли"}},{q="Де засурмити в ріг?",a="У ріг треба засурмити серед велетенських ребер і кістяків кодо за пагорбами на північний схід від Перехрестя, де полює білий лев.",al={"де засурмити","місце ечеякі"}}},fp="17,232,21.505.0,35.202.0,30.161.0,34.191.0,27.170.0"}
P.entries["item:huge-gnoll-claw"] = {n="Велетенський Кіготь Ґнола",s="Велетенський Кіготь Ґнола — безпомилковий трофей, здобутий у Гоґґера, велетенського гнола, що нишпорить південно-західним Лісом Елвінн. Значно більший за будь-який звичайний гнолячий пазур, він слугує офіційним доказом загибелі, якого вимагає влада Стормвінда в Ґолдширі.",h="Велетенський Кіготь Ґнола — безпомилковий трофей, здобутий у Гоґґера, велетенського гнола, що нишпорить...",kw={"велетенський кіготь","гоґґер","гнол","винагорода","маршал дуґан","ґолдшир"},ang={["class:Hunter"]="Здобути кіготь такого велетенського хижака — означає показати найвищу майстерність вистежування й полювання на звіра, що раз у раз долав озброєні загони.",["faction:Alliance"]="Здобутий кіготь звільняє серце королівства від його найсумнозвіснішого лісового жаху й доводить вашу доблесть Маршалові Дуґану та змученому гарнізону Ґолдширу."},sec={{t="Доказ мисливця за головами",b="Місяцями здоровань Гоґґер тероризував південні ліси Узлісся, відбиваючись від патрулів і зриваючи кожну спробу тутешнього гарнізону загнати чи приборкати його. Поступаючись силою й розтягнуте по всьому Елвінну, військо Стормвінда оголосило відкриту винагороду за голову тварюки. Маршал Дуґан у Ґолдширі вимагає незаперечного доказу, перш ніж видати винагороду, і величезний кіготь здорованя дає безсумнівне підтвердження, що жах лісів нарешті впав."}},faq={{q="Для чого потрібен Велетенський Кіготь Ґнола?",a="Кіготь — офіційний доказ смерті Гоґґера. Його приносять просто Маршалові Дуґану в Ґолдшир, щоб отримати обіцяну винагороду.",al={"що робити з кігтем хоггера","використання кігтя ґнола","хто хоче кіготь"}},{q="Звідки цей кіготь?",a="Його забирають просто в Гоґґера — добірного гнола, що блукає біля таборів Річколапів на південно-західному краю Узлісся в Лісі Елвінн.",al={"хто дропає кіготь","як отримати кіготь ґнола","де знайти кіготь ґнола"}},{q="Чому Маршал Дуґан хоче кіготь, а не голову?",a="Гоґґер незвично великий навіть для ватажка Річколапів, а його величезні кігті впізнавані з першого погляду. Такий кіготь не лишає війську Стормвінда жодного сумніву, що сумнозвісного розбійника справді вбито.",al={"чому кіготь доказ смерті","чому не голова хоггера","доказ нагороди дуґана"}},{q="Чи можна отримати інший кіготь, якщо цей загубиться?",a="Так. Якщо ви загубите кіготь, перш ніж віддасте його Маршалові Дуґану, можна знову вистежити Гоґґера на південному заході Лісу Елвінн і здобути новий.",al={"загублений кіготь ґнола","чи можна отримати кіготь знову","респавн кігтя хоггера"}}},fp="15,254,21.493.0,37.161.0,31.148.0,56.224.0,36.152.0"}
P.entries["item:humbert-s-sword"] = {n="Меч Гумберта",s="Меч Гумберта — особиста зброя Вартового Смерті Гумберта з Таррен Мілла. Дворфійські солдати викрали його з табору, поки той розвідував їхню твердиню Дун Ґарок.",h="Меч Гумберта — особиста зброя Вартового Смерті Гумберта з Таррен Мілла.",kw={"меч гумберта","вартовий смерті гумберт","дун ґарок","дарталія","таррен мілл","дворфи"},ang={["faction:Horde"]="Повернення меча збігається з ширшими діями Орди проти дворфійського осередку в Дун Ґароку, зокрема зі збиранням дворфійської крові й військових відзнак.",["race:Undead"]="Верховний Екзекутор Дарталія тримає війська Відступників у Гілсбреді в безжальній дисципліні, тож недбалі вартові на кшталт Гумберта відчайдушно намагаються приховати свої помилки."},sec={{t="Необачна мить розвідника",b="Верховний Екзекутор Дарталія відрядила Вартового Смерті Гумберта стежити з прихованої позиції за дворфами в Дун Ґароку. Одного ранку, поки він покинув свій пост без нагляду, щоб назбирати хмизу й закип'ятити воду, дворфійські патрулі натрапили на його табір і розграбували все спорядження, зокрема й особистий клинок. Дворфів, яких треба обшукати, так багато, що Гумберт покладається на агентів Орди: хай проникнуть до фортеці й повернуть утрачену зброю."},{t="Дворфійська скарбниця",b="Після крадіжки речі Гумберта віднесли за укріплені барикади Дун Ґарока. Оскільки дворфійські стрільці, горяни й жерці перерозподіляють припаси по всьому гарнізону, щоб знайти саме того злодія, доведеться обшукувати захисників, що стоять у шанцях і редутах твердині."}},faq={{q="Кому належить цей меч?",a="Клинок належить Вартовому Смерті Гумберту — вартовому-Відступникові з Таррен Мілла, якому доручили розвідати Дун Ґарок.",al={"чий це меч","власник гумберта","хто такий гумберт"}},{q="Як меч Гумберта потрапив до дворфів?",a="Вартовий Смерті Гумберт уранці покинув свій розвідницький табір біля Дун Ґарока, щоб назбирати дров. Поки його не було, дворфський патруль обнишпорив табір і забрав його спорядження.",al={"як дворфи отримали меч","чому дворфи мають меч","як вкрали меч"}},{q="Чому Гумберт так відчайдушно хоче повернути меч?",a="Без зброї Гумберт не може пильнувати Дун Ґарок, як наказала йому Верховний Екзекутор Дарталія, а дворфів у гарнізоні так багато, що самому злодія не знайти.",al={"чому гумберт хоче меч","що буде, якщо гумберт втратить меч","чому гумберт турбується"}},{q="Де знайти меч?",a="Меч у дворфів, що стоять гарнізоном у Дун Ґароку на південному сході Передгір'я Гілсбреда. Його можна відібрати в горян, стрільців чи жерців, розставлених по всій заставі.",al={"звідки падає меч","місце меча","як знайти меч гумберта"}}},fp="15,196,25.439.0,17.325.0,20.120.0,40.182.0,50.175.0,29.205.0"}
P.entries["item:hyacinth-mushroom"] = {n="Гіацинтовий Гриб",s="Гіацинтові Гриби — своєрідні гриби, що проростають біля коріння дерев по всьому Тінедолу на Тельдрассилі. Тутешні травники — нічні ельфи цінують їх за лікувальні властивості, а ще вони — улюблена пожива й здобич бешкетливих ґреллів і ґреллят.",h="Гіацинтові Гриби — своєрідні гриби, що проростають біля коріння дерев по всьому Тінедолу на Тельдрассилі.",kw={"гіацинтовий гриб","гриби","тінедол","ґрелли","протиотрута","травництво","алдрассил"},ang={["profession:Herbalism"]="Хоч збирання цих грибів у Тінедолі не вимагає формального навчання, будь-який травник-початківець оцінить їхню роль у знешкодженні лютих лісових отрут.",["race:NightElf"]="Для молодих нічних ельфів, що навчаються в Тінедолі, збирання дикої рослинності на кшталт Гіацинтових Грибів — ранній урок користування дарами природи задля підтримки своїх родичів."},sec={{t="Рослинність Тінедолу",b="Гіацинтові Гриби рясно ростуть по всьому Тінедолу, буяючи у вологій тіні біля підніжжя прадавніх курганів, замшілого каміння й розлогого коріння Алдрассила. Корисні в лісових ліках, вони привернули й увагу споганених ґреллів, що часто їх збирають про запас. Коли молодих вартових чи учнів — нічних ельфів уражає тутешня отруйна фауна, як-от павуки Печери Тіньової Нитки, ці гриби стають основним складником заспокійливих напоїв і протиотрут, що їх готують лісові цілителі."}},faq={{q="Для чого потрібні Гіацинтові Гриби?",a="Жриця Діранія Сілвершайн використовує їх як важливий складник протиотрути для Іверрона — юного нічного ельфа, якого покусали й отруїли отруйні павуки, коли він досліджував Печеру Тіньової Нитки.",al={"використання гіацинтового гриба","що він робить","ліки іверрона"}},{q="Де ростуть Гіацинтові Гриби?",a="Вони проростають просто на землі біля стовбурів і коріння великих дерев, а також біля валунів по всій відлюдній долині Тінедол на Тельдрассилі.",al={"місце грибів","де знайти гіацинтовий гриб","гриби тіньового гаю"}},{q="Чому грелли носять Гіацинтові Гриби?",a="Пустотливі грелли й греллята, що заполонили південь Тінедолу, чомусь уподобали ці гриби: вони збирають їх і тягнуть до своїх таборів.",al={"дроп грибів з грелів","чому грелли їх мають","гриби гредкінів"}},{q="Чи отруйні самі Гіацинтові Гриби?",a="Ні. Хоч вони яскраві й ростуть у тінистих місцях, місцеві цілителі безпечно додають їх до цілющих припарок і протиотрут.",al={"чи отруйний гіацинтовий гриб","отруйний гриб"}}},fp="17,271,19.525.0,37.198.0,33.161.0,42.154.0,44.184.0"}
P.entries["item:hypercapacitor-gizmo"] = {n="Гіперконденсаторна Штукенція",s="Гіперконденсаторна Штукенція — химерний інженерний пристрій, знайдений на дні каньйону в Тисячі Голок. Колись він теліпався на шиї звіра, замкненого в клітці посеред розграбованого каравану, і його справжнє призначення лишається загадкою навіть для майстра, що називає себе його власником.",h="Гіперконденсаторна Штукенція — химерний інженерний пристрій, знайдений на дні каньйону в Тисячі Голок.",kw={"гіперконденсаторна штукенція","візло берінґшайнер","застава білого рубежу","кентаври","караван","пантера"},ang={["faction:Horde"]="Мандрівники, що допомагають Заставі Білого Рубежу, проганяють агресивних кентаврів і повертають загублені дивовижі з розграбованих караванів на дні каньйону.",["profession:Engineering"]="Штукенція — класичний зразок гоблінської інженерії: хитромудрий пристрій із загрозливою назвою, збудований із великим запалом, перш ніж хтось завдав собі клопоту вирішити, що він має робити."},sec={{t="Дивна реліквія з каравану",b="Коли кентаври-грабіжники напали на гоблінський караван, що йшов через Тисячу Голок, вони розграбували майже все, що бачили. Єдиний, хто вцілів, Візло Берінґшайнер, сяк-так доповз до безпечної Застави Білого Рубежу, лишивши позаду свій найцінніший винахід — Гіперконденсаторну Штукенцію. Дивним чином пристрій опинився закріпленим на шиї лютої, розлюченої пантери, замкненої в перевізній клітці. Кентаври так боялися звіра, що обійшли клітку стороною серед палаючих уламків — і самі того не знаючи, вберегли чудернацьку машину Візло."},{t="Майстрування навпомацки",b="Візло гордо вихваляє пристрій як найкраще своє творіння, але, отримавши його назад, зізнається, що й гадки не має, що він насправді робить. Як і чимало гоблінських вигадок, Гіперконденсаторна Штукенція — заплутаний клубок амбіцій і непередбачуваних деталей, приречений не служити якійсь зрозумілій практичній меті, а давати творцеві привід для нескінченного майстрування."}},faq={{q="Що таке Гіперконденсаторна Штукенція?",a="Це інженерний пристрій, який збудував гоблін Візло Берінґшайнер. Попри гучну назву, навіть Візло не знає, що він насправді робить, і збирається присвятити час його вивченню, щоб це з'ясувати.",al={"що таке штукенція","гіперконденсатор","що робить штукенція"}},{q="Як пристрій опинився на шиї пантери?",a="На караван Візла напали й пограбували кентаври на півночі Тисячі Голок. У метушні пристрій опинився пристебнутим до шиї розлюченої пантери, замкненої в дорожній клітці, — і забобонні кентаври не наважилися його взяти.",al={"чому пантера має штукенцію","як пантера її отримала"}},{q="Хто хоче повернути Гіперконденсаторну Штукенцію?",a="Її шукає Візло Берінґшайнер — єдиний, хто вцілів із пограбованого каравану. Він знайшов прихисток на Заставі Білого Рубежу, таборі тауренів на північному заході Тисячі Голок.",al={"кому потрібна штукенція","штукенція візла"}},{q="Чому кентаври її не вкрали?",a="Кентаври обнишпорили весь караван, але страшенно боялися лютої пантери в клітці. Звіра й металевий нашийник вони не зачепили серед руїн.",al={"чому кентаври не взяли","кентаври й пантера"}}},fp="20,258,25.559.0,21.363.0,33.220.0,50.250.0,40.173.0,32.179.0"}
P.entries["item:ignition-key"] = {n="Ключ Запалювання",s="Ключ запалювання — важливий ключ керування, який носить Наглядач Луґвізл на буровій ділянці Венчурної Компанії в Багнистому Болоті. Він потрібен, щоб відімкнути кермову колонку й запустити керування вдосконаленого подрібнювача Венчурної Компанії.",h="Ключ запалювання — важливий ключ керування, який носить Наглядач Луґвізл на буровій ділянці Венчурної...",kw={"ключ запалювання","наглядач луґвізл","візлкренк","подрібнювач","венчурна компанія","інженерна справа"},ang={["profession:Engineering"]="Ключ відмикає подрібнювач із напрочуд досконалими механізмами керування, що перевершують звичні гоблінські конструкції і в регулюванні швидкості, і в точних рухах маніпулятора."},sec={{t="Бракуюча частина шпигунської справи",b="Коли Спаттервалв із Раджета послав свого агента викрасти фірмовий подрібнювач Венчурної Компанії з Багнистого Болота, все пішло не так гладко. Таємний пілот, Візлкренк, зумів прослизнути в кабіну машини, але виявив, що кермова колонка намертво заблокована. Щоб підозріливі десятники нічого не помітили, він удавав механічну несправність, чекаючи, поки шукач пригод добуде потрібний Ключ Запалювання. Ключ надійно береже Наглядач Луґвізл високо на центральній нафтовій вишці, контролюючи доступ до найсучасніших механізмів маніпулятора, швидкості й обертання машини."}},faq={{q="Де знайти Ключ Запалювання?",a="Ключ тримає Наглядач Луґвізл, що керує бурінням із диспетчерської на самій верхівці нафтової вежі в Багнистому Болоті.",al={"місце ключа запалювання","хто дропає ключ запалювання","як отримати ключ запалювання"}},{q="Чому Візлкренку потрібен саме цей ключ?",a="На відміну від простіших інженерних машин, у цього вдосконаленого потрощувача Венчурної Компанії заблокована рульова колонка. Без потрібного ключа запалювання пілот не зможе керувати обертанням, швидкістю, стійкістю чи маніпуляторами, щоб на ньому втекти.",al={"чому візлкренку ключ","що робить ключ","призначення ключа потрощувача"}},{q="Хто хоче, щоб потрощувач викрали?",a="Цю операцію влаштував Спаттервалв — гоблін-інженер із Раджета, щоб заволодіти досконалішими інженерними кресленнями Венчурної Компанії.",al={"хто послав візлкренка","навіщо красти потрощувач","потрощувач рятчета"}},{q="Що стається, коли ключ доставлено?",a="Щойно ключ розблоковує рульову колонку, Візлкренк запускає двигун потрощувача й мусить відчайдушно прориватися крізь ворожих робітників Багнистого Болота, щоб утекти до Раджета.",al={"після здачі ключа","втеча","що далі"}}},fp="12,247,28.614.0,36.146.0,44.222.0,30.149.0,39.184.1"}
P.entries["item:ilkrud-magthrull-s-tome"] = {n="Фоліант Ількруда Маґтрулла",s="Фоліант Ількруда Маґтрулла — гримуар, відібраний у небезпечного орка-чорнокнижника, що засів у спотворених глибинах Ашенвалю. Коли його приносять Делґренові Очищувачу, мерзенний зміст книги викриває ширші темні оборудки культистів, що діють із Вежі Альталакса.",h="Фоліант Ількруда Маґтрулла — гримуар, відібраний у небезпечного орка-чорнокнижника, що засів у спотворених...",kw={"фоліант ількруда маґтрулла","ілкруд маґтрулл","делґрен очищувач","святилище вогняного шраму","вежа альталакса","чорнокнижник"},ang={["class:Paladin"]="Здобувши фоліант, ви допомагаєте братові Делґрену — побратимові-воїнові Святого Світла, що пильно стоїть на варті проти тіні й скверни в диких нетрях Ашенвалю.",["class:Warlock"]="Гримуар Маґтрулла — цінний запис темних скувань, що докладно описує, як підкоряти блукачів Порожнечі й сукубів у спотвореному Святилищі Вогняного Шраму."},sec={{t="Гримуар скверни",b="Ілкруд Маґтрулл — грізний орк-чорнокнижник, що окопався біля Святилища Вогняного Шраму на південному заході Ашенвалю, у місці, отруєному давнім демонічним впливом. Оточений викликаними посіпаками, Маґтрулл записував у цей особистий фоліант свої мерзенні обряди й таємні перемовини. Паладин Срібного Світанку Делґрен Очищувач давно знав про чорнокнижника, але викриті зв'язки між Маґтруллом і темними культистами, що збираються у Вежі Альталакса, зробили здобуття книги нагальною справою."},{t="Розплутати культ",b="Фоліант, вирваний із мертвої руки Маґтрулла, приносять Делґренові на Пост Маестри. Делґрен хоче розшифрувати записи чорнокнижника, щоб збагнути, яка мережа керує демонічною діяльністю на межі Темного Узбережжя й Ашенвалю. Текст дає цінні відомості про тіньових змовників, що смикають за ниточки порчі, яка вкорінюється на півночі Калімдору."}},faq={{q="Кому належить цей фоліант?",a="Книга належить Ілкруду Маґтруллу — могутньому орку-чорнокнижникові, що засів серед демонічних руїн Святилища Вогняного Шраму на південному заході Ашенвалю.",al={"хто такий ількруд маґтрулл","хто написав фоліант","ількруд маґтрулл"}},{q="Де знайти фоліант?",a="Його забирають у самого Ілкруда Маґтрулла в Святилищі Вогняного Шраму, на південь від Святилища Аессіни в Ашенвалі.",al={"місце фоліанта","як отримати фоліант","де знайти ількруда"}},{q="Навіщо Делґренові Очищувачу книга?",a="Делґрен хоче вивчити записи Маґтрулла, щоб розкрити темні зв'язки між місцевими поклонниками демонів і культистами з Вежі Альталакса.",al={"навіщо делґрену книга","що у фоліанті","призначення книги делґрена"}},{q="Що стається, коли фоліант повернуто?",a="Делґрен вивчає текст на Посту Маестри, щоб розшифрувати демонічні послання Маґтрулла й визначити наступний крок у руйнуванні мережі культу.",al={"здати фоліант","що делґрен робить з книгою"}}},fp="23,277,24.510.0,19.393.1,19.155.0,24.132.0,44.153.0,41.153.0"}
P.entries["item:incantations-from-the-nether"] = {n="Заклинання з Нижнього Світу",s="«Заклинання з Нижнього Світу» — гримуар демонічної магії, який зберігають культисти Пекучого Клинка, що ховаються під Оргріммаром. Сильвана Віндраннер і її поплічник-жахолорд Варіматрас хочуть заволодіти фоліантом, щоб обернути його знання про скверну на користь Відступників.",h="«Заклинання з Нижнього Світу» — гримуар демонічної магії, який зберігають культисти Пекучого Клинка, що...",kw={"заклинання з нижнього світу","пекучий клинок","провалля лютого вогню","варіматрас","сильвана віндраннер","гримуар","скверна"},ang={["class:Warlock"]="Фоліанти, винесені просто з Нижнього Світу, містять могутню магію скверни, якої жадав би кожен честолюбний знавець темних мистецтв.",["race:Undead"]="Здобувши цю книгу, ви прямо допомагаєте найближчому колу Темної Леді в Андерсіті зібрати темні знання, потрібні для війни з Погибеллю."},sec={{t="Дари Легіону",b="Під вулицями Оргріммара з червоного каменю, у вогняних тунелях Провалля Лютого Вогню, діє Пекучий Клинок — підземна секта, пов'язана з Радою Тіней. Серед її найтемніших скарбів — «Заклинання з Нижнього Світу», книга чарів, сповнена демонічних обрядів, дарованих посланцями Палаючого Легіону. Поки культисти черпають із її мерзенних таємниць, плетучи зраду в орківській столиці, звістка про книгу долетіла далеко за море, до королівських покоїв Андерсіті."},{t="Задуми Відступників",b="Для Леді Сильвани Віндраннер і жахолорда Варіматраса такі могутні реліквії скверни — марнотратство в руках культистів, яких вони вважають недалекоглядними. Варіматрас посилає вірних шукачів пригод з Орди глибоко в Провалля Лютого Вогню, щоб здобути «Заклинання» разом з їхньою книгою-посестрою — «Закляттями Тіні». Темна Леді має намір обернути викувані в Нижньому Світі сили книги на свій найголовніший похід — знищити Короля-Ліча й помститися Погибелі."}},faq={{q="Де знайти книгу «Заклинання з Нижнього Світу»?",a="Книгу носять культисти й чорнокнижники Пекучого Клинка, що ховаються в Проваллі Лютого Вогню — системі вулканічних печер просто під Оргріммаром.",al={"де взяти заклинання з нижнього світу","хто дропає заклинання з нижнього світу","місце заклинань з нижнього світу"}},{q="Кому потрібна ця книга й навіщо?",a="Книгу шукають жахолорд Варіматрас і Леді Сильвана Віндраннер. Вони вважають, що такі демонічні дари марно пропадають у дрібних культистів Пекучого Клинка, і хочуть обернути її темну магію проти свого заклятого ворога — Короля-Ліча.",al={"кому потрібна книга","чому сильванас хоче цю книгу","завдання варіматраса про книгу"}},{q="Що таке Пекучий Клинок?",a="Пекучий Клинок — таємне коло чорнокнижників і культистів, що діє під Оргріммаром у союзі з Радою Тіней. Вони служать Палаючому Легіону й з тіні підточують нову Орду Тралла.",al={"історія пекучого клинка","хто такий пекучий клинок"}},{q="Яка ще книга йде в парі з цією?",a="Варіматрасу потрібні два томи: «Заклинання з Нижнього Світу» та другий гримуар, «Закляття Тіні». Обидва треба відібрати в культистів у Проваллі Лютого Вогню, щоб виконати його доручення.",al={"інша книга для варіматраса","сила знищити книги"}}},fp="28,254,19.470.0,17.455.1,53.161.0,28.235.0,26.213.0,40.191.0"}
P.entries["item:incendia-agave"] = {n="Інцендія-Агава",s="Інцендія-Агава — рідкісна колюча водяна рослина, що росте в Киплячому Ставку під Шпилем Темної Хмари в Тисячі Голок. Коли її зачаровує вправний шаман, її незвичайні властивості дають змогу розпалити священний вогонь життя.",h="Інцендія-Агава — рідкісна колюча водяна рослина, що росте в Киплячому Ставку під Шпилем Темної Хмари в Тисячі...",kw={"інцендія-агава","киплячий ставок","шпиль темної хмари","тисяча голок","маґата ґрімтотем","травництво","шаман"},ang={["class:Shaman"]="Щоб перетворити водяний сукулент на порошок, достатньо могутній для розпалу священного обрядового вогню, потрібне справжнє шаманське мистецтво стихій.",["profession:Herbalism"]="Травникам знадобиться їхнє чуття на трави, щоб відшукати колючі кущики Інцендії-Агави, сховані на каламутному дні Киплячого Ставка."},sec={{t="Рідкісна пустельна трава",b="Інцендія-Агава росте під водою та довкола Киплячого Ставка в Тисячі Голок, просто в тіні Шпиля Темної Хмари. Її природно охороняють мандрівні елементалі пари, тож рослину важко зібрати, і в Калімдорі вона трапляється рідко. Хоч агава й росте під водою, у ній криються могутні природні сили, що напрочуд добре служать обрядам полум'я."},{t="Священний вогонь",b="Таурени, обізнані в обрядах, знають, що приспаний священний вогонь життя не розпалити звичайною іскрою. Старійшина Маґата Ґрімтотем з Узвишшя Старійшин у Тандер Блафі має шаманські знання, потрібні, щоб зачарувати зібрані оберемки Інцендії-Агави й перетворити їх на містичний порошок. Готовий порошок розпалює обрядову жаровню, необхідну для прикликання мстивого вітряного змія Арікари."}},faq={{q="Де росте Інцендія-Агава?",a="Інцендія-Агава росте в озері Киплячого Ставу й довкола нього, під Шпилем Темної Хмари на півночі Тисячі Голок. Чимало її лежить під водою на дні озера.",al={"де знайти агаву","місце інцендія-агави","де агава"}},{q="Для чого потрібна Інцендія-Агава?",a="З десяти в'язок агави роблять обрядовий порошок. Коли Маґата Ґрімтотем у Тандер Блафі зачарує його, порошком запалюють священне вогнище життя й викликають змію Арікару.",al={"призначення інцендія-агави","навіщо збирати агаву","що робить агава"}},{q="Хто може зачарувати Інцендію-Агаву?",a="Маґата Ґрімтотем, впливова шаманка з Узвишшя Старійшин у Тандер Блафі, знає обрядове ремесло, щоб уплести шаманську магію в сиру рослину.",al={"хто зачаровує агаву","агава мафати","хто перетворює агаву на порошок"}},{q="Які загрози чатують довкола Інцендії-Агави?",a="Водами й берегами Киплячого Ставу никають ворожі парові елементалі, надзвичайно стійкі до чарів криги й вогню.",al={"небезпеки агави","що охороняє агаву","небезпеки киплячого басейну"}}},fp="14,222,18.381.0,15.376.1,31.202.0,32.203.0,35.161.0,41.141.0"}
P.entries["item:incendia-powder"] = {n="Інцендієвий Порошок",s="Інцендієвий Порошок — зачарований обрядовий каталізатор, очищений для розпалу священного полум'я. Посланці Орди несуть його до Тисячі Голок; порошок спеціально оброблено шаманськими заклинаннями, щоб викликати приспаного звіра-духа Арікару на вершині Шпиля Темної Хмари.",h="Інцендієвий Порошок — зачарований обрядовий каталізатор, очищений для розпалу священного полум'я.",kw={"інцендієвий порошок","арікара","маґата ґрімтотем","шпиль темної хмари","кайрн бладгуф","священний вогонь","обряд"},ang={["class:Shaman"]="Цей порошок показує, як полум'я стихій і духовну силу можна зв'язати воєдино, щоб пробудити приспаних духів предків.",["race:Tauren"]="Розпалювання поховальних вогнищ обрядовими порошками відображає хитку рівновагу між шануванням священних традицій і захистом провідників племен."},sec={{t="Іскра прикликання",b="Інцендієвий Порошок — не звичайна вибухівка й не простий спалаховий порох, а очищена обрядова речовина, старанно насичена шаманською магією. Суміш, яку зачаровує й довіряє мандрівникам Маґата Ґрімтотем з Узвишшя Старійшин у Тандер Блафі, створено так, щоб вона реагувала лише зі священним вогнем життя, що горить на відлюдних скелях Шпиля Темної Хмари. Щойно її розсипають на освяченій жаровні, де покоять мертвих, її алхімічна й духовна сила прикликає мстивого крилатого змія Арікару."},{t="Тривожні знамення",b="Обряди, за якими створюють і використовують Інцендієвий Порошок, ґрунтуються на тлумаченнях старої шаманки Маґати Ґрімтотем. Вона вірила, що зміни традицій і звичаїв тауренів спонукали прадавніх духів полювати на Верховного Вождя Кайрна Бладгуфа, тож порошок зачарували, щоб змусити привид вийти на світло, де його можна знищити. Хоч порошок і справді прикликає лютого змія, жорстока сутичка лишає тривожні питання: що насправді розбурхало такого звіра?"}},faq={{q="Для чого потрібен Інцендієвий Порошок?",a="Інцендієвий Порошок — зачарований пил, який кидають у священне вогнище життя на вершині Шпиля Темної Хмари в Тисячі Голок. Полум'я, розпалене цією сумішшю, викликає мстиву духовну змію Арікару.",al={"призначення інцендієвого порошку","навіщо мені інцендієвий порошок","що робить інцендієвий порошок"}},{q="Хто зачарував порошок?",a="Маґата Ґрімтотем перетворила зібрану інцендієву агаву на зачарований порошок на Узвишші Старійшин у Тандер Блафі, після того як Мотеґа Фаєрмейн із Застави Білого Рубежу сповістив про Арікару.",al={"хто зробив інцендієвий порошок","хто зачарував інцендієвий порошок"}},{q="Де треба використати порошок?",a="Його треба розсипати у священному вогнищі на самотній поховальній скелі-голці в Шпилі Темної Хмари, високо над соляними каньйонами Тисячі Голок.",al={"місце інцендієвого порошку","куди кинути порошок","де використати порошок"}},{q="Навіщо треба було викликати Арікару?",a="Magatha Grimtotem fears that changes in tauren lore have angered Arikara and that the serpent may be stalking Cairne Bloodhoof. She asks that Arikara be summoned and slain before harm can come to Cairne.",al={"навіщо викликати арікару","чому битися з арікарою"}}},fp="15,264,20.522.0,15.503.1,33.199.0,43.174.0,38.156.0,36.203.0"}
P.entries["item:insane-scribbles"] = {n="Божевільні Каракулі",s="Вирвані з незбагненного Сутінкового Фоліанта, Божевільні Каракулі — уривок темного письма, який носять культисти на Темному Узбережжі. Від самого погляду на танцюючий текст і спотворені завитки паморочиться в голові й важчає розум. Давні охоронці лісу вивчають такі уривки, щоб розгадати зловісні наміри Молота Присмерку.",h="Вирвані з незбагненного Сутінкового Фоліанта, Божевільні Каракулі — уривок темного письма, який носять...",kw={"божевільні каракулі","сутінковий фоліант","молот присмерку","ону","гай прадавніх","древні боги"},ang={["class:Priest"]="Жерці, чутливі до ментальних атак і енергій, торкнутих Порожнечею, розпізнають у звивистих письменах небезпечний прояв божевілля, що прямо протистоїть ясності Світла.",["race:NightElf"]="Для нічних ельфів реліквії Молота Присмерку — загроза порчі для давнього спокою та священних земель Темного Узбережжя."},sec={{t="Рукопис, що зводить з розуму",b="Дивитися на сторінки Сутінкового Фоліанта вкрай небезпечно для смертного розуму. Письмена звиваються пергаментом, а витончені завитки на очах у читача перетворюються на гротескні, тривожні образи. Навіть вирвати один аркуш — ці Божевільні Каракулі — справжнє випробування, після якого в голові паморочиться й усе пливе. Попри хаотичну безладність письма, пергамент бринить первісною, прадавньою магією, пов'язаною просто з темними силами, давно похованими під Азеротом."},{t="Підказки для Прадавніх",b="Коли каракулі приносять Ону — шанованому прадавньому, що опікується Гаєм Прадавніх, — вони відкривають погляд на напасті, які нищать Темне Узбережжя. Ону впізнає хаотичну енергію, що в'їлася в пергамент, як безпомилковий почерк Древніх Богів. Для захисників Калімдору зібрати каракулі докупи — важливий крок до того, щоб з'ясувати, навіщо саме Молот Присмерку зібрався на оповитих імлою берегах."}},faq={{q="Що станеться, якщо спробувати прочитати ці каракулі?",a="Текст не піддається простому перекладу. Варто лише подивитися на пергамент, як літери починають пливти, а візерунки довкола перетворюються на жахливі обриси, — і того, хто намагається їх розшифрувати, раптом охоплюють запаморочення й розумова втома.",al={"прочитати божевільні каракулі","що написано в тексті","чи можна їх прочитати"}},{q="Звідки вирвано ці каракулі?",a="Їх вирвали з Фоліанта Присмерку — мерзенного гримуара культистів Молота Присмерку, що орудують на Темному Узбережжі.",al={"звідки каракулі","походження тому сутінків"}},{q="Хто може зрозуміти чи вивчити каракулі?",a="Повернений пергамент оглядає Древо Знань, Ону. Спираючись на віковічну мудрість, Ону відчуває прадавню, первісну магію, що скріплює чорнило, і прагне з'ясувати, що культ замислює в цьому краї.",al={"хто хоче каракулі","каракулі ону"}},{q="Яка сила йде від пергаменту?",a="Пергамент пульсує хаотичною первісною магією, пов'язаною з Древніми Богами, — темними божествами, яким поклоняється Молот Присмерку.",al={"яка магія в каракулях","тип магії"}}},fp="16,345,22.508.0,22.439.1,48.240.0,37.119.0,42.206.0,47.134.0"}
P.entries["item:inscribed-bark"] = {n="Гравірована Кора",s="Гравірована Кора — живий пергамент, який прадавнє Дерево Оракула довіряє, щоб донести звістку про стан Тельдрассила Архідруїдові Фандралу Стаґгелму. Це офіційний звіт про віття Світового Дерева й незгасні загрози, що тривожать його ліси.",h="Гравірована Кора — живий пергамент, який прадавнє Дерево Оракула довіряє, щоб донести звістку про стан...",kw={"гравірована кора","дерево оракула","фандрал стаґгелм","послання","коло кенарія","дарнасус","тельдрассил"},ang={["class:Druid"]="Друїди впізнають у цій гравірованій деревині нагальне послання від прадавнього союзника, що підкреслює хистку рівновагу й тривалі недуги молодого Світового Дерева.",["race:NightElf"]="Для калдореїв послання на корі прадавніх дерев уособлюють священний зв'язок між природою та її охоронцями, з'єднуючи дикі гаї з мармуровими терасами Дарнасуса."},sec={{t="Послання від Оракула",b="Вирізана зі священної деревини Дерева Оракула, ця гравірована кора — пряме послання від прадавнього охоронця проводу Кола Кенарія в Дарнасусі. Коли шукачі пригод приборкують гарпій, що зазіхають на галявини, Дерево Оракула довіряє їм цей знак, не бажаючи ризикувати звичайними гінцями на споганених стежках віття. Вирізьблене послання сповіщає Архідруїда Фандрала Стаґгелма і про нещодавні перемоги, і про глибшу, тривожну пошесть, що й далі тримає Тельдрассил."}},faq={{q="Що таке Гравірована Кора?",a="Це шматок кори з написом від Дерева Оракула — звіт про здоров'я гілок і небезпеки, що їм загрожують, для Архідруїда Фандрала Стаґгелма в Дарнасусі.",al={"що таке гравірована кора","кора дерева оракула","призначення гравірованої кори"}},{q="Хто надсилає це послання й навіщо?",a="Дерево Оракула вручає його шукачам пригод, коли ті проженуть гарпій із гнізд. Прадавнє дерево вже остерігається посилати звичайних гінців небезпечними лісовими стежками, тож довіряє свій звіт перевіреному мандрівникові.",al={"хто написав гравіровану кору","хто дає гравіровану кору","гонець дерева оракула"}},{q="Як Архідруїд Фандрал Стаґгелм сприймає послання?",a="Фандрал визнає, що вигнання гарпій дало перепочинок, але з досадою зауважує, що глибші біди нікуди не ділися. Звіт підживлює його давні сумніви, чи поверне колись його праця над Тельдрассилом нічним ельфам утрачене безсмертя.",al={"реакція фандрала на кору","що каже фандрал про кору"}}},fp="14,252,25.522.0,23.172.0,31.233.0,58.264.1"}
P.entries["item:intact-raptor-horn"] = {n="Цілий Ріг Раптора",s="Цілий ріг, здобутий у хижих рапторів, що никають саванами Пусток. Збережений у бездоганному стані, він дуже потрібен заповзятливому гоблінові, який хоче заробити на чутках про розум рапторів.",h="Цілий ріг, здобутий у хижих рапторів, що никають саванами Пусток.",kw={"цілий ріг раптора","раптори","мебок міззірікс","раджет","ішамугале","полювання"},ang={["class:Hunter"]="Щоб здобути ріг-трофей цілим, потрібне чисте вбивство — і воно доводить вашу влучність у двобої з одними з найлютіших хижаків савани.",["profession:Cooking"]="Мебок збирається розтерти роги для настоянок на вині, але досвідчені виживальники знають: частини рапторів зазвичай краще годяться на знаряддя, ніж на смачну страву."},sec={{t="Сумнівний складник",b="Звичайні мисливці цінують частини рапторів заради шкур, кігтів і трофеїв, але неушкоджені роги в полі трапляються рідше. У портовому містечку Раджет дивакуватий гоблін-алхімік на ім'я Мебок Міззірікс виплекав химерну теорію про місцеву звірину: раптори Пусток хитріші за своїх родичів деінде, тож він підозрює, що їхній розум міститься просто в рогах. Розтираючи цілі роги й варячи з них тонізувальні настоянки, Мебок прагне розлити цей уявний геній по пляшках і продавати як «розумні напої»."},{t="На слідах зграй",b="Бездоганний ріг не відколеш у першого-ліпшого молодого звіра. Щоб отримати придатний для варива матеріал, мисливці мусять здобувати роги в особливо лютих хижаків — як-от сонцелускаті косокігті, що никають південними рівнинами й північними околицями біля Ашенвалю. Легендарні жахи степу, як-от Такк Стрибун і невловимий Ішамугале, теж мають роги, досить міцні, щоб уціліти в запалі полювання."}},faq={{q="Кому потрібні ці цілі роги рапторів?",a="Їх шукає Мебок Міззірікс — гоблін-торговець і пивовар-початківець із Раджета. Він вірить, що цілі роги — ключ до його наступного товару, на якому можна швидко розбагатіти.",al={"кому потрібні роги рапторів","покупець рогів","хто купує ріг раптора"}},{q="Чому роги мають бути цілими?",a="Мебок хоче розтерти їх на дрібний порошок, щоб додавати в питво. Надщерблені чи зламані роги або викидають під час полювання, або вважають зіпсованими: у них немає всієї сили, яку гоблін сподівається використати у своїх рецептах.",al={"чому цілі","зламані роги"}},{q="Які раптори носять ці роги?",a="Їх здебільшого мають дорослі сонцелускі косокігті, що никають на крайній півночі й півдні Пусток, а також сумнозвісні раптори-одинаки, як-от Ішамугале й Такк Стрибун.",al={"звідки падають роги","які раптори","хто дропає цілий ріг"}},{q="Чи справді роги рапторів роблять розумнішим?",a="Раптори Пусток славляться незвичною зграйною хитрістю й злагодженістю, але думка, що їхній розум зберігається в рогах — і передається через напій, — лише неперевірена гоблінська вигадка.",al={"чи розумнішають від рогів","чи раптори розумні","розум рапторів"}}},fp="18,211,25.550.0,19.428.0,36.164.0,35.223.0,25.191.0,42.194.0"}
P.entries["item:intrepid-strongbox-key"] = {n="Ключ від Скрині Безстрашності",s="Ключ від Скрині Безстрашності — іржавий залізний ключ, який ревно беріг Капітан Галіндор, командир приреченого корабля Альянсу «Безстрашний». Навіть у нежитті капітан стискає його в руці, тримаючи під замком прокляту реліквію, що занапастила його команду біля берегів Багнокраю.",h="Ключ від Скрині Безстрашності — іржавий залізний ключ, який ревно беріг Капітан Галіндор, командир...",kw={"ключ від скрині безстрашності","капітан галіндор","третій флот","ґлорін стілброу","прокляття","гавань менетіл"},ang={["class:Priest"]="Ключ відмикає артефакт мерзенної некротичної сили, тож потрібні святі обряди менетілського жерця Ґлоріна Стілброу, щоб очистити його й упокоїти душі команди.",["faction:Alliance"]="Ключ належав командирові Третього флоту Альянсу, чия трагічна загибель біля берегів Гавані Менетіл досі лишається відкритою раною для вцілілих мешканців гавані."},sec={{t="Капітанова таємниця",b="Коли Третій флот розбився біля бурхливих берегів Багнокраю, бойовий корабель «Безстрашний» обернувся на руїну, а його команда — на неспокійних проклятих духів. Капітан Галіндор одержимо беріг загадковий предмет, схований у важкій скрині корабля. І по смерті його примарна постать блукає залитою водою палубою, не віддаючи іржавого ключа, що відмикає найглибший і найтемніший вантаж трюму."},{t="Розірвати пута",b="Вирвати ключ у Капітана Галіндора — єдиний спосіб відімкнути скриню «Безстрашного» й забрати прокляту реліквію, що прикувала команду до її мук. Лише здобувши цим ключем предмет, його можна віднести дворфові-жерцеві Ґлоріну Стілброу в Гавань Менетіл, щоб він його очистив."}},faq={{q="Хто носить Ключ від Скрині Безстрашності?",a="Ключ тримає Капітан Галіндор — примарний командир, що походжає верхньою палубою північного розбитого корабля біля північно-східного узбережжя Багнокраю.",al={"у кого ключ","дроп ключа безстрашності","ключ галіндора"}},{q="Що відмикає Ключ від Скрині Безстрашності?",a="Він відмикає Замкнену Скриню «Безстрашного», що лежить під водою в розколотому корпусі затонулого корабля під капітанською палубою.",al={"що відмикає ключ","місце скрині безстрашності","де скриня"}},{q="Чому скриню тримали замкненою?",a="Капітан Галіндор замкнув у скрині темний проклятий предмет, щоб сховати його й убезпечити, але лихе зло, що з нього сочилося, зрештою занапастило корабель і прикувало його команду до нежиття.",al={"що було в скрині","чому замкнена"}},{q="Хто може очистити проклятий предмет зі скрині?",a="Ґлорін Стілброу, дворф-жрець із Гавані Менетіл, має святі знання, потрібні, щоб очистити проклятий артефакт, коли скриню відімкнуто.",al={"хто очищає","скриня ґлоріна стілброу"}}},fp="22,284,18.424.0,17.321.1,39.150.0,42.138.0,34.176.0,49.160.0"}
P.entries["item:invisibility-liquor"] = {n="Лікер Невидимості",s="Лікер Невидимості — міцний, алхімічно насичений напій, зварений з рідкісних листів кристалевої ламінарії, знайдених у Лісі Елвінн. Створений, щоб на коротку мить зробити того, хто його вип'є, невидимим, він стає ключем таємної змови, яка дозволяє двом молодим закоханим обійти ворожнечу своїх родин.",h="Лікер Невидимості — міцний, алхімічно насичений напій, зварений з рідкісних листів кристалевої ламінарії...",kw={"лікер невидимості","алхімія","томмі джо","мейбелл маклур","кристалева ламінарія","закохані"},ang={["class:Mage"]="Поки чарівники Кірін-Тору роками відточують ілюзії й закляття невидимості, мешканці Елвінну домагаються грубого наслідування за допомогою перебродженого спирту й намоклої ламінарії.",["race:Human"]="Цей напій показує, до яких безглуздих крайнощів доходить гірка сільська ворожнеча в Лісі Елвінн між родами Стоунфілдів і Маклурів."},sec={{t="Зілля для нещасливих закоханих",b="Тривала ворожнеча між Стоунфілдами й Маклурами робить мирні стосунки між їхніми домами майже неможливими. Коли молодий Томмі Джо Стоунфілд прагне зустрітися з Мейбелл Маклур подалі від пильних очей рідні, звичайної потайності замало. Лікер Невидимості дає дивовижний вихід: хмільний напій, що згинає зір довкола того, хто його випив, даруючи рівно стільки непомітності, щоб непоміченим перетнути спірні поля."},{t="Незвична алхімія Елвінну",b="Зварений з листів кристалевої ламінарії, здобутих у тутешніх водах, де кишать мурлоки, цей напій поєднує простий самогонний промисел із сирими магічними реагентами. Хоч трунок незаконний і, можливо, небезпечний для вживання, він виявляється достатньо сильним, щоб Мейбелл зникла з очей, щойно він торкнеться її губ, і вона змогла вислизнути в ліс на таємне побачення."}},faq={{q="Що робить Лікер Невидимості?",a="Це міцний трунок із магічними властивостями, що на якийсь час робить того, хто його вип'є, цілком невидимим.",al={"дія лікеру","напій невидимості","що він робить"}},{q="Хто користується Лікером Невидимості?",a="Лікер приносять Мейбелл Маклур, щоб вона зникла з очей рідні й прокралася на зустріч зі своїм коханим, Томмі Джо Стоунфілдом, попри ворожнечу їхніх родин.",al={"хто п'є лікер","лікер мейбел маклюр"}},{q="Як роблять лікер?",a="Його варять із Листів Кристалевої Ламінарії, зібраних на річкових руслах і берегах озер Лісу Елвінн, де мурлоки часто ховають ці чарівні рослини.",al={"інгредієнти лікеру","лікер з кристалевої ламінарії"}},{q="Чи можна самому випити Лікер Невидимості?",a="Ні. Цей напій — особливий предмет завдання, призначений лише для доставки Мейбелл Маклур у межах її плану вислизнути з дому.",al={"чи можна випити самому","випити лікер невидимості"}}},fp="19,300,32.449.0,25.363.1,33.126.0,33.177.0,23.146.0,53.144.0"}
P.entries["item:iron-pike"] = {n="Залізний Шпичак",s="Залізні Шпичаки — міцні будівельні матеріали, які відправили зі Стормвінда на ремонт Мосту Еверстілл у Лейкширі. Гноли Редріджу влаштували засідку на валку й розграбували її, тож містечку тепер бракує найнеобхіднішого для відбудови.",h="Залізні Шпичаки — міцні будівельні матеріали, які відправили зі Стормвінда на ремонт Мосту Еверстілл у...",kw={"залізний шпичак","міст еверстілл","бригадир ослоу","гноли","лейкшир","редрідж"},ang={["faction:Alliance"]="Повертаючи вкрадені будівельні матеріали від диких гнолів, ви допомагаєте вберегти важливі переправи Лейкширу, а з ними — й укріплений східний кордон Стормвінда від нападів Блекрок.",["profession:Blacksmithing"]="Ці важкі будівельні шпичаки показують, як тяжко довелося місцевим ковалям: усе сире залізо пішло на зброю."},sec={{t="Викрадений вантаж",b="Коли на Лейкшир нещодавно напали орки Блекрок, усі запаси металу в містечку переплавили на обладунки, клинки й боєприпаси для оборони. Через нестачу заліза місцеві будівельники попросили нову партію зі Стормвінда. Та ще до того, як матеріали дісталися містечка, зграя гнолів Редріджу перехопила валку просто на дорозі. Гноли затягли ящики із залізними шпичаками й заклепками на північ, у пагорби, і важливий ремонт Мосту Еверстілл зупинився."},{t="Відбудова прольоту",b="Бригадир Ослоу, якому доручили наглядати за відбудовою Мосту Еверстілл, розраховує на шукачів пригод: хтось мусить піти на землі гнолів і повернути вкрадене залізо. Без цих важких залізних шпичаків, що скріплюють кам'яно-дерев'яний каркас, Лейкшир лишається частково відрізаним від північного шляху й беззахисним перед новими нападами."}},faq={{q="Чому гноли носять будівельні шпичаки?",a="Гноли напали на караван із припасами, що йшов зі Стормвінда до Лейкширу. Вони розбіглися пагорбами Редріджу з ящиками вкраденого будівельного залізяччя — зокрема залізними шпичаками й заклепками.",al={"чому гноли мають залізні шпичаки","звідки гноли взяли шпичаки"}},{q="Кому в Лейкширі потрібні ці залізні шпичаки?",a="Бригадирові Ослоу — щоб відбудувати Незрушний Міст, що з'єднує Лейкшир через Озеро Незрушне. Вільного заліза в місті немає: місцеві запаси переплавили на зброю й обладунки під час недавніх нападів орків.",al={"кому потрібні залізні шпичаки","наглядач ослоу шпичаки"}},{q="Де знайти ці залізні шпичаки?",a="Вони в гнолів Редріджу, що отаборилися на пагорбах і хребтах на північ від Лейкширу.",al={"де знайти залізні шпичаки","місце залізних шпичаків"}},{q="Чому Лейкшир не міг сам викувати шпичаки?",a="Лейкшир вичерпав місцеве залізо, відбиваючись від орків Блекрок: кожен клаптик металу переплавили на мечі, кулі й захисне спорядження. Довелося просити в Стормвінда нового будівельного заліза.",al={"чому лейкшир замовив залізо","нестача заліза в лейкширі"}}},fp="9,247,20.497.0,19.340.0,47.192.0,40.226.0,40.89.0,55.214.0"}
P.entries["item:iron-pommel"] = {n="Залізне Навершя",s="Залізне Навершя — остання бракуюча частина Жезла Дартола, створеного давно померлим чарівником Дартолом. Нічні ельфи з Астранаару шукають цей жезл, щоб стримати напади фурболгів на свій народ. Навершя віддали на зберігання друїдам Підземної Обителі Дор'Даніл, але воно загубилося, коли їхній притулок спустошила різанина, а потім заполонили слизуни.",h="Залізне Навершя — остання бракуюча частина Жезла Дартола, створеного давно померлим чарівником Дартолом.",kw={"залізне навершя","жезл дартола","дор'даніл","друїди","слизуни","ашенваль"},ang={["class:Druid"]="Навершя — похмурий пам'ятник загиблим друїдам Дор'Даніла, чия священна служба скінчилася різаниною на узліссі.",["faction:Alliance"]="Повернення навершя завершує важливий етап у відновленні Жезла Дартола — знаряддя, без якого не захистити Ашенваль від порчі, що підкрадається."},sec={{t="Тягар загиблого кола",b="Щоб уберегти містичну силу Жезла Дартола, його розділили й розпорошили по всьому Ашенвалю. Залізне Навершя довірили друїдам нічних ельфів, що жили біля дороги, яка в'ється на південь до Пусток. Лихо спіткало відлюдну громаду в Підземній Обителі Дор'Даніл: коло друїдів вирізали, і їхній тихий притулок поринув у мертву тишу. Навершя зникло серед цього спустошення — його поглинули потворні булькотливі слизуни, що тепер плазують оскверненою галявиною."},{t="Здобуте з багна",b="Друїди загинули, тож щоб знайти навершя, доводиться обнишпорити осквернену западину на південь від Застави Розщепленого Дерева. Реліквія лишалася замкненою в міцній скрині. Шукачі пригод, прорубуючись крізь зіпсованих слизунів, знаходять проковтнуту скриню цілою в їдкій масі одного з них — і нарешті здобувають останню частину, потрібну, щоб відновити жезл."}},faq={{q="Для чого потрібне Залізне Навершя?",a="Залізне Навершя — остання частина, потрібна, щоб зібрати Жезл Дартола. Принісши його Шаель'дрін до місячного колодязя, ви даєте їй змогу відновити прадавній артефакт, щоб послабити напади фурболгів на нічних ельфів Ашенвалю.",al={"призначення залізного навершя","навіщо мені залізне навершя","що робить залізне навершя"}},{q="У кого спершу було навершя?",a="Його довірили друїдам нічних ельфів, що жили біля дороги до Пусток. На жаль, коло вирізали, перш ніж жезл устигли зібрати, і їхній притулок лежить у руїнах.",al={"хто охороняв навершя","у кого було залізне навершя","друїди дор'данілу"}},{q="Де знайти навершя?",a="Навершя замкнене в скрині, яку носить у собі один зі зіпсованих слизів, що блукають отруєною улоговиною на схід від головного шляху, на південь від Застави Розщепленого Дерева й на північ від кордону з Пустками.",al={"місце залізного навершя","де залізне навершя","де взяти залізне навершя"}},{q="Кому віднести навершя?",a="Навершя треба принести Шаель'дрін — дріаді, що доглядає місячний колодязь на схід від Озера Ірисів: вона знає обряд, щоб відновити Жезл Дартола.",al={"здати залізне навершя","куди нести навершя","кому потрібне навершя"}}},fp="11,335,23.480.0,23.343.1,33.241.0,30.195.0,26.190.0,29.153.0"}
P.entries["item:iron-rivet"] = {n="Залізна Заклепка",s="Залізні Заклепки — міцні будівельні кріплення, виготовлені в Стормвінді для відбудови зруйнованого Мосту Еверстілл у Лейкширі. Після того як гноли Редріджу влаштували засідку на валку з припасами й розграбували її, ці важкі металеві деталі розлетілися по таборах гнолів на північних пагорбах.",h="Залізні Заклепки — міцні будівельні кріплення, виготовлені в Стормвінді для відбудови зруйнованого Мосту...",kw={"залізна заклепка","міст еверстілл","бригадир ослоу","гноли","лейкшир","озеро незрушне"},ang={["faction:Alliance"]="Повертаючи вкрадені припаси, ви безпосередньо допомагаєте відбудовувати Лейкшир і стримуєте гнолів, що зухвало загрожують містечку.",["profession:Blacksmithing"]="Ці надміцні кріплення — звичайна стормвіндська ковальська робота, викувана саме для того, щоб скріплювати великі споруди на кшталт кам'яно-дерев'яних мостів."},sec={{t="Викрадений вантаж",b="Коли орки Блекрок раз у раз штурмували Лейкшир, міська рада була змушена переплавити будівельні запаси заліза на зброю, обладунки й боєприпаси. Щойно найгірше минуло, Бригадир Ослоу попросив у Стормвінда нових будівельних матеріалів, щоб полагодити розколотий Міст Еверстілл. Та ще до міста валку з вантажем перехопили місцеві гноли Редріджу. В'ючних тварин і вози затягли в пагорби на північ від Озера Незрушного, а потрібні для будівництва матеріали — залізні заклепки й шпичаки — розійшлися по гнолівських зграях."},{t="Лагодження мосту",b="Без цих важких залізних заклепок ремонтувати Міст Еверстілл небезпечно. Кам'яно-дерев'яний каркас, перекинутий через озеро, потребує надійних металевих кріплень, щоб витримувати вагу возів і подорожніх. Тільки повернувши заклепки з таборів гнолів, можна відновити важливий зв'язок Лейкширу із західними долинами й захистити околиці міста від нових нападів."}},faq={{q="Для чого потрібні Залізні Заклепки?",a="Це важкі будівельні кріплення, потрібні Бригадирові Ослоу, щоб полагодити пошкоджений Незрушний Міст у Лейкширі, який утратив своє залізо під час боїв з орками Блекрок.",al={"призначення залізних заклепок","навіщо потрібні залізні заклепки","для чого заклепки"}},{q="Звідки в гнолів ці заклепки?",a="Караван із припасами, відправлений зі Стормвінда, гноли Редріджу захопили просто на дорозі. Ці мародери потягли будівельний вантаж — заклепки й залізні шпичаки — до своїх таборів на північ від Лейкширу.",al={"чому гноли мають заклепки","як гноли отримали заклепки","хто вкрав заклепки"}},{q="Чому Лейкширу взагалі забракло заліза?",a="Під час недавньої навали орків захисники Лейкширу мусили переплавити всі запаси заліза на мечі, кулі й обладунки, щоб вистояти в облозі.",al={"нестача заліза в лейкширі","чому в лейкширі немає заліза"}},{q="Хто шукає ці заклепки?",a="Бригадир Ослоу — майстер-будівничий, що керує відновленням Незрушного Мосту на березі біля Лейкширу.",al={"хто хоче заклепки","хто бере залізні заклепки"}}},fp="10,290,20.609.0,18.418.0,30.186.0,36.215.0,46.158.0,32.112.0"}
P.entries["item:iron-shaft"] = {n="Залізне Древко",s="Залізне Древко — металева частина Жезла Дартола, реліквії, яку шукав Тероніс, друг Рейн Вульфраннер, сподіваючись стримати напади фурболгів на Ашенваль. Здобуте із замкненої скрині біля кордону зі Скверноліссям, воно стає важливою складовою відновлення реліквії для захисників Ашенвалю.",h="Залізне Древко — металева частина Жезла Дартола, реліквії, яку шукав Тероніс, друг Рейн Вульфраннер...",kw={"залізне древко","жезл дартола","древені","сквернолісся","шаель'дрін","ашенваль"},ang={["class:Druid"]="Відновлення Жезла Дартола тісно пов'язане з друїдським служінням природі: забуті знаряддя допомагають зцілювати поранені землі.",["race:NightElf"]="Здобути Залізне Древко — сумний обов'язок, адже для цього доводиться вбивати улюблених лісових древенів, що стали жертвами демонічної порчі, яка просочується зі Сквернолісся."},sec={{t="Частина Жезла Дартола",b="Жезл Дартола створив Дартол, а його частини розпорошили по всьому Ашенвалю; одну навіть віддали на зберігання друїдам Дор'Даніла. Залізне Древко — міцна металева основа цього знаряддя; його сховали в замкненій скрині на відлюдній галявині біля північного кордону Ашенвалю, неподалік від оскверненого Сквернолісся."},{t="Порча лісу",b="Щоб здобути Залізне Древко, треба забрати ключ від скрині в місцевих древенів, що колись доглядали ці ліси. Демонічна порча повзе на південь зі Сквернолісся, і прадавні охоронці — Збожеволілі Прадавні та Зів'ялі Прадавні — втратили розум. Дріада Шаель'дрін доручає мандрівникам здобути древко, щоб жезл можна було викувати наново, а справу загиблого Тероніса — завершити."}},faq={{q="Для чого потрібне Залізне Древко?",a="Залізне Древко — частина Жезла Дартола, розбитої реліквії. Його збирають, щоб дріада Шаель'дрін допомогла зібрати жезл і завершити справу Тероніса, який шукав його, щоб послабити напади фурболгів на Ашенваль.",al={"призначення залізного древка","що це за древко","навіщо мені залізне древко"}},{q="Де знайти Залізне Древко?",a="Воно замкнене в скрині в тихій галявині на захід від дороги до Сквернолісся, на півночі Ашенвалю.",al={"місце залізного древка","знайти залізне древко","де скриня"}},{q="Як відчинити скриню з древком?",a="Для скрині потрібен Дерев'яний Ключ. Його носять зіпсовані деревники — Збожеволілі й Зів'ялі Прадавні, — що блукають лісами на північний схід від Притулку Рейнвуд.",al={"як відчинити скриню","ключ від скрині","ключ залізного древка"}},{q="Хто шукає Залізне Древко?",a="Шаель'дрін, дріада біля місячного колодязя в центрі Ашенвалю, посилає шукачів пригод зібрати частини Жезла Дартола в межах зусиль очистити ліс.",al={"хто хоче залізне древко","видавець завдання на древко"}}},fp="10,303,23.355.0,19.392.1,32.214.0,30.128.0,47.166.0,34.167.0"}
P.entries["item:ironband-s-progress-report"] = {n="Звіт про Поступ Айронбенда",s="Звіт про Поступ Айронбенда — письмове донесення про негаразди на розкопках Шукача Айронбенда у східному Лох Модані. У ньому розповідається і про повільне копання, якому заважають агресивні троги, і міститься нагальне прохання надіслати ще вибухового пороху.",h="Звіт про Поступ Айронбенда — письмове донесення про негаразди на розкопках Шукача Айронбенда у східному Лох...",kw={"звіт айронбенда","шукач айронбенд","лох модан","троги","вибуховий порох","розкопки","джерн горнгелм"},ang={["profession:Mining"]="Рудокопи надто добре знають, як потрібен вибуховий порох, щоб розчистити вперту породу, — і яка це небезпека, коли припаси зникають на землях трогів.",["race:Dwarf"]="Для дворфійських дослідників і рудокопів це донесення — свідчення небезпечної дійсності розкопок давніх пам'яток титанів у самому серці Каз Модану."},sec={{t="Благання про порох",b="Розкопкам Шукача Айронбенда в Лох Модані безперестанку заважають місцеві троги. Щоб робота не стала, Айронбенд склав цей звіт і знову виклав у ньому свою відчайдушну потребу у вибуховому порохові. Звіт спершу несуть Джернові Горнгелму в Телсамар, а потім пересилають до Асамблеї Дослідників в Айронфорджі: він описує простої на розкопках і просить важких боєприпасів. Донесення швидко змушує керівництво Ліги звести брови, адже кілька тижнів тому Айронбендові вже відправили чималий запас пороху, і начальство не може збагнути, куди поділися попередні вантажі."}},faq={{q="Що таке Звіт про Поступ Айронбенда?",a="Це офіційне донесення з поля, яке написав Шукач Айронбенд про стан своїх розкопок у Лох Модані: він скаржиться, що йому заважають троги, і вимагає ще вибухового порошку.",al={"звіт про поступ","звіт айронбенда","що це за звіт"}},{q="Хто отримує цей звіт?",a="Спершу звіт доставляють Джернові Горнгелму — місцевому посередникові розкопок у Телсамарі. Горнгелм посилає того, хто його приніс, просто до Шукача Стормпайка в штабі Ліги Дослідників в Айронфорджі.",al={"хто отримує звіт","кому віддати звіт","доставити звіт про поступ"}},{q="Навіщо Айронбенду ще вибуховий порошок?",a="Айронбенд запевняє, що порошок потрібен для археологічних розкопок, хоча постійні набіги трогів неподалік натякають, що вибухівка може знадобитися йому й для оборони. Дивно, але і Горнгелм, і Стормпайк вважають, що ще кілька тижнів тому надіслали йому вдосталь порошку.",al={"чому вибуховий порошок","що сталося з порошком","нестача порошку"}},{q="Як Шукач Стормпайк сприймає звіт?",a="Стормпайк лютує через повільний поступ і не може второпати, чому Айронбенд ні словом не згадує величезну партію порошку, відправлену раніше, — і питає, куди могли подітися зниклі боєприпаси.",al={"реакція стормпайка","чи стормпайк сердиться"}}},fp="26,253,20.597.0,35.210.0,25.224.0,40.252.0,50.203.0"}
P.entries["item:ishamuhale-s-fang"] = {n="Ікло Ішамугале",s="Ікло Ішамугале — мисливський трофей, здобутий в Ішамугале, сумнозвісного сонцелускатого раптора, знаного в Пустках як Списозуб. Принесений Джорнові Скайсіру в Табір Тауражо, зуб доводить перемогу над одним із найсмертоносніших природних хижаків Калімдору.",h="Ікло Ішамугале — мисливський трофей, здобутий в Ішамугале, сумнозвісного сонцелускатого раптора, знаного в...",kw={"ікло ішамугале","ішамугале","списозуб","джорн скайсір","табір тауражо","раптори"},ang={["class:Hunter"]="Здобути ікло Списозуба — важливий обряд посвяти в Пустках, що перевіряє вміння слідопита виманити, зустріти й здолати хитрого верховного звіра.",["race:Tauren"]="Для мисливців Тауражо здобути ікло — не про безглузде вбивство, а про те, щоб увібрати сиру силу хижака, зберігши дисципліну й рівновагу."},sec={{t="Трофей Списозуба",b="Ішамугале бояться по всій центральній савані як найлютішого з живих сонцелускатих рапторів — верховного хижака, що, кажуть, убиває з чистої хижацької пристрасті, а не з голоду. Виманений на відкрите місце свіжим м'ясом жеври біля всохлого дерева на північний захід від Раджета, звір не знає пощади. Відтяте величезне ікло доводить мисливським наставникам Орди, що мандрівник здолав не просто звіра, а саму несамовиту лють рівнин."},{t="Урок поміркованості",b="Коли ікло приносять Джорнові Скайсіру в Табір Тауражо, у ньому бачать значно більше, ніж кістку й кров. Для тауренів табору здобуте ікло Ішамугале передає люту силу хижака мисливцеві, що його здолав. А справжнє випробування, яке настає далі, — поміркованість: приборкати цю дику лють, а не дати їй заволодіти душею мисливця."}},faq={{q="Що таке Ікло Ішамугале?",a="Це трофей із тіла Ішамугале — сумнозвісного сонцелуского раптора на прізвисько «Списозуб», що никає Пустками.",al={"зуб ішамугале","ікло списозуба","ікло раптора пустищ"}},{q="Кому потрібне Ікло Ішамугале?",a="Ікло приносять Джорну Скайсіру в Табір Тауражо в межах мисливських випробувань, які починаються в Серґри Даркторн на Перехресті.",al={"кому віддати ікло ішамугале","здати ікло ішамугале","куди ікло ішамугале"}},{q="Як знайти звіра Ішамугале?",a="Ішамугале не блукає відкрито. Мисливці мусять убити свіжу жевру й покласти її тушу біля мертвого дерева на північний захід від Раджета, щоб виманити раптора зі схованки.",al={"як викликати ішамугале","прикликати ішамугале","де ішамугале"}},{q="Що для тауренів означає здобуте ікло?",a="За словами Джорна Скайсіра, трофей символізує, що легендарна сила Ішамугале тепер живе в мисливцеві, — і той мусить нести тягар користуватися нею стримано й шляхетно.",al={"що означає ікло","обряд мисливців тауренів ішамугале"}}},fp="17,251,20.447.0,22.346.1,26.117.0,28.134.0,34.161.0,52.197.0"}
P.entries["item:ivar-s-head"] = {n="Голова Івара",s="Голова Івара — моторошний доказ знищення ненажерливого гуля Івара Мерзенного в Срібноліссі. Її шукає скрадачка смерті Рейн Йорік, щоб її поранений брат Квінн міг безпечно одужати.",h="Голова Івара — моторошний доказ знищення ненажерливого гуля Івара Мерзенного в Срібноліссі.",kw={"голова івара","івар мерзенний","гуль","рейн йорік","квінн йорік","срібнолісся"},ang={["faction:Horde"]="Знищуючи свавільні рештки Погибелі на кшталт Івара, ви захищаєте гінців Орди, що йдуть північним Срібноліссям до Гробниці.",["race:Undead"]="Для розвідників-Відступників дикі гулі — бездумна напасть, що зриває військову розвідку й загрожує ще кволій безпеці Лордерона."},sec={{t="Відтята загроза",b="Розвідуючи північне Срібнолісся за наказом Верховного Екзекутора Гадрека, скрадачі смерті з-поміж Відступників — Рейн і Квінн Йорік — потрапили на покинутому хуторі в засідку дикого гуля, відомого як Івар Мерзенний. Брат і сестра відбилися від потвори, але Квінна в сутичці жорстоко пошматовано. Застрягши на зруйнованому хуторі, поки брат одужував, Рейн не могла лишити Квінна самого, щоб завершити місію. Відтята голова Івара — остаточний доказ того, що звір більше ніколи не тероризуватиме садибу, і Квінн має час одужати під пильним наглядом Рейн."}},faq={{q="Чия це голова?",a="Голова належала Івару Мерзенному — лютому гулеві, що никає покинутим хутором, відомим як Ділянка Івара, на півночі Срібнолісся.",al={"хто такий івар","чия голова івара","що таке івар"}},{q="Навіщо Рейн Йорік голова Івара?",a="Рейн потрібен речовий доказ, що Івара знищено. Її брата Квінна тяжко покалічила ця потвора, і йому треба одужати без страху нової засідки, перш ніж вони зможуть звітувати Верховному Екзекуторові Гадреку.",al={"чому рейн хоче голову","здати голову івара","навіщо вбивати івара"}},{q="Де знайти Івара Мерзенного?",a="Івар Мерзенний ховається в напівзруйнованій стодолі на Ділянці Івара, чатуючи, доки поранені скрадачі смерті втратять пильність.",al={"місце івара","де івар"}}},fp="11,210,16.614.0,19.138.0,38.210.0,30.142.0"}
P.entries["item:iverron-s-antidote-item"] = {n="Протиотрута Іверрона (предмет)",s="Протиотрута Іверрона — тендітний лікувальний напій, який приготувала Діранія Сілвершайн у Тінедолі. Зварена спеціально, щоб знешкодити смертельну отруту тутешніх павуків Вебвуда, суміш дуже нестійка і швидко псується після приготування.",h="Протиотрута Іверрона — тендітний лікувальний напій, який приготувала Діранія Сілвершайн у Тінедолі.",kw={"протиотрута іверрона","протиотрута","діранія сілвершайн","іверрон","вебвуд","павуки","тінедол"},ang={["profession:Herbalism"]="Суміш показує надзвичайну мінливість тутешніх складників Тельдрассила і підкреслює, що деякі трав'яні ліки треба вживати одразу після приготування.",["race:NightElf"]="Для молодих нічних ельфів — шукачів пригод, що починають шлях у Тінедолі, поспіх із цими ліками до Іверрона показує, як громада покладається на швидкі дії та знання трав проти повзучої скверни у вітті Тельдрассила."},sec={{t="Крихкі ліки",b="Виготовлена Діранією Сілвершайн в Алдрассилі, ця протиотрута має побороти сильну отруту, що вразила молодого нічного ельфа Іверрона. Через мінливу природу складників і трав'яних каталізаторів напій зберігається надзвичайно недовго — лише п'ять хвилин після приготування. Гінці мають без зволікань мчати на північ, до печери Вебвуда, щоб доставити суміш, доки вона не перетворилася на нікчемну бовтанку."}},faq={{q="Для чого потрібна Протиотрута Іверрона?",a="Вона зцілює Іверрона від отруйного укусу, якого він зазнав від павуків Вебвуда біля їхньої печери на півночі Тінедолу.",al={"використання протиотрути","що робить протиотрута іверрона"}},{q="Чому протиотрута діє лише обмежений час?",a="Діранія Сілвершайн зауважує, що суміш нестійка й зберігає силу лише п'ять хвилин після приготування. Якщо не дати її вчасно, її цілющі властивості цілком зникають.",al={"чому 5 хвилин","таймер протиотрути","чому вона спливає"}},{q="Хто варить протиотруту?",a="Діранія Сілвершайн, цілителька з нічних ельфів в Алдрассилі в Тінедолі, варить зілля зі складників, зібраних, щоб урятувати Іверрона.",al={"хто зробив протиотруту","хто варить протиотруту"}},{q="Що буде, якщо протиотрута вивітриться?",a="Якщо час сплине, напій зіпсується й більше не подіє. Тоді треба повернутися до Діранії Сілвершайн в Алдрассил по свіжу порцію.",al={"протиотрута спливла","таймер закінчився"}}},fp="25,241,16.463.0,36.122.0,40.199.0,23.146.0,37.151.0"}
P.entries["item:jade-phial"] = {n="Нефритова Пляшечка",s="Нефритова Пляшечка — особливо виготовлена посудина, яку дає друїд — нічний ельф Корітрас Мунрейдж у Доланаарі. Вона призначена безпечно набирати й перевозити священну воду з місячних колодязів Тельдрассила, щоб поповнювати центральний колодязь друїдів у Дарнасусі.",h="Нефритова Пляшечка — особливо виготовлена посудина, яку дає друїд — нічний ельф Корітрас Мунрейдж у Доланаарі.",kw={"нефритова пляшечка","місячний колодязь","корітрас мунрейдж","доланаар","дарнасус","село зоряного вітерця","тельдрассил"},ang={["class:Druid"]="Для молодих друїдів нести Нефритову Пляшечку — ранній урок опіки, що підкреслює: життєва сила місячних колодязів Тельдрассила потребує постійної шани й турботи.",["race:NightElf"]="Місячні колодязі уособлюють тривкий зв'язок між калдореями та Елуною; доглядати їх посудинами на кшталт Нефритової Пляшечки — священний обов'язок кожного нічного ельфа."},sec={{t="Посудина для священних вод",b="Тельдрассил усіяний місячними колодязями, що спрямовують місячні й природні сили, життєво важливі для суспільства нічних ельфів і друїдського служіння. Щоб підтримувати цю злагоду, центральний місячний колодязь, яким послуговуються друїди в Дарнасусі, треба час від часу поповнювати з віддалених колодязів великої гілки. Корітрас Мунрейдж довіряє молодим посвяченим Нефритову Пляшечку — посудину, старанно підготовлену, щоб набирати чисту воду з місячного колодязя біля Села Зоряного Вітерця, не порушуючи її тонкої духовної сили."}},faq={{q="Для чого потрібна Нефритова Пляшечка?",a="Нефритовою Пляшечкою набирають священну воду з місячного колодязя просто за Селом Зоряного Вітерця. Наповнену, її треба повернути Корітрасу Мунрейджу в Доланаар, щоб допомогти поповнити місячний колодязь друїдів у Дарнасусі.",al={"призначення нефритової пляшечки","навіщо мені нефритова пляшечка","що робить нефритова пляшечка"}},{q="Хто дає Нефритову Пляшечку?",a="Корітрас Мунрейдж, друїд нічних ельфів із Доланаара, дає пляшечку шукачам пригод, що проходять обряд, відомий як «Корона Землі».",al={"хто дає нефритову пляшечку","де взяти нефритову пляшечку","нефритова пляшечка корітраса"}},{q="Куди зрештою потрапляє вода з цієї пляшечки?",a="Набрану воду везуть, щоб підтримати й поповнити головний місячний колодязь, який доглядають кенарійські друїди в столиці — Дарнасусі.",al={"куди йде вода колодязя","призначення нефритової пляшечки далі","хто використає воду"}}},fp="10,245,26.506.0,32.226.0,28.148.0,44.166.0"}
P.entries["item:jennea-s-flask"] = {n="Настоянка Дженнеа",s="Настоянка Дженнеа — порожня посудина, яку чарівниця Дженнея Кеннон у Кварталі магів Стормвінда дає майбутнім магам. Її використовують, щоб узяти пробу води з Дзеркального Озера й дослідити збурення в тутешніх силових лініях.",h="Настоянка Дженнеа — порожня посудина, яку чарівниця Дженнея Кеннон у Кварталі магів Стормвінда дає майбутнім...",kw={"настоянка дженнеа","пляшка","дженнея кеннон","дзеркальне озеро","силові лінії","проба води"},ang={["class:Mage"]="Для магів-новачків ця пляшка — одне з перших польових доручень від Святилища Чародія: доказ того, що ви здатні на тонкі таємні дослідження й стеження за стійкістю силових ліній."},sec={{t="Посудина для таємних досліджень",b="Після катастрофічних магічних потрясінь по всьому Азероту природний плин таємних течій зірвався зі своїх давніх русел. У Стормвінді Дженнея Кеннон прагне зрозуміти, як глибоко ці містичні зсуви вплинули на Ліс Елвінн. Вона дає цю просту скляну пляшку перспективним учням і посилає їх на південний захід від воріт столиці набрати свіжої води біля підніжжя водоспаду на Дзеркальному Озері. Наповнена посудина береже тендітну пробу, щоб її можна було принести до Святилища Чародія неушкодженою для таємного аналізу."},{t="На варті вод",b="Головна турбота, що стоїть за цією пляшкою, — безпека людей. Якщо хиткі силові лінії почнуть просочувати магічну скверну в Дзеркальне Озеро, довколишня природа й кожен, хто п'є з його вод, можуть зазнати дивних чи шкідливих недуг. Чиста проба в пляшці Дженнеї дає магам Стормвінда змогу виявити незримий магічний осад, перш ніж отруєні течії непомітно розповзуться околицями."}},faq={{q="Для чого потрібна пляшка Дженнеї?",a="Це порожня посудина, яку вам дають, щоб набрати пробу води біля водоспаду на Дзеркальному Озері в Лісі Елвінн.",al={"призначення пляшки","що робить пляшка","використання пляшки"}},{q="Хто дає цю пляшку?",a="Її дає Дженнея Кеннон — наставниця магів у Святилищі Чародія в Стормвінді.",al={"хто дає пляшку","джерело пляшки дженнеї"}},{q="Навіщо Дженнеї вода з Дзеркального Озера?",a="Недавні магічні зіткнення порушили потоки магії по всьому світу. Дженнея боїться, що ці блукаючі течії просочуються в природні води Лісу Елвінн, — а це загрожує кожному, хто п'є з озера.",al={"чому вода дзеркального озера","навіщо проба води"}},{q="Де наповнити пляшку?",a="Пляшку треба віднести до підніжжя водоспаду, що спадає в Дзеркальне Озеро, на південний захід від головної брами Стормвінда в Лісі Елвінн.",al={"де наповнити пляшку","місце пляшки","місце озера"}}},fp="14,219,28.557.0,19.431.0,32.114.0,25.104.0,44.206.0,28.147.0"}
P.entries["item:jitters-completed-journal"] = {n="Завершений Щоденник Джиттерса",s="Завершений Щоденник Джиттерса — рукописна оповідь про похмурі трагедії Сутінколісся, зокрема про різанину на фермі Свена Йорґена. Боячись помсти, відлюдний Тремтій віддає дописаний текст, щоб очистити своє ім'я й пролити світло на зловісні сили, що тероризують край.",h="Завершений Щоденник Джиттерса — рукописна оповідь про похмурі трагедії Сутінколісся, зокрема про різанину на...",kw={"завершений щоденник","тремтій","свен йорґен","морбент фел","єпископ фартінґ","собор світла"},ang={["class:Priest"]="Доставивши щоденник Єпископові Фартінґу до Собору Світла, жерці стають на службу очищенню від нечестивої скверни за допомогою святих реліквій.",["faction:Alliance"]="Щоденник — суворе нагадування про те, як глибоко Сутінколісся поринуло в небезпеку, поки провід Стормвінда зайнятий іншим."},sec={{t="Сповідь боягуза",b="Коли напали на ферму Свена, Тремтій утік у паніці, покинувши недописаний щоденник серед руїн. Завершений щоденник заповнює прогалини того жахливого дня: у ньому розповідається, як таємничі темні вершники вирізали родину Свена. Тижнями, переховуючись у Сутінколіссі, Тремтій знаходив розраду лише в цих записах. Він охоче віддає дописану книгу — йому конче треба пояснити, що сталося насправді, і він сподівається, що записана правда вбереже його від лютого гніву Свена."},{t="Розплутуючи темряву",b="Щоденник не лише вгамовує давнє горе: прочитавши його, Свен розповідає, що бачив, як вершники в чорних плащах розмовляли з чарівником Морбентом Фелом у Покинутому Ряду. Свен передає завершений рукопис із подорожніми на північ, до Собору Світла в Стормвінді. Там Єпископ Фартінґ читає слова Тремтія, щоб збагнути мерзенну скверну, що гноїться в Сутінколіссі, і з допомогою цих одкровень створює святу зброю, здатну пробити темні захисні чари Фела."}},faq={{q="Чому Тремтій віддав свій щоденник?",a="Тремтій утік із ферми Свена під час нападу й покинув там неповний щоденник. Завершений варіант він віддав шукачам пригод, щоб ті віднесли його Свенові, — сподіваючись, що повна правда його виправдає й убереже від Свенової запальної вдачі.",al={"чому тремтій віддає щоденник","щоденник тремтія","чому тремтій це написав"}},{q="Що щоденник відкриває про ферму Свена?",a="У ньому — повна розповідь Тремтія як очевидця трагедії на фермі Свена Йорґена, що заповнює прогалини незавершеного щоденника.",al={"що сталося на фермі свена","напад на родину свена","темні вершники ферма свена"}},{q="Хто такий Морбент Фел і як він пов'язаний зі щоденником?",a="Морбент Фел — некромант, що живе на Покинутому Ряду. Щоденник спонукає Свена поділитися відомостями, які спрямовують розслідування до нього.",al={"зв'язок морбента фела","хто такий морбент фел","чаклун самотній роу"}},{q="Чому щоденник несуть до Стормвінда?",a="Свен велить шукачам пригод віднести щоденник Єпископові Фартінґу в Собор Світла. Стормвінд майже покинув Даркшир напризволяще, тож мудрість і свята наука Фартінґа потрібні, щоб приготувати зброю, яка проб'є магічні обереги Морбента Фела.",al={"чому до єпископа фартінга","віднести щоденник до собору","щоденник шукання мудрості"}}},fp="26,289,21.483.1,23.449.1,36.244.0,47.134.1,58.143.1,38.265.1"}
P.entries["item:johaan-s-findings"] = {n="Висновки Йогаана",s="Висновки Йогаана — в'язка дослідницьких записів Аптекаря Йогаана з Брілла. Довірені гінцеві, що прямує на південь, ці нотатки передають Аптекареві Ренферрелу в Гробниці новітні алхімічні здобутки з Галявин Тірісфалю.",h="Висновки Йогаана — в'язка дослідницьких записів Аптекаря Йогаана з Брілла.",kw={"висновки йогаана","аптекар йогаан","аптекар ренферрел","брілл","нова чума","королівське аптекарське товариство"},ang={["faction:Horde"]="Несучи дослідження на південь, мандрівник ніби закінчує школу знайомих Галявин Тірісфалю й вступає в темніші протистояння Срібнолісся.",["race:Undead"]="Ці висновки відбивають єдину рушійну мету Королівського Аптекарського Товариства — створити Нову Чуму, обіцяну Темній Леді."},sec={{t="Листування аптекарів",b="Королівське Аптекарське Товариство працює під невпинним тиском Леді Сильвани Віндраннер, яка вимагає створити Нову Чуму, здатну знищити і живих, і Погибель. Дослідники розпорошені по спірних руїнах Лордерона, тож вкрай важливо підтримувати обмін відомостями між заставами. Аптекар Йогаан зводить свої нотатки з місцевих випробувань у Бріллі й відсилає їх на південь Аптекареві Ренферрелу, який керує роботою товариства з Гробниці в Срібноліссі. Ці записи — лише невеличка частка спільних зусиль Товариства вдосконалити свої смертоносні зілля."}},faq={{q="Що таке Висновки Йогаана?",a="Це пакунок алхімічних нотаток і досліджень, які зібрав Аптекар Йогаан у Бріллі. У паперах описано його недавні випробування й досліди в Галявинах Тірісфалю.",al={"висновки йогаана","що таке висновки йогаана","дослідження йогаана"}},{q="Хто має отримати цей предмет?",a="Висновки адресовано Аптекареві Ренферрелу — старшому членові Королівського Аптекарського Товариства в Гробниці на півночі Срібнолісся.",al={"хто отримує висновки йогаана","куди нести висновки йогаана","доставка ренферрелу"}},{q="Навіщо аптекарі діляться цими дослідженнями?",a="Королівське Аптекарське Товариство покладається на обмін знаннями між своїми розпорошеними дослідниками, щоб пришвидшити роботу. Сильвана Віндраннер вимагає швидко створити Нову Чуму, тож дослідникам у Срібноліссі конче треба знати про відкриття, зроблені в Тірісфалі.",al={"навіщо ділитися висновками","призначення висновків йогаана","дослідження королівського аптекарського товариства"}},{q="Хто написав ці документи?",a="Аптекар Йогаан — алхімік Королівського Аптекарського Товариства, що працює біля шибениці в Бріллі. Він проводить досліди на місцевих зразках, щоб наблизити алхімічні цілі Відступників.",al={"хто такий аптекар йогаан","хто це написав","аптекар йогаан"}}},fp="17,238,25.584.0,26.165.0,37.157.0,55.282.0,26.186.0"}
P.entries["item:johaan-s-special-drink"] = {n="Особливий Напій Йогаана",s="Особливий Напій Йогаана — смертельне вариво, приготоване Аптекарем Йогааном у селищі Брілл. Замаскована під звичайний трунок, суміш слугує польовим випробуванням чуми, яку розробляє Королівське Аптекарське Товариство.",h="Особливий Напій Йогаана — смертельне вариво, приготоване Аптекарем Йогааном у селищі Брілл.",kw={"особливий напій йогаана","аптекар йогаан","отрута","королівське аптекарське товариство","таверна шибеничний кінець","брілл"},ang={["race:Dwarf"]="Вариво відкриває похмуру долю дворфських розвідників, що підійшли надто близько до Галявин Тірісфалю, де бранців використовують як лабораторних піддослідних.",["race:Undead"]="Для Відступників доставка варива Йогаана — практичне служіння Королівському Аптекарському Товариству й великим задумам Леді Сильвани проти живих."},sec={{t="Отруйне вариво",b="Зварений у казанах Брілла, Особливий Напій Йогаана — геть не корчемний трунок. Аптекар Йогаан готує його, переганяючи різні отруйні складники й місцеві реагенти в один напій, призначений саме для перевірки заразності на живому організмі. Переданий нібито для того, щоб угамувати спрагу бранця, він утілює невідступне прагнення аптекарів Відступників викувати зброю, достатньо потужну, щоб здійснити задуми Сильвани Віндраннер щодо Азерота."},{t="Випробування в підвалі",b="Напій знаходить свого адресата в брудному підвалі під Таверною «Шибеничний Кінець», який Вартові Смерті використовують як тимчасову камеру для заблукалих непроханих гостей. Коли його пропонують полоненому дворфу-горянину, що знемагає в кайданах, спраглий в'язень жадібно п'є, маючи його за грубий ель. Вариво діє миттєво: дворф помирає на місці, і Королівське Аптекарське Товариство переконується, що його найновіший штам швидко гасить живих жертв."}},faq={{q="Що таке Особливий Напій Йогаана?",a="Це смертоносне вариво, яке створив Аптекар Йогаан у Бріллі. Його подають як питво, але в ньому штам чуми, над якою працюють Відступники, — щоб перевірити, як вона вбиває живих.",al={"що таке напій йогаана","напій йогаана","що це за річ"}},{q="Кому дають цей напій?",a="Напій несуть у погріб Таверни «Шибеничний Кінець» у Бріллі й дають Полоненому Горянинові, якого схопили місцеві Вартові Смерті.",al={"хто п'є напій","кому віддати напій","ціль напою"}},{q="Що стається, коли хтось його вип'є?",a="В'язень випиває рідину, чекаючи звичайних корчемних помиїв, щоб утамувати спрагу, — і миттю падає мертвий від лютої отрути варива.",al={"чи дворф помре","дія напою","що він робить"}},{q="Навіщо Аптекар Йогаан робить цей напій?",a="Аптекар Йогаан випробовує нову чуму Королівського Аптекарського Товариства. Полонений дворф стає для нього мимовільним живим піддослідним, щоб побачити, наскільки дієво суміш обриває смертне життя.",al={"чому йогаан зробив напій","мотив аптекаря йогаана","чому випробовувати чуму"}}},fp="22,224,12.487.0,16.468.1,31.220.0,26.159.0,36.143.1,43.211.0"}
P.entries["item:jordan-s-ore-shipment"] = {n="Постачання Руди Джордана",s="Постачання Руди Джордана — скриня очищеного сплаву, призначена для коваля Джордана Стілвелла. Вантаж ішов до Айронфорджа з Багнокраю, але в північно-східних пагорбах Лох Модану його перехопили й пограбували огри Мо'ґрош.",h="Постачання Руди Джордана — скриня очищеного сплаву, призначена для коваля Джордана Стілвелла.",kw={"постачання руди джордана","джордан стілвелл","бейлор стоунгенд","огри","мо'ґрош","сплав","паладин"},ang={["class:Paladin"]="Відібрати цей викрадений сплав в огрів Мо'ґрош — важливий крок у дорученні Джордана Стілвелла, яким ви доводите свою відданість під час Випробування праведності.",["profession:Blacksmithing"]="Особливий сплав Бейлора Стоунгенда — зразок вишуканої дворфійської металургії, настільки цінний, що Джордан Стілвелл відмовився від будь-якої звичайної заміни."},sec={{t="Перехоплений вантаж",b="Цей особливий сплав викував дворф Бейлор Стоунгенд, і його обіцяли Джорданові Стілвеллу для ковальської роботи. Коли валка з припасами перетинала гори на південь, з Багнокраю до Лох Модану, на неї люто напали огри Мо'ґрош. Вантаж затягли до огрячої твердині в нетрях, поранені охоронці так і сконали від ран, а ковальська справа Джордана стала — доки якийсь шукач пригод не вирве сплав із лап звірюк."}},faq={{q="Що в цьому постачанні?",a="У постачанні — особливий сплав, який виготовив дворф Бейлор Стоунгенд і пообіцяв ковалеві Джорданові Стілвеллу для його роботи з металом в Айронфорджі.",al={"що в постачанні джордана","яка це руда","вміст руди джордана"}},{q="Хто вкрав Постачання Руди Джордана?",a="Огри Мо'ґрош напали на караван, що йшов на південь із Багнокраю, вирізали охорону й потягли ящики на свої землі на північний схід від озера.",al={"хто вкрав постачання","хто його вкрав","огри руда"}},{q="Хто такий Бейлор Стоунгенд?",a="Бейлор Стоунгенд — дворф-ремісник із Лох Модану й давній друг Джордана Стілвелла. Він улаштував відправлення сплаву, доки караван не захопили огри.",al={"бейлор стоунгенд","хто такий бейлор"}},{q="Чому це постачання важливе для паладинів?",a="Паладини, що проходять «Тест Праведності», шукають цей сплав, щоб допомогти Джорданові Стілвеллу викувати освячену зброю Світла.",al={"руда для паладинів","іспит праведності руда","чому паладинам це потрібно"}}},fp="21,227,20.473.0,28.154.0,32.186.0,24.167.0,43.131.0"}
P.entries["item:jordan-s-refined-ore-shipment"] = {n="Постачання Очищеної Руди Джордана",s="Постачання Очищеної Руди Джордана — ящик високоякісного металу, підготовлений спеціально для коваля Джордана Стілвелла. Здобутий у межах священних випробувань паладина, він дає необхідну сировину, щоб викувати святу зброю доброчесності.",h="Постачання Очищеної Руди Джордана — ящик високоякісного металу, підготовлений спеціально для коваля Джордана...",kw={"очищена руда","джордан стілвелл","паладин","випробування праведності","ковальство","айронфордж","самоцвіт кор"},ang={["class:Paladin"]="Здобути цю партію очищеної руди — перевірка терпіння й відданості паладина, одне з практичних випробувань на шляху до створення символічної зброї Світла.",["profession:Blacksmithing"]="Кожен ремісник розуміє: для майстерного кування потрібні бездоганні, ретельно підготовлені зливки, а не сира руда з поля."},sec={{t="Матеріали коваля",b="Коли Джордан Стілвелл узявся викувати зброю, гідну відданого паладина, звичайна сировина не годилася. Ковалеві знадобився набір рідкісних і вибагливих складників: Очищений Самоцвіт Кор, міцна дубова деревина Вайтстоуну, його власний загублений ковальський молот і особлива партія очищеної руди. Цей вантаж — металева основа для тієї священної праці, доставлена до Айронфорджа, щоб завершити Випробування праведності."}},faq={{q="Для чого Постачання Очищеної Руди Джордана?",a="Очищену руду доставляють Джорданові Стілвеллу під Айронфорджем: це один із чотирьох головних складників, потрібних, щоб викувати майстерну зброю для паладинів, які проходять «Тест Праведності».",al={"призначення очищеної руди","що джордан робить з рудою","використання постачання руди"}},{q="Хто готує очищену руду?",a="Постачання влаштовує Бейлор, який наглядає за очищенням і відправленням особливого металу, потрібного Джорданові Стілвеллу.",al={"хто робить очищену руду","руда бейлора","хто очищає руду джордана"}},{q="Чому Джорданові потрібне саме це постачання?",a="Джордан Стілвелл хоче викувати символ паладинства й Світла, а для цього потрібні матеріали, кращі за звичайні обрізки з кузні. Особливо оброблений метал забезпечує клинку чи бойку молота рівновагу й чистоту, гідні святого лицаря.",al={"чому особлива руда","чому джордан не використає залізо","причина очищеної руди"}}},fp="29,233,19.437.0,47.185.0,29.133.0,44.252.0"}
P.entries["item:jordan-s-smithing-hammer"] = {n="Ковальський Молот Джордана",s="Ковальський Молот Джордана — дорога родинна реліквія, яку коваль-людина Джордан Стілвелл успадкував від батька. Повернути його з проклятих зал Фортеці Шадовфенг конче потрібно, щоб викувати святу зброю, освячену Світлом.",h="Ковальський Молот Джордана — дорога родинна реліквія, яку коваль-людина Джордан Стілвелл успадкував від...",kw={"ковальський молот","джордан стілвелл","фортеця шадовфенг","срібнолісся","реліквія","паладин","ковальство"},ang={["class:Paladin"]="Повернення спадкового молота — частина тяжких випробувань праведності, яка доводить рішучість паладина вирушити в небезпечні землі по знаряддя святого ремесла.",["profession:Blacksmithing"]="Кожен коваль розуміє сентиментальний і практичний зв'язок між майстром та молотом, що перейшов до нього від предків."},sec={{t="Спадок майстра",b="Сторонньому Ковальський Молот Джордана може здатися звичайним ковальським залізом, але для Джордана Стілвелла він утілює і спадщину, і призначення. Успадкований від батька, цей інструмент — осердя Джорданової самості як майстра кузні біля Айронфорджа. Хтозна-як опинившись за покинутими кам'яними стінами Фортеці Шадовфенг у Срібноліссі, він має бути повернений, перш ніж Джордан зможе взятися за свій шедевр — священну зброю, гідну святого захисника."}},faq={{q="Де знайти Ковальський Молот Джордана?",a="Молот лежить за проклятими мурами Фортеці Шадовфенг серед темних лісів Срібнолісся. Паладини, що проходять «Тест Праведності», мусять вирушити в захоплену фортецю, щоб його повернути.",al={"місце молота","де молот джордана","де знайти ковальський молот джордана"}},{q="Чому цей молот такий важливий для Джордана Стілвелла?",a="Молот дістався Джорданові від батька. Він дуже дорогий йому як пам'ять, і саме ним Джордан хоче викувати свій найкращий витвір — святу зброю Світла.",al={"чому джордан хоче молот","історія молота джордана стілвелла"}},{q="Для чого молот, коли його повернуто?",a="Коли молот разом із деревиною, рудою й самоцвітом приносять Джорданові під браму Айронфорджа, він кує ним величну священну зброю, щоб нагородити паладина, який йому допоміг.",al={"що молот виготовляє","іспит праведності молот"}}},fp="24,242,20.457.0,42.205.0,51.177.0,43.177.0"}
P.entries["item:kadrak-s-flag"] = {n="Прапор Кадрака",s="Прапор Кадрака — знамено Орди, яке дає розвідник Кадрак на кордоні між Пустками та Ашенвалем. Встромлений просто в Лігві Кігтя після загибелі Ключниці Ринтаріель, він стає недвозначним попередженням нічним ельфам і дріадам Піка Кам'яного Кігтя.",h="Прапор Кадрака — знамено Орди, яке дає розвідник Кадрак на кордоні між Пустками та Ашенвалем.",kw={"прапор кадрака","кадрак","лігво кігтя","ринтаріель","пік кам'яного кігтя","знамено орди"},ang={["faction:Horde"]="Застромити це знамено глибоко в Лігві Кігтя — зухвале утвердження сили на чужій землі, що доводить: у відповідь на провокацію Орда вдарить просто по святилищах нічних ельфів.",["race:NightElf"]="Осквернення Лігва Кігтя криваво-червоним знаменом Орди — пряма образа й провокація проти захисників Піка Кам'яного Кігтя."},sec={{t="Знак непокори",b="На кордонах Калімдору напруга сягає краю: гінці й вартові Альянсу раз у раз перевіряють межі земель, які тримає Орда. Коли розшифрований сувій викриває листування дріади Ринтаріель, Ключниці Лігва Кігтя, Кадрак вирішує, що вбити її — замало. Він дає цей багряний стяг, щоб його встромили глибоко в Лігві на вершині Кам'яного Кігтя. Застромивши знамено Орди в одній зі священних гірських твердинь нічних ельфів, Кадрак прагне передати ясне послання: на вторгнення в Пустки відповідатимуть сміливою відплатою на землі Альянсу."}},faq={{q="Для чого потрібен Прапор Кадрака?",a="Прапор встромлюють у Лігві Кігтя на вершині Піку Кам'яного Кігтя, коли вбито Рінтаріель Ключника. Стяг Орди в їхній твердині застерігає нічних ельфів не посилати більше розвідників і гінців у Пустки.",al={"призначення прапора","навіщо ставити прапор","що робить прапор"}},{q="Хто дає прапор?",a="Кадрак, орк-розвідник на прикордонній сторожі між північчю Пусток і Ашенвалем, вручає стяг шукачам пригод Орди в межах свого походу, щоб убезпечити край.",al={"хто дає прапор","де взяти прапор","місце кадрака"}},{q="Де встромлюють прапор?",a="Стяг встромлюють у Лігві Кігтя — печерному святилищі на західних схилах Піку Кам'яного Кігтя в Горах Кам'яного Кігтя.",al={"де ставити прапор","місце прапора","місце прапора в лігві кігтя"}},{q="Хто така Рінтаріель?",a="Рінтаріель — дріада, Ключник Лігва Кігтя. Вона спрямовує гінців, що перетинають землі Орди, доки Кадрак не перехоплює її послання й не наказує її вбити.",al={"дріада рінтаріель","хто така рінтаріель","хранителька ключів"}}},fp="13,282,18.604.0,31.234.0,23.182.0,26.140.0,18.191.0"}
P.entries["item:keg-of-shindigger-stout"] = {n="Барило Темного Пива Шіндіґера",s="Барило Темного Пива Шіндіґера — бочка міцного дворфійського пива, яке варять і стережуть стрільці й солдати гарнізону Дун Ґарока. Королівське Аптекарське Товариство в Таррен Міллі прагне його не заради вечірнього келиха, а як підступний засіб доставки щойно створених чум.",h="Барило Темного Пива Шіндіґера — бочка міцного дворфійського пива, яке варять і стережуть стрільці й солдати...",kw={"барило темного пива шіндіґера","темне пиво","дун ґарок","аптекар лайдон","еліксир агонії","таррен мілл"},ang={["faction:Horde"]="Удар по Дун Ґароку руйнує небезпечний військовий плацдарм Альянсу, затиснутий просто між Горами Альтерак і Аратійським нагір'ям.",["race:Undead"]="Для Відступників викрадення барила цінного дворфійського пива — суто практична алхімія: алкоголь маскує запах і смак смертоносних сумішей, створених для Леді Сильвани."},sec={{t="Улюблений напій дворфів",b="Дун Ґарок — грізна дворфійська твердиня на південному сході Передгір'я Гілсбреда, яку завзято утримують дворфи Айронфорджа. У її укріплених казармах і їдальнях кремезні захисники діляться барилами Темного Пива Шіндіґера, щоб перетерпіти холод і виснажливу облогу місцевих ворогів. Пиво міцне, і є його вдосталь, тож воно — основа щоденного виживання гарнізону."},{t="Отруйна посудина Аптекаря Лайдона",b="Дворфи вважають Темне Пиво Шіндіґера чесною нагородою після бою, а Аптекар Лайдон у Таррен Міллі бачить у ньому ідеальний переносник жаху. Розробляючи зловісний Еліксир Агонії для Відступників, Лайдон відмовляється випробовувати свою смертоносну формулу на звірах. Натомість він шукає непочате барило пива, щоб підмішати в нього своє вариво й приготувати отруєний частунок для полонених людських фермерів, яких тримають у Таррен Міллі."}},faq={{q="Для чого потрібне Темне Пиво Шіндіґера?",a="Аптекар Лайдон у Таррен Міллі хоче отримати барило, щоб випробувати свій щойно вдосконалений Еліксир Агонії. Замість марнувати люту отруту на лабораторних тварин він має намір отруїти дворфський ель і влаштувати смертельне польове випробування на розумних істотах.",al={"навіщо темне пиво шіндіґера","призначення темного пива шіндіґера","що лайдон робить з барилом"}},{q="Де знайти Барило Темного Пива Шіндіґера?",a="Барила зберігаються глибоко в дворфській фортеці Дун Ґарок на південному сході Передгір'я Гілсбреда — зазвичай у трапезних і нижніх казармах, де живе дворфська піхота.",al={"місце барила","де темне пиво шіндіґера","знайти пиво"}},{q="Хто варить Темне Пиво Шіндіґера?",a="Його варять і тримають дворфи Дун Ґарока, що утримують добре укріплений гарнізон у Передгір'ї Гілсбреда від імені Айронфорджа.",al={"хто варить темне пиво шіндіґера","чи це дворфський ель"}},{q="Чому Аптекар Лайдон не зварить для випробування власного трунку?",a="Лайдон просить барило, що вже зберігається в Дун Ґароку, щоб використати цей ель для досліду; у завданні не сказано, що він сам варить трунок.",al={"чому красти дворфське пиво","чому пиво дан ґарока"}}},fp="23,294,18.408.0,32.416.1,34.255.0,45.234.0,27.139.0,63.145.0"}
P.entries["item:ken-zigla-s-draught"] = {n="Трунок Кен'зіґли",s="Трунок Кен'зіґли — сильне, бридке на смак лікувальне зілля, яке готує Кен'зіґла в Горах Кам'яного Кігтя. Його створено, щоб повернути тяжко пораненим досить сил рухатися, не стікаючи кров'ю.",h="Трунок Кен'зіґли — сильне, бридке на смак лікувальне зілля, яке готує Кен'зіґла в Горах Кам'яного Кігтя.",kw={"трунок кен'зіґли","кен'зіґла","доґран","табір тауражо","гостромани","чорнокнижники","сукуб"},ang={["class:Warlock"]="Здобути й доставити цей трунок — неодмінний крок у випробуваннях, щоб викликати й підкорити сукуба: так чорнокнижник доводить свою винахідливість і вміння знаходити шлях Пустками.",["faction:Horde"]="Поки в Таборі Тауражо бракує людей через фуражирські патрулі, трунок — єдина надія для агента, схопленого за лініями ворожих шипогривів."},sec={{t="Гіркі ліки",b="Це сильне вариво Кен'зіґли з Гір Кам'яного Кігтя — невідкладний засіб для тих, хто на порозі смерті. Трунок надзвичайно міцний, і його треба ретельно відмірювати: якщо випити більше половини дози за раз, хворий може стекти кров'ю, бо кров рине жилами надто бурхливо. Половина дози дає досить сирої снаги, щоб рушити з місця й утекти від неминучої небезпеки, а решту треба лишити, доки тіло не оговтається після цілої ночі відпочинку."},{t="Милосердя в Пустках",b="Трунок відіграє важливу роль у пошуках Доґрана — агента, якого схопили й катували шипогриви на північ від Табору Тауражо. Чорнокнижники Орди, що шукають знак пожирача душ, несуть цю гірку суміш просто у вороже стійбище Гостроманів. Випивши її, Доґран має рівно стільки сили, щоб пошкандибати геть від своїх катів, хоча тяжкі рани назавжди позбавили його змоги володіти кінцівками."}},faq={{q="Для чого потрібен Трунок Кен'зіґли?",a="Це сильний цілющий напій, що повертає сили вмирущим чи тяжко пораненим. Якщо дати його правильно, поранений має досить снаги, щоб звестися на ноги й утекти з полону, не стікши кров'ю на смерть.",al={"що робить трунок кен'зіґли","призначення трунку","навіщо мені трунок кен'зіґли"}},{q="Хто готує трунок?",a="Його варить Кен'зіґла — аптекарка чи травниця з Гір Кам'яного Кігтя, яка приготувала трунок заздалегідь, знаючи, що хтось прийде просити допомоги для Доґрана.",al={"хто варить трунок","хто така кен'зіґла","місце кен'зіґли"}},{q="Чому трунок треба пити лише половину за раз?",a="Суміш надзвичайно сувора для тіла. Половина порції дає рівно стільки снаги, щоб рухатися без сильної кровотечі, а другу половину треба відкласти, доки хворий не відпочине ніч, — інакше напруга може стати смертельною.",al={"як приймати трунок кен'зіґли","половина дози","інструкція до трунку"}},{q="Хто отримує трунок?",a="Зрештою його приносять Доґранові — агентові, якого тримають у полоні тяжко пораненим у таборі шипогривів на північ від Табору Тауражо в Пустках.",al={"хто п'є трунок","хто такий доґран","куди доставити трунок"}},{q="Чому по ці ліки посилають чорнокнижників?",a="Чорнокнижників Орди, які хочуть прив'язати сукуба, спрямовують до Доґрана: у нього є річ, сповнена глибоких почуттів. Доставити трунок треба, щоб дістатися до нього й здобути те, що потрібно для обряду виклику.",al={"чому чорнокнижникам ліки","завдання сукуби трунок","завдання чорнокнижника кен'зіґла"}}},fp="19,229,15.466.0,20.421.1,37.231.0,22.169.0,50.220.0,25.137.0,48.224.0"}
P.entries["item:khazgorm-s-journal"] = {n="Щоденник Казґорма",s="Щоденник Хазґорма — особистий польовий записник Шукача Хазґорма, очільника дворфійських розкопок Айронфорджа в Бель Модані на півдні Пусток. У ньому описано загарбницьку діяльність Ліги Дослідників на землях, які вважає своїми тауренське плем'я Стоунспайр.",h="Щоденник Хазґорма — особистий польовий записник Шукача Хазґорма, очільника дворфійських розкопок Айронфорджа...",kw={"щоденник хазґорма","шукач хазґорм","бель модан","ліга дослідників","ґанн стоунспайр","стоунспайр"},ang={["faction:Horde"]="Здобувши цю книгу, ви допомагаєте Ґаннові Стоунспайру захищати Калімдор від загарбницьких експедицій Альянсу, що просуваються глибоко на суверенні землі Орди.",["race:Tauren"]="Щоденник — відчутний доказ черствості загарбників з Айронфорджа, які підривали священні землі предків, не зважаючи на плем'я Стоунспайр."},sec={{t="Літопис руйнування",b="Щоденник належить Шукачеві Хазґорму, який керує важкими машинами й підривними роботами, що врізаються в пагорби на півдні Пусток. Ці записи аж ніяк не схожі на ідилічні пошуки знань, про які говорить Ліга Дослідників: вони свідчать про безжальні розкопки, що вигнали плем'я Стоунспайр. Таурени намагалися дійти мирної згоди, але їм відмовили, тож щоденник — цінний воєнний трофей для Ґанна Стоунспайра, що прагне зрозуміти й розібрати присутність дворфів на своїй батьківщині."},{t="Зміна тактики",b="Знайдена серед решток Хазґорма поміж наметів і колон розкопок, книга дає Ґаннові важливе розуміння будови експедиції дворфів, її обладнання та слабких місць. Вивчивши особисті записи шукача, Ґанн може перейти від простого відганяння робітників до прицільних диверсій проти машин розкопок, і щоденник стає переломним моментом у боротьбі за Бель Модан."}},faq={{q="Кому належить щоденник?",a="Щоденник належить Шукачеві Хазґорму — одному з керівників дворфських розкопок Айронфорджа на місці розкопок у Бель Модані на півдні Пусток.",al={"чий щоденник","казґорм","рудознавець казґорм"}},{q="Навіщо Ґаннові Стоунспайру ця книга?",a="Ґанн Стоунспайр хоче дослідити щоденник, щоб пізнати задуми й таємниці дворфів-загарбників, які прогнали його плем'я, і з нотаток самого Хазґорма спланувати нові удари по табору в Бель Модані.",al={"навіщо ґанну щоденник","завдання ґанна щоденник","книга повернення ґанна"}},{q="Де знайти щоденник?",a="Щоденник носить сам Шукач Хазґорм, якого можна знайти серед наметів і кам'яних стовпів діючих розкопок трохи на південь від Бель Модану.",al={"де щоденник казґорма","знайти щоденник казґорма","місце казґорма"}},{q="Що щоденник відкриває про дворфів?",a="Він показує менш учений бік Ліги Дослідників: їхня гонитва за похованими реліквіями й спадщиною титанів часто йде просто коштом корінних племен, як-от тауренів Стоунспайр, і супроводжується насильством над ними.",al={"ліга дослідників пустища","таємниці розкопок дворфів","призначення бейл модана"}}},fp="18,272,23.518.0,18.429.1,31.153.0,40.208.0,31.160.0,47.214.0"}
P.entries["item:klaven-mortwake-s-journal"] = {n="Щоденник Клавена Мортвейка",s="Щоденник Клавена Мортвейка — розвідувальне донесення, яке агенти SI:7 здобули у вежі Дефіас на північному сході Вестфолу. Схований у скрині, відправленій із Сутінколісся, він описує таємні спроби Братства зварити алхімічні суміші, здатні оживлювати мертвих.",h="Щоденник Клавена Мортвейка — розвідувальне донесення, яке агенти SI:7 здобули у вежі Дефіас на північному...",kw={"щоденник клавена мортвейка","клавен мортвейк","si:7","матіас шоу","отрути","вестфол"},ang={["class:Rogue"]="Проникнути до вежі й забрати щоденник Мортвейка — випробування для розбійників SI:7: воно перевіряє вміння відмикати замки й скрадатися та відкриває вам мистецтво варіння смертельних отрут.",["faction:Alliance"]="Щоденник дає стормвіндським шпигунам незаперечний доказ того, що повстання Дефіас — це не лише невдоволені робітники, а й зв'язки з тролями-знахарями й алхімічною некромантією."},sec={{t="Моторошна формула",b="SI:7 давно стежила за вежею Дефіас, що височіє на хребтах північного Вестфолу, і помічала дивні вантажі з темного прикордоння Сутінколісся, а з ними — потворних нелюдських вартових. Щоденник, знайдений у найвищій скрині, належав Клавенові Мортвейку й розкриває мету цих поставок. Мортвейк записував алхімічні дослідження про те, як алхіміки, пов'язані з тролями Занзіла у Стренглторні, знайшли спосіб піднімати бездумних неживих трутнів за допомогою особливих отрут і зіль, — і Братство Дефіас прагнуло повторити це для власних лав."},{t="Розвіддані для SI:7",b="Майстер Матіас Шоу, очільник розвідки Стормвінда, поставив повернення щоденника Мортвейка на перше місце, щоб скласти докупи ширшу мережу союзів Братства. Нотатки підтверджують не лише темні досліди з оживлення мертвих, а й незаконну логістичну підтримку, що пов'язує Сутінколісся, Венчурну Компанію та Дефіас. Для розбійників на службі корони здобуття цього темного дослідження стає вирішальним кроком до опанування мистецтва отрут."}},faq={{q="Що таке Щоденник Клавена Мортвейка?",a="Це дослідницький записник Клавена Мортвейка — агента, що працює у вежі Дефіас на північному сході Вестфолу. У ньому нотатки про алхімічну некромантію та незаконні шляхи постачання.",al={"що таке щоденник клавена","щоденник мортвейка","що це за річ"}},{q="Де знайти щоденник?",a="Він замкнений у Скрині Сутінколісся на верхньому поверсі вежі Дефіас на півночі Вестфолу. Її стережуть вартові-нежить, а відімкнути можна лише ключем, забраним в одного з потворних охоронців Клавена.",al={"де знайти щоденник клавена","місце щоденника клавена","місце скрині сутінколісся"}},{q="Які таємниці записано в щоденнику?",a="Текст відкриває, що тролі Занзіла з Долини Стренглторну створили отруйні зілля, здатні підіймати мерців і керувати ними, — смертоносний рецепт, який Братство Дефіас наполегливо намагалося здобути й застосувати.",al={"що написано в щоденнику","таємниці щоденника","отрута занзіла"}},{q="Кому потрібен цей щоденник?",a="Документ просить Майстер Матіас Шоу, очільник розвідувальної служби Стормвінда SI:7, щоб стежити за постачанням Дефіас і навчати агентів корони небезпек і користі бойових отрут.",al={"кому віддати щоденник клавена","кому потрібен щоденник","щоденник матіаса шоу"}}},fp="25,290,18.597.1,21.473.0,34.195.0,27.198.0,44.222.0,23.193.0"}
P.entries["item:kodo-horn"] = {n="Ріг Кодо",s="Роги кодо — міцні природні реагенти, які беруть у звірів, що бродять північними краями Пусток. Для друїдів Кола Кенарія їхня щільна будова дає потрібну міць і силу для дослідних трав'яних сумішей, передусім для цілющих мазей, що лікують отруєних звірів.",h="Роги кодо — міцні природні реагенти, які беруть у звірів, що бродять північними краями Пусток.",kw={"ріг кодо","кодо","тонга рунтотем","цілюща мазь","друїди","пустки"},ang={["class:Druid"]="Для молодих друїдів Орди збирати ці роги — важливий обряд посвяти під наглядом Тонги Рунтотема, що веде до вродженої влади над отрутами природи.",["race:Tauren"]="Таурени глибоко шанують кодо й беруть у них лише з повагою та з певною метою — цього разу, щоб уберегти тендітну природу Пусток."},sec={{t="Реагент рівнин",b="Таурени по всіх Пустках шанують кодо за витривалість і силу, але їхні роги мають і практичну лікувальну цінність. Тонга Рунтотем, що працює на Перехресті, використовує цілі роги, щоб посилити дію своїх трав'яних ліків. Для очищення цих мазей не годяться ні тріски, ні уламки: лише цілі роги, зібрані в дорослих кодо, що блукають посушливими рівнинами, мають досить сили, щоб стати опорою ліків."}},faq={{q="Для чого потрібні Роги Кодо?",a="Тонга Рунтотем разом із Земнокоренем і чистою водою варить із них цілющу мазь. Ця суміш лікує отруєних газелей по всіх Пустках — і це важливий крок у навчанні друїда, що опановує природні засоби від отрут.",al={"призначення рогу кодо","навіщо збирати роги кодо","використання рогу кодо"}},{q="Де збирають ці роги?",a="Їх знімають із кодо Пусток і заблукалих кодо Пусток, що кочують північними просторами Пусток, — зазвичай вони пасуться між Перехрестям і довколишніми чагарниками.",al={"де знайти роги кодо","місце рогу кодо","які кодо дропають роги"}},{q="Чому друїди не можуть брати уламки рогів?",a="Тонга Рунтотем зауважує, що прості відламки й уламки не мають потрібної сили, щоб збалансувати мазь. Ліки вимагають цілих рогів, щоб порції були досить сильні проти лютих отрут.",al={"чому не зламані роги","уламки рогів"}},{q="Чи гідно друїдові полювати на кодо?",a="Так, якщо це служить більшій рівновазі природи. Друїди беруть від землі та її створінь лише те, що потрібно, щоб зцілити більше лихо — як-от загадкове отруєння, що вражає місцеві стада газелей.",al={"друїд полює на кодо","баланс і кодо"}}},fp="9,302,23.435.0,29.253.0,32.187.0,44.204.0,51.214.0"}
P.entries["item:kodo-liver"] = {n="Печінка Кодо",s="Печінка кодо — важкий орган, який добувають у величезних кодо, що бродять рівнинами Пусток. Навряд чи це звичайна страва, але Майстрові Броварства Дрону в Раджеті вона потрібна як важливий складник для бродіння незвичного трогівського елю, рецепт якого він перейняв від мандрівного майстра броварства Ченя Бурештофа.",h="Печінка кодо — важкий орган, який добувають у величезних кодо, що бродять рівнинами Пусток.",kw={"печінка кодо","майстер броварства дрон","трогівський ель","чень бурештоф","раджет","кулінарія"},ang={["profession:Cooking"]="Звичайне м'ясо кодо — основна харчова пайка по всьому центральному Калімдору, а от печінку кодо вважають надто гидкою й смердючою для звичайної кухні біля вогнища, тож її місце в трогівському елі Раджета ще й тому таке сумнозвісне.",["race:Tauren"]="Таурени шанують кожну частину вполюваного кодо, але навіть найдосвідченіші мандрівники рівнин скоса дивляться на гоблінів і чужинців, які перетворюють священні нутрощі кодо на дивакуватий ель у Раджеті."},sec={{t="Дивний броварський складник",b="На великих кодо Пусток полюють здебільшого таурени та мандрівні хижаки — заради міцних шкур і поживного м'яса. Та свіжа печінка кодо має значно химерніше призначення в портовому містечку Раджет. Майстер Броварства Дрон використовує цей орган разом зі слинними залозами громових яструбів і блискавичними залозами, щоб відтворити міцне вариво, якого його навчив Чень Бурештоф, — трогівський ель. Дрон запевняє, що ця незвична суміш має добрячу силу й дарує сміливим мандрівникам ситний напій просто з диких країв центрального Калімдору."}},faq={{q="Для чого потрібна Печінка Кодо?",a="Печінку Кодо доставляють Майстрові Броварства Дрону в Раджет. Він додає її до міцного трогівського елю за рецептом, якого його навчив славетний майстер броварства, пандарен Чень Бурештоф.",al={"призначення печінки кодо","навіщо печінка кодо","для чого печінка кодо"}},{q="З яких істот добувають Печінку Кодо?",a="Її можна вирізати з різних кодо, що бродять відкритою саваною Пусток, — звичайних кодо Пусток, кошлатих, заблукалих і великих кодо, а також рідкісних звірів, як-от Лакота'мані й Бронтус.",al={"де взяти печінку кодо","хто дропає печінку кодо","джерело печінки кодо"}},{q="Навіщо комусь класти в ель звірячі нутрощі?",a="Майстер Броварства Дрон варить за екзотичними й химерними рецептами, які передав йому Чень Бурештоф. У трогівському елі саме сирі нутрощі, як-от печінка кодо й стихійні залози, дають напою славетну міць і неповторний смак — наче удар у щелепу.",al={"чому печінка в елі","печінка кодо в алкоголі"}}},fp="10,290,25.543.0,30.182.0,35.200.0,42.239.0"}
P.entries["item:kodobane-s-head"] = {n="Голова Кодобейна",s="Голова Кодобейна — відтята голова Барака Кодобейна, хитрого ватажка кентаврів-колкарів. Здобута як доказ його смерті, вона потрапляє до орка-воєводи Реґтара Дезґейта як свідчення того, що загрозу кентаврів біля Забутих ставків зламано.",h="Голова Кодобейна — відтята голова Барака Кодобейна, хитрого ватажка кентаврів-колкарів.",kw={"голова кодобейна","барак кодобейн","колкари","кентаври","реґтар дезґейт","забуті озерця"},ang={["faction:Horde"]="Перехрестя Пусток — важлива сухопутна ланка між Оргріммаром і Тандер Блафом; приборкання ватажків кентаврів на кшталт Кодобейна вкрай важливе, щоб караванні шляхи лишалися безпечними.",["race:Tauren"]="Поколіннями кентаври гнали кочових тауренів через увесь Калімдор аж до межі вимирання. Повалити Барака Кодобейна — означає помститися за століття кровопролиття й захистити пасовиська Малгору й Пусток."},sec={{t="Воєнний трофей",b="Кентаври-колкари Пусток споконвіку були розпорошеною, неорганізованою напастю, але піднесення честолюбних воєвод загрожує об'єднати їхні грабіжницькі загони у військо. Барак Кодобейн облаштував свій табір біля буйних вод Забутих ставків, відрізавши доступ до важливих ресурсів оази й нападаючи на довколишні стежки. Реґтар Дезґейт, що стоїть у бункері на захід від Перехрестя, вимагає його відтятої голови як незаперечного доказу, що цей ватажок більше не згуртує своїх жорстоких родичів проти Орди."}},faq={{q="Хто такий Барак Кодобейн?",a="Барак Кодобейн — помітний вождь кентаврів Колкар. На відміну від багатьох своїх свавільних родичів, Барак мав досить хитрощів і поваги, щоб збирати ватаги, і отаборився біля Забутих ставків, щоб утвердити панування Колкар на півночі Пусток.",al={"барак кодобейн","хто такий кодобейн","історія барака"}},{q="Навіщо Реґтарові Дезґейту його голова?",a="Реґтарові Дезґейту доручено вберегти землі Орди в Пустках. Кентаври зазвичай чубляться між собою, тож ватажків, що справді вміють мислити тактично, знищують насамперед. Голова Кодобейна гарантує, що вождь мертвий, а не просто прогнаний.",al={"навіщо голова","голова для реґтара дезґейта","нагорода за кодобейна"}},{q="Де знайти Барака Кодобейна?",a="Барак Кодобейн отаборився біля північної оази, відомої як Забуті ставки, трохи на північний захід від Перехрестя в Пустках.",al={"місце барака","де кодобейн","поява барака"}},{q="Чи смерть Барака спиняє загрозу Колкар?",a="Ні. Барак Кодобейн — лише перший із кількох воєвод, що гуртують Колкар. Його смерть розладнує їхню присутність біля Забутих ставків, але інші ватажки, як-от Вероґ Дервіш і Гезрул Бладмарк, і далі спрямовують напади кентаврів по всіх Пустках.",al={"чи розбито кентаврів","що буде після смерті барака"}}},fp="15,245,15.511.0,23.271.0,41.281.0,30.132.0,42.255.0"}
P.entries["item:kravel-s-crate"] = {n="Ящик Кравела",s="Ящик Кравела — важкий вантаж, який Кравел Колбірд відправляє з Перегонів Міражу в Мерехтливих Низинах. Він призначений для експедиції Несінгварі в Долині Стренглторну й містить особливі мисливські набої, створені, щоб валити найнебезпечнішу дичину джунглів.",h="Ящик Кравела — важкий вантаж, який Кравел Колбірд відправляє з Перегонів Міражу в Мерехтливих Низинах.",kw={"ящик кравела","кравел колбірд","несінгварі","долина стренглторну","набої","перегони міражу"},ang={["class:Hunter"]="У ящику — особливі важкі набої, створені саме для добірних дворфійських мисливських рушниць і призначені для експедицій на велику дичину.",["race:Dwarf"]="Ця доставка — справа суто дворфійська: вона пов'язує оборудки Кравела Колбірда на солончаках зі славетною мисливською ватагою Несінгварі у Східних Королівствах."},sec={{t="Доставка в джунглі",b="Ящик Кравела, який вручає меткий підприємець Кравел Колбірд на Перегонах Міражу, — незавершена угода, що простягається між континентами. Вантаж замовив кілька тижнів тому заможний покровитель-дворф, але доставка так затрималася, що покупець устиг зовсім покинути Калімдор. Не бажаючи втратити прихильність багатого клієнта, який уже сплатив пересилання, Кравел доручає мандрівним шукачам пригод дотягти ящик аж на північ Долини Стренглторну."},{t="Набої особливого калібру",b="Попри непримітний вигляд і кірку соляного пилу, яку він збирає в Мерехтливих Низинах, ящик везе смертоносний вантаж: важкі набої особливого калібру, виготовлені саме для мисливських рушниць. Отримавши їх у таборі експедиції на північ від Ґром'ґола, адресат зауважує, що ці потужні набої дуже цінують мисливці на велику дичину і що без них не вижити серед хижаків, які нишпорять під пологом джунглів."}},faq={{q="Що в Ящику Кравела?",a="Ящик набитий особливими мисливськими набоями. Цей великокаліберний шріт призначений саме для рушниць на велику дичину — щоб валити небезпечних звірів у дикій природі.",al={"що в ящику","вміст ящика","що у ящику кравела"}},{q="Хто надіслав Ящик Кравела?",a="Його надіслав Кравел Колбірд — дворф-торговець, що крутиться серед перегонів і азартних ігор на Перегонах Міражу в Мерехтливих Низинах Тисячі Голок.",al={"хто дав ящик","чий ящик кравела"}},{q="Куди треба доставити ящик?",a="Ящик треба доправити до мисливського табору експедиції Несінґворі на півночі Долини Стренглторну, при річці на північ від Базового Базового Табору Ґром'ґол.",al={"куди доставити ящик","призначення ящика","хто отримує ящик кравела"}},{q="Чому доставка затрималася?",a="Пакунок тижнями йшов до соляних рівнин Тисячі Голок, а за цей час замовник уже зібрався й вирушив у джунглі Долини Стренглторну.",al={"чому затрималися","чому доставка затрималася"}}},fp="14,270,24.473.0,24.405.0,30.174.0,24.158.0,33.152.0,29.176.0"}
P.entries["item:kreenig-snarlsnout-s-tusk"] = {n="Ікло Крініга Гарчоморда",s="Ікло Крініґа Снарлснаута — моторошний мисливський трофей, здобутий у ватажка нападників-шипогривів Гостроманів на півночі Пусток. Відтяте ікло — незаперечний доказ для Торка на Перехресті, що загрозу шляхам постачання Орди знищено.",h="Ікло Крініґа Снарлснаута — моторошний мисливський трофей, здобутий у ватажка нападників-шипогривів...",kw={"ікло крініґа","крініґ снарлснаут","гостромани","шипогриви","торк","перехрестя"},ang={["faction:Horde"]="Обози зі зброєю, провізією й поселенцями з Дуротару — життєва сила поширення Орди в Пустках. Принісши це ікло, ви захищаєте ці важливі артерії.",["race:Orc"]="Трофей із переможеного ватажка — вияв суворої, практичної війни, якій віддають перевагу орки Перехрестя: це показ сили, що сіє паніку серед ворогів."},sec={{t="Трофей обірваних амбіцій",b="Обози з припасами, що йдуть із Дуротару на захід у Пустки, повсякчас зазнають нападів, але останні з них стали дедалі зухвалішими під проводом лютого ватажка Гостроманів на ім'я Крініґ Снарлснаут. Щоб зламати злагодженість шипогривів, Торк — командир варти Перехрестя — наказав знищити Снарлснаута. Ікло ватажка — не лише певний доказ того, що нападник загинув, а й навмисна образа племені Гостроманів, що ламає їхній дух і лишає бійців без проводу."}},faq={{q="Хто такий Крініґ Снарлснаут?",a="Крініґ Снарлснаут — помітний ватажок шипогривів Гостроманів, що отаборилися на північний схід від Перехрестя. Він влаштовував зухвалі набіги на каравани Орди з припасами на головному шляху з Дуротару й перетворив шлях постачання на небезпеку — аж до своєї смерті.",al={"крініґ снарлснаут","хто такий крініґ","історія гарчоморда"}},{q="Чому Торкові потрібне саме ікло?",a="Торк вимагає ікло і як незаперечний доказ, що Крініґ мертвий, і як навмисну образу племені Гостроманів. Вирване ікло полеглого вождя шипогривів принижує їхню гордість і ламає дух уцілілих нападників.",al={"чому ікло","чому нести ікло торкові","ікло для торка"}},{q="Звідки взяли це ікло?",a="Ікло здобувають у таборі Крініґа Снарлснаута на північний схід від Перехрестя — біля гірських передгір'їв, трохи на південь від головного шляху з Дуротару в Пустки.",al={"де крініґ","де взяти ікло","місце гарчоморда"}},{q="Що дає Пусткам смерть Крініґа?",a="Торк вважає, що без Крініґа нападники-Гостромани розгубляться без проводу. Втрата командира сіє хаос у їхніх лавах і різко зменшує напади на важливі вантажі з припасами.",al={"чи припинилися набіги","наслідки смерті крініґа"}}},fp="25,274,28.552.0,27.267.0,42.223.0,26.192.0,57.213.0"}
P.entries["item:kron-s-amulet"] = {n="Амулет Крона",s="Амулет Крона — особиста пам'ятка Крона, молодого орка-мисливця з Дуротару, що зник на Річці Південної Люті.",h="Амулет Крона — особиста пам'ятка Крона, молодого орка-мисливця з Дуротару, що зник на Річці Південної Люті.",kw={"амулет крона","крон","кроколіски","південна лють","тор'крен","дуротар"},ang={["class:Hunter"]="Суворий урок для кожного майбутнього слідопита: не варто недооцінювати лютих звірів у незнайомих річкових землях.",["race:Orc"]="Доля Крона — трагічне нагадування: хоч гордість і бойова слава рухають орчою традицією, безрозсудність і зневага до мудрості старших можуть принести швидку й марну смерть."},sec={{t="Трагедія на Південній Люті",b="Крон був норовливим молодим орком із хутора на північний захід від Гострого Пагорба. Прагнучи довести свою вправність і зневажаючи небезпеку, він подався полювати на лютих кроколісків-страхопащ, що нишпорять на Річці Південної Люті вздовж кордону з Пустками. Знехтувавши застереженнями матері, Міші Тор'крен, він через уперту гордість потрапив просто в пащі річкових хижаків. Він так і не повернувся, лишивши по собі тільки цю проковтнуту дрібничку — мовчазне підтвердження, що його вбили й зжерли."}},faq={{q="Хто такий Крон?",a="Крон — запальний молодий орк-мисливець, що жив зі своєю матір'ю, Мішею Тор'крен, на хуторі на північний захід від Гострого Пагорба. Прагнучи випробувати свою силу, він сам пішов полювати на річкових звірів, попри застороги про їхню лютість.",al={"хто такий крон","історія крона","лор крона"}},{q="Де знайти Амулет Крона?",a="Амулет дістають зі шлунків кроколісків-жахопащ і зіпсованих кроколісків-жахопащ, що чатують на берегах Річки Південної Люті в Дуротарі.",al={"де знайти амулет","місце амулета крона","хто дропає амулет крона"}},{q="Хто хоче повернути Амулет Крона?",a="Його скорботна мати, Міша Тор'крен, чекає звісток про сина на своєму хуторі на північний захід від Гострого Пагорба. Амулет дає їй остаточну, болісну певність, потрібну, щоб почати оплакувати сина.",al={"кому потрібен амулет","куди здати амулет крона","міша тор'крен"}}},fp="13,131,24.492.1,13.229.0,29.156.1,33.178.1"}
P.entries["item:kuz-s-skull"] = {n="Череп Куза",s="Череп Куза — відтята голова Куза, помітного нападника з-поміж шипогривів-Гостроманів на півдні Пусток. Вийшовши з Рейзорфен Краул, Куз допомагав організовувати жорстокі напади на застави Орди, аж поки колишній родич, що потрапив у полон, не прирік його на смерть.",h="Череп Куза — відтята голова Куза, помітного нападника з-поміж шипогривів-Гостроманів на півдні Пусток.",kw={"череп куза","куз","гостромани","понівечозуб","лок оркбейн","табір тауражо"},ang={["faction:Horde"]="Голова Куза безпосередньо захищає поселення Орди на кшталт Перехрестя й Табору Тауражо від організованої війни шипогривів."},sec={{t="Гірка ворожнеча",b="Рівнини південних Пусток кишать племенем Гостроманів, але їхня організована агресія походить від певних ватажків, яких посилають просто з Рейзорфен Краул. Куз разом із Наком і їхнім безжальним вождем Локом Оркбейном керували жорстокими нападами на мандрівників і поселення на кшталт Перехрестя. Та власна зрада їх і згубила. Зрадивши свого побратима-шипогрива Понівечозуба й покинувши його гнити в клітці в Таборі Тауражо, вони нажили собі мстивого ворога. Понівечозуб за свою ціну видав, де шукати Куза, звитяжцям Орди, готовим відтяти нападникові голову й назавжди покласти край його набігам."},{t="Доказ відплати",b="Череп Куза, принесений до Табору Тауражо, — похмуре підтвердження того, що третину командування південного загону знищено. Для Понівечозуба ця голова — солодке задоволення від помсти племені, яке його покинуло. А для Орди, що тримає гарнізони по всіх Пустках, загибель Куза ламає хребет злагодженим наступам Гостроманів, розбиває їхній провід і дарує тимчасовий перепочинок шляхам постачання на рівнинах."}},faq={{q="Хто така Куз?",a="Куз — одна з трьох хитрих шипогривів-Гостроманів, яких послали з Рейзорфен Краул на південь Пусток. Разом із Наком і Локом Оркбейном вона спрямовувала смертоносні засідки й набіги на табори й шляхи постачання Орди.",al={"хто така куз","історія куз","куз бритвогрив"}},{q="Навіщо Понівечозубу череп Куз?",a="Власні родичі зрадили Понівечозуба й покинули помирати в клітці в Таборі Тауражо. Прагнучи помсти, перш ніж зустріти власну смерть, він посилає шукачів пригод Орди вбити своїх зрадливих суперників і принести їхні черепи як доказ.",al={"чому понівечозуб хоче куз мертву","помста понівечозуба"}},{q="Де знайти Куз у Пустках?",a="Куз кочує в глибині південних Пусток — вона отаборилася з шипогривами-Гостроманами на південь від Табору Тауражо, біля колючого прикордоння.",al={"місце куз","де знайти куз"}},{q="Що стається, коли Куз убито?",a="Череп Куза разом із головами Нака й Лока Оркбейна, принесені Понівечозубу, руйнують провід набігів Гостроманів і відкривають шлях до безпеки південних торгових шляхів.",al={"нагорода за куз","наслідок зради зсередини"}}},fp="11,256,13.607.0,20.438.1,12.218.0,38.236.0,34.145.0,32.191.0"}
P.entries["item:laced-pumpkin"] = {n="Гарбуз із Хмільним Сиропом",s="Гарбуз із Хмільним Сиропом — звичайний гарбуз, оброблений смертельним варивом, яке розробив Аптекар Йогаан у Бріллі. Вручений голодному ув'язненому хрестоносцю Багряного Хрестового Походу нібито як харч, він слугує живим польовим випробуванням дедалі більшого алхімічного арсеналу Відступників.",h="Гарбуз із Хмільним Сиропом — звичайний гарбуз, оброблений смертельним варивом, яке розробив Аптекар Йогаан у...",kw={"гарбуз із хмільним сиропом","аптекар йогаан","отрута","полонений багряний фанатик","таверна шибеничний кінець","брілл"},ang={["faction:Alliance"]="Доля полоненого фанатика — суворе, моторошне нагадування про жахливу долю, що чекає на будь-яку живу людину, захоплену живцем на землях Відступників.",["race:Undead"]="Для Відступників обернути звичайну їжу на зброю — показ прагматизму Королівського Аптекарського Товариства, що йде на будь-які засоби, аби вберегти Тірісфаль від фанатичних живих хрестоносців."},sec={{t="Гіркий урожай",b="Для недосвідченого ока гарбуз із сиропом виглядає як звичайний плід, зібраний на ураженому ґрунті Галявин Тірісфалю. Та під наглядом Аптекаря Йогаана у Бріллі овоч обробляють дослідними токсинами, покликаними розкрити весь потенціал нежиття. Королівське Аптекарське Товариство невпинно шукає нову зброю, щоб відбити і Погибель на півночі, і живі людські сили, що наступають з півдня, — тож навіть прості плоди врожаю стають носіями зарази й хімічної смерті."},{t="Дослід у підвалі",b="Головне призначення гарбуза із сиропом — практичне випробування на живих. У вогкому підвалі Таверни «Шибеничний Кінець» наглядачі з Відступників тримають виголоднілого Полоненого Багряного Фанатика. Знесилений голодом в'язень з полегшенням приймає отруєне підношення. Щойно він з'їдає гарбуз, вариво аптекаря запускає бурхливе перетворення: людина-фанатик обертається на безтямного гуля, який кілька кроків шкутильгає в муках, а тоді падає мертвий на холодну кам'яну підлогу."}},faq={{q="Що таке Гарбуз із Хмільним Сиропом?",a="Це польовий гарбуз, у який впорснули експериментальну суміш Аптекаря Йогаана з Брілла, — щоб перевірити, як алхімія Відступників діє на живих.",al={"гарбуз із хмільним сиропом","отруйний гарбуз","гарбуз йогаана"}},{q="Хто їсть Гарбуз із Хмільним Сиропом?",a="Його з'їдає Полонений Багряний Фанатик, ув'язнений у погребі під Таверною «Шибеничний Кінець» у Бріллі, якого тюремники морили голодом.",al={"хто їсть гарбуз","ціль гарбуза","нагодувати гарбузом"}},{q="Що стається, коли хтось з'їдає гарбуз?",a="Гарбуз дають полоненому фанатикові, щоб випробувати найновішу формулу Йогаана. Як саме він подіє, стане відомо, коли в'язень його з'їсть.",al={"ефект гарбуза","що буде з фанатиком","фанатик гуль"}},{q="Навіщо Відступники це зробили?",a="Аптекар Йогаан і Королівське Аптекарське Товариство випробовують нові біологічні суміші проти Погибелі на півночі й живих людей, що підступають, — а піддослідними стають полонені вороги.",al={"чому відступники це зробили","випробування чуми відступниками"}}},fp="13,280,16.513.0,21.486.1,26.169.0,27.139.0,43.140.1,31.197.0"}
P.entries["item:laird-s-response"] = {n="Відповідь Лейрда",s="Відповідь Лейрда — запечатане послання, яке написав засолювач риби Лейрд у прибережному порту Обердайн. Адресований Нессі Шедовсонг у Селищі Рут'теран, лист описує дивні відмінності між морськими мешканцями біля материка й незвично великою рибою, що буяє біля берегів Тельдрассилу.",h="Відповідь Лейрда — запечатане послання, яке написав засолювач риби Лейрд у прибережному порту Обердайн.",kw={"відповідь лейрда","лейрд","несса шедовсонг","тельдрассил","селище рут'теран","світове дерево"},ang={["race:NightElf"]="Для нічних ельфів, які доглядають береги Тельдрассилу, нотатки Лейрда — цікава, хоч і трохи тривожна підказка про те, що молоде Світове Дерево вже має протиприродний вплив на природу довкола."},sec={{t="Луска й коріння",b="Переглянувши звіти про улов з усього Прихованого Моря, Лейрд з Обердайна помітив разючу розбіжність: риба, яку витягають біля берегів Тельдрассилу, значно більша й рясніша, ніж та, що ловиться біля материкових пляжів Темного Узбережжя. У цій письмовій відповіді Нессі Шедовсонг Лейрд ділиться своєю робочою гіпотезою: протиприродна присутність і буйна життєва сила щойно посадженого Світового Дерева, можливо, викривлюють і підстьобують морське життя довкола. Лист, який доставляють мандрівники, що повертаються через воду, викликає подив і тиху цікавість серед рибалок Селища Рут'теран."}},faq={{q="Що таке Відповідь Лейрда?",a="Це письмове послання, яке написав Лейрд — торговець рибою й засолювальник з Обердайна, — у відповідь на запит Несси Шедовсонг із Тельдрассила.",al={"що це за річ","відповідь лейрда","що таке відповідь лейрда"}},{q="Кому пише Лейрд?",a="Відповідь надсилають Нессі Шедовсонг — нічній ельфійці із Селища Рут'теран біля південного підніжжя Тельдрассила.",al={"хто отримує відповідь лейрда","кому лист","лист нессі лейрда"}},{q="Що сказано в листі про рибу?",a="Лейрд зауважує, що риба, виловлена біля берегів Тельдрассила, помітно більша й рясніша, ніж на материковому Темному Узбережжі, — тож, можливо, саме Світове Дерево впливає на місцеве морське життя.",al={"чому риби великі","різниця риб темного узбережжя і тельдрассила","що знайшов лейрд"}},{q="Як послання повертається до Селища Рут'теран?",a="Гінці можуть або сісти на звичайний пором із пристані Обердайна, або домовитися про переліт на гіпогрифі з майстринею польотів Кейлайс Мунфезер.",al={"як повернутися до нессі","човен рут'теран темне узбережжя","пором з обердайна до нессі"}}},fp="16,298,28.614.0,25.164.0,24.120.0,40.211.0,55.153.0"}
P.entries["item:lake-creeper-moss"] = {n="Мох Озерного Повзуна",s="Мох Озерного Повзуна — органічна речовина, яку збирають із водяних повзунів, що мешкають серед Світанкових Островів на Озері Лордамер. Королівське Аптекарське Товариство шукає його як важливий реагент для створення нової смертоносної чуми.",h="Мох Озерного Повзуна — органічна речовина, яку збирають із водяних повзунів, що мешкають серед Світанкових...",kw={"мох озерного повзуна","озеро лордамер","світанкові острови","аптекар берард","нова чума","головний аптекар фаранелл","травництво"},ang={["profession:Herbalism"]="Хоч цей мох росте на водяних звірах, а не в ґрунті, він належить до темнішого, експериментального краю рослинності Лордерона, яку збирають для аптекарських досліджень.",["race:Undead"]="Кожен зразок озерного моху, принесений до Апотекаріуму, наближає Відступників до досконалої Нової Чуми — і до помсти і Погибелі, і живим."},sec={{t="Алхімічний урожай",b="Мох Озерного Повзуна росте на шкурах лютих прісноводних звірів, що нишпорять довкола південних Світанкових Островів на Озері Лордамер, і має особливі властивості, яких йому надали отруєні води Лордерона. Аптекар Берард, доки прокляття Аруґала не забрало його розум, описав цей мох у щоденнику: він зауважив, що мох схожий на сліди речовин на скам'янілих рештках істот, які загинули в озері від давньої чуми. Зразки, здобуті агентами-Відступниками, відсилають просто до Апотекаріуму в Андерсіті — живити темні досліди Головного Аптекаря Фаранелла."},{t="Паливо для Нової Чуми",b="Цей мох — не просто цікавий водяний наріст: він стає важливим етапом у створенні головної зброї Відступників. Разом зі спорідненим мохом з Озерних Скрадачів і хворобливими пухлинами місцевих мурлоків-Темноплавців мох повзунів дає органічну основу, потрібну, щоб виплекати штам, здатний знищувати і живу плоть, і Погибель. Хоч аптекар, що відкрив його користь, загинув, Королівське Аптекарське Товариство й далі варить за його рецептом на службі Темній Леді."}},faq={{q="Для чого потрібен Мох Озерного Повзуна?",a="Це алхімічний реагент, яким Головний Аптекар Фаранелл і Королівське Аптекарське Товариство варять і вдосконалюють свою Нову Чуму в Андерсіті.",al={"призначення моху повзуна","навіщо збирати мох озерного повзуна","використання моху озерного повзуна"}},{q="Звідки цей мох?",a="Його збирають з озерних повзунів і старих озерних повзунів, що живуть у водах довкола південних Островів Світанку на сході Озера Лордамер.",al={"де взяти мох повзуна","місце моху повзуна","місце озерного повзуна"}},{q="Хто відкрив алхімічну цінність моху?",a="Аптекар Берард описав особливі властивості моху у своєму польовому щоденнику, перш ніж прокляття Аруґала перетворило його на безвольного слугу в Селі Пайрвуд. Його нотатки згодом знайшов Аптекар Ренферрел.",al={"хто відкрив мох","мох берарда","хто писав про мох повзуна"}},{q="Хто отримує зібраний мох?",a="Мох приймає Головний Аптекар Фаранелл в Апотекаріумі Андерсіті й поєднує його з Мохом Озерного Скрадача й затверділою пухлиною, щоб просунути свої дослідження.",al={"хто хоче мох повзуна","здати мох повзуна","мох фараннела"}}},fp="17,247,18.555.0,22.522.1,35.149.0,31.142.0,43.205.0,32.163.0"}
P.entries["item:large-candle"] = {n="Велика Свічка",s="Великі Свічки — воскові свічки, які цінують і носять кобольди, що риють копальні Лісу Елвінн. Прикріплені на маківках, ці грубі світильники дають видимість у підземних тунелях і слугують надійним джерелом сирого воску для людських аптекарів.",h="Великі Свічки — воскові свічки, які цінують і носять кобольди, що риють копальні Лісу Елвінн.",kw={"велика свічка","кобольди","віск","вільям пестл","аптекар","копальня фарґодіп"},ang={["faction:Alliance"]="Забираючи свічки в кобольдів Елвінну, шукачі пригод Альянсу водночас послаблюють шкідників, що заполонили копальні, і постачають важливі матеріали аптекарській справі Стормвінда.",["profession:Mining"]="Рудокопи, що розробляють жили у Фарґодіпі та Яшмовій копальні, раз у раз натикаються на зграї кобольдів, які жадають і золота, і мерехтливого світла цих великих свічок."},sec={{t="Підземне світло й віск",b="Кобольди, що риють тунелі під Лісом Елвінн, покладаються на полум'я свічки, щоб орієнтуватися в чорних як ніч підземних штольнях, і кріплять воскові свічки просто до голови. Кобольди-рудокопи, прохідники й геоманти люто захищають свої свічки від зайд. Попри грубе виготовлення, великі свічки, які носять глибоко в Копальні Фарґодіп і Яшмовій копальні, містять цінний віск, який наземним ремісникам нелегко виробити у великій кількості, — так буденне знаряддя чудовиськ стає алхімічним товаром."},{t="Торгівля й аптекар",b="Вільям Пестл, аптекар родом зі Стормвінда, збирає ці великі свічки в корчмі «Лев'яча Гордість» у Ґолдширі. Шукаючи витопленого воску для настоянок, бальзамів і мазей, які готує його родинна аптека, Пестл наймає перехожих шукачів пригод очистити заполонені копальні й забрати свічки в підземних загарбників."}},faq={{q="Для чого потрібні Великі Свічки?",a="Вільям Пестл збирає Великі Свічки в Ґолдширі для аптеки свого брата в Стормвінді. Там свічки перетоплюють і використовують віск як складник різних мазей, бальзамів і алхімічних рецептів.",al={"використання великої свічки","навіщо великі свічки","хто хоче великі свічки"}},{q="Де знайти Великі Свічки?",a="Їх носять кобольди, що живуть у копальнях Лісу Елвінн, — переважно в Копальні Фарґодіп на південь від Ґолдшира та в Яшмовій копальні на сході. Свічки мають копачі, шахтарі й геоманти.",al={"де знайти великі свічки","місце великої свічки","свічки кобольдів"}},{q="Чому кобольди носять свічки на голові?",a="Кобольди живуть у непроглядно темних підземних тунелях, і їм потрібне світло, щоб копати й знаходити дорогу. Вони прилаштовують свічки на голову, щоб руки лишалися вільними для кайла, геомантських чарів і зброї.",al={"чому кобольди носять свічки","свічка на голові кобольда"}},{q="Хто такий Вільям Пестл?",a="Вільям Пестл — аптекар зі Стормвінда, що веде справи в Корчмі «Лев'яча Гордість» у Ґолдширі. Він збирає сировину в навколишніх нетрях і копальнях для аптеки, яку тримає разом із братом.",al={"історія вільяма пестла","хто аптекар у ґолдширі"}}},fp="12,253,26.490.0,24.353.0,32.240.0,33.200.0,44.203.0,22.233.0"}
P.entries["item:large-soran-ruk-fragment"] = {n="Великий Уламок Соран'рука",s="Великий уламок Соран'рука — чималий залишок прадавнього артефакту, скутого демонічною силою. Колись у ньому був ув'язнений дух зганьбленого демона Палаючого Легіону, а тепер цей уламок потрапив до рук зловісних чаклунів у моторошних мурах Фортеці Шадовфенг.",h="Великий уламок Соран'рука — чималий залишок прадавнього артефакту, скутого демонічною силою.",kw={"великий уламок соран'рука","соран'рук","фортеця шадовфенг","демон","чорнокнижник","доан кархан"},ang={["class:Warlock"]="Здобувши Великий Уламок Соран'рука, ви зможете підкорити ув'язненого в ньому демонічного духа й допомогти Доанові Кархану відновити могутню зброю для демонічних мистецтв."},sec={{t="Спадщина Соран'рука",b="Коли демони Палаючого Легіону втрачають ласку своїх темних володарів, їхніх духів часом прирікають на ув'язнення в зачарованих сферах. Ці посудини згодом роздають магам і чорнокнижникам, що служать Легіонові, і ті черпають могутню силу скверни, ув'язнену всередині. Навіть розбита на уламки, залишкова сутність скутого демона й далі випромінює силу, тож кожен уламок — бажана здобич для честолюбних знавців магії тіні."},{t="Уламок у Шадовфенгу",b="Сферу Соран'рука давно розкололи навпіл. Одну половину розбили ще дрібніше й розпорошили серед сектантів деінде, а більшу забрав чаклун, що живе в проклятій твердині — Фортеці Шадовфенг. Там, серед зловісних Темних Душ Шадовфенга, Великий Уламок Соран'рука спрямовує демонічну силу, доки його не знайдуть ті, хто прагне знову викувати прадавню посудину."}},faq={{q="Що таке Великий Уламок Соран'рука?",a="Це більша половина Сфери Соран'рука — прадавньої магічної посудини, в якій ув'язнено дух зганьбленого демона Палаючого Легіону.",al={"великий уламок соран'рука","що це за уламок","що таке уламок соран'рука"}},{q="Де знайти уламок?",a="Уламок тримають Темні Душі Шадовфенгу — лихі чаклуни, що засіли в проклятій Фортеці Шадовфенг у Срібноліссі.",al={"де взяти великий уламок","місце великого уламка","хто дропає великий уламок соран'рука"}},{q="Чому сферу розбито?",a="Первісну сферу розкололи на дві головні частини. Меншу половину розбили на дрібніші скалки й віднесли в прибережні печери Чорноглибинних Печер, а цю, більшу, зберігали темні чарівники у Фортеці Шадовфенг.",al={"як розбилася сфера","чому сфера розбита","історія сфери соран'рука"}},{q="Хто хоче її зібрати?",a="Доан Кархан, відлюдник, що живе на далекому півдні Пусток, присвятив життя вивченню й відновленню втрачених сфер Палаючого Легіону.",al={"кому потрібен великий уламок","хто збирає сферу"}}},fp="24,276,23.468.0,23.410.0,37.145.0,28.147.0,23.229.0,27.169.0"}
P.entries["item:laughing-sister-s-hair"] = {n="Волосся Реготливої Сестри",s="Волосся Реготливої Сестри — м'які чарівні пасма, які зрізають у дріад, що живуть у зачарованих лісах Ашенвалю. Вправні ткачі дуже цінують ці пасма: вони мають вроджені містичні властивості й чудово пасують для пошиття вишуканих мантій.",h="Волосся Реготливої Сестри — м'які чарівні пасма, які зрізають у дріад, що живуть у зачарованих лісах Ашенвалю.",kw={"волосся реготливої сестри","дріади","кравецтво","кіл'гала","притулок рейнвуд","ашенваль"},ang={["faction:Horde"]="Щоб здобути ці пасма, доводиться заходити на землі нічних ельфів в Ашенвалі й убивати лісових духів, — і це показує, що Орда готова силою брати місцеву магію.",["profession:Tailoring"]="Неземні пасма дріад — одне з найекзотичніших джерел нитки на Калімдорі: їх цінують за те, що вони вплітають у тканину вроджену магію природи."},sec={{t="Рідкісний матеріал для ткання",b="Це волосся, яке зрізають у дріад, відомих як реготливі сестри, поблизу Притулку Рейнвуд в Ашенвалі, сповнене дивовижної природної магії. Для нічних ельфів дріади — священні охоронниці лісу, пов'язані з Кенарієм, а от ремісники Орди цінують їхнє волосся лише як потужний матеріал для ремесла. Кравець-троль Кіл'гала на Перехресті пряде із цих пасм зачаровані шати для початківців у таємній магії."}},faq={{q="Звідки береться Волосся Реготливої Сестри?",a="Волосся збирають у реготливих сестер — дріад, що блукають зачарованими гаями біля Притулку Рейнвуд у центрі Ашенвалю.",al={"де взяти волосся реготливої сестри","місце волосся реготливої сестри","джерело волосся дріад"}},{q="Навіщо Кіл'галі волосся дріад?",a="Кіл'гала — майстер-кравець із Перехрестя в Пустках. Він тче з чарівних пасом зачаровані мантії для здібних учнів Дейно.",al={"навіщо кіл'галі волосся","використання волосся реготливої сестри","кравець троль волосся дріад"}},{q="Чи віддадуть реготливі сестри волосся добровільно?",a="Ні. Реготливі сестри — завзяті охоронниці природи й присяжні захисниці Ашенвалю. Як сухо зауважує Кіл'гала, дріади нізащо добровільно не віддадуть свого волосся посланцям Орди.",al={"чи можна попросити волосся у дріад","чи дріади віддають волосся"}}},fp="22,244,24.435.0,44.128.0,39.175.0,55.189.0"}
P.entries["item:legacy-of-the-aspects"] = {n="Спадок Аспектів",s="«Спадок Аспектів» — прадавній том, захований глибоко в Притулку Дор'Даніл на півдні Ашенвалю. Його здобувають під час ордівського випробування розуму: книга містить важливі знання про Великих Аспектів, що формували прадавній Азерот.",h="«Спадок Аспектів» — прадавній том, захований глибоко в Притулку Дор'Даніл на півдні Ашенвалю.",kw={"спадок аспектів","великі аспекти","притулок дор'даніл","брауґ дімспіріт","випробування розуму","ашенваль"},ang={["class:Druid"]="Книга лежить глибоко в Притулку Дор'Даніл, оточена трагічними, змученими духами полеглих друїдів з нічних ельфів.",["faction:Horde"]="Цей том — серцевина традиційного обряду посвяти, що перевіряє, чи мають шукачі пригод з Орди мудрість і знання, гідні їхньої фізичної сили."},sec={{t="Випробування розуму",b="Попередні випробування старійшин-тауренів перевіряють фізичну витривалість і силу волі, а пошук «Спадку Аспектів» покликаний кинути виклик розуму. За дорученням Брауґа Дімспіріта, що стоїть біля входу на Стежку Глибокого Кігтя в Горах Кам'яного Кігтя, претендент має спуститися в примарні підземні притулки Дор'Даніла. Давній текст лежить на кам'яному постаменті під охороною неспокійних духів полеглих друїдів і лютих істот, які їх убили. Здобути книгу — лише перший крок: шукач мусить запам'ятати її зміст, перш ніж віддати том, бо його випитуватимуть про історичні уроки з неї."}},faq={{q="Де лежить ця книга?",a="Книга лежить на кам'яному постаменті в нижніх залах Курганного Лігва Дор'Даніл на півдні Ашенвалю, на південь від Застави Розщепленого Дерева.",al={"де книга спадок аспектів","місце книги","де ця книга"}},{q="Навіщо Брауґові Дімспіріту ця книга?",a="Брауґ Дімспіріт проводить за нею «Тест Знань». На відміну від випробувань сили, тут з'ясовують, чи має шукач пригод розум і уважність, щоб вивчити й запам'ятати важливі знання про історію.",al={"навіщо браугу книга","іспит знань"}},{q="Що буде, якщо не прочитати текст, перш ніж говорити з Брауґом?",a="Щойно отримавши книгу, Брауґ розпитує шукачів про знання з її сторінок. За хибну відповідь — миттєве магічне вигнання: непідготовленого прохача переносить далеко, аж до Табору Тауражо в Пустках.",al={"наслідок неправильної відповіді","провал іспиту"}}},fp="21,249,18.619.0,26.148.0,40.234.0,68.231.0"}
P.entries["item:letter-to-delgren"] = {n="Лист до Делґрена",s="Лист до Делґрена — нагальне послання, яке написав Балтул Шедовстрайк біля Вежі Альталакса на півночі Темного Узбережжя. Адресований його наставникові, паладинові Делґрену Очищувачу, лист докладно описує зловісні дії демонічного культу Темного Берега. Цей лист несе важливі відомості на південь, до Посту Маестри в Ашенвалі.",h="Лист до Делґрена — нагальне послання, яке написав Балтул Шедовстрайк біля Вежі Альталакса на півночі Темного...",kw={"лист до делґрена","балтул шедовстрайк","делґрен очищувач","культ темного берега","вежа альталакса","пост маестри"},ang={["class:Paladin"]="Це послання показує незвичне побратимство: паладин-людина навчає учня з нічних ельфів Святого Світла, єднаючи давні землі калдореїв із войовничою вірою Східних Королівств.",["faction:Alliance"]="Лист свідчить про дедалі тіснішу співпрацю в Альянсі: звитяжці-люди та Вартові нічних ельфів об'єднують сили проти демонічних культів, що проникають на північ Калімдору."},sec={{t="Пересторога на південь",b="Поки культисти Темного Берега збираються довкола руїн Вежі Альталакса, нічний ельф Балтул Шедовстрайк стежить за їхньою дедалі лютішою злобою. Не маючи бойової сили, щоб викорінити культ самотужки, Балтул пише це послання, просячи допомоги у свого наставника у Святому Світлі — Делґрена Очищувача. Мерзенні обряди культу загрожують не лише Темному Узбережжю, тож лист треба пронести через увесь край аж до західного Ашенвалю, де Делґрен разом із Вартовими нічних ельфів полює на демонів і нежить."}},faq={{q="Що таке Лист до Делґрена?",a="Це запечатане послання, яке написав Балтул Шедовстрайк, із донесенням про дедалі більшу діяльність демонічного культу Темного Берега у Вежі Альталакса. Його адресовано паладинові Делґрену Очищувачу.",al={"що це за лист","лист до делґрена","лист балтула"}},{q="Хто такий Делґрен Очищувач?",a="Делґрен — паладин-людина з Посту Маестри на заході Ашенвалю. Відданий Святому Світлу, він допомагає своєю бойовою вправністю Вартовим нічних ельфів викорінювати демонів і нежить із прадавніх лісів і навчає Балтула священної війни.",al={"хто такий делґрен","історія делґрена","де делґрен"}},{q="Чому Балтул надсилає лист так далеко?",a="Балтул — учень Делґрена й покладається саме на досвід свого наставника в боротьбі з демонічною скверною. Делґрен має і бойову вправність, і підтримку місцевих Вартових на Посту Маестри, щоб дати злагоджену відсіч темним обрядам Темного Берега.",al={"чому слати в ашенвейл","чому не розповісти обердайну"}},{q="Куди треба доставити цей лист?",a="Лист треба нести на південь через усе Темне Узбережжя, перетнути кордон з Ашенвалем і дістатися Посту Маестри при західній дорозі.",al={"куди віднести лист","місце доставки листа"}}},fp="17,335,20.573.0,30.200.0,28.267.0,47.270.0,44.143.0"}
P.entries["item:letter-to-ello"] = {n="Лист до Елло",s="Лист до Елло — запечатане послання, написане Аберкромбі, дивакуватим відлюдником, що живе біля Притону Жебрака в Сутінколіссі. Адресований меру Даркшира Елло Ебонлоку, лист доставляють нібито на знак давньої дружби, хоча написаний він архаїчним письмом.",h="Лист до Елло — запечатане послання, написане Аберкромбі, дивакуватим відлюдником, що живе біля Притону...",kw={"лист до елло","аберкромбі","елло ебонлок","сірра вон'інді","даркшир","притон жебрака"},ang={["faction:Alliance"]="Носити листи між дивакуватими відлюдниками й мерами — звичайна справа для мандрівників у Сутінколіссі, хоча урядники Даркшира щоразу насторожуються, коли до них потрапляють дивні послання."},sec={{t="Дивне вітання",b="Коли шукачі пригод допомагають відлюдникові Аберкромбі з дорученнями в Сутінколіссі, старий самітник довіряє їм цю записку й запевняє, що мер Елло Ебонлок — його давній друг, який радітиме з того, що вдалося зробити. Насправді мер Даркшира й гадки не має ні про якого Аберкромбі. Зламавши печатку, Ебонлок виявляє, що не може розібрати жодної фрази архаїчного письма, і передає записку вченому Даркшира, Сіррі Вон'Інді, щоб той переклав."},{t="Темні знамення",b="Це, здавалося б, невинне доручення приховує справжні, моторошні наміри відлюдника. Ніякого дружнього листування між давніми знайомими тут немає: стародавні руни, виведені рукою Аберкромбі, віщують загибель усьому Даркширу."}},faq={{q="Хто написав Лист до Елло?",a="Лист написав Аберкромбі — відлюдник, що живе в напіврозваленій хатині біля Цвинтаря Воронячого Пагорба на заході Сутінколісся.",al={"хто написав лист","автор листа до елло","хто надіслав лист"}},{q="Чи може бургомістр Елло Ебонлок прочитати лист?",a="Ні. Отримавши лист у Даркширі, бургомістр Ебонлок не може розібрати письма й зауважує, що воно, схоже, написане якоюсь прадавньою, невідомою мовою.",al={"чи може елло прочитати","чому елло не може прочитати записку","мова листа елло"}},{q="Хто може перекласти записку?",a="Бургомістр Ебонлок посилає гінців віднести послання Сіррі Вон'Інді — місцевій ученій у Даркширі, що знається на давніх письменах і таємних мовах.",al={"хто перекладе записку","перекласти записку аберкромбі","хто може прочитати лист"}},{q="Чи справді бургомістр Ебонлок знає Аберкромбі?",a="Хоч Аберкромбі й запевняє, що вони з бургомістром старі друзі, Елло Ебонлок наполягає, що ніколи не чув ні про якого Аберкромбі.",al={"чи знає елло аберкромбі","чи друзі елло та аберкромбі","давні друзі аберкромбі та елло"}}},fp="14,293,18.490.0,10.224.1,29.120.0,41.179.0,27.158.0,47.137.0"}
P.entries["item:letter-to-jin-zil"] = {n="Лист до Джин'Зіла",s="Лист до Джин'Зіла — послання, написане орком Дарсоком Свіфтдаґґером на Перехресті. Його довіряють шукачеві пригод після загибелі Серени Бладфезер, і воно сповіщає знахаря Темного Списа Джин'Зіла в Горах Кам'яного Кігтя, що північні Пустки очищено від загрози Бладфезер.",h="Лист до Джин'Зіла — послання, написане орком Дарсоком Свіфтдаґґером на Перехресті.",kw={"лист до джин'зіла","дарсок свіфтдаґґер","серена бладфезер","знахар джин'зіл","гарпії","перехрестя","малака'джин"},ang={["faction:Horde"]="Лист стає містком для шукачів пригод з Орди, які від наведення ладу в Пустках переходять до глибших протистоянь, що назрівають у Горах Кам'яного Кігтя.",["race:Troll"]="Доставляючи лист, мандрівники з Темного Списа потрапляють просто до Знахаря Джин'Зіла — старого чаклуна, що береже традиційне вуду далеко від Островів Відлуння."},sec={{t="Гонець до Гір Кам'яного Кігтя",b="Після знищення гарпій, що заполонили Сухі Пагорби, і загибелі Серени Бладфезер Дарсок Свіфтдаґґер пише це послання давньому бойовому товаришеві. Знаючи, що гарпії Пусток спершу гніздилися на вершинах Гір Кам'яного Кігтя, Дарсок через цей лист рекомендує здібного воїна для ширшого порубіжжя й сповіщає знахаря Джин'Зіла, що матріархиня гарпій упала."},{t="Давні спогади в Малака'джині",b="Коли лист доставляють до печери в Малака'джині, Джин'Зіл зустрічає новину з ностальгійним задоволенням. Смерть Серени нагадує старому знахареві про заснування Дуротару після Третьої війни, коли його друг Рокхан разом зі звіроловом-мок'наталом Рекссаром убив старшу сестру Серени — Бладфезер. Тепер, коли загинула й Серена, Джин'Зіл вважає, що помсту роду Бладфезер остаточно погашено."}},faq={{q="Хто написав Лист до Джин'Зіла?",a="Лист написав Дарсок Свіфтдаґґер — орк із Перехрестя в Пустках, що керує обороною від хижих ковенів гарпій.",al={"хто це написав","відправник листа","лист дарсока"}},{q="Де знайти Джин'Зіла?",a="Знахар Джин'Зіл живе в печері в Малака'джині — заставі тролів Темного Спису серед південно-східних скель Гір Кам'яного Кігтя.",al={"де джин'зіл","місце джин'зіла","знайти джин'зіла"}},{q="Яку новину несе лист?",a="Послання сповіщає Джин'Зіла, що Серену Бладфезер, ватажку гарпій, які налітали на північ Пусток, убито, — і околиці на північ від Перехрестя тепер у безпеці.",al={"що каже лист","яка новина в листі"}},{q="Чому Джин'Зілу не байдужі Бладфезер?",a="Джин'Зіл пам'ятає заснування Дуротару після Третьої війни, коли його товариш Рокхан і воїн-мок'натал Рекссар убили старшу сестру Серени. Відтоді Серена прагнула помсти Орді, тож її загибель — бажане завершення цієї історії.",al={"чому джин'зілу бладфезер","історія бладфезер","рохан і бладфезер"}}},fp="17,325,25.425.0,26.416.1,32.154.0,25.147.0,41.181.0,46.246.0"}
P.entries["item:letter-to-jorgen"] = {n="Лист до Йорґена",s="Лист до Йорґена — конфіденційне послання, складене, щоб залучити давнього знайомого в Стормвінді. Воно правує агентові за рекомендацію на початку розслідування гучного дипломатичного зникнення.",h="Лист до Йорґена — конфіденційне послання, складене, щоб залучити давнього знайомого в Стормвінді.",kw={"лист до йорґена","йорґен","долина героїв","терамор","джайна праудмур","зниклий дипломат"},ang={["class:Rogue"]="Діяти через тихі депеші й неохочих вуличних інформаторів, а не через міську варту, — звичний і необхідний спосіб розкрити нечисту гру в столиці.",["faction:Alliance"]="Послання зачіпає хиткий спокій Альянсу: воно покликане тихо владнати випадок, що загрожує дипломатичним зв'язкам між Стормвіндом і Терамором."},sec={{t="Сухий виклик",b="Коли високопоставлений дипломат, що прямував до Терамора, так і не прибув на заплановані переговори з Леді Джайною Праудмур, королівські слідчі кинулися замовчувати випадок. Поки офіційні агенти прочісували столицю, потай задіяли й інші канали. Цей запечатаний лист склали, щоб оминути звичну військову бюрократію; він адресований саме Йорґенові — суворому ветеранові, що коротає дні за рибалкою під велетенськими статуями в Долині Героїв. Послання нагадує про давні зобов'язання й утягує неохочого знайомого в таємне розслідування, довкола якого ходять чутки про змову Дефіас."}},faq={{q="Для чого цей лист?",a="Лист слугує рекомендацією й закликом виконати давнє зобов'язання. Він веде того, хто його несе, до Йорґена — агента в Долині Героїв, щоб той незалежно поглянув на справу зниклого дипломата, не сполошивши широкий загал.",al={"для чого лист до йорґена","навіщо лист до йорґена","призначення листа"}},{q="Хто такий Йорґен?",a="Йорґен — відлюдкуватий знайомий, що живе просто за брамою Стормвінда й проводить час, рибалячи у водах Долини Героїв. Хоч і дратується, коли його відволікають, давній борг зобов'язує його допомогти, щойно йому покажуть цей лист.",al={"хто такий йорґен","йорґен нпс","йорґен стормвінд"}},{q="З яким зникненням пов'язаний лист?",a="Відомий дипломат вирушив зі Стормвінда до Терамора на аудієнцію з Леді Джайною Праудмур, але зник дорогою. Підозра падає на Братство Дефіас, хоча весь розмах змови тримають у суворій таємниці.",al={"який дипломат зник","хто зник","зниклий дипломат"}},{q="Куди доставляють лист?",a="Лист несуть у Долину Героїв — величний вхід до Стормвінда, обставлений пам'ятниками героям Другої війни. Йорґена можна знайти біля води неподалік головної брами.",al={"куди нести лист","місце йорґена","де йорґен"}}},fp="16,221,23.602.0,35.241.0,14.248.0,45.240.0,30.202.0"}
P.entries["item:lewis-note"] = {n="Записка Льюїса",s="«Записка Льюїса» — термінова заявка на припаси, яку написав Інтендант Льюїс у Сентінел Гіллі. Гонець доставляє її грифоном, і в ній — прохання надіслати конче потрібне захисне спорядження від приватного бронника зі Старого Міста Стормвінда.",h="«Записка Льюїса» — термінова заявка на припаси, яку написав Інтендант Льюїс у Сентінел Гіллі.",kw={"записка льюїса","інтендант льюїс","осрік стренг","сентінел гілл","народне ополчення","старе місто"},ang={["race:Human"]="Доставляючи цю заявку, юні людські шукачі пригод вчаться користуватися королівською мережею грифонів — і на власні очі бачать гірку правду: правителі Стормвінда майже нічого не роблять, щоб озброїти захисників Вестфолу."},sec={{t="Благання про сталь",b="Народне ополчення в Сентінел Гіллі живе на мізерні кошти й майже не отримує офіційної підтримки від Дому Вельмож у Стормвінді. У постійних сутичках із Братством Дефіас гарнізон швидко витрачає свої скромні запаси спорядження. Щоб захисникам було чим боронитися, Інтендант Льюїс покладається на приватні домовленості, а не на королівське постачання. Ця заявка цілком оминає офіційні військові канали: гонець Альянсу має полетіти грифоном до Старого Міста й передати замовлення просто Осрікові Стренгу, власникові крамниці «Обмежений імунітет»."}},faq={{q="Що таке Записка Льюїса?",a="Це письмове замовлення від Інтенданта Льюїса із Сентінел Гілл до Осріка Стренга, зброяра в Стормвінді, — з проханням надіслати більше захисного спорядження для змученого гарнізону Вестфолу.",al={"що це за річ","призначення записки льюїса","що робить записка"}},{q="Хто написав цю записку?",a="Її написав Інтендант Льюїс — офіцер, що відає запасами, провіантом і зброєю для Народного ополчення на Сентінел Гілл.",al={"хто такий льюїс","інтендант льюїс"}},{q="Хто отримує записку?",a="Записку спершу несуть майстрові грифонів Тору на Сентінел Гілл, а тоді доставляють просто Осрікові Стренгу в його крамницю обладунків «Обмежений Імунітет» у Старому Місті Стормвінда.",al={"куди записка","хто отримує записку льюїса","записка осріка стренґа"}},{q="Чому гарнізон не отримує обладунків від королівства?",a="Уряд королівства майже покинув Вестфол, і місцеві захисники мусять самі дбати про себе без прямого військового фінансування чи королівських обладунків. Льюїс змушений покладатися на особисті торгові зв'язки, як-от з Осріком Стренгом, щоб споряджати ополчення.",al={"чому купувати в осріка","чому стормвінд не допомагає","допомога стормвінда вестфоллу"}}},fp="11,225,16.605.0,20.184.0,20.160.0,22.202.0,57.255.0"}
P.entries["item:lieutenant-s-insignia"] = {n="Відзнака Лейтенанта",s="Відзнака Лейтенанта — емблема, яку носять старші члени культу Палаючого Клинка, що ховається в Дуротарі. Здобута шукачами пригод Орди, вона стає важливим доказом того, що культ діє небезпечно близько від Оргріммара.",h="Відзнака Лейтенанта — емблема, яку носять старші члени культу Палаючого Клинка, що ховається в Дуротарі.",kw={"відзнака лейтенанта","палаючий клинок","череп-скеля","тралл","ніру файрблейд","тіньова рада"},ang={["class:Warlock"]="Відзнака показує, як Палаючий Клинок зловживає магією Скверни на службу Палаючому Легіону, і це неабияк ускладнює хистку терпимість Тралла до законослухняних чорнокнижників Орди.",["faction:Horde"]="Для молодої Орди відзнака — знак підступної загрози: демонічна скверна намагається підточити нову державу Тралла зсередини."},sec={{t="Знак культу",b="Відзнаку Лейтенанта забирають у культистів, що окопалися в Череп-скелі на східному узбережжі Дуротару; вона засвідчує, що її власник — офіцер Палаючого Клинка. Вождь Тралл не терпітиме зрадників у своїй новій державі, але відкрита облава лише розпорошила б культ, перш ніж викрито його ватажків. Тож Тралл перетворює відзнаку на підроблене посвідчення й повертає її довіреному поборникові, щоб перевірити вірність підозрюваних запроданців, які таяться просто під Оргріммаром."},{t="Тіньова Розколина",b="Тралл посилає свого агента з відзнакою до Тіньової Розколини, щоб показати її чорнокнижникові Ніру Файрблейду. Гадаючи, що вітає щойно підвищеного підлеглого, Ніру цілком ковтає наживку. Засліплений пихою, чорнокнижник відкрито хвалиться, що Палаючий Клинок — пряме знаряддя Ради Тіней й Палаючого Легіону, і мимоволі дає Траллові нагоду викрити гниль, що вкоренилася під містом."}},faq={{q="Звідки береться Відзнака Лейтенанта?",a="Її забирають у фанатиків і учнів Палаючого Клинка, що орудують у Череп-скелі — печері на узбережжі на схід від Оргріммара в Дуротарі.",al={"як отримати відзнаку лейтенанта","хто дропає відзнаку лейтенанта","джерело відзнаки лейтенанта"}},{q="Для чого потрібна відзнака?",a="Вождь Тралл використовує відзнаку, щоб замаскувати свого агента. З нею молодий шукач пригод може видати себе за офіцера Палаючого Клинка й піти туди, куди не дістануться власні агенти Тралла, — щоб дізнатися, хто насправді очолює культ.",al={"навіщо мені відзнака лейтенанта","завдання відзнаки лейтенанта","що робити з відзнакою"}},{q="Хто такий Ніру Файрблейд?",a="Ніру Файрблейд — орк-чорнокнижник із Тіньової Розколини в Оргріммарі. Він запевняє, що служить Траллові, доводячи, що чорнокнижники можуть допомагати Орді, а насправді таємно очолює місцевий осередок культу Палаючого Клинка.",al={"хто такий ніру","історія ніру файрблейда"}},{q="Чому Тралл не вб'є Ніру Файрблейда одразу?",a="Тралл знає, що Ніру — зрадник, але передчасний удар лише попередить справжніх господарів культу й розпорошить їхню мережу. Тралл воліє використовувати Ніру як мимовільного донощика, щоб викрити ширшу присутність Ради Тіней у Дуротарі.",al={"чому тралл не вбиває ніру","чому тримати ніру живим","чому проникнути до ніру"}}},fp="21,230,18.517.0,19.448.1,47.143.0,30.223.1,23.214.2,57.244.1"}
P.entries["item:lightning-gland"] = {n="Блискавкова Залоза",s="Блискавкові залози добувають зі звірів-бурешкурів, що блукають рівнинами Пусток. Вони насичені природним стихійним зарядом, і їх шукає Майстер Броварства Дрон із Раджета: з них він варить вогненне, міцне трогське пиво за рецептом, який перейняв від мандрівного пандарена Ченя Бурештофа.",h="Блискавкові залози добувають зі звірів-бурешкурів, що блукають рівнинами Пусток.",kw={"блискавкова залоза","трогське пиво","дрон","раджет","бурештоф","пустки"},ang={["profession:Cooking"]="Хоч блискавкові залози й не належать до звичних кулінарних інгредієнтів, вони добре показують прикордонну броварську філософію Ченя Бурештофа й Майстра Броварства Дрона: сирі нутрощі звірів ідуть просто в міцний трунок."},sec={{t="Інгредієнт, що б'є струмом",b="Савани Пусток населяють різні хижаки, яких торкнулися стихії, — зокрема й бурешкури. У їхній плоті ховається блискавкова залоза: орган, що пульсує прихованою електричною силою. Для звичайної страви ці мінливі залози навряд чи годяться, зате їх високо цінують дивакуваті бровари, яким до смаку напій зі справжнім жалом."},{t="Трогське пиво Дрона",b="У портовому містечку Раджет Майстер Броварства Дрон продовжує броварські традиції, яких його навчив Чень Бурештоф. Щоб зварити міцний напій, відомий як трогське пиво, Дронові потрібні п'ять блискавкових залоз, а ще слинна залоза громояструба і свіжа печінка кодо. Готове пійло має неабиякий удар: шукачі пригод кажуть, що воно водночас і бадьорить, і валить з ніг."}},faq={{q="Які істоти носять блискавкові залози?",a="Блискавкові залози добувають із грозошкурів, що кочують широкими саванами Пусток.",al={"де взяти блискавкові залози","хто дропає блискавкову залозу","блискавкова залоза штормошкірих"}},{q="Кому потрібні блискавкові залози й навіщо?",a="Майстер Броварства Дрон у Раджеті збирає їх, щоб зварити трогівський ель за рецептом, якого його навчив мандрівний майстер броварства Чень Бурештоф.",al={"кому потрібні блискавкові залози","здати блискавкову залозу","призначення блискавкової залози"}},{q="Що ще потрібно, крім блискавкової залози?",a="Рецепт Дрона вимагає п'яти блискавкових залоз, слинної залози великого громового яструба й свіжої печінки кодо, взятої в звірів Пусток.",al={"інгредієнти ель дрона","три предмети бочка чена"}}},fp="15,259,21.334.0,17.360.0,38.87.0,35.140.0,50.162.0"}
P.entries["item:logging-rope"] = {n="Линва Лісоруба",s="Линва лісоруба — важкий канат, без якого не обійтися лісозаготівлям клану Бойової Пісні в Ашенвалі. Місцеві племена фурболгів, що люто опираються поширенню Орди в прадавньому лісі, влаштовували засідки на вантажі цих міцних линв і викрадали їх.",h="Линва лісоруба — важкий канат, без якого не обійтися лісозаготівлям клану Бойової Пісні в Ашенвалі.",kw={"линва лісоруба","бойова пісня","фурболги","лісозаготівля","лок окарр","ашенваль"},ang={["faction:Horde"]="Повернути линви вкрай важливо, щоб воєнна машина клану Бойової Пісні й далі отримувала деревину попри безперервні засідки.",["race:Orc"]="Орківські поселення на Калімдорі цілком залежать від деревини Ашенвалю, тож кожна перехоплена скриня з лісорубським знаряддям — образа, що вимагає відплати."},sec={{t="Викрадені линви",b="Щоб підтримувати збудовані гоблінами машини й лісопилки Лісозаготівельного Табору Бойової Пісні, потрібно безліч міцних лісорубських линв. Та важливі вантажі так і не дійшли до лісорубів у таборі: їх перехопили племена фурболгів Гнилолісу й Будякохутрих. Збожеволілі від порчі й люто віддані лісам своїх предків, ці фурболги складають викрадені линви у своїх таборах на півночі та в центрі Ашенвалю."},{t="Постачання для війни",b="Лок Окарр на Заставі Розщепленого Дерева має повернути втрачений ланцюжок постачання, поки лісозаготівля Бойової Пісні не зупинилася. Відбиваючи важкі линви просто в матерів лігва та воїнів фурболгів, Орда може й далі валити ліс, в'язати колоди й налагоджувати пилки, попри безупинний партизанський опір споконвічних мешканців лісу."}},faq={{q="Для чого потрібна Линва Лісоруба?",a="Це товста промислова линва, потрібна Лісозаготівельному Табору Бойової Пісні, щоб зв'язувати зрубану деревину, тягати колоди по бездоріжжю й кріпити важкі машини в Ашенвалі.",al={"використання линви лісоруба","чому війнапісня потребує линви","линва лісорубів війнапісні"}},{q="Хто вкрав линву?",a="Вантажі пограбували місцеві фурболги — Гнилолісці й Будякохутрі, — що тягнуть украдені линви до своїх лігв і таборів по всьому Ашенвалю.",al={"хто вкрав линву","злодій линви","які фурболги мають линву"}},{q="Хто хоче повернути цю линву?",a="Лок Окарр із Застави Розщепленого Дерева просить линву разом з іншими загубленими припасами, щоб роботи в Лісозаготівельному Таборі Бойової Пісні не стали.",al={"кому потрібна линва","видавець завдання на линву"}},{q="Чому фурболги крадуть припаси лісорубів?",a="Фурболги люто опираються суцільній вирубці Ашенвалю, яку веде Орда. Перехоплюючи каравани з припасами, вони зупиняють лісопилки й мстяться за вторгнення на свої землі.",al={"мотив фурболгів","чому фурболги нападають на постачання"}}},fp="12,249,12.446.0,24.366.0,30.170.0,27.161.0,25.159.0,43.174.0"}
P.entries["item:lok-s-skull"] = {n="Череп Лока",s="Череп Лока — відтята голова Лока Оркбейна, лютого воїна Гостроманів, який водив шипогривів у жорстокі набіги на шляхи постачання Орди на півдні Пусток. Його прагне здобути ув'язнений шипогрив Понівечозуб, щоб помститися, а сам череп — незаперечний доказ того, що ватажок нападників загинув.",h="Череп Лока — відтята голова Лока Оркбейна, лютого воїна Гостроманів, який водив шипогривів у жорстокі набіги...",kw={"череп лока","лок оркбейн","гостромани","шипогриви","понівечозуб","перехрестя","торк"},ang={["faction:Horde"]="Здобувши череп Лока Оркбейна, ви знищуєте верхівку південних шипогривів, які постійно нападають на каравани з припасами між Табором Тауражо й Перехрестям.",["race:Orc"]="Виставити напоказ відтяту голову ватажка шипогривів, який зухвало назвався «Оркбейном», тобто погибеллю орків, — глибоке вдоволення для орків, що боронять Пустки, і запорука їхньої безпеки."},sec={{t="Падіння ватажка",b="Вийшовши з Рейзорфен Краулу на південь Пусток, Лок Оркбейн разом зі своїми підручними Наком і Кузом очолив запеклі напади шипогривів-Гостроманів на шляхи постачання Орди. Зрадивши Понівечозуба й покинувши його в полоні в Таборі Тауражо, Лок здобув похмуру славу серед орків-оборонців, які ледве стримували його безжальні набіги. Здобути Локів череп — це не лише помститися за скривдженого бранця, що й вказує поборникам Орди дорогу до Локового табору, а й знищити саму верхівку, яка веде наступ Гостроманів."},{t="Доказ для Перехрестя",b="Понівечозуб вимагає черепи всіх трьох змовників, щоб утамувати власну жагу помсти, але Локів череп повертає — його слід віднести на північ, до Торка на Перехресті. Торк і командування Орди підозрювали, що за набігами стоїть якийсь інший шипогрив, тож моторошний трофей стає для них цілковитою несподіванкою й остаточним доказом: загрозу центральним торговим шляхам Пусток рішуче відсічено."}},faq={{q="Хто такий Лок Оркбейн?",a="Лок Оркбейн — грізний воїн Гостроманів, що вийшов із Рейзорфен Краул, щоб очолити загони шипогривів-грабіжників на півдні Пусток. Відомий ненавистю до орків і хитрою тактикою, він разом із вірними спільниками Наком і Куз влаштовував зухвалі напади на каравани й застави Орди.",al={"хто такий лок","історія лока оркбейна","хто був лок оркбейн"}},{q="Навіщо Понівечозубу Череп Лока?",a="Лок Оркбейн і його спільники зрадили Понівечозуба й кинули його, тож таурени з Табору Тауражо спіймали його й замкнули в клітці. Знаючи, що загибелі не минути, Понівечозуб мститься родичам, які відвернулися від нього, — посилає шукачів пригод Орди стратити його колишніх товаришів.",al={"чому понівечозуб хоче череп","помста понівечозуба","чому вбити лока"}},{q="Чому череп несуть Торкові на Перехрестя?",a="Торк керує обороною Перехрестя й захищає важливі шляхи постачання Орди від набігів шипогривів. Череп Лока доводить командирові-оркові, що справжнього призвідця південних набігів убито, — і мандрівникам краю стає спокійніше.",al={"чому нести череп торкові","торк череп лока","хто бере череп лока"}},{q="Хто такі Нак і Куз?",a="Нак і Куз — інші ватажки набігів разом із Локом Оркбейном на півдні Пусток. Понівечозуб описує одного як заклинача, а другого як слідопита: вони доповнювали воїнську силу Лока, спрямовуючи набіги на Орду.",al={"нак і куз","лейтенанти лока оркбейна","куз і нак"}}},fp="11,310,18.521.0,24.408.1,20.299.0,38.295.0,52.276.0,21.222.0"}
P.entries["item:lonebrow-s-journal"] = {n="Щоденник Лоунброу",s="Щоденник Лоунброу — пошарпаний записник, який знайшли в кістлявих руках дворфа-дослідника Генріґа Лоунброу біля підніжжя Великого Підйомника. Його сторінки розповідають про останню похмуру мандрівку Лоунброу Тисячею Голок і вказують на небезпеки, що причаїлися в Рейзорфен Краулі.",h="Щоденник Лоунброу — пошарпаний записник, який знайшли в кістлявих руках дворфа-дослідника Генріґа Лоунброу...",kw={"щоденник лоунброу","генріґ лоунброу","фалфіндел вейвордер","рейзорфен краул","чарлґа рейзорфленк","великий підйомник"},ang={["faction:Alliance"]="Останні записи Генріґа Лоунброу стають важливою ланкою між розвідниками Альянсу та друїдами, що стережуть кордон Фераласу, і згуртовують допомогу проти загрози шипогривів.",["race:Dwarf"]="Натрапити на полеглого родича в такому віддаленому, ворожому краю — сумне нагадування про небезпеки, які чигають на дворфів-дослідників далеко за межами Каз Модану."},sec={{t="Остання воля біля Великого Підйомника",b="Генріґ Лоунброу знайшов свій сумний кінець біля підніжжя Великого Підйомника, що з'єднує Пустки з Тисячею Голок. Його кістяк, покинутий на скелястому виступі, досі стискає цей пошарпаний щоденник. Записи свідчать про його останні мандри й просять того, хто їх знайде, переказати звістку нічному ельфові-друїду Фалфінделу Вейвордеру в Таланаарі — прикордонній заставі на шляху до Фераласу. Нотатки Лоунброу кидають важливе світло на загрозу шипогривів, що назріває на півдні Пусток."},{t="Ниточка до Рейзорфену",b="Коли щоденник потрапляє до Фалфіндела Вейвордера, записи Лоунброу підтверджують дедалі більшу тривогу Альянсу щодо шипогривів Рейзорфен Краулу. Його зміст веде просто до заклику героїв ударити в саме серце колючого лабіринту й здолати Чарлґу Рейзорфленк — Стару з Краулу, що спрямовує загрозу шипогривів."}},faq={{q="Хто такий Генріґ Лоунброу?",a="Генріґ Лоунброу — дворф-мандрівник, що загинув біля підніжжя Великого Підйомника в Тисячі Голок. Він помер, стискаючи в руці щоденник, і хотів, щоб записи дійшли до нічних ельфів у Таланаарі.",al={"генріґ лоунброу","хто такий лоунброу","мертвий дворф підйомник"}},{q="Де знайти щоденник?",a="Щоденник лежить біля скелета Генріґа Лоунброу трохи осторонь від схилу біля підніжжя Великого Підйомника, на низькому скелястому виступі на півночі Тисячі Голок.",al={"де щоденник лоунброу","знайти щоденник лоунброу","скелет біля великого підйомника"}},{q="Кому слід віднести Щоденник Лоунброу?",a="Щоденник треба віднести на захід через Тисячу Голок до Фалфіндела Вейвордера — друїда нічних ельфів у Таланаарі на кордоні з Фераласом.",al={"кому віднести щоденник","фалфіндель вейвордер","куди здати щоденник"}},{q="До чого веде щоденник?",a="Прочитавши щоденник і доповівши Фалфінделу Вейвордеру, ви дізнаєтеся відомості про шипогривів, які ведуть до вилазки в Рейзорфен Краул, щоб здолати каргу Чарлґу Рейзорфленк.",al={"завдання відьма краулів","продовження щоденника лоунброу"}}},fp="18,282,30.496.0,20.329.1,24.221.0,27.151.0,38.150.0,30.176.1"}
P.entries["item:lorgalis-manuscript"] = {n="Рукопис Лорґаліса",s="Рукопис Лорґаліса — давній текст, пов'язаний із поклонінням Древнім Богам і переказами про них, що вцілів у зруйнованих ельфійських руїнах під Ашенвалем. Схований у затопленому храмовому комплексі Чорноглибинних Печер, він таїть секрети, яких жадають темні вчені, що прагнуть пробудити прадавні дрімотні сили.",h="Рукопис Лорґаліса — давній текст, пов'язаний із поклонінням Древнім Богам і переказами про них, що вцілів у...",kw={"рукопис лорґаліса","ґерріґ боунґріп","древні боги","чорноглибинні печери","айронфордж","сектанти"},ang={["class:Warlock"]="Рукопис — рідкісний місток між прадавніми магічними знаннями ельфів і забороненими сутностями глибин, і він таїть відомості, яких жадають ті, хто торгує темними мистецтвами.",["race:NightElf"]="Текст написали прадавні предки нічних ельфів ще до того, як їхній храм поглинули хвилі, але його одержимість дрімотними темними силами робить рукопис трагічною реліквією минулого їхньої цивілізації."},sec={{t="Книга тих, хто спить",b="Рукопис Лорґаліса походить із часів величних ельфійських храмів, що стояли ще до Великого Розколу, і він пережив катастрофічну повінь, яка затопила руїни Блекфатому. Ельфи давнини збирали глибокі таємниці, і частина їхніх архівів записувала темніші сили. Рукопис містить могутні знання, пов'язані просто з Древніми Богами, — знання, які, кажуть, відчиняють містичні двері й пробуджують прадавні сутності, що сплять глибоко під світом. Схований у подзьобаній іржею залізній скрині серед затоплених коридорів, він привернув увагу і сектантів, і вчених тіні."},{t="Очі в тіні",b="У Покинутій Печері Айронфорджа дивакуватий збирач на ім'я Ґерріґ Боунґріп охоче наймає відважних шукачів пригод, щоб вони вирушили за море й здобули текст. Боунґріп побожно говорить про «останні дні» й пробудження сплячих божеств. Здобутий текст мають переписати й поширити серед його темного кола братів і сестер, розносячи заборонені знання, які мешканцям поверхні ніколи не судилося збагнути."}},faq={{q="Що таке Рукопис Лорґаліса?",a="Це прадавній ельфійський текст із темними, потаємними знаннями про Древніх Богів. Кажуть, у ньому приховано таємниці, потрібні, щоб відчиняти брами й пробуджувати сплячі первісні сутності.",al={"що таке рукопис лорґаліса","книга лорґаліса","що робить рукопис"}},{q="Де лежить рукопис?",a="Рукопис лежить у поточеній іржею залізній скрині глибоко під водою в Чорноглибинних Печерах — зруйнованому храмі нічних ельфів на Узбережжі Зорам в Ашенвалі.",al={"де знайти рукопис лорґаліса","місце рукопису","скриня чорноглибинних печер"}},{q="Кому потрібен рукопис?",a="Ґерріґ Боунґріп, загадковий хранитель знань із Покинутої Печери в Айронфорджі, доручає шукачам пригод його повернути. Він хоче переписати й поширити його прадавнє вчення серед своїх потаємних однодумців.",al={"кому потрібен рукопис","завдання ґерріґа боунґріпа","хто такий боунґріп"}},{q="Чому Ґерріґ Боунґріп говорить про кінець днів?",a="Боунґріп належить до тих, хто вивчає Древніх Богів і поклоняється їм. Його цікавлять прадавні ельфійські писання саме тому, що в них є знання, здатні пробудити «Тих, Хто Спить», — і провістити те, що він вважає прийдешнім кінцем часів.",al={"ґерріґ про кінець днів","культист боунґріп","боунґріп давні боги"}}},fp="19,301,25.577.0,19.443.1,32.201.0,32.161.0,25.210.0,49.217.0"}
P.entries["item:lunar-fungus"] = {n="Місячний Гриб",s="Місячний Гриб — сильний лікувальний наріст, який збирають із грибних цвітінь глибоко в печерах Темного Узбережжя. Новачки-друїди збирають ці гриби разом зі звичайними травами, щоб зварити відновлювальну мазь для лікування хворої звірини.",h="Місячний Гриб — сильний лікувальний наріст, який збирають із грибних цвітінь глибоко в печерах Темного...",kw={"місячний гриб","аланндаріан найтсонг","коло кенарія","друїди","земнокорінь","темне узбережжя"},ang={["class:Druid"]="Молоді друїди шукають Місячний Гриб у печерах Темного Узбережжя в межах перших обрядів, щоб опанувати цілющу магію й лікувати отруєних звірів.",["race:NightElf"]="Лікувати зіпсованих лісових створінь довкола Обердайна місцевими засобами на кшталт Місячного Гриба — постійний обов'язок охоронців Темного Узбережжя."},sec={{t="Властивості й середовище",b="Цей своєрідний гриб, який збирають із Місячних Грибних Цвітінь, буяє в темних підземних печерах по всьому Темному Узбережжю. Коло Кенарія цінує його за підсилювальну дію: змішаний із заспокійливою водною основою та звичайним земляним коренем, гриб дає потрібну силу, щоб створити дієвий засіб проти виснажливих недуг. Оскільки росте він переважно в сирих підземеллях, куди часто навідуються войовничі місячники, щоб його здобути, доведеться обережно пробиратися дикими нетрями."},{t="Урок зцілення",b="В Обердайні Аланндаріан Найтсонг посилає молодих друїдів збирати Місячний Гриб у межах навчання відновлювальних мистецтв природи. Бачачи, як реагенти на кшталт цього гриба протидіють підступним отрутам у місцевих оленів, новачки засвоюють основи трав'яного лікування, перш ніж навчитися спрямовувати природні протиотрути безпосередньо — через зміну подоби й чисту духовну силу."}},faq={{q="Для чого потрібен Місячний Гриб?",a="Місячний Гриб додає цілющої сили мазі, що відновлює здоров'я. Аланндаріан Найтсонг поєднує його із Земнокоренем і чистою водою, щоб лікувати хворих оленів по всіх нетрях Темного Узбережжя.",al={"призначення місячного гриба","що робить місячний гриб","навіщо збирати місячний гриб"}},{q="Де росте Місячний Гриб?",a="Він проростає з Місячних Грибних Квітів, що ховаються в печерах на схід від Обердайна на Темному Узбережжі. У цих темних печерах живуть дратівливі місячники, що боронять свою територію від непроханих гостей.",al={"де росте місячний гриб","місце місячного гриба","де знайти місячний гриб"}},{q="Кому в Обердайні потрібен цей гриб?",a="Друїд Аланндаріан Найтсонг просить учнів дикої природи принести Місячний Гриб як частину їхнього навчання й використовує його природні цілющі властивості, щоб готувати ліки для хворих лісових тварин.",al={"кому потрібен місячний гриб","травницьке завдання обердайна"}},{q="Чому друїди-новачки мусять збирати справжні трави, щоб вилікувати отруту?",a="Розуміння речових протиотрут — основа друїдської науки. Збираючи дикі реагенти, як-от Місячний Гриб, і спостерігаючи, як певні складники протидіють певним отрутам, учні опановують засади зцілення, перш ніж навчитися виганяти отруту безпосередньо духовною магією.",al={"чому друїди збирають трави","навчання друїдів лікування отрути"}}},fp="12,240,22.504.0,19.400.0,30.197.0,29.189.0,38.198.0,68.296.0"}
P.entries["item:lurker-venom"] = {n="Отрута Причаєної",s="Отрута Причаєної — сильна природна отрута хижих павуків, що нишпорять кам'янистими пагорбами й лісами Лох Модану. Дворфійським оборонцям ця їдка отрута потрібна як головний складник алхімічної знешкоджувальної суміші проти диверсій Темного Заліза.",h="Отрута Причаєної — сильна природна отрута хижих павуків, що нишпорять кам'янистими пагорбами й лісами Лох...",kw={"отрута причаєної","павуки","лох модан","шанда ткаля","знешкоджувальна суміш","темне залізо"},ang={["profession:Engineering"]="Знешкодити ворожу вибухівку органічною отрутою — це винахідлива, імпровізована гілка дворфійської інженерії в бойових умовах.",["race:Dwarf"]="Горяни й оборонці Лох Модану раз у раз обертають небезпеки дикої місцини собі на користь, щоб захистити важливі споруди Каз Модану від клану Темного Заліза."},sec={{t="Небезпечний реагент",b="Пагорби й скелі навколо Лох Модану кишать хижими павуками — від звичайних лісових причаюнів до горезвісної матріархині Шанди Ткалі. Їхні укуси — постійна небезпека для горян і мандрівників, але знавець вибухівки Ешлан Стоунсмерк назвав їхню люту отруту одним зі складників знешкоджувальної суміші, яку готує Головний Інженер Гіндервір. У поєднанні з рідкісними мінералами й сльозами озерних кроколісків Отрута Причаєної утворює активний розчинник, здатний обеззброїти складну вибухівку Темного Заліза."}},faq={{q="Звідки береться Отрута Причаєної?",a="Її добувають із різних павучих причаєних Лох Модану — скельних, лісових і деревних, а також їхньої матріархині Шанди Ткалі.",al={"як отримати отруту причаєної","хто дропає отруту причаєної","де взяти отруту причаєної"}},{q="Для чого потрібна Отрута Причаєної?",a="Головний Інженер Гіндервір додає отруту до особливої хімічної суміші, щоб знешкодити вибухові пристрої, які диверсанти Темного Заліза заклали довкола Каменетесної Греблі.",al={"навіщо мені отруту причаєної","призначення отрути причаєної","що гіндервейр робить з отрутою"}},{q="Навіщо отрута, щоб знешкодити вибухівку?",a="Дворфські інженери часто вдаються до реактивних, кислотних чи їдких сумішей, щоб розчинити тонкі механічні деталі чи знешкодити нестійкий вибуховий порошок, не підірвавши його.",al={"чому павуча отрута для бомб","як отрута зупиняє бомби темного заліза"}},{q="Чи Шанда Ткаля — єдине джерело отрути?",a="Ні. Отруту має й Шанда, але її може дати будь-яка звичайна дика павучиха-причаєна, що живе в лісах і на скелястих кручах Лох Модану.",al={"чи треба вбивати шанду","отрута причаєної шанди"}}},fp="12,267,18.543.0,34.170.0,30.189.0,37.177.0,38.143.0"}
P.entries["item:lydon-s-toxin"] = {n="Токсин Лідона",s="Токсин Лідона — алхімічне вариво, яке Аптекар Лайдон синтезував у Таррен Міллі, щоб зірвати вирубку лісів Венчурною Компанією в Горах Кам'яного Кігтя. Його довіряють шукачам пригод Орди, і вони доставляють токсин Аптекарці Замах у Тандер Блаф, щоб вона придумала дієвий спосіб його застосувати.",h="Токсин Лідона — алхімічне вариво, яке Аптекар Лайдон синтезував у Таррен Міллі, щоб зірвати вирубку лісів...",kw={"токсин лідона","аптекар лайдон","аптекарка замах","королівське аптекарське товариство","венчурна компанія","гори кам'яного кігтя","розпилювач токсинів"},ang={["race:Tauren"]="Таурени вітають допомогу проти Венчурної Компанії, що нищить природу, але хімічні методи Королівського Аптекарського Товариства випробовують межі їхніх шаманських переконань.",["race:Undead"]="Перевезення Токсину Лідона — яскравий приклад розгалуженої мережі Королівського Аптекарського Товариства, що узгоджує польові дослідження між Лордероном і Калімдором, аби довести союзникам корисність Відступників."},sec={{t="Рішення від Королівського Аптекарського Товариства",b="Цю отруйну сполуку Аптекар Лайдон створив у Передгір'ї Гілсбреда для боротьби з лісорубами Венчурної Компанії, що спустошують Гори Кам'яного Кігтя. За словами Лайдона, від дотику вариво спричиняє смертельні наслідки й може бути заразним. Але перш ніж пустити речовину в хід проти гоблінських робіт довкола Кручі Вітрорізу, її треба переправити через континенти до Аптекарки Замах — представниці Королівського Аптекарського Товариства в Тандер Блафі. Замах потрібна сира суміш, щоб сконструювати пристрій для широкого розпилення — Розпилювач Токсинів, — аби вариво знищило хижих лісорубів, не наражаючи без потреби на небезпеку надбання Орди."}},faq={{q="Для чого потрібен Токсин Лідона?",a="Токсин створив Аптекар Лайдон, щоб послабити хватку Венчурної Компанії на Кручі Вітрорізу. Він має завдати нищівного удару гоблінам-робітникам, що плюндрують край, а може, й поширитися між ними як зараза.",al={"призначення токсину лідона","що робить токсин","навіщо токсин лідона"}},{q="Хто такий Аптекар Лайдон?",a="Аптекар Лайдон — член Королівського Аптекарського Товариства з Таррен Мілла в Передгір'ї Гілсбреда. Він спеціалізується на лютих отрутах і експериментальних сумішах, що служать цілям Відступників.",al={"хто такий лайдон","аптекар лайдон","творець токсину"}},{q="Чому токсин треба доставити в Тандер Блаф?",a="Лайдон довів хімічну суміш до ладу, але не має практичного способу застосувати її на широкому просторі. Аптекарка Замах, що живе на Узвишші Духів у Тандер Блафі, вивчає рослини краю й керує справами Товариства в Калімдорі; вона бере токсин, щоб перетворити його на переносний розпилювач.",al={"чому тандер блаф","чому нести токсин замаху","навіщо аптекар замах"}},{q="Що стається, коли Замах отримує токсин?",a="Отримавши фіал, Аптекарка Замах перетворює речовину на аерозоль під тиском — Розпилювач Токсинів, — щоб агент міг розвіяти отруту в самому серці табору Венчурної Компанії.",al={"створення токсичного туманогена","що замах робить з токсином"}}},fp="13,300,27.697.0,31.212.0,24.227.0,47.293.0,44.213.0"}
P.entries["item:macgrann-s-dried-meats"] = {n="В'ялене М'ясо МакГранна",s="В'ялене М'ясо МакГранна — місячний запас солоних харчів, які мисливець Тундра МакГранн заготував, щоб пережити сувору зиму Дун Мороґу. Увесь запас, схований у посиленій торієвій м'ясній скрині, поцупив лютий єті, відомий як Старий Айсбірд.",h="В'ялене М'ясо МакГранна — місячний запас солоних харчів, які мисливець Тундра МакГранн заготував, щоб...",kw={"в'ялене м'ясо","тундра макгранн","старий айсбірд","єті","зимовий запас","торієва скриня","долина холодного вітерцю"},ang={["profession:Cooking"]="Соління й в'ялення дичини — основна кулінарна навичка виживання в Дун Мороґу, що дає мисливцям, як-от МакГранн, зберігати м'ясо місяцями, не боячись, що воно зіпсується на морозі.",["race:Dwarf"]="Дворфійські горяни добре знають: у високих горах підготовка означає виживання, а втрачений зимовий запас може стати різницею між життям і смертю."},sec={{t="Зимовий запас",b="Життя серед крижаних скель Дун Мороґу вимагає ретельного планування. Готуючись до заметілей холодної пори, дворф-мисливець Тундра МакГранн тижнями полював на дичину, солив м'ясо й ховав його до міцної скрині. Знаючи, що ведмеді-падложери та хижаки раз у раз дошкуляють його обійстю, МакГранн не ризикував і замкнув харчі в торієвій м'ясній скрині. Та навіть із цими пересторогами він не передбачив зайду, достатньо дужого, щоб понести всю скриню, замість ламати її на місці."},{t="До лігва єті",b="Поки МакГранн вистежував оленів, сумнозвісний єті Старий Айсбірд напав на табір мисливця й затягнув важку скриню до свого лігва в Долині Холодного Вітерцю. Хоч звір і не мав чим пробити суцільне торієве обшиття, через поранену ногу МакГранн не міг швидко вирушити до печери по своє добро. Без сторонньої допомоги, щоб повернути запас до настання зими, безпорадний мисливець опинився перед загрозою голоду серед гірських снігів."}},faq={{q="Що таке В'ялене М'ясо МакГранна?",a="Це місячний запас солоного провіанту, який заготував Тундра МакГранн, щоб пережити люту зиму в Дун Мороґу.",al={"що таке в'ялене м'ясо макґранна","м'ясо тундри","схованка м'яса макґранна"}},{q="Чому м'ясо замкнули в скрині?",a="У Дун Мороґу аж кишить голодними хижаками, як-от гірськими ведмедями. МакГранн тримав в'ялене м'ясо в міцній торієвій скрині для м'яса, щоб звірі-падальники не розтерзали його зимових запасів.",al={"чому м'ясо замкнули","чому торієвий сейф","скриня макґранна"}},{q="Хто вкрав скриню з м'ясом?",a="Грізний єті на ім'я Старий Айсбірд украв усю скриню, поки МакГранн полював на оленів, і затягнув важку посудину до свого печерного лігва в Долині Холодного Вітерцю.",al={"хто вкрав м'ясо","хто його вкрав","злодій м'ясної скрині"}},{q="Чому Тундра МакГранн не може сам повернути м'ясо?",a="У МакГранна поранена нога, тож йому бракує швидкості й скритності, щоб прослизнути в лігво Старого Айсбірда й утекти, перш ніж лютий єті зажене його в кут.",al={"чому макґранн не забирає сам","чому тундрі потрібна допомога","тундра поранена"}}},fp="22,261,14.556.0,20.457.0,32.126.0,37.208.0,26.173.0,53.164.0"}
P.entries["item:mackreel-s-moonshine"] = {n="Самогон МакКрила",s="Цей самогон — міцний дворфійський трунок, який жене Фоґґі Маккріл, що служить на зруйнованому Мосту Тандол на півночі Багнокраю. Він досить міцний, щоб звалити з ніг вартового на посту, і цінується аж на півночі, у Саутшорі, де Броварник Білґер приймає його як плату за борги.",h="Цей самогон — міцний дворфійський трунок, який жене Фоґґі Маккріл, що служить на зруйнованому Мосту Тандол на...",kw={"самогон маккріла","фоґґі маккріл","броварник білґер","міст тандол","саутшор","самогон"},ang={["profession:Cooking"]="Хоч це грубий самогон, а не вишукане кулінарне вино, такі міцні місцеві трунки, як у Фоґґі, — звичний товар у прикордонних шинках.",["race:Dwarf"]="Дворфи впізнають добрий міцний трунок за запахом, і самогон Фоґґі явно має досить сили, щоб звалити з ніг навіть горянина."},sec={{t="Міцне вариво",b="Цей самогон, який жене вартовий Фоґґі Маккріл на Мосту Тандол, має сумнозвісну славу через свою міцність. Навіть загартовані дворфи-вартові падають з ніг після ночі з цим трунком і прокидаються з таким головним болем, ніби над ними прокотилася ціла бригада облогових машин. Попри нищівний удар, його високо цінують, бо він зігріває мандрівників у вогкі холоди Лордерона й Каз Модану."},{t="Плата до Саутшора",b="Фоґґі Маккріл заборгував Броварникові Білґеру — шинкареві й головному пивоварові Саутшора. Щоб розрахуватися, Фоґґі віддав замість монети партію свого самогону. Білґер радо приймає трунок замість золота, охочий поповнити свої запаси міцним варивом Маккріла на холодні прибережні дні в Передгір'ї Гілсбреда."}},faq={{q="Хто робить Самогон МакКрила?",a="Його гонить Фоґґі Маккріл — дворф-вартовий на зруйнованій ділянці Мосту Тандол між Багнокраєм і Аратійським нагір'ям.",al={"творець самогону маккрила","хто його зварив","туманний маккрил лікер"}},{q="Чому цей самогон посилають до Саутшора?",a="Фоґґі Маккріл заборгував Броварникові Білґеру в Саутшорі. Замість монет він погодився сплатити прострочений борг свіжою партією свого самогону.",al={"чому в саутшор","доставка самогону","борг пивовара білджера"}},{q="Наскільки міцний Самогон МакКрила?",a="Надзвичайно міцний. Фоґґі визнає, що, випивши його, знепритомнів просто на посту, а потім скаржився на головний біль, наче по його черепу прогуркотіла ціла бригада облогових машин.",al={"наскільки міцний","міцність самогону","ефекти самогону маккрила"}},{q="Чому доставку треба квапити?",a="Фоґґі добряче випив і проспав свою варту, а прокинувшись, зрозумів, що до кінця строку сплати боргу Броварникові Білґеру лишилися лічені хвилини.",al={"чому на час","чи завдання на час","чому поспішати"}}},fp="20,277,13.397.0,21.353.0,31.148.0,47.170.0,35.207.0,40.163.0"}
P.entries["item:maggot-eye-s-paw"] = {n="Лапа Червивого Ока",s="Лапа Червивого Ока — моторошний трофей, здобутий із вождя гнолів Червивого Ока в Лігві Гаррена. Принесена до Брілла, вона слугує речовим доказом страти звіра за грабунок могил на користь Погибелі.",h="Лапа Червивого Ока — моторошний трофей, здобутий із вождя гнолів Червивого Ока в Лігві Гаррена.",kw={"лапа червивого ока","червиве око","гноли","лігво гаррена","екзекутор зиґанд","брілл"},ang={["race:Undead"]="Для Відступників з Брілла принести лапу Червивого Ока — прямий удар по викрадачах тіл, що постачають ненависному Королю-Лічу сировину."},sec={{t="Доказ страти",b="Червиве Око накликало на себе суворий гнів Відступників, грабуючи могили й плюндруючи околиці Лігва Гаррена: воно постачало трупи, щоб поповнювати армії, якими командує Король-Ліч. У відповідь у містечку Брілл оголосили офіційний смертний вирок і нагороду. Оскільки для військових адміністраторів на кшталт Екзекутора Зиґанда самих чуток про смерть ніколи не досить, мисливці за головами мусять відтяти лиходієві лапу й принести її до міста, щоб отримати винагороду й закрити справу."}},faq={{q="Навіщо Екзекуторові Зиґанду лапа Червивого Ока?",a="Екзекутор Зиґанд вимагає незаперечного доказу, що засудженого гнола справді покарано. Відтята лапа — речове підтвердження страти, лише тоді Брілл виплатить винагороду.",al={"чому лапа","доказ нагороди червивого ока","лапа зиґанда"}},{q="Які злочини Червиве Око вчинив проти Відступників?",a="Червиве Око водив грабіжницькі набіги по півночі Галявин Тірісфалю — зокрема крав поховані трупи з хуторів, як-от Лігва Гаррена, щоб постачати війська Короля-Ліча.",al={"злочини червивого ока","чому червивого ока розшукують","що накоїв червиве око"}},{q="Де знайти Червиве Око?",a="Червиве Око засів у Лігві Гаррена — зруйнованому хуторі на північний схід від Брілла в Галявинах Тірісфалю, зазвичай ховається в напівзруйнованій хаті.",al={"місце червивого ока","де знайти червиве око","гнол прихисток гаррена"}},{q="Чому гноли співпрацюють із військами Короля-Ліча?",a="Гноли від природи — хижі падальники, що шукають вигоди, а свавільні ватаги в Галявинах Тірісфалю вступили в союз із Погибеллю чи потрапили під її владу: вони грабують могили людей і Відступників, щоб постачати тіла некромантам.",al={"гноли та погибель","чому гноли крадуть тіла","гноли погибелі"}}},fp="16,220,18.480.0,47.191.0,55.190.0,26.153.0,51.210.0"}
P.entries["item:maggran-s-reserve-letter"] = {n="Резервний Лист Маґрана",s="Резервний Лист Маґрана — офіційне донесення, написане Маґґраном Ертбайндером у Притулку Сонячної Скелі. Перенесений через Калімдор до Великого Підйомника, він дає вартовому, що там служить, довгоочікувану заміну, щоб той міг повернутися додому й навідати родину.",h="Резервний Лист Маґрана — офіційне донесення, написане Маґґраном Ертбайндером у Притулку Сонячної Скелі.",kw={"резервний лист маґрана","маґґран ертбайндер","ґріш лонґраннер","великий підйомник","притулок сонячної скелі","калімдор"},ang={["faction:Horde"]="Послання показує повоєнні зусилля Орди дбати про свої розпорошені сили, змінюючи вартових на віддалених заставах Калімдору свіжими резервами."},sec={{t="Вартовий отримує заміну",b="Утримання застав на суворих просторах Калімдору вимагає пильності, але проводирі Орди розуміють, що тривала варта тяжко б'є по бойовому духу. Це просте послання, яке Маґґран Ертбайндер написав серед високих скель Притулку Сонячної Скелі, — офіційний наказ, що сповіщає Ґріша Лонґраннера: на його пост біля Великого Підйомника вже вислано воїна на заміну. Для самотнього вартового, що стереже височенні дерев'яні лебідки далеко на півдні, лист обіцяє рідкісну в неспокійні часи річ — почесну відпустку, щоб побачитися з родиною."}},faq={{q="Для чого Резервний Лист Маґрана?",a="У листі — офіційний наказ Маґґрана Ертбайндера звільнити вартового Ґріша Лонґраннера з посту біля Великого Підйомника на півдні Пусток, щоб той міг повернутися додому й навідати родину.",al={"що робить цей лист","призначення листа маґрана","навіщо доставляти лист"}},{q="Хто написав лист?",a="Лист написав Маґґран Ертбайндер, старійшина з Притулку Сонячної Скелі в Горах Кам'яного Кігтя.",al={"хто його написав","автор резервного листа","маґґран ертбайндер"}},{q="Кому призначено лист?",a="Його адресовано Ґрішу Лонґраннеру — вартовому Орди на вершині Великого Підйомника, що з'єднує південь Пусток із Тисячею Голок.",al={"кому лист","одержувач листа","куди він"}},{q="Куди доставляють лист?",a="Його треба нести на південь через Пустки, до краю каньйону Тисячі Голок, де стоїть Великий Підйомник.",al={"місце доставки","де гріш","місце великого підйомника"}}},fp="24,235,17.589.0,48.205.0,21.113.0,27.142.0,30.116.0"}
P.entries["item:mangy-claw"] = {n="Облізла Лапа",s="Облізла Лапа — відрубана лапа великого крижанокігтого ведмедя Дробкігтя з Дун Мороґу. Це похмурий доказ того, що смертоносного звіра, який убив безпорадного дворфійського пілота, нарешті вбито.",h="Облізла Лапа — відрубана лапа великого крижанокігтого ведмедя Дробкігтя з Дун Мороґу.",kw={"облізла лапа","дробкіготь","ведмідь","гільдельве","пілот гаммерфут","облогова бригада","помста"},ang={["class:Hunter"]="Вистежити такого сумнозвісного хижака, як Дробкіготь, серед лютих гірських заметілей — перевірка вміння мисливця приборкувати небезпечних звірів, що стережуть свою територію.",["race:Dwarf"]="Для дворфів виконати передсмертну волю полеглого товариша й помститися за члена Облогової Бригади Айронфорджа — справа глибокої особистої та кланової честі."},sec={{t="Передсмертне бажання пілота",b="Коли паровий танк Пілота Гільдельве зламався серед замерзлих пагорбів Дун Мороґу, він продовжив шукати руду пішки й опинився сам на сам із гірською пусткою. Як записано в його знайденому щоденнику, Гільдельве зумів відбити перший напад велетенського крижанокігтого ведмедя на ім'я Дробкіготь, хоча звір жорстоко пошматував його в тій сутичці. Пізніше хижак повернувся добити ослаблого пілота. Останній запис Гільдельве благав про помсту хижакові — і цю справу завершено, коли з убитого ведмедя взято Облізлу Лапу."},{t="Помста за Облогову Бригаду",b="Облізла Лапа, принесена Пілотові Гаммерфуту, дарує Обложній Бригаді Айронфорджа гірке заспокоєння. Гаммерфут розсилав шукачів по заметах, сподіваючись знайти друга живим, та дізнався лише про його страшну долю. Щоденник Гільдельве разом із відрубаною лапою хижака доводить, що передсмертне прохання Гільдельве виконано: він упокоївся, а пілоти Айронфорджа вдячні."}},faq={{q="Що таке Облізла Лапа?",a="Це трофей, відтятий від Дробкігтя — лютого крижанокігтого ведмедя, що чатує в Дун Мороґу. Вона — речовий доказ того, що звіра вистежено й убито.",al={"призначення облізлої лапи","що це за лапа","предмет дробкіготь"}},{q="Кому потрібна Облізла Лапа?",a="Пілот Гаммерфут, що стоїть біля гірських перевалів Дун Мороґа, шукає лапу разом із щоденником свого загиблого друга Гільдельве, щоб пересвідчитися, що ведмідь-убивця мертвий.",al={"хто бере облізлу лапу","здати облізлу лапу","здати пілотові хаммерфуту"}},{q="Чому на Дробкігтя треба було полювати?",a="Дворф-пілот Гільдельве пішки шукав руду, коли зламався його паровий танк, і Дробкіготь покалічив, а зрештою вбив його. Передсмертним проханням Гільдельве, записаним в особистому щоденнику, було, щоб хтось помстився звірові.",al={"чому полювати на дробкіготь","хто загинув від дробкігтя","історія гільдельве"}},{q="Де никає звір Дробкіготь?",a="Дробкіготь никає засніженими хребтами й пагорбами Дун Мороґа неподалік від місця, де знайшли останки пілота Гільдельве.",al={"місце дробкігтя","де дробкіготь","дробкіготь дан морог"}}},fp="10,211,20.540.0,31.399.1,23.160.0,25.170.0,36.239.0,36.118.0"}
P.entries["item:marshal-haggard-s-badge"] = {n="Відзнака Маршала Геггарда",s="Відзнака Маршала Геггарда — символ звання й влади, який Маршал Гаґґард носив на службі королівству Стормвінд. Викрадена хитрощами бандитом Дефіас Джеком Мертвозубом, відзнака становить небезпечну загрозу як знаряддя для видавання себе за міських урядовців.",h="Відзнака Маршала Геггарда — символ звання й влади, який Маршал Гаґґард носив на службі королівству Стормвінд.",kw={"відзнака","маршал гаґґард","джек мертвозуб","братство дефіас","маршал дуґан","обман"},ang={["class:Warrior"]="Повернення відзнаки Гаґґарда доводить вашу стійкість ветеранові війська Стормвінда, який винагороджує перспективних воїнів доглянутою зброєю зі своїх бойових днів.",["faction:Alliance"]="Повернення відзнаки береже цілісність військового командування Стормвінда й не дає Братству Дефіас підірвати місцеву оборону зсередини."},sec={{t="Викрадена відзнака",b="Хоч Маршал Гаґґард давно пішов на спочинок у свою маленьку садибу на пагорбах Лісу Елвінн, його стара відзнака маршала Стормвінда досі має офіційну вагу. Під покровом ночі розбійник Дефіас на ім'я Джек Мертвозуб надягнув стормвіндську накидку й удав із себе Маршала Дуґана, командира гарнізону Ґолдширу. Повіривши, що колишнім товаришам потрібна відзнака для службових справ, старий Гаґґард віддав її без жодної підозри. Джек утік у ліс, перш ніж відставний офіцер усвідомив обман. У руках Братства Дефіас такий знак влади Стормвінда може дозволити розбійникам проходити повз застави чи сіяти сум'яття серед тутешніх патрулів."}},faq={{q="Що таке Відзнака Маршала Геггарда?",a="Це офіційний знак звання з часів служби Маршала Гаґґарда королівству Стормвінд. Навіть у відставці така відзнака свідчить про колишнє військове становище й має справжню вагу.",al={"відзнака геггарда","відзнака маршала","відзнака маршала геггарда"}},{q="Як Мертвозубий Джек заволодів відзнакою?",a="Мертвозубий Джек підійшов до дому Маршала Гаґґарда під покровом темряви в табарді Стормвінда. У сутінках Гаґґард сприйняв його за Маршала Дуґана з Ґолдшира й віддав відзнаку, щойно той попросив.",al={"як вкрали відзнаку","хто вкрав відзнаку","хитрощі мертвозубого джека"}},{q="Чому відзнака небезпечна в руках Дефіас?",a="Зі справжньою маршальською відзнакою й переодягнений у форму агент Дефіас міг би видавати себе за високих посадовців Стормвінда, проходити повз вартових, проникати в гарнізони чи віддавати фальшиві накази міській варті.",al={"чому джек хоче відзнаку","використання відзнаки дефіас","небезпека відзнаки"}},{q="Де зберігається відзнака?",a="Мертвозубий Джек замкнув украдену відзнаку у своїй скрині, схованій у його таборі на південь від хутора Маршала Гаґґарда в Лісі Елвінн.",al={"місце відзнаки","де знайти відзнаку","скринька мертвозубого"}}},fp="23,290,17.675.0,32.203.0,38.208.0,54.201.0,24.147.0"}
P.entries["item:mary-s-looking-glass"] = {n="Дзеркальце Мері",s="Дзеркальце Мері — покинуте ручне дзеркальце, яким колись дорожила Сліпа Мері, доки трагедія не забрала в неї зір і життя. Кинуте в проклятих гаях Сутінколісся, воно дісталося гулеві-нишпорці, а згодом його розшукали, щоб завершити телескоп Вікторі Призм'Антраса.",h="Дзеркальце Мері — покинуте ручне дзеркальце, яким колись дорожила Сліпа Мері, доки трагедія не забрала в неї...",kw={"дзеркальце мері","сліпа мері","сутінколісся","телескоп","вікторі призм'антрас","гуль"},ang={["faction:Alliance"]="Повертаючи реліквії з лап жахіть, що чатують на Цвинтарі Тихих Садів, ви даруєте знесиленим мешканцям Даркшира бодай крихту спокою й допомагаєте міським задумам.",["profession:Engineering"]="Інженери оцінять винахідливість Вікторі, що перетворив старовинне хатнє дзеркальце на робочий оптичний відбивач для астрономічного приладу."},sec={{t="Покинутий скарб",b="До своєї жахливої долі Сліпа Мері дорожила цим відполірованим дзеркальцем. Але після страшної події, що коштувала Мері очей і життя, власне відображення стало для неї болісним нагадуванням про втрачене. Вона викинула дзеркальце за стодолу, лишивши його на поталу темряві Сутінколісся. Там його схопив пазурами Божевільний Гуль, що блукав зруйнованими околицями, і заніс дрібничку на південь, до склепів Цвинтаря Тихих Садів."},{t="Очі до небес",b="У Даркширі дивакуватий зорезнавець Вікторі Призм'Антрас мріяв зазирнути крізь вічні сутінки Сутінколісся в чисте небо над ними. Щоб збудувати телескоп, йому знадобилися особливі оптичні лінзи й дзеркальне скло. Дізнавшись про це, Мері скерувала шукачів пригод вистежити дику нежить, що нишпорить біля зруйнованої каплиці цвинтаря, і повернути дзеркальце: воно мало стати оптичним відбивачем у його величній машині для споглядання зірок."}},faq={{q="Чому Мері викинула дзеркальце?",a="Колись дзеркальце було однією з найдорожчих речей Мері, але вона викинула його за стодолу після випадку, про який не розповідає до кінця. В іншій розмові вона пояснює, що сама вирвала собі очі, бо не могла витримати свого вигляду.",al={"чому мері викинула","чому викинула дзеркальце","історія дзеркальця сліпої мері"}},{q="У кого опинилося дзеркало, коли Мері його викинула?",a="Викинуте дзеркало підібрав Божевільний Гуль, що блукав лісом за старим хутором Мері. Згодом ця збожеволіла нежить оселилася в покинутій каплиці на Цвинтарі Тихих Садів.",al={"у кого дзеркало","хто впустив дзеркальце","де дзеркальце"}},{q="Навіщо Вікторі Призм'Антрасу дзеркальце Мері?",a="Вікторі будує хитромудрий телескоп, щоб пробитися крізь морок Сутінколісся й вивчати зорі. Йому потрібна добра відбивна поверхня, щоб спрямовувати світло крізь прилад, і вціліле скло Мері ідеально пасує до його задуму.",al={"навіщо вікторі дзеркальце","використання дзеркальця вікторі","дзеркало телескопа"}},{q="Де знайти Божевільного Гуля з дзеркалом?",a="Божевільний Гуль ховається в далекому південно-східному куті Сутінколісся — зазвичай никає зруйнованою кам'яною каплицею на Цвинтарі Тихих Садів.",al={"місце божевільного гуля","де божевільний гуль","гуль тихих садів"}}},fp="20,269,19.454.0,19.443.0,42.239.0,53.200.0,56.227.0,55.147.0"}
P.entries["item:mathystra-relic"] = {n="Реліквія Матістри",s="Реліквії Матістри — давні артефакти нічних ельфів, розкидані серед зарослих руїн Матистри на півночі Темного Узбережжя. Хоч це лише рештки занепалої ельфійської твердині, у них досі дрімають уламки магії, що привернули увагу культу Молота Присмерку.",h="Реліквії Матістри — давні артефакти нічних ельфів, розкидані серед зарослих руїн Матистри на півночі Темного...",kw={"реліквія матістри","матистра","ону","молот присмерку","глефа володаря","темне узбережжя"},ang={["class:Druid"]="Працюючи пліч-о-пліч із прадавніми на кшталт Ону, друїди бережуть крихку рівновагу Темного Узбережжя, пильнуючи, щоб забуті магічні рештки не живили темних викликань.",["race:NightElf"]="Для калдореїв повернути ці реліквії — це водночас і вберегти небезпечні давні таємниці від Молота Присмерку, і вшанувати спадщину міста, втраченого під час Розколу."},sec={{t="Рештки занепалої твердині",b="До Великого Розколу Матистра була гордим містом і твердинею ельфійської цивілізації на узбережжі Калімдору. Сьогодні її повалені колони й потріскане каміння наполовину поглинули чагарі та морська імла, а серед руїн блукають неспокійні духи й чатують звірі. Руїнами розкидано давні реліквії тієї золотої доби. Хоч десять тисяч років занедбання їх і стерли, ці артефакти досі зберігають слабкі сліди ельфійського тайного ремесла, тож без нагляду вони стають небезпечною здобиччю."},{t="Насувна загроза",b="Древо Знань Ону шукає ці реліквії, відколи дізнався, що зловісний культ Молота Присмерку намагається обернути на зброю забуті ельфійські письмена, викопані біля Глефи Володаря. Культисти прагнуть приборкати давню магію калдореїв, щоб наблизити повернення своїх темних господарів. Вивчаючи ці розпорошені рештки, Ону й охоронці Темного Узбережжя сподіваються розгадати наміри культу й не дати згасаючій силі Матистри послужити темним цілям."}},faq={{q="Що таке Реліквії Матістри?",a="Це уламки й артефакти, що лишилися від прадавнього міста нічних ельфів Матістри. Хоч їм тисячі років, вони досі зберігають рештки магічної майстерності ельфійської цивілізації часів до Розколу.",al={"що таке реліквія матістри","ельфійські реліквії матістри","що за реліквії"}},{q="Де знайти ці реліквії?",a="Вони розкидані серед уламків каміння, повалених колон і високої трави в Руїнах Матістри на півночі Темного Узбережжя.",al={"місце реліквій матістри","де знайти реліквії","місця реліквій"}},{q="Кому потрібні Реліквії Матістри?",a="Древо Знань на ім'я Ону, що живе в Гаю Прадавніх на півдні Темного Узбережжя, просить мандрівників зібрати їх для вивчення.",al={"кому потрібні реліквії","кому нести реліквії","реліквії ону"}},{q="Чому ними цікавиться Молот Присмерку?",a="Культ розшифровує прадавні ельфійські тексти, знайдені неподалік, біля Глефи Володаря. Культисти прагнуть викривити й використати магічні таємниці давніх ельфів, щоб допомогти покликати у світ своїх тіньових господарів.",al={"чому молот присмерку хоче реліквії","молот присмерку матістра"}}},fp="15,261,28.491.0,15.479.1,30.227.0,29.153.0,31.135.0,48.223.0"}
P.entries["item:melenas-head"] = {n="Голова Меленаса",s="Голова Меленаса — відтята здобич, узята в Лорда Меленаса, сатирського ватажка, що отаборився всередині Скелі Скверни. Принесений як беззаперечний доказ його загибелі, трофей позначає тихе усунення застарілої демонічної загрози на вітті Тельдрассила.",h="Голова Меленаса — відтята здобич, узята в Лорда Меленаса, сатирського ватажка, що отаборився всередині Скелі...",kw={"голова меленаса","лорд меленас","сатир","скеля скверни","ґрелли","тінедол","тельдрассил"},ang={["class:Warrior"]="Нести відтяту голову ворожого воєводи — безпомильний, первісний доказ того, що небезпечного супротивника та його військо ґреллів зламано.",["race:NightElf"]="Сатири — трагічне демонічне спотворення прадавнього роду нічних ельфів, тож тиха страта Лорда Меленаса — водночас необхідність і культурний сором."},sec={{t="Негласна ганьба",b="Для нічних ельфів, що охороняють Тінедол і навколишні простори Тельдрассила, сама присутність сатирів на їхньому новому Світовому Дереві — гірка ганьба. Лорд Меленас улаштував лігво в покручених печерах Скелі Скверни, одразу на північ від ельфійських поселень, і згуртував під своїм стягом напасливих воїнів-ґреллів. Оскільки калдореї цінують стриманість, коли йдеться про скверну так близько до їхнього серця, цей кривавий трофей слугує негласним доказом: його підступи придушено, перш ніж його вплив устиг розповзтися."}},faq={{q="Хто такий Лорд Меленас?",a="Лорд Меленас — сатир-командир, що засів у печері, відомій як Скеля Скверни, на Тельдрассилі. Він зібрав під своєю орудою ватагу греллів, щоб строїти підступи проти довколишніх застав калдореїв.",al={"хто такий меленас","історія лорда меленаса","розповідь про меленаса"}},{q="Чому його смерть має лишитися таємницею?",a="Сатири — прадавні прокляті нічні ельфи, спотворені демонічною скверною, — так близько від священних гілок Тельдрассила: для влади калдореїв це глибока ганьба. Розібратися з ним швидко й тихо — значить не допустити паніки й зменшити сором.",al={"чому таємниця","таємниця скривленої ненависті","чому мовчати"}},{q="Звідки взяли Голову Меленаса?",a="Голову здобувають глибоко в Скелі Скверни — зіпсованій печері трохи на північ від Доланаара й Тінедолу в центрі Тельдрассила.",al={"де меленас","місце скверної скелі","місце меленаса"}}},fp="13,248,20.532.0,21.187.0,32.253.0,35.131.0"}
P.entries["item:menethil-statuette"] = {n="Статуетка Менетіла",s="Статуетка Менетіла — рідкісна срібляста фігурка, що зображує покійного короля Теренаса Менетіла II молодим паладином із піднятим бойовим молотом. Загублена під час корабельної аварії біля берегів Багнокраю, вона — надзвичайно рідкісна пам'ятка загиблого володаря Лордерона.",h="Статуетка Менетіла — рідкісна срібляста фігурка, що зображує покійного короля Теренаса Менетіла II молодим...",kw={"статуетка менетіла","теренас менетіл","лордерон","болвар фордрагон","собор світла","сліпа принцеса"},ang={["class:Paladin"]="Статуетка зображує покійного короля Теренаса молодим воїном Світла з піднятим молотом — глибоко зворушливий образ для святих лицарів, що оплакують загибле королівство.",["faction:Alliance"]="Теренас — провідник, що об'єднав народи й заснував Великий Альянс, тож будь-яка збережена пам'ятка про нього — надихаючий скарб у розколотому світі."},sec={{t="Рідкісна реліквія Лордерона",b="Статуетка зображує короля Теренаса Менетіла II в молоді роки — довговолосим паладином, що здіймає молот до небес. Теренас славився скромністю за свого правління й не любив особистих пам'ятників, тож на його честь замовили зовсім мало статуй чи портретів. Після того як Королівство Лордерон упало під натиском Погибелі, майже всі такі реліквії знищили, тож ця вціліла подоба надзвичайно цінна для Альянсу."},{t="Утрачена в болотах",b="Статуетка була вантажем торгового судна «Сліпа Принцеса», що прямувало до гавані Альянсу — Менетіла. Коли на корабель біля болотистого узбережжя напали агресивні мурлоки-Блакитнозябрі, вантаж розкидало, і статуетка опинилася в напівзасипаній бочці на березі. Оскільки поблизу чигали такі загрози, як орки Драконячої Пащі, місцеві захисники поспішили відіслати знайдену реліквію на південь, до Стормвінда, де Верховний Лорд Болвар Фордрагон довірив її Соборові Світла."}},faq={{q="Кого зображує статуетка?",a="Вона зображує Короля Теренаса Менетіла II — колишнього володаря Лордерону й творця першого Альянсу. Його показано не літнім монархом, а юним паладином із бойовим молотом у руці.",al={"кого зображує статуетка","хто на статуетці","хто на статуетці менетіла"}},{q="Як загубилася статуетка?",a="Її везли через Велике море на торговому судні «Сліпа Принцеса». Коли на корабель напали мурлоки-Блакитнозябрі в Багнокраї, його вантаж винесло на берег і замулило.",al={"як загубилася статуетка","хто загубив статуетку","кораблетроща в болотах статуя"}},{q="Чому зображення Короля Теренаса такі рідкісні?",a="Король Теренас був скромним володарем і щиро не любив пам'ятників на власну славу, тож його статуй зробили дуже мало. Майже всі портрети й фігури, що лишалися на півночі, знищила Погибель, плюндруючи Лордерон.",al={"чому мало статуй теренаса","пам'ятники теренасу"}},{q="Куди зрештою потрапляє статуетка?",a="Знайдену в Багнокраї статуетку приносять Верховному Лордові Болвару Фордрагону у Фортецю Стормвінда. Болвар розуміє, що в реліквії зібралося Світло, і велить Лордові Ґрейсону Шедовбрейкеру берегти її в Соборі Світла.",al={"куди нести статуетку","хто зберігає статуетку","статуетка собор"}}},fp="18,267,25.469.0,16.499.0,30.204.0,27.203.0,43.247.0,32.260.1"}
P.entries["item:merrin-s-letter"] = {n="Лист Меррін",s="Лист Меррін — нагальне послання від Меррін Роквівер, археологині, що застрягла на розкопі в Багнокраї. Вона розповідає, як розкоп заполонили люті раптори, і запевняє рідних, що поки що жива.",h="Лист Меррін — нагальне послання від Меррін Роквівер, археологині, що застрягла на розкопі в Багнокраї.",kw={"лист меррін","меррін роквівер","таррел роквівер","раптори","шукач велґар","багнокрай"},ang={["faction:Alliance"]="Доставлена записка приносить важливі відомості й гірко-солодку розраду вартовим Альянсу, що пильнують шлях через Багнокрай.",["race:Dwarf"]="Лист підкреслює, яку високу особисту ціну платить Ліга Дослідників, відкопуючи давню історію в небезпечних диких краях Каз Модану."},sec={{t="Звістка з руїн",b="Розкопуючи величезні доісторичні скам'янілості й реліквії на Місці Розкопок Велґара в Багнокраї, дворфійська експедиція потривожила гніздо лютих плямистих рапторів. Звірі заполонили траншеї, вбили кількох робітників і відрізали вцілілим дослідникам шлях до втечі. Пишучи цю записку серед хаосу, Меррін Роквівер повідомляє чоловікові, Таррелу, що лишився в Гавані Менетіл: хоч розкоп і лежить у руїнах, вона, Шукач Велґар та Ормер Айронбрейд уціліли за барикадами в укритті."}},faq={{q="Хто написав Лист Меррін?",a="Лист написала Меррін Роквівер — дослідниця, що брала участь в археологічній експедиції на розкопках серед південних пагорбів Багнокраю.",al={"автор листа меррін","хто така меррін"}},{q="Кому адресовано лист?",a="Його адресовано Таррелові Роквіверу, який із тривогою чекає звісток на мосту в Гавані Менетіл.",al={"адресат листа меррін","кому лист меррін"}},{q="Що сталося з командою розкопок?",a="Коли археологи відкопували величезні скам'янілі кістки, на них напала й розбила зграя плямистих рапторів. Чимало дворфів-робітників загинуло, і лише жменька вцілілих забарикадувалася в нашвидкуруч зведеному таборі.",al={"що сталося з розкопками","чому експедиція провалилася"}},{q="Хто допоміг Меррін вижити під час нападу?",a="Ормер Айронбрейд хоробро боронив Меррін і головного шукача, даючи їм змогу відступити й сховатися, поки решта розкопок упала під натиском рапторів.",al={"хто врятував меррін","ормер айронбрейд"}}},fp="15,269,25.531.0,26.155.0,31.100.0,37.228.0,37.161.0"}
P.entries["item:middle-of-gelkak-s-key"] = {n="Середня Частина Ключа Ґелкак",s="Середня Частина Ключа Ґелкак — зламаний металевий уламок, що належав гномові-піратові Ґелкаку Джайромасту, який зазнав корабельної аварії. Коли його судно пішло на дно біля Темного Узбережжя, цю центральну частину вхопили падальники з-поміж місцевих мурлоків Сірої Імли.",h="Середня Частина Ключа Ґелкак — зламаний металевий уламок, що належав гномові-піратові Ґелкаку Джайромасту...",kw={"ключ ґелкака","ґелкак джайромаст","мурлоки сірої імли","темне узбережжя","трешадони","гном-пірат"},ang={["profession:Engineering"]="Ключ — виготовлена на замовлення механічна деталь, щоб заводити й запускати годинникового першого помічника: класична гномська винахідливість навіть у руках пірата."},sec={{t="Уламок у мулі",b="Коли дикі трешадони затягли корабель Ґелкака Джайромаста під хвилі, гнома-пірата викинуло на берег, а найцінніші його пожитки розтрощило об кам'янисті мілини. Серед уламків був особливий заводний ключ для його механічного першого помічника. Під час катастрофи ключ розломився на три частини, які розлетілися берегом. Верхню й нижню частини потягли прибережні звірі, а середня впала в око мурлокам Сірої Імли, що нишпорять у прибої Темного Узбережжя, — і ті швиденько сховали блискучий металевий шматок у своїх таборах і схованках серед корабельних решток."}},faq={{q="Для чого потрібна Середня Частина Ключа Ґелкак?",a="Це один із трьох уламків, потрібних Ґелкакові Джайромасту — пірату, що зазнав корабельної аварії біля берегів Темного Узбережжя. Складений із верхньою й нижньою частинами, ключ знову оживляє його механічного першого помічника.",al={"що відчиняє ключ ґелкак","використання середньої частини ключа ґелкак","навіщо мені цей ключ"}},{q="Де опинилася ця частина ключа?",a="Середню частину підібрало плем'я мурлоків Сірої Імли. Її можна відібрати в грабіжників, оракулів, ловців із сітками, мисливців на приплив та інших членів племені, що блукають пляжами й уламками кораблів Темного Узбережжя.",al={"у кого середня частина ключа","де знайти середню частину ключа ґелкак","хто дропає середню частину ключа"}},{q="Чому ключ узагалі розбився?",a="Корабель Ґелкака потопили неподалік від берега люті трешадони. Коли гнома викинуло на берег серед уламків, ключ ударився об прибережні скелі й розколовся на три частини, які потім розтягли місцеві падальники.",al={"як зламався ключ","чому ключ у шматках"}}},fp="22,254,22.598.0,44.212.0,32.208.0,42.242.0"}
P.entries["item:milly-s-harvest"] = {n="Урожай Міллі",s="Урожай Міллі — ящики й відра щойно зібраного винограду, які Міллі Осворт назбирала на Виноградниках Нортшира. Коли бандити Дефіас захопили поля, урожай довелося покинути, і плоди ризикують бути вкраденими злодіями або розчавленими під чоботами варти абатства.",h="Урожай Міллі — ящики й відра щойно зібраного винограду, які Міллі Осворт назбирала на Виноградниках Нортшира.",kw={"урожай міллі","міллі осворт","виноград","виноградники нортшира","братство дефіас","ящики"},ang={["faction:Alliance"]="Загроза простим фермерам Нортширу показує, яким тонким став військовий гарнізон Стормвінда: звичайні громадяни залежать від перехожих шукачів пригод, щоб уберегти свій прожиток.",["race:Human"]="Для людей, що починають свій шлях у Нортширі, повернення врожаю Міллі часто стає першою прямою зустріччю з беззаконням Братства Дефіас, що повзе рідною землею."},sec={{t="Крихкий урожай",b="Родючий ґрунт Долини Нортширу родить виноград, життєво важливий для тутешніх виноробів і громади абатства. Коли настала пора збирання, Міллі Осворт працювала на лозах, збираючи свіжі плоди в відра. Її працю жорстоко перервали озброєні розбійники в червоних масках, що вдерлися на виноградники й змусили її тікати на землі абатства, покинувши врожай розкиданим між рядами."},{t="Побічні втрати",b="Хоч варта Стормвінда пильнує вхід у долину, брак людей залишив Нортшир уразливим. Гарнізон пообіцяв вигнати Дефіас, та Міллі боялася, що будь-яка затяжна сутичка між броньованою вартою й безжальними злодіями цілком знищить її працю. Повернення ящиків, перш ніж їх розтопчуть або заберуть як провіант, рятує один із небагатьох мирних урожаїв Нортширу."}},faq={{q="Що таке Урожай Міллі?",a="Це щойно зібраний виноград у ящиках і відрах, який Міллі Осворт покинула, коли головорізи Дефіас захопили Виноградники Нортшира.",al={"урожай міллі","що таке урожай","виноград міллі освурт"}},{q="Чому ящики лишилися на винограднику?",a="Бандити Дефіас напали на виноградники саме тоді, коли Міллі збирала врожай, і вона мусила кинути все й тікати рятуватися до Абатства Нортшира.",al={"чому покинули","чому міллі лишила виноград","чому лишили урожай"}},{q="Чому вартові Нортшира не забрали врожай?",a="Вартових у Нортширі й так ледве вистачає на набіги Дефіас і місцеві загрози. До того ж Міллі боялася, що навіть якщо вартові проженуть бандитів, їхні чоботи в сутичці витопчуть і знищать ніжний виноград.",al={"чому не вартові","чому варта не може забрати","варта стормвінда нортшир"}},{q="Хто ці бандити, що загрожують урожаю?",a="Це головорізи Братства Дефіас — зграї розбійників і грабіжників, що сіють неспокій по всьому Лісу Елвінн.",al={"хто захопив виноградники","хто нападає на виноградник","бандити виноградника"}}},fp="15,292,15.412.0,17.448.0,24.158.0,48.177.0,56.235.0,44.145.0"}
P.entries["item:miners-gear"] = {n="Шахтарське Спорядження",s="Шахтарське Спорядження — міцні дворфійські кайла, лопати й інструменти для копання, що зберігаються в Шахті Срібного Потоку. Коли шахту обсіла нечисть, Ліга Шахтарів доручила шукачам пригод винести цінне знаряддя, перш ніж місцева варта піде на штурм.",h="Шахтарське Спорядження — міцні дворфійські кайла, лопати й інструменти для копання, що зберігаються в Шахті...",kw={"шахтарське спорядження","шахта срібного потоку","ліга шахтарів","кобольди","лох модан","кайла"},ang={["profession:Mining"]="Кожен рудокоп знає ціну добре викуваного дворфійського заліза: залишити найкращі кайла й лопати злодюжкам зі свічками на головах — маленька трагедія.",["race:Dwarf"]="Для дворфів кобольди, що кладуть брудні лапи на дворфійські вироби, — нестерпна образа, за яку шахту треба вичистити негайно."},sec={{t="Припаси Ліги Шахтарів",b="Коли в Шахті Срібного Потоку у східному Лох Модані скінчилася руда, Ліга Шахтарів перетворила тихі тунелі на підземний склад гірничого спорядження. На жаль, кобольди, що живуть у тунелях, швидко заполонили шахту, розтягли збережене добро й отаборилися серед ящиків. Ліга боїться, що цінне дворфійське спорядження або потрощать горяни під час рішучого штурму, або зіпсують злодюжки, тож покладається на сміливих шукачів пригод, які пролізуть усередину й витягнуть ящики в безпечне місце."}},faq={{q="Що таке Шахтарське Спорядження?",a="Шахтарське Спорядження — це ящики з дворфським інструментом для копання, як-от кайлами й лопатами, що належать Лізі Шахтарів і зберігаються в сухих тунелях Шахти Срібного Потоку.",al={"що таке шахтарське спорядження","предмети шахтарського спорядження","шахтарське спорядження лох модан"}},{q="Чому спорядження лишили в шахті?",a="Коли руда в Шахті Срібного Потоку вичерпалася, Ліга Шахтарів перетворила порожні тунелі на склад. Там спорядження й лежало, доки шахту несподівано не заполонили кобольди.",al={"чому спорядження в шахті срібного струмка","чому лишили спорядження"}},{q="Хто хоче повернути це спорядження?",a="Горянин Стормпайк від імені Ліги Шахтарів керує цими пошуками. Він хоче врятувати інструменти, перш ніж його бойові товариші ввійдуть у шахту, щоб винищити кобольдів.",al={"хто хоче шахтарське спорядження","кому потрібне спорядження","спорядження гірського стрільця стормпайка"}},{q="Де знайти Шахтарське Спорядження?",a="Спорядження спаковане в Ящики Ліги Шахтарів, розкидані по штреках Шахти Срібного Потоку на східних пагорбах Лох Модану.",al={"місце шахтарського спорядження","де знайти шахтарське спорядження","місця ящиків ліги шахтарів"}}},fp="12,271,30.521.0,21.178.0,34.179.0,30.180.0,32.151.0"}
P.entries["item:minshina-s-skull"] = {n="Череп Міншіни",s="Череп Міншіни містить ув'язнену душу троля Темного Списа Міншіни, брата Майстра Ґадріна. Полонена відступником-відьмаком Залазаном на Островах Відлуння, вона перетворила череп на моторошну посудину, що живить темні обрядові чари.",h="Череп Міншіни містить ув'язнену душу троля Темного Списа Міншіни, брата Майстра Ґадріна.",kw={"череп міншіни","міншіна","ґадрін","залазан","острови відлуння","душа","відьмак"},ang={["faction:Horde"]="Повернення черепа — ранній удар по спотвореній владі Залазана над Островами Відлуння біля самого узбережжя Дуротару.",["race:Troll"]="Для Темного Списа осквернення Міншіни Залазаном — тяжка образа традицій предків, тож повернення його черепа — справа честі племені."},sec={{t="Ув'язнений дух",b="Коли Залазан захопив владу над Островами Відлуння й вигнав плем'я Темного Списа, Міншіна був серед полонених і вбитих. Замість дати жертві відійти в смерть, зрадливий відьмак прив'язав душу Міншіни до його ж відрубаного черепа. Поставлений у мерзенне коло сили на найпівденнішому острові, череп став прив'яззю магічного поневолення. Майстер Ґадрін, якого мучать видіння брата, що кличе його уві сні, шукає відважних мандрівників, аби ті вирушили на захоплені острови, повернули реліквію й розірвали владу Залазана над духом його брата."}},faq={{q="Хто такий Міншіна?",a="Міншіна — троль Темного Спису й брат Майстра Ґадріна із Села Сен'джин. Його вбили під час смути, що спалахнула через зраду Залазана на Островах Відлуння.",al={"лор міншіни","хто такий міншіна","брат майстра ґадріна"}},{q="Чому душа Міншіни ув'язнена в черепі?",a="Залазан темною магією прив'язав дух Міншіни просто до його відтятої голови. Покладена в обрядове коло сили на головному острові, ув'язнена душа лишалася скутою волею Залазана й не могла піти до предків.",al={"чому ув'язнити його душу","ритуал черепа залазана","душа в черепі"}},{q="Де знайти череп?",a="Череп лежить на найбільшому, найпівденнішому з Островів Відлуння — на пагорбі, в колі сили, оздобленому свічками, обрядовими знаками й іншими черепами, яке стережуть раби Залазана.",al={"де череп міншіни","місце кола сили","місце черепа острови відлуння"}},{q="Що стається, коли череп приносять Майстрові Ґадріну?",a="Повернений Майстрові Ґадріну в Село Сен'джин, череп розриває темні чари. Коли мерзенний зв'язок розірвано, примарна подоба Міншіни на мить з'являється, вдячно вклоняється й спокійно відходить до царства предків.",al={"звільнення міншіни","нагорода ґадріна за череп","що буде з міншіною"}}},fp="16,228,16.585.0,17.169.0,44.238.0,27.203.0,56.231.1"}
P.entries["item:mirror-lake-water-sample"] = {n="Зразок Води Дзеркального Озера",s="Зразок Води Дзеркального Озера — пляшка свіжої озерної води, набраної біля підніжжя водоспаду в Лісі Елвінн. Зібраний магами-новачками за дорученням Дженнеї Кеннон із Кварталу магів Стормвінда, він потрібен, щоб з'ясувати, чи не просочуються змінені таємні течії в тутешні водойми.",h="Зразок Води Дзеркального Озера — пляшка свіжої озерної води, набраної біля підніжжя водоспаду в Лісі Елвінн.",kw={"зразок води","дзеркальне озеро","дженнея кеннон","святилище чародія","силові лінії","маг"},ang={["class:Mage"]="Принести зразок — ранній обряд обов'язку для магів Альянсу, що навчаються в Святилищі Чародія: він учить стежити за силовими лініями довкілля й розпізнавати дике магічне просочування."},sec={{t="Перевірка вод Елвінну",b="Після катастрофічних світових конфліктів, що зірвали містичні русла світу з їхніх сталих шляхів, маги Святилища Чародія в Стормвінді глибоко стурбовані залишковим таємним збуренням. Дженнея Кеннон доручає перспективним учням наповнити спеціально підготовлену пляшку біля підніжжя водоспаду Дзеркального Озера, що лежить одразу на південний захід від Воріт Стормвінда. Аналізуючи цей зразок води, маги прагнуть виявити, чи не просочилися блукаючі магічні скверни в природні водойми, якими живиться довколишній люд."}},faq={{q="Що таке Зразок Води Дзеркального Озера?",a="Це вода, зачерпнута біля водоспаду на Дзеркальному Озері в Лісі Елвінн у пляшку Дженнеї. Маги-новачки набирають її, щоб у Святилищі Чародія перевірили, чи немає в ній магічного забруднення.",al={"зразок дзеркального озера","предмет зразок води","вода дженнеї"}},{q="Навіщо Дженнеї Кеннон ця проба води?",a="Недавні магічні потрясіння по всьому Азероту порушили усталені потоки магії. Дженнея Кеннон боїться, що свавільна магічна енергія змінює природу й отруює місцеву питну воду.",al={"навіщо перевіряти дзеркальне озеро","призначення дженнеї кеннон","магічна скверна води"}},{q="Де набирають пробу?",a="Її набирають біля підніжжя водоспаду, що спадає в Дзеркальне Озеро, на південний захід від Брами Стормвінда в Лісі Елвінн.",al={"де взяти зразок","місце дзеркального озера","водоспад зразка"}},{q="Що буде, якщо вода виявиться магічно отруєною?",a="Дженнея Кеннон побоюється, що кожен, хто довго пиє з Дзеркального Озера, може зазнати шкідливих магічних наслідків, якщо лей-потоки отруїли воду.",al={"наслідки отруєної води","чи отруєне дзеркальне озеро"}}},fp="24,301,28.549.0,37.189.0,46.197.0,30.130.0,60.174.0"}
P.entries["item:mist-veil-s-lockbox"] = {n="Скринька Туманної Завіси",s="Скринька Туманної Завіси — міцна скриня, що лежить серед затонулих решток корабля нічних ельфів «Туманна Завіса» біля берегів Темного Узбережжя. У ній бортовий журнал капітана та його особисті речі, втрачені, коли на корабель напали й потопили прибережні мурлоки.",h="Скринька Туманної Завіси — міцна скриня, що лежить серед затонулих решток корабля нічних ельфів «Туманна...",kw={"скринька туманної завіси","туманна завіса","срібна зоря","ґорболд стілгенд","мурлоки","обердайн"},ang={["faction:Alliance"]="Повернувши скриньку, ви вшануєте загиблу команду й підтримаєте морську громаду Обердайна, якій нині непросто.",["race:NightElf"]="Загиблий капітан був шанованим мореплавцем із нічних ельфів, і, врятувавши його журнал, ви допоможете його духові знайти спокій у водах біля Темного Узбережжя."},sec={{t="Поглинуті глибиною",b="Корабель нічних ельфів «Туманна Завіса» знайшов свій кінець у підступних прибережних водах дорогою до Обердайна. Ворожі мурлоки напали на нього разом із сестринським судном «Срібна Зоря», здолали команду й відправили корабель на морське дно. Капітан загинув під час нападу, і його бортовий журнал та цінні особисті речі лишилися замкненими в цій скриньці. Скриня лежить у затопленому трюмі — похмурий трофей серед тих самих істот, що спричинили катастрофу."},{t="Спокій для команди",b="Для моряків, яким пощастило дістатися Обердайна, втрата корабля й командира — досі відкрита рана. Ґорболд Стілгенд хоче повернути Скриньку Туманної Завіси, щоб останні речі капітана гідно вшанували й поховали. Ризикнути спуститися в затоплені рештки по скриню — хоч якась розрада для зболених горем уцілілих, що застрягли на материку."}},faq={{q="Що в Скриньці Туманної Завіси?",a="У скриньці — капітанський журнал і особисті речі капітана. Капітан загинув, коли корабель затонув, і вцілілі моряки в Обердайні хочуть повернути ці пам'ятки, щоб ушанувати свого загиблого ватажка.",al={"вміст скриньки туманної завіси","що в скриньці","що у коробці"}},{q="Як затонула «Туманна Завіса»?",a="На «Туманну Завісу» напали прибережні мурлоки, коли вона прямувала до Обердайна. Не впоравшись із натиском, корабель пішов на дно разом зі своїм супутником — «Срібним Світанням».",al={"чому корабель розбився","хто потопив туманну завісу","що сталося з туманною завісою"}},{q="Де знайти скриньку?",a="Вона під водою біля берегів Темного Узбережжя, на північ від Обердайна. Скринька лежить у затопленому корпусі «Туманної Завіси», де аж кишить мурлоками.",al={"де скринька туманної завіси","місце туманної завіси","місце скриньки"}},{q="Хто хоче повернути скриньку?",a="Ґорболд Стілгенд в Обердайні шукає скриньку від імені вцілілих моряків, сподіваючись дати спокій пам'яті загиблого капітана.",al={"хто бере скриньку","хто дає завдання","завдання ґорболда скринька"}}},fp="19,260,18.493.0,17.391.0,35.204.0,27.215.0,27.190.0,32.155.0"}
P.entries["item:mo-grosh-crystal"] = {n="Кристал Мо'ґрош",s="Кристали Мо'ґрош — рідкісні мінеральні утворення, які видобувають і ревно збирають огри Мо'ґрош у північно-східному Лох Модані. Їх цінують за незвичні алхімічні властивості, і вони стають важливим складником для знешкодження підривних засобів Темного Заліза.",h="Кристали Мо'ґрош — рідкісні мінеральні утворення, які видобувають і ревно збирають огри Мо'ґрош у...",kw={"кристал мо'ґрош","огри","твердиня мо'ґрошів","лох модан","каменетесна гребля","гіндервір"},ang={["profession:Mining"]="Хоч ці сирі мінерали видобуто глибоко на землях огрів, у поєднанні з органічними реагентами вони виявляють незвичну хімічну активність.",["race:Dwarf"]="Захист Каменетесної Греблі тримається на дворфійській кмітливості, що обертає видобутий огрячим кланом скарб на запобіжник від підступності Темного Заліза."},sec={{t="Рідкісний огрячий скарб",b="Огри Мо'ґрош видобувають ці характерні кристали у своїй твердині, захованій серед скель північно-східного Лох Модану. Хоч огри, що покладаються на грубу силу, рідко знаються на тонкій металургії, Кристали Мо'ґрош — цінний скарб для їхнього клану: їх носять і рядові громили, і шамани-містики, і височенні ватажки. Кристали досить рідкісні, тож у Твердині Мо'ґрошів їх пильно стережуть."},{t="Відповідь на загрозу Темного Заліза",b="Коли розвідка з'ясовує, що диверсанти Темного Заліза замишляють удар по Каменетесній Греблі, Головний Інженер Гіндервір шукає Кристал Мо'ґрош, а з ним — отруту павуків-причаюнів і сльози кроколісків. Поєднавши кристалічний мінерал із цими активними реагентами, дворфійські інженери можуть виготовити особливу суміш, здатну знешкодити небезпечну вибухівку Темного Заліза, перш ніж долину затопить."}},faq={{q="Звідки беруться Кристали Мо'ґрош?",a="Їх добувають і тримають огри Мо'ґрош на північному сході Лох Модану. Кристал може мати будь-хто з клану в Твердині Мо'ґрошів — містики, громили, вишибали й шамани.",al={"місце кристала мо'ґрош","де знайти кристал мо'ґрош","хто дропає кристал мо'ґрош"}},{q="Для чого потрібен кристал?",a="Головному Інженерові Гіндервіру з Каменетесної Греблі кристал потрібен для знешкоджувальної суміші. Змішаний з отрутою причаєних і сльозами кроколісків, він допомагає знешкодити вибухівку Темного Заліза, якою хотіли підірвати греблю.",al={"що робить кристал мо'ґрош","використання кристала мо'ґрош","чому гіндервейр хоче кристал"}},{q="Навіщо огри видобувають ці кристали?",a="Огри Мо'ґрош видобувають кристали з довколишніх пагорбів як цінний скарб клану. Їхні містики й шамани використовують дивні мінерали в обрядах, а воїни збирають їх як рідкісне багатство.",al={"чому огри мають кристали","лор кристалів огрів"}}},fp="16,241,23.451.0,31.417.1,37.204.0,29.223.0,40.215.0"}
P.entries["item:modr-fragment"] = {n="Уламок Модра",s="Уламок Модра — одна з чотирьох утрачених частин, відколотих від прадавнього Каменя Ґоаза — реліквії, відкопаної в Багнокраї. Знайдений серед реліквій і пухкої землі на Місці Розкопок Велґара, він несе давнє письмо титанів, без якого не скласти забутого пророцтва.",h="Уламок Модра — одна з чотирьох утрачених частин, відколотих від прадавнього Каменя Ґоаза — реліквії...",kw={"уламок модра","камінь ґоаза","шукач велґар","ліга дослідників","титани","багнокрай"},ang={["faction:Alliance"]="Мандрівники з Альянсу допомагають Шукачеві Велґару пробитися на заполонений розкоп, щоб уберегти для Айронфорджа безцінні історичні дослідження.",["race:Dwarf"]="Для дворфійської Ліги Дослідників повернути втрачені частини, як-от Уламок Модра, конче потрібно, щоб розшифрувати спадщину титанів і розкрити глибоку історію свого роду."},sec={{t="Частина Каменя Ґоаза",b="Ще до того, як люті раптори вигнали Лігу Дослідників з розкопу в Багнокраї, Шукач Велґар відкопав Камінь Ґоаза — величезну табличку з прадавніми знаками титанів. Перекладений текст раптово обривався в чотирьох місцях, приховуючи застереження про божественний задум і приречене пророцтво. Уламок Модра — одна з тих чотирьох утрачених частин, що лишилися серед давніх реліквій і перекопаної землі, коли копачі мусили рятуватися втечею."},{t="Таємниці під землею",b="Склавши Уламок Модра з уламками Адоса, Голма й Неру, Шукач Велґар нарешті відтворює повний напис. Перекладене письмо відкриває приголомшливі знання з досвітку світу, зокрема згадку про «Древніх Богів... Скутих під Землею». Те, що починалося як звичайний археологічний розкоп на болотах, натомість оголило сліди первісної боротьби, замкненої під ґрунтом."}},faq={{q="Що таке Уламок Модра?",a="Це уламок каменю з написом, відколотий від Каменю Ґоаза — прадавньої реліквії титанів, знайденої на Місці Розкопок Велґара в Багнокраї.",al={"уламок модра","що таке модр","реліквія модра"}},{q="Хто шукає цей уламок?",a="Шукач Велґар, археолог Ліги Дослідників, що стоїть на краю розкопок, де аж кишить рапторами, шукає його, щоб доповнити відсутній текст таблиці.",al={"хто хоче уламок модра","завдання уламка велґара"}},{q="Що стається, коли зібрано всі чотири уламки?",a="Поєднавши Уламок Модра з уламками Адоса, Голма й Неру, Шукач Велґар відновлює Камінь Ґоаза. Прочитавши всі письмена титанів, він натрапляє на зловісну згадку про «Древніх Богів… скутих під землею».",al={"що буде коли зібрати всі чотири уламки","камінь ґоаз завершений","що каже камінь ґоаз"}},{q="Де знайти уламок?",a="Він розкиданий по Місцю Розкопок Велґара на півдні Багнокраю — захований у прадавніх глечиках-реліквіях чи в пухкій землі, яку стережуть люті раптори.",al={"місце уламка модра","де знайти модр"}}},fp="13,269,25.468.0,25.427.1,26.146.0,33.163.0,50.229.1,28.165.0"}
P.entries["item:moldy-tome"] = {n="Запліснявілий Фоліант",s="Запліснявілий Фоліант — підмочені водою врятовані рештки, що містять половину оригінального Фоліанта Кабали. Утрачений під час корабельної аварії біля узбережжя Передгір'я Гілсбреда, він зберігає темні таємні обряди, яких прагнуть чорнокнижники, що хочуть опанувати виклик демонів.",h="Запліснявілий Фоліант — підмочені водою врятовані рештки, що містять половину оригінального Фоліанта Кабали.",kw={"запліснявілий фоліант","фоліант кабали","подертий манускрипт","мисливець Скверни","чорнокнижник","передгір'я гілсбреда","кром стаутарм"},ang={["class:Warlock"]="Повернути цей розмоклий гримуар — важливий обряд посвяти для чорнокнижників, що складають докупи ритуали, потрібні, щоб підкорити мисливця Скверни."},sec={{t="Поглинутий хвилями",b="Фоліант Кабали був єдиним, незамінним трактатом про темні мистецтва, що колись зберігався в королівстві Лордерон. На якомусь етапі своєї темної історії гримуар безжально понівечили й розірвали надвоє. Частину, яку тепер звуть Запліснявілим Фоліантом, везли кораблем на південь — до Гавані Менетіл і Айронфорджа. Та судно так і не дісталося мети, загинувши в підступних водах на захід від Саутшора. Викинута на берег на південь від Шахти Лазурової Жили, уціліла половина лежала, нищена вогкістю й прибоєм, серед мурлоків, що нишпорять узбережжям Гілсбреда в пошуках поживи."},{t="Повернення темної праці",b="Попри цвіль і гниючий пергамент, Запліснявілий Фоліант зберігає могутні демонічні знання. Послідовники темних мистецтв під проводом наставників — як-от Кром Стаутарм в Айронфорджі чи Джора Аннісон в Андерсіті — наважуються пробитися до прибережних таборів, щоб його повернути. Поєднаний зі своєю другою половиною — Подертим Манускриптом, знайденим у курних печерах Тисячі Голок, — відновлений твір дає точні заклинання, потрібні, щоб викликати й підкорити мисливця Скверни."}},faq={{q="Що таке Запліснявілий Фоліант?",a="Це половина рідкісного Фоліанта Кабали — окультного гримуара з обрядами виклику демонів. Розмоклий і зотлілий, він — та частина первісного тексту, що пережила корабельну аварію.",al={"запліснявіла книга","що це за річ","історія запліснявілого фоліанта"}},{q="Де опинився Запліснявілий Фоліант?",a="Його винесло на берег Передгір'я Гілсбреда, на захід від Саутшора й на південь від Шахти Лазурової Жили. Він потрапив до рук місцевих прибережних мурлоків, які ховають його у своєму таборі.",al={"місце запліснявілого фоліанта","де запліснявілий фоліант","де знайти запліснявілий фоліант"}},{q="Чому фоліант був на кораблі?",a="Цю частину, що зберігалася в Лордероні, відправили на судні до Гавані Менетіл, щоб доставити вченим Айронфорджа. Корабель затонув біля берегів Гілсбреда й так і не дійшов до мети.",al={"чому загубили в морі","фоліант з корабля","перевезення фоліанта"}},{q="Що потрібно, щоб зібрати Фоліант Кабали?",a="Запліснявілий Фоліант треба поєднати з Подертим Манускриптом — другою, відірваною половиною книги, яку занесло аж до Твердині Розщепленого Копита в Тисячі Голок.",al={"друга половина фоліанта","бракує сторінок","частини фоліанта кабали"}}},fp="10,249,17.574.0,24.444.1,23.187.0,32.187.0,27.205.0,49.163.0"}
P.entries["item:moonpetal-lily"] = {n="Лілея Місячна Пелюстка",s="Лілеї Місячна Пелюстка — великі світні рослини, корінні для Тельдрассила, що буяють довкола прісних озерець. Славетні потужними відновлювальними властивостями, їхні пелюстки цінують як ключові складники природних ліків і цілющих напоїв.",h="Лілеї Місячна Пелюстка — великі світні рослини, корінні для Тельдрассила, що буяють довкола прісних озерець.",kw={"лілея місячна пелюстка","лілея","протиотрута","тінедол","алдрассил","травництво","печера тіньової нитки"},ang={["profession:Herbalism"]="Хоч у нагальну хвилину їх збирають просто руками, Лілеї Місячна Пелюстка наочно показують багатий відновлювальний ботанічний потенціал Тельдрассила.",["race:NightElf"]="Для молодих калдореїв, що навчаються в Тінедолі, пізнати відновлювальні властивості корінних рослин на кшталт Лілеї Місячної Пелюстки — важливий ранній урок життя в злагоді з природою."},sec={{t="Рослинність озерець",b="Лілеї Місячна Пелюстка ростуть лише на вологих берегах прісних озерець і ставків, найохочіше — на північно-західному боці Алдрассила в Тінедолі. Як і більшість рослинності, що буяє на верхівці новопосталого Світового Дерева, вони вбирають неповторну сутність затишних гаїв Тельдрассила. Їхні широкі пелюстки ніжні й сяйливі, і їх легко помітити біля тихої води, де природна волога дає їм змогу квітнути."},{t="Природні протиотрути",b="Цілителі й травники нічних ельфів цінують Лілею Місячну Пелюстку за її надзвичайні цілющі властивості. У поєднанні з іншою лісовою рослинністю, як-от Гіацинтовими Грибами, лілея діє як потужний заспокійливий і стабілізувальний засіб. Ця відновлювальна якість робить її неодмінним складником протиотрут проти смертельних токсинів, зокрема лютої отрути павуків Вебвуда, що чигають у Печері Тіньової Нитки."}},faq={{q="Де ростуть Лілеї Місячна Пелюстка?",a="Вони ростуть на берегах двох прісних ставків на північно-західному боці Алдрассила в Тінедолі на Тельдрассилі.",al={"де знайти лілеї місячна пелюстка","місце лілеї місячна пелюстка","місця лілей"}},{q="Для чого потрібні Лілеї Місячна Пелюстка?",a="Лілеї мають помітні відновлювальні й цілющі властивості. У Тінедолі Діранія Сілвершайн разом із Гіацинтовими Грибами й Іхором Павука Вебвуда варить із них сильну протиотруту від павучої отрути.",al={"використання лілеї місячна пелюстка","що робить лілея місячна пелюстка"}},{q="Кому потрібна протиотрута з цих лілей?",a="Нічному ельфові Іверрону, якого отруїли укусом павуки Вебвуда біля Печери Тіньової Нитки: щоб вижити, йому потрібна протиотрута з Лілей Місячна Пелюстка.",al={"для кого протиотрута","отрута іверрона"}},{q="Чи можна зібрати Лілеї Місячна Пелюстка поза Тельдрассилом?",a="Вони пов'язані саме з відлюдними ставками Тельдрассила й відомі в цих краях лише в затишку під гілками Тінедолу.",al={"чи ростуть лілеї деінде","лілеї в інших зонах"}}},fp="14,236,18.439.0,17.428.0,31.133.0,35.198.0,45.176.0,55.123.0"}
P.entries["item:moonstalker-fang"] = {n="Ікло Місячного Скрадайла",s="Ікло Місячного Скрадайла — гострий зуб, вирваний у хижих місячних скрадачів, що блукають імлистими лісами Темного Узбережжя. Такі ікла збирають мандрівники, які допомагають Візбанґові Кранктоґґлу обслуговувати його автоматичні пробовідбірні пристрої.",h="Ікло Місячного Скрадайла — гострий зуб, вирваний у хижих місячних скрадачів, що блукають імлистими лісами...",kw={"ікло місячного скрадайла","місячні скрадачі","візбанґ кранктоґґл","дзижчалка","обердайн","темне узбережжя"},ang={["class:Hunter"]="Щоб здолати місячних скрадачів, треба тримати чуття напоготові проти хижаків, що нападають із засідки й природно зливаються з темними кронами узбережжя.",["race:Gnome"]="Ексцентричні пристрої далекого зв'язку Візбанґа Кранктоґґла — класична гномська інженерія, навіть якщо його заплітання язиком і дивний вибір зразків змушують здивовано звести брови."},sec={{t="Механізм-дробарка",b="Місячні скрадачі — потайні шаблезубі коти, що нишпорять лісовими узліссями Темного Узбережжя й вистежують здобич між затіненими соснами. Їхні довгі ікла — грізна мисливська зброя, здатна розтинати плоть і кістки. Та для ексцентричного гнома-майстра Візбанґа Кранктоґґла ці зуби мають зовсім інше, механічне призначення. Його автоматичний пристрій, відомий як Дзижчалка 323, що стоїть на північ від Обердайна біля мосту, налаштований саме на те, щоб стирати ці міцні ікла на порох у межах його безладних екологічних досліджень."}},faq={{q="Звідки беруться Ікла Місячного Скрадайла?",a="Їх добувають із різних місячних скрадачів Темного Узбережжя — малих і дорослих, самців-батьків, матріархинь і невловимого хижака на ім'я Тіньокіготь.",al={"де взяти ікла місячного скрадайла","хто дропає ікла місячного скрадайла","джерело іклів"}},{q="Кому потрібні Ікла Місячного Скрадайла?",a="Гном-інженер Візбанґ Кранктоґґл просить шість таких іклів, щоб закинути їх у Дзижчальну Скриньку 323 — автоматичний спостережний пристрій на північ від Обердайна, біля мосту через річку.",al={"кому потрібні ікла","яке завдання потребує ікла","здати дзижчальну скриньку 323"}},{q="Що відбувається з іклами в машині?",a="Щойно ікла потрапляють у Дзижчальну Скриньку 323, внутрішні шестерні оживають і миттю перемелюють тверді ікла на дрібний порох — для чудернацьких польових дослідів Візбанґа.",al={"що робить дзижчальна скринька 323","навіщо молоти ікла"}}},fp="16,233,20.533.0,37.170.0,28.173.0,45.160.0"}
P.entries["item:moonwell-water-tube"] = {n="Пробірка з Водою Місячної Криниці",s="Пробірка з освяченою водою з місячного колодязя в Обердайні. Її сильна очищувальна магія природи потрібна, щоб перевірити таємничий червоний кристал, що вріс у східні кряжі Темного Узбережжя, і побачити, як він відгукнеться.",h="Пробірка з освяченою водою з місячного колодязя в Обердайні.",kw={"пробірка з водою місячного колодязя","місячний колодязь","червоний кристал","обердайн","сквернолісся","елуна"},ang={["class:Druid"]="Друїди вважають воду місячного колодязя важливим провідником рівноваги природи, що якнайкраще годиться, аби протидіяти протиприродній порчі.",["race:NightElf"]="Перевіряти чужинську порчу благословенною водою з місячного колодязя — саме так калдореї покладаються на ласку Елуни, щоб відкривати приховані істини."},sec={{t="Посудина очищувальних вод",b="Набрана просто з мерехтливого місячного колодязя в Обердайні, Пробірка з Водою Місячної Криниці містить рідину, просякнуту благословенними енергіями Елуни. Місячні колодязі служать поселенням нічних ельфів священними сховищами відновлювальної магії й чистоти, тож навіть невеличка пробірка напрочуд сильна проти порчі чи невідомих містичних явищ."},{t="Розслідування червоного кристала",b="Пробірку підготували саме для того, щоб перевірити величезний чужинський червоний кристал, що з'явився на східному скелястому схилі Темного Узбережжя. Оскільки просто над гірською стіною здіймаються спотворені висоти Сквернолісся, дослідники побоювалися, що багряне утворення має таке саме темне походження. Коли благословенна вода стікає гранями кристала, магія змушує непрозорий камінь ненадовго стати прозорим і відкриває таємниці, що гудуть, замкнені всередині."}},faq={{q="Звідки набирають воду?",a="Воду зачерпують просто зі священного Місячного Колодязя в прихистку нічних ельфів — Обердайні, у самому серці Темного Узбережжя.",al={"де наповнити пробірку","джерело води пробірки","вода місячного колодязя обердайна"}},{q="Навіщо поливати червоний кристал водою з місячного колодязя?",a="Вода з місячного колодязя несе зосереджену магію природи й місяця. Якщо полити нею дивний червоний кристал, вона перевіряє його магічний склад і викликає неземну реакцію: непрозора поверхня мінералу на мить стає прозорою.",al={"чому вода місячного колодязя","призначення пробірки з водою","що робить вода"}},{q="Чому кристал непокоїть дослідників?",a="Кристал лежить просто під східними горами на межі зі Скверноліссям. Зважаючи на глибоку демонічну скверну Сквернолісся, учені бояться, що це чужинське утворення — продовження тієї скверни, яка просочується вниз, на Темне Узбережжя.",al={"навіщо перевіряти кристал","небезпека червоного кристала","зв'язок із скверним лісом"}}},fp="19,208,28.336.0,29.443.1,30.132.0,42.218.0,52.213.0"}
P.entries["item:mossy-tumor"] = {n="Моховий Наріст",s="Моховий Наріст — гидка отруйна пухлина, яку вирізають із кори й плоті зіпсованих деревляників Тельдрассилу. Такі нарости трапляються здебільшого довкола Озера Джерела і є зовнішньою ознакою моторошного зла, що поширюється новим Світовим Древом.",h="Моховий Наріст — гидка отруйна пухлина, яку вирізають із кори й плоті зіпсованих деревляників Тельдрассилу.",kw={"моховий наріст","деревляники","озеро джерела","тельдрассил","релліан ґрінспайр","пухлини","скверна"},ang={["class:Druid"]="Для друїдів, відданих рівновазі природи, рослинні охоронці на кшталт деревляників, укриті отруйними пухлинами, — тривожний знак: із Тельдрассилом щось глибоко не так.",["race:NightElf"]="Нічні ельфи посадили Тельдрассил, щоб відновити втрачений зв'язок із природою, тож хворобливі нарости, які так швидко з'явилися на їхньому новому домі, — тривожна прикмета."},sec={{t="Симптом недуги Тельдрассилу",b="Деревляників Тельдрассилу створили, щоб вони плекали й доглядали гілля великого дерева, але багато з них стали ворожими й хворими. Ці мохові нарости — тілесний вияв внутрішньої недуги. Переповнені отрутою, вони проростають на тілах болотяних звірів, топтунів і старих деревляників, що блукають біля Озера Джерела. Релліан Ґрінспайр і хранителі Дарнасуса доручають мандрівникам зрізати ці нарости, щоб їх можна було дощенту спалити й не дати отруті глибше вкоренитися в землі острова."}},faq={{q="Що таке Моховий Наріст?",a="Це хворобливий наріст, який знімають із тіл отруєних деревляників. Сповнені мерзенної отрути, ці нарости показують, що духи природи Тельдрассила потерпають від неприродного зіпсуття.",al={"моховий наріст","що це за наріст","наріст деревляника"}},{q="Де знайти Мохові Нарости?",a="Їх збирають із зіпсованих деревляників — деревляників-топтунів, болотяних звірів і старих деревляників, — що блукають довкола Озера Джерела на півночі Тельдрассила.",al={"де взяти нарости","дроп мохового нароста","місце деревляників"}},{q="Навіщо Релліанові Ґрінспайру ці нарости?",a="Релліан прагне стримати зіпсуття, що вражає Тельдрассил. Збираючи нарости й спалюючи їх на попіл, він не дає зосередженій у них отруті знову просочитися в ґрунт і воду.",al={"нарости релліана ґрінспайра","навіщо палити нарости"}},{q="Чому деревляники хворіють?",a="Темне лихо почало опановувати Тельдрассил, спотворюючи його доглядачів і диких створінь. Нічні ельфи шукають справжнє джерело недуги, але деревляників із помітними наростами вже вважають неврятованими.",al={"чому деревляники хворі","скверна деревляників"}}},fp="11,263,33.546.0,22.203.0,31.170.0,46.197.0,42.255.0"}
P.entries["item:mountain-lion-blood"] = {n="Кров Гірського Лева",s="Кров Гірського Лева — складник, який добувають із хижаків, що нишпорять Передгір'ям Гілсбреда та засніженими схилами Альтераку. Аптекар Лайдон із Таррен Мілла шукає цю свіжу кров, щоб створити страшний Еліксир Болю Королівського Аптекарського Товариства.",h="Кров Гірського Лева — складник, який добувають із хижаків, що нишпорять Передгір'ям Гілсбреда та засніженими...",kw={"кров гірського лева","гірські леви","аптекар лайдон","еліксир болю","таррен мілл","нова чума"},ang={["faction:Horde"]="Збирання звірячих складників довкола Таррен Мілла безпосередньо зміцнює укріплену присутність Орди проти ворожих людських осередків у Гілсбреді.",["race:Undead"]="Кожен зібраний флакон допомагає Королівському Аптекарському Товариству розробляти нищівну біологічну зброю, щоб закріпити Лордерон за Відступниками."},sec={{t="Складник із пагорбів",b="Нагір'ям і передгір'ям обабіч Гілсбреда й Альтераку нишпорять дикі, виголоднілі гірські леви. Звичайні мисливці полюють на цих хижаків заради шкур і пазурів, а Відступники з Королівського Аптекарського Товариства цінують те, що тече в їхніх жилах. Свіжа кров гірського лева має особливі біологічні властивості, і Аптекар Лайдон у Таррен Міллі вірить, що вона стане основою для нового потужного отруйного варива, покликаного нести живим страждання."},{t="Паливо для Нової Чуми",b="Досліди Аптекаря Лайдона в Таррен Міллі безпосередньо служать головному дорученню Королівського Аптекарського Товариства — удосконаленню Нової Чуми Відступників. Збираючи кров сильних диких звірів, Лайдон прагне вдосконалити суміш, яку називає Еліксиром Болю, перевіряючи, наскільки дієво місцеві органічні сполуки можна обернути на зброю проти ворогів Темної Леді."}},faq={{q="Для чого потрібна Кров Гірського Лева?",a="Аптекареві Лайдону в Таррен Міллі потрібно десять фіалів Крові Гірського Лева, щоб перегнати смертоносне вариво — Еліксир Болю, частину досліджень нових хвороб Королівського Аптекарського Товариства.",al={"для чого кров гірського лева","кому потрібна кров лева","кров для еліксиру болю"}},{q="Де зібрати Кров Гірського Лева?",a="Її беруть у гірських левів, що полюють по всьому Передгір'ю Гілсбреда й у сусідніх засніжених кручах Гір Альтерак.",al={"де знайти кров гірського лева","місце крові гірського лева","які леви дропають кров"}},{q="Чому Аптекар Лайдон хоче саме кров диких котів?",a="Лайдон вважає, що життєві соки лютих і витривалих гірських левів — ідеальна жива основа для особливо болісного отруйного варива проти живих мешканців Гілсбреда.",al={"чому кров лева","чому лайдон хоче кров лева"}},{q="Чи придатна Кров Гірського Лева для алхімічних рецептів?",a="Ні. Це суто експериментальний дослідницький реагент, який збирають для особистої роботи Аптекаря Лайдона, а не складник звичайної ремісничої алхімії.",al={"чи алхіміки можуть використати кров гірського лева","чи кров лева для алхімії"}}},fp="19,253,20.474.0,22.370.0,37.200.0,43.139.0,59.206.0,59.158.0"}
P.entries["item:mudsnout-blossom"] = {n="Суцвіття Багнорила",s="Суцвіття Багнорила — смердючі отруйні гриби, що проростають на Хуторі Нетандера в Передгір'ї Гілсбреда. Їх стережуть місцеві гноли, а збирає Королівське Аптекарське Товариство: ці мерзенні гриби йдуть на дослідження еліксирів Аптекаря Лайдона.",h="Суцвіття Багнорила — смердючі отруйні гриби, що проростають на Хуторі Нетандера в Передгір'ї Гілсбреда.",kw={"суцвіття багнорила","гриби","хутір нетандера","аптекар лайдон","таррен мілл","еліксир агонії"},ang={["profession:Herbalism"]="Хоча ботаніки й травники через назву можуть прийняти його за звичайну квітку, Суцвіття Багнорила — нестійкий смердючий гриб, який дуже цінують знавці отрут і темні алхіміки.",["race:Undead"]="Відступники широко використовують отруйні властивості цих грибів, збираючи їх, щоб удосконалювати біохімічну зброю для Королівського Аптекарського Товариства."},sec={{t="Отруйний гриб",b="Попри квіткову назву, Суцвіття Багнорила — це насправді великі смердючі гриби, що буйно ростуть переважно в забрудненій землі Хутора Нетандера, на південь від Таррен Мілла. Вони виростають серед таборів місцевих гнолів-Багнорилів, які люто боронять цю землю. Для живих істот спори й м'якуш гриба — заразна отрута, що спричиняє муки й швидкий розпад тіла."},{t="Паливо для Королівського Аптекарського Товариства",b="У Таррен Міллі Аптекар Лайдон шукає Суцвіття Багнорила як сировину для своїх хімічних дослідів. За дорученням Леді Сильвани Віндраннер Королівське Аптекарське Товариство невпинно працює над новою чумою, здатною знищити і Погибель, і живе людство. Їдкі властивості цих грибів, що висушують плоть, роблять їх ідеальною основою для варива Лайдона — сумнозвісного Еліксиру Агонії."}},faq={{q="Що таке Суцвіття Багнорила?",a="Попри назву «суцвіття», це великий смердючий отруйний гриб, що росте у вогкому ґрунті Передгір'я Гілсбреда.",al={"лор суцвіття багнорила","чи суцвіття квітка","що за рослина суцвіття багнорила"}},{q="Де ростуть Суцвіття Багнорила?",a="Вони ростуть по всьому Хутору Нетандера — покинутому хуторі на південь від Таррен Мілла й на схід від річки, що тече повз Саутшор. Там аж кишить гнолами-Багнорилами.",al={"місце суцвіття багнорила","де знайти суцвіття багнорила","гриби нетандерського двору"}},{q="Навіщо їх збирає Королівське Аптекарське Товариство?",a="Аптекареві Лайдону в Таррен Міллі вони потрібні, щоб зварити Еліксир Агонії. Відступники досліджують отрути, щоб створити нову чуму, здатну вигубити і живих, і Погибель.",al={"чому лайдон хоче суцвіття","інгредієнти еліксиру агонії","гриб аптекаря лайдона"}},{q="Для чого Королівське Аптекарське Товариство використовує суцвіття?",a="Аптекар Лайдон збирає ці смердючі гриби для свого наступного еліксиру — це частина досліджень Відступників у галузі хвороб і отрут.",al={"досліди із суцвіттям багнорила","суцвіття багнорила для еліксиру"}}},fp="16,254,14.399.0,37.429.1,27.120.0,32.181.0,52.192.0,60.134.0"}
P.entries["item:mudsnout-composite"] = {n="Порошок Багнорила",s="Порошок Багнорила — алхімічна суміш, яку Аптекар Лайдон у Таррен Міллі готує із зібраних Суцвіть Багнорила. Її відносять до Андерсіті як важливу основу для досліджень Королівського Аптекарського Товариства над новою чумою.",h="Порошок Багнорила — алхімічна суміш, яку Аптекар Лайдон у Таррен Міллі готує із зібраних Суцвіть Багнорила.",kw={"порошок багнорила","суцвіття багнорила","аптекар лайдон","таррен мілл","еліксир агонії","головний аптекар фаранелл","травництво"},ang={["profession:Herbalism"]="Суцвіття Багнорила доводять, що навіть скромну місцеву рослину досвідчений аптекар може розтерти й обернути на зброю.",["race:Undead"]="Кожна така партія, як цей порошок, прямо служить наказу Темної Леді: забезпечити майбутнє Відступників, створивши чуму, що знищить і живих, і Погибель."},sec={{t="Основа для розкладу",b="Цей тонкий порошок Аптекар Лайдон виготовляє просто в полі із Суцвіть Багнорила, зібраних у Передгір'ї Гілсбреда. Він і сам по собі отруйний, але щоб розкрити смертоносніші властивості, йому потрібен особливий колоїд розкладу, який готує сам Головний Аптекар Фаранелл. Поєднана з ним, суміш стає ключовим хімічним складником Еліксиру Агонії, що його створюють для Темної Леді."},{t="Аптекарське листування",b="Шлях порошку з Таррен Мілла до Апотекаріуму Андерсіті показує, як працює алхімія Відступників: розпорошено й крок за кроком. Польові дослідники постійно збирають місцеві реагенти й відсилають зразки до столичних майстрів на доопрацювання. Хоч Леді Сильвана наполегливо вимагає швидких результатів проти живих людей і Погибелі, Фаранелл хвалить порошок як винахідливе підґрунтя для їхньої великої мети."}},faq={{q="Для чого потрібен Порошок Багнорила?",a="Це проміжна паста із Суцвіть Багнорила. Головний Аптекар Фаранелл в Андерсіті має обробити її колоїдом розкладу — це допомагає створити Еліксир Агонії.",al={"призначення порошку багнорила","що робить порошок багнорила"}},{q="Хто створив порошок?",a="Аптекар Лайдон, дослідник-Відступник із Таррен Мілла в Передгір'ї Гілсбреда, розтер свіжі суцвіття й замісив пасту, перш ніж надіслати її на північ.",al={"хто зробив порошок багнорила","творець порошку багнорила"}},{q="Навіщо він Головному Аптекареві Фаранеллу?",a="Фаранелл керує великою працею Королівського Аптекарського Товариства над новою чумою. Порошок Лайдона дає ту особливу рослинну основу, що потрібна для подальших досліджень смертоносних отрут.",al={"чому нести фараннелу","фараннел багнорил"}}},fp="18,249,16.417.0,25.449.1,40.196.0,26.157.0,44.190.0"}
P.entries["item:mudsnout-mixture"] = {n="Суміш Багнорила",s="Суміш Багнорила — отруйна алхімічна основа, яку готує Головний Аптекар Фаранелл в Андерсіті. Її створюють, змішуючи порошок багнорила з алхімічним колоїдом розкладу, і вона стає основою смертоносного Еліксиру Агонії Королівського Аптекарського Товариства.",h="Суміш Багнорила — отруйна алхімічна основа, яку готує Головний Аптекар Фаранелл в Андерсіті.",kw={"суміш багнорила","колоїд розкладу","еліксир агонії","аптекар лайдон","головний аптекар фаранелл","таррен мілл","хутір нетандера"},ang={["faction:Horde"]="Шукачі пригод з Орди, що працюють у Таррен Міллі, стають гінцями й польовими агентами: вони переносять отруйні суміші через Лордерон, щоб зміцнити позиції Відступників у Гілсбреді.",["race:Undead"]="Ця суміш показує безжальну винахідливість Королівського Аптекарського Товариства: прості дикі складники воно перетворює на хімічну зброю, створену, щоб нищити живих."},sec={{t="Колоїд розкладу",b="Коли Аптекар Лайдон у Таррен Міллі береться створити нову заразну біологічну зброю, він відсилає на північ, до Андерсіті, основу — порошок із Суцвіть Багнорила, отруйних грибів із захопленого гнолами Хутора Нетандера. Вражений можливостями порошку, Головний Аптекар Фаранелл додає до нього власний колоїд розкладу й отримує нестійку Суміш Багнорила. Розчин стабілізує грибну сполуку й водночас готує її заразні властивості до подальшої обробки каталізаторами вже в передгір'ях."},{t="Каталіз агонії",b="Хоч Суміш Багнорила й сильнодійна, без ключових каталізаторів, що пробуджують її заразні речовини, вона бездіяльна. Фаранелл доручає гінцям повернути пляшечку до Таррен Мілла разом із Сильним Еліксиром Тролячої Крові, отруйною лускою наг Кинджалоспинних та очима мурлоків Подертих Плавців. Коли Лайдон додасть каталізатори, суміш перетвориться на смертоносний Еліксир Агонії — фірмову отруту, покликану сіяти загибель серед живих ворогів Відступників."}},faq={{q="Для чого потрібна Суміш Багнорила?",a="Вона слугує проміжною хімічною основою для Еліксиру Агонії — експериментальної отрути, яку Аптекар Лайдон у Таррен Міллі вдосконалює, щоб нищити ворогів Відступників.",al={"призначення суміші багнорила","що робить суміш багнорила","використання суміші багнорила"}},{q="Хто створює Суміш Багнорила?",a="Її створює Головний Аптекар Фаранелл, очільник Королівського Аптекарського Товариства в Апотекаріумі Андерсіті, насичуючи сирий порошок багнорила власним колоїдом розкладу.",al={"хто робить суміш багнорила","творець суміші багнорила"}},{q="Чому для неї потрібні частини гнолів?",a="Не потрібні, попри назву. Порошок роблять із Суцвіть Багнорила — отруйних грибів, що ростуть на Хуторі Нетандера серед гнолів-Багнорилів; Аптекар Лайдон замішує з них порошок, а тоді Фаранелл додає свій колоїд розкладу.",al={"чому багнорил","лор отрути гнолів"}},{q="Як суміш активують?",a="Щоб пробудити приховані заразні складники суміші, Аптекареві Лайдону потрібні Сильний Еліксир Тролячої Крові, а також луска наг Кинджалоспинних і очі мурлоків-Подертих Плавців, зібрані на узбережжі Гілсбреда.",al={"активувати суміш багнорила","реагенти еліксиру агонії"}}},fp="16,266,18.511.0,20.436.1,38.184.0,33.196.0,37.235.0,29.216.0"}
P.entries["item:murloc-head"] = {n="Голова Мурлока",s="Голови Мурлоків — моторошні трофеї, відтяті в земноводних істот, що нишпорять Західним Узмор'ям у Передгір'ї Гілсбреда. Лейтенантові Фаррену Орінеллю із Саутшора вони потрібні як речовий доказ знищених загроз, щоб задовольнити свого начальника, Маршала Редпата.",h="Голови Мурлоків — моторошні трофеї, відтяті в земноводних істот, що нишпорять Західним Узмор'ям у Передгір'ї...",kw={"голова мурлока","мурлоки","західне узмор'я","фаррен орінелль","маршал редпат","саутшор"},ang={["faction:Alliance"]="Очищення Західного Узмор'я захищає крихке рибальське господарство Саутшора й убезпечує узбережжя вразливої твердині Альянсу в Лордероні."},sec={{t="Моторошніший різновид доказу",b="Саутшорові загрожують небезпеки з усіх боків, але войовничі мурлоки, що скупчуються вздовж Західного Узмор'я, — нагальна загроза для місцевих рибалок і мандрівників узбережжям. Хоча шукачі пригод з Альянсу часто прочісують пляжі, винищуючи цих істот, Маршал Маркус Редпат вимагає незаперечних доказів, перш ніж підписати оборонні звіти. Щоб догодити бюрократії, Лейтенант Фаррен Орінелль покладається на найманих бійців, які приносять холодні, мокрі голови мурлоків, — неприємна справа, яку сам Фаррен вважає цілком огидною, надто ж тому, що це видовище геть відбило йому апетит до місцевих морепродуктів Саутшора."}},faq={{q="Навіщо Фаррену Орінеллю голови мурлоків?",a="Маршала Маркуса Редпата не вдовольнили прості донесення, що пляжі очищено від мурлоків. Щоб пересвідчитися, що загроза справді поменшала, він вимагав речових доказів — і Лейтенантові Фаррену довелося збирати відтяті голови.",al={"докази фаррена","навіщо голови мурлоків","хто хоче голови мурлоків у саутшорі"}},{q="Де знайти цих мурлоків?",a="Їх збирають із племен мурлоків, що заполонили Західне Узмор'я — узбережжя на захід від Саутшора в Передгір'ї Гілсбреда.",al={"місце голови мурлока","де взяти голови мурлоків гілсбред","мурлоки західного берега"}},{q="Чому Фаррену вони такі гидкі?",a="Фаррен вважає ходячу рибу протиприродною й огидною до нудоти. Вигляд слизьких закривавлених голів, з яких скапує на підлогу, так його гидить, що він відмовляється їсти рибу — а в портовому містечку на кшталт Саутшора це головна їжа.",al={"реакція фаррена","фаррен їсть рибу"}},{q="Чи розв'язують голови проблему мурлоків у Саутшорі?",a="Голови дають доказ, якого вимагав Маршал Редпат. Він приймає їх і посилає Фаррена зайнятися загрозами на Східному Побережжі.",al={"чи припинять мурлоки нападати","ланцюжок завдань фаррена"}}},fp="11,253,24.630.0,43.239.0,30.138.0,35.248.0,60.158.0"}
P.entries["item:musquash-root"] = {n="Мускусний Корінь",s="Мускусний Корінь — рідкісна рослина, що росте лише у вологому ґрунті під величезними водоспадами Каменетесної Греблі в Багнокраї. Це важливий складник зілля, яке варять культисти, що ховаються під Стормвіндом.",h="Мускусний Корінь — рідкісна рослина, що росте лише у вологому ґрунті під величезними водоспадами Каменетесної...",kw={"мускусний корінь","каменетесна гребля","багнокрай","зардет із чорного кігтя","сльоза тіллоа","лорд вішок"},ang={["class:Warlock"]="Для чорнокнижників, що діють під «Зарізаним Ягням», цей корінь — необхідність, щоб змусити замовкнути цікавих вельмож і вберегти свій хиткий прихисток у місті.",["profession:Herbalism"]="Хоч це й не звичайна торгова трава, корінь показує, як особливі мікроклімати, як-от підніжжя Каменетесної Греблі, плекають неповторні й небезпечні рослини."},sec={{t="Рідкісний складник",b="Мускусний Корінь буяє у вічно змоченому туманом ґрунті, куди спадає водоспад Каменетесної Греблі в Багнокраї. Через відлюдне й вологе місце зростання його надзвичайно важко зібрати. Звичайні травники рідко його шукають, проте деякі знавці темних мистецтв цінують корінь за сильні хімічні й алхімічні властивості."},{t="Задум чорнокнижника",b="Під вулицями Стормвінда, в темному підпіллі, відомому як «Зарізане Ягня», Зардет із Чорного Кігтя шукає цей корінь разом зі Сльозою Тіллоа. Разом ці рідкісні рослини — основа тонкого зілля, щоб позбутися Лорда Вішока, члена Дому Вельмож, який почав пхати носа в справи прихованого міського ковену чорнокнижників."}},faq={{q="Де знайти Мускусний Корінь?",a="Мускусний Корінь росте лише в Багнокраї — біля самого підніжжя великого водоспаду під Каменетесною Греблею.",al={"де мускусний корінь","місце мускусного кореня","як знайти мускусний корінь"}},{q="Для чого потрібен Мускусний Корінь?",a="Зардет із Чорного Кігтя просить його разом зі Сльозою Тіллоа для напою, що має відволікти лорда Вішока й спинити його вимоги розслідувати ковен чорнокнижників Стормвінда.",al={"що робить мускусний корінь","призначення мускусного кореня","навіщо мені мускусний корінь"}},{q="Хто хоче, щоб цей корінь зібрали?",a="Зардет із Чорного Кігтя, чорнокнижник із катакомб під корчмою «Зарізане Ягня» в Кварталі магів Стормвінда, посилає агентів по нього.",al={"кому потрібен мускусний корінь","видавець завдання на мускусний корінь","хто просить мускусний корінь"}},{q="Хто такий лорд Вішок?",a="Лорд Вішок — член Дому Вельмож Стормвінда, який дізнався про ковен чорнокнижників у місті й почав домагатися від ради офіційного розслідування.",al={"хто такий вішок","лорд вішок"}}},fp="13,234,17.354.0,20.367.1,29.122.0,31.190.0,30.151.0,20.176.0"}
P.entries["item:mysterious-fossil"] = {n="Таємнича Скам'янілість",s="Таємнича Скам'янілість — давній зразок, який шукач Ремтревел відкопав на березі Темного Узбережжя. Її дивні особливості збудили жвавий інтерес дворфської Ліги Дослідників, і вчені переправляють її за море, щоб розкрити приховані таємниці.",h="Таємнича Скам'янілість — давній зразок, який шукач Ремтревел відкопав на березі Темного Узбережжя.",kw={"таємнича скам'янілість","шукач ремтревел","ґрейвіскер","флеґонґат","ліга дослідників","гавань менетіл"},ang={["faction:Alliance"]="Переправлення реліквії показує, який важливий ланцюг постачання пов'язує застави Альянсу — від польових розвідників на Темному Узбережжі до вчених у Дарнасусі й Гавані Менетіл.",["race:Dwarf"]="Для дворфів ця скам'янілість — ще один утрачений шматочок у нескінченних пошуках Ліги Дослідників, що прагне скласти докупи давню спадщину титанів і відкопати забуті таємниці."},sec={{t="Цікава знахідка",b="Працюючи на диких берегах Темного Узбережжя, шукач Ремтревел знайшов скам'янілість, не схожу на звичайне закам'яніле каміння, розкидане по всьому Калімдору. Вважаючи її пам'яткою величезного історичного значення, Ремтревел домовився, щоб зразок доставили дворфським ученим, а не лишили марніти в нетрях. Коли реліквію принесли до головного археолога Ґрейвіскера в Дарнасусі, її одразу визнали надзвичайною знахідкою."},{t="Зв'язки за океаном",b="Головний археолог Ґрейвіскер помітив, що зразок дивовижно схожий на іншу рідкісну скам'янілість, яку колись показували на зібранні Ліги Дослідників в Айронфорджі. Ту першу знахідку досліджував археолог Флеґонґат, який підозрював, що в камені дрімає прихована сила, яка чекає на пробудження. Щоб з'ясувати походження скам'янілості й розкрити її можливі таємниці, Ґрейвіскер велів кур'єрам переправити її через океан до Флеґонґата, який чекає в Таверні «Глибока Вода» в Гавані Менетіл."}},faq={{q="Де знайшли Таємничу Скам'янілість?",a="Скам'янілість знайшов Шукач Ремтревел на Темному Узбережжі під час польових робіт на прадавньому північному березі Калімдору.",al={"місце скам'янілості","де її знайшли","походження скам'янілості"}},{q="Навіщо Лізі Дослідників ця скам'янілість?",a="Ліга Дослідників присвячує себе вивченню прадавніх артефактів і походження світу. Головний Археолог Ґрейвіскер вважає, що цей зразок пов'язаний із дослідженнями Археолога Флеґонґата, який припускав, що в таких скам'янілостях може критися сила, яку можна пробудити.",al={"чому дворфи її хочуть","інтерес ліги дослідників","що робить скам'янілість"}},{q="Хто такий Археолог Флеґонґат?",a="Археолог Флеґонґат — дослідник Ліги Дослідників, відомий вивченням схожих скам'янілих реліквій. Зараз він зупинився в Таверні «Глибока Вода» в Гавані Менетіл і чекає супроводу до Місця Розкопок Велґара в Багнокраї.",al={"хто такий флеґонґат","місце флеґонґата","де флеґонґат"}},{q="Хто такий Головний Археолог Ґрейвіскер?",a="Головний Археолог Ґрейвіскер — старший представник Ліги Дослідників у Дарнасусі, що наглядає за дослідженнями дворфів і археологічними роботами на півночі Калімдору.",al={"ґрейвіскер","хто такий ґрейвіскер","дворф-археолог дарнасуса"}}},fp="17,282,19.454.0,21.507.1,38.133.0,48.268.0,31.248.0,39.190.0"}
P.entries["item:nak-s-skull"] = {n="Череп Нака",s="Череп Нака — моторошний мисливський трофей, відтятий у Нака, одного з трьох помітних ватажків шипогривів-Гостроманів, що водили бойові загони на півдні Пусток. Його шукає полонений шипогрив Понівечозуб: як доказ поразки нападника і як помсту за гірку зраду рідного племені.",h="Череп Нака — моторошний мисливський трофей, відтятий у Нака, одного з трьох помітних ватажків...",kw={"череп нака","нак","гостромани","шипогриви","понівечозуб","табір тауражо"},ang={["faction:Horde"]="Знищення ватажків Гостроманів, як-от Нака, знімає величезний тиск зі шляхів постачання Орди між Табором Тауражо й Перехрестям."},sec={{t="Знак помсти",b="Вийшовши з Рейзорфен Краулу, трійця — Нак, Куз і Лок Оркбейн — почала жорстокі набіги на поселення й дороги Орди по всіх Пустках. Оборонцям Перехрестя було невідомо, що ці воєначальники готують напади, куди хитріші за звичайні племінні сутички. Коли полоненого Гостромана Понівечозуба покинули помирати в клітці в Таборі Тауражо, його жага відплати обернулася проти колишніх побратимів. Вимагаючи речового доказу Накової смерті, Понівечозуб просить шукачів пригод з Орди принести відтятий череп разом із черепами його спільників — і так зламати хребет південним загонам нападників."}},faq={{q="Хто такий Нак?",a="Нак — хитрий ватажок шипогривів-Гостроманів, що вийшов із Рейзорфен Краул разом із Куз і Локом Оркбейном. Утрьох вони спрямовували смертоносні сутички й набіги на мандрівників і поселення Орди по всьому півдню Пусток.",al={"хто такий нак","лор нака","нак пустища"}},{q="Кому потрібен Череп Нака?",a="Череп вимагає Понівечозуб — полонений шипогрив-Гостроман, якого тримають у дерев'яній клітці в Таборі Тауражо. Озлоблений тим, що власні родичі кинули його напризволяще, Понівечозуб прагне кривавої помсти ватажкам, які його зрадили.",al={"хто хоче череп","кому віддати череп нака","череп понівечозуба"}},{q="Чому Понівечозуб хоче черепів своїх же родичів?",a="Нак, Куз і Лок Оркбейн відвернулися від Понівечозуба й лишили його помирати в полоні. Мстячись за зраду, Понівечозуб допомагає Орді: видає, де вони ховаються, і вимагає їхні відтяті голови як доказ їхньої загибелі.",al={"чому зраджувати плем'я","мотив понівечозуба","чому понівечозуб хоче черепи"}},{q="Чи допомагає Череп Нака захистити Перехрестя?",a="Так. За словами Понівечозуба, Нак і його спільники були хитрими головами за зухвалими набігами Гостроманів, що тиснули на Перехрестя й центральні торгові шляхи. Їхня смерть завдає нищівного удару злагодженій війні племені.",al={"перехрестя в безпеці","припинити набіги квілборгів"}}},fp="11,277,20.637.0,12.236.0,22.237.0,55.251.0,56.248.0"}
P.entries["item:nek-rosh-s-head"] = {n="Голова Нек'роша",s="Голова Нек'роша — моторошний доказ загибелі Вождя Нек'роша, ватажка клану Драконячої Пащі в Багнокраї. Здобутий шукачами пригод з Альянсу, цей трофей вручають Капітанові Стаутфісту як підтвердження того, що загрозу орків для Гавані Менетіл зламано.",h="Голова Нек'роша — моторошний доказ загибелі Вождя Нек'роша, ватажка клану Драконячої Пащі в Багнокраї.",kw={"голова нек'роша","вождь нек'рош","драконяча паща","капітан стаутфіст","гавань менетіл","багнокрай"},ang={["faction:Alliance"]="Вручивши цей похмурий трофей Капітанові Стаутфісту, ви вбережете Гавань Менетіл від неминучого нападу й здобудете чималу прихильність Королівства Айронфордж.",["race:Dwarf"]="Драконяча Паща терзає Каз Модан ще з Другої війни; принесена відтята голова вождя — довгоочікувана справедливість для захисників боліт."},sec={{t="Вирішальний удар",b="Клан Драконячої Пащі — постійна небезпека для болотяних земель: він збирає сили й облогові знаряддя проти порту Альянсу, Гавані Менетіл. Після того як катапульти спалено, оборона порту залежить від того, чи вдасться вбити самого Вождя Нек'роша. Відтята голова — незаперечний доказ для Капітана Стаутфіста й влади Айронфорджа, що хватку цього воєначальника над Багнокраєм зламано."}},faq={{q="Хто такий Нек'рош?",a="Нек'рош — вождь, що очолював рештки клану Драконячої Пащі в Багнокраї й спрямовував напади та воєнні зусилля на довколишні землі Альянсу.",al={"хто такий нек'рош","вождь нек'рош","хто був нек'рош"}},{q="Кому потрібна Голова Нек'роша?",a="Капітан Стаутфіст, що керує обороною Гавані Менетіл, вимагає голову як речовий доказ загибелі вождя, перш ніж нагородити поборника від імені Айронфорджа.",al={"хто бере голову","здати голову нек'роша","куди нести голову нек'роша"}},{q="Чому Нек'рош став мішенню?",a="Нек'рош керував силами Драконячої Пащі, що загрожували Гавані Менетіл. Знищивши їхні облогові машини й убивши вождя, Альянс мав намір завдати нищівного удару присутності клану в краї.",al={"чому вбити нек'роша","чому перемогти нек'роша"}}},fp="15,281,17.395.0,17.175.0,26.198.0,36.220.0"}
P.entries["item:neru-fragment"] = {n="Уламок Неру",s="Уламок Неру — одна з чотирьох прадавніх різьблених кам'яних частин Каменя Ґоаза, реліквії, знайденої на Місці Розкопок Велґара в Багнокраї. Відкопаний із розритої землі, він містить частину давнього письма титанів про первісну історію Азероту.",h="Уламок Неру — одна з чотирьох прадавніх різьблених кам'яних частин Каменя Ґоаза, реліквії, знайденої на Місці...",kw={"уламок неру","камінь ґоаза","шукач велґар","титани","ліга дослідників","багнокрай"},ang={["race:Dwarf"]="Для Ліги Дослідників повернути частини таблички, як-от Уламок Неру, конче потрібно, щоб розкрити таємниці титанів і скласти докупи історію походження дворфійського роду."},sec={{t="Частина Каменя Ґоаза",b="Discovered by the dwarven archaeological expedition led by Prospector Whelgar, the Goaz Stone broke apart into four distinct remnants: the Ados, Modr, Golm, and Neru fragments. When raptors overrun the dig site, work ground to a halt, leaving the Neru Fragment buried beneath loose soil amid the aggressive beasts. Recovering this fragment is crucial for reassembling the tablet, allowing dwarven scholars to decipher a forgotten record whose surviving words mention a divine plan and a doomed prophecy."},{t="Reading the Restored Tablet",b="Once the four fragments restore the Goaz Stone, Prospector Whelgar continues translating its Titan script. The newly legible words speak of Old Gods chained beneath the land."}},faq={{q="Що таке Уламок Неру?",a="Це прадавній кам'яний уламок, відколотий від більшої реліквії — Каменю Ґоаза. Його відкопала дворфська експедиція в Багнокраї, перш ніж розкопки заполонили раптори.",al={"лор уламка неру","що таке уламок неру","шматок таблички неру"}},{q="Де знайти уламок?",a="Він розкиданий по Розкопках Велґара на півдні Багнокраю, де аж кишить рапторами, — зазвичай закопаний у пухкій землі чи схований серед покинутих артефактів.",al={"де знайти уламок неру","місце уламка неру","як отримати уламок неру"}},{q="Що стається, коли зібрано всі чотири уламки?",a="Prospector Whelgar pieces the Goaz Stone back together so he can continue translating its Titan script and investigate the mystery hinted at by its surviving text.",al={"камінь ґоаз завершено","що каже камінь ґоаз","кінець розкриття минулого"}}},fp="13,284,23.503.0,27.174.1,26.175.0,28.158.0,50.163.1"}
P.entries["item:nessa-s-collection"] = {n="Збірка Несси",s="Збірка Несси — пакунок риб'ячих кісток і луски, зібраних у водах довкола Селища Рут'теран. Призначена для вивчення рибним торговцем Лейрдом з Обердайна, вона показує, якими незвично величезними виростають водяні створіння біля коріння Тельдрассилу.",h="Збірка Несси — пакунок риб'ячих кісток і луски, зібраних у водах довкола Селища Рут'теран.",kw={"збірка несси","несса шедовсонг","лейрд","тельдрассил","селище рут'теран","веспристус"},ang={["race:NightElf"]="Збірка вперше відкриває нічним ельфам незвичну буйність вод довкола Тельдрассилу — саме тоді, коли вони перебираються з рідного острова на материк."},sec={{t="Щедроти Світового Дерева",b="Несса Шедовсонг, рибалка, що живе в Селищі Рут'теран біля підніжжя Тельдрассилу, зібрала ці риб'ячі кістки й луску, щоб порівняти морське життя острова з тим, що на материку Калімдору. Води, що омивають Велике Дерево, дають улов приголомшливих розмірів, тож Несса посилає речові докази за море Лейрдові — рибному торговцеві, що працює на пристанях Обердайна. Переданий через селищного майстра гіпогрифів Веспристуса, пакунок стає наочним доказом буйної життєвої сили Тельдрассилу."},{t="Цікаве порівняння",b="Оглянувши вміст на Темному Узбережжі, Лейрд виявляє, що зразки значно перевершують своїх материкових родичів. У збірці — щелепи майже вдвічі більші, ніж у риби з берегів Темного Узбережжя, і окремі лусочки завбільшки зі стиснений кулак. Для прибережних нічних ельфів пакунок наочно показує, наскільки води довкола Тельдрассилу відрізняються від похмурих берегів північного Калімдору."}},faq={{q="Що в Збірці Несси?",a="Збірка складається з риб'ячих кісток, завеликих щелеп і луски завбільшки з кулак — усе це з риби, виловленої у водах біля Селища Рут'теран.",al={"вміст збірки несси","що в посилці","посилка з рибними кістками"}},{q="Кому надсилають збірку?",a="Її надсилають Лейрдові — нічному ельфові, торговцеві рибою з портового селища Обердайн на Темному Узбережжі.",al={"кому збірка несси","хто такий лейрд","пункт доставки"}},{q="Навіщо Несса зібрала ці зразки риби?",a="Несса хотіла порівняти напрочуд велику рибу, що буяє довкола Тельдрассила, з морськими мешканцями материкового Калімдору.",al={"навіщо слати рибні кістки","порівняння риби несси","причина достатку тельдрассила"}},{q="Як збірка потрапляє до Обердайна?",a="Мандрівник несе пакунок до майстра гіпогрифів Рут'терана, Веспристуса, який влаштовує переліт через воду до Обердайна, щоб посилку доставили Лейрдові.",al={"як збірка потрапляє до обердайна","доставка веспристуса","гіпогриф посилка"}}},fp="18,266,24.555.0,20.434.0,34.145.0,36.113.0,42.128.0,40.169.0"}
P.entries["item:nether-gem"] = {n="Самоцвіт Порожнечі",s="Самоцвіт Порожнечі — зачарований магічний камінь, який довіряє посланцеві некромант-відлюдник Ґунтер Арканус. Сповнений магічної сили, він слугує провідником на великі відстані: через нього Ґунтер може явити свою магічну проєкцію й говорити просто зі старим соратником Бетором Айсшардом в Андерсіті.",h="Самоцвіт Порожнечі — зачарований магічний камінь, який довіряє посланцеві некромант-відлюдник Ґунтер Арканус.",kw={"самоцвіт порожнечі","ґунтер арканус","бетор айсшард","озеро світлої води","магічний квартал","некромант","маг"},ang={["class:Mage"]="Для знавців магії Самоцвіт Порожнечі — приклад того, як майстри-маги долають величезні відстані за допомогою магічного провидіння й проєкцій, замість того щоб ризикувати в дорозі.",["race:Undead"]="Доставка каменя — великий дипломатичний успіх Відступників: могутній Ґунтер Арканус стає союзником проти Погибелі й Багряного Хрестового Походу."},sec={{t="Провідник магічного єднання",b="Самоцвіт Порожнечі, викуваний або зачарований Ґунтером Арканусом на його самотньому острові посеред Озера Світлої Води, — це містичний зв'язок через усі Галявини Тірісфалю. Ґунтер, що власною силою волі вирвався з-під влади Короля-Ліча, довго з підозрою уникав молодого народу Відступників. Отримавши назад свою загублену книгу заклять, він довіряє самоцвіт посланцеві на знак доброї волі. Коли камінь приносять до Бетора Айсшарда на вершині Магічного Кварталу в Андерсіті, він являє магічний образ Ґунтера просто перед очільником Гільдії магів — і відкриває самотньому магові шлях до союзу з Леді Сильваною та Відступниками."}},faq={{q="Що робить Самоцвіт Порожнечі?",a="Самоцвіт Порожнечі дає Ґунтерові Арканусу змогу говорити на великій відстані з Бетором Айсшардом. Коли Бетор в Андерсіті спрямовує в камінь магію, той показує примарний образ Ґунтера, і двоє могутніх магів можуть розмовляти безпосередньо.",al={"призначення самоцвіту порожнечі","що таке самоцвіт порожнечі","що робить самоцвіт порожнечі"}},{q="Хто створив Самоцвіт Порожнечі?",a="Самоцвіт дає Ґунтер Арканус — грізний некромант, що живе на острові посеред Озера Світлої Води. Він вручає його шукачеві пригод, щоб той доставив його старому товаришеві Бетору, коли Ґунтерові повертають загублену книгу заклять.",al={"хто створив самоцвіт порожнечі","звідки самоцвіт порожнечі","самоцвіт ґунтера"}},{q="Чому Самоцвіт Порожнечі важливий для Відступників?",a="Саме завдяки йому Ґунтер Арканус переходить на бік Відступників. Спершу Ґунтер не довіряв іншим мерцям, боячись, що вони досі раби Погибелі; самоцвіт дає йому змогу відновити зв'язок із Бетором Айсшардом і присягнути на вірність Леді Сильвані.",al={"чому самоцвіт важливий відступникам","ґунтер відступники","самоцвіт порожнечі відступників"}}},fp="10,295,29.636.0,28.250.0,27.218.0,50.288.1"}
P.entries["item:ng-5"] = {n="НҐ-5",s="НҐ-5 — скорочена назва нітроміргліцеронію, горезвісно нестійкої хімічної сполуки. Її роздобувають для гнома-винахідника Ґаксима Растфіззла в Горах Кам'яного Кігтя, і вона — головний каталізатор його вибухових інженерних задумів.",h="НҐ-5 — скорочена назва нітроміргліцеронію, горезвісно нестійкої хімічної сполуки.",kw={"нґ-5","нітроміргліцероній","ґаксим растфіззл","вибухівка","гноми","гори кам'яного кігтя"},ang={["profession:Engineering"]="Інженери впізнають у НҐ-5 нітроміргліцероній — норовливий хімічний каталізатор, який винахідники цінують, коли звичайному чорному порохові бракує сили запалити важкі боєприпаси.",["race:Gnome"]="Підірвати цілі вози з динамітом нестійким хімічним розчином заради простого відволікання — класичне, ризиковане гномське розв'язання проблем у найкращому вигляді."},sec={{t="Небезпечний реагент",b="НҐ-5, офіційно відомий як нітроміргліцероній, — надзвичайно небезпечний хімічний розчин, з яким поводяться лише з крайньою обережністю — або з безрозсудним гномським запалом. Ґаксимові Растфіззлу, агентові в Горах Кам'яного Кігтя, ця речовина потрібна як ключова запальна сполука. За словами Ґаксима, НҐ-5 дає саме ту реакцію, що потрібна, аби підірвати цілі вози з динамітом і влаштувати потужний вибух, який має посіяти хаос серед його супротивників у краї."}},faq={{q="Що таке НҐ-5?",a="НҐ-5 означає «нітромірґліцероній» — надзвичайно нестійку й нестабільну хімічну суміш, яку використовують передусім як вибуховий запальник у складних підривних роботах і гномській інженерії.",al={"що таке нґ-5","що таке нітромірглицеронійум","предмет нґ-5"}},{q="Кому потрібна НҐ-5 і навіщо?",a="Хімікат потрібен гномові-інженерові Ґаксиму Растфіззлу в Горах Кам'яного Кігтя. Це найважливіший складник, щоб надійно підпалити кілька возів, ущерть набитих динамітом, — для видовищного відвертання уваги.",al={"кому потрібна нґ-5","ґаксім растфізл нґ-5","навіщо нґ-5"}},{q="Чи небезпечно поводитися з НҐ-5?",a="Надзвичайно небезпечно. Постачальник застерігає кур'єрів поводитися з речовиною з неймовірною обережністю й жартує, що кожен, хто не друг Ґаксима, найпевніше рознесе себе на шматки.",al={"чи безпечна нґ-5","нґ-5 вибухівка","чи вибухне нґ-5"}}},fp="4,253,18.509.0,13.183.0,23.224.0,28.187.0"}
P.entries["item:nightmare-shard"] = {n="Скалка Жаху",s="Скалка Жаху — кришталева реліквія, яку Фалла Сейджвінд вручає гінцям, оглянувши заплямований сяйливий уламок із Печер Стогонів. Вона містить чисту, але стривожену сутність Смарагдового Сну й несе тривожне видіння, яке змушує старших друїдів у Дарнасусі й Тандер Блафі негайно здійняти тривогу — і зберігати таємницю.",h="Скалка Жаху — кришталева реліквія, яку Фалла Сейджвінд вручає гінцям, оглянувши заплямований сяйливий уламок...",kw={"скалка жаху","смарагдовий сон","фалла сейджвінд","печери стогонів","гамуул рунотем","матренґіл берволкер","коло кенарія","друїд"},ang={["class:Druid"]="Для друїдів ця скалка — моторошне відкриття: їхній священний прихисток, Смарагдовий Сон, більше не вільний від скверни, а тривога за долю Наралекса в Печерах Стогонів виявляється небезпідставною.",["faction:Horde"]="Скалка приносить тяжкі вісті просто на Узвишшя Старійшин у Тандер Блафі, де Гамуул Рунтотем докладає зусиль, щоб утвердити місце тауренів у ширшому братстві Кенарія."},sec={{t="Спотворене видіння",b="Оглядаючи загадковий сяйливий уламок, знайдений глибоко в Печерах Стогонів, Фалла Сейджвінд розуміє, що його енергія значно темніша, ніж можна було гадати. Замість відбивати безтурботну життєву силу Смарагдового Сну, уламок віддзеркалює покручену, неприродну недугу — жахіття наяву. Страхаючись того, що може означати його поява, вона замикає цю заплямовану сутність у Скалці Жаху й наказує негайно доставити її старшим провідникам Кола Кенарія."},{t="Знамення пошепки",b="Отримавши скалку, Верховний Друїд Гамуул Рунтотем на Узвишші Старійшин і Матренґіл Берволкер у Дарнасусі зазирають у її глибини — і обидва майстри завмирають у приголомшеному відчаї. Видіння всередині похитує їхній спокій і підтверджує тихі підозри: у самому Сні щось пішло страшенно не так. Не бажаючи сіяти паніку серед люду, друїди швидко забирають скалку й застерігають гінця більше нікому не розповідати про побачене."}},faq={{q="Що таке Скалка Жаху?",a="Це скалка, яку Фалла Сейджвінд довіряє шукачам пригод: у ній ув'язнено сутність Смарагдового Сну з артефакту, винесеного з Печер Стогонів. Замість мирних сил природи від неї йде темне, згубне сонне видіння.",al={"що таке скалка жаху","лор скалки жаху"}},{q="Хто створив Скалку Жаху?",a="Фалла Сейджвінд передає скалку кур'єрові, дослідивши світний уламок, принесений із Печер Стогонів. Усвідомивши, наскільки серйозна й зіпсована його природа, вона доручає віднести його просто до старших друїдів на вивчення.",al={"хто створив скалку жаху","звідки скалка"}},{q="Чому скалка так тривожить проводирів друїдів?",a="Зазирнувши в скалку, Гамуул Рунтотем і Матренґіл Берволкер бачать, що Смарагдовий Сон уже спотворює жахіття. Через небезпеку й паніку, яку могло б викликати це відкриття, обидва старійшини негайно припиняють розмову й тримають справу в таємниці серед старших членів Кола Кенарія.",al={"чому гамуул турбується","чому матренгіл ховає скалку"}},{q="Куди треба доставити скалку?",a="Шукачам пригод Орди велять доставити її Архідруїдові Гамуулу Рунтотему на Узвишшя Старійшин у Тандер Блафі, а мандрівники Альянсу несуть її Матренґілу Берволкеру з Кола Кенарія в Дарнасусі.",al={"кому нести скалку","здати скалку жаху"}}},fp="15,344,18.487.0,12.467.1,28.253.0,32.245.0,43.337.1,42.208.0"}
P.entries["item:nightsaber-fang"] = {n="Ікло Нічного Шаблезуба",s="Гострий зуб, здобутий із хижих нічних шаблезубів, що блукають диким віттям Тельдрассила. Хоч це звичний трофей полювання, ці ікла шукають і як сирі складники тутешні лісові мешканці із сумнівними намірами.",h="Гострий зуб, здобутий із хижих нічних шаблезубів, що блукають диким віттям Тельдрассила.",kw={"ікло нічного шаблезуба","нічний шаблезуб","зенн фаулгуф","сатир","доланаар","тельдрассил","трофей"},ang={["class:Hunter"]="Здолати нічного шаблезуба й узяти його ікло означає довести основне володіння дикою природою, та постачати частини звірів споганеним лісовим духам — спотворення самого духу полювання.",["race:NightElf"]="Нічні шаблезуби — улюблені супутники й символи богині Елуни, тож полювати на цих священних хижаків задля віроломного сатира — глибока ганьба."},sec={{t="Трофей полювання",b="Нічні шаблезуби — одні з найсмертоносніших природних хижаків північного Калімдору; нічні ельфи шанують їх за спритність, лютість і глибокий духовний зв'язок з Елуною. По всьому великому віттю Тельдрассила ці котячі звірі полюють у тінях під шатром. Здолавши одного, мисливець здобуває гострі ікла — незаперечний доказ своєї вправності, хоч деякі непевні постаті в лісі шукають їх для не надто шляхетних обрядових цілей."},{t="Складник для сатира",b="За поселенням Доланаар чигає Зенн Фаулгуф — облудний сатир, що полює на завзятих і недосвідчених мандрівників. Запевняючи, що потребує лісових складників, Зенн підмовляє молодих шукачів пригод здобувати ікла нічних шаблезубів разом із перами стригід і павутинним шовком. Віддати такі хижацькі складники означає прямо допомогти шахраєві, який відверто глузує з наївного героя, щойно дістане своє."}},faq={{q="Звідки беруться Ікла Нічного Шаблезуба?",a="Ікла Нічного Шаблезуба забирають у хижих нічних шаблезубів, що никають нетрями Тельдрассила, особливо в лісі довкола Доланаара.",al={"де взяти ікла нічного шаблезуба","хто дропає ікла нічного шаблезуба","джерело іклів шаблезуба"}},{q="Кому на Тельдрассилі потрібні Ікла Нічного Шаблезуба?",a="Їх просить Зенн Фаулгуф — сатир, що тиняється трохи осторонь головного шляху під Доланааром, у межах доручення, яке він дає мандрівним шукачам пригод.",al={"кому потрібні ікла нічного шаблезуба","здати ікла нічного шаблезуба","хто купує ікла шаблезуба"}},{q="Навіщо Зенну Фаулгуфу Ікла Нічного Шаблезуба?",a="Зенн запевняє, що звірині реагенти потрібні йому для його лісових справ, але тримає їхню суть у таємниці й тішиться, коли ошукує довірливих мандрівників і змушує їх служити собі.",al={"навіщо зенну ікла","реагент зенна фаулгуфа","прохання зенна"}},{q="Які ще реагенти Зенн просить разом з іклами?",a="Окрім двох іклів нічного шаблезуба, Зенн вимагає двоє пір'їн неяситі й два клапті павутини павуків Вебвуда.",al={"що ще потрібно зенну","предмети прохання зенна","інші реагенти для зенна"}}},fp="15,233,18.458.0,17.384.1,36.153.0,41.140.0,45.187.0,58.111.0"}
P.entries["item:nissa-s-remains"] = {n="Останки Нісси",s="Останки Нісси — повернуті земні рештки Нісси Аґаманд, шляхтянки колись заможної династії Аґамандів на півночі Галявин Тірісфалю. Убита й піднята безтямною служницею Погибелі під час Третьої війни, вона разом із родиною тепер стала здобиччю колишніх робітників, що прагнуть помсти.",h="Останки Нісси — повернуті земні рештки Нісси Аґаманд, шляхтянки колись заможної династії Аґамандів на півночі...",kw={"останки нісси","нісса аґаманд","аґаманди","коулмен фартінґ","помста","брілл"},ang={["faction:Horde"]="Знищення піднятих Аґамандів і очищення їхніх млинів убезпечує північ Галявин Тірісфалю від недобитків Погибелі, що загрожують Бріллу й Андерсіті.",["race:Undead"]="Для Відступників відвоювати Тірісфаль означає вичистити і колишніх гнобителів з Погибелі, і заможних аристократів, що через дурну гордість прирекли простих робітників на нежиття."},sec={{t="Спадщина гордині",b="До Третьої війни родина Аґамандів була найзаможнішою і найвпливовішою династією Галявин Тірісфалю: вона тримала процвітаючі млини на північних пагорбах. Коли Чума Нежиті підповзла до Лордерону, патріархи родини вперто відмовилися евакуюватися. Натомість вони укріпили маєтки й переконали своїх слуг і робітників стояти до кінця. Та зухвалість коштувала життя всім. Аґаманди впали перед Погибеллю й повстали не з гордою незалежністю, а шкутильгаючими безтямними рабами, прикутими до волі, що її диктує Король-Ліч."},{t="Гірка відплата",b="У містечку Брілл уцілілі, що згодом вирвалися на волю під проводом королеви Сильвани Віндраннер, не забули фатальної гордості цієї родини. Коулмен Фартінґ, колишній робітник на млинах Аґамандів, плекає гірку образу на колишніх господарів за те, що заманили своїх робітників у пащу нежиття. Він доручає шукачам пригод упокоїти піднятих Аґамандів і повернути їхні тілесні рештки — зокрема й Ніссині. Для Фартінґа й інших серед Відступників спалити чи знищити ці реліквії означає похмуре відчуття остаточного завершення й злостивої помсти."}},faq={{q="Хто така Нісса Аґаманд?",a="Нісса — з родини Аґаманд, лордеронських вельмож, яким належали розлогі Млини Аґаманда в Галявинах Тірісфалю. Коли Погибель пронеслася Лордероном, вона загинула разом із рідними й повстала нежиттю під владою Короля-Ліча.",al={"хто така нісса","лор нісси","нісса аґаманд"}},{q="Навіщо Коулменові Фартінґу останки Нісси?",a="За життя Коулмен Фартінґ працював на млинах Аґамандів. Він люто ненавидить цю родину, бо через її пиху й відмову тікати вірні робітники лишилися й загинули. Збираючи їхні останки, він мститься колишнім господарям.",al={"чому коулмен хоче останки","чому вбивати аґаманд","мотив коулмена фартінґа"}},{q="Де збирають ці останки?",a="Нісса Аґаманд блукає зруйнованими Млинами Аґаманда на півночі Галявин Тірісфалю, серед напіврозвалених хат, разом зі своїми піднятими родичами й безвольними рабами Погибелі.",al={"де знайти ніссу","місце нісси аґаманд"}},{q="Чи зберегла Нісса свою волю, як Відступники?",a="Ні. На відміну від Відступників, які вирвалися з-під влади Короля-Ліча, Нісса та її родина лишилися рабами Погибелі — безвольною нежиттю без розуму й свободи, які мають мешканці Андерсіті.",al={"чи нісса відступниця","чи мала нісса вільну волю","чи нісса погибель"}}},fp="15,298,17.567.0,18.540.0,22.260.0,47.246.0,33.194.0,49.197.0"}
P.entries["item:nitroglycerin"] = {n="Нітрогліцерин",s="Нітрогліцерин — нестійка хімічна речовина, яку носять при собі дворфійські вояки й офіцери гарнізону Бель Модану на півдні Пусток. Дворфи використовують її як промислову вибухівку для своїх розкопок, хоча її можна обернути й проти них самих.",h="Нітрогліцерин — нестійка хімічна речовина, яку носять при собі дворфійські вояки й офіцери гарнізону Бель...",kw={"нітрогліцерин","бель модан","ґанн стоунспайр","дворфи","вибухівка","пустки"},ang={["profession:Engineering"]="Інженер одразу впізнає в нітрогліцерині класичну вибухову основу: вбравшись у пористу деревну масу разом з окисником на зразок нітрату натрію, вона стає стійкою і придатною до підриву.",["race:Tauren"]="Нестійка хімія, якою дворфи шматують землю довкола Бель Модану, — гірке нагадування про промислове спустошення, що спіткало плем'я Стоунспайр."},sec={{t="Промислові підриви",b="Дворфи з Бел'дуна вгризалися в родові землі тауренів Стоунспайр важкими механічними бурами й небезпечною хімією. Щоб пробивати глибокі шурфи й розносити пагорби, дворфи на розкопках Бель Модану та в його укріпленій фортеці тримають запаси чистого нітрогліцерину під рукою. Пляшечки з нестійкою рідиною носять при собі і рядові вояки, і офіцери, як-от Лорд Сайрік Блекфордж, — щоб руйнівні розкопки не спинялися."},{t="Їхньою ж зброєю",b="Після смерті Шукача Хазґорма вигнаний зі своїх земель тауренський воїн Ґанн Стоунспайр вирішив дощенту зруйнувати дворфійську фортецю, що дедалі глибше вгризалася в його край. Вивчивши дворфійські інженерні креслення, Ґанн збагнув: якщо змішати відібраний нітрогліцерин із деревною масою та нітратом натрію, вийде заряд, достатньо потужний, щоб ударити у відповідь по укріпленому гарнізону Бель Модану."}},faq={{q="Звідки береться нітрогліцерин?",a="Нітрогліцерин носять дворфські загони в Бель Модані на півдні Пусток — вояки, стрільці й офіцери Бел'дуна, а також Лорд Сайрік Блекфордж у фортеці.",al={"де знайти нітрогліцерин","хто дропає нітрогліцерин","джерело нітрогліцерину"}},{q="Для чого потрібен нітрогліцерин?",a="Ґанн Стоунспайр разом із деревною масою й натрієвою селітрою робить із нього потужний вибуховий заряд, обертаючи підривне ремесло дворфів проти їхнього ж укріплення в Бель Модані.",al={"для чого нітрогліцерин","призначення нітрогліцерину","інгредієнти помсти ґанна"}},{q="Навіщо дворфи взагалі його носили?",a="Шукачі й гарнізон Бель Модану покладаються на вибухівку, парові машини й нестійкі хімікати, щоб розривати землю й вести археологічні розкопки.",al={"чому дворфи його носили","вибухівка бейл модана"}},{q="Хто такий Ґанн Стоунспайр?",a="Ґанн Стоунспайр — таурен-воїн у вигнанні, що втратив землі предків, коли дворфи облаштували розкопки й фортецю в Бель Модані й промисловим нищенням прогнали його плем'я.",al={"хто такий ґанн","ґанн стоунспайр"}}},fp="13,256,21.476.0,29.384.1,35.187.0,35.202.0,52.174.0,23.199.0"}
P.entries["item:nondescript-letter"] = {n="Непримітний Лист",s="Непримітний Лист — запечатане послання без позначок, довірене щойно пробудженим Відступникам, що покидають Похоронний Подзвін. Вручений Келвіном Монтеґ'ю під виглядом доручення, він скеровує носія дорогою до Корчмарки Рене в Таверні «Шибеничний Кінець» у Бріллі.",h="Непримітний Лист — запечатане послання без позначок, довірене щойно пробудженим Відступникам, що покидають...",kw={"непримітний лист","келвін монтеґ'ю","корчмарка рене","таверна шибеничний кінець","похоронний подзвін","брілл"},ang={["class:Rogue"]="Слизька поведінка Келвіна Монтеґ'ю й різка зміна настрою Рене мають усі ознаки дрібної розбійницької інтриги й шифрованого спілкування злочинного світу.",["race:Undead"]="Для щойно піднятих Відступників цей лист — одна з перших спонук покинути межі Похоронного Подзвону й дослідити більші поселення Галявин Тірісфалю."},sec={{t="Доручення кур'єра",b="До щойно піднятих Відступників, що хочуть вирушити за межі Похоронного Подзвону, підходить Келвін Монтеґ'ю — слизький розбійник, що тиняється біля околиці села. Жаліючись на втому від боїв із безтямними зомбі й павуками, Келвін просить мандрівників віднести простий конверт без позначок східною дорогою до Брілла. Недбало адресований корчмарці на ім'я Рене, лист — лише привід виштовхнути мандрівників із долини в бік Таверни «Шибеничний Кінець», хоча обіцянки Келвіна про щедру винагороду від самого початку звучать порожньо."},{t="Підозріле листування",b="Коли лист доставляють до Брілла, Корчмарка Рене спершу розігрує перебільшено веселу виставу, мовляв, це напевно добрі звістки від її святої матінки з Похоронного Подзвону. Зрозумівши, що кур'єр бачить наскрізь її незграбну гру, вона миттю міняє люб'язність на гостре роздратування. Вона вихоплює лист, відмовляється сказати, хто його насправді надіслав і що в ньому, і грубо проганяє носія — хіба що той збирається заплатити за кімнату."}},faq={{q="Що таке Непримітний Лист?",a="Це звичайнісінький, нічим не оздоблений конверт, який Келвін Монтеґ'ю в Похоронному Подзвоні дає новим шукачам пригод-Відступникам, щоб доставити Корчмарці Рене в Брілл.",al={"непримітний лист","що це за лист","лист келвіна"}},{q="Хто надсилає лист і хто його отримує?",a="Келвін Монтеґ'ю, розбійник із Похоронного Подзвону, вручає лист кур'єрам. Його адресовано Корчмарці Рене в Таверні «Шибеничний Кінець» у Бріллі.",al={"хто надсилає лист","хто отримує лист","відправник листа"}},{q="Що насправді написано в листі?",a="Зміст листа гравцеві не відкривається. Коли ви питаєте, Корчмарка Рене скидає свою привітну личину й сердито каже, що звідки лист і що в ньому — не ваша справа.",al={"що написано в листі","зміст листа","чи можна прочитати лист"}},{q="Навіщо Келвін Монтеґ'ю хоче, щоб лист доставили?",a="Келвін запевняє, що надто зайнятий боротьбою з місцевими зомбі й павуками, щоб самому виконати доручення. Насправді доставка виводить мандрівників із Похоронного Подзвону й знайомить їх із вигодами та місцями відпочинку в Бріллі.",al={"навіщо надсилати лист","мотив келвіна","чому брилл"}}},fp="18,263,18.530.0,25.447.1,31.163.0,42.151.0,34.214.0,43.230.0"}
P.entries["item:nori-s-mug"] = {n="Кухоль Норі",s="Кухоль Норі — особистий посуд Норі Прайддріфта, в якому він розносить обпікаючий ранковий узвар крижаними заметами Дун Мороґу. Доставивши теплий напій, що проганяє пронизливий гірський холод, подорожні мусять повернути порожній кухоль ощадливому власникові.",h="Кухоль Норі — особистий посуд Норі Прайддріфта, в якому він розносить обпікаючий ранковий узвар крижаними...",kw={"кухоль норі","норі прайддріфт","ранковий узвар","дурнан фуркаттер","анвілмар","посуд","доставка"},ang={["race:Dwarf"]="Для дворфів, які зносять бурі Дун Мороґу, поділитися теплим напоєм — природна річ, але загубити добрий корчемний посуд у заметі — непрощенне марнотратство."},sec={{t="Повернення кур'єра",b="На морозних гірських перевалах Дун Мороґу паруючий кухоль ранкового узвару — одна з небагатьох утіх, здатних пробити лютий холод. Норі Прайддріфт довіряє свій кухоль подорожнім, які несуть свіжу, паруючу порцію Дурнану Фуркаттеру до Анвілмара. Коли його спорожнять, міцний посуд мусить вирушити назад. Як зауважує Норі, кухлі на деревах не ростуть, і пильнувати витривалий дворфійський посуд — справа першорядна там, де гостинність зустрічається із засніженою пусткою."}},faq={{q="Для чого потрібен Кухоль Норі?",a="У ньому несуть гарячий, як окріп, ранковий узвар Дурнанові Фуркаттеру в Анвілмар. Коли Дурнан нап'ється й зігріється, порожній кухоль треба віднести назад Норі Прайддріфту.",al={"призначення кухля норі","що було в кухлі","чашка норі"}},{q="Кому належить цей кухоль?",a="Кухоль належить Норі Прайддріфту — дворфові з Дун Мороґа, що цінує свої речі й вимагає, щоб кур'єри повертали його посуд, а не розкидали його по снігу.",al={"хто така норі","власниця кухля","чий кухоль"}},{q="Чому Норі вимагає повернути кухоль?",a="Добрий глиняний посуд і міцні кухлі — практичні речі в суворому гірському кліматі. Як прямо каже Норі, кухлі на деревах не ростуть, тож для нього це і справа честі, і проста практичність — щоб кожен позичений кухоль повертався до нього.",al={"чому повернути кухоль","чому норі хоче кухоль назад","кухлі не ростуть на деревах"}},{q="Що пили з кухля?",a="У ньому був гарячий ранковий узвар — ситний теплий напій, який дворфи Дун Мороґа люблять за те, що він проганяє пекучий холод і зігріває душу.",al={"що було в чашці","що таке ранковий узвар","ранковий узвар напій"}}},fp="10,276,18.476.0,28.196.0,18.189.0,45.242.0,28.136.0"}
P.entries["item:notched-rib"] = {n="Зазубрене Ребро",s="Зазубрене Ребро — кістяний трофей, здобутий із безтямної нежиті, що блукає Галявинами Тірісфалю. Вартовий Смерті Діллінджер у Бріллі збирає ці пошрамовані рештки як доказ зусиль зламати опору Погибелі на Млинах Аґаманда.",h="Зазубрене Ребро — кістяний трофей, здобутий із безтямної нежиті, що блукає Галявинами Тірісфалю.",kw={"зазубрене ребро","скелети","вартовий смерті діллінджер","млини аґаманда","погибель","брілл"},ang={["race:Undead"]="Для Відступників збирання цих потрощених кісток — частина безнастанної війни за виживання проти безтямних прислужників Короля-Ліча, які затягли б їх назад у рабство."},sec={{t="Похмурий доказ бою",b="Сили Погибелі, що збираються на північних полях Галявин Тірісфалю, складаються з оживлених скелетів у зруйнованих обладунках. Серед них солдати Тріснутого Черепа й солдати Гримучих Кісток кидаються на кожну живу чи вільну істоту, яка трапиться їм на шляху. Клинки, що розтинають їхні крихкі кістяки, лишають на кістках вибоїни й зарубки. Щоб переконатися, що розвідники й добровольці Відступників справді проріджують цих безтямних зайд, а не просто спостерігають за ними, Вартові Смерті вимагають речових доказів. Зазубрене, позначене боєм ребро — незаперечний доказ того, що ще одного раба, якого послав Король-Ліч, розтрощено."},{t="Убезпечення млинів",b="Млини Аґаманда — ключова стратегічна позиція на північний захід від Брілла. Якби Погибель міцно закріпилася серед зруйнованих хуторів і вітряків, вона мала б прямий плацдарм для ударів углиб Тірісфалю. Вартовий Смерті Діллінджер наглядає за дорогами, що ведуть на північ, і відряджає звитяжців розчавити скелетні загони, перш ніж ті згуртуються. Купи зазубрених ребер, принесені до Брілла, доводять, що лінії Відступників тримаються й повільно перемелюють авангард Погибелі — кістка за кісткою."}},faq={{q="Що таке Зазубрене Ребро?",a="Це пошрамована кістка з оживлених вояків Погибелі, що захопили північ Галявин Тірісфалю. Її приносять Вартовому Смерті Діллінджеру як речове підтвердження знищених ворогів.",al={"зазубрене ребро","що таке зазубрене ребро","предмет зазубрене ребро"}},{q="Звідки беруться Зазубрені Ребра?",a="Їх забирають у вояків Тріснутого Черепа й вояків Гримучих Кісток, що патрулюють землі Млинів Аґаманда на північний захід від Брілла.",al={"де знайти зазубрене ребро","хто дропає зазубрені ребра","джерело зазубреного ребра"}},{q="Кому потрібні ці кістки?",a="Їх збирає Вартовий Смерті Діллінджер, що стоїть при дорозі під самим Бріллом, разом із Почорнілими Черепами — щоб пересвідчитися, що наступ Погибелі відбито.",al={"хто бере зазубрені ребра","здати зазубрене ребро","кому потрібні ребра"}},{q="Чому Погибель збирається на Млинах Аґаманда?",a="Безвольна нежить намагається облаштувати на млинах плацдарм. Звідти сили Погибелі легко могли б завдавати ударів по всіх Галявинах Тірісфалю й загрожувати поселенням Відступників.",al={"погибель у млинах аґаманда","чому скелети в млинах","загроза погибелі у млинах"}}},fp="11,236,20.629.0,18.542.0,22.191.0,32.141.0,22.157.0,46.196.0"}
P.entries["item:nugget-slug"] = {n="Металева Шайба",s="Металеві шайби — спеціальні механічні кріплення калібру 17,5, що застосовуються в промисловій інженерії. Венчурна Компанія тримає їхні запаси у відрах з інструментами на Багнистому Болоті, а майстри-механіки полюють на них, щоб лагодити свої норовливі механізми.",h="Металеві шайби — спеціальні механічні кріплення калібру 17,5, що застосовуються в промисловій інженерії.",kw={"металева шайба","самофланж","венікі болтбакет","венчурна компанія","багниста драговина","інженерія"},ang={["profession:Engineering"]="Кожен інженер знає: поєднати фірмові шайби калібру сімнадцять із половиною з нестабільним гоблінським самофланжем — певний спосіб швидко й гучно розібрати все на друзки."},sec={{t="Промислові кріплення Багнистого Болота",b="Ці шайби — надміцні металеві кріплення для важких промислових конструкцій. Їх виготовляють саме калібру 17,5, і без них не обходиться жодна важка техніка на видобувних ділянках Венчурної Компанії. Як звичайний крам вони нічого не варті, зате незамінні для майстрів, що возяться з переробленим гоблінським обладнанням."},{t="Лагодимо самофланж",b="Венікі Болтбакет потребує чималого запасу металевих шайб, щоб перебрати нестабільний самофланж, знайдений у Пустках. Венчурна Компанія раз у раз лишає відра з інструментами по всіх своїх бурових ділянках на Багнистому Болоті, тож збирачам брухту там є чим поживитися — навіть якщо ремонт Венікі зрештою закінчиться раптовим вибухом."}},faq={{q="Що таке металева шайба?",a="Металева шайба — особливе металеве кріплення калібру 17,5, яке використовують у важких машинах. Такі шайби — частина конструкції складних промислових механізмів, як-от нафтових бурів і самофланжів.",al={"що таке металеві шайби","лор металевої шайби","шайба кріплення"}},{q="Де знайти металеві шайби?",a="Вони зберігаються у відрах з інструментами, розкиданих по Мулистому Багну — буровому табору Венчурної Компанії на північному сході Пусток.",al={"де знайти металеві шайби","місце металевих шайб","відра з інструментами мулистого болота"}},{q="Навіщо вони Венікі Болтбакет?",a="Венікі Болтбакет хоче поколупатися в здобутому самофланжі й полагодити його. У неї самої скінчилися кріплення калібру сімнадцять із половиною, тож вона посилає шукачів пригод забрати їх у сусідньому таборі Венчурної Компанії.",al={"кому потрібні металеві шайби","чому венікі хоче шайби","ремонт самофланжа"}},{q="Чи лагодять шайби самофланж?",a="Не вдало. Щойно Венікі вставляє в механізм здобуті шайби й береться до роботи, самофланж раптом вибухає просто перед нею.",al={"чи працює машина","вибух самофланжа","результат ремонту венікі"}}},fp="11,232,38.358.0,30.376.1,22.206.0,29.133.0,38.215.0,48.156.1"}
P.entries["item:ogre-s-monocle"] = {n="Огрський Монокль",s="Огрський Монокль — величезне скельце, яке носить Ззарк'Вул, огр з Огрського Кургану Вул'Ґол на півдні Сутінколісся. Його велетенська лінза має саме ті розміри, яких потребує Вікторі Призм'Антрас у Даркширі, щоб зібрати хитромудрий телескоп для споглядання зірок.",h="Огрський Монокль — величезне скельце, яке носить Ззарк'Вул, огр з Огрського Кургану Вул'Ґол на півдні...",kw={"огрський монокль","ззарк'вул","огрський курган вул'ґол","вікторі призм'антрас","телескоп","огри"},ang={["faction:Alliance"]="Забравши лінзу в огрів Вул'Ґолу, ви позбавляєте південні ліси небезпечного громила й допомагаєте змученим мешканцям Даркшира знайти розраду в зорях.",["profession:Engineering"]="Креслення Коґа — типовий гномський розмах: якщо в польових умовах немає точно шліфованих лінз, згодяться й нестандартні деталі на кшталт велетенських окулярів."},sec={{t="Дивовижна лінза",b="Огри рідко славляться витонченою вченістю, та Ззарк'Вул якимсь дивом розжився величезним моноклем, якраз до свого велетенського зросту. Коли мешканець Даркшира Вікторі Призм'Антрас узявся будувати прилад для споглядання зірок за кресленнями гномського інженера Коґа, він переконався, що звичайні лінзи замалі. Монокль Ззарк'Вула виявився єдиним шматком полірованого скла в окрузі з потрібною кривиною й розміром, щоб сфокусувати світло в готовому приладі."},{t="Вирвати лінзу з Вул'Ґолу",b="Щоб здобути монокль, доведеться вирушити до Огрського Кургану Вул'Ґол у темному південному Сутінколіссі. Ззарк'Вул живе серед своїх брутальних родичів і зовсім не прагне добровільно розлучитися з примітною прикрасою. Забрати лінзу можна, лише перемігши громила на його ж території, — а тоді скло повертається до Даркшира, і Вікторі нарешті може звернути погляд до нічного неба."}},faq={{q="Хто носить Огрський Монокль?",a="Монокль має Ззарк'Вул — відомий огр, що блукає Огрським Курганом Вул'Ґол на півдні Сутінколісся.",al={"хто дропає монокль","у кого огрський монокль","предмет зз'арк'вула"}},{q="Навіщо Вікторі Призм'Антрасу окуляр огра?",a="Вікторі будує телескоп за кресленнями гнома Коґа. Приладу потрібна незвично велика лінза, і величезний монокль Ззарк'Вула — єдине скло в Сутінколіссі, що пасує за розмірами.",al={"навіщо монокль","для чого монокль","лінза телескопа"}},{q="Звідки в огра велетенський монокль?",a="Джерело не пояснює, як Ззарк'Вул здобув монокль. Відомо лише, що в нього є монокль, достатньо великий для телескопа Вікторі.",al={"чому в огра монокль","окуляри огра"}},{q="Де Огрський Курган Вул'Ґол?",a="Огрський Курган Вул'Ґол лежить серед південних пагорбів Сутінколісся, на південь від головного шляху між Даркширом і західним кордоном.",al={"де вул'ґол","огрський курган сутінколісся"}}},fp="14,266,14.496.0,22.382.0,31.114.0,54.233.0,36.143.0,40.137.0"}
P.entries["item:okra"] = {n="Окра",s="Окра — городня культура, яку вирощують на оброблених ділянках Вестфолу. Місцеві господарі дуже її цінують: вона чудово загущує ситні рагу, які в цьому краї варять із того, що є під рукою.",h="Окра — городня культура, яку вирощують на оброблених ділянках Вестфолу.",kw={"окра","вестфоллське рагу","салма салдін","ферма салдина","кулінарія","вестфол"},ang={["faction:Alliance"]="Поки вельможі Стормвінда ласують привізним м'ясом, прикордонні господарі Альянсу виживають, вирощуючи серед руїн Вестфолу витривалі культури на кшталт окри.",["profession:Cooking"]="Кожен мандрівний кухар знає: для доброго рагу мало сирого м'яса — окра дає потрібну крохмалисту густину, щоб жорстка дичина стала справжньою гарячою стравою."},sec={{t="Основа Ферми Салдина",b="Хоч більша частина Вестфолу лежить облогом під загрозою розбійників Дефіасу й нападів здичавілих жнивних големів, уперті фермери на кшталт Салдінів досі примудряються виростити із землі поживні овочі. Окра стелиться низько й зеленіє в зораній землі довкола Ферми Салдина. Попри суворі умови сільської глушини, урожай не здається й дає місцевим господарям ситну їжу, коли торгівля й постачання зі Стормвінда цілком пересихають."},{t="Вестфоллське Рагу",b="Окра найбільше відома як незамінна основа славетного Вестфоллського Рагу Салми Салдін. Разом із м'ясом, яке вдається вполювати на курних рівнинах, — м'ясом стерв'ятників, рилами кривавоіклих і очима мурлоків з узбережжя — нарізані стручки розварюються й перетворюють рідку юшку на ситну, відновлювальну страву. Для поселенців, що з останніх сил тримаються своїх господарств, свіжі стручки окри перетворюють убогу дику здобич на гарячу ситну вечерю."}},faq={{q="Де у Вестфолі росте окра?",a="Окра росте на оброблених грядках Ферми Салдина при центральній дорозі Вестфолу. Мандрівники можуть побачити ці помітні зелені рослини, що буяють у борознах біля садиби Фермера Салдіна.",al={"де у вестфоллі росте окра","місце окри","де росте окра"}},{q="Для чого потрібна окра?",a="Окру збирають для Салми Салдін на Фермі Салдина, щоб вона зварила своє фірмове Вестфоллське Рагу. Природний крохмаль окри загущує юшку й об'єднує грубі складники — м'ясо грифа, рила кабанів і очі мурлоків — у ситну страву.",al={"використання окри","для чого окра","навіщо мені окра"}},{q="Чому окра важлива для Салдінів?",a="Торгові шляхи перерізано, королівство майже не допомагає, тож хуторяни мусять покладатися лише на те, що самі виростять і вполюють. Окра — одна з небагатьох культур, що ще ростуть на Фермі Салдина, і вона годує родину й перехожих мандрівників.",al={"чому окра важлива салдінам","окра салдінів"}}},fp="4,198,26.460.0,13.448.0,33.206.0,22.223.0,38.254.0"}
P.entries["item:oslow-s-toolbox"] = {n="Ящик з Інструментами Ослоу",s="Ящик з Інструментами Ослоу містить важливі будівельні інструменти, потрібні Бригадирові Ослоу в Лейкширі. Дорогою з Ґолдширу їх везли човном через Озеро Незрушне, але орківська катапульта пустила човен на дно.",h="Ящик з Інструментами Ослоу містить важливі будівельні інструменти, потрібні Бригадирові Ослоу в Лейкширі.",kw={"ящик з інструментами ослоу","бригадир ослоу","озеро незрушне","ґолдшир","лейкшир","мурлоки"},ang={["faction:Alliance"]="Лейкшир в облозі Блекрок майже відрізаний від світу, тож повернути інструменти Ослоу вкрай важливо, щоб міські укріплення трималися."},sec={{t="Фатальна переправа",b="Підтримувати укріплення й господарство Лейкширу — виснажлива праця, надто коли орки Блекрок облягають Гори Редріджу. Бригадир Ослоу замовив із Ґолдширу набір важливих будівельних інструментів. Головний міст до Лейкширу зруйнував ворог, тож вантаж довелося везти через Озеро Незрушне веслувальним човном. Переправа обірвалася раптово: сили Блекрок поцілили в човен із катапульти, і він разом із важкою скринею Ослоу пішов просто на дно, де кишать мурлоки."}},faq={{q="Чому Ящик з Інструментами Ослоу лежить на дні озера?",a="Інструменти везли з Ґолдшира. Міст у Лейкширі зруйнували під час облоги, тож вантаж довелося переправляти через Озеро Незрушне човном. Орки Блекрок обстріляли човен із катапульти, потопили його, і ящик пішов на дно.",al={"чому ящик на дні озера","як ослоу загубив інструменти","історія затонулого ящика"}},{q="Кому належить цей ящик?",a="Ящик належить Бригадирові Ослоу — наглядачеві будівництва й ремонтів у Лейкширі. Без належного знаряддя підтримувати укріплення міста під безперервними нападами майже неможливо.",al={"хто такий ослоу","власник ослоу","інструменти наглядача ослоу"}},{q="Де в Озері Незрушному затонули інструменти?",a="Інструменти лежать у затонулій скрині біля уламків розбитого човна в Озері Незрушному, серед підводних валунів на південь від помітного табору мурлоків на березі.",al={"місце ящика","де затонула скриня","де затонув човен"}},{q="Що стереже затонулу скриню?",a="Води довкола уламків кишать ворожими мурлоками й хижими водяними звірами, зокрема небезпечними озерними молотильниками, що никають глибшими місцями озера.",al={"небезпеки біля ящика","вороги озера незрушного","що охороняє інструменти ослоу"}}},fp="15,215,18.576.0,49.284.0,22.215.0,43.182.0,36.175.0"}
P.entries["item:osric-s-crate"] = {n="Ящик Осріка",s="Ящик Осріка — важкий пакунок зі щойно виготовленим обладунком, відправлений зі Стормвінда знеможеним захисникам Сентінел Гілл. Перевезений на грифоні повітряною мережею королівства, він дає життєво важливе спорядження, щоб Народне ополчення втримало Вестфол проти розбійницьких зграй.",h="Ящик Осріка — важкий пакунок зі щойно виготовленим обладунком, відправлений зі Стормвінда знеможеним...",kw={"ящик осріка","обладунок","сентінел гілл","народне ополчення","грифон","інтендант льюїс"},ang={["faction:Alliance"]="Кожна партія зброї та обладунку, що доходить до Сентінел Гілл, допомагає втримати західні кордони королівства від цілковитого падіння перед Братством Дефіас."},sec={{t="Припаси для фронту",b="Вестфол страждає від нападів Братства Дефіас і гнолів-мародерів, тоді як військо Стормвінда відсутнє. Тутешні захисники, об'єднані в Народне ополчення на Сентінел Гілл, не мають офіційної підтримки корони й мусять покладатися на розрізнені припаси. Ящик Осріка містить свіжу партію захисного обладунку, надісланого зі столиці Інтендантові Льюїсу, щоб роздати його просто бійцям-добровольцям ополчення на місці."},{t="Крилата кур'єрська мережа",b="Везти спорядження суходолом зі Стормвінда через Ліс Елвінн і далі за кордон Вестфолу повільно й небезпечно через бандитські засідки. Щоб обминути дороги, ящик довіряють шукачеві пригод, який летить із грифонника Дунґара Лонґдрінка в Торговому Кварталі Стормвінда до Тора на Сентінел Гілл. Ця швидка доставка показує, яку важливу роль відіграють грифони в постачанні прикордонних гарнізонів під час війни."}},faq={{q="Що в Ящику Осріка?",a="У ящику — захисні обладунки, виготовлені в Стормвінді. Інтендант Льюїс перевіряє доставку й одразу береться роздавати обладунки бійцям, що боронять Сентінел Гілл.",al={"що в ящику","вміст ящика осріка","вміст ящика осріка скрині"}},{q="Хто такий Осрік?",a="Осрік — зброяр зі Стормвінда, який приготував цю партію спорядження для Народного ополчення, що тримає Вестфол.",al={"хто такий осрік","хто надіслав ящик осріка"}},{q="Хто отримує ящик?",a="Вантаж адресовано Інтендантові Льюїсу — офіцерові, що відає припасами й спорядженням Народного ополчення на Сентінел Гілл у Вестфолі.",al={"куди ящик","кому віддати ящик осріка","одержувач ящика"}},{q="Чому ящик доставляють грифоном?",a="Бандити й розбійники роблять дороги між Стормвіндом, Лісом Елвінн і Вестфолом небезпечними. Переліт на грифоні від Дунґара Лонґдрінка в Стормвінді просто до Тора на Сентінел Гілл гарантує, що обладунки прибудуть швидко й неушкодженими.",al={"чому грифоном","навіщо грифони","політ ящика осріка"}}},fp="13,284,22.458.0,22.421.0,29.192.0,13.116.0,23.148.0,38.228.0"}
P.entries["item:package-of-empty-ooze-containers"] = {n="Набір Порожніх Контейнерів для Слизу",s="Цей набір — комплект спеціальних порожніх банок для зразків, який видає гном-дослідник Ларіс Ґірдавдл в Айронфорджі. Призначений для небезпечного збору зразків у заражених лісах Сквернолісся, він містить банки, що безпечно тримають зіпсований і проклятий слиз і не розчиняються.",h="Цей набір — комплект спеціальних порожніх банок для зразків, який видає гном-дослідник Ларіс Ґірдавдл в...",kw={"набір порожніх контейнерів для слизу","ларіс ґірдавдл","сквернолісся","слиз","королівське аптекарське товариство","ліга дослідників"},ang={["faction:Alliance"]="Збір цих зразків допомагає Альянсу не відставати від тривожних досліджень, які веде Королівське Аптекарське Товариство Відступників.",["race:Gnome"]="Ларіс Ґірдавдл бачить у дослідженні слизу важливу нагоду показати дворфам Айронфорджа, що прихистити гномів-біженців було варто."},sec={{t="Спорядження для польових досліджень",b="Цей набір із дюжини порожніх банок — частина для проклятих, частина для зіпсованих слизунів — Ларіс Ґірдавдл зібрав для відважних мандрівників, що вирушають до Сквернолісся. Сирі зразки слизу славляться їдкістю й схильністю перетравлювати звичайну поклажу, тож міцне запаяне скло конче потрібне, щоб перевезти їдкі рештки через континенти аж до верстата винахідника в Айронфорджі."},{t="Таємниця слизу",b="Зацікавлення Ґірдавдла слизом — аж ніяк не дивацьке хобі. Помітивши, що дослідники Відступників із Королівського Аптекарського Товариства постійно збирають цих химерних істот по всьому Азероту, він підозрює, що слизуни можуть приховувати глибокі таємниці про походження світу. Ґірдавдл припускає, що слиз може бути первісною виділиною, пов'язаною із самим створенням світу, і покладається на польових агентів із цим набором, щоб зібрати докази, які принесуть йому визнання в Лізі Дослідників."}},faq={{q="Що в наборі порожніх контейнерів для слизу?",a="У наборі — дванадцять банок для зразків: шість порожніх банок для проклятого слизу й шість — для оскверненого.",al={"вміст набору","що в наборі","банки для слизу всередині"}},{q="Хто дає цей набір?",a="Його вручає шукачам пригод Альянсу Ларіс Ґірдавдл — гном-учений і дослідник з Айронфорджа.",al={"хто дає банки","предмет завдання ларіса ґірдавдла","де взяти набір для слизу"}},{q="Де мають використати ці контейнери?",a="Їх призначено для зіпсованих нетрів Сквернолісся: там шукачі пригод мають здолати осквернені й прокляті слизи й зібрати зразки решток просто з переможених істот.",al={"де використати банки для слизу","яка зона для слизів","місце банок для слизу"}},{q="Навіщо Ларісові Ґірдавдлу ці зразки слизу?",a="Ларіс помітив, що Королівське Аптекарське Товариство Відступників збирає слизи по всьому світу, і хоче розкрити їхні таємниці. Він також має незвичну теорію, що слизи — первісні виділення, пов'язані зі створенням Азероту, і сподівається, що, довівши її, здобуде вагу в Лізі Дослідників.",al={"навіщо збирати слиз","дослідження ґірдавдла","чому ларіс хоче слиз"}}},fp="32,289,24.409.0,23.492.0,52.121.0,26.116.0,44.183.0,50.308.0"}
P.entries["item:painted-gnoll-armband"] = {n="Розмальована Нараменна Пов'язка Гнола",s="Розмальовані Нараменні Пов'язки Гнолів — грубі оздоби, які носять гноли Річколапи, що нишпорять околицями Лісу Елвінн. Гарнізон Вестбрук збирає ці позначені пов'язки як речовий доказ виконаних винагород за винищення зграй, що насуваються.",h="Розмальовані Нараменні Пов'язки Гнолів — грубі оздоби, які носять гноли Річколапи, що нишпорять околицями...",kw={"нараменна пов'язка","гноли","річколапи","гарнізон вестбрук","ліс елвінн","помічник рейнер"},ang={["faction:Alliance"]="Збирання цих пов'язок напряму допомагає Гарнізону Вестбрук і зміцнює західний рубіж Стормвінда, поки постійне військо міста відтягнуте в інші краї."},sec={{t="Знаки Річколапів",b="Зграя Річколапів позначає своїх воїнів і падложерів грубими пов'язками, розмальованими простими племінними візерунками. Ці розмальовані пов'язки збирають із гнолів Річколапів уздовж диких кордонів Лісу Елвінн. Для захисників Стормвінда ж вони втілюють дедалі більшу територіальну загрозу, що підступає до Озера Кам'яного Кургану й лісів на південь від Гарнізону Вестбрук."},{t="Винагорода для Гарнізону Вестбрук",b="Поки військо Стормвінда розтягнуте по всьому королівству, Гарнізон Вестбрук силкується втримати західний кордон від загроз, що насуваються. Помічник Рейнер призначив постійну винагороду за зграї-загарбниці, доручаючи шукачам пригод винищувати гінців і недоростків Річколапів. Розмальовані пов'язки слугують незаперечним доказом убивства, дозволяючи помічникам гарнізону рахувати винагороди й проріджувати гнолів, що підступають до сусідніх полів."}},faq={{q="Навіщо Гарнізону Вестбрук ці пов'язки?",a="Помічник Рейнер у Гарнізоні Вестбрук збирає пов'язки як доказ убитих гнолів-Річколапів. Вояки гарнізону самі не дають ради зграям, що підступають, тож Стормвінд платить нагороду кожному шукачеві пригод, який принесе ці знаки.",al={"навіщо пов'язки","хто хоче розмальовані пов'язки гнолів","нагорода помічника рейнера"}},{q="Які гноли носять ці розмальовані пов'язки?",a="Їх носять гноли-Річколапи в Лісі Елвінн — зокрема бігуни й недоростки Річколапів, що заполонили ліси на південь від Гарнізону Вестбрук і береги довкола Озера Кам'яного Кургану.",al={"де падають пов'язки","хто дропає розмальовану пов'язку гнола","які гноли мають пов'язки"}},{q="Як гноли-Річколапи опинилися в Лісі Елвінн?",a="Зграї Річколапів просунулися на схід уздовж меж Лісу Елвінн і отаборилися біля Озера Кам'яного Кургану й на лісових околицях. Користуючись тим, що війська королівства поріділи, вони полюють, мародерствують і загрожують довколишнім поселенням.",al={"чому гноли тут","вторгнення гнолів у ельвін","річколапи ельвін"}},{q="Що означає розмальовка на пов'язках?",a="Пов'язки позначають трофеї, зняті з гнолів Річколапів, і слугують доказом для Помічника Рейнера. Джерело не приписує розмальованим візерункам ні звань, ні якогось особливого значення.",al={"чому розмальовані","знаки на пов'язках гнолів"}}},fp="21,230,22.370.0,29.441.0,48.231.0,41.201.0,41.247.0,54.175.0"}
P.entries["item:panther-cage-key"] = {n="Ключ від Клітки Пантери",s="Ключ від Клітки Пантери — маленький металевий ключ, який зберігає Візло Берінґшайнер на Заставі Білого Рубежу. Він відмикає укріплену клітку, де серед уламків розграбованого каравану в Тисячі Голок сидить розлючений хижак.",h="Ключ від Клітки Пантери — маленький металевий ключ, який зберігає Візло Берінґшайнер на Заставі Білого Рубежу.",kw={"ключ від клітки пантери","візло берінґшайнер","пантера","застава білого рубежу","кентаври","гіперконденсаторна штукенція"},ang={["faction:Horde"]="Допомагаючи Візло, ви убезпечуєте дороги Тисячі Голок довкола Застави Білого Рубежу від непередбачуваних наслідків набігів кентаврів.",["profession:Engineering"]="Ключ відмикає клітку з непередбачуваним прототипом майстра — ще один доказ того, що дивакуваті винахідники ховають свої найтендітніші механізми в найнебезпечніших місцях, які лише можна уявити."},sec={{t="Небезпечний замок",b="Коли кентаври-розбійники напали на мандрівний караван на північ від Застави Білого Рубежу й розграбували його, гоблін-майстер Візло Берінґшайнер ледве врятував собі життя. Серед уламків возів і пограбованого вантажу грабіжники не торкнулися лише одного — міцної клітки з лютою рідкісною пантерою. На шиї хижака висів найцінніший винахід Візло — гіперконденсаторна штукенція. Кентаври не наважилися підійти до гаркітливого звіра й обходили клітку десятою дорогою, тож ключ Візло — єдиний спосіб відчинити дверцята й забрати пристрій."}},faq={{q="Хто дає Ключ від Клітки Пантери?",a="Ключ вручає шукачам пригод Візло Берінґшайнер — гоблін-майстер, що відпочиває на Заставі Білого Рубежу на північному заході Тисячі Голок.",al={"хто дає ключ пантери","де взяти ключ від клітки пантери","джерело ключа клітки пантери"}},{q="Що відмикає ключ?",a="Він відмикає залізну клітку серед поламаних возів розбитого каравану трохи на північ від Застави Білого Рубежу, — у ній сидить розлючена, небезпечна пантера.",al={"що відчиняє ключ пантери","місце клітки пантери","де клітка"}},{q="Чому кентаври не пограбували клітку?",a="Кентаври обнишпорили решту каравану, але пантера в клітці була така люта й грізна, що навіть грабіжники не наважилися до неї підступитися.",al={"чому кентаври лишили пантеру","кентаври бояться пантери"}},{q="Що в клітці, крім звіра?",a="На шиї пантери закріплено дорогоцінну Гіперконденсаторну Штукенцію Візла, тож кожен, хто хоче повернути винахід, мусить відімкнути клітку й зійтися з хижаком віч-на-віч.",al={"навіщо відчиняти клітку","що на пантері"}}},fp="16,219,17.550.0,34.133.0,25.147.0,37.165.0,42.176.0"}
P.entries["item:parker-s-lunch"] = {n="Обід Паркера",s="Обід Паркера — щойно приготована страва, яку Дарсі в Лейкширі загортає для Вартового Паркера, що вартує на дорозі. Цей клуночок відкриває буденне життя захисників Редріджу — їхню приязнь і скромні радощі.",h="Обід Паркера — щойно приготована страва, яку Дарсі в Лейкширі загортає для Вартового Паркера, що вартує на...",kw={"обід паркера","вартовий паркер","дарсі","корчма лейкшира","лейкшир","редрідж"},ang={["faction:Alliance"]="Столиця не поспішає з підкріпленням, тож Лейкшир тримається саме на взаємодопомозі містян і нечисленних вартових.",["profession:Cooking"]="Тепла домашня страва — часто єдина розрада, що тримає прикордонних вартових на ногах під час довгих чергувань серед ворожих звірів."},sec={{t="Обід у дорогу",b="Поки Гори Редріджу потерпають від нападів гнолів і орків Блекрок, дрібні буденні турботи нікуди не зникають. Дарсі, офіціантка в корчмі Лейкширу, збирає цю ситну їжу для Вартового Паркера, який патрулює відкриту дорогу на південь, до Сутінколісся. Гарнізон Редріджу розтягнутий до межі й відрізаний від допомоги Стормвінда, тож окремі вартові несуть довгі самотні чергування. Ця передача не лише годує вартового, а й дає початок довгому сором'язливому залицянню двох містян."}},faq={{q="Хто приготував Обід Паркера?",a="Обід приготувала Дарсі — служниця з корчми в Лейкширі. Вона хвилюється за Вартового Паркера, що несе небезпечний дозор, і просить мандрівних шукачів пригод безпечно доставити йому їжу.",al={"хто приготував обід паркера","хто дав обід паркера","обід дарсі редрідж"}},{q="Де знайти Вартового Паркера?",a="Вартовий Паркер патрулює головний ґрунтовий шлях, що веде з Лейкширу на південний захід до кордону із Сутінколіссям. Він ходить туди й назад, пильнуючи, чи не з'являться бродячі гноли.",al={"місце вартового паркера","де вартовий паркер","знайти вартового паркера"}},{q="Що робить Вартовий Паркер, отримавши обід?",a="Паркера глибоко зворушує турбота Дарсі. Вдячний за гарячу їжу на важкому дозорі, він невдовзі шукає, як віддячити їй, і просить допомогти надіслати їй свіжі нарциси від травниці.",al={"що паркер робить після обіду","дарсі та паркер","реакція паркера на обід"}},{q="Чому Дарсі не віднесе обід сама?",a="Дороги за Лейкширом кишать лютими гнолами Редріджу й загарбниками Блекрок. Вартовий Паркер має бойовий вишкіл і обладунки, щоб вижити в дозорі, а звичайним містянам, як Дарсі, вирушати туди самим небезпечно.",al={"чому дарсі не віднесе сама","чому доставляти обід"}}},fp="14,201,19.526.0,28.194.0,32.182.0,52.210.1,44.241.0"}
P.entries["item:partially-filled-vessel"] = {n="Частково Наповнена Посудина",s="Частково Наповнена Посудина — зачарований контейнер для перевезення благословенної води місячних колодязів Тельдрассилом. Віддана молодим посвяченим — нічним ельфам Тенароном Стормґріпом в Алдрассилі, вона несе воду, набрану в Тінедолі, до поселення Доланаар.",h="Частково Наповнена Посудина — зачарований контейнер для перевезення благословенної води місячних колодязів...",kw={"частково наповнена посудина","місячний колодязь","тенарон стормґріп","корітрас мунрейдж","тінедол","доланаар","алдрассил"},ang={["class:Druid"]="Перевезення освячених вод — неодмінний обов'язок у служінні безперервним зусиллям Кола Кенарія плекати й оглядати здоров'я Світового Дерева.",["race:NightElf"]="Нести цю посудину — обряд посвяти, що виводить молодих нічних ельфів із прихистку Тінедолу до ширшої відповідальності за турботу про Тельдрассил."},sec={{t="Священна доставка",b="У вітті Алдрассила посвячені калдореї набирають благословенну воду з усамітненого місячного колодязя Тінедолу. Тенарон Стормґріп переливає цей чистий зразок у спеціальну посудину, готуючи її до подорожі Світовим Деревом. Посудина лишається наповненою лише частково, бо її шлях тільки почався: згодом треба зібрати ще священних вод з усього Тельдрассила, щоб подбати про здоров'я острова."},{t="Далі до Доланаара",b="Щоб донести посудину, треба пройти на південь крізь браму долини й рушити бруківкою на захід до Доланаара. Ця подорож позначає вихід молодого шукача пригод із захищеної колиски Тінедолу в ширші нетрі Тельдрассила. Біля центрального місячного колодязя Доланаара посудину приймає Корітрас Мунрейдж, щоб спрямувати наступний етап обряду."}},faq={{q="Що в посудині?",a="У ній чиста вода з місячного колодязя — зі священного озерця в Тінедолі; налив її в посудину друїд Тенарон Стормґріп.",al={"що в посудині","вміст посудини","яка вода"}},{q="Чому вона наповнена лише частково?",a="Місячний колодязь Тінедолу дає лише першу пробу. Щоб доглядати Тельдрассил, треба набрати воду з кількох місячних колодязів по всьому дереву, перш ніж посудина наповниться.",al={"чому лише частково","чому не повна"}},{q="Кому віднести цю посудину?",a="Віднесіть посудину на південь із Тінедолу й ідіть брукованою дорогою на захід до Доланаара. Там вручіть її Корітрасові Мунрейджу, що доглядає місячний колодязь містечка.",al={"кому посудина","куди нести","здати посудину"}},{q="Навіщо переносять воду з місячних колодязів по Тельдрассилу?",a="Друїди й жриці стежать за Тельдрассилом і живлять його через води місячних колодязів. Переносячи воду між колодязями, вони підтримують їхнє благословення на неспокійних гілках молодого Світового Дерева.",al={"навіщо возити воду колодязів","призначення води","навіщо переносити воду"}}},fp="23,257,17.421.0,18.376.0,26.135.0,32.190.0,29.161.0,52.216.0"}
P.entries["item:pendant-of-shadow"] = {n="Амулет Тіні",s="Амулет Тіні — темний талісман, який носив чорнокнижник-ренегат Морґант на вершині Вежі Ілґалара в Горах Редріджу. Принесений магові Теокрітусу до Вежі Азори, він слугує незаперечним доказом того, що непокірного чаклуна знищено раніше, ніж його зловісні задуми встигли здійснитися.",h="Амулет Тіні — темний талісман, який носив чорнокнижник-ренегат Морґант на вершині Вежі Ілґалара в Горах...",kw={"амулет тіні","морґант","вежа ілґалара","теокрітус","вежа азори","коса елуни","чорнокнижник"},ang={["class:Mage"]="Повертаючи темний талісман на прохання Теокрітуса, ви нагадуєте, що маги й досі відповідають за приборкання безрозсудних чаклунів-ренегатів, які загрожують королівству.",["class:Warlock"]="Морґант — приклад того, як небезпечно привертати пильну увагу Вежі Азори, ганяючись за непередбачуваними забороненими артефактами на кшталт Коси Елуни."},sec={{t="Знак темного чорнокнижника",b="Амулет Тіні, який чорнокнижник-ренегат Морґант тримав у своєму лігві на Вежі Ілґалара, просякнутий темним чаклунством. Морґант прагнув розгадати таємниці Коси Елуни — давньої реліквії величезної й непередбачуваної сили. Побоюючись лиха, яке чорнокнижник міг накликати на Гори Редріджу й королівство Стормвінд, маг Теокрітус доручив шукачам пригод проникнути до Ілґалара, покласти край підступам Морґанта й вирвати з його рук талісман як доказ його загибелі."}},faq={{q="Де знайти Амулет Тіні?",a="Амулет носить чорнокнижник Морґант, що живе на самій верхівці Вежі Ілґалара на північному сході Гір Редріджу.",al={"де амулет тіні","місце амулета тіні","як отримати амулет тіні"}},{q="Кому потрібен Амулет Тіні?",a="Талісман треба принести чарівникові Теокрітусу, що живе у Вежі Азори на сході Лісу Елвінн.",al={"кому віддати амулет тіні","здати амулет тіні","амулет теокрітуса"}},{q="Навіщо Теокрітусу цей амулет?",a="Амулет потрібен Теокрітусу як відчутний доказ того, що Морґанта вбито, а його гонитві за небезпечною Косою Елуни покладено край.",al={"навіщо теокрітусу амулет","призначення амулета тіні"}},{q="Чим Морґант загрожував з амулетом?",a="Морґант полював на невловиму Косу Елуни. Теокрітус боявся, що, якщо темний чорнокнижник заволодіє артефактом, він вивільнить згубну силу над Редріджем і всім королівством довкола.",al={"що робив морґант","лор морґанта"}}},fp="17,310,23.500.0,38.135.0,32.122.0,38.160.0,47.209.0"}
P.entries["item:pendant-of-the-sea-lion"] = {n="Амулет Морського Лева",s="Амулет Морського Лева — священний друїдський талісман, що уособлює поєднання водяної спритності й витривалості. Його складають у Святилищі Ремулоса в Місячному Гаю, і він засвідчує, що учень готовий опанувати водяну форму.",h="Амулет Морського Лева — священний друїдський талісман, що уособлює поєднання водяної спритності й...",kw={"амулет морського лева","друїд","водяна форма","святилище ремулоса","місячний гай","дендрит старблейз","турак рунтотем"},ang={["class:Druid"]="Складання цього талісмана — важлива віха в навчанні друїда: воно відкриває змогу дихати під водою й плавати з невимушеною швидкістю у формі морського лева.",["race:Tauren"]="Для шу'гало, що йдуть шляхом Кола Кенарія, повернути амулет Тураку Рунтотему означає вшанувати і предків, і вчення Місячного Гаю."},sec={{t="Знак глибин",b="Щоб прийняти водяну форму морського лева, друїд мусить довести, що здатен подолати найбільші небезпеки води. Амулет створюють із двох окремих половин: одна втілює спритність, потрібну, щоб прослизнути повз водяних хижаків, а друга дарує витривалість, без якої не витримати довгого перебування під водою. Біля Святилища Ремулоса в Місячному Гаю обидві частини з'єднують в одне ціле."},{t="Доказ майстерності",b="Готовий амулет приносять старшим наставникам — Тураку Рунтотему на високих узвишшях Тандер Блафа чи Матренґілу Берволкеру в Дарнасусі. Талісман — незаперечний доказ того, що учень пройшов випробування Дендрита Старблейза, і старійшини відкривають йому таємницю перевтілення у водяну форму."}},faq={{q="Для чого Амулет Морського Лева?",a="Він доводить, що новачок-друїд пройшов випробування водяної спритності й витривалості й готовий навчитися перетворюватися на водяну подобу.",al={"що робить амулет морського лева","використання амулета морського лева","навіщо амулет морського лева"}},{q="Де складають амулет?",a="Дві половини — спритності й витривалості — треба з'єднати біля Святилища Ремулоса в священному прихистку Місячного Гаю.",al={"як скласти амулет морського лева","де з'єднати половинки амулета"}},{q="Кому в Тандер Блафі показати амулет?",a="Друїди-таурени вручають складений амулет Туракові Рунтотему на Узвишші Старійшин у Тандер Блафі, щоб завершити навчання.",al={"кому показати амулет у тандер блафі","амулет турака рунетотема","водна форма орди здати"}},{q="Чи можуть цей амулет здобути й нічні ельфи?",a="Так. Друїди нічних ельфів проходять те саме випробування в Місячному Гаю, а складений амулет несуть Матренґілу Берволкеру в Дарнасус.",al={"чи нічні ельфи можуть здобути амулет","амулет морського лева дарнасус"}}},fp="23,237,19.408.0,16.338.0,51.166.0,31.148.0,49.125.0,39.138.0"}
P.entries["item:perenolde-tiara"] = {n="Діадема Переноль",s="Діадема Переноль — оздоблена смарагдами реліквія занепалого королівського дому Альтераку, яку свого часу виготовили дворфійські майстри Айронфорджу. Загублена серед руйнування королівства, вона зрештою потрапила в жадібні руки огра, що блукав руїнами, а потім привернула увагу колекціонерів у Стормвінді.",h="Діадема Переноль — оздоблена смарагдами реліквія занепалого королівського дому Альтераку, яку свого часу...",kw={"діадема переноль","альтерак","ейден переноль","ґрел'борґ скнара","граф ремінгтон ріджвелл","смарагди"},ang={["faction:Alliance"]="Ця реліквія — гірке нагадування про дім Переноль, чия зрада під час Другої війни мало не знищила перший Альянс Лордерону.",["race:Dwarf"]="Діадема — свідчення славетного ювелірного мистецтва Айронфорджу, чиї майстри гранували й оправляли смарагди для людських правителів півночі."},sec={{t="Реліквія зруйнованого королівства",b="Перш ніж гірське королівство Альтерак ганебно впало й перетворилося на руїни під час Другої війни, ним правив рід Переноль. Серед його скарбів була ця витончена діадема, замовлена в майстрів-ювелірів Айронфорджу й оздоблена сяйливими смарагдами. Коли Альтерак занепав після зради короля Ейдена Переноля, коштовність зникла серед хаосу й руїн високих скель."},{t="Скарб скнари",b="Діадема не лишилася навіки похованою під снігом: її відкопав Ґрел'борґ Скнара — огр-маг, що нишпорить руїнами Альтераку в пошуках покинутих багатств. Звістка про вцілілу реліквію дійшла до Графа Ремінгтона Ріджвелла, багатого стормвіндського вельможі, що прагне здобувати славетні реліквії для свого родинного музею, — і почалися пошуки, щоб вирвати діадему з загребущих рук огра."}},faq={{q="Що таке Діадема Переноль?",a="Це родова коштовність, що колись належала королівській родині Перенольдів з Альтераку. Її виготовили майстри-ювеліри з дворфів Айронфорджа й оздобили добірними смарагдами, а згубилася вона під час падіння Альтераку.",al={"лор діадеми переноль","що це за діадема","діадема альтераку"}},{q="У кого тепер діадема?",a="Огр-маг, відомий як Ґрел'борґ Скнара, знайшов діадему серед засніжених руїн Альтераку. Він ревниво стереже її, нишпорячи зруйнованим королівством у пошуках інших утрачених скарбів.",al={"де діадема","хто дропає діадему","діадема грелборґ"}},{q="Навіщо діадема Графу Ремінгтону Ріджвеллу?",a="Граф Ремінгтон Ріджвелл збирає славетні історичні старожитності для свого родинного музею в Стормвінді. Справжня коронна коштовність занепалого людського королівства стане вражаючою окрасою його збірки.",al={"хто хоче діадему","чому реміґтон хоче її","мотив реміґтона ріджвелла"}},{q="Хто такі Перенольди?",a="Перенольди — правляча династія королівства Альтерак. Під час Другої війни король Ейден Переноль зрадив Альянс і перейшов на бік Орди орків, що призвело до занепаду й загибелі його королівства.",al={"родина переноль","дім переноль","правителі альтераку"}}},fp="15,311,27.406.0,17.401.0,28.211.0,28.183.0,43.223.0,24.209.0"}
P.entries["item:phial-of-scrying"] = {n="Флакон Віщування",s="Флакон Віщування — зачарована посудина, яку дає Ону, Древній знань, на Темному Узбережжі. Якщо ним скористатися, з'являється чаша віщування, що дає змогу спілкуватися на відстані крізь спотворені ліси.",h="Флакон Віщування — зачарована посудина, яку дає Ону, Древній знань, на Темному Узбережжі.",kw={"флакон віщування","ону","темне узбережжя","молот присмерку","чаша віщування","глефа володаря"},ang={["class:Druid"]="Друїди бачать у чашах віщування гармонійне поєднання природної води й магії спілкування, що дає змогу охоронцям лісу перешіптуватися через спотворені землі.",["race:NightElf"]="Для нічних ельфів Темного Узбережжя давні засоби віщування на кшталт віщувальної води необхідні, щоб пильно стерегти священні ліси, куди вдираються чужинські культи."},sec={{t="Лінза над Темним Узбережжям",b="Флакон Віщування, який довіряють розвідникам, що вирушають углиб Темного Узбережжя, містить містичну воду, що викликає на землі тимчасову чашу віщування. Цей засіб дозволяє ворожити на відстані, тож мандрівники, які заходять у небезпечні місця на кшталт Глефи Володаря, можуть спілкуватися з Ону безпосередньо, не повертаючись одразу до його гаю."},{t="Викриття культу",b="Ону дає флакон саме для того, щоб стежити за тривожною присутністю культистів Молота Присмерку. Встановивши віщувальний зв'язок там, де лежить давній полеглий володар, пронизаний велетенською глефою, розвідник підтверджує, що темні культисти збираються довкола давніх решток, шукаючи крихти забутої сили, що не згасла навіть у смерті."}},faq={{q="Що робить Флакон Віщування?",a="Відкоркований флакон створює на землі чарівну чашу для віщування, і шукач пригод у полі може зв'язатися з Древнім знань Ону й поговорити з ним на величезній відстані.",al={"використання флакона віщування","функція чаші віщування","для чого цей флакон"}},{q="Хто дає Флакон Віщування?",a="Прадавній деревник Ону довіряє флакон розвідникам на Темному Узбережжі, коли доручає їм розвідати Глефу Володаря на півдні.",al={"хто дає флакон віщування","де взяти флакон"}},{q="Що буде, якщо флакон загубиться чи вичерпається?",a="Якщо ви загубите флакон чи використаєте його, не завершивши завдання, Ону дасть інший, поки медитує на Темному Узбережжі.",al={"загублений флакон віщування","отримати ще флакон","замінити флакон"}},{q="Навіщо Ону віщує, зазираючи в Глефу Володаря?",a="Ону знає, що Глефа Володаря — місце, де поліг давній володар, і просить вас пошукати там культистів Молота Присмерку. Що вони замишляють, з'ясується, коли розслідування триватиме далі.",al={"чому віщувати глефу майстра","місія ону з глефою"}}},fp="16,194,23.356.0,19.359.1,34.181.0,34.136.0,47.121.0,44.174.0"}
P.entries["item:piece-of-krom-zar-s-banner"] = {n="Шматок Прапора Кром'зара",s="Подертий клапоть тканини зі штандарта Воєначальника Кром'зара, ватажка відплатного війська кентаврів-Колкарів. Для Реґтара Дезґейта він — відчутний доказ того, що навалу кентаврів із Пустограю зламано.",h="Подертий клапоть тканини зі штандарта Воєначальника Кром'зара, ватажка відплатного війська кентаврів-Колкарів.",kw={"прапор кром'зара","кром'зар","колкари","кентаври","реґтар дезґейт","пустограй"},ang={["faction:Horde"]="Перемога над Кром'заром і захоплення його прапора зупиняють великий наступ кентаврів і вбезпечують північні шляхи між Дуротаром, Малгором і Перехрестям.",["race:Tauren"]="Кентаври здавна дошкуляли кочовим племенам, тож розгром авангарду Кром'зара — бажаний знак того, що стежки до Малгора тепер безпечні."},sec={{t="Трофей кентаврської навали",b="Коли по всіх Пустках один за одним полягли вожді Колкарів, із Пустограю на схід рушив розлючений бойовий загін, що прагнув помсти. На чолі з Воєначальником Кром'заром загарбники атакували оборонні бункери на захід від Перехрестя. Відтятий клапоть поваленого бойового штандарта — незаперечний доказ для Реґтара Дезґейта, що напад розгромлено, а південні торгові шляхи збережено для Орди."}},faq={{q="Для чого цей шматок прапора?",a="Подертий клапоть несуть Реґтарові Дезґейту до його бункера на захід від Перехрестя. Він доводить, що Воєначальника Кром'зара вбито, а його загін нападників розбито, — і це завершує оборону півночі Пусток.",al={"призначення прапора","навіщо зберігати прапор","що робити з шматком прапора"}},{q="Хто такий Воєначальник Кром'зар?",a="Кром'зар — лютий командир Колкар, посланий із пустищ Пустограю. Він повів пряму відплатну атаку на застави Орди у відповідь на загибель місцевих ватажків Колкар.",al={"хто такий кром'зар","лор кром'зара","воєначальник кром'зар"}},{q="Чому Колкар напали на бункер?",a="Коли поборники Орди вбили місцевих вождів Пусток — зокрема Барака, Вероґа й Гезрула, — розлючені кентаври зібрали підкріплення з Пустограю, щоб помститися Орді на захід від Перехрестя.",al={"чому контратака","чому колкар вторглися","причина контратаки пустища"}},{q="Чи дізнається Тралл про цю перемогу?",a="Так. Отримавши клапоть прапора, Реґтар Дезґейт обіцяє надіслати офіційну звістку просто Вождеві Траллу в Оргріммар і відзначити захисників, які зламали навалу.",al={"нагорода від тралла","чи тралл знає"}}},fp="26,216,31.423.0,35.207.0,25.182.0,37.222.0,33.178.0"}
P.entries["item:plainstrider-beak"] = {n="Дзьоб Степовика",s="Дзьоби степових довгоступів добувають із високих нелітаючих птахів, що бродять чагарниковими рівнинами Пусток. Старші мисливці на Перехресті збирають ці дзьоби як доказ того, що новачок проредив місцевих птахів, які загрожують запасам поселення.",h="Дзьоби степових довгоступів добувають із високих нелітаючих птахів, що бродять чагарниковими рівнинами Пусток.",kw={"дзьоб степовика","степовий довгоступ","перехрестя","серґра даркторн","полювання","мисливець"},ang={["class:Hunter"]="Полювання на степових довгоступів і збирання їхніх дзьобів — перший урок для молодого слідопита: як вистежити й здобути звіра на відкритих рівнинах Калімдору.",["faction:Horde"]="Прорідивши набридливі зграї на схід від Перехрестя, ви прямо захищаєте крихкі торгові й постачальні шляхи, що годують цю заставу Орди."},sec={{t="Мірило полювання",b="Неосяжні савани довкола Перехрестя населяють різні породи степових довгоступів — великі, прудкі й норовливі. Порівняно з лютішими звірами центрального Калімдору це досить легка здобич, але через свою ненажерливість вони постійно шкодять поселенням. Серґра Даркторн доручає новоприбулим мисливцям принести дзьоби степових довгоступів — на доказ того, що зграї відігнали від життєво важливих шляхів постачання й комор."}},faq={{q="Навіщо Серґрі Даркторн Дзьоби Степовика?",a="Серґра Даркторн просить мисливців проріджувати степових довгоступів, бо ці агресивні птахи раз у раз нищать запаси їжі довкола Перехрестя. Дзьоби — відчутний доказ успішного полювання й того, що загроза шляхам постачання поменшала.",al={"навіщо збирати дзьоби","завдання дзьобів степовика серґри","навіщо дзьоби"}},{q="З яких істот добувають ці дзьоби?",a="Їх забирають у різних довгоступів, що бігають саваною, — великих, прудких і норовливих степових довгоступів Пусток.",al={"що дропає дзьоби степовика","джерела дзьобів степовика","де взяти дзьоби"}},{q="Чому не з кожного степового довгоступа можна взяти дзьоб?",a="У запалі бою, особливо з прудкими птахами, що відчайдушно б'ються, дзьоб часто тріскає, ламається чи стає непридатним як чистий мисливський трофей, тож збирають лише цілі.",al={"чому поганий дроп","дзьоб степовика не падає"}}},fp="17,249,21.464.0,50.264.0,34.174.0,54.199.0"}
P.entries["item:plainstrider-feather"] = {n="Перо Степовика",s="Вискубані у прудких птахів, що блукають рівнинами Малгору, пера степових довгоступів — важливий матеріал, який збирають молоді мисливці на Плато Червоної Хмари. Табір Нарачі використовує їх передусім для одягу й племінних оздоб, і таурени шанують створінь, що годують селище.",h="Вискубані у прудких птахів, що блукають рівнинами Малгору, пера степових довгоступів — важливий матеріал...",kw={"перо степовика","степовий довгоступ","пера","мисливець","табір нарачі","ґрулл гоквінд","плато червоної хмари"},ang={["class:Hunter"]="Вистежувати прудких степових довгоступів на Плато Червоної Хмари — засадниче випробування посвяченого на терпіння, слідопитство й шану до здобичі.",["race:Tauren"]="Для молодого таурена зібрати пера степового довгоступа — важливий перший урок: нічого не брати в створінь Матері-Землі як належне й використовувати кожну частину здобичі на їжу й одяг."},sec={{t="Перша пожертва мисливця",b="На Плато Червоної Хмари молоді таурени рано вчаться, що виживання залежить від гострого ока слідопита й мисливця. Степові довгоступи бігають трав'янистим плоскогір'ям, даючи і поживу, і практичні матеріали. Вискубані міцні пера дають табору змогу виготовляти традиційний одяг і спорядження. Подані Ґруллу Гоквінду разом зі свіжим м'ясом, ці пера засвідчують повагу до потреб племені й стають найпершим випробуванням на шляху до визнання Вождем Гоквіндом і гостинного прийому в Тандер Блафі."}},faq={{q="Для чого потрібні Пера Степовика?",a="Таурени з Табору Нарачі використовують їх передусім для одягу й обрядових речей. Ґрулл Гоквінд збирає їх у мисливців-новачків, щоб поповнити запаси племені.",al={"призначення пера","використання пера степовика","навіщо збирати пера"}},{q="Хто збирає Пера Степовика на Плато Червоної Хмари?",a="Ґрулл Гоквінд просить їх від імені Табору Нарачі, щоб поповнити запаси селища й перевірити, чи мають молоді мисливці дисципліну, потрібну, щоб годувати плем'я.",al={"хто хоче пера","кому потрібні пера","ґрулл гоквінд пера"}},{q="Де знайти степових довгоступів?",a="Вони блукають відкритими луками Плато Червоної Хмари й хвилястими рівнинами Малгору.",al={"де знайти степових довгоступів","місце степових довгоступів","фарм пер"}},{q="Навіщо Ґруллу Гоквінду ці пера для племінних обрядів?",a="Полювання — наріжний камінь культури тауренів: і для виживання, і як змагання. Повернувшись із м'ясом і пір'ям, новачок доводить Вождеві Гоквінду, що може годувати плем'я, перш ніж вирушити далі до Тандер Блафа.",al={"полювання починається лор","випробувальне полювання тауренів","чому полювати на степових довгоступів"}}},fp="20,300,25.496.0,40.164.0,52.172.0,33.97.0,64.234.0"}
P.entries["item:plainstrider-kidney"] = {n="Нирка Степовика",s="Орган, вийнятий із прудконогих степових довгоступів, що бродять посушливими рівнинами Пусток. Більшості мандрівників він не до смаку, проте в екзотичних броварських традиціях Калімдору це дивний, але незамінний складник.",h="Орган, вийнятий із прудконогих степових довгоступів, що бродять посушливими рівнинами Пусток.",kw={"нирка степовика","степовий довгоступ","дрон","раджет","пиво","бурештоф"},ang={["class:Hunter"]="Розбирати тушки степових довгоступів просто на савані — випробування мисливської точності: нутрощі мають лишитися цілими для обміну з броварами Раджета.",["profession:Cooking"]="Кулінари-мандрівники можуть скривитися від думки про пташині нирки в шляхетному трунку, але виживання в дикому Калімдорі часто тримається на тому, щоб пустити в діло кожну частину здобичі."},sec={{t="Незвичний броварський складник",b="Безкраї простори Пусток населяють високі нелітаючі птахи — степові довгоступи. Мисливці зазвичай беруть їхнє пір'я й м'ясо на знаряддя та прості харчі, але Майстер Броварства Дрон у Раджеті шукає їхні нутрощі з зовсім іншою метою. Як запевняє цей дивакуватий бровар, нирки степових довгоступів потрібні, щоб відтворити легендарне міцне пиво Ченя Бурештофа: вони додають напою особливого удару, а рецепт передавався незвичним родоводом броварів."}},faq={{q="Для чого потрібна Нирка Степовика?",a="Вона потрібна Майстрові Броварства Дрону в Раджеті, щоб відтворити легендарну партію елю Бурештофа. Він запевняє, що рецепта його наставника навчив сам мандрівний майстер броварства, пандарен Чень Бурештоф.",al={"використання нирки степовика","навіщо мені нирки степовика","призначення нирки степовика"}},{q="Навіщо комусь варити ель із нутрощами тварин?",a="Екзотичні напої Калімдору часто містять частини суворих місцевих тварин, щоб дати міцний, незабутній смак і особливий удар. Майстер Броварства Дрон зауважує, що такі міцні, дикі рецепти тепло нагадують йому химерні витвори на кшталт трогівського елю.",al={"нирки в елі","чому нирки в штормстаут","частини тварин в алкоголі"}},{q="З яких істот добувають ці нирки?",a="Їх вирізають із різних степових довгоступів, що бігають Пустками, — прудких, норовливих і великих.",al={"де падають нирки степовика","хто дропає нирку степовика","джерело нирок степовика"}},{q="Які ще складники потрібні, крім нирок?",a="Щоб завершити вариво, Майстер Броварства Дрон просить п'ять нирок степових довгоступів, п'ять іклів саванних левів і один ріг громового ящера.",al={"інші інгредієнти пива","що ще потрібно дрону","інгредієнти штормстауту"}}},fp="19,224,32.498.0,39.200.0,46.250.0,36.143.0,56.140.0"}
P.entries["item:plainstrider-meat"] = {n="М'ясо Степовика",s="М'ясо Степовика — свіжа дичина, здобута з нелітаючих птахів, що блукають рівнинами Малгору. Для молодих тауренів, які входять у зрілість на Плато Червоної Хмари, збирання цієї поживи — і життєво важливі зимові припаси, і головний обряд посвяти.",h="М'ясо Степовика — свіжа дичина, здобута з нелітаючих птахів, що блукають рівнинами Малгору.",kw={"м'ясо степовика","степовий довгоступ","дичина","мисливець","табір нарачі","ґрулл гоквінд","вождь гоквінд"},ang={["class:Hunter"]="Прудкий степовий довгоступ дає мисливцям-початківцям ранню перевірку слідопитства й влучності на відкритих рівнинах Малгору.",["race:Tauren"]="Для молодих тауренів, що виходять на Плато Червоної Хмари, полювання на степових довгоступів — перший практичний крок до поваги Вождя Гоквінда й права увійти в Тандер Блаф."},sec={{t="Пожива для плато",b="Життя тауренів нерозривно пов'язане з землею й урівноважує шану до природи з практичною потребою виживати. На Плато Червоної Хмари Табір Нарачі — поселення, що значною мірою живе з дичини, вполюваної на довколишніх луках. М'ясо степових довгоступів дає селищу необхідні запаси харчів, коли комори порожніють, а оперення птахів — матеріал для одягу й церемоніальних оздоб."},{t="Випробування молодого мисливця",b="Полювання на степових довгоступів — одне з перших випробувань для молоді, що прагне здобути повагу племені. Ґрулл Гоквінд посилає мисливців-новачків вистежувати прудких птахів на плато й збирати м'ясо та пера, щоб довести свою вправність слідопита й самостійність, перш ніж стати перед його батьком, Вождем Гоквіндом."}},faq={{q="Для чого потрібне М'ясо Степовика?",a="Молоді мисливці на Плато Червоної Хмари збирають М'ясо Степовика, щоб поповнити виснажені харчові запаси Табору Нарачі, — це важливе доручення від Ґрулла Гоквінда.",al={"навіщо м'ясо степовика","завдання м'ясо степовика","що робити з м'ясом степовика"}},{q="Хто просить це м'ясо?",a="Ґрулл Гоквінд, син Вождя Гоквінда, просить новачків полювати на степових довгоступів плато, щоб поповнити запаси їжі племені й довести, що вони здатні його годувати.",al={"хто хоче м'ясо степовика","ґрулл гоквінд м'ясо"}},{q="Де знайти М'ясо Степовика?",a="Його добувають із нелітаючих степових довгоступів, що блукають луками Малгору, особливо хвилястими пагорбами Плато Червоної Хмари.",al={"де взяти м'ясо степовика","місця степових довгоступів","фарм м'яса степовика"}},{q="Чому полювання на степових довгоступів важливе для тауренів?",a="Таурени полюють і з практичної потреби, і як духовна наука. Принісши здобич до табору, мисливець виявляє шану Земній Матері, самостійність і здатність годувати плем'я.",al={"культура полювання тауренів","чому полювати на степових довгоступів"}}},fp="17,257,23.401.0,22.311.0,35.162.0,23.166.0,37.138.0,64.202.0"}
P.entries["item:plainstrider-scale"] = {n="Луска Степового Довгоступа",s="Міцна луска, знята з довгоступів, що бродять широкими рівнинами Малгору. Це важливий складник традиційних ліків, які Маур Рейнколлер готує проти лютого зараження.",h="Міцна луска, знята з довгоступів, що бродять широкими рівнинами Малгору.",kw={"луска степового довгоступа","довгоступ","маур рейнколлер","маззранаш","село бладгуф","малгор","ліки"},ang={["race:Tauren"]="Збирання ліків із дарів землі відображає традиційні навички виживання, яких навчають молодих мисливців Малгору: кожна частина звіра рівнин служить племені."},sec={{t="Рідкісний складник",b="Степові довгоступи найбільше відомі м'яким пір'ям і пісним м'ясом, але їхні потужні ноги вкриті міцною захисною лускою. Ця луска витримує і жорстку місцевість чагарників, і пазурі хижаків. Знайти цілу луску, придатну для ліків, — справа терпіння: лише деякі довгоступи Малгору мають луску, досить тверду, щоб її можна було розтерти й приготувати для народних засобів."},{t="Ліки від отруйного укусу",b="Коли Маур Рейнколлер із Села Бладгуф натрапив на Маззранаша — легендарного довгоступа, відомого демонічно-червоними очима й отруйним укусом, — він дістав тяжку рану в плече. Упавши в маячну гарячку, Маур потребує Луски Степового Довгоступа разом із серцем вовка, стегновою кісткою кугуара й шлунком стрімкокрила, щоб очистити рану від зараження, поки воно не вбило його."}},faq={{q="Для чого потрібна Луска Степового Довгоступа?",a="Це важливий лікарський складник, який збирають для Маура Рейнколлера в Селі Бладгуф. Разом із частинами інших хижаків Малгору з неї варять засіб від запаленої отруйної рани, якої завдав довгоступ-одинак Маззранаш.",al={"що робить луска степового довгоступа","використання луски степового довгоступа","навіщо луска степового довгоступа"}},{q="Де знайти Луску Степового Довгоступа?",a="Луску здобувають, полюючи на диких степових довгоступів, що бігають відкритими луками по всьому Малгору.",al={"де взяти луску степового довгоступа","як отримати луску степового довгоступа","місце луски степового довгоступа"}},{q="Чому в Маура Рейнколлера запалення?",a="Мандруючи рівнинами, Маур потрапив у засідку Маззранаша — страхітливого довгоступа, відомого отруйним укусом і багряними очима, — і той вкусив його в плече. Укус спричинив гарячку з маренням, що дедалі гіршає й не минає від звичайного відпочинку.",al={"як маур захворів","чому маур хворий","укус мазранаш"}},{q="Які ще складники потрібні Маурові для ліків?",a="Крім Луски Степового Довгоступа, Маурові потрібні Серце Степового Вовка, Стегнова Кістка Рівнинного Кугуара й Шлунок Стрімкокрила, щоб завершити цілющу суміш.",al={"інгредієнти для маура рейнколлера","ліки від мазранаш","предмети завдання мазранаш"}}},fp="18,201,17.395.0,28.371.1,40.252.0,39.107.0,32.247.0,53.149.0"}
P.entries["item:plainstrider-talon"] = {n="Кіготь Степового Довгоступа",s="Кіготь Степового Довгоступа — гострий кіготь, здобутий із великих нелітаючих степових довгоступів, що водяться в Малгорі. Шамани тауренів разом з іншими природними реагентами використовують ці кігті, щоб виготовляти священні очисні тотеми, коли джерела води на їхній землі осквернено.",h="Кіготь Степового Довгоступа — гострий кіготь, здобутий із великих нелітаючих степових довгоступів, що...",kw={"кіготь степового довгоступа","степовий довгоступ","тотем","малл тандергорн","водяна криниця","шамани","малгор"},ang={["class:Shaman"]="Виготовлення очисних тотемів із тілесних частин звірів, як-от кігтів, — зразок традиційної шаманської практики тауренів, що черпає силу просто з рідних духів землі.",["race:Tauren"]="Шанувати жертву звірини Малгору — осердя тауренського полювання: кожен узятий звір допомагає зцілити Матір-Землю, коли її вражає гоблінське визискування."},sec={{t="Узи рівнин",b="Великі нелітаючі степові довгоступи блукають відкритими травами Малгору, покладаючись на потужні ноги й гострі кігті, щоб відбиватися від хижаків і рити тверду землю прерій у пошуках поживи. Для тауренів Села Бладгуф кожна частина вполюваного звіра має духовний відгук. Коли гоблінські підприємства осквернили священні джерела на кшталт Водяної Криниці Вінтергуфів, шаман Малл Тандергорн зажадав кігтів степових довгоступів разом із лапами степових вовків. У ритуальному ремеслі тауренів реагенти, зібрані з тутешніх хижаків і збирачів, дають змогу спрямувати духовну сутність землі в тотеми, здатні вигнати неприродні отрути."}},faq={{q="З яких істот випадає Кіготь Степового Довгоступа?",a="Кігті степових довгоступів добувають із дорослих і старих степових довгоступів, а також із сумнозвісного Маззранаша на луках Малгору.",al={"хто дропає кіготь степового довгоступа","де взяти кігті степового довгоступа","джерело кігтя степового довгоступа"}},{q="Для чого потрібні Кігті Степового Довгоступа?",a="Маллу Тандергорну в Селі Бладгуф потрібні кігті степових довгоступів і лапи степових вовків, щоб виготовити очисний тотем, яким очищають зіпсовану Водяну Криницю Вінтергуфів.",al={"використання кігтя степового довгоступа","навіщо мені кігті","завдання кігтя степового довгоступа"}},{q="Навіщо Маллу Тандергорну частини тварин, щоб очистити воду?",a="Шаманство тауренів спирається на злагоду з природними духами Малгору. Вплітаючи в обрядовий тотем частки місцевих тварин, шаман закликає саму первісну силу землі на боротьбу з чужою отрутою, яку принесли гобліни Венчурної Компанії.",al={"навіщо лапи й кігті тварин","шаманський обряд очищення кігті"}},{q="Хто отруїв криниці Малгору?",a="Гобліни — а саме агенти Венчурної Компанії, що діють у Малгорі, — та їхні прислужники отруїли священні племінні криниці, порушивши рівновагу краю й поставивши під загрозу племена тауренів.",al={"хто отруїв криниці","хто отруїв воду малгору","винуватець отруєння води"}}},fp="18,249,19.620.0,41.151.0,38.177.0,63.258.0,40.205.0"}
P.entries["item:podrig-s-order"] = {n="Наказ Подріґа",s="Наказ Подріґа — письмова військова заявка Вартового Смерті Подріґа з Гробниці. У ній він просить у торговця з Андерсіті Ґордона Вендгема свіжу партію зброї, щоб залога Відступників у Срібноліссі була належно озброєна.",h="Наказ Подріґа — письмова військова заявка Вартового Смерті Подріґа з Гробниці.",kw={"наказ подріґа","вартовий смерті подріґ","ґордон вендгем","андерсіті","гробниця","карос разок","зброя"},ang={["profession:Blacksmithing"]="Кована зброя вкрай потрібна на передовій, де безперервні бої постійно виснажують запаси залог.",["race:Undead"]="Заявка показує життєву ниточку постачання між Андерсіті й віддаленими заставами на кшталт Гробниці, завдяки якій вояки Темної Леді лишаються належно озброєними проти Погибелі."},sec={{t="Озброїти Гробницю",b="Срібнолісся — хиткий рубіж для Відступників, затиснутий між Погибеллю, що наступає, дикими звірами й іншими прихованими загрозами. Після переліку спорядження, який Вартовий Смерті Подріґ провів за наказом Екзекутора Гадрека, виявилося, що припасів у Гробниці здебільшого досить, але запасної зброї катастрофічно бракує. Це офіційне донесення перелічує клинки й зброю, потрібні вартовим смерті, які тримають заставу."},{t="Через доглядача кажанів",b="У вогких склепах Срібнолісся зброю так просто не викуєш, тож заявку адресовано Ґордонові Вендгему — торговцеві зброєю з гамірного Торгового Кварталу Андерсіті. Щоб пришвидшити замовлення, гінці несуть документ просто до Доглядача Кажанів Кароса Разока й користуються летючими шляхами Відступників, аби швидко поповнити припаси зі столиці."}},faq={{q="Що написано в Наказі Подріґа?",a="Це офіційна заявка з переліком зброї на заміну, потрібної Вартовим Смерті в Гробниці після звичних утрат у полі.",al={"що в наказі подріґа","зміст наказу подріґа","подробиці наказу подріґа"}},{q="Хто написав Наказ Подріґа?",a="Його склав Вартовий Смерті Подріґ за вказівкою Екзекутора Гадрека після перевірки зброярні Гробниці.",al={"хто це написав","автор наказу подріґа"}},{q="Хто отримує наказ?",a="Він призначений Ґордонові Вендгему — торговцеві зброєю, що веде справи в Торговому Кварталі Андерсіті.",al={"хто отримує наказ","куди наказ подріґа","одержувач наказу подріґа"}},{q="Чому Гробниці потрібна нова зброя?",a="Безперервні сутички з Погибеллю та іншими ворожими силами в Срібноліссі часто ламають чи забирають спорядження у Вартових Смерті, що боронять заставу.",al={"навіщо потрібна зброя","нестача зброї склепу"}}},fp="14,228,20.431.0,24.366.0,34.139.0,25.133.0,23.106.0,40.164.0"}
P.entries["item:pork-belly-pie"] = {n="Пиріг зі Свинячою Грудинкою",s="Пиріг зі Свинячою Грудинкою — сита домашня страва, яку пече «Тітонька» Берніс Стоунфілд у Лісі Елвінн. Попри гірку, давню ворожнечу між родинами Стоунфілдів і Маклурів, малий Біллі Маклур не може встояти перед куховарством Тітоньки Берніс і вимагає пиріг як хабар, щоб розповісти про загублену родинну реліквію.",h="Пиріг зі Свинячою Грудинкою — сита домашня страва, яку пече «Тітонька» Берніс Стоунфілд у Лісі Елвінн.",kw={"пиріг","свиняча грудинка","біллі маклур","тітонька берніс","кулінарія","ворожнеча"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що допомагають сільському Елвінну, такі доручення, як доставка пирогів, проливають світло на дріб'язкові, та глибоко вкорінені чвари, що ділять сільське серце Стормвінда.",["profession:Cooking"]="Пиріг показує, як домашня їжа може по-справжньому впливати на місцеві суперечки, навіть якщо сам рецепт лишається ревно бережною таємницею Тітоньки Берніс."},sec={{t="Хабар між ворожими фермами",b="Родини Стоунфілдів і Маклурів роками плекають гірке суперництво, сварячись за землю й гордість у серці Лісу Елвінн. Попри цю ворожнечу, малий Біллі Маклур має очевидну слабкість: він обожнює знаменитий пиріг зі свинячою грудинкою Тітоньки Берніс. Коли зникає цінне родинне намисто, Біллі відмовляється ділитися тим, що знає, доки шукач пригод не принесе йому теплий шматок. Берніс пече його вкрай неохоче — і з промовистим побажанням, щоб жадібний хлопчисько ним удавився, — доводячи, що кулінарна слава часом долає навіть найупертішу родинну ворожнечу."}},faq={{q="Для чого потрібен Пиріг зі Свинячою Грудинкою?",a="Пиріг пече Тітонька Берніс Стоунфілд, щоб задобрити малого Біллі Маклура. Біллі знає важливі подробиці про зникле родинне намисто Стоунфілдів, але не скаже ані слова, доки не втамує апетит стряпнею Тітоньки Берніс.",al={"використання пирога","навіщо пиріг зі свинячою грудинкою","що робити з пирогом"}},{q="Хто пече Пиріг зі Свинячою Грудинкою?",a="Пиріг свіжим пече Тітонька Берніс Стоунфілд на Фермі Стоунфілдів. Хоч вона й терпіти не може Біллі Маклура та всю його родину, все одно готує пиріг, щоб повернути загублене намисто.",al={"хто пече пиріг","пекарка пирога","пиріг бабусі стоунфілд"}},{q="Чому Біллі Маклур хоче їжі від ворожої родини?",a="Попри запеклу й галасливу ворожнечу між Стоунфілдами й Маклурами, стряпню Тітоньки Берніс знає вся долина. Для Біллі шлунок і смачна свиняча грудинка куди важливіші за родинні образи.",al={"чому біллі хоче пиріг","чому маклур хоче їжу стоунфілдів"}},{q="Чи можна з'їсти Пиріг зі Свинячою Грудинкою?",a="Ні. Пиріг — предмет завдання, призначений лише для Біллі Маклура. Ви не можете з'їсти його самі, щоб відновити здоров'я чи ману, хоч яким апетитним він видається.",al={"чи можна його з'їсти","чи їстівний пиріг зі свинячою грудинкою"}}},fp="14,318,29.572.0,36.258.0,29.212.0,53.232.0,35.153.0"}
P.entries["item:powdered-azurite"] = {n="Порошковий Азурит",s="Порошковий азурит — подрібнений мінеральний реагент, який добувають у Шахті Лазурової Жили в Передгір'ї Гілсбреда. Його шукає майстер-зброяр Тун'ґрім Файрґейз, щоб гартувати й кувати жорстокі обладунки для молодих воїнів Орди.",h="Порошковий азурит — подрібнений мінеральний реагент, який добувають у Шахті Лазурової Жили в Передгір'ї...",kw={"порошковий азурит","шахта лазурової жили","передгір'я гілсбреда","тун'ґрім файрґейз","жорстокий обладунок","ковальство"},ang={["class:Warrior"]="Здобувши порошковий азурит, ви доводите свою витривалість у далеких краях: збираєте особливі реагенти, з яких Тун'ґрім Файрґейз викує для вас обладунок лютої сили.",["faction:Horde"]="Щоб здобути цей очищений пил, доведеться вдарити вглиб Східних Королівств і вирвати ресурси просто з рук Альянсу в Передгір'ї Гілсбреда."},sec={{t="Рідкісна мінеральна сполука",b="Порошковий азурит — очищений пил із мінеральних жил під Передгір'ям Гілсбреда. Люди-робітники Шахти Лазурової Жили вгризаються в надра, щоб добути цей характерний синій камінь, а тоді товчуть його й пакують на продаж і для металургії. У руках вправного коваля цей пил стає важливим флюсом чи присадкою під час роботи з щільними металами: він додає готовому обладункові міцності й особливої витривалості."},{t="Кування жорстоких обладунків",b="Хоч порошковий азурит походить із людських штолень по той бік Великого моря, досвідчені ковалі Орди добре знають його неабиякі металургійні властивості. Тун'ґрім Файрґейз, літній орк-зброяр, що живе в Пустках, вимагає трохи цього товченого каменю разом з очищеним залізом і вогненними реагентами. Домішаний до розплаву, порошок дає йому змогу викувати важкі, нищівні пластини, якими славляться його бойові обладунки."}},faq={{q="Для чого потрібен Порошковий Азурит?",a="Це необхідний металургійний складник для Тун'ґріма Файрґейза — майстра-зброяра в Пустках. Він поєднує розтертий мінерал із залізними зливками й нестійкими реагентами, щоб викувати частини Жорстокого Обладунку для поборників Орди.",al={"використання порошкового азуриту","що таке порошковий азурит"}},{q="Де знайти Порошковий Азурит?",a="Його забирають у шахтарів-людей, що трудяться в Шахті Лазурової Жили на південному узбережжі Передгір'я Гілсбреда у Східних Королівствах.",al={"де знайти порошковий азурит","місце порошкового азуриту","хто дропає порошковий азурит"}},{q="Навіщо зброяреві в Пустках реагенти з Гілсбреда?",a="Тун'ґрім Файрґейз шукає найкращі матеріали, щоб кувати обладунки, гідні легендарних воїнів. Залізо легко дістати, але особливі гартувальні властивості мінералу з Лазурової Жили варті того, щоб його поборники перепливли за ним море.",al={"чому гілсбред","джерело мінералів тун'ґріма"}}},fp="16,217,23.418.0,20.454.0,34.245.0,36.156.0,67.267.0"}
P.entries["item:powers-of-the-void"] = {n="Сили Порожнечі",s="Сили Порожнечі — рідкісний магічний фоліант, що колись зберігався в закритому крилі бібліотеки Абатства Нортшира. Після того як послушник-відступник викрав його, переходячи до Братства Дефіас, наставниця чорнокнижників Друзілла Ла Салль прагне повернути книгу, щоб поглибити власне вивчення темної магії.",h="Сили Порожнечі — рідкісний магічний фоліант, що колись зберігався в закритому крилі бібліотеки Абатства...",kw={"сили порожнечі","фоліант","друзілла ла салль","братство дефіас","абатство нортшира","чорнокнижник"},ang={["class:Warlock"]="Повернення цього викраденого гримуара — засадниче випробування для молодих людей-чорнокнижників: доказ волі, достатньої, щоб заслужити таємницю прикликання біса.",["race:Human"]="Присутність фоліанта в Нортширі показує, що Святий Орден зберігає небезпечні магічні записи поряд зі звичайними церковними текстами, ховаючи їх від очей послушників."},sec={{t="Заборонений нортширський текст",b="Архіви Абатства Нортшира зберігають значно більше, ніж святе письмо й церковні записи. У захищеному крилі бібліотеки абатства лежали «Сили Порожнечі» — науковий трактат про енергії тіні й Безодні, імовірно написаний архімагом Хадґаром. Зважаючи на небезпечну природу таких досліджень, влада абатства пильно охороняла книгу й суворо забороняла доступ до неї випадковим відвідувачам. Так вона лишалася поза досяжністю тутешньої наставниці чорнокнижників Друзілли Ла Салль, яка не могла крутитися біля заборонених полиць, не викликавши небажаних підозр жрецтва."},{t="Крадіжка Дефіас і повернення",b="Фоліант зрештою покинув мури абатства не руками Друзілли, а через зраду зсередини. Послушник, що навчався в Нортширі, зрікся обітниць, щоб пристати до Братства Дефіас, і, тікаючи в сусідні виноградники, прихопив кілька цінних томів. Скориставшись пригодою злодія, Друзілла посилає перспективних чорнокнижників-новачків просто в табір бандитів Дефіас, щоб забрати фоліант з їхніх наметів. Повернення тексту слугує подвійній меті: воно віддає темне знання в руки наставниці й перевіряє, чи має новачок досить сміливості, щоб прив'язувати потойбічних демонів."}},faq={{q="Що таке «Сили Порожнечі»?",a="Це рідкісна окультна книга про темні енергії й поняття Нижнього Світу, яку, кажуть, написав архімаг Хадґар. Її тримали замкненою в закритому крилі Абатства Нортшира, доки її не викрали.",al={"що таке сили порожнечі","книга сили порожнечі","що за вкрадений том"}},{q="Чому книгу тримали замкненою в Абатстві Нортшира?",a="Абатство Нортшира зберігає історичні архіви, зокрема небезпечні тексти про заборонену магію. Книги про енергію Порожнечі й демонологію тримають під замком, щоб новачки й заблукані практики не зловживали ними.",al={"чому була в абатстві","чому жерці її мали","бібліотечне крило нортшира"}},{q="Як книга потрапила до Братства Дефіас?",a="Послушник абатства перекинувся до Братства Дефіас і забрав із собою кілька цінних томів із закритої бібліотеки Нортшира, сховавши їх у таборі бандитів на нортширських виноградниках.",al={"хто вкрав книгу","вкрадені книги дефіас","як дефіас її отримали"}},{q="Навіщо Друзіллі Ла Салль «Сили Порожнечі»?",a="Друзілла — місцева наставниця чорнокнижників у Нортширі. Вона прагне таємних знань цього тому для власного темного ремесла, але ніколи не могла б потрапити в захищені архіви бібліотеки абатства, не здійнявши тривоги.",al={"навіщо друзіллі книга","хто хоче книгу","вкрадений том друзілли ла салль"}},{q="Що доводить Друзіллі повернений том?",a="Здобутий том доводить Друзіллі, що новачок має хитрість, силу й рішучість, потрібні, щоб керувати демонічними слугами, — і вона вчить його викликати першого біса.",al={"навіщо чорнокнижникам книга","випробування прикликання біса","нагорода за вкрадений том"}}},fp="18,280,28.591.0,25.595.0,27.203.0,47.227.0,44.200.0,51.200.0,48.190.0"}
P.entries["item:prairie-alpha-tooth"] = {n="Зуб Альфи Прерій",s="Зуб Альфи Прерій беруть у лютих ватажків зграй, що блукають рівнинами довкола Тандер Блафу. У традиції тауренів ці зуби — могутня пожертва, якою очищають і шанують дорогоцінні джерела води на їхній землі.",h="Зуб Альфи Прерій беруть у лютих ватажків зграй, що блукають рівнинами довкола Тандер Блафу.",kw={"зуб альфи прерій","степові вовки","альфа","малл тандергорн","криниця","тандер блаф","малгор"},ang={["class:Shaman"]="Духів водяних криниць треба задобрювати земною рівновагою, і пожертвувані ікла найвищого хижака закріплюють цю природну гармонію.",["race:Tauren"]="Узяти ікло альфи прерій — означає виконати священний обов'язок мисливця: брати потрібне з повагою й повертати цю первісну сутність, щоб зцілити отруєну землю."},sec={{t="Очисна пожертва",b="Водяні криниці Малгору — життєво важливі джерела для тауренів, і збереження їхньої духовної чистоти вимагає обрядів шани й жертви. Щоб очистити Водяну Криницю Вайлдмейнів, Маллу Тандергорну із Села Бладгуф потрібні зуби, зібрані в альф степових вовків, що скрадаються в тіні Тандер Блафу. Як найвищі хижаки хвилястих трав'янистих рівнин, ці альфи уособлюють первісну силу дикої природи. Пожертвувані зуби шанують рівновагу між мисливцем, здобиччю й духами землі."}},faq={{q="Для чого потрібен Зуб Альфи Прерій?",a="Малл Тандергорн використовує вісім таких зубів в обряді очищення Криниці Вайлдмейнів — останньої отруєної криниці біля Села Бладгуф.",al={"призначення зуба альфи","для чого вовчі зуби в малгорі","предмет тотема вайлдмейн"}},{q="Де никають ватажки степових вовків?",a="Ватажки-альфи степових вовків никають відкритими трав'янистими рівнинами в центрі й на півночі Малгору — особливо кружляють довкола круч біля підніжжя Тандер Блафа.",al={"де ватажки степових вовків","місця вовків-альф","місця альф степових вовків"}},{q="Навіщо обрядові очищення води вовчі зуби?",a="Обряди тауренів шанують рівновагу природи. Щоб очистити криниці, потрібні священні складники, взяті просто в лютих корінних звірів цієї землі, — вони символізують і жертву, і життєву силу тварин Малгору.",al={"навіщо вовчі зуби для води","обряд зуба мулла тандергорна"}}},fp="19,216,20.495.0,39.142.0,34.148.0,53.212.0"}
P.entries["item:prairie-wolf-heart"] = {n="Серце Степового Вовка",s="Серце Степового Вовка — життєво важливий орган вовків, що блукають луками Малгору. Це незамінний складник термінових народних ліків, які Маур Рейнколлер із Села Бладгуф готує проти отруйного зараження.",h="Серце Степового Вовка — життєво важливий орган вовків, що блукають луками Малгору.",kw={"серце степового вовка","степовий вовк","маур рейнколлер","маззранаш","село бладгуф","малгор","ліки"},ang={["class:Hunter"]="Вистежування певних вовчих зграй на рівнинах свідчить про початкове розуміння здобичі та звичок звірів Малгору.",["race:Tauren"]="Ліки для виживання з частин здобутих звірів відображають практичні, близькі до землі традиції тауренів у дикій природі Малгору."},sec={{t="Ліки від отруйного укусу",b="Вовки рівнин — люті хижаки, витривалі й завзяті на широких травах Малгору. Їхні серця шукає Маур Рейнколлер — таурен із Села Бладгуф, який став жертвою легендарного степового довгоступа на ім'я Маззранаш. Уражений лютою отрутою істоти, що викликає гарячку, Маур покладається на традиційну медицину рівнин, щоб зупинити поширення отрути. Разом з іншими сильнодійними складниками, як-от кістка кугуара й пташиний шлунок, життєва сутність щойно вбитого степового вовка дає очищувальну силу, потрібну для ліків, поки маячня не стала смертельною."}},faq={{q="Для чого потрібне Серце Степового Вовка?",a="Його збирають для Маура Рейнколлера в Селі Бладгуф. Разом із кількома іншими частинами тварин Маурові воно потрібне, щоб зварити сильні народні ліки від отруйного укусу сумнозвісного довгоступа Маззранаша.",al={"використання серця степового вовка","навіщо серце вовка","призначення серця степового вовка"}},{q="Де здобути Серце Степового Вовка?",a="Його вирізають із тіл степових вовків, ватажків-альф і степових скрадачів, що полюють хвилястими рівнинами Малгору.",al={"місце серця вовка","хто дропає серце вовка","як знайти серце степового вовка"}},{q="Навіщо Маурові Рейнколлеру звірячі органи, щоб вилікувати рану?",a="Маззранаш завдає страшного запаленого укусу, що спричиняє гарячку й марення. Маур вдається до традиційних степових засобів тауренів із сильних реагентів — вовчого серця, стегнової кістки кугуара, луски степового довгоступа й шлунка стрімкокрила, — щоб очистити рану, поки вона не стала смертельною.",al={"навіщо серце вовка для ліків","ліки маура"}},{q="Чи підійде для ліків будь-яке вовче серце?",a="Лише серця степових вовків Малгору мають ту особливу життєву силу й властивості, яких вимагає традиційний степовий рецепт Маура Рейнколлера.",al={"чи підійде будь-яке вовче серце","які вовки дропають серце"}}},fp="18,243,28.598.0,38.211.0,43.140.0,63.269.0,42.154.0"}
P.entries["item:prairie-wolf-paw"] = {n="Лапа Степового Вовка",s="Лапи степових вовків здобувають із хижаків, що блукають рівнинами Малгору. Шамани, як-от Малл Тандергорн із Села Бладгуф, використовують їх як природні складники, щоб уплести силу землі в очисні тотеми.",h="Лапи степових вовків здобувають із хижаків, що блукають рівнинами Малгору.",kw={"лапа степового вовка","степовий вовк","тотем","малл тандергорн","криниця вінтергуфів","очищення","малгор"},ang={["class:Shaman"]="Виготовлення очисних тотемів із частин місцевих звірів показує засаду стихій: живою сутністю землі вигнати неприродну скверну.",["race:Tauren"]="Для тауренів здобути вовчі лапи — урочистий обов'язок дбайливого господаря: закликати рідних звірів землі, щоб зцілити прабатьківські водяні криниці, осквернені гоблінською жадобою."},sec={{t="Природні реагенти рівнин",b="Степові вовки скрадаються хвилястими травами Малгору, полюючи зграями разом зі степовими переслідувачами та своїми альфами. Хоч вони небезпечні для молодих мисливців і місцевої худоби, ці створіння глибоко вплетені в духовну рівновагу рівнин. Шамани тауренів бачать у вовчих лапах не просто трофеї, а важливі провідники вродженої життєвої сили землі."},{t="Очищення криниць",b="Коли підприємства гоблінів осквернили священні запаси води Малгору, шаман Малл Тандергорн потребував речової допомоги самої землі, щоб протидіяти забрудненню. Зв'язані разом із кігтями степових довгоступів, вовчі лапи дають первісний духовний відгук, потрібний для виготовлення очисних тотемів, і так починається життєво важлива праця з очищення Водяної Криниці Вінтергуфів."}},faq={{q="З яких істот випадає Лапа Степового Вовка?",a="Їх збирають зі степових вовків, степових скрадачів і ватажків-альф, що полюють рівнинами Малгору, переважно на південний захід від Села Бладгуф.",al={"хто дропає лапу степового вовка","де взяти лапи степового вовка","джерело лапи степового вовка"}},{q="Кому потрібні Лапи Степового Вовка?",a="Їх просить Малл Тандергорн, шаман-таурен із Села Бладгуф, щоб виготовити очисний тотем і відновити отруєні криниці.",al={"кому потрібні лапи степового вовка","лапи вовка мулла тандергорна","здати лапу степового вовка"}},{q="Навіщо вовчі лапи, щоб очистити воду?",a="Шаманство тауренів спирається на те, щоб спрямовувати природну життєву силу землі проти скверни. Вовчі лапи разом із пташиними кігтями дають шаманові змогу прив'язати живий дух Малгору до стихійного тотема, здатного вигнати гоблінські отрути.",al={"навіщо вовчі лапи","лор лапи степового вовка","чому мулл хоче лапи"}},{q="Яку криницю допомагають очистити ці лапи?",a="Лапи збирають саме для очисного тотема Водяної Криниці Вінтергуфів, яку отруїли гобліни-зайди та їхні посіпаки.",al={"яка криниця","очищення криниці зимових копит"}}},fp="16,244,30.370.0,19.354.0,39.166.0,28.147.0,42.251.0,44.154.0"}
P.entries["item:pridewing-venom-sac"] = {n="Отруйний Мішечок Гордокрила",s="Отруйні мішечки гордокрилів добувають у смертоносних віверн, що гніздяться довкола Озера Міркфаллон у Горах Кам'яного Кігтя. Нічні ельфи з Астранаару прагнуть зібрати й знищити ці мішечки, бо розвідка повідомляє, що агенти Орди добувають цю сильну отруту для таємних убивств.",h="Отруйні мішечки гордокрилів добувають у смертоносних віверн, що гніздяться довкола Озера Міркфаллон у Горах...",kw={"отруйний мішечок","гордокрили","віверни","отрута","озеро міркфаллон","астранаар"},ang={["faction:Alliance"]="Не дати Орді доступу до отрути гордокрилів украй важливо, щоб уберегти прикордонні дозори від невидимих убивць на спірних межах Кам'яного Кігтя та Ашенвалю.",["race:NightElf"]="Хоч провід вартових і шкодує, що доводиться вбивати безневинних диких звірів, захист життів ельфів від отруєних клинків важить більше за природну злагоду."},sec={{t="Загроза серед скель",b="Гордокрили Кам'яного Кігтя — небезпечні крилаті хижаки, що споконвіку живуть у горах на південь від Ашенвалю, особливо довкола Озера Міркфаллон. Дикі віверни отруйні від природи, але розвідка Альянсу з Терамора повідомляє, що вбивці Орди почали видоювати з них отруту, щоб змащувати клинки для таємних нападів на поселення нічних ельфів. Щоб уберегти родичів і зірвати ворогові постачання, вартові в Астранаарі наймають розвідників, які полюють на цих звірів і збирають отруйні залози, поки їх не здобула Орда."}},faq={{q="З яких істот добувають Отруйний Мішечок Гордокрила?",a="Ці мішечки добувають із різних виверн, що живуть на кручах біля Озера Міркфаллон у Горах Кам'яного Кігтя, — молодих гордокрилів, небесних мисливців, патріархів і подруг.",al={"де взяти мішечок гордокрила","хто дропає мішечок гордокрила","джерела отрути гордокрила"}},{q="Навіщо Астранаару Отруйні Мішечки Гордокрила?",a="До Шіндрелл Свіфтфайр дійшли донесення, що агенти Орди добувають отруту гордокрилів, щоб змащувати нею зброю для тихих убивств проти Альянсу. Знищивши чи відібравши ці залози, вона запобігає таким ударам.",al={"навіщо збирати мішечки","отрута шиндрел свіфтфайр"}},{q="Хто приймає ці мішечки в Ашенвалі?",a="Їх збирає Шіндрелл Свіфтфайр із містечка нічних ельфів Астранаар в Ашенвалі, щоб захистити свій народ від таємних нападів.",al={"хто бере отруту гордокрила","здати завдання гордокрила"}},{q="Чи гордокрили — природні союзники Орди?",a="Ні. Дикі гордокрили біля Озера Міркфаллон — звірі, що не допомагають Орді з власної волі, хоча агенти-орки використовують їхню отруйну природу у своїй війні.",al={"чи гордокрили з ордою","чи гордокрили служать оркам"}}},fp="19,286,21.530.0,43.192.0,45.209.0,42.140.0,51.166.0"}
P.entries["item:prismatic-punch-card"] = {n="Призматична Перфокарта",s="Призматична Перфокарта — картка даних із найвищим рівнем допуску, яку можна знайти в полеглому місті Гномреґан. Її крок за кроком оновлюють на низці терміналів «Матричний Перфограф», і на ній зберігаються дані, яких відчайдушно шукають гноми-біженці в Айронфорджі.",h="Призматична Перфокарта — картка даних із найвищим рівнем допуску, яку можна знайти в полеглому місті...",kw={"призматична перфокарта","перфокарти","перфограф","кастпайп","гномреґан","інженерні лабораторії"},ang={["profession:Engineering"]="Послідовне програмування перфокартами й мережа автоматичних терміналів показують високий рівень обчислювальних машин, що їх збудували майстри Гномреґана.",["race:Gnome"]="Складна система безпеки «Перфограф» — яскравий приклад того, як гномська винахідливість і бюрократія вціліли неушкодженими навіть після падіння рідного дому."},sec={{t="Питання безпеки",b="Коли гноми тікали від вторгнення трогів і отруйного опромінення Гномреґана, у глибинах лишилися величезні сховища досліджень і міських записів. Щоб уберегти найважливіші системи, гноми застосували багатоступеневий протокол безпеки. Щоб дістатися до терміналу «Матричний Перфограф 3005-D» у нижніх Інженерних Лабораторіях, треба пройти цілу низку перфокарт: від простої Білої Перфокарти — через Жовту, Синю й Червону, отримуючи допуск на окремих терміналах, — аж до остаточної Призматичної Перфокарти. Її закодований рівень допуску жартома позначено як такий, що чекає винайдення зовсім нового числа."},{t="Життєво важливе повідомлення",b="Майстер-механік Кастпайп, що нині перебуває серед біженців в Айронфорджі, посилає відважних шукачів пригод назад до заражених залів Гномреґана рятувати надважливі дані. Кастпайп описує ці дані як життєво необхідні, без яких ніяк не прожити, але розшифроване двійкове повідомлення на останній призматичній картці відкриває кумедну правду буденного гномського міського життя: це автоматичне сповіщення про те, що білизна Кастпайпа готова й чекає в пральні."}},faq={{q="Як створити Призматичну Перфокарту?",a="Призматичну Перфокарту отримують, вставивши Червону Перфокарту в термінал Матричного Перфографа 3005-D на нижньому рівні Інженерних Лабораторій Гномреґана. Щоб дійти до цього кроку, треба поступово вдосконалити звичайну Білу Перфокарту на терміналах моделей A, B і C по всьому комплексу.",al={"як отримати призматичну перфокарту","створити призматичну перфокарту","послідовність покращення перфокарти"}},{q="Які дані зберігає Призматична Перфокарта?",a="На картці сказано, що її рівень допуску такий високий, що для нього ще не вигадали числа, а далі йде довгий рядок двійкового коду. Майстер-механік Кастпайп наполягає, що ці дані надзвичайно важливі.",al={"що написано на картці","двійковий переклад перфокарти","розшифрована перфокарта"}},{q="Кому потрібна Призматична Перфокарта?",a="Картку просить Майстер-механік Кастпайп — гном-інженер у вигнанні, що живе в Айронфорджі, — під час завдання «Порятунок даних». Він вважає її вміст нагальними, безцінними відомостями, що лишилися під час евакуації Гномреґана.",al={"хто бере призматичну перфокарту","завдання кастпайпа","кому потрібна картка"}},{q="Де стоять термінали Матричного Перфографа?",a="Термінали розставлені по Гномреґану відповідно до рівня допуску. Перфограф 3005-A — біля Депо потяга й входу до Майстерні на поверхні, модель B — у Гуртожитку за Чистою Зоною, модель C — глибше в комплексі, а модель D — у нижніх Інженерних Лабораторіях.",al={"місця терміналів","де перфографи","де пробивати картки"}}},fp="20,249,20.637.0,22.483.1,41.311.0,48.205.1,35.242.0,51.303.0"}
P.entries["item:pristine-spider-silk"] = {n="Бездоганний Павучий Шовк",s="Бездоганний Павучий Шовк — надзвичайно тонка нитка, яку збирають з отруйних павуків Сутінколісся. Маги Стормвінда замовляють цей рідкісний матеріал, щоб ткати міцні зачаровані мантії, гідні визнаних знавців таємних мистецтв.",h="Бездоганний Павучий Шовк — надзвичайно тонка нитка, яку збирають з отруйних павуків Сутінколісся.",kw={"бездоганний павучий шовк","павуки","сутінколісся","святилище чародія","вінн ларсон","кравецтво"},ang={["class:Mage"]="Стормвіндських магів посилають просто в Сутінколісся по цю бездоганну нитку — це обряд посвяти, щоб здобути мантію, гідну вашого зростання в таємному мистецтві.",["profession:Tailoring"]="Здобуті у смертельно небезпечних павуків, ці тонкі, але міцні нитки — вершина природних тканин для пошиття магічного вбрання."},sec={{t="Ткання таємного",b="Не кожна нитка здатна втримати чари й витримати знос, якого вимагає діяльний маг. Звичайного павучого шовку в кравців досить, але потрібну міцність мають лише бездоганні нитки, взяті в падложерних самітників і молодих чорних вдів у темних гаях Сутінколісся. Маги стормвіндського Святилища Чародія посилають своїх здібних учнів у ці небезпечні ліси по бездоганні мотки, а пошити з них одяг, гідний адепта, доручають місцевій майстрині-кравчині Вінн Ларсон."}},faq={{q="Звідки береться Бездоганний Павучий Шовк?",a="Його добувають із павуків, що чатують у Сутінколіссі, — зокрема з павуків-падальників і молодих чорних вдів, що гніздяться під похмурими кронами.",al={"де взяти бездоганний павучий шовк","хто дропає бездоганний павучий шовк","місце бездоганного павучого шовку"}},{q="Хто шиє одяг із цього шовку?",a="Вінн Ларсон, кравчиня з Кварталу магів Стормвінда, шиє із зібраних мотків вишукану мантію для Святилища Чародія.",al={"хто використовує бездоганний павучий шовк","хто шиє шовк на шати","шати вінн ларсон"}},{q="Чому магам потрібен саме цей шовк?",a="Магам потрібен одяг, що відповідає їхній дедалі більшій магічній майстерності. Лише найчистіший, неушкоджений шовк смертоносних павуків Сутінколісся має міцність і якість, гідні мантії вправного мага.",al={"чому бездоганний шовк","використання магічного павучого шовку"}}},fp="20,240,18.520.0,42.149.0,35.152.0,44.193.0"}
P.entries["item:prowler-claws"] = {n="Кігті Нишпорки",s="Кігті нишпорки — трофеї, відтяті в нишпорок савани, що скрадаються випаленими сонцем рівнинами Пусток. Принесені Серґрі Даркторн на Перехресті, вони доводять, що мисливець здатен вистежити й здолати найнебезпечніших потайних хижаків Калімдору.",h="Кігті нишпорки — трофеї, відтяті в нишпорок савани, що скрадаються випаленими сонцем рівнинами Пусток.",kw={"кігті нишпорки","нишпорка савани","серґра даркторн","перехрестя","полювання","пустки"},ang={["class:Hunter"]="Здолати нишпорок савани й забрати їхні кігті — важливий обряд посвяти для молодих мисливців, які вчаться скритності, вистежуванню й боротьбі зі звіром віч-на-віч.",["faction:Horde"]="Винищуючи небезпечних нишпорок довкола Перехрестя, ви захищаєте гінців, каравани й поселенців Орди на небезпечних центральних шляхах Калімдору."},sec={{t="Трофеї скрадача",b="Висока трава Пусток ховає нишпорок савани — великих котячих хижаків, відомих своїм терпінням, хитрістю й смертоносними ударами. Полювання на них — важливе випробування для молодих воїнів і розвідників Орди. На відміну від травоїдної здобичі на кшталт степового довгоступа чи жеври, нишпорки самі влаштовують засідки на кожного, хто ступить на їхні мисливські угіддя. Щоб здобути їхні гострі вигнуті кігті, треба перемогти звіра, що покладається на цілковиту скритність і люто боронить свою землю, — і так довести мисливиці табору, що скрадач сам став здобиччю."},{t="Доказ для мисливиці",b="На Перехресті Серґра Даркторн вимагає ці кігті, щоб оцінити, чи готовий новачок до складніших випробувань. Пригорща принесених кігтів показує, що мисливець навчився читати сліди серед золотої трави савани й витримує удари пазурів, які рвуть і шкіру, і плоть. Ті, хто повертається зі здобиччю, доводять, що мають досить пильності, аби вижити навіть поруч зі смертоноснішими звірами, які чигають на рівнинах."}},faq={{q="Де взяти Кігті Нишпорки?",a="Кігті Нишпорки забирають у саванних нишпорок, що блукають луками в центрі Пусток, особливо на рівнинах на південний захід від Перехрестя.",al={"місце кігтів нишпорки","як отримати кігті нишпорки","де знайти кігті нишпорки"}},{q="Кому потрібні ці кігті й навіщо?",a="Серґра Даркторн, досвідчена мисливиця з Перехрестя, просить мисливців принести їй сім Кігтів Нишпорки — як випробування їхнього вміння вистежувати й битися з небезпечними хижаками.",al={"кому потрібні кігті нишпорки","здати кігті нишпорки","завдання кігтів серґри"}},{q="Чому полювання на саванних нишпорок вважають поважним?",a="На відміну від стад, що пасуться в Пустках, нишпорки — скритні хижаки, що вистежують мандрівників і здобич, ховаючись у високих заростях. Полювання на них перевіряє, чи вміє шукач пригод уникати засідок і здолати смертоносного, хитрого звіра.",al={"чому полювати на нишпорок","чи небезпечні нишпорки"}}},fp="13,273,23.532.0,22.418.0,29.161.0,30.192.0,56.250.0"}
P.entries["item:pure-hearts"] = {n="Чисті Серця",s="Чисті Серця — обрядові реагенти, які Карендін Галґар в Андерсіті дає чорнокнижникам-Відступникам. Ними приманюють сукуба крізь Викривлений Нижній Світ і змушують його проявитися, щоб чорнокнижник міг здолати демона й прив'язати до себе.",h="Чисті Серця — обрядові реагенти, які Карендін Галґар в Андерсіті дає чорнокнижникам-Відступникам.",kw={"чисті серця","сукуб","карендін галґар","чорнокнижник","викривлений нижній світ","демонологія","андерсіті"},ang={["class:Warlock"]="Для чорнокнижників-Відступників здобути й використати ці серця — переломна мить у демонології: так ви доводите, що ваш розум здатен опертися звабам Викривленого Нижнього Світу.",["race:Undead"]="Посеред гнилі й зарази Андерсіті використовувати зовсім незаплямовані серця, щоб грати на апетитах демонів, — це взірець холодного, прагматичного чаклунства Відступників."},sec={{t="Приманка для Нижнього Світу",b="Демонологія спирається на ниці бажання й духовні слабкості. Щоб викликати сукуба в Магічний Квартал Андерсіті, Карендін Галґар дає чорнокнижникам Чисті Серця. Покладені в коло виклику, ці незаплямовані духовні сутності стають потужною приманкою й тягнуть звабливого демона крізь Викривлений Нижній Світ у світ смертних. Щойно демон з'явиться, чорнокнижник мусить опертися його чарам, що полонять розум, і здолати його в бою. Перемога над сукубом утверджує містичну владу заклинача: демон повертається у Викривлений Нижній Світ, доки чорнокнижник не прокличе його справжнє ім'я, щоб навіки прив'язати до служіння."}},faq={{q="Для чого потрібні Чисті Серця?",a="Вони — містичний каталізатор для кола виклику в Магічному Кварталі Андерсіті: приманюють сукуба й проявляють його крізь порожнечу, щоб чорнокнижник міг із ним битися й прив'язати його.",al={"використання чистих сердець","навіщо чисті серця","що роблять чисті серця"}},{q="Хто дає Чисті Серця?",a="Карендін Галґар, наставник чорнокнижників-Відступників у Магічному Кварталі під руїнами Лордерону, дає їх учням, готовим опанувати виклик сукуба.",al={"хто дає чисті серця","видавець завдання на чисті серця"}},{q="Чому сукуб відгукується на Чисті Серця?",a="Сукуби живляться зіпсуттям, спокусою й нищенням невинності. Сяйво незаплямованих, чистих сердець — непереборна принада крізь Викривлений Нижній Світ, що тягне їх просто в приготоване чорнокнижником коло виклику.",al={"чому сукуба хоче чисті серця","лор чистих сердець"}},{q="Чи лишаються Чисті Серця у вас після обряду?",a="Ні. Коли сукуба викликано й приборкано, рештки Чистих Сердець повертають Карендіну Галґару як доказ, що випробування прив'язування завершено.",al={"чи залишаються чисті серця","що буде з чистими серцями"}}},fp="11,222,19.642.0,34.185.0,29.188.0,43.227.0,52.152.0"}
P.entries["item:purified-kor-gem"] = {n="Очищений Самоцвіт Кор",s="Очищений Самоцвіт Кор — рідкісний освячений кристал, потрібний зброяреві Джордану Стілвеллу біля Айронфорджа. Колись заплямований темними енергіями, він має бути відвойований у глибинах Калімдору й очищений ельфійською магією, перш ніж його можна буде вкувати у святу зброю Світла.",h="Очищений Самоцвіт Кор — рідкісний освячений кристал, потрібний зброяреві Джордану Стілвеллу біля Айронфорджа.",kw={"самоцвіт кор","паладин","джордан стілвелл","чорноглибинні печери","тундріс віндвівер","обердайн","наґи","очищення"},ang={["class:Paladin"]="Здобути й очистити цей самоцвіт — довести відданість паладина, пройшовши шлях від глибин Калімдору назад до Дун Мороґу, щоб викувати знакову зброю Світла.",["faction:Alliance"]="Здобуття очищеного самоцвіту єднає зусилля всього Альянсу: мудрість нічних ельфів Обердайна дає силу ковалю-людині, що працює на схилах Дун Мороґу."},sec={{t="Від скверни до святості",b="Свій шлях камінь починає як Зіпсутий Самоцвіт Кор у володінні підлих наґів, що зачаїлися в Чорноглибинних Печерах глибоко під узбережжям Ашенвалю. Щоб очистити камінь від його водяної, тіньової скверни, паладин мусить знайти нічного ельфа Тундріса Віндвівера в Обердайні. Спираючись на таємні й природні мистецтва, Тундріс виганяє з каменя скверну, обертаючи його на осяйний Очищений Самоцвіт Кор. Лише в цьому бездоганному стані він годиться як провідник святої сили."},{t="Шедевр коваля",b="Біля Айронфорджа, серед засніжених скель Дун Мороґу, зброяр-людина Джордан Стілвелл потребує самоцвіт як ключовий складник для кування майстерної зброї. Давно маючи креслення озброєння, гідного Срібної Длані, Стілвелл не мав екзотичних матеріалів, щоб утілити задум. Очищений Самоцвіт Кор разом із Дубовою Деревиною Вайтстоуну та рідкісною рудою стає духовним осердям, потрібним, щоб спрямовувати праведний гнів паладина."}},faq={{q="Для чого потрібен Очищений Самоцвіт Кор?",a="Його приносять ковалеві Джорданові Стілвеллу, що стоїть біля брами Айронфорджа в Дун Мороґу. Стілвелл використовує освячений самоцвіт як необхідний складник, щоб викувати освячену зброю для паладина, який проходить свої випробування.",al={"використання очищеного самоцвіту кор","навіщо мені самоцвіт кор","для чого самоцвіт кор"}},{q="Звідки походить самоцвіт?",a="Камінь походить із підземних руїн Чорноглибинних Печер на узбережжі Ашенвалю, де наги тримають його як зіпсований артефакт.",al={"походження самоцвіту кор","де падає самоцвіт кор","хто дропає самоцвіт кор"}},{q="Хто очищає самоцвіт?",a="Тундріс Віндвівер, ельф-учений із прибережного поселення Обердайн на Темному Узбережжі, виганяє темну енергію із Зіпсутого Самоцвіту Кор і повертає йому чистоту.",al={"як очистити самоцвіт кор","хто очищає самоцвіт кор","самоцвіт кор тундріса віндвівера"}},{q="Чи може будь-який шукач пригод скористатися Очищеним Самоцвітом Кор?",a="Самоцвіт шукають саме паладини, що проходять «Тест Праведності». Джордан Стілвелл приберігає своє ремесло для святих воїнів, які приносять йому очищений кристал разом з іншими рідкісними матеріалами.",al={"чи самоцвіт кор лише для паладинів","чи будь-хто може використати очищений самоцвіт кор"}}},fp="16,274,27.493.0,23.438.0,38.235.0,29.155.0,21.188.0,52.200.0"}
P.entries["item:putrid-claw"] = {n="Гнилий Кіготь",s="Гнилі кігті — зогнилі руки, відтяті в безтямної нежиті, що никає лісами на захід від Брілла. Вартовий Смерті Діллінджер збирає їх як остаточний доказ того, що загрозу Погибелі біля старого мосту тримають на відстані.",h="Гнилі кігті — зогнилі руки, відтяті в безтямної нежиті, що никає лісами на захід від Брілла.",kw={"гнилий кіготь","нежить","погибель","вартовий смерті діллінджер","старий міст","брілл"},ang={["race:Undead"]="Для свіжих посвячених Відступників, що покидають Похоронний Подзвін, винищення цієї безтямної Погибелі — раннє нагадування: свобода означає постійний захист від безтямних оболонок, на які вони колись самі скидалися."},sec={{t="Трофей безтямних",b="Навіть на власній батьківщині Відступники не можуть почуватися цілком безпечно: Король-Ліч і досі сягає сюди своєю рукою. Гурти безтямної Погибелі — гниючі мерці й пошматовані трупи — раз у раз переходять східні кордони на Галявини Тірісфалю, збираючись уздовж доріг і біля старого мосту на захід від Брілла. Щоб убезпечити мандрівників і лінії постачання гарнізону, Вартові Смерті призначають нагороду за цих блукаючих страховиськ. Відтятий гнилий кіготь — незаперечний речовий доказ того, що ще один шкутильгаючий труп упокоєно назавжди."}},faq={{q="Для чого потрібні гнилі кігті?",a="Вартовий Смерті Діллінджер у Бріллі збирає їх як підтвердження для винагороди — що місцеві новобранці-Відступники проріджують Погибель, яка блукає Галявинами Тірісфалю.",al={"використання гнилих кігтів","навіщо збирати гнилі кігті","хто хоче гнилі кігті"}},{q="Звідки беруться гнилі кігті?",a="Їх знімають із гнилих мерців і понівечених трупів, що никають проклятими лісами на захід від Брілла, особливо біля старого мосту через річку.",al={"де взяти гнилі кігті","дроп гнилих кігтів","дроп гнилих мерців"}},{q="Чому Погибель у Галявинах Тірісфалю?",a="Після спустошення Лордерону рештки безвольної Погибелі Короля-Ліча безперервно просочуються на захід через кордони Тірісфалю й загрожують дорогам і поселенням, якщо їх не винищувати.",al={"чому зомбі біля брилла","погибель у тирисфалі"}},{q="Чому Відступники не дають безвольній нежиті просто блукати?",a="На відміну від Відступників, які вирвалися на волю під проводом королеви Сильвани й повернули собі волю, безвольна Погибель кориться лише темним інстинктам чи давньому наказові Короля-Ліча й нападає на кожного живого чи вільного мерця, щойно побачить.",al={"відступники проти безвольних зомбі","чому вбивати іншу нежить"}}},fp="11,231,22.526.0,31.161.0,32.141.0,38.203.0,59.211.0"}
P.entries["item:pyrewood-shackle"] = {n="Кайдани Пайрвуда",s="Кайдани Пайрвуда — зачаровані пута, які носять знедолені мешканці Села Пайрвуд у південному Срібноліссі. Просякнуті дивною магією Архімага Аруґала, ці обручі пов'язані з моторошним прокляттям, що з настанням ночі перетворює звичайних селян на ненажерливих воргенів.",h="Кайдани Пайрвуда — зачаровані пута, які носять знедолені мешканці Села Пайрвуд у південному Срібноліссі.",kw={"кайдани пайрвуда","село пайрвуд","воргени","архімаг аруґал","далар донвівер","прокляття"},ang={["class:Mage"]="Маги, що вивчають Аруґалові вироби, упізнають необачне застосування чарів перетворення й сковування, вплетених у звичайну сталь.",["race:Undead"]="Учені-Відступники в Гробниці вважають розгнуздане чаклунство Аруґала великою загрозою своїм кордонам, тож збирання цих зачарованих пут вкрай важливе, щоб знешкодити вплив Фортеці Шадовфенг."},sec={{t="Пута Аруґалової магії",b="Прокляте село Пайрвуд ховає тривожну таємницю: удень його мешканці живуть звичайним життям і мають вигляд звичайних людей, але з заходом сонця перетворюються на диких воргенів Мунрейдж. Архімаг Аруґал закував цих селян у зачаровані кайдани в межах своїх викривлених дослідів із воргенським чаклунством. Далар Донвівер, дослідник магії, що служить Відступникам у Гробниці, вивчає ці кайдани, щоб розгадати чари, які зумовлюють це подвійне існування. Збираючи й аналізуючи залишкову енергію обручів, Донвівер прагне глибше збагнути магію Аруґала й зламати владу божевільного архімага над краєм."}},faq={{q="Для чого потрібні Кайдани Пайрвуда?",a="Далар Донвівер у Гробниці просить ці кайдани, щоб вивчити їхні чари. Висотавши з них магію, він сподівається розплутати закляття Архімага Аруґала й знайти спосіб знищити його вплив у Срібноліссі.",al={"використання кайданів пайрвуда","навіщо збирати кайдани","кайдани далара донвівера"}},{q="Хто носить ці кайдани?",a="Кайдани носять прокляті мешканці Села Пайрвуд на півдні Срібнолісся — і вдень, у людській подобі, і вночі, коли вони перетворюються на воргенів Мунрейдж.",al={"хто дропає кайдани пайрвуда","джерело кайданів","де знайти кайдани пайрвуда"}},{q="Чому селяни вночі перетворюються?",a="Архімаг Аруґал піддав мешканців Пайрвуда безрозсудним магічним дослідам і чарам. Кайдани підтримують закляття, що дає їм удень мати вигляд звичайних людей, а з настанням темряви вони показують свою дику подобу воргенів.",al={"чому пайрвуд перетворюється на воргенів","прокляття пайрвуда","таємниця вовкулаків пайрвуда"}},{q="Хто такий Далар Донвівер?",a="Далар Донвівер — маг-Відступник, що живе в Гробниці в Срібноліссі. Він уважно вивчає магічні аномалії, що лишив по собі Архімаг Аруґал, зосереджуючись на тому, щоб розібрати й зламати його викривлені прокляття.",al={"далар донвівер","хто такий далар"}}},fp="16,295,22.656.0,36.232.0,27.194.0,40.256.0,24.223.0"}
P.entries["item:quinn-s-potion"] = {n="Зілля Квінна",s="Зілля Квінна — відновлювальний напій, який приготував Аптекар Ренферрел у Гробниці. Його зварили, щоб поставити на ноги й підбадьорити пораненого скрадача смерті Квінна Йоріка після невдалого розвідувального патруля в Срібноліссі.",h="Зілля Квінна — відновлювальний напій, який приготував Аптекар Ренферрел у Гробниці.",kw={"зілля квінна","аптекар ренферрел","квінн йорік","гробниця","скрадачі смерті","срібнолісся"},ang={["race:Undead"]="Королівське Аптекарське Товариство рідко марнує сили на прості польові ліки, хіба що вони прямо рятують розвідників-Відступників, без яких не вберегти кордонів Срібнолісся."},sec={{t="Ліки Ренферрела",b="Коли скрадача смерті Квінна Йоріка тяжко побили й вивели з ладу біля Іварової ділянки, звістка дійшла до Королівського Аптекарського Товариства в Гробниці. Аптекар Ренферрел поспіхом змішав цей особливий напій, щоб допомогти Квіннові одужати. Ренферрел рідко дозволяє дрібним польовим втратам відволікати його від величніших і зловісніших досліджень для Леді Сильвани, але все ж дав ліки, щоб поставити пораненого розвідника на ноги й дати йому змогу рушити в дорогу."}},faq={{q="Для чого потрібне Зілля Квінна?",a="Зілля має допомогти одужати скрадачеві смерті Квінну Йоріку, що лежить поранений у північних лісах Срібнолісся. Випивши його, він відновлює досить сил, щоб знову рушити в дорогу.",al={"призначення зілля квінна","що робить зілля квінна","навіщо варити зілля квінна"}},{q="Хто зварив це зілля?",a="Вариво приготував Аптекар Ренферрел — алхімік Королівського Аптекарського Товариства зі склепів Гробниці.",al={"хто зварив зілля квінна","хто його зварив","зілля ренферрела"}},{q="Куди треба доставити зілля?",a="Його треба віднести на північ від Гробниці до Квінна Йоріка, що ховається біля хутора, відомого як Ділянка Івара.",al={"куди віднести зілля","місце квінна","місце квінна йоріка"}},{q="Чому Квіннові Йоріку знадобилося зілля?",a="Квінн був у дозорі скрадачів смерті, що розвідував північ Срібнолісся. На Ділянці Івара на розвідників напали гуль Івар Мерзенний і його посіпаки з Погибелі, і Квінн лишився там тяжко пораненим і безпорадним.",al={"чому квінн поранений","що сталося з квінном йоріком","квінн ушкоджений"}}},fp="14,231,16.466.0,32.212.0,23.131.0,43.120.0,41.214.0"}
P.entries["item:ran-bloodtooth-s-skull"] = {n="Череп Рана Бладтуса",s="Череп Рана Бладтуса — моторошний трофей, здобутий у ватажка зіпсованих фурболгів в Ашенвалі. Принесений нічним ельфам Астранаару, він стає відчутним доказом того, що лютій загрозі лісовому краю покладено край.",h="Череп Рана Бладтуса — моторошний трофей, здобутий у ватажка зіпсованих фурболгів в Ашенвалі.",kw={"череп рана бладтуса","фурболги","рейн вульфраннер","тероніс","астранаар","ашенваль"},ang={["faction:Alliance"]="Приносячи цей похмурий трофей, звитяжці Альянсу доводять, що гідні разом із вартовими боронити тендітні кордони Ашенвалю.",["race:NightElf"]="Для нічних ельфів здобути череп — сумна перемога. Вона помщається за Тероніса, але й нагадує, як глибоко демонічна порча спустошила їхніх колишніх союзників-фурболгів."},sec={{t="Трофей оборони Ашенвалю",b="Ліси Ашенвалю тяжко потерпають від демонічної скверни та порчі дикої природи, і колись мирні племена фурболгів упали в кровожерне божевілля. Одним із найлютіших серед цих ворожих ватажків був Ран Бладтус. Його череп дає вартовим нічних ельфів певний доказ, що громило загинув: його владу над місцевими фурболгами зламано, а знесилене містечко Астранаар може хоч трохи перепочити."},{t="Шана загиблим",b="Коли череп приносять Вартовій Рейн Вульфраннер в Астранаар, він ставить крапку в розслідуванні, яке почав загиблий розвідник Тероніс. Разом із Жезлом Дартола — прадавнім артефактом, очищеним від порчі, — череп Рана Бладтуса зберігають на видноті як свідчення мужності тих, хто бився за збереження священного лісу."}},faq={{q="Хто такий Ран Бладтус?",a="Ран Бладтус — вождь зіпсованих фурболгів в Ашенвалі, якого Вартові нічних ельфів вважали однією з найлютіших загроз краю.",al={"хто такий ран бладтус","лор рана бладтуса","ким був бладтус"}},{q="Навіщо Вартовим його череп?",a="Рейн Вульфраннер в Астранаарі потрібен речовий доказ перемоги над Раном Бладтусом. Череп кладуть поруч із Жезлом Дартола як символ перемоги й пам'яті про тих, хто загинув, захищаючи Ашенваль.",al={"навіщо мені череп","череп рейн вульфраннер","для чого череп"}},{q="Хто такий Тероніс?",a="Тероніс — Вартовий нічних ельфів, що загинув, намагаючись очистити зачарований жезл і з'ясувати джерело божевілля фурболгів, яке вразило Ашенваль. Його справу підхопили Рейн Вульфраннер і мандрівні шукачі пригод.",al={"лор тероніса","хто такий тероніс","тероніс астранаар"}}},fp="22,242,31.443.0,19.338.1,23.147.0,36.199.0,16.224.0"}
P.entries["item:raptor-head"] = {n="Голова Раптора",s="Відтята голова раптора — кривавий доказ того, що звіра в Пустках убито. Ґазроґ із Перехрестя вимагає ці моторошні трофеї, щоб очистити околиці від зграй після неймовірної крадіжки платні для варти.",h="Відтята голова раптора — кривавий доказ того, що звіра в Пустках убито.",kw={"голова раптора","раптори","ґазроґ","перехрестя","нагорода","пустки"},ang={["class:Hunter"]="Вистежувати сонцелуских рапторів у сухих чагарниках Пусток — перевірка, чи зможе мисливець перехитрувати одних із найагресивніших і найхитріших зграйних хижаків савани.",["faction:Horde"]="Перехрестя — серце сполучення Орди в центральному Калімдорі. Знищивши хижаків-злодіїв, ви вбезпечуєте припаси й платню гарнізону."},sec={{t="Нагорода Перехрестя",b="Життя на посушливих рівнинах Пусток і так нелегке, а тут ще й місцева звірина грабує сторожові вежі. Коли зі сторожової вежі Перехрестя зникла скриня з платнею для варти, оборонці впіймали на гарячому неймовірного злодія — дикого раптора. Спантеличений і розлючений Ґазроґ одразу оголосив нагороду за хитрих ящерів, що никають саваною. Принесені на заставу відтяті голови рапторів доводять, що цих хижих шкідників винищують, перш ніж вони поцуплять іще щось із припасів Орди."}},faq={{q="Навіщо Ґазроґу голови рапторів?",a="Вантаж срібла — платню для вартових Перехрестя — викрали просто з їхньої вежі. На загальне здивування, одним зі злодіїв, яких застали на гарячому, виявився раптор. Ґазроґ хоче, щоб цих звірів вистежили по всіх Пустках, аби вони більше не грабували поселення.",al={"навіщо збирати голови рапторів","ґазроґ раптори","нагорода за голови рапторів"}},{q="Навіщо диким рапторам срібло?",a="Ґазроґ визнає, що не уявляє, навіщо диким звірам металеві монети. Утім, раптори Калімдору славляться моторошною хитрістю, і цей випадок і соромить вартових Перехрестя, і розпалює в них жагу відплати.",al={"чому раптори хочуть срібло","раптори крадуть монети","таємниця рапторів-злодіїв"}},{q="Які раптори дають ці голови?",a="Голови можна здобути з різних сонцелуских рапторів, що бродять центром і півднем Пусток, — хльостохвостів, верещунів і косокігтів. Голови дають і сумнозвісні звірі, як-от Ішамугале й Такк Стрибун.",al={"де взяти голови рапторів","які раптори дропають голови","раптори пустища"}},{q="Що стається, коли голови віддано?",a="Коли Ґазроґ отримує дванадцять голів і бачить, що рапторів поменшало, увага переходить на те, куди ж насправді поділося вкрадене срібло.",al={"що далі після рапторів-злодіїв","після збору голів рапторів"}}},fp="11,202,24.506.0,34.274.0,36.246.0,32.220.0,40.155.0"}
P.entries["item:rare-earth"] = {n="Рідкісноземельний Метал",s="Рідкісноземельний Метал — особливий пакунок багатого на мінерали ґрунту, здобутого в Дарнасусі для ботанічних дослідів на Тельдрассилі. Його посилають гінцем із Доланаара травникові-дослідникові Деналану в його табір на березі Озера Ал'Амет.",h="Рідкісноземельний Метал — особливий пакунок багатого на мінерали ґрунту, здобутого в Дарнасусі для ботанічних...",kw={"рідкісноземельний метал","ґрунт","деналан","сірал блейдліф","озеро ал'амет","дарнасус","доланаар"},ang={["profession:Herbalism"]="Травники оцінять копіткі зусилля дослідників на кшталт Сірал Блейдліф і Деналана, які вивчають, як особливий ґрунт може змінити ріст і властивості саджанців Тельдрассила.",["race:NightElf"]="Для нічних ельфів, що доглядають своє молоде Світове Дерево, кожен ботанічний дослід біля Озера Ал'Амет дає розуміння того, як життя пристосовується до неприборканого віття Тельдрассила."},sec={{t="Ґрунт Дарнасуса",b="Новопостала жива система Тельдрассила потребує уважного спостереження й плекання, тож травники по всьому острову вивчають, як різні рослини відгукуються на чужий чи збагачений ґрунт. Цей пакунок рідкісної землі замовив просто з Дарнасуса Деналан — дивакуватий ботанік, що облаштувався на східному березі Озера Ал'Амет. Коли пакунок застряг у дорозі й із запізненням опинився в Доланаарі, травниця Сірал Блейдліф доручає мандрівникам, що прямують на південь, доставити нетривкий ґрунт Деналану, доки його сила не вивітрилася."}},faq={{q="Для чого потрібен Рідкісноземельний Метал?",a="Цю рідкісну землю призначено для Деналана — травника й дослідника рослин, що отаборився на березі Озера Ал'Амет. Він використовує особливі мінеральні суміші й збагачений ґрунт, привезені з Дарнасуса, щоб вирощувати місцеві рослини Тельдрассила й ставити на них досліди.",al={"використання рідкісноземельного металу","що деналан робить з рідкісною землею","призначення рідкісної землі"}},{q="Хто надсилає Деналанові цю землю?",a="Пакунок тримає Сірал Блейдліф — травниця з містечка Доланаар. Він запізнився з Дарнасуса, тож вона просить шукачів пригод, що прямують на південь до Озера Ал'Амет, доставити його замість неї.",al={"хто дає рідкісну землю","де взяти рідкісну землю","посилка сірал блейдліф"}},{q="Чому Деналан хвилювався через доставку?",a="Вантаж затримався дорогою до Доланаара, і Деналан довго чекав на березі озера. Отримавши його, він одразу непокоїться, чи зберегла земля свіжість і життєву силу для його ботанічних дослідів.",al={"чи зіпсована рідкісна земля","свіжа земля деналана","чому земля спізнилася"}}},fp="10,233,17.537.0,28.252.0,36.208.0,43.244.0"}
P.entries["item:rattlecage-skull"] = {n="Череп Гримучих Кісток",s="Черепи Гримучих Кісток — потрощені рештки безтямної нежиті, що никає зруйнованими околицями Похоронного Подзвону. Чорнокнижники-новачки з Відступників мають зібрати ці скам'янілі трофеї для Вені Мартанд, щоб показати свою міцніючу волю й здобути право на темне мистецтво прикликання.",h="Черепи Гримучих Кісток — потрощені рештки безтямної нежиті, що никає зруйнованими околицями Похоронного...",kw={"череп гримучих кісток","скелети","чорнокнижник","веня мартанд","похоронний подзвін","демон"},ang={["class:Warlock"]="Для чорнокнижників Відступників збирання цих черепів — перша віха їхньої дисципліни: доказ, що вони мають холодну волю, потрібну, щоб поневолити першого демона.",["race:Undead"]="Трощення нижчих, бездумних скелетів підкреслює віру Відступників в те, що панування утверджується чистою волею, яка й відрізняє вільну нежить від безтямних рабів."},sec={{t="Випробування неофіта",b="У безсонячних межах Похоронного Подзвону щойно піднятими Відступниками, що мають хист до темної магії, опікується Веня Мартанд. Щоб довести, що початківець має досить сили духу, аби підкоряти своїй волі істот з інших планів, Веня доручає йому впокорити скелетів Гримучих Кісток, що досі блукають біля зруйнованої кузні. Знищити цих нижчих мерців і принести їхні відтяті черепи — і практичне випробування дисципліни, і ритуальне підґрунтя, перш ніж навчитися прориватися в порожнечу й поневолювати першого демонічного прислужника."}},faq={{q="Для чого потрібні Черепи Гримучих Кісток?",a="Їх збирає Веня Мартанд у Похоронному Подзвоні. Чорнокнижники-Відступники мусять принести їй три черепи, щоб довести свою зосередженість і рішучість, — лише тоді вона навчить їх обрядів виклику й прив'язування біса.",al={"що таке черепи гримучих кісток","використання черепа гримучих кісток","хто хоче черепи гримучих кісток"}},{q="Звідки беруться Черепи Гримучих Кісток?",a="Їх забирають з розбитих решток скелетів Гримучих Кісток — безвольної нежиті, що блукає зарослими дорогами й напівзруйнованими подвір'ями біля покинутої кузні Похоронного Подзвону.",al={"де взяти черепи гримучих кісток","хто дропає черепи гримучих кісток","місце черепа гримучих кісток"}},{q="Навіщо Вені Мартанд черепи скелетів для випробування чорнокнижника?",a="Веня вважає, що сила оминає невігласів, а майстерність вимагає підкоряти зовнішні сили своїй волі. Убивши безвольних скелетів і забравши їхні голови, учень доводить, що має основну силу волі, щоб керувати енергіями хаосу, а не бути ними поглиненим.",al={"навіщо черепи для чорнокнижників","випробування вені мартанд"}},{q="Які знання дають за ці черепи?",a="Коли черепи принесено, Веня Мартанд відкриває таємний обряд, що дає змогу викликати й прив'язати біса, — і молоді чорнокнижники здобувають свого першого справжнього демона-слугу.",al={"що за черепи отримаєш","нагорода пронизати завісу"}}},fp="16,267,17.530.0,36.202.0,37.169.0,68.285.0,55.164.0"}
P.entries["item:raven-claw-talisman"] = {n="Талісман Воронячого Пазура",s="Талісман Воронячого Пазура — священна реліквія нічних ельфів, пов'язана з Друїдами Кігтя. Він зберігається глибоко в Курганному Лігві Бан'етіл на Тельдрассилі і є однією з чотирьох неодмінних Реліквій Пробудження, потрібних, щоб безпечно провести сплячих друїдів назад зі Смарагдового Сну.",h="Талісман Воронячого Пазура — священна реліквія нічних ельфів, пов'язана з Друїдами Кігтя.",kw={"талісман воронячого пазура","реліквії пробудження","друїди кігтя","курганне лігво бан'етіл","смарагдовий сон","атрідас бермантл","фурболги"},ang={["class:Druid"]="Талісман — емблема Друїдів Кігтя, що показує, як обрядові осередки бережуть дух друїда, поки той блукає Смарагдовим Сном.",["race:NightElf"]="Повернення цієї реліквії захищає і прадавню традицію нічних ельфів, і життя сплячих родичів, яким загрожує безумство фурболгів Вузлошкірів."},sec={{t="Ключ до пробудження",b="Талісман Воронячого Пазура зберігається в окремій скрині всередині Курганного Лігва Бан'етіл — підземного притулку, де Друїди Кігтя Тельдрассила поринули в глибокий споглядальний сон. Друїдська сплячка — тонкий духовний поріг. Якщо зв'язок друїда з явою розірвати без належного обрядового осередку, його дух ризикує навіки застрягти у Смарагдовому Сні. Разом із Чорним Пером, Сапфіром Небес і Руною Гніздування талісман потрібен Атрідасу Бермантлу в Доланаарі, щоб провести обряд пробудження й безпечно повернути сплячих."},{t="Загроза в курганному лігві",b="Коли споганені фурболги Вузлошкірів заполонили Курганне Лігво Бан'етіл, священні скрині та сплячі друїди опинилися в безпосередній небезпеці. Споганення фурболгами відрізало святилище від зовнішньої допомоги й наразило реліквії на втрату чи знищення. Атрідас Бермантл доручає захисникам Тельдрассила пройти звивистими земляними ходами лігва й здобути Талісман Воронячого Пазура, доки вигнаних друїдів не втрачено для Сну назавжди."}},faq={{q="Для чого потрібен Талісман Воронячого Пазура?",a="Це одна з чотирьох священних Реліквій Пробудження, потрібних для обряду, що пробуджує Друїдів Кігтя з глибокої сплячки в Смарагдовому Сні.",al={"що робить талісман воронячого пазура","призначення талісмана воронячого пазура","навіщо мені талісман воронячого пазура"}},{q="Де знайти Талісман Воронячого Пазура?",a="Він лежить у Скрині Воронячого Пазура в земляних тунелях Курганного Лігва Бан'етіл на захід від Доланаара на Тельдрассилі.",al={"де талісман воронячого пазура","місце скрині воронячого пазура","як знайти талісман воронячого пазура"}},{q="Кому потрібен Талісман Воронячого Пазура?",a="Атрідасу Бермантлу — друїдові нічних ельфів із Доланаара: талісман потрібен йому, щоб приготувати обряди пробудження для своїх родичів, що загубилися уві сні.",al={"кому потрібен талісман воронячого пазура","хто бере талісман воронячого пазура","кому його віддати"}},{q="Чому друїди не можуть прокинутися без нього?",a="Друїдська сплячка, що веде в Смарагдовий Сон, — складний і тонкий транс. Без особливого осередку Реліквій Пробудження, що закріплює обряд, дух сплячого ризикує назавжди загубитися у Сні.",al={"чому друїди потребують реліквій щоб прокинутися","чому реліквії пробудження","чи можуть друїди прокинутися без реліквій"}}},fp="19,260,18.627.0,28.447.0,41.158.0,39.135.0,34.136.0,40.243.0"}
P.entries["item:razorflank-s-medallion"] = {n="Медальйон Рейзорфланка",s="Медальйон Рейзорфланка — особистий знак Чарлґи Рейзорфленк, відьми, що панує в Рейзорфен Краулі. Здобутий у самому серці твердині шипогривів, він — незаперечний доказ того, що матріархиню повалено.",h="Медальйон Рейзорфланка — особистий знак Чарлґи Рейзорфленк, відьми, що панує в Рейзорфен Краулі.",kw={"медальйон рейзорфланка","чарлґа рейзорфленк","рейзорфен краул","фалфіндел вейвордер","таланаар","шипогриви"},ang={["faction:Alliance"]="Здобувши медальйон, ви мститеся за полеглого розвідника Гералата й дворфа-дослідника Лоунброу та вбезпечуєте прикордонний шлях від Таланаара до Фераласу.",["race:NightElf"]="Убивши Чарлґу й забравши її медальйон, нічні ельфи можуть безпечно дослідити осквернене священне місце спочинку Аґамаґґана."},sec={{t="Доказ падіння відьми",b="Цей медальйон, який носила сама Чарлґа Рейзорфленк, уособлює владу відьми, що веде шипогривів Рейзорфену. Коли Фалфіндел Вейвордер у Таланаарі дізнається про долю полеглих дослідників — Гералата й дворфа Лоунброу, — він доручає шукачам пригод з Альянсу вдарити просто по ватажці шипогривів. Медальйон відьми підтверджує її смерть і заспокоює вартових нічних ельфів, що стережуть кордони Фераласу: сили, зібрані в Краулі, втратили свою проводирку."}},faq={{q="Хто носить Медальйон Рейзорфланка?",a="Власниця медальйона — Чарлґа Рейзорфленк, карга й беззаперечна ватажка шипогривів у Рейзорфен Краул. Вона носить його при собі глибоко в колючих лабіринтах твердині.",al={"хто дропає медальйон рейзорфланка","джерело медальйона рейзорфланка","медальйон чарлґи"}},{q="Хто хоче отримати цей медальйон?",a="Медальйон просить Фалфіндел Вейвордер із прикордонної застави Таланаар між Фераласом і Тисячею Голок. Він вимагає його як остаточний доказ, що Чарлґу вбито.",al={"хто хоче медальйон рейзорфланка","здати медальйон рейзорфланка","медальйон фалфінделя"}},{q="Навіщо Фалфінделу доказ смерті Чарлґи?",a="Чарлґа збирала вороже військо шипогривів у Рейзорфен Краул, що загрожувало довколишнім краям і спричинило смерть розвідників, як-от Гералата й Лоунброу. Принесений медальйон запевняє нічних ельфів, що безпосередню загрозу зламано, і вони можуть продовжити розвідку краю.",al={"чому вбити чарлґу","призначення медальйона","навіщо медальйон"}}},fp="22,237,25.505.0,35.200.0,41.189.0,49.323.0"}
P.entries["item:reagent-pouch-shaman"] = {n="Мішечок Реагентів (шаман)",s="Мішечок реагентів, який носять культисти Палаючого Клинка, що причаїлися на скелях Дуротару. Шаман, що прагне єднання з вогнем, потребує цих зібраних чарівних складників, щоб перегнати свою першу вогняну сапту.",h="Мішечок реагентів, який носять культисти Палаючого Клинка, що причаїлися на скелях Дуротару.",kw={"мішечок реагентів","шаман","палаючий клинок","вогняна сапта","телф джулам","вогняний тотем","дуротар"},ang={["class:Shaman"]="Здобуття мішечка — поворотний обряд переходу на шляху до вашого Вогняного Тотема, який учить, що навіть осквернені стихійні посередники можна повернути на службу рівновазі.",["class:Warlock"]="Мішечки — звичайні чаклунські припаси культистів Скверни, що містять обрядові складники для демонічної піромантії, а не для єднання з природою."},sec={{t="Складники полум'я",b="Щоб приготувати вогняну сапту й налаштувати молодого шамана на духів полум'я, потрібні особливі обрядові каталізатори. Культисти Палаючого Клинка носять невеликі торбинки з реагентами для демонічних вогняних заклять. Відлюдник Телф Джулам поєднує зібрані порошки та олії з вогняною смолою шипогривів Гостроманів, щоб приготувати напій, який дарує зір у царину вогню."},{t="Нечисті джерела, чисте бачення",b="Хоч Палаючий Клинок спотворює полум'я задля руйнування й чаклунства Скверни, речовини в їхніх мішечках лишаються пов'язаними з первісною природою жару й горіння. Шаманська філософія стверджує, що всі сили стихій існують у напрузі: вогонь — і творець, і руйнівник. Забираючи вкрадені знаряддя культистів, шаман повертає стихійне середовище, щоб пробудити справжнє єднання з духами."}},faq={{q="Для чого потрібен мішечок реагентів?",a="Він — необхідний складник, з якого Телф Джулам варить вогняну сапту. Випивши цей еліксир, шаман здобуває провидчий зір, потрібний, щоб знайти духів стихій і здобути свій Вогняний Тотем.",al={"використання мішечка реагентів","що робить мішечок реагентів","завдання шамана мішечок реагентів"}},{q="Де знайти мішечок реагентів?",a="Мішечок забирають у культистів Палаючого Клинка, що засіли в Печері Пилового Вітру на скелястих висотах на північний схід від Гострого Пагорба в Дуротарі.",al={"дроп мішечка реагентів","де взяти мішечок реагентів","місце мішечка палаючого клинка"}},{q="Навіщо шаманові реагенти чорнокнижників?",a="Палаючий Клинок наповнює свої мішечки складниками, просякнутими магією вогню. Їхні обряди тримаються на полум'ї, тож їхні реагенти — готові стихійні каталізатори, які можна пустити на вогняну сапту.",al={"чому речі чорнокнижників","чому реагенти палаючого клинка","шаман і скверна"}}},fp="22,197,23.400.0,28.406.0,35.198.0,32.145.0,40.224.0"}
P.entries["item:reconstructed-tome"] = {n="Відновлений Фоліант",s="Відновлений фоліант — зібраний докупи гримуар темних знань кабали, укладений для чорнокнижників, які прагнуть поглибити владу над демонічними слугами. Він містить таємні знання й обряди, потрібні, щоб викликати й підкорити хижого мисливця Скверни з Викривленого Нижнього Світу.",h="Відновлений фоліант — зібраний докупи гримуар темних знань кабали, укладений для чорнокнижників, які прагнуть...",kw={"відновлений фоліант","фоліант кабали","мисливець скверни","страгад фарсан","чорнокнижник","раджет"},ang={["class:Warlock"]="Зібрати Відновлений фоліант — важливий обряд посвяти: він відкриває темні обряди, які дають вам владу над мисливцем Скверни і змогу спрямувати його жагу до магії проти ворожих заклиначів."},sec={{t="Гримуар, складений заново",b="Знайдений уривками й старанно складений докупи, Відновлений фоліант — це рідкісне зібрання вчень кабали, офіційно відоме як Фоліант Кабали. Чорнокнижники і Альянсу, і Орди докладають чималих зусиль, щоб відновити його пошарпані аркуші, і радяться з окультними вченими, які раді бодай краєм ока зазирнути в таємний зміст, перш ніж завершений рукопис піде з їхніх рук."},{t="Ключ до мисливця Скверни",b="Відновлену працю приносять Страгадові Фарсану — досвідченому майстрові викликів, що живе неподалік від порту Раджет у Пустках. Разом із магічними жезлами каналізування, відібраними в заклиначів клану Драконячої Пащі, обряди з фоліанта дають ученикам Страгада точні заклинання, щоб допомогти чорнокнижникові викликати, здолати й підкорити своїй волі ненажерливого мисливця Скверни."}},faq={{q="Для чого потрібен Відновлений Фоліант?",a="У книзі — темні обряди й учення кабали, потрібні, щоб викликати й підкорити мисливця Скверни. Чорнокнижник приносить її разом із жезлами каналізування Страгаду Фарсану в Раджет, щоб підготувати обряд прив'язування.",al={"призначення відновленого фоліанта","навіщо мені відновлений фоліант","використання відновленого фоліанта"}},{q="Хто такий Страгад Фарсан?",a="Страгад Фарсан — досвідчений викликач, що живе над портовим містечком Раджет у Пустках. Він наглядає за суворими випробуваннями чорнокнижників, які прагнуть поневолити небезпечніших демонів.",al={"хто такий страгад","роль страгада фарсана"}},{q="Чому вчені, що вивчають книгу, хочуть мати копію?",a="Ученим, які допомагають розшифрувати подерті сторінки, окультні тексти кабали видаються неймовірно захопливими й рідкісними. І дворфські дослідники, і дослідники-Відступники вважають своє звичне читво вбогим у порівнянні й прагнуть заволодіти рідкісними демонічними знаннями зі сторінок.",al={"хто переклав","вчені відновлений фоліант"}},{q="Що ще, крім фоліанта, потрібно для обряду?",a="Страгадові потрібні три жезли каналізування, щоб його послідовники могли підтримувати обряд виклику. Ці жезли треба відібрати в заклиначів Драконячої Пащі, що засіли в Багнокраї.",al={"інші предмети","що ще з відновленим фоліантом"}}},fp="18,269,22.395.0,20.401.1,40.208.0,22.198.0,51.264.0,54.179.0"}
P.entries["item:recruitment-letter"] = {n="Вербувальний Лист",s="Вербувальний лист — офіційне розпорядження, яке вручають багатообіцяльним шукачам пригод, що вирушають із Дуротару на службу в Пустки. Його видає розвідник Такрін Патсікер, і він скеровує придатних до служби добровольців на прикордонну заставу під началом Каргала Баттлскара.",h="Вербувальний лист — офіційне розпорядження, яке вручають багатообіцяльним шукачам пригод, що вирушають із...",kw={"вербувальний лист","такрін патсікер","каргал баттлскар","дуротар","новобранці","перехрестя"},ang={["faction:Horde"]="Цей лист знаменує перехід новобранця від місцевої оборони Дуротару до справжньої військової служби на рубежах Калімдору.",["race:Orc"]="Для молодих орків вручити підписаний лист про службу такому ветеранові, як Каргал Баттлскар, — важливий ранній крок до честі в новій Орді Вождя Тралла."},sec={{t="Набір на кордон",b="Коли молоді воїни й розвідники проявляють себе довкола Гострого Пагорба, Орда звертає погляд на захід — до неосяжних диких просторів Пусток. Такрін Патсікер вибирає новобранців, які здаються досить сильними для служби на передовій, і вручає їм цей лист. Перейти міст через Річку Південної Люті — це обряд посвяти: лишити позаду захищену червону землю Дуротару й стати в ряди Орди, що стоїть на варті проти шипогривів, кентаврів і розвідників Альянсу."},{t="Явитися до Баттлскара",b="Лист адресовано Каргалові Баттлскару — сивому ветеранові, що керує заставою відразу за річкою. Каргал оцінює кожного новобранця, перш ніж офіційно затвердити його вступ до війська. Та цей лист — лише перший крок: прикордонним заставам вічно бракує рук, тож будь-якого затвердженого новобранця швидко відсилають далі на захід, до ключового вузла — Перехрестя."}},faq={{q="Хто написав цей вербувальний лист?",a="Лист роздає Такрін Патсікер — орк-розвідник при дорозі з Гострого Пагорба, що пильнує здібних новобранців, які мандрують на захід.",al={"хто дає вербувальний лист","хто написав","лист такріна слідопита"}},{q="Куди треба віднести цей лист?",a="Ви доставляєте його Каргалові Баттлскару на сторожову заставу орків одразу за мостом через Річку Південної Люті, на самому кордоні Дуротару й Пусток.",al={"куди віднести вербувальний лист","здати вербувальний лист","кому віддати"}},{q="Що стається, коли лист підписано?",a="Каргал підписує документ, офіційно зараховуючи вас до війська, і одразу наказує йти вглиб рівнин і стати до служби на Перехресті, де конче потрібне підкріплення.",al={"що буде після підпису каргала","наступне завдання після вербувального листа"}},{q="Чому Орда набирає шукачів пригод у Пустках?",a="Пустки — величезний і небезпечний край, що з'єднує головні поселення Орди. Через безперервні загрози від місцевих кланів кентаврів, лютих шипогривів Щетиноспинних і дій Альянсу командирам на передовій потрібні всі здатні руки, яких тільки можна зібрати.",al={"чому вербують","чому призов у пустищі"}}},fp="18,253,27.482.0,23.395.0,34.157.0,34.152.0,39.187.0,57.256.0"}
P.entries["item:red-burlap-bandana"] = {n="Червона Мішковинна Бандана",s="Червоні Мішковинні Бандани — грубі фарбовані маски з тканини, які носять дрібні розбійники й кишенькові злодії Братства Дефіас. У Долині Нортширу Помічник Віллем збирає ці клапті тканини як доказ убитих злодіїв, що підступають до виноградників абатства.",h="Червоні Мішковинні Бандани — грубі фарбовані маски з тканини, які носять дрібні розбійники й кишенькові...",kw={"червона бандана","мішковина","братство дефіас","помічник віллем","нортшир","розбійники"},ang={["class:Rogue"]="Для розбійника-початківця зривання червоних масок із незграбних злодюжок Нортширу — урок того, як швидко недисципліновані розбійники стають легкою мішенню для місцевих охоронців порядку.",["faction:Alliance"]="Поширення цих червоних бандан аж до порога Абатства Нортшира показує, як сильно сільські кордони королівства вислизають з-під влади Стормвінда."},sec={{t="Знак Братства",b="Червона мішковинна бандана, пов'язана на нижній частині обличчя, слугує розпізнавальним знаком рядових Братства Дефіас. Зроблена з дешевої грубої тканини й просочена червоною фарбою, вона приховує риси злодія й водночас сповіщає про вірність повстанню, що набирає сили. У Нортширі молоді новобранці й звичайні головорізи носять ці хустки в східні сади, не здогадуючись, що тутешня варта використовує яскраву червону тканину як похмурий знак для винагороди."}},faq={{q="Навіщо Помічникові Віллему ці бандани?",a="Помічник Віллем збирає бандани як відчутний доказ, що шукач пригод знищив головорізів Дефіас, які пролазять через річку біля Абатства Нортшира. Злодії відкрито носять червону тканину, тож принесені бандани засвідчують, що винагороду за місцевих розбійників заслужено.",al={"навіщо збирати бандани","бандани віллема","здати братство злодіїв"}},{q="Хто носить червоні мішковинні бандани?",a="Їх носять волоцюги й головорізи з Братства Дефіас — організованої ватаги розбійників, що діє по всьому Лісу Елвінн і Вестфолу. Груба червона тканина — і маскування, і знак вірності їхній підпільній гільдії.",al={"хто носить червону бандану","лор маски дефіас","хто дропає червоні бандани"}},{q="Чому злодії Дефіас орудують у Нортширі?",a="Розвідники й грабіжники Дефіас отаборилися за струмком на схід від Абатства Нортшира, щоб мародерствувати, красти припаси й стежити за тими, хто виїжджає зі Стормвінда. Гарнізону абатства бракує людей, тож дрібні розбійники вільно никають довколишніми садами.",al={"чому дефіас у нортширі","злодії біля абатства"}},{q="Чому бандани червоні?",a="Бандани — просто клапті дешевої мішковини, пофарбовані в багряний колір. Цей помітний колір — офіційний стяг і однострій Братства Дефіас, щоб члени братства впізнавали одне одного в полі.",al={"чому маски дефіас червоні","значення червоної тканини"}}},fp="18,254,25.446.0,43.285.0,34.248.0,47.264.0,28.221.0"}
P.entries["item:red-leather-bandana"] = {n="Червона Шкіряна Бандана",s="Характерна частина вбрання членів Братства Дефіас по всьому Вестфолу. Зроблена з фарбованої багряної шкіри, вона водночас практично закриває обличчя й безпомильно позначає непокору Короні Стормвінда.",h="Характерна частина вбрання членів Братства Дефіас по всьому Вестфолу.",kw={"червона шкіряна бандана","братство дефіас","розвідник ґаліаан","едвін венкліф","сентінел гілл","вестфол"},ang={["class:Rogue"]="Багряна маска в людських землях стала синонімом підпільного розбою — безпомильним знаком злодіїв, організованих із військовою точністю.",["faction:Alliance"]="Кожна червона бандана, знята з полеглого розбійника, означає на одного грабіжника менше серед тих, хто загрожує голодним фермерам і знесиленому ополченню Вестфолу."},sec={{t="Знак Братства",b="Серед курних полів і покинутих ферм Вестфолу ці багряні бандани ховають обличчя грабіжників на шляхах, мародерів і бунтівних робітників. Для Народного ополчення в Сентінел Гіллі цей головний убір — більше, ніж просто тканина: це речовий доказ вірності розбійницькому братству Едвіна Венкліфа. Розвідник Ґаліаан збирає ці бандани в мандрівних шукачів пригод, щоб стежити за переміщеннями братства й тим, як тануть його лави в краї."}},faq={{q="Чому Дефіас носять червоні шкіряні бандани?",a="Червона бандана — спільний однострій Братства Дефіас. Вона приховує обличчя під час нападів на хутори й дороги і водночас відкрито заявляє про вірність повстанню Едвіна Венкліфа проти Стормвінда.",al={"маска дефіас","чому червона бандана","значення бандани дефіас"}},{q="Хто хоче, щоб ці бандани зібрали у Вестфолі?",a="Розвідник Ґаліаан із Народного ополчення на Сентінел Гілл просить мандрівників збирати їх. За ними він відстежує пересування ватаг і підтверджує загибель розбійників.",al={"хто бере червоні бандани","завдання галіаана про бандану","здати бандану на сентінел гіллі"}},{q="Де знайти ці бандани?",a="Їх можна забрати майже в будь-якого розбійника, грабіжника чи контрабандиста Братства Дефіас у таборах, на полях і в шахтах Вестфолу.",al={"дроп червоної бандани","фарм червоних бандан","хто дропає червону шкіряну бандану"}}},fp="19,236,23.473.0,44.220.0,47.184.0,31.139.0"}
P.entries["item:red-linen-bandana"] = {n="Червона Лляна Бандана",s="Червона лляна бандана — характерна маска на обличчя, яку носять члени Братства Дефіас по всьому Лісі Елвінн. Окрім того, що вона приховує особу бандита, тканина виткана з якісного льону, який винахідливі мешканці часто перешивають на корисний одяг.",h="Червона лляна бандана — характерна маска на обличчя, яку носять члени Братства Дефіас по всьому Лісі Елвінн.",kw={"червона бандана","льон","братство дефіас","едвін венкліф","сара тімберлейн","тканина"},ang={["class:Rogue"]="Багряна тканина, пов'язана на нижній частині обличчя, стала знаковим обличчям розбійників і кишенькових злодіїв у лісах довкола столиці.",["profession:Tailoring"]="Бандани показують, яким цінним лишається сире ткане полотно в сільському Елвінні, де прості ткалі перешивають бандитські кольори на робочий одяг."},sec={{t="Знак Дефіас",b="Поки дрібні новачки й звичайні головорізи в Долині Нортширу вдовольняються грубими мішковинними масками, повноправні бійці Дефіас по всьому Лісі Елвінн носять ткані червоні лляні бандани. Яскраво-багряна тканина слугує водночас уніформою й заявою про вірність розбійницькому братству Едвіна Венкліфа: вона ховає обличчя й сповіщає про заколот проти корони Стормвінда."},{t="Перешита тканина",b="Попри кривавий підтекст, бандани скроєні з пристойного полотна. Практичні поселенці, як-от Сара Тімберлейн, чий дім — Лісозаготівельний Табір Східної Долини, регулярно просять подорожніх збирати їх у таборах розбійників. Трохи прання й шиття — і контрабандна тканина перетворюється на міцний одяг і бинти для робочого люду лісу."}},faq={{q="Чому Дефіас носять червоні лляні бандани?",a="Червона бандана — однострій і знак непокори Стормвінду: вона приховує обличчя власника й показує його вірність братству Едвіна Венкліфа.",al={"значення маски дефіас","чому червоні маски","червона бандана дефіас"}},{q="Чим вони відрізняються від масок, які носять у Нортширі?",a="Головорізи в Долині Нортширу носять грубі мішковинні маски, а досвідчені агенти Дефіас по всьому Лісу Елвінн — тонший червоний льон.",al={"мішковина проти льону","маски нортшира","мішковинна бандана"}},{q="Хто хоче зібрати ці бандани?",a="Їх збирає Сара Тімберлейн із Лісозаготівельного Табору Східної Долини. Швачці бракує тканини, тож вона пере й розпускає бандитські маски, щоб виткати з них практичний одяг.",al={"хто бере червоні лляні бандани","бандана сари тімберлейн","здати завдання про бандани"}},{q="Які вороги носять червоні лляні бандани?",a="Їх носять майже всі агенти Дефіас у Лісі Елвінн — бандити, засідники, чаклуни-ренегати, портові робітники й ватажки на кшталт Морґана Збирача.",al={"хто дропає червону лляну бандану","де фармити бандани","дроп бандан дефіас"}}},fp="17,253,18.390.0,16.360.0,42.167.0,54.146.0,36.169.0,39.168.0"}
P.entries["item:red-wool-bandana"] = {n="Червона Вовняна Бандана",s="Червоні Вовняні Бандани — саморобні знаки, які ув'язнені головорізи Дефіас роблять у В'язниці Стормвінда. Видерті з тюремних вовняних ковдр, вони навіть за ґратами слугують зухвалими символами братства.",h="Червоні Вовняні Бандани — саморобні знаки, які ув'язнені головорізи Дефіас роблять у В'язниці Стормвінда.",kw={"червона вовняна бандана","братство дефіас","в'язниця стормвінда","мак раскол","нікова раскол","помста"},ang={["faction:Alliance"]="Для захисників Альянсу повернути ці бандани — похмурий акт справедливості для юного Мака Раскола й удар по бунтівниках, що захопили міську в'язницю.",["profession:Tailoring"]="Ці грубо зшиті бандани показують, як навіть цупкі вовняні ковдри можна розпустити й перетворити на щось нове руками зневірених в'язнів."},sec={{t="Зшиті з непокори",b="Навіть замкнені глибоко за високими кам'яними мурами В'язниці Стормвінда, члени Братства Дефіас не зрікаються себе. Зі шматків, видертих із тюремних вовняних ковдр, в'язні потай шиють червоні бандани, щоб носити їх як розпізнавальні кольори. Для вартових ці хустки — контрабанда, що розпалює смертельні бунти; для в'язнів — заява, що їхнє братство й бунт живуть навіть у кайданах."},{t="Бабусина помста",b="Бандани набули гіркої слави після того, як чотирнадцятирічний тюремний вартовий Мак Раскол спіймав в'язнів, коли ті роздирали ковдри. Коли він спробував їх покарати, засуджені з Дефіас ударили його ножем у спину. Після його смерті вбита горем бабуся хлопця, Нікова, шукає сміливців, які спустяться в охоплене бунтом підземелля, проріджать лави бунтівників і принесуть багряні хустки як доказ помсти."}},faq={{q="Звідки в'язні В'язниці беруть ці бандани?",a="В'язні з Дефіас роблять їх, роздираючи тюремні вовняні ковдри. Навіть обеззброєні й ув'язнені, вони перетворюють свою вбогу постіль на символи непокори й носять їх у камерах.",al={"звідки бандани","джерело бандан у в'язниці","як роблять червоні бандани"}},{q="Хто хоче, щоб ці бандани зібрали?",a="Їх просить зібрати Нікова Раскол — скорботна бабуся зі Стормвінда. Її чотирнадцятирічного онука Мака, вартового В'язниці, убили в'язні, коли він застав їх за виготовленням бандан.",al={"хто потребує червоні вовняні бандани","видавець завдання колір крові","бандана ніково раскола"}},{q="Чому в'язням так важливо носити червоні хустки?",a="Братство Дефіас носить червоні маски й бандани як головні кольори й однострій ватаги. За ґратами саморобні клапті допомагають в'язням зберігати звання, бойовий дух і єдність.",al={"чому червоні хустки","символ дефіас червоний","значення червоної бандани"}},{q="Які в'язні їх носять?",a="Їх має майже кожен бунтівний член Дефіас у В'язниці — полонені, ув'язнені, в'язні, повстанці й каторжники.",al={"хто дропає червону вовняну бандану","дроп бандан у в'язниці"}}},fp="16,210,20.424.0,25.415.0,54.196.0,35.205.0,60.197.0,25.142.0"}
P.entries["item:remaining-drops-of-purest-water"] = {n="Останні Краплі Найчистішої Води",s="Останні краплі найчистішої води — залишок особливого напою, який приготувала водяна провидиця Брайн. Шамани, що несуть ці могутні краплі, мандрують через королівства, щоб очистити священне водяне святилище, осквернене чумою нежиті Погибелі.",h="Останні краплі найчистішої води — залишок особливого напою, який приготувала водяна провидиця Брайн.",kw={"останні краплі найчистішої води","брайн","тотем води","шаман","срібнолісся","погибель"},ang={["class:Shaman"]="Ці краплі — вінець ваших випробувань на шляху до влади над водою. Донести їх із посушливих Пусток на сплюндроване узбережжя Срібнолісся необхідно, щоб здобути Тотем Води.",["faction:Horde"]="Паломництво шамана поєднує землі Орди в Калімдорі з хиткими володіннями Відступників у Срібноліссі й показує, як далеко сягає духовне зцілення в боротьбі з поморою Погибелі."},sec={{t="Ліки для осквернених вод",b="Цей насичений еліксир, створений обрядовим збиранням по всьому Калімдору й Лордерону, зберігає найчистішу суть прозорої води; приготувала його самітниця Брайн у Пустках. Частину напою шаман випиває, щоб узріти далекі стихії, а останні краплі береже для куди небезпечнішого завдання. Їх несуть на зачумлені береги Срібнолісся поблизу Гробниці, де вони стають життєво важливим очисним каталізатором на Жаровні Вічноджерела. Згоряючи в обрядовому вогні разом із наручами полеглого оскверненого елементаля, ця чиста вода розтинає некротичну скверну й викликає неосквернений дух води, який розмовляє з шаманом і завершує його єднання зі стихією."}},faq={{q="Для чого ці краплі?",a="Їх кладуть на Жаровню Вічного Джерела на узбережжі Срібнолісся разом із наручами зіпсованого прояву води. Цей обряд очищає осквернене святилище стихій і викликає незіпсованого духа води.",al={"що роблять останні краплі","призначення останніх крапель","використання найчистішої води"}},{q="Звідки ця рідина?",a="Це рештки очисного напою, який зварила Брайн — орчиха-шаманка, що живе на пагорбі на півдні Пусток, — під час духовних випробувань майбутніх шаманів.",al={"хто зробив найчистішу воду","походження крапель","краплі води брайн"}},{q="Чому обряд проводять аж у Срібноліссі?",a="Святилище води на узбережжі Срібнолісся, на захід від Гробниці, осквернила чума нежиття, і його духи стихій стали ворожими й спотвореними. Очищення саме цього джерела доводить відданість і майстерність шамана навіть на великій відстані.",al={"чому сільверпайн","чому їхати в сільверпайн","святиня води сільверпайну"}},{q="Що стається, коли краплі торкаються жаровні?",a="Вилиті в полум'я жаровні разом зі зіпсованими наручами, краплі шиплять у вогні й пробуджують закляття, що очищає рештки чуми й викликає чистий прояв води.",al={"жаровня обряд","що буде на жаровні","обряд жаровні вічного джерела"}}},fp="31,249,27.730.0,30.228.0,31.194.0,61.246.0,41.206.0"}
P.entries["item:remedy-of-arugal"] = {n="Зілля Аругала",s="«Зілля Аругала» — заклинання, записане магом Аруґалом під час його ранніх дослідів із воргенською магією. Залишене в занедбаній хаті на хуторі в Срібноліссі, воно потрібне Даларові Донвіверу, щоб розплутати темну роботу чаклуна.",h="«Зілля Аругала» — заклинання, записане магом Аруґалом під час його ранніх дослідів із воргенською магією.",kw={"зілля аругала","архімаг аруґал","далар донвівер","воргени","срібнолісся","заклинання"},ang={["class:Mage"]="Маги-Відступники поділять фахову зневагу Далара Донвівера до незграбних, необачних забавок Аруґала, але й визнають небезпеку неконтрольованих чарів виклику.",["race:Undead"]="Для Відступників здобути це заклинання — ранній, але важливий крок у відсіч диким воргенам, що загрожують кордонам Срібнолісся."},sec={{t="Рештки по магові",b="Ще до того як захопити Фортецю Шадовфенг, Архімаг Аруґал переховувався на покинутому пшеничному хуторі на північ від мосту через річку в Срібноліссі. Там, серед забутого сільського начиння й гнилих мостин, він описував свої дивні мистецтва в кількох запорошених книгах чарів. Сувій під назвою «Зілля Аругала» — серед цих записів: у ньому викладено ранні способи й магічні формули, які Аруґал вигадав, бавлячись небезпечними перетвореннями, що прокляли місцевих мешканців."},{t="Під пильним оком Відступників",b="Далар Донвівер, знаний чаклун-Відступник, що діє з Гробниці, не надто шанує родовід Аруґала й зневажливо вважає розум колишнього даларанського чарівника кволим і прозорим. Та все ж Донвівер розуміє, як нагально треба збагнути саму будову прокляття воргенів. Здобувши «Зілля Аругала», агенти-Відступники дають Донвіверу основи таємних знань, потрібні, щоб протидіяти поширенню Аруґалової напасті й утвердити Срібнолісся за Леді Сильваною."}},faq={{q="Що таке Зілля Аругала?",a="Це магічна формула, яку записав маг-ренегат Аруґал. Це не цілюще зілля, а записане закляття з магічними прийомами, якими він користувався, коли вперше почав досліди з магією воргенів у Срібноліссі.",al={"що таке зілля аруґала","предмет зілля аруґала","закляття зілля"}},{q="Де лишилося Зілля?",a="Аруґал залишив його серед запорошених книг заклять на горішньому поверсі покинутого пшеничного хутора трохи на північ від мосту через річку в Срібноліссі.",al={"де знайти зілля аруґала","місце зілля аруґала","книга заклять ферми"}},{q="Навіщо Даларові Донвіверу це закляття?",a="Далар Донвівер прагне розібрати саме ту магію, якою користувався Аруґал, щоб Відступники змогли знайти протидію, — і сподівається обернути власні методи чаклуна проти нього, щоб убезпечити край.",al={"навіщо даларові закляття","далар донвівер зілля"}},{q="Хто стереже книги заклять на хуторі?",a="Хутір заполонили вовкуваті раби Аруґала. Коли хтось намагається потривожити запорошені книги на другому поверсі, з тіні вистрибує Темний Бігун Мунрейджів, щоб захистити речі свого господаря.",al={"що нападає на фермі","засідка книги заклять"}}},fp="16,250,18.455.0,17.498.0,29.235.0,33.172.0,42.198.0,38.205.0"}
P.entries["item:rendered-spores"] = {n="Зібрані Спори",s="Зібрані Спори — нестійка емульсія, приготована зі зразків грибів, зібраних по всіх Пустках. Їх виготовляє Аптекар Гелбрім на Перехресті, і суміш швидко псується, якщо її негайно не доставити Аптекарці Замах під Тандер Блаф для стабілізації.",h="Зібрані Спори — нестійка емульсія, приготована зі зразків грибів, зібраних по всіх Пустках.",kw={"зібрані спори","аптекар гелбрім","аптекарка замах","озера видінь","королівське аптекарське товариство","перехрестя","тандер блаф"},ang={["race:Tauren"]="Те, що аптекарі-Відступники проводять досліди над дивною флорою Пусток у священних Ставках Видінь, відображає непростий, але практичний союз, укладений у Тандер Блафі.",["race:Undead"]="Королівське Аптекарське Товариство постійно шукає в Калімдорі нові біологічні сполуки на користь Відступникам і покладається на прудких гінців, які пов'язують польових дослідників, як-от Гелбріма, з лабораторними фахівцями, як-от Замах."},sec={{t="Нестійка суміш",b="Здобувши дивні спори з грибів біля вологих оаз Пусток, Аптекар Гелбрім переробляє їх на активну хімічну емульсію, відому як Зібрані Спори. Делікатна екстракція утримує сильнодійні речовини грибів у рідкому середовищі, проте розчин хімічно нестійкий. Свою силу він зберігає лише сорок п'ять хвилин, а тоді розкладається й стає геть непридатним для наукових досліджень."},{t="Доставка до Ставків Видінь",b="На віддаленій заставі Гелбрімові бракує й обладнання, і часу, щоб завершити очищення, тож емульсію треба мерщій доставити його колезі-Відступниці, Аптекарці Замах. Сховавшись у підземних Ставках Видінь під Узвишшям Духів у Тандер Блафі, Замах має спеціальне обладнання й реактиви, щоб знову запечатати спори й завершити їхню обробку для Королівського Аптекарського Товариства."}},faq={{q="Для чого потрібні Зібрані Спори?",a="Це грибна речовина, яку Аптекар Гелбрім добув і перетворив на емульсію для досліджень Королівського Аптекарського Товариства. Аптекарка Замах у Тандер Блафі використовує цю сильну суміш, щоб продовжити вивчення дивних наростів, що ширяться Пустками.",al={"призначення зібраних спор","що замах робить зі спорами","навіщо зібрані спори"}},{q="Чому емульсія діє лише обмежений час?",a="Хімічна емульсія Гелбріма вкрай нестійка й починає розкладатися, щойно її змішано. Її сила триває лише сорок п'ять хвилин, тож кур'єр мусить швидко перенести її рівнинами до Тандер Блафа, доки вона не стане недієвою.",al={"чому спори на час","чому спори спливають","тривалість зібраних спор"}},{q="Хто створив ці спори?",a="Аптекар Гелбрім, дослідник-Відступник із Перехрестя в Пустках, переробив сирі грибні спори, зібрані з грибів біля оаз, на цю нестійку рідку суміш.",al={"хто зробив спори","хто збирає спори","спори хелбрима"}},{q="Куди треба доставити суміш?",a="Спори треба доставити Аптекарці Замах. Вона мешкає глибоко в Ставках Видінь — системі печер під Узвишшям Духів у столиці тауренів, Тандер Блафі.",al={"куди нести зібрані спори","місце замаха","місце басейнів видінь"}}},fp="15,257,18.452.0,31.417.0,34.273.0,40.261.0,25.187.0,34.177.0"}
P.entries["item:renferrel-s-findings"] = {n="Знахідки Ренферрела",s="Знахідки Ренферрела — збірка дослідницьких записів, які уклав Аптекар Ренферрел у Срібноліссі. Довірені гінцям Орди, ці документи несуть важливі дані на південь, до Аптекаря Лайдона в Таррен Міллі, щоб допомогти зварити Нову Чуму Відступників.",h="Знахідки Ренферрела — збірка дослідницьких записів, які уклав Аптекар Ренферрел у Срібноліссі.",kw={"знахідки ренферрела","аптекар ренферрел","срібнолісся","усипальниця","таррен мілл","нова чума"},ang={["faction:Horde"]="Гінці, що несуть папери Ренферрела, допомагають зміцнити плацдарм Орди в Лордероні, з'єднуючи відокремлені застави, як-от Гробницю й Таррен Мілл.",["race:Undead"]="Дослідження в цих документах служать найвищій меті Сильвани Віндраннер: удосконалити Нову Чуму, щоб винищити і Погибель, і живих ворогів, що зазіхають на землі Відступників."},sec={{t="Чума в розробці",b="Королівське Аптекарське Товариство невтомно працює за прямим наказом Темної Леді, Леді Сильвани Віндраннер, щоб створити Нову Чуму. Такий прорив вимагає постійної співпраці дослідників, розпорошених по всьому Лордерону. Аптекар Ренферрел, що служить в Гробниці в Срібноліссі, збирає ці знахідки, щоб записати свої успіхи й досліди, і відсилає зібрані відомості на південь, до Таррен Мілла, щоб колеги могли спиратися на його результати."},{t="До Таррен Мілла",b="Доставка цих паперів через кордон зі Срібнолісся до Передгір'я Гілсбреда — важлива ланка алхімічної мережі Відступників. У Таррен Міллі Аптекар Лайдон нетерпляче чекає записів Ренферрела, щоб звірити їх і вдосконалити власні суміші проти живих і Погибелі. Без надійних гінців, що ходять спірними дорогами Гілсбреда, розпорошені дослідження Товариства швидко зупинилися б."}},faq={{q="Що в Знахідках Ренферрела?",a="У пакунку — найновіші дослідні дані й нотатки, які Аптекар Ренферрел зібрав під час роботи в Срібноліссі, зокрема щодо створення Нової Чуми для Відступників.",al={"що в знахідках","дослідження ренферрела","що в нотатках"}},{q="Хто має отримати ці дослідження?",a="Документи отримує Аптекар Лайдон. Він досліджує чуму в Таррен Міллі — поселенні Відступників у Передгір'ї Гілсбреда.",al={"хто отримує знахідки ренферрела","куди знахідки","цільова доставка"}},{q="Чому аптекарі обмінюються нотатками?",a="Леді Сильвана Віндраннер тисне на Королівське Аптекарське Товариство, щоб воно створило Нову Чуму. Аптекарі вірять, що прорив настане значно швидше, якщо вони узгоджуватимуть роботу й порівнюватимуть результати, а не працюватимуть нарізно.",al={"чому аптекарі діляться нотатками","чому слати лайдону","зв'язок аптекарів"}},{q="Де Аптекар Ренферрел проводить досліди?",a="Аптекар Ренферрел працює в Гробниці — головній заставі Відступників у самому серці Срібнолісся.",al={"де ренферрел","місце аптекаря ренферрела","хто написав знахідки ренферрела"}}},fp="20,264,23.486.0,14.425.0,36.213.0,41.143.0,39.254.0,56.123.0"}
P.entries["item:report-on-the-defias-brotherhood"] = {n="Звіт про Братство Дефіас",s="Звіт про Братство Дефіас — офіційний документ, який уклав Міський Архітектор Барос Алекстон; у ньому описано діяльність змовників Едвіна Венкліфа й загрозу, яку вони становлять. Призначений для королівського двору, звіт довірено шукачеві пригод, що розкрив змову в Мертвих Копальнях, щоб той особисто доставив його до Фортеці Стормвінда.",h="Звіт про Братство Дефіас — офіційний документ, який уклав Міський Архітектор Барос Алекстон; у ньому описано...",kw={"звіт про братство дефіас","барос алекстон","едвін венкліф","мертві копальні","фортеця стормвінда","катрана престор"},ang={["faction:Alliance"]="Доставка цієї депеші — вінець довгої боротьби за безпеку Вестфолу й спроби попередити провід Стормвінда про повстання, що назріває на його кордонах.",["race:Human"]="Для людей королівства цей звіт підкреслює трагічний і досі не розв'язаний конфлікт між шляхетним домом Стормвінда й каменярами, які відбудували місто."},sec={{t="Депеша для трону",b="Після довгого розслідування заворушень, що охопили Вестфол і сусідні землі, Міський Архітектор Барос Алекстон склав цей офіційний звіт, щоб попередити провід Стормвінда про весь масштаб загрози Дефіас. Замість того щоб послати звичайного королівського гінця, Алекстон довірив документ саме тому героєві, який розплутав змову. Звіт, доставлений просто до Фортеці Стормвінда, має супроводжувати особисту аудієнцію, на якій ідеться про задуми Едвіна Венкліфа й небезпеку, яку вони несуть королівству."},{t="Прийом у Фортеці",b="Хоч звіт адресований королю Варіану Рінну, гонець, прибувши до тронної зали, бачить, що монарха немає — він вирушив у тиху дипломатичну подорож. Замість нього звіт приймають королівські радники й регентство при хлопчикові-королі Андуїні. За припинення підступів Венкліфа гонцеві висловлюють королівську подяку, проте присутність при дворі таких осіб, як Леді Катрана Престор, кидає непевну тінь на те, наскільки серйозно поставляться до застережень цього документа."}},faq={{q="Що таке Звіт про Братство Дефіас?",a="Це офіційне донесення, яке написав Барос Алекстон: у ньому зведено всі зібрані відомості про Едвіна Венкліфа, його підземне військо й ширшу змову Дефіас проти Стормвінда.",al={"що це за звіт","предмет звіт про дефіас","звіт бароса алекстона"}},{q="Хто написав цей звіт?",a="Документ підготував Барос Алекстон — Міський Архітектор Стормвінда, що колись працював пліч-о-пліч із каменярами, доки ті не відкололися й не утворили Братство Дефіас.",al={"хто зробив звіт про дефіас","автор звіту"}},{q="Чому цей звіт треба віднести до Фортеці Стормвінда?",a="Барос Алекстон вважає, що шукач пригод, який розкрив змову, заслуговує на честь особисто представити знахідки престолу й здобути королівське визнання за захист королівства.",al={"чому віднести звіт","доставка аудієнції в короля"}},{q="Чи читає звіт Король Варіан?",a="Ні. Коли ви прибуваєте до Фортеці Стормвінда, Короля Варіана Рінна немає — кажуть, він вирушив у таємну дипломатичну подорож. Документ замість нього приймають королівський двір і регенти.",al={"чи читає король звіт","аудієнція варіана рінна"}}},fp="32,323,25.528.0,21.473.1,45.199.0,22.174.0,43.192.0,33.177.0"}
P.entries["item:resonite-crystal"] = {n="Резонітовий Кристал",s="Резонітові Кристали — рідкісні мінерали, які видобувають кобольди в Печері Кам'яного Зсуву в Горах Кам'яного Кігтя. Їхні гарячкові розкопки стривожили Мор'роґала з Притулку Сонячної Скелі.",h="Резонітові Кристали — рідкісні мінерали, які видобувають кобольди в Печері Кам'яного Зсуву в Горах Кам'яного...",kw={"резонітовий кристал","кобольди","печера кам'яного зсуву","гори кам'яного кігтя","мор'роґал","земляни"},ang={["class:Shaman"]="Для шаманів Резонітові Кристали мають тривожний відгук: вони впізнають дрімотну первісну магію землі, яку лишили по собі творіння титанів, давно поховані під горами.",["profession:Mining"]="На відміну від звичайних мідних чи олов'яних жил, резоніт — надзвичайно зосереджене мінеральне утворення, і щоб його видобути, треба пробитися повз агресивних кобольдів у найглибші підземні шари."},sec={{t="Давній резонанс",b="Заховані в глибинах Яру Кам'яного Зсуву, Резонітові Кристали раптом стали осередком гарячкових кобольдячих розкопок. Звичайні печерні копачі шукають буденну руду чи блискучі дрібнички, тож одержимість кобольдів саме цими утвореннями одразу стривожила шаманів Притулку Сонячної Скелі. Якщо придивитися, камені гудуть тонким магічним відгуком, пов'язаним із первісним творенням світу. Мор'роґал розпізнав у цій слабкій енергії сліди магії землян — ознаку того, що кобольди прорилися в давній шар, створений титанами."},{t="Черпаючи з надр",b="Знахідка резоніту підтверджує тривожні звістки для Орди в Горах Кам'яного Кігтя: кобольди-копачі прорилися досить глибоко, щоб потурбувати давніх землян. Землян створили самі титани, щоб висікати й ліпити підвалини світу, тож залишкова магія вперто чіпляється за навколишню скелю. Збираючи ці кристали, агенти Орди сподіваються збагнути гарячкові задуми кобольдів і обернути силу зачарованого каменю проти тих сплячих сил, які потурбували внизу."}},faq={{q="Де знайти Резонітові Кристали?",a="Резонітові Кристали знаходять у Печері Кам'яного Зсуву — глибокій печері в Яру Кам'яного Зсуву на південному сході Гір Кам'яного Кігтя.",al={"місце резоніту","де взяти резоніт","фарм резонітових кристалів"}},{q="Навіщо кобольди видобувають Резонітові Кристали?",a="Кобольди гарячково видобувають рідкісні кристали, але Мор'роґал поки не знає навіщо. Щоб зрозуміти, що вони затіяли, він просить принести зразки й дослідити глибини печери.",al={"навіщо кобольди видобувають резоніт","змова кобольдів із кристалами","кобольди кам'яного зсуву"}},{q="Яка сила в Резонітовому Кристалі?",a="Мор'роґал підозрює, що кристали пов'язані з чимось тривожним під горами. Їхню магічну природу розпізнають, коли до нього дійдуть зразки й вісті з печери.",al={"магія резонітового кристала","що таке резоніт","чи резоніт магічний"}},{q="Хто вивчає ці кристали?",a="Мор'роґал, таурен із Притулку Сонячної Скелі в Горах Кам'яного Кігтя, досліджує кристали, щоб зрозуміти раптовий сплеск діяльності кобольдів і знайти спосіб протидіяти злу, яке відкопали.",al={"хто хоче резоніт","кристали мор'роґала","відпочинок сонячної скелі резоніт"}},{q="Хто такі земляни, згадані у зв'язку з кристалом?",a="Земляни — істоти, яких, як кажуть, створили титани, щоб формувати землю. Їхній можливий зв'язок із резонітом з'ясовують під час завдання Мор'роґала.",al={"хто такі земляни","зв'язок землян із титаном"}}},fp="16,193,17.587.1,17.518.1,34.159.0,45.182.0,44.176.0,31.214.0,60.164.0"}
P.entries["item:restabilization-cog"] = {n="Шестерня Рестабілізації",s="Шестерні Рестабілізації — точні механічні компоненти, зняті з прокажених гномів, що блукають біля опромінених руїн Гномреґану. У Хараносі гномським майстрам потрібні ці цілі деталі, щоб зібрати Рекомбобулятор — амбітну машину, покликану повернути назад мутацію прокажених.",h="Шестерні Рестабілізації — точні механічні компоненти, зняті з прокажених гномів, що блукають біля опромінених...",kw={"шестерня рестабілізації","рекомбобулятор","прокажені гноми","оззі тоґлвольт","раззл спрайспрокет","гномреґан","харанос"},ang={["profession:Engineering"]="Точні допуски Шестерень Рестабілізації — зразок класичного гномського дизайну: вони витримують нестабільне тертя й урівноважують тендітні механічні збірки, як-от Рекомбобулятор.",["race:Gnome"]="Для гномів-вигнанців у Дун Мороґу добування цих компонентів — скорботний обов'язок: знімати механізми зі спотворених братів у відчайдушній надії зібрати ліки для полеглих Гномреґану."},sec={{t="Деталі для ліків",b="Коли Гномреґан затопили радіацією в катастрофічній спробі знищити трогів-загарбників, незліченних гномів обернуло на хворих, ворожих прокажених гномів. Попри божевілля, ці уражені вигнанці досі носять на собі складну гномську механіку та придатне до використання кріплення. Майстри Оззі Тоґлвольт і Раззл Спрайспрокет вірять, що жахливе перетворення можна систематично скасувати. Щоб довершити прототип Рекомбобуляційного Пристрою, вони покладаються на шукачів пригод, які добудуть життєво важливі деталі просто з уражених біля воріт Гномреґану — зокрема цілі Шестерні Рестабілізації, щоб урівноважити внутрішні системи згоряння машини."}},faq={{q="Для чого потрібна Шестерня Рестабілізації?",a="Шестерні Рестабілізації потрібні майстрові Раззлу Спрайспрокету в Хараносі. Разом із Гіромеханічними Деталями вони — важливі конструктивні частини Рекомбобулятора, експериментального винаходу, що має вилікувати опромінених прокажених гномів.",al={"призначення шестерні","що робить шестерня рестабілізації","навіщо збирати шестерні"}},{q="Де знайти ці шестерні?",a="Їх носять збожеволілі прокажені гноми та їхній навіжений ватажок Ґібблвілт, що блукають біля зовнішніх брам і в траншеях перед Гномреґаном на заході Дун Мороґа.",al={"місце шестерень рестабілізації","хто дропає шестерні","де фармити шестерні"}},{q="Чи справді Рекомбобулятор може вилікувати прокажених гномів?",a="Раззл Спрайспрокет і Оззі Тоґлвольт певні, що правильно налаштований механізм здатен звернути мутацію. Проте гномська інженерія славиться непередбачуваністю, і чи зможе Рекомбобулятор справді відновити розум і тіла їхнього народу — досі незавершена й неперевірена справа.",al={"чи працює рекомбобулятор","чи є ліки для прокажених гномів"}}},fp="19,289,21.623.0,39.247.0,30.166.0,54.289.0"}
P.entries["item:robo-mechanical-guts"] = {n="Робомеханічні нутрощі",s="Робомеханічні нутрощі — придатні до використання шестерні, дроти й нутрощі машин, вийняті з несправних конструктів, що блукають руїнами Гномреґана. Гномським інженерам у Стормвінді потрібні саме ці деталі, щоб полагодити важкі прохідницькі машини, які мають допомогти відвоювати Гномреґан у Дун Мороґу.",h="Робомеханічні нутрощі — придатні до використання шестерні, дроти й нутрощі машин, вийняті з несправних...",kw={"робомеханічні нутрощі","деталі","шоні","екскаваторатори","гномреґан","роботи"},ang={["profession:Engineering"]="Кожен врятований клубок дротів і гірошестерня нагадують про вершину гномської автоматики, яка тепер, на лихо, здичавіла від радіації й самотності.",["race:Gnome"]="Розбирати на частини годинникових вартових, що збунтувалися у вашому втраченому домі, — гірко й солодко водночас, але їхні нутрощі дають справжні деталі, потрібні, щоб повернути Гномреґан."},sec={{t="Запчастини для флоту",b="Коли Великий Тінкер Ґелбін Меккаторк і вцілілі гноми покинули Гномреґан, усередині лишилися тисячі автоматичних механізмів, годинникових вартових і промислових роботів. Після радіаційної катастрофи ці машини й далі самі собою блукають коридорами. У Стормвінді майстриня Шоні збирає флот гіробуроматичних екскаватораторів, щоб пробитися крізь оборону Гномреґана й відвоювати втрачене місто. Не маючи свіжої сировини, вона доручає сміливим шукачам пригод вирушити в заражені зали Гномреґана й вирізати з роботів справні нутрощі — пружини, дроти й гіродеталі, — щоб переобладнати копальні машини."}},faq={{q="Для чого потрібні Робомеханічні нутрощі?",a="Їх збирає Шоні в Стормвінді, щоб полагодити цілий флот гіробуромагічних копачів — особливих прохідницьких машин, що мають підтримати визволення Гномреґана в Дун Мороґу.",al={"для чого нутрощі роботів","використання робомеханічних нутрощів","навіщо збирати механічні нутрощі"}},{q="Де знайти ці деталі?",a="Їх можна зібрати з різних ворожих механічних автоматів, роботів і заражених потвор, що блукають і околицями, і глибинами Гномреґана.",al={"де взяти робомеханічні нутрощі","місце дропу нутрощів","деталі роботів гномереґану"}},{q="Хто така Шоні й навіщо їй стільки деталей?",a="Шоні — честолюбна гномська інженерка з Дворфійського Кварталу Стормвінда. Їй доручено підготувати цілий підрозділ підземних прохідницьких машин — майже чотириста штук, — щоб пробитися в захоплені руїни Гномреґана.",al={"хто така шоні","шоні стормвінд","флот ґіродрилматичних екскаваторів"}}},fp="20,315,21.658.0,39.198.0,35.160.0,49.245.0"}
P.entries["item:rocket-car-parts"] = {n="Деталі Ракетного Авто",s="Деталі ракетного авто — розкидані, покручені металеві рештки швидкісних зіткнень у Мерехтливих Низинах, що в Тисячі Голок. Їх безупинно «постачають» безрозсудні гонщики-гноми й гобліни, які женуть експериментальні болиди понад межі можливого, а підбирають ці уламки спритники, що вміють обернути аварії на трасі на швидкий заробіток.",h="Деталі ракетного авто — розкидані, покручені металеві рештки швидкісних зіткнень у Мерехтливих Низинах, що в...",kw={"деталі ракетного авто","кравел колбірд","перегони міражу","мерехтливі низини","уламки","гонщики"},ang={["profession:Engineering"]="Обгорілі шестерні й поскручувані вихлопні вузли, що всіяли солончаки, — свідчення хаотичних крайнощів гномської та гоблінської інженерних філософій.",["race:Dwarf"]="Гномам і гоблінам важать лише самі перегони, а заповзятливі дворфи на кшталт Кравела Колбірда доводять, що справжній зиск — у збиранні уламків, які лишаються після них."},sec={{t="Швидкість, аварії та спритна торгівля",b="Перегони Міражу в Мерехтливих Низинах — арена нескінченного вибухового суперництва гоблінської та гномської інженерії. У гонитві за неперевершеною швидкістю на суходолі гонщики раз у раз зазнають катастрофічних поломок, вибухових осічок і швидкісних аварій, що розкидають метал по всіх солончаках. Ці викинуті рештки — від погнутих циліндрів і обгорілих шестерень до зім'ятої бляхи — недовго лежать без діла. Збирачі брухту й торговці, а надто спритний дворф Кравел Колбірд, наймають мандрівних шукачів пригод прочісувати сліпучо-білі простори й збирати уламки. А що обидві гоночні команди повсякчас відчайдушно шукають запчастин, аби зліпити наступний прототип, зібраний брухт легко перепродати тим самим командам, які його й розбили."}},faq={{q="Звідки всі ці деталі ракетних авто?",a="Це наслідки безперервних аварій, вибухів і поломок на Перегонах Міражу. Гномські й гоблінські пілоти раз у раз ганяють нестійкі експериментальні ракетні машини соляними рівнинами Тисячі Голок, доки ті не розлітаються на друзки.",al={"чому на соляних рівнинах деталі","походження брухту ракетних авто","звідки деталі"}},{q="Хто скуповує цей брухт?",a="Торговці на кшталт дворфа Кравела Колбірда скуповують уламки в мандрівників і перепродують гвинтики, обшивку й пристрої назад гномам і гоблінам, яким завжди бракує запчастин, щоб лагодити й удосконалювати свої гоночні машини.",al={"хто хоче деталі ракетних авто","деталі кравела коулберда","хто скуповує уламки"}},{q="Чи небезпечно збирати ці деталі?",a="Самі уламки — нешкідливий брухт, хоча часом на них трапляються моторошні сліди жорстоких аварій, як-от відірвані кінцівки, затиснуті в металі. Головна небезпека — ворожі звірі соляних рівнин: василіски, обпалені скорпіди й хижі солончакові грифи, що никають довкола полів уламків.",al={"чи безпечно збирати деталі","небезпеки під час збору деталей"}},{q="Чи турбує гномів і гоблінів, що деталі з розбитих машин?",a="Анітрохи. Ні гноми, ні гобліни не гидують уживаними матеріалами. Їм важливо лише здобути придатні пристрої, шестерні й металеву обшивку, щоб зібрати щось достатньо швидке й обігнати суперника на трасі.",al={"чи гонщикам байдуже на уламки","чому гобліни використовують брухт"}}},fp="16,342,34.812.0,46.251.0,31.246.0,36.309.0,68.237.0"}
P.entries["item:rod-of-channeling"] = {n="Жезл Каналізування",s="Жезл каналізування — магічний фокус, який носять заклиначі клану Драконячої Пащі в Багнокраї. Чорнокнижники, що прагнуть опанувати виклик мисливця Скверни, мусять зібрати кілька таких жезлів, щоб учні Страгада Фарсана в Раджеті могли надійно закріпити обрядове коло.",h="Жезл каналізування — магічний фокус, який носять заклиначі клану Драконячої Пащі в Багнокраї.",kw={"жезл каналізування","драконяча паща","багнокрай","страгад фарсан","мисливець скверни","фоліант кабали"},ang={["class:Warlock"]="Здобути три жезли каналізування — важлива віха у випробуваннях Фоліанта Кабали: вони дають вам стримувальне коло, потрібне, щоб підкорити свого першого мисливця Скверни."},sec={{t="Знаряддя підкорення",b="Коли чорнокнижник хоче підкорити такого мінливого хижака, як мисливець Скверни, самої сили волі рідко вистачає. Страгадові Фарсану потрібні три однакові жезли, щоб його учні могли злагоджено спрямовувати магію й утримувати коло виклику, поки сам заклинач проводить обряд підкорення. Темні заклиначі клану Драконячої Пащі — серед них охоронці кісток і охоронці тіней, що никають Табором Анґерфанґ і довколишніми руїнами Багнокраю, — носять ці знаряддя для власних лиховісних чарів. Хоч жезли зазвичай потерті й пощерблені в боях, вони лишаються могутніми фокусами, здатними спрямовувати хаотичну енергію Нижнього Світу."}},faq={{q="Для чого потрібен Жезл Каналізування?",a="Жезли віддають чорнокнижникові Страгаду Фарсану над Раджетом. Його послідовники спрямовують ними силу й утримують магічне коло, потрібне, щоб викликати й прив'язати ворожого мисливця Скверни.",al={"що таке жезл каналізування","призначення жезла каналізування","навіщо мені жезл каналізування"}},{q="Де знайти Жезли Каналізування?",a="Їх тримають заклиначі клану Драконячої Пащі — особливо вартові кісток і вартові тіней, — що засіли в Багнокраї, зокрема довкола Табору Анґерфанґ.",al={"де взяти жезли каналізування","хто дропає жезл каналізування","місце жезла каналізування"}},{q="Навіщо Страгадові три жезли?",a="Страгад залучає до обряду виклику мисливця Скверни кількох послідовників. Кожному помічникові потрібен свій осередок, щоб безпечно тримати канал, поки чорнокнижник приборкує звіра.",al={"чому три жезли","чому 3 жезли каналізування"}},{q="Навіщо Драконячій Пащі ці жезли?",a="Клан Драконячої Пащі практикує темне шаманство й тіньове чаклунство — рештки давньої Орди. Їхні вартові кісток і вартові тіней спрямовують жезлами прокльони, некромантію й магію тіні в безперервних війнах за землі Багнокраю.",al={"жезли драконячої пащі","чому вони у драконячої пащі"}}},fp="17,268,22.603.0,39.175.0,38.165.0,33.188.0,39.236.0"}
P.entries["item:rolf-and-malakai-s-medallions"] = {n="Медальйони Рольфа і Малакая",s="Медальйони Рольфа і Малакая — службові знаки двох вартових Стормвінда, що зникли, патрулюючи східний Ліс Елвінн. Позначені гербом королівства, вони потрібні Вартовому Томасу, щоб дізнатися долю зниклих товаришів.",h="Медальйони Рольфа і Малакая — службові знаки двох вартових Стормвінда, що зникли, патрулюючи східний Ліс...",kw={"медальйони","рольф","малакай","вартовий томас","мурлоки","варта"},ang={["faction:Alliance"]="Медальйони — тверезе нагадування про те, що навіть у серці Альянсу тутешні вартові стикаються зі смертельною небезпекою, охороняючи сільські торгові шляхи.",["race:Human"]="Для людей Елвінну ці знаки означають утрачених синів і захисників, чия смерть показує вразливість королівства, поки військо зайняте деінде."},sec={{t="Гірке підтвердження",b="Коли вартові Рольф і Малакай зникли на берегах річки у східному Лісі Елвінн, їхній командир, Вартовий Томас, боявся найгіршого. Знайдені особисті медальйони вартових — незаперечний доказ їхньої загибелі від рук мурлоків, що насуваються. Для гарнізону Стормвінда ці знаки — не просто дрібнички: вони уособлюють полеглих солдатів, які тримали оборону проти зростаючих загроз дикої природи, коли військо королівства було розтягнуте до відчаю."},{t="Знаки служби",b="Як і багато хто з міської варти Стормвінда та сільських патрулів, люди-вартові носять розпізнавальні медальйони, що засвідчують їхню вірність і владу під короною. Повернення цих знаків Вартовому Томасу дає йому змогу офіційно звітувати про зниклих людей, записати їхню жертву в польовому рапорті й здійняти тривогу щодо агресивних племен мурлоків, що оселяються біля торгових шляхів."}},faq={{q="Що таке Медальйони Рольфа і Малакая?",a="Це офіційні службові жетони вартових Рольфа й Малакая — двох стормвіндських вартових на сході Лісу Елвінн, яких підстерегли й убили мурлоки.",al={"що таке медальйони рольфа і малакая","медальйон рольфа","медальйон малакая"}},{q="Кому належать ці медальйони?",a="Вони належали вартовим Рольфу й Малакаю — товаришам по службі під орудою Вартового Томаса, які пильнували річку й дороги між Ґолдширом і Лісозаготівельним Табором Східної Долини.",al={"хто були рольф і малакай","чиї медальйони"}},{q="Кому віднести ці медальйони?",a="Віднесіть їх Вартовому Томасу, що стоїть на варті біля східного мосту при дорозі між Ґолдширом і Лісозаготівельним Табором Східної Долини.",al={"хто хоче медальйони","куди здати медальйони","здати медальйон"}},{q="Чому ці медальйони важливі для Вартового Томаса?",a="Вартовий Томас послав обох у дозор і боявся, що їх спіткала лиха доля. Медальйони підтверджують їхню загибель, і він може засвідчити їхню жертву та попередити Стормвінд про дедалі більшу загрозу мурлоків.",al={"чому томасу потрібні медальйони","реакція вартового томаса"}}},fp="29,250,19.485.0,17.383.0,39.184.1,34.170.0,39.134.0,51.214.1"}
P.entries["item:rot-blossom"] = {n="Гнилоцвіт",s="Гнилоцвіт — бридка мертвотна рослина, що росте серед осквернених могил Сутінколісся. Живлений отруєним ґрунтом і рештками нежиті, він цінується за потужні й нездорові алхімічні властивості.",h="Гнилоцвіт — бридка мертвотна рослина, що росте серед осквернених могил Сутінколісся.",kw={"гнилоцвіт","сутінколісся","цвинтар тихих садів","кістяки","зомбі-сік","травництво"},ang={["faction:Alliance"]="Похід у проклятий ґрунт по ці похмурі квіти — водночас і послуга Нічній Варті: так ви допомагаєте очистити околиці Даркшира від ненажерливих кістяків.",["profession:Herbalism"]="На відміну від звичайних трав, що ростуть під сонцем і дощем, гнилоцвіт — бридка ботанічна аномалія, яку живлять лише мертвотна гниль і цвинтарна земля, тож це похмурий приклад зіпсованої флори."},sec={{t="Рослини склепів",b="Протиприродна скверна Сутінколісся породжує дивну й моторошну рослинність, і найтривожніша з неї — Гнилоцвіт. Укорінені в оскверненій землі таких цвинтарів, як Цвинтар Тихих Садів, ці похмурі квіти буяють поруч зі смертю. Місцеві чутки кажуть, що вони можуть пускати коріння навіть у розтрощених черепах ходячих мерців — особливо кістяних жахіть і кістяних виродків, що нишпорять серед курганів. Для мешканців Даркшира збирати гнилоцвіт — і похмура повинність, і небезпечна необхідність: потривожити ґрунт, у якому він росте, означає кинути виклик неспокійним мерцям."},{t="Моторошний інгредієнт",b="Попри відразливу природу, гнилоцвіт має особливе призначення в місцевих варивах. У його квітах є темні сутності, без яких не зварити Зомбі-Сік — бридкий трунок, пов'язаний із моторошними способами виживання в Сутінколіссі. Ті, кого посилають по квіти, часто мимохіть допомагають Нічній Варті, бо заодно винищують неспокійні кістяки, що блукають проклятими цвинтарями."}},faq={{q="Де знайти Гнилоцвіт?",a="Гнилоцвіт росте на зіпсованій землі цвинтарів Сутінколісся, особливо на Цвинтарі Тихих Садів, і, як відомо, проростає з решток скелетів-потвор.",al={"де ростуть гнилоцвіти","місце гнилоцвіту","знайти гнилоцвіт"}},{q="Для чого потрібен Гнилоцвіт?",a="Це головний складник, з якого місцеві броварі й алхіміки гонять міцний мерзенний трунок — Зомбі-Сік.",al={"використання гнилоцвіту","навіщо збирати гнилоцвіт","чим корисний гнилоцвіт"}},{q="Чому ці квіти ростуть у скелетах?",a="Темна магія, що засіла в Сутінколіссі, заражає і землю, і неспокійних мерців. Гнилоцвіт живиться просто некротичною скверною й тліном, тож проростає в черепах і ребрах блукаючих скелетів.",al={"гнилоцвіти в черепах","жахливі квіти скелетів","скелети гнилоцвіт"}},{q="Як збирання Гнилоцвіту допомагає Даркширу?",a="Кожен, хто йде в місця на кшталт Тихих Садів по квіти, неминуче мусить рубати скелетів-жахів і потвор, що заполонили ці землі, — а це дає вкрай потрібне полегшення Алтеї Ебонлок і змученій Нічній Варті.",al={"алтея ебонлок гнилоцвіт","нічна варта гнилоцвіт","допомога даркширу"}}},fp="11,212,19.561.0,21.398.0,32.201.0,31.119.0,40.215.0,47.242.0"}
P.entries["item:rot-hide-ichor"] = {n="Сукровиця Гнилошкірого",s="Сукровиця Гнилошкірого — мерзенна рідина, яку добувають з гнилошкірих гнолів-нежиті, що заполонили Острів Фенріс на Озері Лордамер. Аптекар Ренферрел збирає зразки цієї речовини в Гробниці, щоб з'ясувати джерело зіпсуття гнолів і знайти, як їм протистояти.",h="Сукровиця Гнилошкірого — мерзенна рідина, яку добувають з гнилошкірих гнолів-нежиті, що заполонили Острів...",kw={"сукровиця гнилошкірого","гнилошкірі гноли","острів фенріс","аптекар ренферрел","озеро лордамер","аптекарі"},ang={["race:Undead"]="Для Відступників дослідження сукровиці — важлива військова розвідка, щоб убезпечити східний фланг Срібнолісся й поглибити владу Королівського Аптекарського Товариства над наукою про чуму."},sec={{t="Чума в крові",b="Гнилошкірі гноли з Острова Фенріс — не звичайні дикі звірі: вони помітно розкладаються й викривлені неприродною скверною. Замість звичайної крові їхніми жилами тече отруйна сукровиця, що підтримує їхню оживлену плоть. Королівське Аптекарське Товариство підозрює, що ця рідина ховає таємницю того, як зграю було зіпсовано і хто командує нею з зруйнованої фортеці на Острові Фенріс."},{t="Дослідження аптекарів",b="Аптекар Ренферрел збирає флакони з цією сукровицею, щоб дослідити її властивості в Гробниці. Виокремивши хімічні й магічні складники, що живлять гнолів, Відступники сподіваються знайти їхні слабкі місця, перш ніж кидати війська в повномасштабний наступ через Озеро Лордамер."}},faq={{q="Звідки береться Сукровиця Гнилошкірого?",a="Її збирають із тіл гнилошкірих гнолів, що живуть по всьому Острову Фенріс в Озері Лордамер, на схід від материкового Срібнолісся.",al={"де взяти сукровицю гнилошкірого","як знайти сукровицю гнилошкірого","місце сукровиці гнола"}},{q="Навіщо Аптекареві Ренферрелу ця сукровиця?",a="Ренферрел хоче розібрати дивну рідину, щоб з'ясувати, що зіпсувало гнолів, і знайти тілесні чи алхімічні слабкості, якими Відступники зможуть скористатися, перш ніж напасти на острів.",al={"навіщо ренферрелу сукровиця","причина завдання ренферрела","призначення сукровиці"}},{q="Чи гнилошкірі гноли — Погибель?",a="Це гноли-нежить, спотворені чумою, але Відступники ще з'ясовують, хто чи що саме їх створило й керує ними на Острові Фенріс.",al={"чи гнилошкірі це погибель","хто керує гнилошкірими","що за гнилошкірі гноли"}},{q="Чи в усіх гнолів є ця сукровиця?",a="Ні. Ця рідина притаманна лише зграї гнилошкірих, чию плоть і кров зіпсувала мерзенна некромантська моровиця.",al={"чи всі гноли дропають сукровицю","звичайна кров гнола"}}},fp="14,276,21.387.0,19.279.0,36.146.0,46.187.0,32.161.0,30.116.0"}
P.entries["item:rough-quartz"] = {n="Грубий Кварц",s="Грубий Кварц — скромний стихійний камінь, який Малий Прояв Землі дарує шаманам-новачкам. Хоч він малий і необроблений, саме він стає духовним осердям першого Тотема Землі шамана.",h="Грубий Кварц — скромний стихійний камінь, який Малий Прояв Землі дарує шаманам-новачкам.",kw={"грубий кварц","кварц","тотем землі","шаман","прояв землі","ерткаллер"},ang={["class:Shaman"]="Грубий Кварц — ваше найперше єднання зі стихією землі, що закорінює ваші закляття й позначає ваш шлях справжнього провідника духів."},sec={{t="Серце Тотема Землі",b="Невтаємниченому оку грубий кварц здається звичайним пустельним камінцем. Та для шамана, що єднається з духами в Дуроторі чи Малгорі, це дар стихій, піднесений самим Малим Проявом Землі. Камінь утілює витривалість, терпіння й непохитну силу. Коли його приносять старійшині на кшталт Канаґи Ерткаллера в Долині Випробувань, кварц вправляють у різьблене дерево Тотема Землі, і він стає духовним осердям, що єднає молодого шамана з живим ґрунтом Азероту."}},faq={{q="Для чого Грубий Кварц?",a="Він доводить, що новачок-шаман поспілкувався з духом стихії землі. Старший шаман робить цей камінчик духовним осердям, коли вирізьблює перший Тотем Землі новачка.",al={"що робить грубий кварц","використання грубого кварцу","навіщо мені грубий кварц"}},{q="Хто дає Грубий Кварц?",a="Його дає Малий Прояв Землі, коли ви поспілкуєтеся з духом під час обряду «Поклик Землі» в Дуротарі чи Малгорі.",al={"де взяти грубий кварц","хто дропає грубий кварц"}},{q="Кому віднести цей камінь у Дуротарі?",a="Принесіть його Канаґі Ерткаллер, наставниці шаманів у Долині Випробувань, — вона зробить із нього ваш Тотем Землі.",al={"куди здати грубий кварц","здати грубий кварц","хто бере грубий кварц"}},{q="Чи використовують цей кварц для чогось іще?",a="Ні. Це суто священний обрядовий предмет, призначений лише для виготовлення Тотема Землі, і в звичайній торгівлі він ні до чого.",al={"чи можна продати грубий кварц","чи кварц для ремесла"}}},fp="12,211,24.543.0,40.192.0,31.136.0,40.127.0,38.114.0"}
P.entries["item:rumbleshot-s-ammo"] = {n="Боєприпаси Рамблшота",s="Боєприпаси Рамблшота — загублений ящик набоїв для зброяра Геґнара Рамблшота в Дун Мороґу. Важкий ящик, покинутий переляканим кур'єром, що втік від голодних вендиґо, лежить у снігу біля Сивого Лігва.",h="Боєприпаси Рамблшота — загублений ящик набоїв для зброяра Геґнара Рамблшота в Дун Мороґу.",kw={"боєприпаси","геґнар рамблшот","вендиґо","сиве лігво","зброяр","лослор","дун мороґ"},ang={["class:Hunter"]="Для стрільців, що блукають лютим холодом Дун Мороґу, сухий порох і повні запаси шроту в Геґнара означають стабільне постачання набоїв для дворфійської вогнепальної зброї.",["profession:Engineering"]="Дворфійські інженери й майстри значною мірою залежать від постійного потоку шроту й пороху, щоб випробовувати власну вогнепальну та експериментальну зброю."},sec={{t="Застрягла партія",b="Геґнар Рамблшот тримає придорожню збройну крамницю на гірській стежці, що спускається від Перевалу Холодного Кряжа до Анвілмара. Стрільці Айронфорджа, горяни й дворфійські мінометні команди невпинно вправляються на засніжених висотах, тож його запаси згоряють майже так само швидко, як спалахує порох. Цю партію шроту відправив Лослор із Хараноса, але до полиць вона не дісталася. Кур'єр, якому доручили її перевезти, розбив табір надто близько до хижих вендиґо Сивого Лігва, запанікував під час нападу й утік, рятуючи життя, покинувши важкий ящик із припасами просто посеред мисливських угідь звірів."}},faq={{q="Хто такий Геґнар Рамблшот?",a="Геґнар Рамблшот — дворф-зброяр, що тримає крамницю при дорозі до Анвілмара. Він обслуговує місцевих стрільців, мисливців і військових рушничників, які швидко витрачають набої на вправах серед скель Дун Мороґа.",al={"рамблшот","хто такий геґнар","продавець зброї"}},{q="Як загубився ящик із набоями?",a="Кур'єр, якого послали з ящиком, необачно отаборився біля входу до Сивого Лігва. Коли ревниві до своєї території вендиґо з лігва напали на його табір, переляканий кур'єр утік, покинувши важкий ящик у снігу.",al={"чому загубили набої","що сталося з набоями","набої кур'єра"}},{q="Де Сиве Лігво?",a="Сиве Лігво — система печер у горах на південний захід від Хараноса. Це сумнозвісне лігво лютих вендиґо Дун Мороґа, через що довколишні схили небезпечні для самотніх мандрівників.",al={"місце сивого лігва","де печера вендіго"}}},fp="17,229,19.631.0,25.224.0,32.242.0,26.212.0"}
P.entries["item:rune-inscribed-parchment"] = {n="Пергамент з Рунними Письменами",s="Письмове послання, яке отримують майбутні орки-шамани в Долині Випробувань. Написане наставником Шікріком і передане Ґорнеком, воно кличе посвячуваних прийняти роль духовних провідників і посередників духів стихій.",h="Письмове послання, яке отримують майбутні орки-шамани в Долині Випробувань.",kw={"пергамент","руни","шаман","шікрік","ґорнек","долина випробувань","предки"},ang={["class:Shaman"]="Ця рунна записка — ваш найперший крок на шляху стихій, що віддає вас під науку Шікріка вчитися шанування предків і влади над стихіями.",["race:Orc"]="Відродження шаманської традиції — осердя нової Орди, і цей пергамент утілює тяглість мудрості предків у Дуроторі."},sec={{t="Поклик до духів",b="У випаленому сонцем каньйоні Долини Випробувань нові орки-шамани починають навчання під пильним оком досвідчених наглядачів. Виконуючи перші випробування для Ґорнека, посвячуваний отримує цей укритий рунами документ. Надісланий самим Шікріком, тутешнім наставником шаманів, пергамент — офіційний виклик до глибших таємниць єднання зі стихіями. Орча культура бачить у шамані не просто бойового заклинача, а неодмінного посередника між живими й предками. Цей короткий припис позначає перехід від простої грубої сили до дисциплінованого шляху шанування предків."}},faq={{q="Що таке Пергамент з Рунними Письменами?",a="Це рукописне послання, яке Ґорнек вручає новачкам — шаманам-оркам у Долині Випробувань. Воно велить з'явитися до наставника шаманів Шікріка, щоб почати справжнє навчання.",al={"пергамент з рунами","що це за річ","пергамент шамана"}},{q="Хто написав пергамент?",a="Пергамент написав Шікрік, наставник шаманів у Долині Випробувань, що хоче навчати молодих новачків шляхів стихій і духів предків.",al={"хто надіслав пергамент","автор пергаменту"}},{q="Чому шаманів вважають обраними серед орків?",a="Шамани-орки — духовні провідники й посередники між народом і предками: вони слухають духів стихій, щоб вести свій народ. Шікрік нагадує учням, що їхній обов'язок — і зцілювати союзників, і обрушувати на ворогів лютий гнів стихій.",al={"чому бути шаманом","роль шамана орків"}}},fp="24,234,24.631.0,37.182.0,24.181.0,49.263.0"}
P.entries["item:rune-inscribed-pendant"] = {n="Амулет із Рунами",s="Амулет із Рунами — магічна дрібничка, знайдена у вантажах із припасами з Даларана, що мали йти до Амбермілла. Кірін-Тор цінує такі амулети, бо вони правлять за провідники для могутньої чарівної енергії.",h="Амулет із Рунами — магічна дрібничка, знайдена у вантажах із припасами з Даларана, що мали йти до Амбермілла.",kw={"амулет із рунами","даларан","кірін-тор","амбермілл","далар донвівер","жрець тіні аллістер"},ang={["class:Mage"]="Маги одразу впізнають роботу Кірін-Тору: руни на амулеті мають урівноважувати нестійкі потоки, коли сплітають чари найвищого порядку.",["race:Undead"]="Для Відступників, що стережуть Срібнолісся, перехоплені даларанські фокуси на кшталт цього амулета — важливі відомості про людський опір, що збирається за мурами Амбермілла."},sec={{t="Реліквія Кірін-Тору",b="Цей амулет, знайдений серед ящиків з картографічним приладдям для даларанського анклаву в Амбермілл, вкритий складними чарівними написами. Високопоставлені чарівники Кірін-Тору часто користуються такими артефактами, щоб зосереджувати й посилювати свої чари. Те, що в край везуть стільки налаштованих амулетів, одразу викликає підозру Відступників у Гробниці: це знак, що готується справа неабиякої магічної сили."},{t="Ключ до задумів Амбермілла",b="Коли амулет приносять до Гробниці, Жрець Тіні Аллістер визнає загрозу укріпленої позиції даларанських чарівників, але передає реліквію Даларові Донвіверу для глибшого вивчення. Донвівер визначає амулет як важливу складову роботи магів і доходить висновку, що Кірін-Тор запасає чарівні фокуси, щоб живити чималі оборонні чи наступальні чари за межами Амбермілла."}},faq={{q="Для чого потрібен Амулет із Рунами?",a="Чарівники Кірін-Тору використовують амулет, щоб спрямовувати потужні потоки магічної енергії. Це магічний осередок для складних чарів, а не проста прикраса.",al={"що робить амулет","призначення амулета","використання амулета з рунами"}},{q="Звідки цей амулет?",a="Його перехоплюють із вантажів, що прямують до Амбермілла в Срібноліссі, де добре укріпилися рештки Кірін-Тору.",al={"де знайти амулет","походження амулета","де його знайшли"}},{q="Хто вивчає амулет у Гробниці?",a="Жрець Тіні Аллістер коротко оглядає його разом із захопленими мапами, а тоді посилає Далару Донвіверу — знавцеві таємної магії в Гробниці, що впізнає роботу Кірін-Тору.",al={"хто вивчає амулет","хто хоче амулет","амулет далара"}},{q="Чому амулет непокоїть Відступників?",a="Перевезення великої кількості амулетів для спрямовування сили свідчить, що Кірін-Тор в Амберміллі готує масштабне магічне дійство, яке загрожує владі Відступників у Срібноліссі.",al={"чому відступники турбуються","загроза амбермілла","чому амулет небезпечний"}}},fp="22,208,15.444.0,27.417.1,44.182.0,33.141.0,42.180.0,40.188.0"}
P.entries["item:rune-inscribed-tablet"] = {n="Табличка з Рунними Письменами",s="Табличка з Рунними Письменами — кам'яне послання, яке отримують молоді тролі-шамани Темного Списа в Долині Випробувань. Передана Ґорнеком, вона спрямовує здібних містиків почати офіційне єднання зі стихіями під опікою орка-наставника Шікріка.",h="Табличка з Рунними Письменами — кам'яне послання, яке отримують молоді тролі-шамани Темного Списа в Долині...",kw={"табличка","руни","шаман","шікрік","ґорнек","темний спис","стихії"},ang={["class:Shaman"]="Табличка — перший офіційний крок шамана до володіння стихіями землі, вогню, води й повітря; вона нагадує учням, що їхня сила тече від духів предків.",["race:Troll"]="Для тролів Темного Списа відгукнутися на поклик орка-наставника — означає зміцнити зв'язок і спільний духовний шлях між тролями та їхніми новими союзниками з Орди."},sec={{t="Поклик до духів",b="Вирізьблена рунами стихій, ця табличка — офіційне запрошення для тролів-шаманів-початківців, що роблять перші кроки в Дуроторі. Коли посвячуваний доводить свою вправність у Долині Випробувань, наглядач Ґорнек вручає йому камінь, надісланий тролем-шаманом Іші-йо, щоб скерувати новачка до наставника шаманів Шікріка. Для тролів Темного Списа, які мають власні глибокі духовні традиції, табличка — початок їхнього спільного шляху з орками, що єднає давню тролячу містику з відродженою шаманською спадщиною, яку обстоює Вождь Тралл."}},faq={{q="Для чого потрібна Табличка з Рунними Письменами?",a="Табличка — вступне послання, яке Ґорнек вручає молодим тролям-шаманам у Долині Випробувань. Воно велить новачкові з'явитися до Шікріка, місцевого наставника шаманів, щоб почати справжнє духовне навчання.",al={"призначення таблички","що робить табличка","використання таблички з рунами"}},{q="Хто надсилає табличку?",a="Табличку підписав Іші-йо — троль-шаман, що дав новачкові перші уроки. Він посилає його далі, до Шікріка — орка, наставника шаманів біля Лігва в Долині Випробувань, який уже знає, що учень прийде.",al={"хто написав табличку","відправник таблички","хто вирізав"}},{q="Хто отримує цю табличку?",a="Цю табличку отримують від Ґорнека лише щойно прибулі тролі-шамани Темного Спису — як перший виклик до наставника свого класу в Дуротарі.",al={"хто отримує табличку","який клас отримує табличку"}}},fp="21,253,24.578.0,43.234.0,21.237.0,25.126.0"}
P.entries["item:rune-of-nesting"] = {n="Руна Гніздування",s="Руна Гніздування — одна з чотирьох священних Реліквій Пробудження, що зберігаються в Курганному Лігві Бан'етіл на Тельдрассилі. Це неодмінна складова тонкого друїдського обряду, потрібного, щоб безпечно прикликати сплячих Друїдів Кігтя назад зі Смарагдового Сну.",h="Руна Гніздування — одна з чотирьох священних Реліквій Пробудження, що зберігаються в Курганному Лігві...",kw={"руна гніздування","реліквії пробудження","друїди кігтя","курганне лігво бан'етіл","смарагдовий сон","атрідас бермантл","скриня гніздування"},ang={["class:Druid"]="Для друїдів Руна Гніздування уособлює священні обряди Кола Кенарія й підкреслює вразливість сплячих братів, коли священні святилища зламано.",["race:NightElf"]="Споганення курганних лігв і втрата цих реліквій пробудження підкреслюють дедалі більшу скверну, що вражає звірину й фурболгів Тельдрассила."},sec={{t="Священний осередок пробудження",b="Друїди нічних ельфів поринають у глибокі циклічні сплячки в підземних курганних лігвах, щоб єднатися з природою через Смарагдовий Сон. Прокинутися з такого глибокого трансу — не просто ворухнутися: потрібен точний обряд під проводом священних знарядь. Руна Гніздування, що безпечно лежить у Скрині Гніздування глибоко в звивистих покоях Курганного Лігва Бан'етіл, закріплює цей процес. Разом із Талісманом Воронячого Пазура, Чорним Пером і Сапфіром Небес руна слугує провідником, що кличе Друїдів Кігтя назад у яву."},{t="Лихо в Бан'етілі",b="Коли споганені фурболги Вузлошкірів заполонили Курганне Лігво Бан'етіл, сплячі захисники кургану опинилися в безпосередній небезпеці. Без доступу до реліквій друїди ризикували навіки застрягти у Смарагдовому Сні, поки загарбники плюндрували їхнє святилище. Повернення Руни Гніздування та супутніх артефактів дає Атрідасу Бермантлу в Доланаарі змогу підготувати обряд, потрібний, щоб безпечно пробудити друїдів у небезпеці."}},faq={{q="Для чого потрібна Руна Гніздування?",a="Це одна з чотирьох Реліквій Пробудження, потрібних Атрідасові Бермантлу, щоб провести обряд, який безпечно пробуджує Друїдів Кігтя з глибокої сплячки в Смарагдовому Сні.",al={"що робить руна гніздування","призначення руни гніздування"}},{q="Де знайти Руну Гніздування?",a="Вона зберігається в Скрині Гніздування в підземних тунелях Курганного Лігва Бан'етіл на захід від Доланаара на Тельдрассилі.",al={"де руна гніздування","місце скрині гніздування"}},{q="Чому сплячі друїди не можуть просто прокинутися самі?",a="Сплячка в Смарагдовому Сні — тонкий стан, схожий на транс. Без священних реліквій і обряду пробудження повернутися буває неможливо: розум блукає Сном, а тіло лишається беззахисним перед небезпекою.",al={"чому друїди потребують ритуалу пробудження","чому друїди не можуть прокинутися"}},{q="Які ще реліквії потрібні разом із Руною Гніздування?",a="Для повного обряду потрібні чотири Реліквії Пробудження: Руна Гніздування, Талісман Воронячого Пазура, Чорне Перо й Сапфір Небес.",al={"інші реліквії пробудження","предмети реліквій пробудження"}}},fp="15,260,28.574.0,19.448.0,37.183.0,35.142.0,58.245.0,59.145.0"}
P.entries["item:runes-of-summoning"] = {n="Руни Прикликання",s="Руни Прикликання — обрядовий предмет, який дає наставник чорнокнижників Карендін Галґар у Магічному Кварталі Андерсіті. З їхньою допомогою в коло виклику прикликають неприборканого блукача Порожнечі, щоб молодий чорнокнижник підкорив його своїй волі.",h="Руни Прикликання — обрядовий предмет, який дає наставник чорнокнижників Карендін Галґар у Магічному Кварталі...",kw={"руни прикликання","блукач порожнечі","карендін галґар","чорнокнижник","магічний квартал","порожнеча","андерсіті"},ang={["class:Warlock"]="Чорнокнижники-Відступники застосовують руни, щоб довести свою владу над Порожнечею й перетворити хаотичну тінь на незмінно вірного слугу.",["race:Undead"]="У підземних глибинах Андерсіті Відступники переступають давні заборони й підкоряють створінь Порожнечі просто під руїнами Лордерона."},sec={{t="Підкорення в Магічному Кварталі",b="У темних закутках Магічного Кварталу Андерсіті Відступники, що опановують темні мистецтва, вчаться керувати силами Нижнього Світу. Карендін Галґар довіряє Руни Прикликання лише тим чорнокнижникам, які готові взяти під владу блукача Порожнечі. Застосувавши руни в діючому колі виклику під місцем Галґара, заклинач прориває тканину Порожнечі й витягає звідти істоту, яку треба здолати й підкорити собі на службу."}},faq={{q="Для чого потрібні Руни Прикликання?",a="Їх використовують у колі виклику в Магічному Кварталі Андерсіті, щоб витягти з Нижнього Світу в тілесний світ неприв'язаного блукача Порожнечі, — і чорнокнижник міг здолати й підкорити його.",al={"призначення рун прикликання","що роблять руни прикликання","як використати руни прикликання"}},{q="Хто дає Руни Прикликання?",a="Їх дає Карендін Галґар, наставник чорнокнижників-Відступників у Магічному Кварталі Андерсіті, на останньому етапі навчання прив'язувати блукача Порожнечі.",al={"хто дає руни прикликання","вчитель рун прикликання","руни карендіна гелґара"}},{q="Де треба активувати руни?",a="Їх треба принести до фіолетового кола виклику просто під помостом Карендіна Галґара в Магічному Кварталі.",al={"де активувати руни","місце рун прикликання","коло виклику андерсіт"}},{q="Що стається, коли сутність викликано?",a="Блукач Порожнечі одразу нападає. Чорнокнижник мусить приборкати його силою магії й зброї. Коли його переможено, сутність стає зв'язаною, і Карендін Галґар навчає закляття, щоб назавжди викликати її.",al={"що буде після використання рун","пустоходець приборкано","після виклику пустоходця"}}},fp="18,256,32.474.0,41.192.0,36.163.0,34.124.0,42.193.0"}
P.entries["item:sack-of-murloc-heads"] = {n="Мішок Голів Мурлоків",s="Мішок Голів Мурлоків — моторошна в'язка, зібрана на пляжах Передгір'я Гілсбреда. Цей доказ військових дій проти місцевих прибережних шкідників Лейтенант Фаррен Орінелль спихає на заїжджих шукачів пригод, щоб ті доставили його Маршалові Редпату в Саутшорі.",h="Мішок Голів Мурлоків — моторошна в'язка, зібрана на пляжах Передгір'я Гілсбреда.",kw={"мішок голів мурлоків","мурлоки","фаррен орінелль","маршал редпат","саутшор","передгір'я гілсбреда"},ang={["faction:Alliance"]="Ця доставка показує розхитане постачання й непоказні щоденні клопоти захисників Саутшора, що тримають купи північний осередок Альянсу."},sec={{t="Бюрократія й прибережні шкідники",b="Саутшор перебуває в постійній облозі розбійників Синдикату, загонів Відступників і диких мурлоків, що юрмляться на узбережжі. Щоб здобути гроші й прихильність міського начальства, місцеві офіцери мусять доводити, що прибережні загрози справді знищують. Лейтенант Фаррен Орінелль збирає докази у вигляді відтятих голів, але огидність вантажу — і власна гидливість — змушують його віддавати мокрий мішок мандрівникам, а не нести моторошний доказ Маршалові Редпату самому."}},faq={{q="Що таке Мішок Голів Мурлоків?",a="Це мішок із мішковини, повний відтятих голів мурлоків, зібраних на західних пляжах Гілсбреда. Він — речовий доказ того, що узбережжя приборкано, для командира гарнізону Саутшора.",al={"мішок голів","мішок мурлоків","що це за річ"}},{q="Чому Лейтенант Фаррен не віднесе його сам?",a="Фаррен вважає огидним нести смердючий мішок із гнилими головами риболюдів. Не бажаючи бруднити однострій і руки, він перекладає цю неприємну справу на поступливого шукача пригод, і той несе мішок через увесь Саутшор.",al={"чому фаррен змушує нести","відмовка фаррена","лінивий фаррен"}},{q="Хто отримує мішок?",a="Мішок доставляють Маршалові Редпату — командирові оборони Саутшора, що оцінює безпеку міста й вимагає відчутних доказів оборонних зусиль.",al={"хто отримує голови","куди нести","здати маршалу редпату"}},{q="Чому Саутшор вимагає голів мурлоків як доказу?",a="Мурлоки раз у раз нападають на узбережжя й загрожують гавані. Офіцери мають засвідчувати, що дозори тримають периметр, а відчутні трофеї гарантують, що ніхто не приписує собі заслуг за пусту варту.",al={"чому саутшор вимагає голови","докази вбивства"}}},fp="20,285,29.515.0,33.189.0,47.208.0,22.171.0,50.226.0"}
P.entries["item:sack-of-supplies"] = {n="Мішок Припасів",s="Ці мішки з припасами належать караванній партії, призначеній для гобліна-інженера Резлака біля Оргріммара. Товари, що їх везли через Дуротар, перехопили гарпії Пилового Вітру, які гніздяться на скелях Каньйону Гострого Вітру.",h="Ці мішки з припасами належать караванній партії, призначеній для гобліна-інженера Резлака біля Оргріммара.",kw={"мішок припасів","резлак","гарпії","каньйон гострого вітру","караван","оргріммар"},ang={["faction:Horde"]="Повернення втрачених припасів у місцевих хижаків гарантує, що прикордонне будівництво довкола молодої столиці Оргріммара триватиме без дорогих затримок."},sec={{t="Розграбований караван",b="Резлак — інженер, якого Ґазлоу найняв із Раджета, — покладається на регулярні каравани через Дуротар, щоб забезпечувати свої будівельні роботи для Орди. Та нетрі Дуротару далеко не приборкані. Коли обіцяна партія проходила біля дороги в каньйоні на південь від Оргріммара, на неї напали й розграбували її тутешні гарпії Пилового Вітру. Люті створіння затягли вантаж углиб своїх гнізд у Каньйоні Гострого Вітру, розкидавши мішки по землі та осипищах поряд із місцями гніздування гарпій."}},faq={{q="Що в цих мішках із припасами?",a="У мішках — будівельні матеріали й товари, відправлені для інженерних робіт Ґазлоу на підтримку будівництва орків біля Оргріммара. Без них Резлак застряг і не має чим завершити роботу.",al={"що в мішках","вміст мішка з припасами","припаси резлака"}},{q="Хто вкрав припаси?",a="Припаси вкрали гарпії Пилового Вітру — дикий пернатий народ, що заполонив високі ущелини й урвища Каньйону Гострого Вітру.",al={"хто вкрав припаси","хто взяв мішки"}},{q="Хто такий Резлак?",a="Резлак — гоблін-інженер, якого Ґазлоу послав із Раджета допомогти Орді будувати й прокладати шляхи в Дуротарі.",al={"хто такий резлак","лор резлака"}}},fp="16,228,19.496.0,34.232.0,23.133.0,14.132.0"}
P.entries["item:salty-scorpid-venom"] = {n="Солона Скорпідова Отрута",s="Солона скорпідова отрута — їдка рідина, яку здобувають зі скорпідів, що нишпорять Мерехтливими Низинами в Тисячі Голок. Насичена природними солями з пустельного дна, вона надзвичайно цінна для гномів — ракетних гонщиків, що прагнуть створити нестійке надгаряче пальне.",h="Солона скорпідова отрута — їдка рідина, яку здобувають зі скорпідів, що нишпорять Мерехтливими Низинами в...",kw={"солона скорпідова отрута","скорпіди","фіззл брассболтс","мерехтливі низини","пальне","перегони міражу"},ang={["profession:Engineering"]="Винахідники, що майструють у Мерехтливих Низинах, повсякчас дивляться далі за звичайну нафту й вугілля, випробовуючи органічні отрути як вибухові прискорювачі згоряння.",["race:Gnome"]="Тільки гномській винахідливості спаде на думку взяти смертельну пустельну отруту, змішати її з негакаталізаторами й упорснути в ракетний двигун — лише заради того, щоб зрізати кілька секунд із часу кола."},sec={{t="Вибухова присадка",b="Скорпіди, що повзають посушливими просторами Мерехтливих Низин, пристосувалися до надзвичайно багатого на мінерали довкілля. За багато поколінь отрута таких звірів, як скорпіди-шматувальники й скорпіди-жахи, увібрала величезну кількість місцевої солі. Гномські майстри на кшталт Фіззла Брассболтса варять із цієї їдкої суміші не протиотрути чи звичайні отрути — вони цінують її як можливу присадку до двигунного пального з високою теплотою згоряння."},{t="Пальне для суперництва на перегонах",b="На Перегонах Міражу інженерне змагання гномів і гоблінів штовхає винахідників випробовувати у своїх ракетних автомобілях дедалі небезпечніші матеріали. Фіззл Брассболтс вірить: якщо виварити солону отруту, обробити її особливими каталізаторами й залити в паливні баки, вона дасть пекельний жар, потрібний, щоб обігнати гоблінських гонщиків на соляних рівнинах."}},faq={{q="Які істоти дають Солону Скорпідову Отруту?",a="Її збирають із небезпечних скорпідів, що блукають соляними рівнинами Тисячі Голок, — особливо зі скорпідів-грабіжників і скорпідів-жахів.",al={"хто дропає солону скорпідову отруту","де взяти отруту скорпідів","джерело отрути скорпідів"}},{q="Чому отрута така солона?",a="Скорпіди живуть просто на вкритій мінералами землі Мерехтливих Низин. Їхні тіла вбирають густі солі висохлого озерного дна, тож отруйні залози насичуються солоністю.",al={"чому отрута солона","пояснення солоної отрути","сіль скорпідів лор"}},{q="Кому потрібна ця отрута й навіщо?",a="Фіззл Брассболтс, гном-інженер на Перегонах Міражу, шукає отруту, щоб скласти експериментальну паливну суміш, яка горить досить гаряче, щоб привести його ракетне авто до перемоги.",al={"кому потрібна отрута скорпідів","чому фіззл хоче отруту","предмет завдання фіззла брассболтса"}}},fp="19,253,27.425.0,27.377.0,43.138.0,26.212.0,29.185.0"}
P.entries["item:samophlange-item"] = {n="Самофланж (предмет)",s="Самофланж — загадкова механічна деталь, яку видобувають із глибин автоматичного пульта керування в Пустках. Попри складний вигляд, її справжнє призначення лишається інженерною загадкою навіть для гоблінів-механіків, які за нею полювали.",h="Самофланж — загадкова механічна деталь, яку видобувають із глибин автоматичного пульта керування в Пустках.",kw={"самофланж","спаттервалв","раджет","спілка винахідників","гобліни","інженерія"},ang={["profession:Engineering"]="Інженери оцінять самофланж як довершений приклад надмірно ускладненої конструкції: за хитромудрим фасадом ховається механізм такий крихкий, що ламається, щойно торкнеться підлоги."},sec={{t="Спантеличлива штуковина",b="Самофланж ховається в пульті керування в Пустках, за лабіринтом зайвих дротів і порожніх трубок. Щоб лише вийняти його з гнізда, доводиться добряче покопирсатися в навмисно заплутаному механізмі. Необізнаному оку він здається найважливішим вузлом годинникових і парових механізмів. Для гоблінів-майстрів це непереборна механічна головоломка, яку мають відправити до Спілки Винахідників в Андермайні, — от тільки через крихку будову деталь рідко витримує недбале поводження досить довго, щоб хтось устиг її зрозуміти."},{t="Цікавість і катастрофа",b="Коли деталь приносять Спаттервалвові в Раджет, інженер збирається відіслати її на розбір і дослідження найповажнішим умам Спілки. Та гоблінська цікавість неминуче бере гору над професійною розважливістю. Часто досить просто покласти тендітний пристрій, щоб роздивитися його нутрощі, — і він розлітається на купу брухту."}},faq={{q="Що таке самофланж?",a="Це химерна механічна деталь, вийнята із серця пульта керування в Пустках. Справжнє її призначення невідоме: довколишні механізми напхані трубками й дротами, що, здається, не роблять нічого корисного.",al={"що робить самофланж","призначення самофланжа","що це за річ"}},{q="Кому потрібен самофланж?",a="Спаттервалв, інженер із портового містечка Раджет, просить мандрівників добути деталь, щоб вивчити її й згодом надіслати до Спілки Винахідників.",al={"кому потрібен самофланж","кому віддати самофланж"}},{q="Що Спаттервалв робить із ним?",a="Хоча він збирається відправити деталь в Андермайн на ретельне вивчення дослідникам Спілки Винахідників, спершу хоче сам роздивитися її ближче. Щойно він кладе її на землю, щоб оглянути, тендітний механізм ламається.",al={"спаттервалв самофланж","що буде з самофланжем"}},{q="Звідки взявся самофланж?",a="Він міститься в хитромудрому пульті керування на півночі Пусток, захований за шарами заплутаної й, здавалося б, марної інженерії.",al={"місце самофланжа","де його знайшли"}}},fp="18,261,22.542.0,25.355.1,22.241.0,26.178.0,34.231.1,36.167.0"}
P.entries["item:samophlange-manual"] = {n="Посібник Самофланжа",s="Посібник Самофланжа — технічна інструкція, що розкриває будову невловимого самофланжа. Венчурна Компанія тримає її під сімома замками, а в розкиданих сторінках — вказівки, без яких гоблінські інженери не полагодять і не запустять цю дивну машинерію.",h="Посібник Самофланжа — технічна інструкція, що розкриває будову невловимого самофланжа.",kw={"посібник самофланжа","самофланж","бос копперплаґ","ріллі ґрісіґоб","шахта кам'яної жили","венчурна компанія"},ang={["faction:Horde"]="Здобутий посібник дає гоблінам, що тримаються Орди, змогу вивчати й пристосовувати корпоративну бурильну техніку просто під носом у Венчурної Компанії.",["profession:Engineering"]="Посібник — фірмова технологія Венчурної Компанії; він показує, як ревно гоблінські механіки бережуть комерційні таємниці й робочі креслення від колег."},sec={{t="Таємниці машинерії",b="Інженерні креслення й інструкції в гоблінських підприємствах бережуть, як золото, і Посібник Самофланжа — не виняток. Працюючи у Венчурній Компанії, честолюбний наглядач на ім'я Бос Копперплаґ ревниво ховав знання про пристрій і роздавав лише окремі сторінки найвідданішим підлеглим, щоб машинерія залишалася під його контролем. Коли пристрій вислизнув із рук Венчурної Компанії, полагодити його стало неможливо, доки не зібрати порвану, розпорошену документацію в наглядача та його команди в Шахті Кам'яної Жили."},{t="Задум суперника",b="Розірвавши стосунки з Венчурною Компанією, гоблінський інженер Ріллі Ґрісіґоб оселився в Оргріммарі, сподіваючись опанувати будову самофланжа. Коли він ще працював на Компанію, Копперплаґ його не жалував, тож тепер Ріллі покладається на заповзятливих мандрівників, щоб ті здобули обкладинку посібника й розрізнені аркуші. Відновлений посібник дає гоблінським механікам, що працюють пліч-о-пліч з Ордою, рідкісну змогу зазирнути у фірмову інженерію Венчурної Компанії."}},faq={{q="Що таке Посібник Самофланжа?",a="Це інженерний посібник про те, як керувати самофланжем і лагодити його, — складним і химерним механічним пристроєм, яким користується Венчурна Компанія в Пустках.",al={"що таке посібник самофланжа","книга самофланжа","путівник самофланжа"}},{q="Кому спершу належав посібник?",a="Його ревниво тримав Бос Копперплаґ, наглядач Венчурної Компанії в Шахті Кам'яної Жили на північному сході Пусток. Копперплаґ пильно беріг його таємниці й видавав окремі сторінки лише найнадійнішим робітникам.",al={"у кого посібник","посібник боса коппер-плага","хто написав посібник"}},{q="Чому посібник розірваний на сторінки?",a="Бос Копперплаґ навмисно розділив книгу, щоб суперники чи ненадійні підлеглі не могли збагнути пристрій цілком. Обкладинку він лишив собі, а п'ять сторінок роздав своїм шахтарям і операторам.",al={"чому знайти сторінки посібника","розкидані сторінки посібника","чому бракує сторінок"}},{q="Хто хоче прочитати повний посібник?",a="Ріллі Ґрісіґоб, інженер з Оргріммара, потребує зібраного докупи посібника, щоб зрозуміти й полагодити зламаний самофланж, здобутий у Пустках.",al={"кому потрібен посібник","ріллі ґрізіґоб","хто хоче посібник самофланжа"}},{q="Для чого використовують самофланж?",a="Точне призначення самофланжа — химерна гоблінська таємниця, але Венчурна Компанія покладається на них на своїх промислових розкопках, як-от водних роботах і бурових установках по всіх Пустках.",al={"що робить самофланж","призначення самофланжа","для чого самофланж"}}},fp="18,280,26.574.0,18.455.0,31.166.0,32.230.0,34.226.0,39.162.0,31.209.0"}
P.entries["item:sample-ichor"] = {n="Зразок Іхору",s="У цій пляшечці — очищена витяжка з мерзенної рідини, що підтримує існування гнилошкірих гнолів Срібнолісся. Аптекар Ренферрел розклав речовину на основні складники й виявив у ній сліди і некромантії, і чорнокнижницьких чарів.",h="У цій пляшечці — очищена витяжка з мерзенної рідини, що підтримує існування гнилошкірих гнолів Срібнолісся.",kw={"зразок іхору","гнилошкірі гноли","аптекар ренферрел","бетор айсшард","некромантія","срібнолісся"},ang={["class:Mage"]="Бетор Айсшард покладається на особливі чари провидіння, щоб прочитати залишки в зразку, — і це показує, чого варта класична магічна наука в протистоянні з темним чаклунством.",["class:Warlock"]="Аптекар Ренферрел виявляє в іхорі саме чорнокнижницьке мистецтво, переплетене з некромантією, — натяк на те, що чари скверни допомогли скріпити цих немертвих звірів."},sec={{t="Розгадка гнилошкірих",b="Гнилошкірі гноли, що нишпорять Срібноліссям, — не звичайні звірі. Здобувши зразки з цих істот та їхніх решток, Аптекар Ренферрел із Королівського Аптекарського Товариства розклав мерзенну рідину на складові. Хімічний аналіз показав, що іхор створено штучно, поєднанням темних шкіл: некромантичні обряди переплетено з чорнокнижницькою магією. Оскільки таке ремесло межує з магічними дисциплінами, що виходять за межі звичайної алхімії, Ренферрел запакував зразок і відіслав до Андерсіті, щоб Бетор Айсшард дослідив його чарами провидіння."}},faq={{q="Що таке Зразок Іхору?",a="Це очищений екстракт, який Аптекар Ренферрел приготував із тілесних рідин гнилошкірих гнолів. Ренферрел розклав його на основні складники, щоб дослідити, якою магією створено цих ходячих мертвих звірів.",al={"зразок іхору","що це за іхор","що таке зразок іхору"}},{q="Кому треба показати цей зразок?",a="Зразок треба доставити Бетору Айсшарду — магові-нежиті з Магічного Кварталу Андерсіті. Знання Бетора у віщуванні й магічних традиціях дають йому змогу розпізнати сліди магії, яких звичайна алхімія не помітить.",al={"кому віднести іхор","здати зразок іхору","бетор айсшард іхор"}},{q="Яка магія в іхорі?",a="Ренферрел виявив у рідині поєднання магії чорнокнижників і некромантії. Оглянувши фіал, Бетор Айсшард зауважує, що він просякнутий могутніми прадавніми чарами, і щоб цілком їх розкрити, потрібне глибше закляття віщування.",al={"яка магія в іхорі","тип магії іхору","магія гнилошкірих"}},{q="Чому аптекарі не завершили аналіз самі?",a="Королівське Аптекарське Товариство вправне в алхімії, отрутах і тілесних моровицях, але щоб розплутати складне магічне плетиво, потрібен справжній чародій. Бетор Айсшард уміє розпізнавати школи магії й розплутувати потаємні закляття, недосяжні для звичайного аптекарського приладдя.",al={"чому аптекарі надіслали бетору","чому не відмовитися від іхору гнилошкірих"}}},fp="12,252,24.620.0,25.222.0,29.249.0,39.246.0,59.278.0"}
P.entries["item:sample-of-zanzil-s-altered-mixture"] = {n="Зразок Зміненої Суміші Занзіла",s="У цій пробірці — сильнодійний зразок зілля, звареного знахарем Занзілом і здобутого під час таємної вилазки в Пустках. Агент, що потерпає від його виснажливої дії, везе зразок за море, до Таррен Мілла, сподіваючись знайти і протиотруту, і смертоносні таємниці отруйного ремесла.",h="У цій пробірці — сильнодійний зразок зілля, звареного знахарем Занзілом і здобутого під час таємної вилазки в...",kw={"зразок","занзіл","серж гінотт","таррен мілл","отрути","шентул","розбійник"},ang={["class:Rogue"]="Доставка цього мерзенного зразка — обряд посвяти для розбійників Орди, що веде просто до поглиблених уроків Сержа Гінотта: як варити, зберігати й наносити смертоносні отрути.",["faction:Horde"]="Щоб доставити це небезпечне зілля, доведеться перетнути континенти — цепеліновими вежами й торованими шляхами, що пов'язують Калімдор із землями Відступників у Лордероні."},sec={{t="Отруйний трофей",b="Проникнувши у вежу Венчурної Компанії біля Багнистого Болота й забравши схованку суміші Занзіла зі скриньки Ґаллівікса, агент і сам потрапляє під мерзенний вплив Занзіла. Шентул посилає ураженого агента за Велике Море зі зразком зілля в руках. Щоб знайти ліки, треба розшукати Сержа Гінотта — аптекаря з Таррен Мілла в Передгір'ї Гілсбреда, що має рідкісне вміння виділити отруту й розгадати її склад."},{t="Таємниці отруйного ремесла",b="Зразок — не лише нагальна медична справа, а й безцінний матеріал для розбійників Орди, що прагнуть опанувати темніші сторони свого ремесла. Серж Гінотт досліджує змінену суміш не тільки для того, щоб вилікувати ураженого гінця, а й щоб показати точне хімічне мистецтво, потрібне, аби варити сильні отрути й поводитися з ними в полі."}},faq={{q="Що це за суміш?",a="Це зразок алхімічного варива, пов'язаного зі знахарем Занзілом, здобутий під час вилазки до вежі Венчурної Компанії біля Багнистого Болота в Пустках. Він містить сильну отруту, що завдає тривалої виснажливої шкоди кожному, хто з нею безпосередньо зіткнеться.",al={"що це за суміш","зразок зміненої суміші занзіла","зразок отрути занзіла"}},{q="Навіщо нести його Сержеві Гінотту?",a="Серж Гінотт — вправний аптекар із Таррен Мілла в Передгір'ї Гілсбреда. Він має особливі знання, щоб знешкодити дію варива й створити надійні ліки, перш ніж отрута завдасть непоправної шкоди.",al={"хто такий серж гінотт","чому нести в таррен мілл","ліки від суміші занзіла"}},{q="Хто такий Занзіл?",a="Занзіл Вигнанець — сумнозвісний троль-знахар із джунглів, відомий зіллями, що доводять до божевілля, отрутами й мутагенами. Його отруйні рецепти поширилися далеко за межі рідних джунглів і потрапили до найманців і промисловців на кшталт Венчурної Компанії.",al={"хто такий занзіл","занзіл вигнанець","історія занзіла"}},{q="Як дістатися до Таррен Мілла, щоб доставити його?",a="Мандрівникам треба сісти на цепелін із Дуротару до Андерсіті в Галявинах Тірісфалю. Звідти — головним шляхом на південь через Срібнолісся й за вказівниками на схід у Передгір'я Гілсбреда, аж до містечка Таррен Мілл.",al={"як дістатися таррен мілла","шлях до гілсбреда","дорога до таррен мілла"}}},fp="34,334,13.478.0,22.344.1,21.277.0,41.236.0,14.274.0,43.245.0"}
P.entries["item:sample-snapjaw-shell"] = {n="Зразок Панцира Щелепаня",s="Зразок панцира щелепаня — міцний черепаховий панцир, здобутий у прісноводних оазах Пусток. Він вражає незгасною життєвою силою, тож його відправляють через Велике море, щоб допомогти друїдським пошукам способу відродити сплюндровані ліси Срібнолісся.",h="Зразок панцира щелепаня — міцний черепаховий панцир, здобутий у прісноводних оазах Пусток.",kw={"зразок панцира щелепаня","щелепань","мура рунтотем","срібнолісся","оази","друїди"},ang={["class:Druid"]="Для друїдів Кола Кенарія вивчення стійкої життєвої сили щелепанів з оаз — важливий урок про те, як життя вистоює і як сплюндровану землю колись можна буде зцілити.",["race:Tauren"]="Доставка цього панцира показує відданість тауренів Земній Матері: вони готові нести допомогу й природне зцілення навіть своїм союзникам-нежиті за морем."},sec={{t="Іскра життя оази",b="Черепахи-щелепані, що живуть у пишних, позначених дивною аномалією оазах Пусток, мають напрочуд живучі панцири. На відміну від звичайного панцира, свіжий зразок панцира щелепаня ще довго після загибелі істоти зберігає слабке внутрішнє сяйво й живий пульс. Для тауренських друїдів, що стежать за стрімкими змінами в довкіллі, ці панцири втілюють стійку, гнучку іскру дикої природи Калімдору — знак того, що життя може буяти навіть серед суворої посухи."},{t="Зцілення далеких земель",b="Відчуваючи приховану життєву силу панцира, тауренські природознавці відсилають гінців через море, щоб доставити зразки Мурі Рунтотем у Гробницю. Перебуваючи серед сплюндрованих просторів Срібнолісся, Мура прагне допомогти Відступникам знайти спосіб зцілити уражені північні землі. Вивчаючи незгасну життєву силу, збережену в панцирі щелепаня, вона сподівається розгадати таємниці, які допоможуть відродити недужий ліс і пробудити нові паростки у вмираючому ґрунті."}},faq={{q="Чим особливий цей панцир хижощелепа?",a="На відміну від крихкої звичайної кістки, цей панцир зберігає внутрішнє сяйво й, здається, досі пульсує життям після того, як його зібрали. Він із хижощелепів, що буяють довкола дивних прісних оаз Пусток, де природна енергія незвично сильна.",al={"чим особливий панцир","що таке панцир хижощелепа","сяйливий панцир"}},{q="Кому потрібен цей зразок?",a="Панцир призначено Мурі Рунтотем — друїдці-таурен, що мешкає в Гробниці в Срібноліссі. Вона вирушила до Східних Королівств, щоб допомагати Відступникам і вивчати, як повертати до життя вмирущі землі.",al={"хто хоче панцир","куди нести панцир","завдання мури рунетотем"}},{q="Навіщо відправляти панцир із Пусток аж до Срібнолісся?",a="Срібнолісся — хворий, зіпсований ліс, а оази Пусток раптом вибухнули впертим, невгамовним життям. Друїди вірять, що, вивчаючи міцну життєву силу звірів Калімдору, можна збагнути, як зцілити отруєну землю Лордерону.",al={"чому слати в сільверпайн","зв'язок панцира із сільверпайном"}},{q="Чи небезпечний чи отруєний панцир?",a="Ні. Панцир випромінює чисту життєву силу, а не темну магію. Раптова буйна зелень в оазах Пусток загадкова, але друїди бачать у цій енергії природну стійкість, яку варто плекати.",al={"чи панцир злий","чи панцир зіпсований"}}},fp="20,263,21.492.0,21.481.0,38.251.0,22.213.0,51.261.0,34.210.0"}
P.entries["item:samuel-s-remains"] = {n="Останки Семюела",s="Останки Семюела — повернуті земні рештки Семюела Фіппса, колишнього мешканця Галявин Тірісфалю, що впав перед Погибеллю. Зібрані шукачами пригод біля Похоронного Подзвону, їх ховають поруч із його дружиною Марлою, щоб виконати її передсмертне бажання.",h="Останки Семюела — повернуті земні рештки Семюела Фіппса, колишнього мешканця Галявин Тірісфалю, що впав перед...",kw={"останки семюела","семюел фіппс","марла","поховання","послушниця елрет","похоронний подзвін"},ang={["race:Undead"]="Поховати останки Семюела — ранній урок самосвідомості Відступників: повага до трагічно загиблих позначає ключову моральну межу між вільною нежиттю й безтямними рабами Погибелі."},sec={{t="Трагічне возз'єднання",b="До того як чума нежиті прокотилася Лордероном, Семюел Фіппс мирно жив зі своєю дружиною Марлою. Коли вдарила зараза, Семюел піддався їй і був прикутий до безтямної служби Погибелі. Марла уникла нежиття лише для того, щоб загинути від руки чоловіка, якого кохала. Попри цей жорстокий кінець її останнім бажанням була не помста, а вічність удвох: вона благала поховати її поруч із Семюелом, щойно його прокляту подобу буде упокоєно. Послушниця Елрет у Похоронному Подзвоні доручає щойно пробудженим Відступникам вистежити блукаючу подобу Семюела на північний схід від поселення, зібрати його кістки й поховати їх у передньому ряду місцевого цвинтаря."}},faq={{q="Хто такий Семюел Фіппс?",a="Семюел Фіппс — людина, що жила в Галявинах Тірісфалю до Третьої війни. Коли прийшла чума Погибелі, він загинув і повстав безвольним рабом Короля-Ліча. Гнаний безтямним голодом, він зрештою вбив власну дружину, Марлу.",al={"семюел фіппс","хто такий семюел","історія семюела"}},{q="Де знайти останки Семюела?",a="Їх забирають у самого Семюела Фіппса, що блукає серед зруйнованого табору при дорозі на північний схід від Похоронного Подзвону. Поклавши край його безтямному існуванню, можна забрати його земні останки.",al={"знайти останки семюела","де семюел фіппс","місце семюела"}},{q="Чому Відступники ховають його поруч із дружиною?",a="Передсмертним бажанням Марли було спочити поруч із коханим чоловіком, хоч саме він її вбив. Послушниця Елрет виконує це прохання, щоб довести: щойно звільнені Відступники досі мають співчуття, шану до мертвих і людяність, що відрізняють їх від Погибелі.",al={"чому ховати семюела","могила мерли","остання воля мерли"}}},fp="16,242,16.635.0,21.233.0,33.202.0,45.279.0"}
P.entries["item:sapphire-of-aku-mai"] = {n="Сапфір Аку'Май",s="Сапфіри Аку'Май — сяйливі, насичені водою мінеральні скупчення, що ростуть у підземних тунелях Чорноглибинних Печер. Наги, що насуваються, почали видобувати ці самоцвіти, тож Земляне Кільце прагне здобути їх, перш ніж хтось скористається їхньою могутньою магічною силою.",h="Сапфіри Аку'Май — сяйливі, насичені водою мінеральні скупчення, що ростуть у підземних тунелях Чорноглибинних...",kw={"сапфір аку'май","дже'ню санкреа","земляне кільце","наги","чорноглибинні печери","шаман"},ang={["class:Mage"]="Природна насиченість водою робить ці сирі сапфіри дуже цінними провідниками для могутніх магічних складників.",["class:Shaman"]="Шамани Земляного Кільця на кшталт Дже'ню Санкреа одразу відчувають духів води, ув'язнених у цих самоцвітах, і вважають видобуток наг стихійною загрозою."},sec={{t="Самоцвіти глибин",b="Сапфіри Аку'Май, знайдені біля затоплених входів до Чорноглибинних Печер на Зорамському Березі Ашенвалю, — кришталеві утворення, багаті на стихійну енергію. Духи води міцно чіпляються за них, тож вони — надзвичайні каталізатори для магічних справ. Коли розвідники доповіли, що підземні наги взялися видобувати ці скупчення зі стін печер, шаман Дже'ню Санкреа звернувся по допомогу до шукачів пригод, щоб їх відібрати. У лапах зміїного народу ці камені легко можуть живити нищівні магічні обряди."}},faq={{q="Що таке Сапфір Аку'Май?",a="Це яскраві сапфірові кристали, що вкривають стіни Чорноглибинних Печер. Тісно пов'язані з духами стихії води, вони мають глибокий магічний і стихійний резонанс.",al={"що це за кристал","історія сапфіра аку'май","що це за самоцвіти"}},{q="Навіщо наги збирають ці сапфіри?",a="Їхні точні наміри невідомі, але Дже'ню Санкреа підозрює, що наги хотіли використати багату водяну й магічну енергію кристалів для небезпечного чаклунства в затопленому храмі.",al={"чому наги збирають сапфіри","збір кристалів нагами"}},{q="Хто шукає ці сапфіри?",a="Дже'ню Санкреа, шаман Земляного Кільця із Застави Зорам'гар на Узбережжі Зорам в Ашенвалі, доручає мандрівникам зібрати їх, щоб вони не дісталися нагам.",al={"хто хоче сапфіри аку'май","хто здає сутність аку'май"}},{q="Чи пов'язані ці кристали безпосередньо зі звіром Аку'май?",a="Кристали названо на честь Аку'май — потворної гідри, що живе в глибинах, але вони природно ростуть у стінах печер. Назва лише відбиває їхню близькість до темної сили, що чатує в руїнах.",al={"зв'язок з аку'май","чи це від аку'май"}}},fp="19,275,16.557.0,30.177.0,44.193.0,35.174.0,54.202.0"}
P.entries["item:sara-balloo-s-plea"] = {n="Благання Сари Баллу",s="Благання Сари Баллу — рукописне послання, яке в Айронфорджі склала вбита горем удова. Не в змозі в своїй скорботі постати перед монархом особисто, вона довіряє цей лист випробуваному захисникові Альянсу, щоб той поніс його перед Короля Маґні Бронзбірда.",h="Благання Сари Баллу — рукописне послання, яке в Айронфорджі склала вбита горем удова.",kw={"благання","сара баллу","лист","удова","король маґні бронзбірд","айронфордж","високий престол"},ang={["faction:Alliance"]="Сара довіряє своє прохання лише захисникам, визнаним за службу Альянсу, покладаючись на їхню репутацію, щоб її звернення вислухали при дворі.",["race:Dwarf"]="Для дворфів донести послання Сари до Високого Престолу — акт глибокої спорідненості: навіть у горі жоден горянин чи містянин не лишиться непочутим Королем Маґні."},sec={{t="Звернення вдови",b="Написане в тіні глибокої особистої трагедії, Благання Сари Баллу — смиренне звернення просто до престолу Айронфорджа. Замість самій іти до Високого Престолу в такому горі, Сара шукає шукача пригод, який довів свою вірність і доблесть Альянсу, щоб той передав її слова. Послання просить уваги Короля Маґні Бронзбірда, звертаючи погляд володаря на приватну жалобу й жертви звичайних дворфійських родин, що служать королівству."}},faq={{q="Що таке Благання Сари Баллу?",a="Це рукописний лист, який Сара Баллу написала Королю Маґні Бронзбірду, просячи його королівської уваги, поки вона тужить на самоті.",al={"благання сари баллу","записка вдови айронфордж","записка сари"}},{q="Чому Сарі Баллу потрібен хтось інший, щоб доставити лист?",a="Сару здолало горе, і вона вважає, що, постанувши перед королем Айронфорджа в такому стані, лише зашкодить своєму проханню, тож покладається на поборника Альянсу.",al={"чому сара не доставить сама","чому сара не може піти","горе сари"}},{q="Хто отримує це послання?",a="Лист адресовано й доставляють просто Королю Маґні Бронзбірду до Високого Трону Айронфорджа.",al={"хто отримує благання","кому доставити","лист магні"}},{q="До чого веде доставка листа?",a="Лист, вручений Королю Маґні, привертає його увагу до втрати Сари Баллу й започатковує королівську відповідь, що вшановує її загиблу родину.",al={"ланцюжок завдань благання","зв'язок з даниною королів","що буде далі"}}},fp="18,238,16.491.0,27.146.0,53.187.0,26.103.0,40.143.1"}
P.entries["item:sarilus-foulborne-s-head"] = {n="Голова Сарілуса Фолборна",s="Голова Сарілуса Фоулборна — моторошний трофей, здобутий у неживого чаклуна, що осквернив води північного Калімдору. Принесена через кордон із Пусток до Ашенвалю, вона стає незаперечним доказом того, що некромант-баламут загинув від рук вартових.",h="Голова Сарілуса Фоулборна — моторошний трофей, здобутий у неживого чаклуна, що осквернив води північного...",kw={"сарілус фоулборн","відступники","пік жахливої імли","велене старстрайк","водяні елементалі","пустки"},ang={["faction:Alliance"]="Щоб завдати цього удару, доводиться пробратися глибоко на ворожі землі Орди в Пустках і знищити небезпечного свавільного чаклуна.",["race:NightElf"]="Голова Фоулборна задовольняє жагу вартових помститися безрозсудному чаклунові-осквернителю, що зганьбив духів цієї землі."},sec={{t="Осквернювача змусили замовкнути",b="Чаклун Відступників Сарілус Фоулборн, що засів на вершині Піка Жахливої Імли на півночі Пусток, накликав на себе гнів нічних ельфів, коли почав псувати й підкоряти собі зграї водяних елементалів. Вартова Велене Старстрайк зі свого посту в Притулку Срібного Вітру впізнала його мерзенну роботу й послала звитяжців через кордон на землі Орди, щоб покласти край його безрозсудним дослідам. Відтята голова мага була єдиним доказом, який Старстрайк погодилася б прийняти: тільки так можна пересвідчитися, що його глузлива посмішка зникла назавжди, а збурені води Ашенвалю хоч трохи заспокояться."}},faq={{q="Хто такий Сарілус Фоулборн?",a="Сарілус Фоулборн — маг-нежить, що оселився на вершині Піку Жахливої Імли на півночі Пусток. Він накликав на себе гнів нічних ельфів, бо викликав і спотворював безліч водяних елементалів, і Вартова Велене Старстрайк наказала його вбити.",al={"хто такий сарілус","історія сарілуса фоулборна","хто такий фоулборн"}},{q="Навіщо Вартовій Велене Старстрайк його голова?",a="Велене Старстрайк хотіла знати напевно, що зарозумілий чаклун мертвий. Сарілус відкрито глузував з неї, оскверняючи водяних духів краю, і лише його відрубана голова могла переконати її, що загрозу усунуто.",al={"навіщо брати його голову","голова велене старстрайк","доказ смерті"}},{q="Де шукати Сарілуса Фоулборна?",a="Його лігво — на самій вершині Піку Жахливої Імли, скелястої гори на півночі Пусток, неподалік від кордону з Ашенвалем.",al={"де знайти фоулборна","місце сарілуса","маг піку жахливої імли"}},{q="Навіщо Фоулборн оскверняв водяних елементалів?",a="Фоулборн тайною магією викликав численних водяних елементалів і підкоряв їх своїй волі, водночас спотворюючи їх. Його безрозсудні чари порушили природну рівновагу вод поблизу Ашенвалю, і Вартові не забарилися з відплатою.",al={"чому осквернювати елементалів","осквернення водяних елементалів","мотиви фоулборна"}}},fp="24,293,18.570.0,26.261.0,50.261.0,35.146.0,44.251.0"}
P.entries["item:sarltooth-s-talon"] = {n="Пазур Сарлтута",s="Пазур Сарлтута — відтятий кіготь ватажка рапторів, що чатує над Місцем Розкопок Велґара в Багнокраї. Для дворфа Ормера Айронбрейда він — відчутний доказ того, що лютого звіра, який заполонив археологічний розкоп, убито.",h="Пазур Сарлтута — відтятий кіготь ватажка рапторів, що чатує над Місцем Розкопок Велґара в Багнокраї.",kw={"пазур сарлтута","сарлтут","раптори","ормер айронбрейд","місце розкопок велґара","багнокрай"},ang={["class:Hunter"]="Вистежити хитрого ватажка зграї на кшталт Сарлтута й здобути його пазур як трофей — класичне випробування влучності й володіння звірами.",["race:Dwarf"]="Здобутий пазур — довгоочікувана помста за полеглих дворфів-археологів, що загинули, служачи Лізі Дослідників з волі Короля Маґні Бронзбірда."},sec={{t="Трофей помсти",b="Коли раптори заполонили Місце Розкопок Велґара й вирізали дворфійську експедицію, Ормер Айронбрейд дивився з гребеня згори, не в змозі завадити різанині. Він запримітив одного величезного, грізного раптора — Сарлтута — як імовірного ватажка зграї, що стояв за нападом. Прагнучи відплати за полеглих родичів, Ормер вимагав смерті звіра й попросив принести один із його хижих пазурів як доказ. Відтятий пазур кладе край терору, який Сарлтут сіяв над прадавніми дворфійськими руїнами."}},faq={{q="Звідки береться Пазур Сарлтута?",a="Пазур вирізають у Сарлтута — великого раптора-ватажка, що никає західними хребтами над Місцем Розкопок Велґара в Багнокраї.",al={"хто дропає пазур сарлтута","місце сарлтута","як отримати пазур"}},{q="Кому потрібен Пазур Сарлтута?",a="Ормер Айронбрейд, дворф, що стоїть на оглядовому майданчику над Місцем Розкопок Велґара, просить пазур, щоб переконатися: звіра, який вирізав його загін, нарешті вбито.",al={"хто бере пазур","куди здати пазур","завдання ормера айронбрейда"}},{q="Навіщо Ормерові Айронбрейду доказ смерті Сарлтута?",a="Ормер вважає, що саме Сарлтут вів зграю рапторів, яка вигнала й перебила дворфів-копачів. Для нього пазур — знак справедливості й останнє прощання з полеглими товаришами.",al={"чому вбити сарлтута","що накоїв сарлтут"}},{q="Що сталося з дворфами на розкопках?",a="Дворфи мали відкопати давні артефакти для Ліги Дослідників, але дикі раптори зненацька напали на робітників, перебили більшість, а вцілілих загнали на сусідній хребет.",al={"лор розкопок велґара","чому раптори на розкопках"}}},fp="17,268,21.498.0,39.139.0,28.173.0,57.175.0,52.193.0"}
P.entries["item:sathrah-s-sacrifice"] = {n="Жертва Сатри",s="Жертва Сатри — це сріблясті павутинні залози, взяті в Леді Сатри, могутньої павучихи з Тельдрассилу. Жриця А'мура доручає цю пожертву шукачам пригод, і її приносять до фонтана в Храмі Місяця, щоб очистити істоту від скверни й упокоїти її дух.",h="Жертва Сатри — це сріблясті павутинні залози, взяті в Леді Сатри, могутньої павучихи з Тельдрассилу.",kw={"жертва сатри","леді сатра","храм місяця","жриця а'мура","сестринство елуни","очищення","тельдрассил"},ang={["class:Priest"]="Жерці Сестринства Елуни вважають цей обряд урочистим актом божественного милосердя: священні води очищають скверну, а не просто позбуваються тіла вбитого звіра.",["race:NightElf"]="Для нічних ельфів убивати зіпсованих звірів — тяжкий обов'язок; повернення духу Леді Сатри до благодаті Елуни дає надію, що життя на Тельдрассилі колись відродиться, вільне від божевілля."},sec={{t="Очищення у священних водах",b="Колись Леді Сатра була шанованою істотою Тельдрассилу, але стала жертвою підступного божевілля і скверни, що вразили гілля великого дерева. На прохання Сестринства Елуни шукачі пригод здобувають її сріблясті павутинні залози не як звичайні трофеї, а як освячену пожертву. Коли ці рештки омивають у священному фонтані Храму Місяця, мерзенна скверна, що отруїла розум Сатри, змивається. Обряд звільняє її стражденну душу: дух Сатри мирно з'являється у святилищі, і їй дарована обіцянка відродження в благодаті Елуни."}},faq={{q="Що таке Жертва Сатри?",a="Жертва Сатри — ритуальне підношення зі сріблястих павутинних залоз Леді Сатри, оскверненої гігантської павучихи, вбитої на Тельдрассилі. Сестринство Елуни використовує його в обряді очищення, щоб звільнити душу створіння.",al={"що за залози","жертва сатри предмет","жертвоприношення леді сатри"}},{q="Чому залози треба покласти у фонтан?",a="Центральний фонтан у Храмі Місяця в Дарнасусі наповнений святою водою, освяченою Елуні. Занурені в неї рештки Сатри очищуються від мерзенної скверни, що звела її з розуму, і її дух звільняється від мук.",al={"чому фонтан у храмі","чому жертва сатри","що робить фонтан"}},{q="Що стається, коли підносять жертву?",a="Щойно жертву занурюють у священні води, скверна зникає і з'являється примарна постать Леді Сатри: вона спокійно обходить водойму — знак того, що її душа нарешті впокоїлася.",al={"що буде у фонтані","дух сатри з'являється","подія біля фонтана"}},{q="Хто проводить цей обряд?",a="Жриця А'мура, служниця Сестринства Елуни з Храму Місяця, доручає шукачам пригод упокоїти створіння й піднести його рештки богині.",al={"хто дає жертву сатри","завдання жриці а'мури","хто очищає сатру"}}},fp="19,300,31.580.0,28.222.0,50.227.0,44.178.1,25.182.0"}
P.entries["item:satyr-horns"] = {n="Роги Сатира",s="Роги сатира — похмурі трофеї, які забирають у зіпсованих сатирів, що чинять лихо в прадавніх лісах Ашенвалю. Їх прагнуть і скорботні мешканці лісу, які жадають відплати, і спритні купці з Раджета, адже вони — незаперечний доказ того, що ще один слуга Палаючого Легіону загинув.",h="Роги сатира — похмурі трофеї, які забирають у зіпсованих сатирів, що чинять лихо в прадавніх лісах Ашенвалю.",kw={"роги сатира","сатири","палаючий легіон","ілліяна","піксель","раджет","ашенваль"},ang={["faction:Horde"]="Діючи із Застави Розщепленого Дерева, воїни Орди вичищають мерзенних сатирів, що загрожують їхнім лісозаготівлям, і водночас заробляють на гоблінських покупцях, які везуть товар до Раджета.",["race:NightElf"]="Для калдореїв відтинати роги сатирів — гіркий обов'язок: так вони очищають ліс предків від родичів, що добровільно проміняли свою спадщину на служіння демонам."},sec={{t="Трофеї помсти й торгівлі",b="Закручені роги сатирів Ашенвалю — промовистий знак демонічної порчі, що пустила коріння у священному лісі. Для дріади Ілліяни, яка ховається серед ельфійських руїн Лісової Пісні, збирання цих відтятих рогів — справа скорботи й помсти за втрачену сестру Анілію. А от для заїжджих торговців, як-от мандрівної гоблінки Піксель, що спочиває на Заставі Розщепленого Дерева, роги — чиста нагода заробити. Попит на роги сатирів у нейтральному порту Раджет злетів, і ці моторошні рештки вбитих демонів стали прибутковим товаром для кожного, хто наважиться полювати на їхніх власників."},{t="Зачищення зіпсованих осередків",b="Роги сатирів не купиш у звичайних постачальників — їх доводиться відтинати просто в тих істот, що чатують у темних закутках лісу. Сатири тримають оплоти по всьому Ашенвалю, і найвідоміші з них — осквернені гаї Ксавіана, затінені западини Сатирнаару та руїни Нічного Потоку. Зачищення цих осередків звільняє землю від залишків демонічної скверни і водночас забезпечує доказами винищення і скорботних охоронців, і завзятих купців."}},faq={{q="Навіщо Ілліяні Роги Сатира?",a="Ілліяна збирає Роги Сатира, щоб помститися за загиблу сестру Анілію, яку вбили сатири Ашенвалю. Роги, зняті з убитих демонів, доводять їй, що сатирів меншає, і дарують спокій духові її сестри.",al={"роги ілліяни","сатири анілії","завдання лісової пісні"}},{q="Навіщо Піксель збирає Роги Сатира?",a="Піксель — заповзятлива мандрівниця, що зупинилася на Заставі Розщепленого Дерева дорогою до Раджета. Вона дізналася, що в гоблінському порту за роги сатирів добре платять, і до свого від'їзду наймає шукачів пригод, щоб ті замість неї взялися за небезпечне полювання.",al={"піксель сплінтертрі","навіщо піксель роги","роги сатирів рятчет"}},{q="Де найкраще шукати сатирів із такими рогами?",a="Сатири живуть у кількох осквернених куточках Ашенвалю. Найбільше їх у Ксавіані та Сатирнаарі на північному сході й у Нічному Потоці в лісах на сході центральної частини краю.",al={"місця сатирів ашенвейл","де сатири","табори сатирів"}},{q="Хто такі сатири й чому в них роги?",a="Сатири — колишні нічні ельфи, яких демонічні угоди часів Війни Прадавніх перетворили на звірині демонічні створіння. Козячі копита, хвости й зловісні роги — тілесні знаки демонічної скверни, дарованої Палаючим Легіоном.",al={"хто такі сатири","чому в сатирів роги"}}},fp="11,308,34.595.0,30.461.0,35.245.0,36.240.0,58.180.0,44.256.0"}
P.entries["item:savannah-lion-tusk"] = {n="Ікло Лева Савани",s="Ікла левів савани — масивні ікла хижих великих котів, що блукають посушливими рівнинами Пусток. Для мандрівників це звичайний мисливський трофей, але вони мають і незвичне призначення: їх додають у легендарне міцне пиво Ченя Бурештофа.",h="Ікла левів савани — масивні ікла хижих великих котів, що блукають посушливими рівнинами Пусток.",kw={"ікло лева савани","леви савани","гумар володар прайду","дрон","раджет","пиво"},ang={["class:Hunter"]="Полювання на лютих левів серед золотих чагарників Пусток — справжнє випробування для слідопита, а здобуті ікла і смертоносні в бою, і цінні для місцевих броварів."},sec={{t="Цікавий броварський складник",b="Великі коти Пусток — від нишпорок і левиць до величних прайдів на чолі з ватажками та звірів на кшталт Гумара Володаря Прайду — озброєні гострими важкими іклами. Більшість тих, хто здолає цих хижаків, бере їхні зуби лише як доказ своєї вправності, але Майстер Броварства Дрон у Раджеті шукає їх для куди хмільнішого ремесла. Разом із нирками степових довгоступів і рогами громоящерів Дрон додає ікла в пиво, щоб відтворити знаменитий трунок, названий на честь Ченя Бурештофа, — з легендарним ударом, який мало чия смертна горлянка витримає."}},faq={{q="Навіщо Майстрові Броварства Дрону Ікла Лева Савани?",a="Майстер Броварства Дрон у Раджеті відтворює рецепт пива «Бурештоф», названого на честь Ченя Штормстаута, — цей рецепт дістався йому від наставника. Ікла — один із трьох місцевих інгредієнтів Пусток, без яких не відтворити особливого смаку й міцності цього стауту.",al={"навіщо ікла для пива","ікла лева дрона","рецепт броваря дрона"}},{q="Які звірі мають Ікла Лева Савани?",a="Їх можна вирізати в будь-якого лева з прайдів савани, що никають Пустками: у високогривих левів, патріархів, матріархів, мисливиць, нишпорок, а також у рідкісних звірів на кшталт Дішу та Гумара Володаря Прайду.",al={"де падають ікла лева","хто дропає ікло лева","джерело іклів лева савани"}},{q="Невже в левів справді такі ікла?",a="У суворих диких краях Калімдору ікла великих котів савани виростають такими масивними й товстими, що місцеві мисливці й поселенці жартома прирівнюють їх до бивнів.",al={"чому ікла левів називають іклами","ікла проти зубів лева","анатомія іклів лева"}}},fp="18,251,28.529.0,51.251.0,39.212.0,29.185.0"}
P.entries["item:scaber-stalk"] = {n="Стебло Стрункавки",s="Стебла Стрункавки — рідкісні гриби, що буяють у сирій, відлюдній печері, захованій за Водоспадом Скельного Джерела на Темному Узбережжі. Травники й алхіміки цінують їх за незвичайні властивості, а Барітрас Муншейд шукає їх для своїх вигадливих сумішей.",h="Стебла Стрункавки — рідкісні гриби, що буяють у сирій, відлюдній печері, захованій за Водоспадом Скельного...",kw={"стебло стрункавки","водоспад скельного джерела","барітрас муншейд","гай прадавніх","гриби","темне узбережжя"},ang={["profession:Herbalism"]="Хоч ці підземні стебла й не звичайна торгова трава, вони дають цінне уявлення про те, як особливий клімат печер і тіні, що насуваються, змінюють місцеві гриби.",["race:NightElf"]="Дослухаючись до перестороги Гаю Прадавніх, нічні ельфи збирають ці печерні гриби дуже обережно, бо біля Водоспаду Скельного Джерела гноїться присутність порчі."},sec={{t="Рідкісний грибний зразок",b="Стебла Стрункавки — маловідомі гриби, що ростуть глибоко в печері, захованій за Водоспадом Скельного Джерела серед північно-східних гір Темного Узбережжя. На відміну від звичайної лісової рослинності, ці бліді стебла буяють лише у відлюдній вогкості підземних печер. Через віддалене й небезпечне середовище зібрати їх украй рідко вдається, тож алхіміки на кшталт Барітраса Муншейда в Обердайні наймають відважних розвідників, готових ризикнути в темряві."},{t="Тінь у водоспаді",b="Збирати Стебла Стрункавки куди небезпечніше, ніж звичайне збиральництво. Шановані духи-дерева з Гаю Прадавніх застерегли місцевих нічних ельфів: вони відчули, як у печері біля Водоспаду Скельного Джерела утверджується темне, дедалі сильніше зло. Хоч алхіміки цінують ці стебла разом із рідкісними Блідими Поганками для дослідних настоїв, збирачі неминуче опиняються віч-на-віч із тим лихом, що вкоренилося під горами."}},faq={{q="Де ростуть Стебла Стрункавки?",a="Стебла Стрункавки ростуть лише у вологій печері, захованій за Водоспадом Скельного Джерела, на гірському хребті північно-східного Темного Узбережжя.",al={"місце стебла стрункавки","де стебла стрункавки","печера стебел стрункавки"}},{q="Кому потрібні Стебла Стрункавки?",a="Барітрас Муншейд, нічний ельф-учений з Обердайна, шукає Стебла Стрункавки й Бліду Поганку, щоб зварити особливе зілля.",al={"хто використовує стебло стрункавки","барітрас муншейд гриби","кому потрібні стебла стрункавки"}},{q="Чому Барітрас Муншейд не зібрав стебла сам?",a="Гай Прадавніх застеріг Барітраса не наближатися до печери: його духи відчули, що за водоспадом знайшло притулок нове небезпечне зло.",al={"чому не зібрав сам","застереження барітраса","застереження печери кліффспрінг"}},{q="Що ще росте поруч зі Стеблами Стрункавки?",a="У печері ховається й смертельно отруйний гриб Бліда Поганка — ще один рідкісний зразок, потрібний Барітрасові для алхімічних досліджень.",al={"інші гриби в печері","бліда поганка і стебло стрункавки","гриби кліффспрінг"}}},fp="12,247,22.463.0,21.462.1,28.147.0,24.136.0,58.155.0,40.128.0"}
P.entries["item:scale-of-old-murk-eye"] = {n="Луска Старого Мурк-Ая",s="«Луска Старого Мурк-Ая» — трофей, здобутий із сумнозвісного ватажка мурлоків, Старого Мутноокого, що тероризує узбережжя Вестфолу. Зрізана зі шкури потвори, вона стає незаперечним доказом її загибелі для примарного доглядача Маяка Вестфолу.",h="«Луска Старого Мурк-Ая» — трофей, здобутий із сумнозвісного ватажка мурлоків, Старого Мутноокого, що...",kw={"луска старого мурк-ая","старий мутноокий","мурлоки","маяк вестфолу","капітан ґрейсон","вестфол"},ang={["faction:Alliance"]="Для моряків Альянсу, що перетинають Велике Море й заходять у води Стормвінда, кінець Старого Мутноокого означає, що Маяк Вестфолу світитиме й далі, рятуючи майбутні кораблі від загибелі на скелях."},sec={{t="Трофей прибережного лиха",b="Узбережжя Вестфолу й так небезпечне через приховані мілини й безжальні шторми, але Старий Мутноокий перетворив загрозу для мореплавства на справжню різанину. За словами Капітана Ґрейсона, привида, прикутого до Маяка Вестфолу, цей мурлок був хитріший за своїх диких родичів і збирав слабкодухих мурлоків у набіги на берег. Мутноокий налякав і прогнав родину доглядача, тож тієї ночі, коли корабель Ґрейсона розбився об скелі, маяк стояв темний, а коли родина повернулася, щоб знову запалити вогонь, мурлок напав ізнову й вирізав їх. Лише луска з цієї потвори може вдовольнити мстивого духа й довести, що узбережжя очищене від найлютішого хижака."}},faq={{q="Для чого потрібна Луска Старого Мурк-Ая?",a="Луска — доказ смерті для Капітана Ґрейсона, привида, що блукає скелястим острівцем біля Маяка Вестфолу. Ґрейсон прагне помститися Старому Мурк-Аю: той залишив маяк темним у ніч, коли розбився корабель капітана, а згодом вирізав родину доглядача маяка.",al={"хто хоче луску","здати луску мурк-ая","використання луски старого мурк-ая"}},{q="Хто такий Старий Мурк-Ай?",a="Старий Мурк-Ай — горезвісно лютий і підступний ватажок мурлоків, що никає піщаними берегами Вестфолу. На відміну від звичайних мурлоків, він уміє згуртувати родичів і змусити їх до злагоджених смертоносних набігів на прибережні застави.",al={"хто такий мурк-ай","історія мурк-ая","старий мурк-ай"}},{q="Чому Старий Мурк-Ай напав на маяк?",a="Спершу Старий Мурк-Ай напав на маяк, щоб прогнати доглядача з родиною й занурити узбережжя в темряву. Коли доглядачі повернулися й знову запалили вогонь, Мурк-Ай зібрав родичів на другий напад: уся родина загинула, а кораблі опинилися наосліп перед підступними прибережними мілинами.",al={"чому напав на маяк","напад на маяк","мурк-ай і маяк"}}},fp="21,235,27.728.0,43.293.0,20.256.0,43.305.0"}
P.entries["item:scarlet-crusade-documents"] = {n="Документи Багряного Хрестового Походу",s="Ці перехоплені папери ніс гонець, якого Багряний Хрестовий Похід послав із Багряного Монастиря до таборів біля Похоронного Подзвону. У них — накази польовим командирам Хрестового Походу по всіх Галявинах Тірісфалю, і вони дають Відступникам саме ті військові відомості, які потрібні, щоб ударити по місцевому проводу Хрестового Походу.",h="Ці перехоплені папери ніс гонець, якого Багряний Хрестовий Похід послав із Багряного Монастиря до таборів...",kw={"документи багряного хрестового походу","накази","мевен корґал","екзекутор аррен","екзекутор зиґанд","брілл","ратуша"},ang={["race:Undead"]="Нести ці перехоплені папери — означає для пробудженого з Відступників випуск із цвинтарних випробувань Похоронного Подзвону до ширших воєнних зусиль, якими керують із Брілла."},sec={{t="Перехоплені накази",b="Відряджений просто з Багряного Монастиря, кур'єр Мевен Корґал ніс ці документи до південного табору Хрестового Походу за межами Похоронного Подзвону. Видані за наказом Верховного Лорда, директиви адресовані капітанам Тірісфальського регіонального командування: Капітан Перрін має далі укріплювати південно-західну вежу й збирати відомості про нежить у Бріллі, Капітан Вашон — придушити рух нежиті біля північної вежі, а капітан Мелроуз — пильнувати кордон із Чумними Землями. Документи розкривають імена, пости й накази польових офіцерів Багряного Хрестового Походу по всіх Галявинах Тірісфалю, обертаючи звичайний кур'єрський рейс на катастрофічний витік розвідки для фанатиків."},{t="Доставка до Брілла",b="Екзекутор Аррен швидко збагнув, що місцеві сили в Похоронному Подзвоні не зможуть скористатися всією широтою цих відомостей. Натомість захоплене досьє стає для щойно пробудженого з Відступників перепусткою з Похоронного Подзвону. Пронесені на північний схід повз Маєток Холодного Вогнища до Брілла, документи передають просто в руки Екзекутора Зиґанда перед Ратушею Брілла. Із цими наказами військовий провід Відступників планує швидкі удари по командирах Багряного Хрестового Походу, що окопалися по всіх Галявинах."}},faq={{q="Хто ніс ці документи?",a="Їх ніс Мевен Корґал — гонець Багряного Хрестового Походу, якого відправили з Багряного Монастиря до табору Походу на південний схід від Похоронного Подзвону.",al={"хто ніс документи","багряний посланець","мевен корґал"}},{q="Що написано в документах?",a="У пакеті — розпорядження капітанам Тірісфальського регіонального командування Походу, видані з наказу верховного лорда: Капітан Перрін має укріпити південно-західну вежу й розвідати нежить у Бріллі, Капітан Вашон — дати раду пересуванням нежиті біля північної вежі, а Капітан Мелроуз — стежити за кордонами Чумних Земель.",al={"що в паперах","зміст документів"}},{q="Кому треба показати ці документи?",a="Після того як документи здобуто для Екзекутора Аррена в Похоронному Подзвоні, їх доручають вам — доставити Екзекуторові Зиґанду, що керує військовими справами краю біля Ратуші Брілла.",al={"куди віднести","кому віддати документи"}},{q="Чому ці документи важливі для Відступників?",a="Захоплені накази точно вказують, де стоять офіцери Походу по всіх Галявинах Тірісфалю. Це дає Відступникам перевагу: вони можуть знищити ворожих командирів і зламати бойовий дух фанатиків у краї.",al={"чому відступники їх хочуть","важливість багряних документів"}}},fp="25,328,18.718.0,17.502.0,33.150.0,41.325.0,33.178.0,50.191.0"}
P.entries["item:scarlet-insignia-ring"] = {n="Перстень з Відзнакою Багряного Хрестового Походу",s="Перстень з Відзнакою Багряного Хрестового Походу — перстень-печатка; його носить кожен, кого Багряний Хрестовий Похід розквартирував на Галявинах Тірісфалю. Для захисників Брілла з Відступників ці персні — моторошний доказ того, що ще одного фанатика стерто з землі Лордерону.",h="Перстень з Відзнакою Багряного Хрестового Походу — перстень-печатка; його носить кожен, кого Багряний...",kw={"перстень з відзнакою","багряний хрестовий похід","варіматрас","вартовий смерті берджесс","брілл","андерсіті"},ang={["faction:Horde"]="Збирання цих перснів допомагає молодій Орді закріпитися у Східних Королівствах, послаблюючи фанатичних хрестоносців довкола Андерсіті.",["race:Undead"]="Для Відступників зірвати ці персні з рук мертвих хрестоносців — пряма заява, що Тірісфаль належить мертвим, і виконання наказів Темної Леді й Варіматраса."},sec={{t="Знаки фанатизму",b="Кожен боєць Багряного Хрестового Походу на Галявинах Тірісфалю — від свіжих неофітів і ревних братів-ченців до загартованих капітанів на кшталт Мелраша й Перріна — носить перстень із відзнакою. Позначені вогняним сигілом Хрестового Походу, персні дають упізнати брата й сестру в організації, яку пожирає параноя. Та для чужинців і ворогів ці дрібнички мають зовсім інше призначення: це безпомильні розпізнавальні знаки найфанатичнішого людського недобитка Лордерону."},{t="Нагорода жахолорда",b="За прямим наказом Варіматраса, жахолорда-заступника Леді Сильвани, Вартовий Смерті Берджесс у Бріллі діяльно збирає ці персні. Відступники вважають Багряний Хрестовий Похід нестерпною пошестю, що повзе їхньою щойно відвойованою батьківщиною. Для новобранців Відступників принести до Брілла купу цих перснів — незаперечний доказ загибелі ворогів і пряме підтвердження вірності престолу Андерсіті."}},faq={{q="Хто носить ці персні з відзнакою?",a="Такий перстень носить майже кожен член Багряного Хрестового Походу на Галявинах Тірісфалю — від рядових неофітів, місіонерів, фанатиків і бійців авангарду до польових офіцерів на кшталт Капітана Перріна, Капітана Мелраша й Капітана Вашона.",al={"хто дропає персні","які хрестоносці мають персні","власники перснів"}},{q="Навіщо Вартовому Смерті Берджессу Персні з Відзнакою Багряного Хрестового Походу?",a="Вартовий Смерті Берджесс збирає персні як речовий доказ того, що багряних хрестоносців винищують. Виконуючи накази Варіматраса й Темної Леді, гарнізон Відступників у Бріллі за цими перснями судить про відданість і вправність новобранців, які очищують Лордерон від людей.",al={"навіщо збирати персні","причина доказу смерті","персні берджесса"}},{q="Що означає відзнака на персні?",a="На персні — знак Багряного Хрестового Походу, символ його священної війни за викорінення всякої нежиті в Лордероні. Хрестоносці носять його із запеклою гордістю як знак праведності, хоча одержимість штовхає їх убивати кожного, хто не належить до їхнього ордену.",al={"багряний символ","що означає відзнака","емблема персня"}},{q="Яку роль Варіматрас відіграє у збиранні цих перснів?",a="Варіматрас — головний поплічник Сильвани Віндраннер в Андерсіті. Він керує воєнними зусиллями, щоб стерти з Галявин Тірісфалю ворожих живих людей, тож знищення Багряного Хрестового Походу стає головною метою для командирів Відступників, як-от Екзекутора Зиґанда й Вартового Смерті Берджесса.",al={"накази варіматраса","чому варіматрас хоче персні","участь володаря жаху"}}},fp="21,254,18.466.0,23.428.0,31.260.0,56.292.0,45.282.0,58.301.0"}
P.entries["item:scavenged-goods"] = {n="Зібрані Припаси",s="Зібрані Припаси — різноманітні уламки покинутого спорядження й запасів, спаковані в ящики довкола Похоронного Подзвону. Щойно підняті Відступники збирають їх, щоб нескінченний потік нових новобранців було чим озброїти й одягти.",h="Зібрані Припаси — різноманітні уламки покинутого спорядження й запасів, спаковані в ящики довкола Похоронного...",kw={"зібрані припаси","спорядження","вартовий смерті салтейн","похоронний подзвін","новобранці","відступники"},ang={["race:Undead"]="Для Відступників збирання покинутого спорядження — необхідність виживання, що закріплює сувору правду: живі не дадуть їм ні допомоги, ні милосердя."},sec={{t="Самі за себе",b="Коли нові Відступники вилазять із землі на цвинтарі Похоронного Подзвону, вони прокидаються майже ні з чим, окрім зотлілого поховального савана. Сусідні поселення й королівства не дають нежиті жодної допомоги, тож вона цілком залежить від того, що зуміє роздобути. Вартовий Смерті Салтейн керує збиранням покинутої зброї, знарядь і одягу, захованих у ящиках по всьому селу, і роздає їх просто наступній партії піднятих новобранців."}},faq={{q="Для чого потрібні Зібрані Припаси?",a="Вартовий Смерті Салтейн збирає їх, щоб спорядити новобранців-Відступників, які встають із кладовища. Якби не рештки, вцілілі в довколишніх ящиках, щойно пробуджена нежить мусила б шкандибати на Галявини Тірісфалю зовсім без зброї та одягу.",al={"призначення зібраних припасів","навіщо збирати зібрані припаси","що салтейн робить з припасами"}},{q="Де знайти ці припаси?",a="Їх дістають зі скринь зі спорядженням біля хатин і серед зруйнованих будівель по всьому Похоронному Подзвону.",al={"де знайти зібрані припаси","місце зібраних припасів","де ящики зі спорядженням"}},{q="Хто просить зібрати припаси?",a="Вартовий Смерті Салтейн, офіцер із Похоронного Подзвону, посилає щойно пробуджених Відступників зібрати ці припаси — так він привчає їх покладатися на себе й готується до прибуття нових загонів.",al={"хто хоче зібрані припаси","завдання охоронця салтейна"}}},fp="15,225,22.454.0,34.236.0,28.111.0,33.178.0"}
P.entries["item:scavenger-paw"] = {n="Лапа Трупоїда",s="Лапи трупоїдів — відтяті кінцівки молодих облізлих вовків, що никають пагорбами Похоронного Подзвону. Щойно пробуджені Відступники збирають їх для місцевих доглядачів, які зшивають із них грубе захисне спорядження.",h="Лапи трупоїдів — відтяті кінцівки молодих облізлих вовків, що никають пагорбами Похоронного Подзвону.",kw={"лапа трупоїда","вовки-трупоїди","послушниця елрет","похоронний подзвін","броня","кравецтво"},ang={["profession:Tailoring"]="Грубе зшивання вовчих лап і крил кажанів, яким займається Послушниця Елрет, показує, як імпровізоване кравецтво підтримує молоді поселення Відступників.",["race:Undead"]="Прокинувшись із гниючою плоттю й майже без спорядження, ви часто починаєте зі збирання частин місцевих хижаків — це перший крок до броні, достатньої, щоб витримати небезпеки Тірісфалю."},sec={{t="Збита нашвидкуруч броня в Похоронному Подзвоні",b="Для щойно повернених у Похоронному Подзвоні ресурсів обмаль. Поки Погибель і Багряний Хрестовий Похід тиснуть на Тірісфаль, кожен клапоть шкури й кожна кістка йдуть у діло. Послушниця Елрет, якій дає настанови Жрець Тіні Сарвіс, збирає лапи місцевих вовків-трупоїдів разом із крилами кажанів, щоб шити придатний одяг і броню для розгублених Відступників, які щойно вийшли з могил."}},faq={{q="Для чого потрібні Лапи Трупоїда?",a="Їх збирає Послушниця Елрет у Похоронному Подзвоні: із сирих звірячих частин вона шиє просту броню та одяг для новачків-Відступників.",al={"призначення лапи трупоїда","для чого лапи","навіщо збирати лапи"}},{q="Де їх знайти?",a="Їх здобувають із молодих і обшарпаних трупоїдів — здичавілих вовків, що никають лісами й полями довкола Похоронного Подзвону.",al={"місце дропу лап","де взяти лапи","які вовки дропають лапи"}},{q="Хто просить ці лапи?",a="Послушниця Елрет, яка допомагає Жерцеві Тіні Сарвісу: лікує поранених новобранців, шиє спорядження й екіпірує тих, кого відправляють у бій.",al={"хто хоче лапи трупоїда","видавець завдання на лапи","новачок елрет лапи"}}},fp="13,213,27.397.0,33.148.0,23.144.0,24.140.0"}
P.entries["item:scorched-spider-fang"] = {n="Обпалене Павуче Ікло",s="Обпалені Павучі Ікла — особливий ремісничий матеріал, який добувають із хижих павуків, що чатують у вогких печерах Багнокраю. Дворфійському бронярові Фуренові Лонґбірду потрібна чимала кількість цих загартованих жаром іклів, щоб викувати міцну загартовану вогнем кольчугу для досвідчених воїнів.",h="Обпалені Павучі Ікла — особливий ремісничий матеріал, який добувають із хижих павуків, що чатують у вогких...",kw={"обпалене павуче ікло","павуки","багнокрай","фурен лонґбірд","кольчуга","ковальство"},ang={["class:Warrior"]="Зібрати п'ятдесят таких іклів — одне з виснажливих випробувань, які Фурен Лонґбірд дає, щоб перевірити вашу витривалість і здобути сировину для вашої особливої кольчуги.",["profession:Blacksmithing"]="Метод Фурена, що вплітає обпалений хітин та ікла в кільця кольчуги, дає змогу зазирнути в рідкісні дворфійські традиції бронярства, що сягають далеко за межі звичайної плавки."},sec={{t="Формула дворфійського коваля",b="Щоб викувати обладунок, який відбиває клинки й витримує жорстокі удари, звичайного заліза мало. У жвавому кварталі Стормвінда вправний коваль Фурен Лонґбірд застосовує маловідомі металургійні прийоми, поєднуючи частини звірів із рідкісними реагентами. Фурен вимагає п'ятдесят обпалених іклів велетенських павуків із боліт, бо їхня щільна, отруйна й природно загартована будова зміцнює кільця кольчуги під час гартування."},{t="Скрадачі Багнокраю",b="Ці ікла добувають просто в смертоносних павуків, що живуть у затоплених долинах і норах Багнокраю, — передусім у печерних скрадачів і скрадачів-п'явок. Попри вогке, гниле болотяне середовище, ці хижаки мають дивно затверділі, наче обпалені щелепи. Щоб зібрати стільки, скільки вимагає Фурен, доведеться спуститися в глибокі улоговини й винищити цілі рої потворної нечисті."}},faq={{q="Для чого потрібні Обпалені Павучі Ікла?",a="Їх збирають для Фурена Лонґбірда, майстра обладунків зі Стормвінда. Йому потрібно п'ятдесят ікол, а ще складники з Гір Кам'яного Кігтя й Рейзорфен Краулу, щоб викувати надзвичайно міцний нагрудник для воїнів Альянсу.",al={"що робити з обпаленими павучими іклами","призначення обпаленого павучого ікла","кому потрібні обпалені павучі ікла"}},{q="Де знайти Обпалені Павучі Ікла?",a="Їх здобувають із павуків Багнокраю — п'явкових і печерних скрадачів, що чатують у вологих норах, на схилах і в печерах розкопок.",al={"де падає обпалене павуче ікло","які павуки дропають обпалене ікло","де фармити обпалені ікла"}},{q="Навіщо ковалеві стільки павучих ікол для обладунків?",a="Фурен Лонґбірд вдається до незвичних дворфських ремісничих методів. Загартовані ікла багаті на мінерали й не бояться вогню, тож правлять за незвичайний загартувальний засіб: оброблені разом із флогістоном і рогами звірів, вони зміцнюють кільця кольчуги.",al={"чому 50 іклів","навіщо фурену павучі ікла"}},{q="Чи може будь-який шукач пригод зібрати й здати ці ікла?",a="Будь-хто, хто мандрує Багнокраєм, може вбити павуків і зібрати їхні жвала, але Фурен Лонґбірд береться за цю роботу лише для воїнів-початківців, які прагнуть заслужити свою загартовану вогнем кольчугу.",al={"чи обпалене ікло лише для воїна","хто може здати обпалені ікла"}}},fp="20,292,25.454.0,24.414.0,40.225.0,39.175.0,62.250.0,51.211.0"}
P.entries["item:scroll-of-messaging"] = {n="Сувій Сповіщення",s="Сувій Сповіщення — зачарований пергамент із особливим магічним закляттям передавання. Здобутий для гнома-інженера Ґаксима Растфіззла в Горах Кам'яного Кігтя, він має незвичне призначення: дає магічний сигнал, потрібний, щоб на відстані підірвати вибухівку.",h="Сувій Сповіщення — зачарований пергамент із особливим магічним закляттям передавання.",kw={"сувій сповіщення","ґаксим растфіззл","нґ-5","венчурна компанія","вибухівка","гори кам'яного кігтя"},ang={["faction:Alliance"]="Сувій відіграє важливу роль, допомагаючи агентам Альянсу зірвати роботу машин Венчурної Компанії й спинити спустошення природи в Горах Кам'яного Кігтя.",["profession:Engineering"]="Як і годиться гномській винахідливості, цей сувій показує, як теоретичну чарівну магію можна пристосувати під дистанційний приймач для механічних підривів."},sec={{t="Вибухове повідомлення",b="Нібито це чарівний сувій для зв'язку на великій відстані, але Ґаксим Растфіззл задумав для Сувою Сповіщення куди руйнівніше застосування. Поєднавши його закляття передавання з нестійкими зарядами НҐ-5, гном планує створити вибухівку з дистанційним підривом. Вибух має влаштувати потужне відволікання на лісозаготівлях Венчурної Компанії в Горах Кам'яного Кігтя й дати агентам час прослизнути повз охорону та викрасти власні інженерні креслення компанії й таємне листування."}},faq={{q="Для чого потрібен Сувій Сповіщення?",a="Хоч на сувої записано закляття для передавання повідомлень, Ґаксим Растфіззл використовує його магію, щоб змайструвати дистанційний детонатор. Разом із вибухівкою NG-5 сувій дає змогу підірвати заряд з безпечної відстані.",al={"використання сувою сповіщення","що робить сувій сповіщення","чому ґаксім хоче сувій"}},{q="Хто отримує цей сувій?",a="Сувій доставляють Ґаксимові Растфіззлу — гномові-інженерові, союзникові Альянсу, що працює в Горах Кам'яного Кігтя.",al={"хто отримує сувій сповіщення","куди нести сувій сповіщення","одержувач сувою"}},{q="Навіщо Ґаксимові дистанційна вибухівка?",a="Ґаксимові потрібен гучний відволікальний маневр на місцевому об'єкті Венчурної Компанії. Хаос дасть змогу прокрастися на їхню територію, викрасти цінні інженерні креслення й забрати документи, щоб зупинити хижацьку вирубку лісу.",al={"причина вибухівки ґаксіма","чому підірвати венчур","відволікання стоунталон"}},{q="Що таке NG-5?",a="NG-5 — вибуховий хімічний заряд, яким користується Ґаксим Растфіззл. У парі з магічним сигналом, записаним на Сувої Сповіщення, він стає саморобним пристроєм для дистанційного підриву.",al={"нґ-5","що таке нґ-5","вибухівка нґ5"}}},fp="19,268,18.543.0,41.200.0,25.118.0,39.244.0,13.186.0"}
P.entries["item:sea-creature-bones"] = {n="Кістки Морського Створіння",s="Кістки Морського Створіння — зразки скелетів, зібрані з величезних туш морських тварин, яких викидає на оповитий імлою берег Темного Узбережжя. Їх відсилають просто до Храму Місяця в Дарнасусі: ці рештки — головне в розслідуванні того, що змушує велетенських звірів викидатися на пляжі.",h="Кістки Морського Створіння — зразки скелетів, зібрані з величезних туш морських тварин, яких викидає на...",kw={"кістки морського створіння","ґвенніт блай'леґґонд","храм місяця","молотильники","мурлоки сірої імли","край імли"},ang={["class:Druid"]="Незбагненна загибель давніх морських хижаків свідчить про глибоке збурення у водах біля Калімдору, і це тривожить кожного охоронця, відданого рівновазі природи.",["race:NightElf"]="Раптові масові викиди на береги Темного Узбережжя глибоко тривожать нічних ельфів, які шанують гармонію природи й бачать у цих випадках темне знамення, що вимагає уваги Храму Місяця."},sec={{t="Знамення на березі",b="Останнім часом на вкритих туманом пляжах Темного Узбережжя тривожно почастішали випадки, коли величезні морські створіння — серед них і велетенські молотильники, значно більші за тих, що водяться на місцевих мілинах, — викидаються на мілководдя й гинуть. Нічні ельфи вбачають у цьому зловісне знамення. Ґвенніт Блай'Леґґонд, дослідниця, яку Храм Місяця відрядив до Обердайна, збирає кісткові зразки цих викинутих на берег левіафанів, щоб відправити їх гіпогрифом до Дарнасуса для ретельного вивчення."},{t="Падло й падальники",b="Здобувати ці кістки небезпечно, бо величезні туші неминуче приваблюють місцевих падальників. Прибережні мурлоки Сірої Імли часто обсідають мертвих і конаючих левіафанів, пожирають рештки й люто боронять свої годівлі. Хоча мурлоки надто слабкі, щоб самотужки полювати на таких велетнів, їхня присутність біля Краю Імли змушує дослідників і шукачів пригод пробиватися крізь зграї падальників, щоб здобути придатні уламки кісток для вивчення."}},faq={{q="Чому цих створінь викидає на берег?",a="Точна причина досі невідома. Поодинокі викиди на берег трапляються й у природі, але їхнє раптове й різке почастішання жриці Елуни вважають неприродним і тривожним — тож вони взялися офіційно це розслідувати.",al={"чому викидає створінь на берег","мертві кити темного узбережжя","чому створіння на березі"}},{q="Кому потрібні ці кістки?",a="Ґвенніт Блай'Леґґонд, дослідниця з Обердайна, збирає кістки для Храму Місяця в Дарнасусі, де вчені та жриці сподіваються з'ясувати, що непокоїть море.",al={"хто бере кістки","хто здає кістки морського створіння","ґвеннит темне узбережжя"}},{q="Це мурлоки вбили цих велетенських звірів?",a="Ні. Місцеві мурлоки з племені Сірої Імли надто слабкі, щоб здолати таких великих морських звірів. Вони лише падальники, що збираються юрбами поласувати тушами, коли тих викидає на берег.",al={"чи мурлоки вбили молотарників","чи сірі мурлоки вбили морського звіра"}},{q="Звідки беруть ці кістки?",a="Їх добувають просто з величезних туш, викинутих на берег Темного Узбережжя, — особливо на піски на південь від Обердайна та вздовж Краю Імли.",al={"де знайти кістки морського створіння","місця викинутих морських створінь"}}},fp="18,328,22.507.0,22.505.0,39.221.0,22.208.0,40.195.0,35.165.0"}
P.entries["item:sea-turtle-remains"] = {n="Останки Морської Черепахи",s="Останки Морської Черепахи — зразки скелетів, урятовані з туш велетенських морських черепах на березі Темного Узбережжя. Для дослідників нічних ельфів в Обердайні, що розслідують тривожне почастішання морських викидів на берег, це важливі зразки.",h="Останки Морської Черепахи — зразки скелетів, урятовані з туш велетенських морських черепах на березі Темного...",kw={"останки морської черепахи","ґвенніт блай'леґґонд","храм місяця","тельдрассил","мурлоки","темне узбережжя"},ang={["class:Druid"]="Протиприродна загибель диких морських левіафанів свідчить про глибшу порчу, що порушує рівновагу природи на узбережжі Калімдору.",["race:NightElf"]="Масові викиди морських тварин просто біля берегів ваших предків — лиховісна прикмета, тим паче що підозри ведуть до вод, які оточують Тельдрассил."},sec={{t="Тривожні викиди",b="Велетенські морські створіння почали викидатися на берег уздовж усіх оповитих імлою берегів Темного Узбережжя, а інші лежать під водою неподалік, біля затонулих кораблів. Ґвенніт Блай'Леґґонд, що працює в Обердайні, наглядає за збиранням уламків скелетів і тканин із цих туш. Храм Місяця в Дарнасусі нагально вимагає цих зразків, бо побоюється, що звірі, можливо, тікають від протиприродного збурення у водах довкола щойно вирослого Світового Дерева — Тельдрассилу."},{t="Падальники мілин",b="Здобувати ці останки — небезпечна справа. Прибережні племена мурлоків постійно збираються довкола величезних туш, обгризають кістки дочиста й гніздяться поруч. Ученим потрібні свіжі уламки кісток і тканин, доки падальники не знищили всіх доказів, що могли б пояснити смертельну міграцію цих створінь."}},faq={{q="Для чого потрібні ці останки?",a="Останки збирає Ґвенніт Блай'Леґґонд в Обердайні. Вона готує їх для вчених і жриць Храму Місяця в Дарнасусі, які намагаються з'ясувати, чому вздовж Темного Узбережжя гине стільки морських створінь.",al={"чому збирати останки черепахи","використання кісток черепахи","завдання морської черепахи темне узбережжя"}},{q="Чому морські черепахи викидаються на берег Темного Узбережжя?",a="Точну причину ще з'ясовують, але дослідники побоюються, що морські мешканці тікають від чогось тривожного у водах довкола Тельдрассила. Ці викиди — не поодинокі випадки, а ознака великого лиха для всього довкілля.",al={"чому черепахи гинуть","викидання черепах темного узбережжя","викинуті морські створіння"}},{q="Де знайти ці туші?",a="Велетенські кістяки морських черепах розкидані по всьому узбережжю Темного Узбережжя: одні лежать на мілководді біля затонулих кораблів на захід від Обердайна, інші — на пляжах серед таборів мурлоків.",al={"місця останків черепахи","де знайти скелет морської черепахи"}},{q="Хто вивчає ці останки?",a="Ґвенніт Блай'Леґґонд, дослідниця з Обердайна, збирає знахідки й надсилає докладні звіти просто до Сестринства Елуни в Храмі Місяця в Дарнасусі.",al={"хто хоче останки","ґвеннит блайлеґонд"}}},fp="18,241,19.497.0,26.321.0,32.236.0,53.229.0,32.204.0,30.176.0"}
P.entries["item:sealed-description-of-thredd-s-visitor"] = {n="Запечатаний Опис Відвідувача Тредда",s="Запечатаний Опис Відвідувача Тредда — конфіденційне донесення Наглядача Телвотера про загадкового чоловіка, який відвідував ув'язненого ватажка Дефіас Базіла Тредда у В'язниці Стормвінда. Цей опис допомагає вистежити таємного агента, що непомітно рухається політичними й злочинними колами Стормвінда.",h="Запечатаний Опис Відвідувача Тредда — конфіденційне донесення Наглядача Телвотера про загадкового чоловіка...",kw={"запечатаний опис відвідувача тредда","наглядач телвотер","базіл тредд","марзон","ґреґор лесковар","матіас шоу"},ang={["class:Rogue"]="Ця справа — наочний урок ремесла: вигадані імена, підроблені документи й відвідини камер — усе виходить на світло, коли Матіас Шоу звіряє описи зовнішності з даними SI:7.",["faction:Alliance"]="Документ оголює тривожні вади у внутрішній безпеці Стормвінда й доводить, що змовники можуть спокійно проходити крізь браму В'язниці з підробленими документами."},sec={{t="Таємничий покровитель",b="Роками в'язень Базіл Тредд сидів у своїй камері без жодних відвідувачів. Усе змінилося, коли раз чи двічі на тиждень до нього став приходити небалакучий чоловік із цілком справжніми документами. Помітивши ці незвичні візити, Наглядач Телвотер склав опис зовнішності чоловіка, документи якого називали його «Маелік». Наглядач запечатав опис, щоб жодне стороннє око не прочитало його, доки за справу не візьмуться належні слідчі."},{t="Від каменярів до шпигунів",b="Коли опис принесли міському архітекторові Баросові Алекстону, той не впізнав відвідувача й лише смутно запідозрив, що це може бути агент, пов'язаний із повстанням Дефіас. Алекстон одразу переслав запечатаний конверт Майстрові Матіасу Шоу, очільникові розвідки Стормвінда, SI:7. Шоу вмить розкусив обман: опис відповідав смертельно небезпечному найманцеві, що діє під різними іменами, зокрема Марзон, і нині робить брудну роботу для Лорда Ґреґора Лесковара."}},faq={{q="Хто склав цей опис?",a="Документ написав і запечатав Наглядач Телвотер, головний наглядач В'язниці Стормвінда. Його насторожило, що до ув'язненого ватажка Братства Дефіас Базіла Тредда почав регулярно навідуватися невідомий.",al={"хто написав","автор опису","хто склав записку"}},{q="Хто цей відвідувач, описаний у документі?",a="Він показав документи на ім'я Маелік. Наглядач Телвотер записав його прикмети, щоб слідчі могли встановити його особу.",al={"хто відвідував тредда","хто такий маелік","особа відвідувача"}},{q="Навіщо відвідувач зустрічався з Базілом Треддом?",a="Телвотера насторожило, що після багатьох років без жодного відвідувача до Тредда раптом почали регулярно приходити. Мету цих візитів розслідують за допомогою запечатаного опису.",al={"чому відвідувач прийшов до тредда","мета відвідувача тредда"}},{q="Куди треба віднести цей запечатаний документ?",a="Спершу документ несуть міському архітекторові Баросу Алекстону в Стормвінді. Алекстон, переглянувши опис, не впізнає цієї людини й просить вас передати документ безпосередньо Майстрові Матіасу Шоу в штаб-квартирі SI:7 у Старому Місті.",al={"куди нести","кому потрібен опис"}}},fp="38,322,19.481.0,25.494.1,27.212.0,42.130.2,46.163.2,49.244.1"}
P.entries["item:sealed-envelope"] = {n="Запечатаний Конверт",s="У цьому щільно запечатаному пакеті — таємні технічні документи Венчурної Компанії та викрадені креслення. Зібраний вигнаним гоблінським інженером Фіззіксом, він містить закриті розробки, які мають дістатися Спаттервалву в Раджеті.",h="У цьому щільно запечатаному пакеті — таємні технічні документи Венчурної Компанії та викрадені креслення.",kw={"запечатаний конверт","фіззікс","спаттервалв","раджет","венчурна компанія","суперкосар 6000","картель стімвідл"},ang={["faction:Horde"]="Несучи ці папери на південь із Гір Кам'яного Кігтя, ви допомагаєте нейтральним гоблінам Раджета підточити агресивні, хижацькі лісозаготівлі Венчурної Компанії.",["profession:Engineering"]="У конверті — технічні креслення Суперкосаря 6000, одного з найруйнівніших і найприбутковіших механічних пристроїв, створених гоблінськими руками."},sec={{t="Корпоративне шпигунство",b="Коли гоблінського інженера Фіззікса раптово вигнали з лісозаготівель Венчурної Компанії в Горах Кам'яного Кігтя, він пішов не з порожніми руками. Напхавши в цей конверт внутрішні посібники, робочі настанови й технічні описи, він зумів винести таємниці компанії просто під носом у колишніх наглядачів. Найціннішими серед викрадених записів є технічні креслення Суперкосаря 6000 — нищівної промислової машини для суцільної вирубки."},{t="Доставка до Раджета",b="Замість ховати небезпечні торгові таємниці, Фіззікс посилає пакет на південь, Спаттервалву — інженерові з нейтрального гоблінського порту Раджет. Конкуренти з картелю Стімвідл не мають до Фіззікса ні особливої прихильності, ні довіри, але інженерна цінність креслень у конверті незаперечна. Документи відкривають чітке уявлення про механічну винахідливість Венчурної Компанії й дають незалежним інженерам змогу скористатися її передовими технологіями лісозаготівлі."}},faq={{q="Що в Запечатаному Конверті?",a="У конверті — внутрішні документи Венчурної Компанії, технічні посібники з експлуатації та креслення лісорубної машини «Суперкосар 6000». Усе це Фіззікс прихопив, поспіхом тікаючи.",al={"вміст конверта","що в запечатаному конверті","предмети запечатаного конверта"}},{q="Хто підготував цей пакет?",a="Конверт підготував Фіззікс — ображений гоблін-інженер, якого Венчурна Компанія вигнала зі своєї лісозаготівлі в Горах Кам'яного Кігтя.",al={"хто підготував конверт","хто дав запечатаний конверт","конверт фіззікса"}},{q="Кому він призначений?",a="Його адресовано Спаттервалву, гобліну-майстрові, що живе в портовому містечку Раджет у Пустках.",al={"кому конверт","куди конверт","доставка спаттервалву"}},{q="Навіщо Спаттервалву ці документи?",a="Хоч Спаттервалв недолюблює Венчурну Компанію й насторожено ставиться до Фіззікса, документи містять цінні вдосконалення та схеми, завдяки яким сторонні майстри можуть зрозуміти й перейняти потужні механічні розробки компанії.",al={"навіщо спаттервалву документи","технології венчур рятчет"}}},fp="15,232,19.494.0,19.506.0,35.206.0,25.165.0,30.107.0,43.227.0"}
P.entries["item:sealed-note-to-elling"] = {n="Запечатана Записка до Еллінга",s="Запечатана Записка до Еллінга — конфіденційне послання, яке написав стормвіндський рибалка Йорґен. Призначена для Еллінга Тріаса, власника сирної крамниці Тріаса, вона стає однією з перших ланок у тихому розслідуванні довкола зниклого дипломата.",h="Запечатана Записка до Еллінга — конфіденційне послання, яке написав стормвіндський рибалка Йорґен.",kw={"запечатана записка до еллінга","еллінг тріас","йорґен","торговий квартал","зниклий дипломат","стормвінд"},ang={["class:Rogue"]="Розбійники, обізнані з тіньовими мережами Стормвінда, знають, що Еллінг Тріас — далеко не просто торговець чеддером, тож це делікатне листування для них — звичайна частина ремесла.",["faction:Alliance"]="Доставивши послання Йорґена, ви безпосередньо служите Короні й просуваєте розслідування, від якого залежить політичний спокій Стормвінда."},sec={{t="Тиха передача",b="Пронести запечатану записку жвавими вулицями Стормвінда може здатися буденною справою, та суворі вказівки Йорґена ясно показують, що на кону: віддати пергамент просто в руки Еллінгові Тріасу й мовчати. Назовні Тріас — лагідний торговець сиром у Торговому Кварталі, проте це таємне послання спрямовує розслідування про зниклого дипломата просто до його прилавка, натякаючи на мережі, значно глибші за торгівлю молочним крамом."}},faq={{q="Що написано в запечатаній записці?",a="Записка лишається запечатаною, доки її не вручать Еллінгу Тріасу. У ній — звіт Йорґена й рекомендація, яка спрямовує посланця до Тріаса для глибшого розслідування зникнення дипломата.",al={"вміст записки","що в записці","текст листа"}},{q="Чому продавець сиру отримує таємні донесення?",a="Еллінг Тріас тримає непоказну сирну крамничку в Торговому Кварталі як прикриття. Але під фартухом у нього розгалужена таємна мережа очей і вух по всьому місту, тож для делікатних розслідувань він незамінний.",al={"чому торговець сиром","чому сирний магазин","чи трайас шпигун"}},{q="Хто такий Йорґен?",a="Йорґен — рибалка, якого можна знайти біля води в Долині Героїв у Стормвінді. Його щось пов'язує з Еллінгом Тріасом і Єпископом ДеЛаве, і єпископ звертається до нього в делікатних справах, що мають лишатися подалі від чужих очей.",al={"хто написав записку","лор йорґена","вартовий йорґен"}},{q="У чому суть справи про зниклого дипломата?",a="Дипломат зі Стормвінда, якого відправили до Терамора на зустріч із Джайною Праудмур, так і не прибув, і королівська влада тихо перевіряє кожен підозрілий слід, щоб не сіяти паніки на вулицях.",al={"лор зниклого дипломата","хто дипломат","чому зник дипломат"}}},fp="21,244,16.451.0,39.188.0,53.251.0,14.221.0,40.191.0"}
P.entries["item:sealed-note-to-watcher-backus"] = {n="Запечатана Записка Вартовому Бакусу",s="Запечатана Записка Вартовому Бакусу — конфіденційне послання, яке написав торговець сирами й інформатор Еллінг Тріас. Адресована вартовому Нічної Варти, що патрулює дорогу за Даркширом, вона нагадує про давню особисту послугу й просить зібрати відомості про діяльність Дефіас у Сутінколіссі.",h="Запечатана Записка Вартовому Бакусу — конфіденційне послання, яке написав торговець сирами й інформатор...",kw={"запечатана записка вартовому бакусу","вартовий бакус","еллінг тріас","нічна варта","даркшир","дефіас"},ang={["class:Rogue"]="Тріас робить звичайного вартового місцевим інформатором — хрестоматійний приклад того, як тихо збирати відомості далеко за міськими мурами.",["faction:Alliance"]="Послання показує, як неофіційне шпигунство й особисті зв'язки тримають докупи потріпані землі Альянсу, коли офіційні канали не працюють."},sec={{t="Слово для Варти",b="Коли перші зачіпки в справі зниклого дипломата в Стормвінді заводять у глухий кут, торговець сирами Еллінг Тріас вирішує оминути свого впертого інформатора Йорґена й скористатися власною мережею. Він пише цей запечатаний воском лист Вартовому Бакусу з Нічної Варти, що несе службу в Сутінколіссі. Тріас посилає шукача пригод на південь крізь похмурий ліс, щоб той доставив лист особисто, — давні добрі стосунки з Бакусом допоможуть дізнатися про будь-які сліди Дефіас поблизу Даркширу."},{t="Далекі очі Тріаса",b="Начебто звичайний купець, що продає добрі сири в Торговому Кварталі, Тріас листується з міським вартовим у Сутінколіссі — і це показує, наскільки широка його розвідувальна мережа. Нічна Варта Даркширу відома своєю замкненістю й недовірою до чужих: вона виживає під постійною загрозою нежиті й лютих звірів. Та тепла відповідь Бакуса на записку Тріаса доводить, що цей на вигляд скромний крамар має справжню відданість і повагу далеко за мурами Стормвінда."}},faq={{q="Хто написав цю записку?",a="Записку написав Еллінг Тріас, власник крамниці «Сири Тріаса» в Торговому Кварталі Стормвінда, який потай працює вправним шпигуном і торговцем відомостями.",al={"хто написав запечатану записку вартовому бакусу","автор записки","хто дає записку"}},{q="Чому її надсилають Вартовому Бакусу?",a="Вартовий Бакус — член Нічної Варти Даркширу й надійний знайомий Еллінга Тріаса. Тріасові треба, щоб той поділився всіма місцевими спостереженнями й чутками про діяльність Братства Дефіас у Сутінколіссі.",al={"хто такий вартовий бакус","чому слати бакусу","яка роль бакуса"}},{q="Де знайти Вартового Бакуса?",a="Вартовий Бакус патрулює дорогу на північ одразу за Даркширом у Сутінколіссі, наглядаючи за лісовими підступами до містечка.",al={"де бакус","місце вартового бакуса","знайти вартового бакуса"}},{q="Що стається після того, як записку доставлено?",a="Упізнавши ім'я Тріаса й відчувши його довіру, Бакус відкидає звичну обережність щодо мандрівних шукачів пригод і погоджується допомогти розслідувати підозрілі події в довколишніх лісах.",al={"що каже бакус","після доставки записки"}}},fp="29,286,20.471.0,25.489.1,20.167.0,39.203.0,34.140.0,41.187.0"}
P.entries["item:searing-collar"] = {n="Пекучий Нашийник",s="Пекучі Нашийники — обрядові обручі, які носять члени культу Палаючого Клинка, що ховаються в Череп-скелі в Дуроторі. Розжарені, щоб палити плоть носія, вони служать культистам для налаштування на демонічні сили.",h="Пекучі Нашийники — обрядові обручі, які носять члени культу Палаючого Клинка, що ховаються в Череп-скелі в...",kw={"пекучий нашийник","палаючий клинок","череп-скеля","культ","марґоз","дуротар"},ang={["class:Warlock"]="Чорнокнижники впізнають у Пекучих Нашийниках грубі, але дієві провідники, що спрямовують скверну просто в смертну плоть.",["race:Orc"]="Для орків, які прагнуть звільнити свій народ від спадщини демонічного рабства, культисти з такими нашийниками на порозі Дуротару — похмуре нагадування, що тінь нікуди не поділася."},sec={{t="Знаряддя скверни",b="У тінистій печері Череп-скелі, одразу на схід від Оргріммара, Палаючий Клинок збирається на темні обряди. Культисти, неофіти й горлорізи культу надягають на шиї Пекучі Нашийники, добровільно піддаючи себе пекучому жару, що таврує й обпалює шкіру. Відлюдник Марґоз вивчає ці жорстокі пристрої і припускає, що відчуття опіку й темні чари, вкладені в метал, напряму налаштовують носіїв на демонічні енергії. Дослідження нашийників показує: це вагомий канал демонічної скверни, що просочується в орче суспільство просто під носом в Орди."}},faq={{q="Що таке Пекучий Нашийник?",a="Пекучий Нашийник — ритуальний обруч, який культисти Палаючого Клинка носять на шиї. Він впікається в плоть власника й пропускає крізь неї демонічну енергію, налаштовуючи культиста на темну магію.",al={"що таке пекучі нашийники","історія пекучого нашийника","що робить нашийник"}},{q="Хто носить ці нашийники?",a="Їх носять члени культу Палаючого Клинка, що ховаються в Череп-скелі: культисти, фанатики, головорізи, учні й неофіти.",al={"хто їх використовує","хто дропає пекучі нашийники","нашийники палаючого клинка"}},{q="Навіщо культисти обпікають власну плоть?",a="Палаючий Клинок використовує розпечений метал як ритуальний посередник. Терплячи опіки й демонічні чари, культисти налаштовують свої тіла й душі на демонічну силу.",al={"чому палити свою плоть","чому носити пекучий нашийник","призначення нашийника"}},{q="Хто хоче оглянути Пекучі Нашийники?",a="Марґоз, дослідник, що стоїть табором у Дуротарі, збирає нашийники, щоб вивчити їхні чари й розкрити таємниці темного впливу Палаючого Клинка.",al={"кому потрібні пекучі нашийники","хто вивчає нашийники","нашийники марґоза"}}},fp="14,216,25.614.0,25.179.0,24.141.0,41.175.0,41.159.0"}
P.entries["item:searing-coral"] = {n="Пекучий Корал",s="Пекучий Корал — рідкісна стійка мінеральна речовина, яку добувають із живих залізних коралів біля узбережжя Багнокраю. Його цінують винахідники й ковалі: завдяки дивовижним тепловим властивостям його можна виплавити й перекувати на захисний обладунок.",h="Пекучий Корал — рідкісна стійка мінеральна речовина, яку добувають із живих залізних коралів біля узбережжя...",kw={"пекучий корал","залізний корал","багнокрай","гавань менетіл","клокморт спаннерспан","фурен лонґбірд","ковальство"},ang={["class:Warrior"]="Збір Пекучого Коралу — важливий крок, щоб довести свою відданість майстрам обладунків Айронфорджа; нагородою стане нагрудник, викуваний на замовлення для важких боїв на передовій.",["profession:Blacksmithing"]="Застосування Пекучого Коралу показує винахідливе поєднання гномської кмітливості й класичного дворфійського ковальства, що перетворює океанські мінерали на загартовані лати."},sec={{t="Рідкісний прибережний скарб",b="Пекучий Корал росте тільки в холодних океанських водах уздовж узбережжя на південь від Гавані Менетіл у Багнокраї. Хоч цей незвичайний морський організм процвітає в холодній солоній воді, з нього добувають багату на мінерали речовину, що витримує надзвичайний жар. Збирачі ризикують у підступному прибої Багнокраю серед прибережних хижаків, щоб відколупати затверділі нарости."},{t="Застосування в ковальстві",b="Пекучий Корал лежить поза звичною дворфійською металургією, але привернув увагу допитливих умів Айронфорджа. Гномські майстри на кшталт Клокморта Спаннерспана переймають прийоми досвідченого майстра обладунків Фурена Лонґбірда: виплавляють корал і вковують його просто в металеві сплави, створюючи легкі, надзвичайно міцні обладунки для молодих воїнів."}},faq={{q="Де росте Пекучий Корал?",a="Пекучий Корал добувають на морському дні біля берега на південь від Гавані Менетіл у Багнокраї. Він росте серед природних заростей залізного коралу під мілкими прибережними водами.",al={"місце пекучого коралу","де знайти пекучий корал","місце залізного коралу"}},{q="Кому в Айронфорджі потрібен Пекучий Корал?",a="Пекучий Корал шукає Клокморт Спаннерспан, гном-майстер із Містечка Майстрів в Айронфорджі. Він експериментує з ковальськими прийомами, яких навчився в легендарного дворфа-зброяра Фурена Лонґбірда.",al={"хто використовує пекучий корал","корал клокморта спаннерспана","корал фурена лонґбірда"}},{q="Як можна викувати обладунок із коралу?",a="Пекучий Корал має надзвичайно щільну, жаростійку будову. Якщо розплавити його в горні й вкувати в металевий сплав, він зміцнює складену броню, і спорядження виходить надзвичайно міцним.",al={"кування з коралу","чи можна виплавити корал","металургія пекучого коралу"}},{q="Чи небезпечно добувати Пекучий Корал?",a="Сам корал зібрати безпечно, щойно його знайдено, але для цього доведеться плисти відкритими водами біля узбережжя Багнокраю, де нишпорять дикі мурлоки й агресивні водяні звірі.",al={"чи гарячий пекучий корал","збір залізного коралу"}}},fp="13,254,23.353.0,23.367.0,30.193.0,37.206.0,35.213.0,38.188.0"}
P.entries["item:secure-crate"] = {n="Захищений Ящик",s="Захищений ящик — щільно напакована посилка із зіллями, алхімічними реагентами й іншим крамом для Східних Королівств. Її доручають мандрівникам у Пустках, і вона має встигнути до гамірного порту Раджет на найближчий відплив.",h="Захищений ящик — щільно напакована посилка із зіллями, алхімічними реагентами й іншим крамом для Східних...",kw={"захищений ящик","раджет","діззівіг","картель стімвідл","торгівля","пустки"},ang={["faction:Horde"]="Перевозячи вантажі через Раджет, мандрівники Орди бачать, наскільки важливі нейтральні торгові зв'язки, які гоблінські порти забезпечують між Калімдором і Східними Королівствами.",["profession:Herbalism"]="Ретельне пакування реагентів показує, наскільки алхіміки й травники по обидва боки моря залежать від прикордонних торгових шляхів для обміну сировиною."},sec={{t="Вантаж гінця",b="Торгові шляхи між Калімдором і Східними Королівствами тримаються на хиткому ланцюжку гінців, пустельних караванів і гоблінських купецьких кораблів. Коли каравани через Пустки не встигають вирушити вчасно, тендітні вантажі на кшталт цього захищеного ящика доводиться нести до узбережжя вільним мандрівникам. Усередині — алхімічний крам, зілля та різні реагенти для партнерів по той бік Великого моря. Вміст делікатний і цінний, тож ящик надійно запечатано, щоб він пережив і посушливі стежки Пусток, і солоні бризки морської подорожі."},{t="Через порт Раджет",b="Сухопутна частина шляху ящика закінчується на пристані Раджета, якою опікується Начальник Пристані Діззівіг. Гавань Раджета — головні нейтральні ворота, через які припаси вирушають за море, наприклад до Бухти Чорної Води. Ведучи облік для картелю Стімвідл, Діззівіг пильнує, щоб і дрібні посилки, і важкі вантажі були належно вписані в декларацію й завантажені на найближчий корабель, — так тримається життєво важливий торговий зв'язок між Старим Світом і рубежем."}},faq={{q="Що в Захищеному Ящику?",a="У ящику — делікатний набір зілль, алхімічних реагентів та інших припасів для партнерів у Східних Королівствах.",al={"вміст ящика","що в ящику","предмети захищеного ящика"}},{q="Куди везуть ящик?",a="Пішки його треба доставити Начальникові Пристані Діззівігу на причалах Раджета. Звідти Діззівіг відправляє його торговим судном через море до Бухти Чорної Води в Старому Світі.",al={"місце призначення ящика","куди захищений ящик"}},{q="Чому ящик доручили шукачеві пригод, а не каравану?",a="Відправник не мав часу сам вирушити до Раджета, а торговий караван уже поїхав, тож довелося найняти посланця, щоб устигнути до відпливу.",al={"чому ящик в мене","пропущений караван"}},{q="Хто приймає ящик у Раджеті?",a="Начальник Пристані Діззівіг приймає ящик на причалах Раджета, записує його до вантажного журналу й ставить на борт наступного корабля, що відпливає з припливом.",al={"хто отримує ящик","ящик діззівіґа"}}},fp="12,268,17.595.0,27.488.0,32.138.0,30.191.0,62.176.0,31.159.0"}
P.entries["item:senir-s-report"] = {n="Звіт Сеніра",s="Звіт Сеніра — депеша, яку написав горянин Сенір Вайтбірдий про загрозу від тролів Морозогривів в Дун Мороґу. У ній — відомості, зібрані з королівського наказу, і призначена вона Сенаторові Баріну Редстоуну в Айронфорджі.",h="Звіт Сеніра — депеша, яку написав горянин Сенір Вайтбірдий про загрозу від тролів Морозогривів в Дун Мороґу.",kw={"звіт сеніра","сенір вайтбірдий","сенатор барін редстоун","тролі морозної гриви","король маґні бронзбірд","сенат","дун мороґ"},ang={["faction:Alliance"]="Доставляючи Звіт Сеніра, ви допомагаєте обороні Дун Мороґа й водночас лавіруєте в колючій внутрішній політиці правлячої верхівки Айронфорджа.",["race:Dwarf"]="Звіт Сеніра відкриває гострий політичний розкол між указами Короля Маґні Бронзбірда й традиційною владою, якої вимагає Сенат в Айронфорджі."},sec={{t="Королівський наказ",b="Цей польовий звіт, складений після розвідувальних вилазок проти тролів Морозогривів, що засіли серед скель Дун Мороґа, містить спостереження горян для дворфійського Сенату. Сенір Вайтбірдий, що несе службу в холодних передгір'ях, написав документ і доклав до нього звіт свого брата Ґреліна про Долину Холодного Хребта, де сказано, що Ґрелін діяв із дозволу Короля Маґні Бронзбірда. Сенір доручає шукачам пригод доставити звіт просто Сенаторові Баріну Редстоуну на Високий Престол Айронфорджа — і обачно радить гінцям не згадувати, скільки сторонньої допомоги знадобилося, щоб його скласти."},{t="Тертя біля Високого Престолу",b="Щойно документ потрапляє до королівського двору, здіймається буря. Читаючи звіт, Сенатор Барін Редстоун обурений не лише змістом про загрозу від тролів, а й королівською печаткою влади на ньому. Те, що Маґні обійшов нагляд законодавців, а розвідники діяли за неконтрольованими королівськими наказами, роздмухує давнє невдоволення в дворфійському Сенаті й показує політичну напругу між рішучим правлінням Короля Маґні та ображеними сенаторами, які вимагають дотримання процедур."}},faq={{q="Що таке Звіт Сеніра?",a="Це офіційне письмове донесення горянина Сеніра Вайтбірда з підсумками його розвідки щодо тролів-Морозогривів у Дун Мороґу, яке треба доставити просто до дворфського Сенату в Айронфорджі.",al={"звіт сеніра","що це за звіт","звіт"}},{q="Хто має отримати звіт?",a="Звіт адресовано Сенаторові Баріну Редстоуну — буркотливому дворфському політикові, що перебуває біля трону Короля Маґні Бронзбірда на Високому Престолі Айронфорджа.",al={"хто отримує звіт","кому віддати звіт","одержувач звіту"}},{q="Чому Сенатор Редстоун так лютує, читаючи його?",a="Сенатор Редстоун у люті, бо вкладений звіт Сенірового брата, Ґреліна Вайтбірда, показує: Ґрелін діяв з волі Короля Маґні, не порадившись із дворфським Сенатом. Редстоуна обурює, що корона одноосібно вирішує питання оборони без схвалення сенаторів.",al={"чому барін сердиться","чому сенатор злий","реакція редстоуна"}},{q="Чому Сенір просить вас не згадувати, що ви йому допомагали?",a="Сенір Вайтбірд хоче, щоб начальство вірило, ніби небезпечну розвідку на засніжених пагорбах він провів сам-один: так він береже свою славу старанного й умілого горянина.",al={"чому мовчати","таємниця сеніра","заслуга сеніра"}}},fp="14,242,17.601.0,25.516.1,23.216.0,38.153.0,56.296.1,50.201.0"}
P.entries["item:serena-s-head"] = {n="Голова Серени",s="Голова Серени — моторошний трофей, здобутий у праматері гарпій Сухих Пагорбів на півночі Пусток. Дарсок Свіфтдаґґер із Перехрестя вимагав її як доказ смерті Серени, щоб виставити на возах із припасами Орди — суворе застереження проти нових нападів із повітря.",h="Голова Серени — моторошний трофей, здобутий у праматері гарпій Сухих Пагорбів на півночі Пусток.",kw={"голова серени","серена бладфезер","гарпії","відьмокрили","дарсок свіфтдаґґер","перехрестя"},ang={["class:Rogue"]="Дарсок Свіфтдаґґер цінує чисту, безжальну роботу й хвалить найманців, які вміють прослизнути до ворожих гнізд і без вагань стратити ціль.",["faction:Horde"]="Каравани — це кровоносні судини, що поєднують Дуротар із Малгором і далекими заставами; голова Серени на возах із припасами — недвозначне послання про владу Орди над дикими пустищами."},sec={{t="Застереження на дорозі",b="Гарпії-Відьмокрили з Сухих Пагорбів давно дошкуляли торгівлі на півночі Пусток, але під проводом Серени Бладфезер їхні напади стали особливо лютими. Вона нападала на шляхи постачання Орди з особистої помсти за сестру, яка загинула від руки володаря звірів Рекссара. Щоб назавжди зламати дух зграї, орк-розбійник Дарсок Свіфтдаґґер наказав вистежити Серену. Він не хотів, щоб її смерть минула непоміченою, тож зажадав її відтяту голову, аби прилаштувати на першому ж каравані, що вирушить у дорогу, — як суворе криваве застереження кожній гарпії, що стежить зі скель угорі."}},faq={{q="Навіщо Дарсокові Свіфтдаґґеру голова Серени?",a="Дарсок хоче незаперечного доказу, що Серена Бладфезер мертва, і збирається виставити її голову на караван постачання Орди. Він сподівається, що рештки матріархи наженуть жаху на вцілілих гарпій-Відьмокрилих і відіб'ють у них охоту нападати на мандрівників.",al={"навіщо брати голову серени","дарсок голова серени","що дарсок робить з головою"}},{q="Чому Серена Бладфезер нападала на каравани Орди?",a="Серену вела жага помсти Орді. Її сестру, Бладфезер, убив Рекссар, звитяжець мок'наталів, і Серена мстилася, нападаючи на шляхи постачання Орди й мандрівників по всіх Пустках.",al={"чому серена нападала на каравани","мотив серени бладфезер","напади гарпій пустища"}},{q="Звідки цей трофей?",a="Його відтято від Серени Бладфезер — матріархи, що гніздиться серед скель Сухих Пагорбів на далекому північному заході Пусток.",al={"де голова серени","місце серени бладфезер","як отримати голову серени"}}},fp="13,282,21.609.0,47.263.0,53.228.0,33.145.0"}
P.entries["item:serpentbloom"] = {n="Зміїцвіт",s="Зміїцвіт — рідкісна підземна трава, що росте лише в темних глибинах Печер Стогонів. Її сильні природні властивості привернули пильну увагу Королівського Аптекарського Товариства Відступників.",h="Зміїцвіт — рідкісна підземна трава, що росте лише в темних глибинах Печер Стогонів.",kw={"зміїцвіт","печери стогонів","аптекарка замах","королівське аптекарське товариство","відступники","травництво"},ang={["profession:Herbalism"]="Вишколені травники мають гостре око, щоб розгледіти ці рідкісні печерні квіти там, де інші бачать лише вогкий камінь.",["race:Undead"]="Добуваючи зміїцвіт, ви прямо допомагаєте Аптекарці Замах і Королівському Аптекарському Товариству, що шукають у чужих краях рослинні багатства, аби зміцнити Відступників."},sec={{t="Рідкісна підземна флора",b="Зміїцвіт росте тільки у вогких, затінених тунелях Печер Стогонів під Пустками. Укорінений у природі, спотвореній неприборканою силою Смарагдового Сну, він буяє далеко від сонця, і між його стеблами часто гніздяться отруйні змії. Оскільки печери кишать ворожими звірами й спотвореними друїдами, мало хто з тих, хто туди спускається, повертається з придатними зразками."},{t="Інтерес аптекарів",b="Зі Ставків Видінь під Тандер Блафом Аптекарка Замах збирає зміїцвіт для Королівського Аптекарського Товариства Андерсіті. Відступники повсякчас шукають по всьому Калімдору отруйні, дивні й хімічно потужні рослини для своїх досліджень на службі Темній Леді. Замах переконана, що зібраний у великій кількості зміїцвіт може дати цінні прориви для алхімії Відступників."}},faq={{q="Де росте Зміїцвіт?",a="Зміїцвіт трапляється лише глибоко в Печерах Стогонів — лабіринті печер на південний захід від Перехрестя в Пустках. Він чіпляється за землю в темних вологих закутках печер.",al={"де знайти зміїцвіт","місце зміїцвіту","трава голосних печер"}},{q="Навіщо Королівському Аптекарському Товариству Зміїцвіт?",a="Аптекарка Замах, агентка Королівського Аптекарського Товариства в Тандер Блафі, шукає рослину для досліджень. Відступники вивчають незвичну й небезпечну флору з усього Калімдору, щоб створювати нові хімічні суміші й сприяти ширшим задумам Сильвани Віндраннер.",al={"хто хоче зміїцвіт","трава аптекаря замаха","навіщо збирати зміїцвіт"}},{q="Чому збирати Зміїцвіт небезпечно?",a="Окрім загальних небезпек Печер Стогонів, де аж кишить рапторами, кроколісками й оскверненими друїдами, у самій рослині часто ховаються отруйні змії. Варто потривожити її — і приховані змії нападають.",al={"небезпека зміїцвіту","змія зміїцвіту"}},{q="Чи травникам легше знайти Зміїцвіт?",a="Так. Ті, хто опанував травництво, мають природне чуття на рослини й можуть вистежити кущики Зміїцвіту в тінистих закутках печерної долівки.",al={"травництво зміїцвіт","відстеження зміїцвіту"}}},fp="12,206,25.409.0,19.424.0,29.205.0,56.276.0,41.232.0,45.164.0"}
P.entries["item:sethir-s-journal"] = {n="Щоденник Сетіра",s="Щоденник Сетіра — особисті записи, які носить при собі невловимий сатир Сетір Прадавній на Тельдрассилі. Здобутий потай, щоденник підтверджує тривожну річ: скверна з материкового Калімдору перекинулася на Світове Древо.",h="Щоденник Сетіра — особисті записи, які носить при собі невловимий сатир Сетір Прадавній на Тельдрассилі.",kw={"щоденник сетіра","сетір прадавній","сатир","сюрна","галявина оракула","скверна","тельдрассил"},ang={["class:Rogue"]="Здобутий щоденник доводить: тихе проникнення й спритні пальці можуть добути вкрай важливі відомості там, де воїни передової й дипломати зазнали цілковитої поразки.",["race:NightElf"]="Щоденник — тривожний доказ того, що Тельдрассил не вберігся від давньої демонічної скверни, яка розповзається материковим Калімдором."},sec={{t="Слід скверни",b="Тельдрассил виростили з надією повернути ельфам безсмертя, але невидима недуга дедалі глибше вкорінюється в його гіллі. Сюрна в Дарнасусі підозрювала, що відповіді знає Сетір Прадавній — самотній сатир, який ховається на віддаленій гілці біля Галявини Оракула. Коли і перемовини, і відкрита сила приносили попереднім розвідникам лише смерть, щоденник Сетіра вдалося тихцем поцупити з його кишені. Записи відкривають похмуру правду: таємнича пошесть, що отруює ліси й води за морем, на Темному Узбережжі, дісталася й самого Тельдрассилу."}},faq={{q="Що таке Щоденник Сетіра?",a="Це щоденник Сетіра Прадавнього — ворожого сатира, що живе на зовнішніх гілках біля Галявини Оракула на Тельдрассилі. У ньому — нотатки про скверну, що поширюється краєм.",al={"що таке щоденник сетіра","історія щоденника сетіра","чий щоденник сетіра"}},{q="Як здобути щоденник?",a="Попередні спроби домовитися із Сетіром чи битися з ним закінчувалися поразкою й смертю, тож щоденник доводиться потай поцупити просто з його торби.",al={"як отримати щоденник сетіра","де взяти щоденник сетіра","обікрасти сетіра"}},{q="Що розкриває щоденник?",a="За словами наставниці розбійників Сюрни, щоденник доводить, що дивна хвороба, яка нищить ліси й води Темного Узбережжя, таки проникла на Тельдрассил.",al={"що каже щоденник сетіра","що в щоденнику сетіра"}},{q="Хто такий Сетір Прадавній?",a="Сетір — сатир-самітник, що гніздиться на відлюдній гілці на околиці Галявини Оракула. Він відомий тим, що жорстоко розправляється з непроханими гостями, і знає щось важливе про скверну, яка підточує Світове Древо.",al={"хто такий сетір","сетір прадавній"}}},fp="16,226,19.554.1,25.205.0,28.154.0,29.169.0,26.217.0"}
P.entries["item:sevren-s-orders"] = {n="Накази Севрена",s="Накази Севрена — письмові розпорядження Магістрата Севрена з Брілла. Вони велять випробуваному агентові Відступників з'явитися до Бетора Айсшарда, могутнього мага з Магічного Кварталу Андерсіті.",h="Накази Севрена — письмові розпорядження Магістрата Севрена з Брілла.",kw={"накази севрена","магістрат севрен","брілл","бетор айсшард","магічний квартал","андерсіті","галявини тірісфалю"},ang={["class:Mage"]="Для знавців магії ці накази відкривають шлях на прийом до Бетора Айсшарда, одного з найвидатніших заклиначів королівства Відступників.",["race:Undead"]="Печатка Севрена знаменує перехід агента від місцевої служби в Тірісфалі до прямої допомоги магічній еліті Андерсіті."},sec={{t="Виклик до столиці",b="Поки Відступники зміцнюють владу над руїнами Лордерона, вправних агентів, що вже довели свою вартість у боях із Погибеллю на Галявинах Тірісфалю, викликають на південь, до столиці. Ці письмові накази від Магістрата Севрена слугують офіційною рекомендацією й посвідченням перед Бетором Айсшардом — одним із найвизначніших магів Темної Леді в Магічному Кварталі. Сам Севрен знає лише те, що доручення пов'язане зі спробою вийти на зв'язок із лічем-одинаком, але виклик має всю повноту влади верховних магів Андерсіті."}},faq={{q="Хто написав ці накази?",a="Накази склав Магістрат Севрен — наглядач-Відступник, що керує справами містечка Брілл на Галявинах Тірісфалю.",al={"автор наказів севрена","хто такий севрен","хто дає накази севрена"}},{q="Кому призначені ці накази?",a="Їх адресовано Беторові Айсшарду, високопоставленому магові-Відступнику з Магічного Кварталу Андерсіті.",al={"хто отримує накази","куди нести накази севрена","хто такий бетор айсшард"}},{q="Про яке доручення йдеться в наказах?",a="Ідеться про те, щоб залучити на бік Відступників норовливого ліча. Це небезпечна справа, для якої потрібен агент, що вже довів свою вправність у боротьбі з Погибеллю.",al={"яка місія лічу","чого хоче бетор","місія блудного лічу"}},{q="Чому доставити їх доручили саме мені?",a="Бетор просив прислати агента, який уже довів, що може протистояти Погибелі. Магістрат Севрен вирішив, що ваших подвигів на Галявинах Тірісфалю досить, щоб упоратися з небезпечним дорученням Бетора.",al={"чому я","чому севрен обрав мене"}}},fp="15,204,22.555.0,23.127.0,40.114.0,44.154.0,33.174.0"}
P.entries["item:shadowhide-pendant"] = {n="Амулет Тіньової Шкури",s="Амулети Тіньової Шкури — грубі прикраси-обереги, які носять гноли Тіньової Шкури, що блукають Горами Редріджу. Їх збирають як законний доказ виконання вироку: вони засвідчують, що захисники краю застосували закон Лейкширу до гнолів, які служать магові-ренегату Морґанту.",h="Амулети Тіньової Шкури — грубі прикраси-обереги, які носять гноли Тіньової Шкури, що блукають Горами Редріджу.",kw={"амулет тіньової шкури","гноли Тіньової Шкури","морґант","пристав конакер","магістрат соломон","лейкшир"},ang={["class:Warrior"]="Гноли Тіньової Шкури — запеклі й фізично грізні супротивники, на яких випробовують себе бійці передової, що захищають дороги до Лейкширу.",["faction:Alliance"]="Прикордонні поселення на кшталт Лейкширу майже не отримують допомоги від стормвіндського гарнізону, тож місцеві магістрати покладаються на вірних шукачів пригод Альянсу, щоб утримувати закон королівства."},sec={{t="Знаки непокори",b="Воїни, громили й заклиначі клану гнолів Тіньової Шкури носять ці амулети як грубі особисті тотеми чи знаки рангу. У глибині пагорбів Редріджу клан згуртувався довкола Лейтенанта Фанґора й потрапив під вплив Морґанта — мага-ренегата, що володіє таємною магією. Для мешканців Лейкширу ці обереги — не просто примітивні прикраси, а розпізнавальні знаки організованої загрози, яка тероризує поселення всього краю на користь ворога Корони."},{t="Правосуддя Лейкширу",b="За повноваженнями Магістрата Соломона й законами Стормвінда, свідома допомога відомому злочинцеві королівства карається смертю. Королівського підкріплення бракує, тож Пристав Конакер у Ратуші Лейкшира покладається на незалежних шукачів пригод, щоб підтримувати порядок. Десять Амулетів Тіньової Шкури — відчутний доказ того, що гноли, які виконували накази Морґанта, зазнали прикордонного правосуддя."}},faq={{q="Що таке Амулет Тіньової Шкури?",a="Це оберіг, який носять гноли клану Тіньової Шкури в Горах Редріджу. Місцевий магістрат приймає такі амулети як доказ того, що гнолів-загарбників убито, захищаючи містечко.",al={"що таке амулети тіньової шкури","історія амулета тіньової шкури","амулет редріджа"}},{q="Навіщо Приставові Конакеру ці амулети?",a="Пристав Конакер збирає їх, щоб виплачувати нагороди згідно із Законом Соломона. Клан Тіньової Шкури діє разом із чаклуном-ренегатом Морґантом, тероризуючи місцевих, тож містечко вважає кожного причетного гнола ворогом, вартим смертної кари.",al={"навіщо збирати амулети","нагорода пристава конакера","завдання конакера"}},{q="Хто носить ці амулети?",a="Їх носять гноли всіх рангів клану Тіньової Шкури — від звичайних грабіжників, громил і скажених гнолів до таких постатей, як Рогг Мовчазний і Лейтенант Фанґор у диких краях Редріджу.",al={"хто дропає амулети","які гноли мають амулети","джерело амулета тіньової шкури"}},{q="Що пов'язує клан Тіньової Шкури з Морґантом?",a="Морґант, маг-відщепенець, що ховається у східних передгір'ях, зловісною силою підкорив гнолів Тіньової Шкури своїй волі й використовує їх як піхоту, щоб тероризувати Лейкшир і втілювати свої задуми.",al={"гноли та морґант","чому гноли працюють з морґантом","тіньова шкура морґант"}}},fp="18,282,18.485.0,19.409.0,29.196.0,46.276.0,27.193.0,66.230.0"}
P.entries["item:shaman-voodoo-charm"] = {n="Шаманський Вудуйський Оберіг",s="Шаманський Вудуйський Оберіг — темна обрядова дрібничка, яку носять шамани фурболгів Вузлошкірів глибоко в Курганному Лігві Бан'етіл. Випромінюючи мерзенну ауру, цей оберіг спрямовує неприродну магію, здатну відтяти дух сплячого друїда від його тіла.",h="Шаманський Вудуйський Оберіг — темна обрядова дрібничка, яку носять шамани фурболгів Вузлошкірів глибоко в...",kw={"шаманський вудуйський оберіг","вуду","шамани","вузлошкіри","фурболги","обен рейджклов","курганне лігво бан'етіл"},ang={["class:Druid"]="Для друїда оберіг — жахливе спотворення священної сплячки: темна магія ув'язнює сновидця у Смарагдовому Сні, а його тілом орудують, мов лялькою.",["race:NightElf"]="Знахідка цих оберегів у Курганному Лігві Бан'етіл відкриває, як глибоко Вузлошкіри споганили одне з найсвятіших спільних місць спочинку калдореїв."},sec={{t="Спотворена магія",b="Плем'я Вузлошкірів на Тельдрассилі впало в безумство й скверну, та в Курганному Лігві Бан'етіл його шамани володіють силами, що сягають далеко за звичайне лісове чаклунство. Цими дивними вудуйськими оберегами шамани навчилися виривати свідомість сплячого друїда зі смертного світу й безпорадно ув'язнювати її у Смарагдовому Сні. Відтявши душу від посудини, фурболги можуть оживити порожнє тіло й обертати шанованих захисників — нічних ельфів на бездумних вартових, що вирізають кожного, хто заходить у кургани."},{t="Розплутування прокляття",b="Коли жертвою цього обряду став друїд Обен Рейджклов, його дух опинився в пастці Сну, а оживлене тіло тероризувало глибини курганів. Сягнувши крізь заслону, Обен доручив шукачам пригод перебити шаманів Вузлошкірів й здобути один з їхніх вудуйських оберегів. Дослідивши мерзенні чари, вкладені в дрібничку, Обен сподівався розгадати покручене ремесло фурболгів і знайти спосіб розірвати пута на своїй викраденій плоті."}},faq={{q="Для чого потрібен Шаманський Вудуйський Оберіг?",a="Шамани Вузлошкірів використовують оберіг у потужному ритуалі, що відриває дух сплячого друїда від тіла: розум лишається в пастці Смарагдового Сну, а спорожніла плоть оживає й нападає на чужинців.",al={"призначення вудуйського оберега","що робить оберіг","використання шаманського оберега"}},{q="Хто носить ці обереги?",a="Їх носять шамани Вузлошкірів, що живуть у звивистих глибинах Курганного Лігва Бан'етіл на Тельдрассилі.",al={"хто дропає обереги","де знайти шаманський вудуйський оберіг","оберіг шамана ґнарлпайнів"}},{q="Навіщо Обенові Рейджклову такий оберіг?",a="Обен Рейджклов застряг у Смарагдовому Сні, а його оживлене тіло шаленіє на волі. Йому треба вивчити мерзенну ауру й магічне плетиво оберега, щоб збагнути, як розірвати чари фурболгів.",al={"навіщо обену оберіг","оберіг обена рейджкло","предмет сплячого друїда"}},{q="Звідки у фурболгів магія вуду?",a="Зазвичай шамани фурболгів шанують духів природи й стихії, але скверна, що охопила Тельдрассил, штовхнула Вузлошкірів до темної, збоченої магії. Оберіг має неприродну, мерзенну ауру, геть не схожу на звичайне шанування природи.",al={"чому фурболги використовують вуду","лор вуду фурболгів"}}},fp="19,260,17.570.0,20.458.1,41.215.0,25.117.0,32.213.0,34.254.0"}
P.entries["item:shard-of-water"] = {n="Скалка Води",s="Скалка води — залишок стихії, здобутий під час єднання шамана з духами води. Іслен Вотерсір на узбережжі Пусток приймає її як відчутний доказ того, що новачок збагнув життєдайну природу води й переміг її скверну.",h="Скалка води — залишок стихії, здобутий під час єднання шамана з духами води.",kw={"скалка води","іслен вотерсір","поклик води","тотем води","шаман","срібнолісся"},ang={["class:Shaman"]="Здобувши цю скалку, ви робите останній крок до злагоди з духами води й завершуєте довгий шлях до власного Тотема Води."},sec={{t="Знак стихійної чистоти",b="Для шаманів, що прагнуть опанувати стихії, єднання з водою вимагає глибокого розуміння рівноваги, життя й збереження. У випробуваннях «Поклику води» шаманів посилають протистояти скверні, що просочилася в природні джерела, — навіть за море, у сплюндровані землі на кшталт Срібнолісся. Скалку води отримує той, хто очистить ці осквернені води. Коли новачок приносить цей кришталевий знак на скелясті береги Пусток, Іслен Вотерсір визнає його гідність — і це останній ключ, потрібний, щоб викувати Тотем Води."}},faq={{q="Для чого потрібна Скалка Води?",a="Вона — доказ того, що ви пройшли випробування Іслен Вотерсір на східному узбережжі Пусток. Віддавши їй скалку, ви завершуєте єднання з водою й отримуєте свій Тотем Води.",al={"призначення скалки води","що робить скалка води","чому в мене скалка води"}},{q="Кому потрібен цей предмет?",a="Іслен Вотерсір, шаманка, що живе в хатині на південь від Раджета на Узбережжі Крамарів, просить скалку, щоб переконатися, що ви очистили зіпсовану воду.",al={"кому потрібна скалка води","куди здати скалку води","скалка ісслен ватерсір"}},{q="Чому випробування призначили аж у Срібноліссі?",a="Вода уособлює зцілення й збереження, а скверна зупиняє життя. Отруєні води Срібнолісся — суворе випробування здатності шамана відновити гармонію стихій серед глибокого тління.",al={"чому сільверпайн","чому випробування в сільверпайні","шаман сільверпайн"}}},fp="14,277,25.555.0,36.188.0,23.157.0,48.194.0"}
P.entries["item:shaw-s-report"] = {n="Звіт Шоу",s="«Звіт Шоу» — таємне донесення, яке Майстер Матіас Шоу з SI:7 написав для Ґраяна Стаутмантла у Вестфолі. У ньому викладено все, що розвідка знає про Гільдію Каменярів, її ватажка Едвіна Венкліфа та їхню кривду на корону після відбудови Стормвінда.",h="«Звіт Шоу» — таємне донесення, яке Майстер Матіас Шоу з SI:7 написав для Ґраяна Стаутмантла у Вестфолі.",kw={"звіт шоу","матіас шоу","si:7","гільдія каменярів","едвін венкліф","ґраян стаутмантл"},ang={["class:Rogue"]="Звіт показує розмах і методи Майстра Матіаса Шоу — незаперечного володаря шпигунської мережі Стормвінда й очільника SI:7.",["faction:Alliance"]="Документ викриває гниль усередині Стормвінда: неоплачений борг перед будівничими королівства породив заколот, що загрожує його нивам."},sec={{t="Розвідка про каменярів",b="Звіт Шоу, доставлений із таємного штабу SI:7 у Стормвінді до Сентінел Гілла, уперше чітко пояснює Народному ополченню, хто командує розбійниками, що плюндрують Вестфол. Документ розповідає, як Гільдія Каменярів на чолі з Едвіном Венкліфом сумлінно відбудувала Стормвінд після його зруйнування в Першій війні. Коли ж по завершенні робіт корона й знать відмовилися чесно розрахуватися з каменярами, у тих закипіла гірка образа. Розвідка Шоу встановлює вирішальний зв'язок між ображеними, викинутими на узбіччя майстрами та злочинним повстанням, що нині охоплює околиці королівства."}},faq={{q="Що таке Звіт Шоу?",a="Це запечатане розвідувальне досьє, яке склав Майстер Матіас Шоу, очільник таємної служби Стормвінда SI:7, для Ґраяна Стаутмантла. У ньому — відомості корони про Гільдію Каменярів і минуле Едвіна Венкліфа.",al={"звіт шоу","що пише шоу","зміст звіту шоу"}},{q="Що звіт розповідає про Едвіна Венкліфа?",a="У звіті сказано, що Венкліф колись очолював Гільдію Каменярів і керував відбудовою Стормвінда після Першої війни. Там пояснено, що Венкліф і його майстри збунтувалися, коли правителі королівства відмовилися як слід їм заплатити.",al={"ванкліф у звіті","що звіт каже про ванкліфа"}},{q="Навіщо Ґраянові Стаутмантлу цей звіт?",a="Стаутмантл очолює Народне ополчення, яке захищає Вестфол від злагоджених набігів розбійників. Без підтримки регулярних королівських військ він покладається на розвідку Матіаса Шоу, щоб дізнатися, хто керує розбійниками і чого вони насправді прагнуть.",al={"чому слати звіт ґраяну","навіщо стаутмантлу звіт"}},{q="Як Стаутмантл сприймає звіт?",a="Стаутмантл глибоко стривожений. Він знає Едвіна Венкліфа як працьовитого й вправного майстра, і без вагоміших доказів йому важко повірити, що такий шанований будівничий міг стати лиходієм.",al={"реакція ґраяна","реакція стаутмантла"}}},fp="13,296,31.642.1,22.241.0,49.242.0,44.242.0,41.224.0"}
P.entries["item:shimmering-frond"] = {n="Мерехтливе Листя",s="Мерехтливе Листя — зразок із дивної світної рослини, що росте на Галявині Оракула в Тельдрассилі. Його незвичне світіння й мінлива аура виказують у ньому екзотичний вид, цілком чужий для віття Світового Дерева.",h="Мерехтливе Листя — зразок із дивної світної рослини, що росте на Галявині Оракула в Тельдрассилі.",kw={"мерехтливе листя","галявина оракула","деналан","озеро ал'амет","болото скорботи","східні королівства","ботаніка"},ang={["class:Druid"]="Поява зайшлої болотяної рослини, що буяє на новонародженому вітті Тельдрассила, — цікава природна аномалія, варта уваги будь-якого друїда.",["profession:Herbalism"]="Травники, що блукають Тельдрассилом, оцінять рідкісну стійкість, потрібну рослині з Болота Скорботи, щоб перетнути океан і прижитися в чужому ґрунті."},sec={{t="Зразок здалеку",b="Блукаючи зеленими шатрами довкола Галявини Оракула, мандрівники можуть натрапити на дивну рослинність із пульсівною сяйливою аурою. Зірване з цієї рослини листя неприродно ловить просіяне лісове світло й мерехтить яскравою життєвою силою. Деналан, ботанік, що доглядає свої грядки біля Озера Ал'Амет, одразу впізнає в листі вид, корінний для далекого Болота Скорботи у Східних Королівствах. Як насіння з болота, що лежить так далеко за Великим морем, зуміло вкоренитися й розквітнути на новопосталому Тельдрассилі, лишається інтригівною загадкою, і Деналан береться проростити й вивчити зразки у власному ґрунті."}},faq={{q="Звідки береться Мерехтливе Листя?",a="Листя зривають із дивної папоротеподібної рослини на Галявині Оракула на Тельдрассилі. Рослина впадає в око звивистим пульсівним сяйвом, що мерехтить на її листі в лісовому світлі.",al={"де взяти мерехтливе листя","місце мерехтливого листя","дивна рослина"}},{q="Кого цікавить Мерехтливе Листя?",a="Деналан, нічний ельф-натураліст, що вивчає рослини біля Озера Ал'Амет, дуже хоче оглянути зразок. Його надзвичайно цікавлять дивні рослини, що вкорінюються на Тельдрассилі.",al={"хто хоче мерехтливе листя","кому віддати мерехтливе листя","деналан мерехтливе листя"}},{q="Чим ця рослина така незвичайна для Тельдрассила?",a="Рослина не походить ні з Калімдору, ні зі Світового Древа. Деналан упізнає в ній вид із каламутних вод Болота Скорботи, що лежить далеко за Великим Морем, у Східних Королівствах, тож її буйне зростання на Тельдрассилі вельми несподіване.",al={"чому рослина особлива","походження рослини","рослина боліт смутку"}},{q="Що стається, коли віддати листя Деналанові?",a="Деналан одразу висаджує зразок у свої вазони біля Озера Ал'Амет і вирощує його, щоб дослідити його швидкий ріст і незвичайні властивості.",al={"що деналан робить з листям","лор паростків"}}},fp="16,244,20.650.0,42.208.0,42.194.0,47.264.0,47.151.0"}
P.entries["item:shimmerweed"] = {n="Мерехтрава",s="Мерехтрава — особлива трава, яку тролі Морозогриви вирощують на Мерехтливому Хребті, серед засніжених висот Дун Мороґу. Тролі збирають її для власних племінних ритуалів, а місцеві дворфійські бровари жадають її гострого, неповторного смаку для експериментальних елів.",h="Мерехтрава — особлива трава, яку тролі Морозогриви вирощують на Мерехтливому Хребті, серед засніжених висот...",kw={"мерехтрава","трава","морозогриви","мерехтливий хребет","реджолд барліброю","село брюнолл","стаут"},ang={["profession:Herbalism"]="Хоч мерехтрава й не входить до стандартного набору польового ботаніка, вона показує, як місцеву флору часто пристосовують і до тутешніх броварських традицій, і до ритуальної алхімії.",["race:Dwarf"]="Вірно дворфійській винахідливості: якщо на сусідній скелі росте дивна рослина, хтось урешті спробує зробити з неї пиво."},sec={{t="Троляча культура",b="Високо над низинами Дун Мороґу тролі Морозогриви доглядають грядки мерехтрави вздовж крижаних скель Мерехтливого Хребта. Тролі збирають рослину й зберігають її в плетених кошиках, розкиданих по їхніх таборах, покладаючись на неї у своїх священних і загадкових ритуалах. Поза тролячим суспільством мало хто з горян зважає на це зілля, хоча його потужні властивості привернули погляд винахідливих чужинців."},{t="Таємний інгредієнт",b="У сусідньому Селі Брюнолл броварник Реджолд Барліброю зацікавився травою не на жарт. Переконаний, що броварство в нього в крові, Реджолд прагне зварити довершений дворфійський стаут і підозрює, що різкий, неповторний смак мерехтрави може виявитися тим, чого бракувало. Він раз у раз наймає відчайдушних мандрівників, щоб ті прослизнули до таборів Морозогривів, обминули ворожих тролів і притягли оберемки трави, яку він кине до своїх бродильних чанів."}},faq={{q="Де росте Мерехтрава?",a="Мерехтраву можна знайти на Мерехтливому Хребті — крижаному підвищенні на північний захід від Села Брюнолл у Дун Мороґу. Її вирощують і збирають тролі-Морозогриви та зберігають у кошиках по своїх таборах.",al={"місце мерехтрави","де знайти мерехтраву","рослина мерехтливого хребта"}},{q="Для чого тролі-Морозогриви використовують Мерехтраву?",a="Тролі-Морозогриви вживають Мерехтраву у своїх таємничих племінних обрядах і церемоніях. Подробиці їхніх ритуалів для чужинців лишаються загадкою, але трава відіграє помітну роль у їхніх звичаях і духовних практиках на Мерехтливому Хребті.",al={"тролі використовують мерехтраву","навіщо тролям мерехтрава"}},{q="Навіщо Реджолдові Барліброю Мерехтрава?",a="Реджолд Барліброю в Селі Брюнолл прагне зварити ідеальний дворфський стаут. Відчувши в дикій траві особливий смак, він хоче кинути в експериментальне сусло кілька оберемків свіжої Мерехтрави й перевірити, чи дасть вона той насичений смак, якого бракує його рецепту.",al={"завдання реджолда барліброя","хто хоче мерехтраву","чому варити з мерехтравою"}},{q="Чи росте Мерехтрава десь, окрім Дун Мороґу?",a="Різновиди Мерехтрави збирали й у посушливих краях на кшталт Дуротару, де провидці, як-от Дрек'Тар, цінують рослину за сильні трав'яні настої та цілющі відвари. Отже, трава пристосовується не лише до засніжених вершин Каз Модану.",al={"мерехтрава дуротар","мерехтрава поза дун морогом"}}},fp="11,252,15.413.0,19.442.0,28.203.0,49.250.0,44.263.0,50.237.0"}
P.entries["item:shindrell-s-note"] = {n="Записка Шіндрелл",s="Записка Шіндрелл — письмове донесення з описом нещодавніх ознак порчі довкола Астранаару та на узбережжі Ашенвалю. Його написала вартова нічних ельфів Шіндрелл Свіфтфайр, і це розвідувальний звіт, який через увесь ліс відправляють на схід, до друїда Кейнета Стіллвінда.",h="Записка Шіндрелл — письмове донесення з описом нещодавніх ознак порчі довкола Астранаару та на узбережжі...",kw={"записка шіндрелл","шіндрелл свіфтфайр","кейнет стіллвінд","лісова пісня","донесення","ашенваль"},ang={["class:Druid"]="Віднісши спостереження Шіндрелл Кейнетові Стіллвінду, ви допоможете побратимам-друїдам докопатися до коренів протиприродної напасті, що мучить ліс.",["race:NightElf"]="Донесення показує незмінну співпрацю між вартовими, які боронять поселення Ашенвалю, і друїдами Кола Кенарія, які вивчають недугу його природи."},sec={{t="Донесення через ліс",b="Поки неспокій ширшає по всьому Ашенвалю, вартові й друїди нічних ельфів спільно стежать за межами лісу. Цей звіт, написаний Вартовою Шіндрелл Свіфтфайр в Астранаарі, описує тривожні заворушення на західному узбережжі та в центральних хащах. Він адресований Кейнетові Стіллвінду — друїдові, що служить при святилищі Лісової Пісні в Лісі Нічної Пісні на сході. Посилаючи гінців зі своїми власними спостереженнями, Шіндрелл допомагає Кейнетові розслідувати непомітну порчу, що закрадається у священні гаї."}},faq={{q="Що таке Записка Шіндрелл?",a="Це донесення Вартової Шіндрелл Свіфтфайр про заворушення й імовірну скверну, помічені біля Астранаару та вздовж узбережжя Ашенвалю.",al={"що це за записка","записка шіндрелл","що в записці"}},{q="Кому призначена записка?",a="Записку адресовано Кейнетові Стіллвінду, друїдові з нічних ельфів, що перебуває в Лісовій Пісні — на сході Ашенвалю, у Лісі Нічної Пісні.",al={"кому віддати","куди нести","кому записка"}},{q="Навіщо написали записку?",a="Кейнет Стіллвінд просив відомостей про незвичайні події в західних лісах, бо побоювався, що в лісі пускає коріння підступна скверна. Шіндрелл зібрала свої спостереження, щоб допомогти йому оцінити загрозу.",al={"чому написали записку","яка скверна","призначення звіту"}},{q="Де живе Шіндрелл Свіфтфайр?",a="Шіндрелл Свіфтфайр — вартова з нічних ельфів, яка служить в Астранаарі в центрі Ашенвалю.",al={"де шіндрелл","місце шіндрелл свіфтфайр","хто надіслав"}}},fp="16,283,26.562.0,25.166.0,33.150.0,25.226.0,38.115.0"}
P.entries["item:shipment-of-boots"] = {n="Партія Чобіт",s="Ящик із взуттям, який крамар Дріззлік відправив із порту Буті Бей для торгової мережі Ґазлоу в Раджеті. Біля узбережжя його перехопили Флібустьєри Південних морів і сховали у своєму таборі на південь від порту.",h="Ящик із взуттям, який крамар Дріззлік відправив із порту Буті Бей для торгової мережі Ґазлоу в Раджеті.",kw={"партія чобіт","ґазлоу","дріззлік","флібустьєри південних морів","пірати","раджет"},ang={["class:Rogue"]="Щоб пробратися до таборів флібустьєрів на узбережжі, доведеться оминати щільні піратські патрулі, тож безшумний підхід — найбезпечніший спосіб повернути вкрадений вантаж Ґазлоу."},sec={{t="Пограбований вантаж",b="Гоблінський торговий порт потребує нескінченних запасів, і Ґазлоу домовився про свіжу поставку чобіт від Дріззліка, торговця одягом із порту Буті Бей. Та партія так і не дісталася пристаней Раджета. Флібустьєри Південних морів, що нишпорять уздовж Узбережжя Крамарів, напали на вантажне судно й забрали ящики до своїх пляжних таборів на південь від гавані. Пірати розкидали вкрадений вантаж по своїх наметах і халупах, і Ґазлоу лишився без очікуваного краму, доки не знайшлися заповзятливі найманці, готові прочесати берег."}},faq={{q="Хто надіслав цю партію чобіт?",a="Чоботи надіслав із Буті Бей Дріззлік — гоблін-торговець, що тримає в південному порту крамницю одягу й припасів.",al={"хто зробив чоботи","звідки чоботи","чоботи дріззліка"}},{q="Хто мав отримати чоботи?",a="Ґазлоу, головний інженер і управитель Раджета, замовив взуття для своїх робітників і торговельних справ.",al={"чиї чоботи","партія чобіт ґазлоу"}},{q="Як чоботи опинилися в піратів?",a="Флібустьєри Південних морів перехопили вантажний корабель біля узбережжя Пусток, пограбували його й перетягли ящики до своїх таборів на південь від Раджета.",al={"чому пірати південних морів мають чоботи","хто вкрав чоботи"}},{q="Де знайти цю партію?",a="Ящик стоїть у піратському таборі Південних морів на узбережжі на південь від Раджета, захований серед награбованого.",al={"місце чобіт","де партія чобіт","знайти партію чобіт"}}},fp="17,233,17.555.0,32.141.0,38.131.0,42.161.0,32.140.0"}
P.entries["item:shipment-of-iron"] = {n="Партія Заліза",s="Скриня сирого металу, що зберігається в людській кузні на Полях Гілсбреду. Вона — важливий запас для місцевого виробництва зброї, тож стала першочерговою ціллю для військ Відступників, які прагнуть перекрити шляхи постачання Саутшора.",h="Скриня сирого металу, що зберігається в людській кузні на Полях Гілсбреду.",kw={"партія заліза","поля гілсбреду","коваль веррінґтан","кузня","таррен мілл","саутшор"},ang={["faction:Horde"]="Позбавлення Гілсбреда постачання калічить збройний опір фермерів, перш ніж похід рушить на Саутшор.",["profession:Blacksmithing"]="Цей запас — кров людського збройного виробництва в долині: без сирих залізних злитків горно Веррінґтана цілком безсиле."},sec={{t="Паливо для опору",b="У безперервній боротьбі за Передгір'я Гілсбреда люди-селяни чинять Таррен Міллу напрочуд упертий опір. Здебільшого ця бойова сила йде просто з кузні на південно-західному краю Полів Гілсбреду, де Коваль Веррінґтан і його учні працюють цілодобово, викуваючи зброю й обладунки з важких партій заліза. Щоб зламати рішучість фермерів, командири Відступників наказали загасити горно, усунути ковалів і захопити запаси металу для війни Орди."}},faq={{q="Де зберігають партію заліза?",a="Партія лежить просто в ковальні на південно-західному краю Полів Гілсбреду, і її пильно стережуть Коваль Веррінґтан та його учні.",al={"місце партії заліза","де залізо","місце заліза гілсбреда"}},{q="Навіщо Відступникам це залізо?",a="Захопивши залізо, Відступники перерізають постачання зброї місцевому людському ополченню. До того ж Верховний Екзекутор Дарталія збирається пустити металеві запаси на потреби воєнної машини Орди, щойно наступ повернеться на знищення Саутшору.",al={"чому красти залізо","залізо таррен мілла","призначення заліза битви за гілсбред"}},{q="Хто спершу користувався цим залізом?",a="Коваль Веррінґтан і четверо його учнів-ковалів озброювали цим залізом містян і польових робітників, перетворюючи простих фермерів на озброєну місцеву оборону проти нежиті.",al={"чиє залізо","залізо верринґтана","ковалі гілсбреда"}},{q="Хто наказує забрати партію заліза?",a="Верховний Екзекутор Дарталія, що керує операціями Відступників із Таррен Мілла, особисто наказує вбити ковалів і забрати залізо під час Битви за Гілсбред.",al={"хто дає завдання","завдання заліза дарталії"}}},fp="16,220,22.546.0,35.179.0,37.231.0,35.193.0,46.173.0"}
P.entries["item:shipping-schedule"] = {n="Розклад Перевезень",s="Розклад Перевезень — документ, який зберігає доглядач пристані Братства Дефіас на Пристані Джерода. У ньому розписано незаконні вантажі, що курсують Лісом Елвінн між Редріджем і Вестфолом, і він привернув пильну увагу розвідки Стормвінда.",h="Розклад Перевезень — документ, який зберігає доглядач пристані Братства Дефіас на Пристані Джерода.",kw={"розклад перевезень","пристань джерода","братство дефіас","контрабанда","si:7","матіас шоу"},ang={["class:Rogue"]="Витягти розклад із кишені доглядача пристані — визначальне випробування непомітності й кишенькової крадіжки для агентів, що прагнуть до лав SI:7."},sec={{t="Контрабанда на Пристані Джерода",b="На південь від Ґолдширу, на елвіннському березі річки Назферіті, Братство Дефіас захопило Пристань Джерода й зробило її осередком свого річкового руху. Через цю таємну пристань Братство переправляє чималі партії контрабанди між Редріджем і Вестфолом, прослизаючи водними шляхами просто під носом у Варти Стормвінда. Розклад Перевезень фіксує ці таємні пересування, і доглядач пристані пильно тримає його при собі."},{t="Під прицілом SI:7",b="Майстер Матіас Шоу, очільник SI:7, замовив викрадення розкладу, щоб нанести на мапу ланцюги постачання Дефіас і випробувати молодих агентів. Проникнути до будиночка на пристані й витягти документ із кишені доглядача — це водночас і цінні розвіддані для корони, і обряд посвяти. Якщо агента спіймають, SI:7 зречеться будь-якого зв'язку з ним, і жоден слід не приведе до казарм у Стормвінді."}},faq={{q="Що таке Розклад Перевезень?",a="Це робочий журнал, який веде начальник доків Братства Дефіас на Пристані Джерода. У ньому розписано, як контрабанду й припаси переправляють між Редріджем і Вестфолом внутрішніми водами Лісу Елвінн.",al={"розклад перевезень дефіас","що це за документ","розклад портового майстра"}},{q="Хто хоче повернути цей розклад?",a="Майстер Матіас Шоу, очільник розвідувальної служби Стормвінда SI:7. Ці відомості допомагають йому стежити за контрабандною мережею Дефіасу й оцінювати перспективних розбійників у ділі.",al={"хто хоче розклад","розклад матіаса шоу","хто бере розклад перевезень"}},{q="Де знайти розклад?",a="Документ носить при собі Начальник Доків Дефіасу в будиночку на Пристані Джерода — на Річці Назферіті на південь від Ґолдширу в Лісі Елвінн. Агентові треба прокрастися в будівлю й поцупити розклад із його кишені або забрати з тіла.",al={"місце розкладу","де портовий майстер","як отримати розклад"}},{q="Для чого використовують Пристань Джерода?",a="Бандити Дефіасу захопили Пристань Джерода й зробили з неї перевалочний пункт. Річкою вони переправляють незаконні вантажі через королівство, сполучаючи свої операції в Редріджі просто з твердинями у Вестфолі.",al={"пристань джерода дефіас","чому дефіас мають пристань джерода","пристань дефіас ельвін"}}},fp="17,271,28.453.0,25.408.0,30.224.0,34.184.0,28.235.0,33.225.0"}
P.entries["item:sida-s-bag"] = {n="Сумка Сіди",s="Сумка Сіди — особиста торба Сіди, мешканки Гавані Менетіл. Її цілком проковтнув повзучий слиз, коли Сіда навідалася до Гробниці Айронбірда, тож щоб повернути сумку й її загадковий вміст, доведеться ретельно пошукати серед їдких слизів Багнокраю.",h="Сумка Сіди — особиста торба Сіди, мешканки Гавані Менетіл.",kw={"сумка сіди","сіда","слизи","гробниця айронбірда","гавань менетіл","багнокрай"},ang={["faction:Alliance"]="Знеможені біженці й мешканці Гавані Менетіл цілком покладаються на мандрівників, щоб упоратися з хижими жахіттями, що наповзають із затопленого Багнокраю."},sec={{t="Панічна оборона",b="Навідуючись, як щотижня, до Гробниці Айронбірда біля Дун Модра, Сіда натрапила на жахливі сочисті слизи, що кишать у тих краях. Запанікувавши перед драглистою масою, що насувалася, вона жбурнула свою торбу просто в одну з істот. Слиз не відступив — він просто вбрав торбу у своє драглисте тіло. Та ця заминка дала Сіді кілька дорогоцінних миттєвостей, щоб утекти й урятуватися в Гавані Менетіл, а її речі лишилися в нутрі невідомого слизу."},{t="Повернута зі слизу",b="Оскільки хвилясті слизи, що повзають довкола Гробниці Айронбірда, — від багряних до велетенських — майже не відрізняються, щоб знайти торбу, доведеться розправлятися з болотяними слизами, доки проковтнута торба не з'явиться цілою. Попри те що вона мокла в їдкій травній багнюці, міцний мішок зберіг свій вміст. Отримавши його назад, Сіда радо забирає свої речі, а зіпсовану, вкриту слизом торбу віддає тому, хто наважився піти на болота заради неї."}},faq={{q="Як Сумка Сіди опинилася в слизі?",a="Сіда запанікувала, коли на неї напали слизи під час відвідин Гробниці Айронбірда. Відчайдушно рятуючись, вона жбурнула свою торбу в одне з чудовиськ, і те відразу поглинуло її цілком.",al={"як слиз отримав сумку","чому сумка в слизі","як сіда загубила сумку"}},{q="У яких слизів може бути Сумка Сіди?",a="Сіда не розрізняє слизів, тож проковтнути сумку міг будь-який хижий слиз довкола Гробниці Айронбірда на північному сході Багнокраю — багряний, чорний чи жахливий.",al={"де сумка сіди","хто дропає сумку сіди","який слиз має сумку"}},{q="Навіщо Сіда ходить до Гробниці Айронбірда?",a="Щотижня Сіда вирушає з Гавані Менетіл до давнього дворфського склепу біля Дун Модра, але причини цих постійних відвідин тримає при собі.",al={"зв'язок сіди з айронбірдом","чому гробниця айронбірда"}},{q="Що було в Сумці Сіди?",a="Сіда швиденько висипає повернені речі на землю й збирає їх, не показуючи, що це, — лише зауважує, що вміст був надто важливий, щоб лишити його розчинятися в слизі.",al={"що сіда дістає з сумки","вміст сумки"}}},fp="10,265,18.532.0,24.496.0,34.209.0,29.208.0,37.175.0,27.196.0"}
P.entries["item:signed-recruitment-letter"] = {n="Підписаний Вербувальний Лист",s="Підписаний вербувальний лист — офіційне розпорядження, видане Каргалом Баттлскаром на Далекій Дозорній Заставі. З печаткою Каргала він переводить новобранців углиб посушливих Пусток — на службу до Перехрестя.",h="Підписаний вербувальний лист — офіційне розпорядження, видане Каргалом Баттлскаром на Далекій Дозорній...",kw={"підписаний вербувальний лист","каргал баттлскар","далека дозорна застава","серґра даркторн","перехрестя","новобранці"},ang={["class:Shaman"]="Цей документ віддає вас на службу Серґрі Даркторн — знаній оркській шаманці, якій Тралл доручив допомогти втримати Пустки.",["faction:Horde"]="Вербувальний лист знаменує ваш перехід від початкової служби в Дуротарі до ширшої військової машини Орди на рубежах."},sec={{t="Переведення новобранця",b="Далека Дозорна Застава — східний поріг Пусток, і тут оцінюють новоприбулих, що переходять Річку Південної Люті з Дуротару. Щойно новобранець доведе Каргалові Баттлскару свою готовність, той ставить печатку й підписує цей рекомендаційний лист. Він править за військовий наказ, що скеровує новобранців дорогою на захід, до Перехрестя, де Серґра Даркторн керує постачанням і обороною сухих рівнин."},{t="Напруга між заставами",b="Хоч лист — офіційний документ Орди, Каргал не приховує особистої зневаги до офіцерки, що чекає на новобранця. Серґра Даркторн для нього — різка шаманка, яка перебалакає будь-якого солдата, і він відкрито сумнівається у високій думці Вождя Тралла про неї. Попри ці сумніви, лист треба вручити просто в руки Серґрі, перш ніж на Перехресті дадуть будь-які нові доручення."}},faq={{q="Для чого потрібен Підписаний Вербувальний Лист?",a="Лист — це офіційний папір про військове переведення. Він доводить Серґрі Даркторн на Перехресті, що Каргал Баттлскар перевірив вас на Далекій Дозорній Заставі й визнав готовим до служби в Пустках.",al={"що робить цей лист","використання вербувального листа","підписаний лист пустища"}},{q="Хто підписав лист?",a="Каргал Баттлскар — орк-ветеран, що наглядає за Далекою Дозорною Заставою на кордоні Дуротару й Пусток. Він підписує лист, коли новобранець виконає перші доручення на кордоні.",al={"хто написав лист","лист каргала","хто підписав"}},{q="Кому я маю доставити лист?",a="Ви доставляєте його Серґрі Даркторн — впливовій оркині-шаманці, що стоїть на центральному роздоріжжі Перехрестя.",al={"куди нести лист","кому віддати лист","одержувач листа"}},{q="Чому Каргал погано відгукується про Серґру Даркторн?",a="Каргал вважає Серґру гострою на язик, важкою у спілкуванні офіцеркою, що марнує час на балачки, коли треба працювати. Хоча Вождь Тралл високо її цінує, Каргал і далі скептично ставиться до її керівництва.",al={"ворожнеча каргала й серґри","чому каргал ненавидить серґру"}}},fp="25,236,22.437.0,23.422.0,53.209.0,22.186.0,31.118.0,49.214.0"}
P.entries["item:silithid-egg-the-barrens"] = {n="Яйце Силітида (Пустки)",s="Яйця силітидів — виводок комахоподібних істот, що гніздяться на півдні Пусток. Ці кладки, закопані в земляних кучугурах довкола Поля Велетнів, збирають дослідники Орди, які прагнуть з'ясувати, звідки взявся рій, що насувається, і наскільки він розумний.",h="Яйця силітидів — виводок комахоподібних істот, що гніздяться на півдні Пусток.",kw={"яйце силітида","силітиди","поле велетнів","корран","рій","пустки"},ang={["faction:Horde"]="Поява розумних роїв комах так близько від Перехрестя — тривожна загроза для торгових шляхів і земель Орди в центральному Калімдорі."},sec={{t="Загадковий рій",b="У посушливій улоговині Поля Велетнів дивні комахоподібні істоти почали перетворювати землю на височенні кучугури. Глибоко в цих гніздах, під затверділим ґрунтом, лежать їхні яйця, які пильно стережуть виводки. Орда знає про силітидів напрочуд мало, але розвідники з Перехрестя помітили ознаки злагодженої поведінки й моторошного розуму, що далеко перевершує звичайних диких звірів. Зібрані невилуплені яйця — найкращий шанс для вчених Оргріммара вивчити життєвий цикл і природу цієї нової загрози."},{t="Розкопки й небезпека",b="Щоб дістатися до яєць, доводиться розколупувати кучугури силітидів особливими копальними кігтями. Тривожити ці кладки — небезпечна справа: силітиди люто відповідають на кожне вторгнення до своїх підземних розплідників і роєм накидаються на будь-кого, хто загрожує їхньому невилупленому потомству. Для дослідників на кшталт троля Коррана цілі, неушкоджені зразки — ключ до вивчення, поки рій не поширився далі Калімдором."}},faq={{q="Що таке Яйця Силітида?",a="Це невилуплені кладки комахоподібних силітидів, що гніздяться в земляних пагорбах на півдні Пусток, особливо на Полі Велетнів.",al={"яйце силітида","що таке яйце силітида","кургани силітидів"}},{q="Хто хоче зібрати ці яйця?",a="Корран, троль-дослідник із Перехрестя, збирає їх для своїх господарів в Оргріммарі, щоб вивчити дивну будову й поведінку силітидів.",al={"кому потрібні яйця","завдання коррана","видавець завдання на яйця"}},{q="Навіщо вивчають силітидів?",a="Орда майже нічого не знає про силітидів. Корран зауважує, що вони виявляють ознаки розуму й злагодженості, яких не мають звичайні дикі тварини, і їхня раптова поява в Пустках непокоїть провідників Орди.",al={"чому вивчати силітидів","загроза силітидів","чи силітиди розумні"}},{q="Як збирають яйця?",a="Їх треба обережно викопати з пагорбів силітидів пристосованим копальним кігтем, відбиваючись від лютого рою, що захищає гнізда.",al={"як збирати яйця","копальний кіготь","збір яєць силітидів"}}},fp="26,282,18.552.0,21.406.0,23.163.0,31.165.0,35.230.0,26.145.0"}
P.entries["item:silixiz-s-tower-key"] = {n="Ключ від Вежі Сіліксиза",s="Ключ від Вежі Сіліксиза — маленький ключ, який носить Наглядач Сіліксиз біля вежі Венчурної Компанії поблизу Багнистого Болота. Агентам Орди з Розтрощеної Руки доручено витягти його просто з кишені наглядача під час таємної диверсії.",h="Ключ від Вежі Сіліксиза — маленький ключ, який носить Наглядач Сіліксиз біля вежі Венчурної Компанії поблизу...",kw={"ключ від вежі","наглядач сіліксиз","венчурна компанія","розтрощена рука","розбійник","пустки"},ang={["class:Rogue"]="Здобути Ключ від Вежі Сіліксиза — важливе випробування для розбійників Орди, що вступають до лав Розтрощеної Руки: воно вимагає вміння скрадатися й обчищати кишені.",["faction:Horde"]="Ключ — важливий трофей у протистоянні грабіжницькому промислу й хімічним дослідам Венчурної Компанії, що загрожують північним Пусткам."},sec={{t="Випробування спритності",b="Об'єкт Венчурної Компанії на північ від Багнистого Болота добре охороняють, а його серце — відокремлена сторожова вежа під наглядом Великого Наглядача Пузіка Ґаллівікса. За межами табору, який патрулюють гоблінські найманці, Наглядач Сіліксиз носить ключ від вежі, який агент Розтрощеної Руки має викрасти й залишити собі. Для мережі розбійників Розтрощеної Руки, що діє з Оргріммара, здобути цей ключ — справа не грубої сили: агенти мусять непомітно прослизнути в табір і чисто обчистити кишені наглядача, довівши свою вправність у потайливості, перш ніж піднятися на отруєні верхні поверхи."}},faq={{q="Де знайти Наглядача Сіліксиза?",a="Наглядач Сіліксиз стоїть біля вежі Венчурної Компанії просто на північ від Багнистого Болота, у північно-східній частині Пусток.",al={"місце сіліксиза","де наглядач сіліксиз","знайти сіліксиза"}},{q="Чи можна здобути ключ, убивши Наглядача Сіліксиза?",a="Ні. З його тіла ключ не взяти. Агентам доводиться непомітно поцупити його з кишені наглядача, поки той живий.",al={"дроп ключа сіліксиза","чи можна вбити сіліксиза","здобути ключ сіліксиза"}},{q="Кому потрібен цей ключ?",a="Ключ — частина доручення від зв'язкових Розтрощеної Руки: його треба доставити Шентулу, наставникові розбійників, що ховається в тінях Оргріммара.",al={"кому потрібен ключ","здати ключ сіліксиза","завдання ключа вежі сіліксиза"}},{q="Для чого використовують ключ?",a="Ключ доводить, що ви проникли до вежі Венчурної Компанії біля Багнистого Болота. Його здають Розтрощеній Руці разом із головою Великого Наглядача Пузіка Ґаллівікса та схованкою зміненої суміші Занзіла.",al={"що відчиняє ключ сіліксиза","призначення ключа сіліксиза","використання ключа вежі"}}},fp="19,274,18.618.0,32.149.0,48.155.0,22.146.0,25.221.1"}
P.entries["item:silvery-spinnerets"] = {n="Сріблясті Павутинні Залози",s="Сріблясті павутинні залози добувають у великої павучихи Леді Сатри на півночі Тельдрассилу. Колись вони ткали павутину, що збирала цілющу вечірню росу для Храму Місяця, а тепер їх шукають жриці Елуни, щоб у священному обряді відродження вшанувати душу полеглої істоти.",h="Сріблясті павутинні залози добувають у великої павучихи Леді Сатри на півночі Тельдрассилу.",kw={"сріблясті павутинні залози","леді сатра","жертва сатри","павучиха","храм місяця","сестринство елуни","озеро джерела"},ang={["class:Priest"]="Для служителів Елуни добування залоз — не замовлення на винищення, а священний похоронний обряд, яким благають Місячну Матір про спасіння душі істоти.",["race:NightElf"]="Трагічний кінець Леді Сатри — тверезе нагадування калдореям, що навіть улюблені Елуною створіння вразливі до підступної недуги, яка точить Тельдрассил."},sec={{t="Священна павутина і скверна",b="Колись Леді Сатра належала до улюблених створінь Елуни й славилася мерехтливою павутиною, яку пряла в місячному сяйві біля Озера Джерела. Її срібний шовк збирав вечірній туман, і з нього утворювалася цілюща роса, яку високо цінувало Сестринство Елуни в Дарнасусі. На жаль, скверна, що розповзається гіллям Тельдрассилу, не оминула й її. Пойнята шаленим безумством, Сатра стала небезпечною для власного виводку й для довколишнього лісу. Жриця А'мура просить мандрівників припинити страждання павучихи й забрати її залози — це акт милосердя, гідне прощання з шанованою мешканкою великого гілля."},{t="Жертва заради відродження",b="Залози шукають не як трофей і не як матеріал для ремесла. Сестринство підносить їх просто Богині Місяця на вершині Храму Місяця. Цим освяченням, яке звуть Жертвою Сатри, жриці моляться, щоб Елуна прийняла дух істоти, очистила божевілля, що опанувало її смертне тіло, і дарувала їй спокій у Відродженні."}},faq={{q="Де взяти Сріблясті Павутинні Залози?",a="Їх здобувають із Леді Сатри — великої павучихи, що живе на північних околицях Тельдрассила біля Озера Джерела.",al={"де знайти сріблясті павутинні залози","дроп сріблястих павутинних залоз","хто дропає сріблясті залози"}},{q="Навіщо Жриці А'мурі ці залози?",a="Жриця А'мура хоче піднести їх Елуні як священну жертву. Цей обряд вшановує колишню чистоту Леді Сатри й благає богиню очистити дух створіння, дарувати йому спокій і відродження.",al={"навіщо жриці а'мурі залози","призначення сліз місяця"}},{q="Чим було особливе павутиння Леді Сатри?",a="Леді Сатра пряла сяйливий срібний шовк, що вловлював вечірній туман у місячному світлі. Роса з її павутиння мала потужну цілющу магію, і Сестринство Елуни зберігало її в Храмі Місяця для зцілення.",al={"павутиння леді сатри","що робила леді сатра"}},{q="Чому Леді Сатру вбили, якщо вона була священною?",a="Вона, як і інші осквернені звірі Тельдрассила, поринула в невиліковне божевілля. Її лютість загрожувала лісу й майбутнім виводкам, тож жриці вирішили, що вбити її — сумний акт милосердя.",al={"чому вбити леді сатру","чому сатра збожеволіла"}}},fp="18,293,29.621.0,23.379.1,40.121.0,47.206.0,37.233.0,46.227.0"}
P.entries["item:simple-memorandum"] = {n="Проста Службова Записка",s="Проста Службова Записка — офіційне повідомлення, яке вручають гномам-воїнам-новачкам, що навчаються в Долині Холодного Хребта. Написана від імені наставника воїнів Трана Кормана, вона наказує новачкам з'явитися до нього в Анвілмар, щоб удосконалити бойову дисципліну.",h="Проста Службова Записка — офіційне повідомлення, яке вручають гномам-воїнам-новачкам, що навчаються в Долині...",kw={"проста службова записка","воїн","тран корман","гноми","анвілмар","долина холодного хребта","гномреґан"},ang={["class:Warrior"]="Ця записка — перший крок воїна від простих сутичок до офіційного бойового навчання під проводом Трана Кормана в Анвілмарі.",["race:Gnome"]="Для гномів-вигнанців записка — нагадування про спільну мету: відточувати бойові навички пліч-о-пліч з дворфійськими союзниками, готуючись до майбутнього визволення Гномреґану."},sec={{t="Виклик до Анвілмара",b="Шукачам пригод-новачкам у Долині Холодного Хребта часто довіряють рекомендаційні листи, щойно вони покажуть свою вправність проти місцевої звірини й трогів. Для молодих гномів-бійців ця записка — офіційний виклик від Трана Кормана, наставника воїнів в Анвілмарі. Дворфійські ветерани визнають: хоч гноми й покладаються на розум і пристрої, повернути Гномреґан удасться лише завдяки чистій фізичній рішучості й бойовій дисципліні. Записка велить власникові відкласти попередні доручення й шукати особистих настанов у мистецтві війни."}},faq={{q="Що таке Проста Службова Записка?",a="Це письмове повідомлення для гномів — воїнів-початківців у Долині Холодного Хребта: воно велить їм з'явитися до дворфа — наставника воїнів в Анвілмарі.",al={"проста службова записка","що це за записка","предмет службова записка"}},{q="Хто написав Просту Службову Записку?",a="Записку надіслав Тран Корман, дворф — наставник воїнів з Анвілмара, який шукає й готує перспективних новачків.",al={"хто написав службову записку","хто надіслав записку","автор простої службової записки"}},{q="Що стається, коли прочитати Просту Службову Записку?",a="Прочитавши документ, ви несете його Транові Корману в Анвілмар. Він відзначає вашу рішучість повернути втрачений дім і пропонує навчити вас основ воїнської майстерності.",al={"що робити зі службовою запискою","куди нести","здати просту службову записку"}},{q="Чому дворф навчає гномів-воїнів?",a="Після падіння Гномреґану гноми-біженці знайшли притулок в Айронфорджі та Анвілмарі. Дворфи-ветерани, як-от Тран Корман, пообіцяли поділитися бойовим досвідом, щоб допомогти вигнаним союзникам вишколитися й зрештою відвоювати своє опромінене місто.",al={"чому тран навчає гномів","дворфи навчають гномів"}}},fp="17,254,21.599.0,30.160.0,32.151.0,49.194.0,39.260.0"}
P.entries["item:simple-rune"] = {n="Проста Руна",s="Проста Руна — кам'яний знак із написом, який вручають дворфам-воїнам-новачкам, що навчаються в Долині Холодного Хребта. Це виклик від наставника воїнів Трана Кормана, який велить новобранцям шукати настанов в Анвілмарі.",h="Проста Руна — кам'яний знак із написом, який вручають дворфам-воїнам-новачкам, що навчаються в Долині...",kw={"проста руна","воїн","тран корман","анвілмар","долина холодного хребта","дворфи","вишкіл"},ang={["class:Warrior"]="Для дворфійських воїнів цей камінь із написом — перший крок до офіційного військового вишколу під проводом досвідченого наставника Трана Кормана.",["race:Dwarf"]="Дворфи традиційно покладаються на міцні руни з написами для наказів, нагадувань і бойових викликів, а не на крихкий пергамент."},sec={{t="Заклик до зброї",b="Просту Руну з вирізьбленими базовими бойовими знаками вручають перспективним новобранцям, які почали розчищати загрози довкола Долини Холодного Хребта. Це не магічний оберіг, а офіційний камінь-виклик від Трана Кормана, наставника воїнів в Анвілмарі. Прочитавши вирізьблені настанови, молодий боєць має з'явитися просто до Трана, щоб опанувати основи бою й почути практичні поради, як вижити серед ворожих пустищ Дун Мороґу."}},faq={{q="Для чого потрібна Проста Руна?",a="Проста Руна — табличка з настановою для новачків-воїнів у Долині Холодного Хребта. Вона велить новобранцеві з'явитися до Трана Кормана в Анвілмарі на справжнє навчання.",al={"використання простої руни","що робить руна","предмет завдання проста руна"}},{q="Хто надсилає Просту Руну?",a="Її надсилає Тран Корман, дворф — наставник воїнів з Анвілмара, який пильно стежить за перспективними бійцями, що допомагають у долині.",al={"хто написав руну","хто дав просту руну","відправник руни"}},{q="Куди нести Просту Руну?",a="Віднесіть її Транові Корману до великої кузні-зали Анвілмара в центрі Долини Холодного Хребта.",al={"куди йти","здати руну","місце трана хормана"}}},fp="11,227,17.463.0,39.198.0,26.145.0,32.102.0"}
P.entries["item:simple-sigil"] = {n="Простий Сигіл",s="Простий Сигіл — скромний навчальний знак, який вручають новачкам-воїнам — нічним ельфам у Тінедолі. Принесений як виклик від наставниці воїнів Алііссії, він позначає офіційне долучення молодого бійця до збройного захисту Тельдрассила.",h="Простий Сигіл — скромний навчальний знак, який вручають новачкам-воїнам — нічним ельфам у Тінедолі.",kw={"простий сигіл","воїн","алііссія","консерватор ілталайн","тінедол","тельдрассил","фералас"},ang={["class:Warrior"]="Для калдорейських воїнів цей простий знак — ваша найперша грамота, що знайомить вас із бойовими традиціями, потрібними для захисту Тельдрассила.",["race:NightElf"]="Сигіл підкреслює нагальність становища калдореїв: наставниці на кшталт Алііссії набирають усі здатні руки, щоб спинити дедалі більшу скверну у вітті Світового Дерева."},sec={{t="Поклик до зброї",b="У затишному вітті Тінедолу молодих нічних ельфів веде до їхнього покликання Консерватор Ілталайн. Майбутнім воїнам Ілталайн вручає Простий Сигіл, надісланий гінцем від наставниці воїнів Алііссії. Із написом, що велить новобранцеві з'явитися на навчання, цей знак — початок дисциплінованого бойового вишколу в тривожний для Світового Дерева час."},{t="Тягар Захисту",b="Принесений Алііссії, сигіл відкриває розмову про нагальний стан калдореїв. Нещодавнє зростання Тельдрассила, повзуча скверна, що вражає лісових звірів, і віднайдення далеких земель на кшталт Фераласа розтягли сили захисників нічних ельфів до краю. Сигіл — не артефакт сили, а практична грамота, що приймає новобранця до лав охоронців, яким доручено затуляти свій народ від нових загроз."}},faq={{q="Що таке Простий Сигіл?",a="Це вступний знак із написом, який Консерватор Ілталайн у Тінедолі дає нічним ельфам — воїнам-початківцям. Він велить власникові з'явитися до Алііссії на навчання воїнської справи.",al={"предмет простий сигіл","що робить простий сигіл","що це за сигіл"}},{q="Хто надсилає Простий Сигіл?",a="Сигіл передає гонець від імені Алііссії, наставниці воїнів у Тінедолі, яка хоче почати навчати нових воїнів захищати Тельдрассил.",al={"хто зробив сигіл","хто надіслав простий сигіл"}},{q="Що з ним робити?",a="Прочитайте напис і віднесіть сигіл Алііссії до підніжжя Алдрассила в Тінедолі, щоб розпочати навчання воїна.",al={"куди здати простий сигіл","хто бере простий сигіл"}},{q="Чи дає сигіл якісь особливі вміння?",a="Ні. Це лише письмове повідомлення й посвідчення, що знайомить майбутніх воїнів із наставником.",al={"сили сигіла","характеристики простого сигіла"}}},fp="12,238,17.413.0,21.439.0,25.188.0,27.178.0,25.126.0,43.102.0"}
P.entries["item:simple-tablet"] = {n="Проста Табличка",s="Проста Табличка — письмове послання, яке отримують тролі-воїни-новачки, прибувши в Долину Випробувань. Передана Ґорнеком, вона велить бійцю-початківцю з'явитися до Франґа, тутешнього наставника воїнів.",h="Проста Табличка — письмове послання, яке отримують тролі-воїни-новачки, прибувши в Долину Випробувань.",kw={"проста табличка","воїн","франґ","ґорнек","тар'сере","долина випробувань"},ang={["class:Warrior"]="Табличка — офіційне знайомство троля-воїна з Франґом, з якого починається його бойовий вишкіл в Орді.",["race:Troll"]="Для тролів Темного Списа, що виборюють своє місце поряд з орками в Дуроторі, цей виклик означає обов'язок поповнити лави на передовій."},sec={{t="Поклик до бою",b="У суворих червоних межах Долини Випробувань новобранців швидко беруть у роботу. Молодим тролям, що шукають шляху воїна, Ґорнек передає цю просту плитку чи пергамент. Написана тролем Тар'сере і адресована Франґу — майстру зброї, що відпочиває біля Лігва, — вона слугує офіційним вступом до бойового вишколу в Дуроторі. Вона закликає новобранця виступити вперед, назватися й довести готовність махати зброєю під стягом Орди."}},faq={{q="Що таке Проста Табличка?",a="Це вступне письмове повідомлення, яке Ґорнек передає тролям — майбутнім воїнам у Долині Випробувань. Воно велить прочитати його й розшукати Франґа, щоб пройти справжній бойовий вишкіл.",al={"проста табличка","що це за табличка","табличка троля-воїна"}},{q="Хто надсилає табличку?",a="Повідомлення підписав троль Тар'сере, який посилає новобранця до Франґа — наставника воїнів біля Лігва в Долині Випробувань.",al={"хто надіслав просту табличку","хто написав табличку","відправник таблички"}},{q="Куди нести табличку?",a="Віднесіть її Франґові — він відпочиває в затінку біля входу до Лігва в Долині Випробувань.",al={"кому віддати просту табличку","куди нести табличку","місце франґа"}},{q="Хто отримує цю табличку?",a="Просту Табличку дають саме тролям-воїнам, що проходять обряд посвяти в Долині Випробувань.",al={"чи може будь-хто отримати просту табличку","який клас отримує просту табличку"}}},fp="13,219,19.491.0,26.186.0,21.147.0,27.113.0,25.118.0"}
P.entries["item:singed-scale"] = {n="Обпалена Луска",s="Обпалена луска — обвуглені, загартовані розрядами пластини, здобуті з наелектризованих громоящерів Дуротару. Здобути їх — обряд посвяти для молодих воїнів Орди, які прагнуть опанувати мистецтво оборонного бою.",h="Обпалена луска — обвуглені, загартовані розрядами пластини, здобуті з наелектризованих громоящерів Дуротару.",kw={"обпалена луска","громоящери","громовий хребет","уззек","воїн","далека дозорна застава"},ang={["class:Warrior"]="Для воїна, який лише набирається сили, принести ці луски Уззекові — важлива віха на шляху до розуміння науки захисту й до вміння стати непробивним щитом Орди.",["faction:Horde"]="Випробування на Далекій Дозорній Заставі гарантують, що вартові й передові загони на рубежах Дуротару й Пусток мають незламну витривалість."},sec={{t="Випробування витривалості",b="Для ветеранів Орди справжнього воїна міряють не лише кров'ю, яку пролила його сокира, а й ударами, які він здатен прийняти, щоб захистити союзників. У посушливій ущелині Громового Хребта на заході Дуротару блискавошкурі та громоящери аж тріщать від мінливої грозової енергії. Полюючи на цих звірів, воїн мусить витримувати безупинні електричні удари й нищівні атаки. Почорніла, обпалена луска, здерта з їхніх шкур, — незаперечний доказ того, що боєць уміє вистояти під жорстоким натиском і втриматися там, де слабші солдати впали б."},{t="Шлях щита",b="На Далекій Дозорній Заставі, на кордоні між Дуротаром і Пустками, ветеран-воїн Уззек вимагає від новачків п'ять таких лусок, перш ніж передати їм свої знання. На думку Уззека, новачок мусить мати природну фізичну міць, перш ніж збагне тонку науку бойових стійок і тактичної оборони. Принесена луска показує, що воїн має досить стійкості, аби поєднати товсту шкуру, важкий обладунок і виважену роботу ніг у непохитну стіну проти ворогів Орди."}},faq={{q="Для чого потрібна Обпалена Луска?",a="Обпалена луска — доказ бойової витривалості. Наставник воїнів Уззек вимагає п'ять лусок, щоб переконатися, що новачок досить загартований для вивчення складніших захисних прийомів.",al={"використання обпаленої луски","хто хоче обпалену луску","завдання обпаленої луски"}},{q="Де знайти обпалену луску?",a="Її збирають із громоящерів і блискавошкірих ящерів, що живуть на Громовому Хребті — у каньйоні на заході Дуротару, просто через річку від Пусток.",al={"місце обпаленої луски","де взяти обпалену луску","як отримати обпалену луску"}},{q="Чому луска обпалена?",a="Громоящери від природи пропускають крізь тіло блискавки й електричні бурі. Безупинне тріскотіння стихійної енергії обпалює й чорнить їхню шкуру, тож луска стає обвугленою на дотик.",al={"чому обпалена","чому луска згоріла"}},{q="Хто такий Уззек і навіщо йому ця луска?",a="Уззек — воїн-ветеран, що служить на Далекій Дозорній Заставі на сході Пусток. Він навчає молодих воїнів Орди захисного бою, але вимагає, щоб ті спершу довели свою витривалість у сутичках зі смертоносними звірами.",al={"хто такий уззек","уззек"}}},fp="12,221,19.575.0,21.515.0,32.205.0,32.155.0,26.215.0,53.237.0"}
P.entries["item:skeleton-finger"] = {n="Палець Кістяка",s="Відламаний кістлявий палець, здобутий із ходячих мерців, що нишпорять проклятими гаями й цвинтарями Сутінколісся. Мадам Єва з Даркшира збирає ці моторошні рештки разом з іклами гулів і павучою отрутою, щоб виготовляти захисні талісмани.",h="Відламаний кістлявий палець, здобутий із ходячих мерців, що нишпорять проклятими гаями й цвинтарями...",kw={"палець кістяка","кістяки","мадам єва","тотем покари","даркшир","сутінколісся"},ang={["class:Mage"]="Маги, що вивчають народне ворожіння, побачать у методі Мадам Єви, яка обертає пальці кістяків і природні отрути на мстиві чари, незвичне поєднання сільського відьомства й симпатичної магії.",["class:Paladin"]="Паладини можуть здригатися від думки, що оскверняють кістяки й носять при собі їхні відламані частини, та в зловісних сутінках Сутінколісся обертати кістки нечестивих на захист живих — сувора необхідність."},sec={{t="Кістки неспокійних",b="Проклятий ліс Сутінколісся заполонили неспокійні рештки мерців — від кістяків-нападників і кістяків-воїнів до некротичних магів і виродків. Звичайні подорожні уникають торкатися бридких решток повсталих мерців, але ворожки й містики цінують їхню холодну сутність. Мадам Єва, віщунка Даркшира, збирає ці кістляві пальці, щоб скріпити їхню залишкову некротичну силу в оберіг мстивої магії — Тотем Покари."}},faq={{q="Які створіння залишають Палець Кістяка?",a="Пальці Кістяка здобувають із різної скелетної нежиті по всьому Сутінколіссю: скелетів-грабіжників, цілителів, охоронців, воїнів, жахів, виродків і скелетів-магів.",al={"де падає палець кістяка","що дропає пальці кістяка","джерело пальця кістяка"}},{q="Кому в Сутінколіссі потрібні Пальці Кістяка?",a="Мадам Єві, віщунці з Даркширу: вони потрібні їй як складник ритуалу, щоб зачарувати захисний оберіг.",al={"кому потрібні пальці кістяка","видавець завдання на пальці кістяка","для чого пальці кістяка"}},{q="Що таке Тотем Покари?",a="Це зачарований оберіг, який Мадам Єва виготовляє з пальців кістяків, іклів гулів і павучої отрути. Вона сплітає їхню темну енергію в ауру, що завдає відплатної шкоди кожному, хто наважиться напасти на власника.",al={"призначення тотема покари","що робить мадам єва"}},{q="Навіщо Мадам Єві рештки нежиті для захисного оберегу?",a="Ритуали Мадам Єви спрямовують приховану скверну й лютість місцевих чудовиськ. Зв'язуючи докупи жорстоку сутність скелетів, гулів і отруйних звірів Сутінколісся, вона обертає їхню затяту злобу на оберіг, що карає нападників.",al={"чому кісткова магія","чому пальці кістяка для тотема"}}},fp="15,234,21.460.0,38.179.0,39.130.0,32.235.0,63.269.0"}
P.entries["item:skin-of-sweet-rum"] = {n="Бурдюк Солодкого Рому",s="Бурдюк Солодкого Рому — особливий трунок із Корчми «Лев'яча Гордість» у Ґолдширі. Його розшукує Шинкар Деніелс у Лейкширі, який усіма силами намагається втримати запаси своєї таверни, поки орки Блекрок відрізали Редрідж від звичних торгових шляхів.",h="Бурдюк Солодкого Рому — особливий трунок із Корчми «Лев'яча Гордість» у Ґолдширі.",kw={"бурдюк солодкого рому","ром","лев'яча гордість","ґолдшир","шинкар деніелс","лейкшир"},ang={["faction:Alliance"]="Доставка цього рому показує, якого тягаря вторгнення орків Блекрок завдало невеликим поселенням, що боронять східні кордони королівства Стормвінд."},sec={{t="Рідкісна розрада для Лейкширу",b="У виснаженому війною Лейкширі запаси таверни небезпечно тануть. Вторгнення орків Блекрок перекрило дороги до Гір Редріджу, і Шинкар Деніелс ледве встигає вгамовувати спрагу знесилених вартових і біженців. Щоб поповнити спорожнілі полиці, Деніелс розсилає мандрівників по всьому королівству по трунки, якими славиться кожен край, зокрема по бурдюк того самого солодкого рому, який варять і наливають у ґолдширській Корчмі «Лев'яча Гордість»."}},faq={{q="Де знайти Бурдюк Солодкого Рому?",a="Бурдюк Солодкого Рому можна купити просто в корчмаря чи шинкаря в Корчмі «Лев'яча Гордість» у Ґолдширі, що в Лісі Елвінн.",al={"місце солодкого рому","де купити солодкий ром","хто продає солодкий ром"}},{q="Кому потрібен цей ром?",a="Шинкар Деніелс, власник таверни в Лейкширі, у завданні «Сухі часи» просить бурдюк Солодкого Рому та кілька інших місцевих напоїв, щоб поповнити спорожнілі запаси.",al={"кому потрібен солодкий ром","здати солодкий ром","завдання солодкого рому"}},{q="Чому в Лейкширі закінчується випивка?",a="Раптовий наступ орків Блекрок у Редріджі перерізав торгові шляхи й затримав постачання до містечка. Звичайні купецькі вози не можуть безпечно проїхати дорогами, тож місцеві запаси майже вичерпано.",al={"чому закінчилася випивка","чому лейкшир сухий","причина сухих часів"}},{q="Які ще напої потрібні, крім рому?",a="Окрім Бурдюка Солодкого Рому з Ґолдширу, Шинкареві Деніелсу потрібні ще барильце лагера Тандербрю з Вестфолу, барило мерло зі Стормвінда та пляшка самогону з Даркширу.",al={"напої сухих часів","список напоїв деніелса","яка ще випивка потрібна"}}},fp="17,252,28.488.0,37.140.0,19.186.0,39.216.0,48.196.0"}
P.entries["item:skittering-blood"] = {n="Метушлива Кров",s="Метушлива Кров — алхімічний реагент, який добувають із павуків, що живуть у Метушливій Темряві в Срібноліссі. Це важливий отруйний складник для досліджень Королівського Аптекарського Товариства над Новою Чумою, що має знищити і Погибель, і людство.",h="Метушлива Кров — алхімічний реагент, який добувають із павуків, що живуть у Метушливій Темряві в Срібноліссі.",kw={"метушлива кров","метушлива темрява","павуки","кретіс тінепрядка","нова чума","аптекар ренферрел","головний аптекар фаранелл"},ang={["faction:Horde"]="Аптекарі-Відступники радо приймають цю сировину, щоб утримати Лордерон, але інші члени Орди часто дивляться на заразні варива з цієї крові з моральним неспокоєм.",["race:Undead"]="Здобуваючи Метушливу Кров, ви прямо допомагаєте королеві Сильвані й Королівському Аптекарському Товариству створити найдосконалішу біологічну зброю проти Артаса й живого людства."},sec={{t="Отруйний дистилят",b="Цю отруйну гемолімфу добувають із павуків Метушливого Павутиння — чатівників і нападників — та з їхньої матки, Кретіс Тінепрядки. Алхіміки-Відступники дуже цінують її заразні властивості. Аптекар Ренферрел з'ясував, що в поєднанні з отрутою із сердець сивих ведмедів ця кров стає основою надзвичайно смертоносного еліксиру. Сполуки в рідині містять сильні заразні речовини, тож вона — ідеальний біологічний каталізатор для хімічних дослідів Апотекаріуму."},{t="Паливо для Нової Чуми",b="Під керівництвом Головного Аптекаря Фаранелла в Андерсіті Королівське Аптекарське Товариство збирає такі реагенти, як Метушлива Кров, щоб створити нищівну Нову Чуму. Перед лицем незліченних полчищ Погибелі й ворожих решток людства Відступники бачать у біологічній війні спосіб урівняти сили. Фаранелл вивчає отруйну силу крові, щоб виплекати заразу, здатну загасити і нежиття, і живу плоть."}},faq={{q="Для чого потрібна Метушлива Кров?",a="Королівське Аптекарське Товариство використовує Метушливу Кров, щоб створити Нову Чуму Відступників. Змішана з отрутами з ведмежих сердець, вона утворює нестійку суміш, яку Головний Аптекар Фаранелл вивчає, щоб нищити і нежить Погибелі, і живих людей.",al={"використання метушливої крові","навіщо збирати павучу кров","що фараннел робить з метушливою кров'ю"}},{q="Де знайти Метушливу Кров?",a="Її збирають із тіл павуків Шурхотливого Плетива — причаєнців, нападників і Кретіса Шедовспіннера, — що ховаються в Шурхотливій Пітьмі та довкола неї: похмурому, затканому павутиною лісі на північному заході Срібнолісся.",al={"де взяти метушливу кров","місце метушливої крові","хто дропає метушливу кров"}},{q="Хто замовляє ці зразки?",a="Аптекар Ренферрел у Гробниці в Срібноліссі доручає зібрати кров і посилає шукачів пригод доставити її просто Головному Аптекареві Фаранеллу в Апотекаріум Андерсіті.",al={"хто хоче метушливу кров","видавець завдання на метушливу кров"}},{q="Навіщо Відступникам отрута місцевих звірів?",a="Королівське Аптекарське Товариство постійно видобуває природні отрути з оскверненої фауни Лордерона. Отрута гігантських павуків Срібнолісся — сирий біологічний збудник, який можна сконцентрувати й обернути на зброю у вигляді штучних чум.",al={"чому павучу отруту","дослідження звірів аптекарями"}}},fp="16,277,18.498.0,22.420.0,34.266.0,32.226.0,27.229.0,49.251.0"}
P.entries["item:sleepers-key"] = {n="Ключ Сплячих",s="Ключ Сплячих — один із трьох зачарованих ключів, створених друїдами нічних ельфів, щоб запечатати своє священне сховище в Лігві Кігтя на Піку Кам'яного Кігтя. Схований у потаємній схованці, замкненій Ключем Воротаря, він уособлює сплячих друїдів дикої природи, що стережуть найглибші таємниці гори.",h="Ключ Сплячих — один із трьох зачарованих ключів, створених друїдами нічних ельфів, щоб запечатати своє...",kw={"ключ сплячих","лігво кігтя","пік кам'яного кігтя","друїди","ключ воротаря","смарагдовий сон"},ang={["class:Druid"]="Ключі й схованки Лігва Кігтя показують багатошаровий захист друїдів нічних ельфів, що спираються на давнє знання Смарагдового Сну й притулків, аби запечатати реліквії сили.",["faction:Horde"]="Здобуття Ключа Сплячих — частина злагодженого набігу на серце Піку Кам'яного Кігтя, щоб зірвати захисні чари нічних ельфів і заволодіти реліквіями з їхнього сховища."},sec={{t="Друїдський запобіжник",b="Вирізьблене у висотах Піку Кам'яного Кігтя, Лігво Кігтя — твердиня й святилище друїдів Калімдору. Розуміючи, що їхні священні реліквії й могутні скарби можуть привернути небажану увагу, хранителі з нічних ельфів вигадали складну систему замків і потаємних схованок, щоб захистити своє сховище. Ключ Сплячих — третина цього захисту. Покладений у відлюдну схованку в глибинах лігва, він дістається лише Ключем Воротаря, захованим біля порога. Разом із Кігтистим Ключем і Ключем від Притулку Ключ Сплячих треба вставити в кам'яні замки Сховища Лігва Кігтя, щоб розвіяти захисні чари й відкрити давні речі, що там зберігаються."}},faq={{q="Для чого потрібен Ключ Сплячих?",a="Ключ Сплячих разом із Ключем від Притулку та Кігтистим Ключем відмикає Скарбницю Лігва Кігтя — зачароване кам'яне сховище глибоко в курганному лігві на Піку Кам'яного Кігтя.",al={"що відчиняє ключ сплячих","призначення ключа сплячих","ключі скарбниці лігва кігтя"}},{q="Як замкнули Ключ Сплячих?",a="Друїди поклали його в Схованку Сплячих у північно-західних тунелях Лігва Кігтя. Щоб відкрити цю схованку, потрібен Ключ Воротаря, який друїди заховали в непоказному ліхтарі біля входу до лігва.",al={"де ключ сплячих","відкрити схованку сплячих","вимога ключа воротаря"}},{q="Навіщо друїди замикали свої реліквії на кілька ключів?",a="Друїди нічних ельфів продумали складний захист, щоб їхні могутні предмети й священні реліквії ніколи не потрапили до рук ворога, якщо на лігво нападуть. Розкидані по прихованих схованках ключі не давали чужинцям легко пограбувати скарбницю.",al={"чому стільки ключів","захист лігва кігтя","головоломка друїдів"}},{q="Чому його називають Ключем Сплячих?",a="Його названо на честь сплячих друїдів, що занурюються в глибокий транс, аби мандрувати Смарагдовим Сном. Як і назви Ключа від Притулку та Кігтистого Ключа, ця назва вшановує священні обов'язки й традиції кіл нічних ельфів, що служать у горах.",al={"хто такі сплячі","чому ключ сплячих так названо"}}},fp="13,300,19.668.0,35.167.0,38.224.0,56.258.0,35.230.0"}
P.entries["item:smoky-iron-ingot"] = {n="Закопчений Залізний Злиток",s="Закопчені залізні злитки — грубо оброблені металеві бруски, які виплавляють кобольди на копальнях Вітрорізу в Горах Кам'яного Кігтя. Оркські зброярі цінують ці злитки як сировину для міцних кольчуг, гідних воїнів Орди.",h="Закопчені залізні злитки — грубо оброблені металеві бруски, які виплавляють кобольди на копальнях Вітрорізу в...",kw={"закопчений залізний злиток","кобольди","круча вітрорізу","гори кам'яного кігтя","тун'ґрім файрґейз","жорстока кольчуга"},ang={["class:Warrior"]="Для воїнів Орди добування цих злитків — випробування витривалості в Горах Кам'яного Кігтя, а самі злитки — важливий складник Жорстокої Кольчуги.",["profession:Blacksmithing"]="Груба якість цих злитків показує, наскільки первісні способи плавлення кобольдів-копачів поступаються вишуканим методам навчених ковалів."},sec={{t="Груба кобольдська металургія",b="У закіптюжених тунелях Кручі Вітрорізу в Горах Кам'яного Кігтя кобольди вгризаються глибоко в кам'янисту землю, видобувають зі схилів неочищену руду й плавлять її на грубих димних багаттях. Закопчені залізні злитки, що з цього виходять, далеко не бездоганні — повні шлаку й деревного вугілля, — але досить щільні, щоб зберігати чималу міцність."},{t="Кування жорстокого обладунку",b="Майже сліпий орк-зброяр Тун'ґрім Файрґейз, що працює в суворому таборі над Пустками, просить саме ці злитки, коли кує обладунки для звитяжних воїнів Орди. Разом з очищеними залізними брусками, порошковим азуритом і мінливим флогістоном закопчений метал стає міцною основою для Жорстоких Кольчуг."}},faq={{q="Звідки беруться Закопчені Залізні Злитки?",a="Закопчені Залізні Злитки носять кобольди, що живуть на розкопках і в тунелях Зрізаного Вітру на сході Гір Кам'яного Кігтя: копачі, каменотеси, шкідники, геоманти та їхні володарі.",al={"де знайти закопчений залізний злиток","місце закопченого залізного злитка","хто дропає закопчені залізні злитки"}},{q="Для чого потрібні Закопчені Залізні Злитки?",a="Їх збирають воїни, що відгукуються на заклик Тун'ґріма Файрґейза — майстра обладунків, який живе на вершинах біля Перехрестя в Пустках. Йому потрібно п'ятнадцять таких злитків, щоб викувати знамениту Жорстоку Кольчугу.",al={"використання закопчених залізних злитків","для чого закопчений злиток","предмет завдання жорстокого обладунку"}},{q="Чому злитки називають закопченими?",a="Кобольди в темних тунелях плавлять метал примітивно, на слабкому вогні. Тож метал зберігає кіптяву, вугільний пил і попіл із їхніх задимлених підземних печей, а не стає чистим і блискучим.",al={"чому закопчений","історія закопченого заліза"}},{q="Чи може будь-який коваль працювати з цими злитками?",a="Ні. Закопчені Залізні Злитки — нерівні, вкриті кіптявою бруски, непридатні для звичайного ковальського ремесла. Лише такі особливі ковалі, як Тун'ґрім Файрґейз, уміють вкувати їх у бойове спорядження на замовлення.",al={"чи кожен коваль може з ним працювати","чи закопчене залізо торгове"}}},fp="16,233,23.354.0,24.338.0,37.202.0,36.215.0,40.215.0,43.196.0"}
P.entries["item:smoldering-embers"] = {n="Тліючі Жаринки",s="Тліючі Жаринки — розпечені, запечені жаром рештки, здобуті з лютих вогняних елементалів Обвугленої Долини. Вартові нічних ельфів збирають ці жарини як речовий доказ того, що вогняні жахіття, які заполонили спустошений ліс, приборкують.",h="Тліючі Жаринки — розпечені, запечені жаром рештки, здобуті з лютих вогняних елементалів Обвугленої Долини.",kw={"тліючі жаринки","обвуглена долина","вогняні елементалі","венчурна компанія","вартові","нічні ельфи"},ang={["class:Druid"]="Друїди бачать у жаринах трагічний доказ природи, яку вивела з рівноваги промислова жадібність: нестримна стихійна лють не дає задушеній попелом землі відродитися.",["race:NightElf"]="Для нічних ельфів палаюча Обвуглена Долина — болісна рана Калімдору. Збирати ці жарини — урочистий обов'язок очистити землю від чужого осквернення й повернути їй спокій під поглядом Елуни."},sec={{t="Рештки Обвугленої Долини",b="Невпинна суцільна вирубка й промислове спустошення Венчурної Компанії пронеслися Обвугленою Долиною, підпалили ліс і вивільнили нищівну лють із глибин землі. Слідом по випаленій улоговині ринули елементалі живого вогню — Палаючі Спустошувачі, Палаючі Руйнівники й блукаючі Свавільні Духи Полум'я. Тліючі Жаринки — вкриті попелом осердя, що лишаються, коли елементаль згасає, — свідчать, що нестримні пожежі долини методично гасять."}},faq={{q="Звідки беруться Тліючі Жаринки?",a="Тліючі Жаринки збирають з вогняних елементалів, що блукають Обвугленою Долиною на півдні Гір Кам'яного Кігтя: палаючих спустошувачів, палаючих руйнівників і свавільних духів полум'я.",al={"де знайти тліючі жаринки","хто дропає тліючі жаринки","джерело тліючих жаринок"}},{q="Навіщо Каелі Шедовспір ці жаринки?",a="Каела Шедовспір хоче мати незаперечний доказ того, що шалених вогняних елементалів в Обвугленій Долині винищують. Вона вірить, що поранена земля ніколи не загоїться під благодаттю Елуни, поки ці люті духи бешкетують на волі.",al={"навіщо збирати тліючі жаринки","жаринки каели шедовспір","мета розлючених духів"}},{q="Чому в Обвугленій Долині з'явилися вогняні елементалі?",a="Венчурна Компанія розчищала прадавній ліс агресивними машинами й безладними підпалами. Безрозсудне хижацтво розхитало рівновагу краю: з надр вирвалися ворожі елементалі вогню й каменю, які зрештою й вигнали гоблінів.",al={"що сталося з обвугленою долиною","чому вогняні елементалі в стоунталоні","вогняні духи венчур"}}},fp="17,253,28.538.0,37.189.0,45.228.0,62.255.0"}
P.entries["item:snellig-s-snuffbox"] = {n="Табакерка Снелліга",s="Ця табакерка — особиста пам'ятка, знайдена в неспокійного нежитя, Першого Помічника Снелліґа, серед уламків Загубленого Флоту. Принесена Першому Помічникові Фіцсіммонсу в Гавань Менетіл, ця дрібничка доводить, що його проклятий колишній товариш по команді нарешті упокоївся.",h="Ця табакерка — особиста пам'ятка, знайдена в неспокійного нежитя, Першого Помічника Снелліґа, серед уламків...",kw={"табакерка снелліга","перший помічник снелліґ","перший помічник фіцсіммонс","третій флот","кул тірас","гавань менетіл"},ang={["faction:Alliance"]="Повертати речі полеглих моряків Кул Тіраса й упокоювати їхні прокляті душі — похмурий обов'язок на службі давньому морському союзникові Альянсу."},sec={{t="Пам'ятка Третього флоту",b="Коли Третій флот Кул Тіраса сів на мілину біля північних берегів Багнокраю, його моряки й офіцери не знайшли мирної смерті. Скуті загадковою темною силою, пов'язаною з прихованим скарбом на борту кораблів, утоплені моряки повстали знову — змученими духами й кістяками-нежиттю. Серед них був Перший Помічник Снелліґ, який досі блукає гнилим трюмом уламка, що лежить найближче до берега. Навіть по смерті він чіплявся за свою табакерку — маленьке буденне нагадування про своє смертне життя на морі. Для єдиного живого вцілілого в тій катастрофі, Першого Помічника Фіцсіммонса, ця дрібничка — відчутний доказ того, що принаймні одного з його загиблих товаришів звільнено від вічних мук."}},faq={{q="Що таке Табакерка Снелліга?",a="Це маленька особиста коробочка, що колись належала Першому Помічникові Снелліґу, офіцерові злощасного Третього флоту Кул Тірасу. Тепер її носить його мертва подоба на уламках кораблів біля північного узбережжя Багнокраю.",al={"що це за річ","табакерка снелліга","табакерка"}},{q="Де знайти Табакерку Снелліга?",a="Табакерку забирають у Першого Помічника Снелліґа, що блукає трюмом південного затонулого корабля, найближчого до берега, у Загубленому Флоті на північному сході Багнокраю.",al={"хто дропає табакерку снелліга","знайти снелліга","місце першого помічника снелліга"}},{q="Кому потрібна ця табакерка?",a="Перший Помічник Фіцсіммонс, єдиний живий з уцілілих Третього флоту, просить шукачів пригод принести йому табакерку до Гавані Менетіл як доказ того, що Снелліґ нарешті спочив.",al={"кому віддати табакерку","хто бере табакерку","завдання фіцсіммонса"}},{q="Чому Перший Помічник Снелліґ проклятий?",a="За словами Фіцсіммонса, темний і жахливий скарб, схований на одному з кораблів Третього флоту, прирік команди на загибель: коли кораблі розбилися, душі моряків опинилися в пастці гнилих дощок, і спокою їм немає.",al={"чому снелліґ мертвий","прокляття загубленого флоту","прокляття третього флоту"}}},fp="18,283,29.710.0,27.215.0,35.157.0,24.174.0,33.204.0"}
P.entries["item:snufflenose-command-stick"] = {n="Командний Жезл Нюхоноса",s="Командний Жезл Нюхоноса — дресирувальна паличка, яку видає гоблін-підприємець Мебок Міззірікс у Раджеті. Нею керують навченими ховрахами-нюхоносами, щоб ті знаходили й викопували цінні синьолисті бульби, закопані глибоко в Рейзорфен Краулі.",h="Командний Жезл Нюхоноса — дресирувальна паличка, яку видає гоблін-підприємець Мебок Міззірікс у Раджеті.",kw={"командний жезл нюхоноса","мебок міззірікс","ховрахи-нюхоноси","синьолиста бульба","рейзорфен краул","раджет"},ang={["profession:Cooking"]="Синьолисті бульби вважають вишуканим делікатесом по всьому світу, але щоб їх добути, потрібні навчена тварина й паличка дресирувальника, а не звичайне кухонне начиння."},sec={{t="Паличка для гризунів",b="Синьолисті бульби — жаданий делікатес по всьому Азероту, але знайти їх без особливої допомоги майже неможливо. Закопані в колючих підземних глибинах Рейзорфен Краулу, коренеплоди цілком сховані від очей. Щоб заробити на цьому прибутковому ринку й не лізти самому в лігва шипогривів, раджетський торговець Мебок Міззірікс привчив чутконосих ховрахів-нюхоносів викопувати бульби. Командний Жезл Нюхоноса — інструмент, яким шукачі пригод керують цими навченими звірятками, підганяючи їх винюхувати й відкопувати коренеплоди на відстані до п'ятдесяти кроків."}},faq={{q="Для чого потрібен Командний Жезл Нюхоноса?",a="Жезлом віддають накази навченому ховрахові-нюхоносу, щоб той шукав сховані бульби синьолиста в колючих тунелях Рейзорфен Краулу. Коли жезл спрямовують на викликаного ховраха, звірятко йде за запахом і викопує коріння.",al={"як використати командний жезл","що робить командний жезл","призначення командного жезла"}},{q="Де взяти Командний Жезл Нюхоноса?",a="Його можна підібрати в Раджеті, що в Пустках, просто біля майстерні Мебока Міззірікса, поруч зі скринькою з навченим ховрахом і посібником.",al={"де взяти командний жезл","місце командного жезла","хто дає командний жезл"}},{q="Навіщо Мебокові Міззіріксу бульби синьолиста?",a="Бульби синьолиста — рідкісний делікатес, який з великим зиском продають заможним цінителям кухні по всьому світу. Ростуть вони лише глибоко під Пустками, на землях шипогривів, тож Мебок наймає шукачів пригод, щоб їх добути.",al={"навіщо бульби","призначення бульби синьолиста","навіщо мебоку бульби"}},{q="Чи можна лишити жезл собі, коли знайдете бульби?",a="Ні. Зібравши потрібні бульби, ви маєте повернути Мебокові в Раджет і командний жезл, і переносну скриньку разом з урожаєм.",al={"чи можна залишити жезл","повернути командний жезл"}}},fp="25,241,17.569.0,47.250.0,50.159.0,45.231.0,54.165.0"}
P.entries["item:snufflenose-owner-s-manual"] = {n="Посібник Власника Нюхоноса",s="Посібник Власника Нюхоноса — книжечка з інструкціями від Марвіґа Растболта з компанії «Снафф Інк.», що лежить біля гобліна-підприємця Мебока Міззірікса в Раджеті. У ній розповідається, як випустити навченого Ховраха-нюхоноса й керувати ним, щоб знайти рідкісні Синьолисті бульби, закопані в Рейзорфен Краулі.",h="Посібник Власника Нюхоноса — книжечка з інструкціями від Марвіґа Растболта з компанії «Снафф Інк.», що лежить...",kw={"посібник власника нюхоноса","ховрах-нюхоніс","мебок міззірікс","марвіґ растболт","синьолиста бульба","рейзорфен краул"},ang={["profession:Cooking"]="Посібник описує, як добувати Синьолисті бульби — підземний коренеплід, який гурмани й торговці по всьому Азероту вважають рідкісним делікатесом."},sec={{t="Гоблінська інструкція з користування",b="Цей короткий посібник, написаний Марвіґом Растболтом, власником «Снафф Інк.», пояснює, як працювати з навченими ховрахами-нюхоносами компанії. Ці звірятка мають такий гострий нюх, що чують підземні Синьолисті бульби за п'ятдесят кроків. Посібник радить шукачам випускати ховраха з провітрюваного ящика й спрямовувати його нюх командним жезлом, ведучи створіння крізь ворожі колючки й тунелі шипогривів Рейзорфен Краулу до цінних делікатесів."}},faq={{q="Для чого потрібен Посібник Власника Нюхоноса?",a="Це інструкція з поводження з навченими ховрахами-нюхоносами Мебока Міззірікса. Шукачі пригод читають її, щоб зрозуміти, як випустити звірятко зі скриньки й скеровувати його командним жезлом до закопаних бульб синьолиста в Рейзорфен Краулі.",al={"що дає посібник","навіщо читати посібник","призначення посібника"}},{q="Де знайти посібник?",a="Посібник лежить у Раджеті, що в Пустках, просто біля Мебока Міззірікса, поруч зі спеціальними скриньками й командними жезлами для збирання бульб.",al={"місце посібника","де книга","як отримати посібник"}},{q="Чому для пошуку бульб синьолиста потрібні ховрахи-нюхоноси?",a="Бульби синьолиста ховаються глибоко в землі Рейзорфен Краулу, і гуманоїдам їх майже не помітити. Навчені ховрахи мають такий гострий нюх, що чують закопану бульбу за п'ятдесят кроків.",al={"чому ховрахи","чи знайти бульби без ховрахів"}},{q="Хто написав посібник?",a="Його підписав Марвіґ Растболт, власник фірми «Нюх Інк.», який написав посібник, щоб навчити нових власників годувати, вигулювати й скеровувати ховрахів запатентованим командним жезлом.",al={"автор посібника","хто його зробив"}}},fp="26,280,26.513.0,54.249.0,28.152.0,59.233.0,21.163.0"}
P.entries["item:sodium-nitrate"] = {n="Нітрат Натрію",s="Нітрат натрію — нестійкий хімічний реагент, який носять при собі дворфи-копачі й гарнізон Бель Модану на півдні Пусток. Експедиція з Айронфорджа привезла його, щоб підривати прадавнє каміння, а вигнаний таурен Ґанн Стоунспайр прагне його відібрати, щоб зібрати вибуховий заряд проти загарбників.",h="Нітрат натрію — нестійкий хімічний реагент, який носять при собі дворфи-копачі й гарнізон Бель Модану на...",kw={"нітрат натрію","бель модан","ґанн стоунспайр","вибухівка","дворфи","айронфордж"},ang={["profession:Engineering"]="Інженери одразу впізнають у трійці «нітрат натрію, нітрогліцерин і деревна маса» хрестоматійний рецепт стабілізованого динаміту — залізна логіка, що стоїть за саморобними зарядами Ґанна.",["race:Tauren"]="Для тауренів удаватися до дворфійської хімії — гіркий відступ від традицій, але Ґанн Стоунспайр вважає, що відчайдушні заходи виправдані, коли треба помститися за знищення родових земель."},sec={{t="Промислові підриви",b="Експедиція з Бел'дуна вдерлася в родові землі племені Стоунспайр із важкими землерийними машинами й вибуховими реагентами. Щоб розколоти вперті кам'яні пласти південних Пусток, дворфи покладалися на нестійкі хімічні сполуки. Нітрат натрію — важливий стабілізатор і окисник у потужній вибухівці; його постійно носять при собі стрільці, солдати й офіцери Бел'дуна на розкопках і в сусідній фортеці."},{t="Відплата тією ж монетою",b="Після того як землі його племені сплюндрували, Ґанн Стоунспайр уважно стежив за загарбниками й роздобув їхні інженерні креслення. Розуміючи, що звичайним нападом добре захищену фортецю не взяти, Ґанн задумав обернути промислову вибухівку дворфів проти них самих. Змішуючи здобутий нітрат натрію з нітрогліцерином і деревною масою, вигнанець-таурен виготовляє саморобні заряди, що мають струснути підвалини Бель Модану."}},faq={{q="Для чого в Пустках потрібен Нітрат Натрію?",a="Дворфи з Айронфорджа використовують його як хімічний складник вибухівки, щоб підривати скелі на своїх розкопках. Ґанн Стоунспайр хоче змішати його з нітрогліцерином і деревною масою, щоб зробити потужні підривні заряди й завдати удару у відповідь по фортеці Бель Модан.",al={"призначення нітрату натрію","що робить нітрат натрію"}},{q="Звідки береться Нітрат Натрію?",a="Його тримає дворфське військо, що стоїть у Бель Модані на півдні Пусток. Солдати, стрільці, офіцери та їхні командири, як-от Лорд Сайрік Блекфордж, мають запаси цього реагенту при собі.",al={"хто дропає нітрат натрію","де взяти нітрат натрію"}},{q="Навіщо Ґаннові Стоунспайру ця речовина?",a="Через дворфські розкопки Ґанн утратив рідне село предків. Не маючи важких облогових машин, він вивчив дворфські креслення, щоб відтворити їхні гірничі заряди й зруйнувати укріплення дворфів їхньою ж вибухівкою.",al={"навіщо ґанну нітрат натрію","вибухівка ґанна стоунспайра"}},{q="Чи небезпечний Нітрат Натрію сам по собі?",a="Сам по собі нітрат натрію — окисник і хімічна сіль, а не вибухівка миттєвої дії. Небезпечним і нестійким він стає, коли його правильно змішати з пальним і чутливими до удару речовинами, як-от нітрогліцерин.",al={"чи нітрат натрію вибуховий"}}},fp="14,325,21.442.0,25.465.1,47.266.0,36.206.0,44.225.0,39.216.0"}
P.entries["item:solomon-s-plea-to-darkshire"] = {n="Прохання Соломона до Дарксаєра",s="Прохання Соломона до Даркширу — термінове послання, яке Магістрат Соломон із Лейкширу адресував Лордові Елло Ебонлоку. Перед лицем дедалі більшої загрози від орків Блекрок і гнолів лист благає провід Даркширу надіслати добірне ополчення, Нічну Варту, щоб зміцнити виснажену оборону Лейкширу.",h="Прохання Соломона до Даркширу — термінове послання, яке Магістрат Соломон із Лейкширу адресував Лордові Елло...",kw={"прохання соломона","магістрат соломон","елло ебонлок","нічна варта","даркшир","лейкшир"},ang={["faction:Alliance"]="Послання показує, як розпадаються південні землі Великого Альянсу: віддалені поселення благають одне одного про порятунок, а Стормвінд лишається байдужим.",["race:Human"]="Для подорожніх-людей ця депеша підкреслює спільну небезпеку, що нависла і над прикордонням Редріджу, і над темними лісами Сутінколісся."},sec={{t="Відчайдушний заклик про допомогу",b="Лейкшир ось-ось захлесне навала орків Блекрок, гнолів і мурлоків, а офіційного підкріплення зі Стормвінда майже немає. У відчаї Магістрат Соломон склав це офіційне прохання до мера Даркширу Елло Ебонлока, благаючи відрядити вартових Нічної Варти на північ, до Редріджу. Документ свідчить, наскільки розладналася центральна військова підтримка на півдні Азероту: окремі людські поселення змушені шукати порятунку одне в одного."},{t="Скрута Даркширу",b="Хоч прохання Соломона й нагальне, воно показує, як мало Лейкшир знає про справжні жахіття, що охопили його сусідів. Саме Сутінколісся обложене нежиттю, ненажерливими звірами й усепроникною темрявою, і Нічна Варта ледве тримає навіть межі власного селища. Тож гінці, що доставляють прохання, знаходять не запас свіжих бійців, а таке саме виснажене місто, яке не може виділити захисників для Редріджу."}},faq={{q="Що таке Прохання Соломона до Даркширу?",a="Це офіційний лист Магістрата Соломона з Лейкширу до Лорда Елло Ебонлока, мера Даркширу. Соломон терміново просить Даркшир надіслати на допомогу своє ополчення, Нічну Варту, щоб захистити Редрідж від орків Блекрок і гнолів.",al={"лист соломона до даркширу","що таке прохання соломона","лист лейкшира до сутінколісся"}},{q="Чому Лейкшир просить військової допомоги в Даркширу, а не в Стормвінда?",a="Центральний уряд Стормвінда через політичну неповороткість і внутрішні чвари так і не спромігся надіслати досить гарнізонних військ на околиці королівства. Залишений сам-на-сам із дедалі запеклішими нападами, Магістрат Соломон звернувся до сусідніх людських містечок, сподіваючись знайти союзні сили.",al={"чому просити даркшир","чому не стормвінд","чому соломону потрібна нічна варта"}},{q="Хто такий Лорд Елло Ебонлок?",a="Лорд Елло Ебонлок — мер і голова громади Даркширу в Сутінколіссі. Він керує містечком і координує Нічну Варту — ополчення, що стримує жахіття, які чатують у лісах.",al={"хто такий ебонлок","мер даркшира","лорд елло"}},{q="Чи справді Даркшир може відпустити Нічну Варту на допомогу Лейкширу?",a="Ні. Сутінколісся потерпає від власного жахіття: його оточують нежить, здичавілі воргени й темна магія. Нічній Варті ледве вистачає людей, щоб утримати околиці Даркширу, і вона не може відпустити до Редріджу жодного бійця.",al={"чи допоможе даркшир","чи прийде нічна варта","чи надіслав ебонлок вартових"}}},fp="27,313,24.521.0,23.468.1,36.274.0,73.318.0,27.226.0,63.228.1"}
P.entries["item:soran-ruk-fragment"] = {n="Уламок Соран'рука",s="Уламок Соран'рука — відколок демонічної сфери-в'язниці, колись пов'язаної з духом зганьбленого слуги Палаючого Легіону. Хоч сферу розколото, а уламки розпорошено між сектантами глибоко під Ашенвалем, кожен із них досі випромінює залишки енергії Скверни.",h="Уламок Соран'рука — відколок демонічної сфери-в'язниці, колись пов'язаної з духом зганьбленого слуги...",kw={"уламок соран'рука","сфера соран'рука","доан кархан","молот присмерку","чорноглибинні печери","чорнокнижник"},ang={["class:Warlock"]="Демонічні посудини-в'язниці на кшталт Сфери Соран'рука — цінні провідники для чорнокнижників, які прагнуть приборкувати й спрямовувати чисту енергію Скверни, не підкоряючи демона напряму."},sec={{t="Розбита в'язниця",b="Коли демони Палаючого Легіону втрачають прихильність своїх володарів, їхні духи часом засуджують до ув'язнення в особливих сферах, які роздають чаклунам Скверни як провідники чистої сили. Така доля спіткала й сферу Соран'рука, але колись її розкололи навпіл. Одну половину розбили на дрібніші уламки, і вони потрапили до рук сектантів Молота Присмерку, що ховаються в затоплених руїнах Чорноглибинних Печер і черпають із залишків демонічної суті силу для власних темних справ."},{t="Відновлення в Пустках",b="Навіть розколотий, кожен шматок зберігає дещицю життєвої сили ув'язненої сутності. На півдні Пусток відлюдькуватий учений Доан Кархан усе життя вивчає такі демонічні посудини — він і сам має подібну, Сферу Зарґейна. Зібравши три дрібні уламки разом із більшим шматком, що зберігається в Срібноліссі, честолюбний чорнокнижник може повернути реліквії цілісність і знову перетворити її на знаряддя сили."}},faq={{q="Що таке Соран'рук?",a="Соран'рук був демоном Палаючого Легіону, що впав у немилість у демонічних володарів. У покарання його дух вирвали й ув'язнили в кришталевій сфері, щоб він слугував смертним чорнокнижникам і магам джерелом енергії.",al={"хто такий соран'рук","лор соран'рука","чи соран'рук демон"}},{q="Де знайти ці уламки?",a="Менші уламки носять послушники Молота Присмерку в печерних залах Чорноглибинних Печер на Зорамському Узмор'ї.",al={"де взяти уламок соран'рука","хто дропає уламки соран'рука","місце уламка соран'рука"}},{q="Звідки в Молота Присмерку ці уламки?",a="Навіть розбиті, уламки зберігають магічну сутність ув'язненого демона. Культисти Молота Присмерку збирають такі осквернені артефакти, щоб живити ними свої темні ритуали й спрямовувати заборонену магію.",al={"чому культисти його мають","молот присмерку соран'рук"}},{q="Хто може відновити Сферу Соран'рука?",a="Доан Кархан, відлюдник, що живе на півдні Пусток біля кордону з Тисячею Голок, знається на вивченні й перековуванні демонічних сфер Легіону.",al={"хто полагодить сферу","куди здати уламок соран'рука","сфера доана карґана"}}},fp="18,249,18.527.0,29.424.1,18.226.0,32.123.0,49.203.0,37.168.0"}
P.entries["item:southsea-treasure"] = {n="Скарб Південних Морів",s="Скарб Південних Морів — цінна схованка глибоко в трюмі корабля Флібустьєрів Південних морів «Лезо Припливу». Його шукає Вреникс Жалюгідний у Раджеті, і викрасти його — справжня перевірка вміння зламувати замки й непомітно проникати для молодих злодіїв.",h="Скарб Південних Морів — цінна схованка глибоко в трюмі корабля Флібустьєрів Південних морів «Лезо Припливу».",kw={"скарб південних морів","флібустьєри південних морів","вреникс жалюгідний","поллі","раджет","розбійник"},ang={["class:Rogue"]="Повернення Скарбу Південних Морів — обряд посвяти для молодих розбійників: це і справжня практика зламування замків, і знайомство з тіньовим угрупованням, відомим як Розтрощена Рука.",["faction:Horde"]="Флібустьєри Південних морів постійно заважають торгівлі довкола Пусток і порту Раджет, тож будь-яка крадіжка з їхньої головної схованки місцевій владі лише на руку."},sec={{t="Смертельне пограбування",b="Піратський корабель «Лезо Припливу», що стоїть на якорі біля Узбережжя Крамарів на південь від Раджета, править Флібустьєрам Південних морів за передову базу й вишкільний табір. Глибоко в його найнижчому трюмі заховано жадану купу здобичі, відому як Скарб Південних Морів. Вреникс Жалюгідний, гоблінський пройдисвіт із Раджета, вважає його найвищим випробуванням для охочих стати кишеньковими злодіями. За словами Вреникса, останні п'ятеро посланців, які намагалися поцупити скриню, повернулися по частинах — через пильних піратів на борту й напрочуд лютого охоронця трюму."},{t="Скарбничка Поллі",b="Злодіїв, яким вдасться оминути піратів-наставників і зламати замок потрібної скрині, чекає лиха несподіванка. Справжній Скарб Південних Морів не лежить у скрині просто так: його стереже Поллі — неприродно люта папуга. Подолати злісного птаха — часто за допомогою гоблінської техніки на кшталт Врениксового пристрою Е.К.А.К. — єдиний спосіб вирвати скарб і принести його до Раджета цілим."}},faq={{q="Де знаходиться Скарб Південних Морів?",a="Скарб зберігається на «Бритві Припливу» — кораблі Флібустьєрів Південних морів, що стоїть на якорі біля узбережжя на південь від Раджета в Пустках. Він лежить у найнижчому трюмі, під приміщеннями, де тренуються пірати.",al={"де скарб","місце приливного бритви","як знайти скарб південних морів"}},{q="Кому потрібен Скарб Південних Морів?",a="Вреникс Жалюгідний, безсоромний гоблін із Раджета, наймає таємних агентів, щоб ті проникли на корабель і викрали для нього здобич.",al={"хто дає завдання","хто такий реникс","кому потрібен скарб"}},{q="Чому скриня порожня, коли її відімкнути?",a="Щойно зламати замок скрині, з'являється Поллі — неймовірно лютий папуга, що стереже трюм. Скарб Південних Морів дістається лише тому, хто здолає Поллі.",al={"звідки поллі","чому з'явилась поллі","чому в скрині немає скарбу"}},{q="Що таке E.C.A.C. і навіщо він потрібен?",a="E.C.A.C. — експериментальний гоблінський пристрій, який видає Вреникс Жалюгідний. Він призначений послаблювати надзвичайно лютих летючих супротивників, а саме смертоносного папугу-вартового Поллі, що чатує в трюмі піратського корабля.",al={"що таке екак","як перемогти поллі","ворожий папуга"}},{q="Навіщо Флібустьєрам Південних морів цей корабель?",a="«Бритва Припливу» править Флібустьєрам Південних морів за базу й злодійське кубло: на другій палубі стоять тренувальні скриньки, на яких команда навчає своїх кишенькових злодіїв.",al={"що таке приливна бритва","лігво піратів пустища","трюм корабля південних морів"}}},fp="17,242,14.555.0,16.443.1,39.196.0,32.148.0,35.186.1,41.227.0,50.176.0"}
P.entries["item:spectral-comb"] = {n="Примарний Гребінь",s="Примарний Гребінь — ефірне знаряддя для зачісування, яким можна торкнутися неспокійних мерців Сутінколісся. Створений так, щоб проходити крізь безтілесні форми, він потрапляє до скорботного духа Сліпої Мері, щоб зібрати пасма примарного волосся.",h="Примарний Гребінь — ефірне знаряддя для зачісування, яким можна торкнутися неспокійних мерців Сутінколісся.",kw={"примарний гребінь","сліпа мері","нитка з примарного волосся","даркшир","привид","кравецтво"},ang={["faction:Alliance"]="Похід із гребенем на південь від Даркшира — суворе нагадування про трагічну долю колишніх хуторян Сутінколісся.",["profession:Tailoring"]="Примарний Гребінь доводить, що кравецтво в темних краях вимагає незвичних способів добування сировини: ефірні волокна беруть у привидів, які віддають їх самі, а не стрижуть, як заведено."},sec={{t="Знаряддя для неспокійних мерців",b="Звичайні речі не можуть торкнутися духа чи розчесати йому коси, тож смертним майстрам майже неможливо зібрати ефірні матеріали. Примарний Гребінь створено саме для того, щоб узаємодіяти з примарними тілами й ковзати крізь безтілесні пасма. Його несуть на південь від Даркшира, до зруйнованого хутора, де самотньо голосить заплаканий привид Сліпої Мері. Знаходячи розраду у звичному ритуалі розчісування свого знівеченого волосся, Мері охоче бере гребінь — і лишає по собі примарні волокна, потрібні, щоб виткати Нитку з Примарного Волосся."}},faq={{q="Для чого потрібен Примарний Гребінь?",a="Гребінь віддають Сліпій Мері — заплаканій примарі, що живе на південь від Даркширу. Коли вона розчісує ним волосся, на гребені залишаються ефірні пасма, з яких згодом можна спрясти надприродну нитку.",al={"призначення примарного гребеня","навіщо мені примарний гребінь","що робить гребінь"}},{q="Хто така Сліпа Мері?",a="Сліпа Мері — змучений дух, що блукає покинутим будинком на пагорбах на південь від Даркширу. Збожеволівши від горя, вона вирвала собі очі й досі боїться, що й після смерті здається іншим потворною.",al={"лор сліпої мері","хто привид із гребенем","сліпа мері"}},{q="Чому не можна скористатися звичайним гребенем?",a="Звичайні речі без особливої магії чи чарів не можуть торкнутися духів. Примарний Гребінь створено саме для того, щоб торкатися безтілесного волосся привида.",al={"чому примарний гребінь","звичайний гребінь і привид"}}},fp="13,226,24.517.0,35.189.0,18.203.0,37.187.0"}
P.entries["item:spells-of-shadow"] = {n="Закляття Тіні",s="«Закляття Тіні» — темний гримуар, який носять культисти Пекучого Клинка, що ховаються в Проваллі Лютого Вогню під Оргріммаром. Сповнений магії скверни, дарованої Палаючим Легіоном, він — ціль, яку хоче здобути верхівка Відступників в Андерсіті.",h="«Закляття Тіні» — темний гримуар, який носять культисти Пекучого Клинка, що ховаються в Проваллі Лютого Вогню...",kw={"закляття тіні","пекучий клинок","провалля лютого вогню","андерсіті","варіматрас","гримуар","скверна"},ang={["class:Warlock"]="Фоліант — свідчення прямого демонічного покровительства Легіону, яке показує, як свавільні культи на кшталт Пекучого Клинка орудують мистецтвами тіні й Нижнього Світу.",["race:Undead"]="Здобувши гримуар, ви прямо служите Леді Сильвані: небезпечні демонічні знання з-під Оргріммара зміцнять Андерсіті проти Погибелі."},sec={{t="Фоліанти Пекучого Клинка",b="Глибоко в розпечених печерах Провалля Лютого Вогню члени Пекучого Клинка — культу-відгалуження, пов'язаного з Радою Тіней, — правлять темні обряди, даровані демонічними володарями з Палаючого Легіону. Серед їхніх найпильніше стережених скарбів — «Закляття Тіні», книга підступного чаклунства тіні й скверни. Культисти й чорнокнижники секти тримають її під рукою, плетучи змови просто під ногами Орди в Дуротарі."},{t="Задуми Темної Леді",b="Звістка про демонічні дари Пекучого Клинка дійшла до королівських покоїв Андерсіті. Леді Сильвана Віндраннер і її поплічник-жахолорд Варіматрас вирішили, що такі могутні реліквії марнуються в руках недалекоглядних культистів. Варіматрас доручає шукачам пригод з Орди спуститися в провалля й здобути «Закляття Тіні» разом із супутнім фоліантом — «Заклинаннями з Нижнього Світу», щоб спрямувати їхню силу на справу Відступників проти Погибелі й Короля-Ліча."}},faq={{q="Що таке Закляття Тіні?",a="Це демонічна книга заклять, яку мають культисти Пекучого Клинка в Проваллі Лютого Вогню. У ній — дари тіньової магії від Палаючого Легіону.",al={"книга закляття тіні","що таке закляття тіні","книга закляттів тіні"}},{q="Кому потрібна ця книга?",a="Варіматрас, жахолорд і радник Леді Сильвани Віндраннер, шукає фоліант на прохання Темної Леді. Він перебуває в Королівському Кварталі Андерсіті.",al={"кому потрібні закляття тіні","хто бере закляття тіні","видавець завдання на закляття тіні"}},{q="Де знайти книгу?",a="Її носять культисти й чорнокнижники Пекучого Клинка в Проваллі Лютого Вогню — мережі вогняних печер просто під Оргріммаром.",al={"місце закляття тіні","де взяти закляття тіні","як отримати закляття тіні"}},{q="Навіщо Відступникам цей гримуар?",a="Леді Сильвана вважає, що темні дари Легіону Відступники використають краще, ніж якісь нікчемні культисти: така магія зміцнить її війну проти Погибелі й Короля-Ліча.",al={"навіщо сильванас книга","навіщо варіматрасу закляття тіні"}}},fp="16,244,26.428.0,24.478.0,29.149.0,20.156.0,28.146.0,39.195.0"}
P.entries["item:spotted-sunfish"] = {n="Плямиста Риба-Сонце",s="Плямиста Риба-Сонце — прісноводна риба, що водиться в Озері Незрушному в Горах Редріджу. Місцеві цінують її за смак, і вона завжди в ходу на пристанях Лейкширу, хоча мурлоків дедалі більшає, тож рибалити стає небезпечно.",h="Плямиста Риба-Сонце — прісноводна риба, що водиться в Озері Незрушному в Горах Редріджу.",kw={"плямиста риба-сонце","риба","доглядач пристані барен","озеро незрушне","мурлоки","лейкшир"},ang={["profession:Cooking"]="Місцева прісноводна риба на кшталт плямистої риби-сонця — основа кухні Озера Незрушного, тож вона незмінно буває на столах таверн Редріджу."},sec={{t="Цінний улов",b="Озеро Незрушне здавна славиться плямистою рибою-сонцем, за яку і місцеві купці, і приїжджі дають добру ціну. Доглядач Пристані Барен постійно торгує нею на причалах Лейкширу, забезпечуючи їжею й торгівлею містечко в скруті. Проте агресивні племена мурлоків, що нишпорять на мілинах, зірвали звичну рибалку й часто запасають власний улов, який шукачам пригод доводиться відбивати силою."}},faq={{q="Де водиться Плямиста Риба-Сонце?",a="Вона водиться у водах Озера Незрушне в Горах Редріджу. Рибалки ловлять її просто в озері, але й місцеві мурлоки постійно її виловлюють, тож мурлочі табори вздовж берега — чудове місце, щоб її роздобути.",al={"де взяти плямисту рибу-сонце","місце плямистої риби-сонце","риба озера незрушного"}},{q="Хто купує Плямисту Рибу-Сонце?",a="Доглядач Пристані Барен на причалах Лейкширу скуповує Плямисту Рибу-Сонце партіями. Він торгує цим делікатесом і платить кожному, хто принесе йому свіжий улов.",al={"хто хоче плямисту рибу-сонце","риба портового майстра барена","продаж риби"}},{q="Навіщо мурлокам ця риба?",a="Мурлоки, що живуть уздовж Озера Незрушне, полюють і промишляють місцеву живність, щоб прогодувати свої дедалі більші племена. Вони виловлюють рибу-сонце з озера так само, як люди-рибалки, і тримають її у своїх таборах на мілководді.",al={"мурлоки плямиста риба-сонце","чому мурлоки дропають рибу"}},{q="Чи можна роздобути її без риболовлі?",a="Так. Доглядач Пристані Барен зауважує, що мандрівники без вудки можуть просто перебити ворожих мурлоків на березі Озера Незрушне й забрати зібрану ними рибу.",al={"здобути рибу-сонце без вудки","риба-сонце без вудки"}}},fp="15,243,14.430.0,32.242.0,34.172.0,36.212.0,36.184.0"}
P.entries["item:stalker-claws"] = {n="Кігті Переслідувача",s="Кігті Переслідувача — пазурі, здобуті зі степових переслідувачів, що блукають хвилястими рівнинами Малгору. Шамани тауренів використовують їх як важливі складники, вирізьблюючи традиційні очисні тотеми для очищення осквернених водяних криниць.",h="Кігті Переслідувача — пазурі, здобуті зі степових переслідувачів, що блукають хвилястими рівнинами Малгору.",kw={"кігті переслідувача","степовий переслідувач","тотем","малл тандергорн","криниця тандергорнів","гобліни","малгор"},ang={["class:Shaman"]="Кігті диких рівнинних хижаків уособлюють люту чистоту природи — неодмінний матеріал для зв'язування й наснаження очисних тотемів.",["race:Tauren"]="Збирання цих кігтів служить священному обов'язку вашого племені — відновити святі води, отруєні безоглядними промисловими зайдами."},sec={{t="Хижаки рівнин",b="Трав'янисті степи Малгору — домівка смертоносних природних хижаків, серед них і потайних степових переслідувачів. Ці звірі живуть первісним інстинктом і смертельною точністю — неодмінна рівновага в задумі Матері-Землі. Малл Тандергорн, прагнучи зцілити вражену землю, потребує цих кігтів не зі злості на звірів, а тому, що чиста природна лють, з якою вони полюють, має духовний відгук, здатний протидіяти штучній скверні."},{t="Очищення криниць",b="Коли підприємства гоблінів почали бурити й копати по всьому центральному Калімдору, хімічні отрути просочилися глибоко в підземні води, що живлять прабатьківські криниці тауренів. Особливо постраждала Водяна Криниця Тандергорнів, уражена мерзенною скверною. Зв'язавши Кігті Переслідувача й Кігті Пуми в Очисний Тотем Громорога, племінні шамани створюють духовний провідник, здатний вичистити бруд і неприродний мул із природних джерел землі."}},faq={{q="Звідки беруться Кігті Переслідувача?",a="Їх здобувають, полюючи на степових переслідувачів на трав'янистих пагорбах Малгору, здебільшого на схід і на захід від Села Бладгуф.",al={"де знайти кігті переслідувача","хто дропає кігті переслідувача","джерело кігтів переслідувача"}},{q="Навіщо Маллу Тандергорну ці кігті?",a="З цих кігтів і кігтів рівнинних пум Малл Тандергорн виготовляє Очисний Тотем Громорога. Природна чистота й сила корінних мисливців рівнин потрібні, щоб очистити отруєні криниці.",al={"навіщо збирати кігті переслідувача","призначення мулла тандергорна","використання кігтів переслідувача"}},{q="Чому Водяна Криниця Тандергорнів забруднена?",a="Криницю отруює неприродне промислове забруднення від гоблінських розробок у Малгорі, які порушують природну рівновагу й отруюють місцеві ґрунтові води.",al={"хто отруїв криницю","чому колодязь тандергорнів хворий","забруднення тандергорнів"}},{q="Що стається, коли кігті зібрано?",a="Зібравши кігті, Малл вирізає з них очисний тотем, який треба віднести просто до Водяної Криниці Тандергорнів, щоб вигнати звідти рештки скверни.",al={"що далі","наступний крок після кігтів","обряд очищувального тотема"}}},fp="13,218,23.477.0,19.437.0,33.127.0,43.214.0,42.165.0,42.162.0"}
P.entries["item:steelgrill-s-tools"] = {n="Інструменти Стілґрила",s="Інструменти Стілґрила — спеціалізований набір механічного знаряддя, замовлений для Белдіна Стілґрілла, головного техніка Складу Стілґрила. Белдін, відомий тим, що жене облогові машини — й власне обладнання — на межу можливостей, часто ламає інструменти й залежить від постачання з сусіднього Хараноса, щоб його майстерня працювала.",h="Інструменти Стілґрила — спеціалізований набір механічного знаряддя, замовлений для Белдіна Стілґрілла...",kw={"інструменти стілґрила","белдін стілґрілл","склад стілґрила","облогові машини","харанос","інженерія","пілот стоунґір"},ang={["profession:Engineering"]="Кожен інженер поспівчуває скруті Белдіна: ремонт важких облогових машин із великими зусиллями регулярно забирає дугові ключі й тонкі гайкові ключі.",["race:Dwarf"]="Утримувати броньовані облогові машини Альянсу — справа дворфійської гордості, і постачання Белдіна гарантує, що броньований авангард Айронфорджа лишається боєздатним."},sec={{t="Майстер із важкою рукою",b="Белдіна Стілґрілла широко вважають одним із найкращих техніків облогових машин у Дун Мороґу, але його напористий стиль ремонту сумнозвісний серед місцевих торговців. Невтомно працюючи над броньованими танками й механічними пристроями, Белдін нищить тонке обладнання майже так само швидко, як його встигають викувати. Ламаючи дугові ключі й зриваючи зубчасті тріскачки, механік без упину робить нові замовлення в Хараносі, щоб його ремонтні верстаки не порожніли."},{t="Щоб машини їхали",b="Ця партія інструментів життєво важлива, щоб бойові машини Айронфорджа лишалися на ходу. На своєму складі на північний схід від Хараноса Белдін обслуговує бойові машини для досвідчених водіїв, як-от Пілот Стоунґір. Без свіжого запасу гайкових ключів і тріскачок важливі облогові машини стояли б напівзібраними в снігу, і зупинилися б і склад, і місцева оборона."}},faq={{q="Для чого потрібні Інструменти Стілґрила?",a="Це нові механічні інструменти на заміну старим, які доставляють Белдінові Стілґріллу на Склад Стілґрила. Вони потрібні Белдінові, щоб ремонтувати важкі дворфські машини, зокрема пошкоджену облогову машину Пілота Стоунґіра.",al={"що це за інструменти","призначення інструментів стілґрила"}},{q="Чому Белдін Стілґрілл так швидко нищить інструменти?",a="Белдін — надзвичайно грубий механік, що працює своїм знаряддям до знемоги. За словами постачальників із Хараноса, він ламає дугові гайкові ключі й ікласті храповики мало не швидше, ніж місцеві майстри встигають їх робити.",al={"чому зламані інструменти","навіщо белдіну інструменти"}},{q="Звідки цей ящик з інструментами?",a="Партію збирають і комплектують у сусідньому селищі Харанос, а тоді передають мандрівникам, що прямують на північний схід до Складу Стілґрила.",al={"де взяти інструменти","звідки ящик з інструментами"}},{q="Хто такий Белдін Стілґрілл?",a="Белдін — дворф-майстер механіки, власник і керівник Складу Стілґрила на північний схід від Хараноса. Його вважають найкращим знавцем облогових машин у краї.",al={"хто такий белдін","белдін стілґрілл лор"}}},fp="18,328,24.468.0,27.376.0,37.220.0,52.224.0,40.154.0,25.174.0"}
P.entries["item:steelsnap-s-rib"] = {n="Ребро Стілснапа",s="Ребро Стілснапа — похмурий трофей, здобутий із туші лютого ватажка гієн Стілснепа в Тисячі Голок. Принесене до Тандер Блафа, воно стає відчутним доказом того, що істоту, позбавлену благословення Земної Матері, знищено.",h="Ребро Стілснапа — похмурий трофей, здобутий із туші лютого ватажка гієн Стілснепа в Тисячі Голок.",kw={"ребро стілснапа","стілснеп","гієни","тисяча голок","мелор стоунгуф","узвишшя мисливців","мисливець"},ang={["class:Hunter"]="Здобути ребро ватажка зграї — перевірка вміння мисливця вистежувати небезпечну здобич і усувати загрози, що порушують рівновагу дикої природи.",["race:Tauren"]="Для тауренів принести цей трофей означає виконати обов'язок перед Земною Матір'ю, знищивши істоту, чия нестримна жорстокість плямує священну рівновагу."},sec={{t="Полювання поза благословенням",b="Більшість полювань тауренів провадять заради прожитку, заради честі чи в пошуках гармонії з природою. Та Стілснеп — здобич іншого роду. Цей лютий ватажок гієн блукає дном каньйону Тисячі Голок на південь від Табору Е'ток, тероризує мирних звірів і збирає зграї дрібніших хижаків для безглуздого кровопролиття. Коли майстер полювання Мелор Стоунгуф з Узвишшя Мисливців прирікає Стілснепа на смерть, він вимагає важку кістку — ребро Стілснепа — як незаперечне підтвердження, що тирана вбито, а каньйон очищено від цієї напасті."}},faq={{q="Для чого потрібне Ребро Стілснапа?",a="Ребро приносять Мелорові Стоунгуфу на Узвишшя Мисливців у Тандер Блафі, щоб завершити полювання на Стілснепа. Воно — відчутний доказ того, що лютого звіра-гієну переможено.",al={"завдання ребра стілснапа","хто хоче ребро стілснапа","що робити з ребром стілснапа"}},{q="Де знайти Стілснепа, щоб здобути ребро?",a="Стілснеп никає північно-західною частиною Тисячі Голок, блукаючи дном каньйону на південь від Табору Е'ток, зазвичай у супроводі вірних побратимів зі зграї.",al={"місце стілснапа","де стілснап","знайти стілснапа"}},{q="Чому Мелор Стоунгуф хоче смерті Стілснепа?",a="Мелор вважає Стілснепа неприродним тираном, що існує поза благословенням Земної Матері. На відміну від звичайних хижаків, які полюють, щоб вижити, Стілснеп сіє безглузде кровопролиття й страх серед мирних звірів, тож його треба знищити.",al={"чому вбити стілснапа","мотив мелора стоунгуфа","лор стілснапа"}},{q="Хто такий Мелор Стоунгуф?",a="Мелор Стоунгуф — досвідчений мисливець-таурен з Узвишшя Мисливців у Тандер Блафі, який доручає молодим слідопитам вистежувати небезпечних звірів по всьому Калімдору.",al={"хто такий мелор","місце мелора стоунгуфа","мелор мисливського підйому"}}},fp="15,245,27.553.0,33.177.0,42.148.0,47.240.0,23.165.0"}
P.entries["item:stolen-silver"] = {n="Викрадене Срібло",s="Викрадене срібло — повернена скринька з монетами Орди, призначеними для гарнізону варти Перехрестя. Її найдивнішим чином потягли в дикі хащі люті раптори Пусток, чим неабияк приголомшили наглядачів застави.",h="Викрадене срібло — повернена скринька з монетами Орди, призначеними для гарнізону варти Перехрестя.",kw={"викрадене срібло","раптори","угіддя рапторів","ґазроґ","перехрестя","платня"},ang={["faction:Horde"]="Перехрестя — стратегічне серце Орди в Пустках. Повернувши ці гроші, ви дбаєте, щоб місцеві бійці були ситі, вчасно отримували платню й були готові тримати оборону проти набігів кентаврів і Альянсу."},sec={{t="Звірине пограбування",b="Неосяжні дикі простори Пусток постійно загрожують шляхам постачання, але мало хто чекав, що місцеві сонцелускі раптори полюватимуть на скриньки з монетами. Коли перехопили вантаж із платнею для гарнізону Перехрестя, раптори затягли скриньку до своїх спільних гнізд в Угіддях Рапторів на південь від Раджета. Для наглядачів на кшталт Ґазроґа ця крадіжка виявила тривожну хитрість хижаків: вони, схоже, або цінують блискучі дрібнички, або мають розум, що далеко перевершує звичайних диких звірів."}},faq={{q="Що таке Викрадене Срібло?",a="Це важка скриня, повна срібних монет на платню вартовим Перехрестя. Її викрали під час нападу диких рапторів і затягли до їхніх гнізд.",al={"що таке викрадене срібло","що за срібло"}},{q="Навіщо рапторам викрадати скриню з монетами?",a="Чим керувалися хижаки, лишається загадкою навіть для таких бувалих воїнів, як Ґазроґ. Звірі зазвичай шукають поживу, але раптори Пусток славляться незвичайною кмітливістю, і щось змусило їх затягти блискучу металеву скриню глибоко до свого лігва.",al={"чому раптори хочуть срібло","розум рапторів","чому срібло"}},{q="Куди забрали срібло?",a="Раптори затягли скриню до Угідь Рапторів — скелястого каньйону з гніздами на південь від Раджета, на сході Пусток.",al={"місце викраденого срібла","де срібло"}},{q="Хто шукає Викрадене Срібло?",a="Ґазроґ, орк із Перехрестя, шукає скриню. У ній — повна місячна платня для виснажених захисників застави.",al={"хто хоче срібло","хто здає викрадене срібло"}}},fp="13,239,15.530.0,26.173.0,41.248.0,27.128.0,37.141.0"}
P.entries["item:stone-of-relu"] = {n="Камінь Релу",s="Камінь Релу — давня археологічна реліквія, знайдена в Багнокраї. Археолог Флеґонґат вважає його ключем до прихованих сил первісних скам'янілостей; ненадовго камінь загубився, коли на вченого дорогою напали місцеві раптори.",h="Камінь Релу — давня археологічна реліквія, знайдена в Багнокраї.",kw={"камінь релу","флеґонґат","ліга дослідників","раптори","багнокрай","скам'янілості"},ang={["faction:Alliance"]="Експедиції Альянсу в Гавані Менетіл покладаються на віднайдені артефакти на кшталт Каменя Релу, щоб виправдати виснажливі розкопки на небезпечних болотах.",["race:Dwarf"]="Для Ліги Дослідників Камінь Релу — важливе знаряддя, щоб скласти докупи історію походження давнього життя й забуту спадщину світу."},sec={{t="Ключ до давніх реліквій",b="Знайдений під час робіт Ліги Дослідників, Камінь Релу, як вважають, має силу, потрібну, щоб розкрити доісторичні скам'янілості, зібрані в Калімдорі та Східних Королівствах. Археолог Флеґонґат визначив цей артефакт як каталізатор, що вивільнить таємниці і його власних зразків із Багнокраю, і скам'янілості, яку шукач Ремтревел відкопав на Темному Узбережжі."},{t="Загублений серед боліт",b="Коли Флеґонґат ішов дорогами Багнокраю на зустріч із шукачем Велґаром, на нього напала зграя плямистих рапторів. У метушні реліквія загубилася, і її проковтнув один із ненажерливих звірів, тож Ліга мусила наймати шукачів пригод, щоб полювати на болотяних рапторів і вирізати давній камінь із їхніх горлянок."}},faq={{q="Що таке Камінь Релу?",a="Камінь Релу — давній артефакт, який шукає Археолог Флеґонґат. Він вважає, що камінь — це ключ або каталізатор, здатний розкрити приховані таємниці й силу, що дрімають у доісторичних скам'янілостях.",al={"камінь релу","що це за камінь","артефакт релу"}},{q="Як камінь опинився в шлунку раптора?",a="Археолог Флеґонґат ніс реліквію дорогою через Багнокрай на зустріч із Шукачем Велґаром, коли на його загін напали плямисті раптори. У метушні камінь загубився, і його проковтнув один зі звірів-падальників.",al={"чому раптори його мають","хто загубив камінь","як його загубили"}},{q="Що Флеґонґат збирається робити з каменем?",a="Флеґонґат хоче поєднати камінь зі своєю знайденою скам'янілістю та скам'янілістю, яку відшукав Шукач Ремтревел на Темному Узбережжі, щоб за допомогою реліквії розгадати й вивільнити їхні приховані магічні таємниці.",al={"що флеґонґат зробить з каменем","призначення каменю релу"}}},fp="13,258,23.387.0,19.330.0,26.207.0,41.217.0,48.190.0"}
P.entries["item:stonetalon-sap"] = {n="Сік з Кам'яного Кігтя",s="Сік з Кам'яного Кігтя — липка, сильна речовина, яку добувають просто з неповоротких живичних звірів, що бродять скелястими висотами Гір Кам'яного Кігтя. Це важливий реагент для знахаря Темного Списа Джин'Зіла, який використовує його сирі лісові властивості, щоб зварити злісне зілля.",h="Сік з Кам'яного Кігтя — липка, сильна речовина, яку добувають просто з неповоротких живичних звірів, що...",kw={"сік з кам'яного кігтя","живичні звірі","знахар джин'зіл","малака'джин","озеро міркфаллон","вуду"},ang={["race:NightElf"]="Осквернення рідної природи Гір Кам'яного Кігтя знахарем Орди, щоб отруїти полонених вартових, — наруга над природою й Елуною.",["race:Troll"]="Знахар Джин'Зіл показує хист Темного Списа обертати улюблений ворогом край на смертоносне знаряддя вуду."},sec={{t="Гіркий збір",b="Ця густа рідина, що скрапує з деревних живичних звірів біля Озера Міркфаллон і Піку Кам'яного Кігтя, несе зосереджену сутність давньої рослинності гір. У природі, у спокої, сік нешкідливий, але в руках досвідченого алхіміка чи знахаря його легко обернути на щось куди темніше. Джин'Зіл із Малака'джина жадає його, щоб зварити те, що глузливо називає «лісовою магією», — смертельний напій, яким має мучити полонених вартових з-поміж нічних ельфів самою сутністю їхньої улюбленої дикої природи."}},faq={{q="Які створіння мають Сік з Кам'яного Кігтя?",a="Його збирають із сокових звірів — дивних лісових створінь, що водяться біля Озера Міркфаллон і вище, на схилах, що ведуть до Піку Кам'яного Кігтя.",al={"де взяти сік кам'яного кігтя","хто дропає сік кам'яного кігтя","соковиті звірі"}},{q="Для чого Знахар Джин'Зіл використовує сік?",a="Джин'Зіл змішує сік з очима скакунів, сутінковими вусами й лускою феєвого дракона, щоб зварити отруйне зілля, яке випробовує на нічних ельфах, ув'язнених у його клітках.",al={"чому джин'зіл хоче сік","рецепт лісової магії джин'зіла"}},{q="Де найкраще шукати сокових звірів?",a="Сокові звірі живуть у гаях довкола Озера Міркфаллон і на буйних зелених стежках, що здіймаються до Піку Кам'яного Кігтя.",al={"місце соковитих звірів","соковиті звірі озера міркфаллон"}},{q="Чи магічний сік сам по собі?",a="Він від природи насичений первісною життєвою силою нагір'я Кам'яного Кігтя, але щоб обернути його на смертельну отруту, потрібні тролівське моджо й особливі реагенти.",al={"чи магічний сік кам'яного кігтя","властивості соку кам'яного кігтя"}}},fp="14,283,16.519.1,36.148.0,47.163.1,43.109.0,30.160.0"}
P.entries["item:stormpike-banner"] = {n="Прапор Стормпайк",s="Прапор Стормпайк — військовий стяг, захований глибоко в підступній Печері Крижаного Крила в Долині Альтерак. Новобранці Альянсу мусять пройти повз диких гарпій, щоб повернути його в межах обряду посвяти й довести, що гідні носити відзнаку Стормпайків.",h="Прапор Стормпайк — військовий стяг, захований глибоко в підступній Печері Крижаного Крила в Долині Альтерак.",kw={"прапор стормпайк","варта стормпайків","печера крижаного крила","долина альтерак","лейтенант гаґґердін","дун балдар"},ang={["faction:Alliance"]="Повернення прапора позначає ваш офіційний вступ до Варти Стормпайків і дає право нести їхню бойову відзнаку в боротьбі з Кланом Морозного Вовка.",["race:Dwarf"]="Прапор уособлює законні права Айронфорджа та священну місію клану Стормпайк — відшукати реліквії титанів по всій долині."},sec={{t="Обряд прийняття",b="Щоб офіційно вступити до лав експедиції Стормпайків у Долині Альтерак, новобранці мусять довести свою мужність ще до першого зіткнення з орками клану Морозного Вовка. Лейтенант Гаґґердін посилає новоприбулих солдатів Альянсу до Печер Крижаного Крила на південний захід від Дун Балдара. Захований глибоко в цьому крижаному підземному лігві, Прапор Стормпайк — справжнє випробування: кожен, хто наважиться протистояти місцевим гарпіям, захопить стяг і повернеться живим, отримує звання й відзнаку новачка Варти Стормпайків."}},faq={{q="Де знаходиться Прапор Стормпайк?",a="Прапор устромлено глибоко в Печерах Крижаного Крила — скутій кригою системі печер на південний захід від Дун Балдара в Долині Альтерак.",al={"місце прапора","де прапор стормпайк","як знайти прапор"}},{q="Чому новобранці мають принести прапор?",a="Лейтенант Гаґґердін вимагає, щоб кожен новобранець Альянсу довів свою хоробрість, перш ніж стати до бою. Хто принесе прапор із небезпечної печери, де аж кишить гарпіями, отримує свою першу Відзнаку Стормпайк.",al={"випробування полігону","чому принести прапор","завдання геґердіна"}},{q="Які загрози чатують на прапор у печері?",a="Печери Крижаного Крила люто захищають дикі місцеві гарпії, що жорстоко нападають на кожного, хто прийде по стяг.",al={"монстри біля прапора","вороги печери льодокрила"}},{q="Кому віддати знайдений прапор?",a="Віднесіть знайдений прапор Лейтенантові Гаґґердіну — офіцерові Альянсу, що стоїть біля входу в Горах Альтерак.",al={"здати прапор","кому віддати прапор"}}},fp="16,248,19.546.0,38.137.0,44.232.0,46.129.0,41.131.0"}
P.entries["item:stormpike-s-request"] = {n="Запит Стормпайк",s="Запит Стормпайка — письмове замовлення, яке Горянин Стормпайк надіслав із пагорбів Лох Модану до Стормвінда. У листі він просить майстра-броняра Фурена Лонґбірда викувати особливий щит неперевершеної дворфійської якості.",h="Запит Стормпайка — письмове замовлення, яке Горянин Стормпайк надіслав із пагорбів Лох Модану до Стормвінда.",kw={"запит стормпайк","горянин стормпайк","фурен лонґбірд","щит","лох модан","дворфійський квартал"},ang={["profession:Blacksmithing"]="Це замовлення — свідчення слави майстрів-бронярів: видатна дворфійська ковальська робота знаходить замовників у цілих королівствах.",["race:Dwarf"]="Для дворфів доставка цього замовлення підтримує родинні й ремісничі зв'язки між горянами, що стережуть Каз Модан, і майстрами, що живуть на чужині в людських містах."},sec={{t="Замовлення з півночі",b="Несучи службу далеко на півночі, в Лох Модані, Горянин Стормпайк потребує нового міцного щита, щоб протистояти небезпекам дворфійського прикордоння. Не довіряючи звичайним ковалям, він наполягає, щоб щит викував Фурен Лонґбірд — броняр, чию легендарну майстерність він шанує понад усе. Фурен тепер живе далеко на півдні, серед людей у Дворфійському Кварталі Стормвінда, — Стормпайк вважає, що з Айронфорджу його виманили не інакше як королівським викупом, — тож горянин покладається на мандрівних шукачів пригод, щоб доставити його офіційне замовлення через королівства."},{t="Рід Стормпайків",b="Доставлений у жвавий Дворфійський Квартал Стормвінда, лист потрапляє просто до вправних рук Фурена Лонґбірда. Стормпайки — горда й поважна дворфійська родина, відома по всьому Каз Модану і бойовою витримкою, і чималими статками, тож їхнє замовлення має вагу. Радий звісткам і роботі зі своєї рідної півночі, Фурен погоджується виконати замовлення й береться кувати щит для горянина."}},faq={{q="Що таке Запит Стормпайк?",a="Це письмове замовлення Горянина Стормпайка з Лох Модану: він просить майстра обладунків Фурена Лонґбірда викувати йому якісний щит.",al={"що це за лист","предмет наказ стормпайка","запит стормпайк"}},{q="Хто написав цей лист?",a="Його написав Горянин Стормпайк — дворф-вартовий, що захищає перевали Лох Модану й щиро захоплюється ковальським хистом Фурена Лонґбірда.",al={"хто надіслав запит стормпайка","хто це написав","горянин стормпайк"}},{q="Куди треба доставити цей лист?",a="Його адресовано Фуренові Лонґбірду, який працює у своїй кузні в Дворфійському Кварталі Стормвінда.",al={"куди нести запит стормпайка","хто отримує лист","доставити запит стормпайка"}},{q="Чому Стормпайк наймає коваля аж у Стормвінді?",a="Горянин Стормпайк вважає майстерність Фурена неперевершеною й не погоджується на жодного іншого зброяра, хоч Фурен і покинув Айронфордж, щоб займатися ремеслом серед людей на півдні.",al={"чому фурен","чому не кувати в айронфорджі","чому слати до стормвінда"}}},fp="19,237,21.578.0,18.448.0,28.154.0,22.144.0,34.105.0,57.191.0"}
P.entries["item:stormwind-armor-marker"] = {n="Талон на Обладунок Стормвінда",s="Талон на Обладунок Стормвінда — офіційний військовий реквізиційний знак, який видають шукачам пригод, що допомогли королівству. Його можна обміняти в уповноважених ремісників, як-от Сара Тімберлейн у Лісозаготівельному Таборі Східної Долини, на щойно виготовлене спорядження.",h="Талон на Обладунок Стормвінда — офіційний військовий реквізиційний знак, який видають шукачам пригод, що...",kw={"талон на обладунок","реквізиція","сара тімберлейн","східна долина","обладунок","стормвінд"},ang={["faction:Alliance"]="Талон утілює господарські зв'язки, що напряму з'єднують прикордонні поселення на кшталт Лісозаготівельного Табору Східної Долини з військовим командуванням Стормвінда."},sec={{t="Військові реквізиції",b="Підтримання закону й порядку по всьому Лісі Елвінн виснажує ресурси королівства. Замість роздавати стандартне спорядження просто з військових застав, командири часом видають офіційні знаки, відомі як талони на обладунок. Ці реквізиційні квитки засвідчують, що носій доблесно послужив Стормвінду, й уповноважують місцевих найнятих майстрів забезпечити його підігнаним обладунком."},{t="Постачання Східної Долини",b="Одне з головних місць, куди несуть ці талони, — Лісозаготівельний Табір Східної Долини на східному рубежі Елвінну. Там ремісники на кшталт Сари Тімберлейн працюють за замовленням війська Стормвінда, перетворюючи місцеві матеріали на захисний одяг із тканини й шкіри. Пред'явивши талон, новобранці отримують підігнаний захист, що допоможе їм берегти довколишні ліси."}},faq={{q="Для чого потрібен Талон на Обладунок Стормвінда?",a="Це офіційний військовий талон, який дають шукачам пригод, що допомагають варті Стормвінда. Він засвідчує вашу службу й дає змогу отримати обладунок у майстра, що працює на замовлення армії.",al={"що таке талон на обладунок","призначення талона","використання талона стормвінда"}},{q="Хто приймає талон?",a="Його приймає Сара Тімберлейн у Лісозаготівельному Таборі Східної Долини, просто на схід через річку в Лісі Елвінн. Вона має угоду з армією Стормвінда на виготовлення тканинного й шкіряного спорядження.",al={"хто бере талон","куди здати талон","талон сари тімберлейн"}},{q="Чому Стормвінд видає талони, а не роздає обладунки одразу?",a="На віддалених заставах варти часто бракує складів, кузень і кравецьких майстерень, щоб спорядити новобранців на місці. Видаючи талони, польові командири доручають спорядження місцевим ремісникам, як-от Сара Тімберлейн, які мають власні майстерні.",al={"чому талони замість обладунків","чому армійські талони","військові ваучери ельвін"}},{q="Яке спорядження можна отримати за талон?",a="Талон дає власникові право вибрати новий тканинний чи шкіряний обладунок, виготовлений на замовлення армійськими постачальниками.",al={"яку броню отримаю","нагороди за талон","тканина чи шкіра"}}},fp="22,251,21.397.0,21.379.0,50.208.0,23.204.0,69.259.0,47.137.0"}
P.entries["item:stoutmantle-s-response-to-solomon"] = {n="Відповідь Стаутмантла Соломону",s="«Відповідь Стаутмантла Соломону» — письмове послання, яке везуть із Сентінел Гілла до Лейкширу. У ньому Ґраян Стаутмантл з гіркотою повідомляє Магістратові Соломону, що знекровлене Народне ополчення не може виділити жодного вояка на оборону Гір Редріджу.",h="«Відповідь Стаутмантла Соломону» — письмове послання, яке везуть із Сентінел Гілла до Лейкширу.",kw={"відповідь стаутмантла соломону","ґраян стаутмантл","магістрат соломон","лейкшир","редрідж","народне ополчення"},ang={["faction:Alliance"]="Цей лист оголює політичну гниль, що паралізує саме серце Альянсу: віддалені поселення мусять благати допомоги одне в одного, поки столиця тримає свої сили при собі.",["race:Human"]="Для людських захисників це послання — похмуре нагадування, що сільська глибинка, як-от Вестфол і Редрідж, однаково відчайдушно бореться за виживання без королівської варти Стормвінда."},sec={{t="Відмова на благання",b="Під безжальним тиском орків Блекрок і гнолів Магістрат Соломон із Лейкширу звернувся до Сентінел Гілла, сподіваючись, що місцеві сили Вестфолу пришлють підкріплення. Письмова відповідь Ґраяна Стаутмантла приносить гірку звістку. Прохання магістрата завдає Стаутмантлові болю, і він чітко дає зрозуміти: Соломон не усвідомлює, наскільки тяжка війна поглинає Вестфол. Народне ополчення постало з відчаю саме тому, що Корона відкликала свій гарнізон і залишила фермерів і добровольців самих протистояти Братству Дефіас. Стаутмантл пояснює, що його власні сили стікають кров'ю й розтягнуті до краю, тож він не може пожертвувати людьми, щоб рятувати ще одне покинуте прикордоння."},{t="Забуті королівством",b="Листування показує спільну трагедію південних людських земель у 25 році після Темного Порталу. І Редрідж, і Вестфол цілком покинуті королівським двором у Стормвінді. Поки король Варіан Рінн вважається зниклим, а постійне військо королівства з незрозумілих причин не пускають до провінційних кордонів, віддаленим містечкам лишається або створювати власну добровольчу варту, або загинути. Коли Соломон отримує запечатану відповідь, до нього доходить: жодне з містечок не врятує інше; усе королівство розлазиться по швах, а столиця мовчить."}},faq={{q="Що написано у Відповіді Стаутмантла Соломону?",a="Ґраян Стаутмантл пояснює, що Вестфол охоплений жорстокою війною з Братством Дефіас і, як і Редрідж, покинутий армією Стормвінда. Він сумує за полеглими захисниками, але твердо відмовляє Магістратові Соломону в проханні про військове підкріплення.",al={"що каже лист","зміст листа стаутмантла","текст відповіді соломону"}},{q="Чому Соломон узагалі попросив допомоги у Вестфолу?",a="На Лейкшир тяжко нападають гноли й орки Блекрок, а його прохання до Генерала Маркуса Джонатана в Стормвінді досі не принесло жодних військ. Не маючи офіційної підтримки, Магістрат Соломон звернувся через Елвінн до Народного ополчення, сподіваючись, що такі самі захисники прикордоння зможуть виділити бійців.",al={"чому просити вестфолл","соломон просить стаутмантла","чому лейкшир просив ополчення"}},{q="Чому Народне ополчення не може виділити бійців?",a="Народне ополчення — добровольче військо, яке ледве втримує Сентінел Гілл і довколишні рівнини від Братства Дефіас. Втрати зростають щодня, підтримки регулярної армії немає, тож, пославши бійців до Лейкширу, Вестфол залишився б зовсім беззахисним.",al={"чому ополчення не допомагає","чи може вестфолл допомогти редріджу","чому відмовити соломону"}},{q="Чому армія Стормвінда не захищає ці містечка?",a="Ніхто в жодному з містечок цього не знає. Стаутмантл пише лише, що Стормвінд відкликав свої війська й залишив Вестфол беззахисним, а Магістрат Соломон може тільки гадати, що ж такого важливого відірвало армію Стормвінда від її народу. Обидва сільські краї змушені боронитися самотужки, силами місцевих добровольців.",al={"де армія стормвінда","чому стормвінд не допоможе","дезертирство стормвінда"}}},fp="33,251,13.687.0,21.551.1,42.282.0,57.293.0,48.269.0,52.322.0"}
P.entries["item:strange-smelling-powder"] = {n="Дивно Пахучий Порошок",s="Дивно Пахучий Порошок — загадковий осад, знайдений під час розслідування підозрілих диверсій довкола Лох Модану. Побоюючись, що це нестійка підривна речовина, Головний Інженер Гіндервір терміново шле гінця на північ, до знавця вибухівки.",h="Дивно Пахучий Порошок — загадковий осад, знайдений під час розслідування підозрілих диверсій довкола Лох...",kw={"дивно пахучий порошок","гіндервір","ешлан стоунсмерк","дун модр","вибухівка","диверсія","лох модан"},ang={["profession:Engineering"]="Інженери впізнають сірчаний запах нестійких підривних сумішей, що не відповідають звичним формулам, якими користуються на гірничих заставах Альянсу.",["race:Dwarf"]="Для дворфів захист кам'яних споруд і водосховищ Лох Модану понад усе, тож будь-який натяк на ворожу вибухівку — негайна криза для всього клану."},sec={{t="Небезпечна знахідка",b="Цей дивний порошок знайшли серед слідів диверсії, що загрожує спорудам Лох Модану, і він одразу стривожив Головного Інженера Гіндервіра. Різкий запах і дрібна текстура свідчать, що це спеціально виготовлена підривна суміш, а не звичайний гірничий вибуховий порох. Не знаючи ні хімічної природи суміші, ні її походження, Гіндервір не наважується порпатися в ній сам: найменша іскра може накликати лихо."},{t="Шлях на північ",b="Дворфійські інженери не ризикують із небезпечними реагентами, тож Гіндервір відсилає зразки порошку крізь Браму Алґаз до Багнокраю. Там, у Дун Модрі біля Мосту Тандол, досвідчений знавець вибухівки Ешлан Стоунсмерк має роздивитися крупинки й з'ясувати, який нищівний вибух готують диверсанти."}},faq={{q="Що таке Дивно Пахучий Порошок?",a="Це підозрілий хімічний осад, знайдений у Лох Модані під час розслідування місцевих диверсій. Через різкий сморід і склад дворфські інженери підозрюють, що це вибухова речовина.",al={"що таке дивно пахучий порошок","що це за порошок","порошок лох модану"}},{q="Навіщо Головний Інженер Гіндервір хоче його дослідити?",a="Гіндервір підозрює, що порошок — особлива вибухівка. Щоб зрозуміти розмах і небезпеку змови проти Лох Модану, йому потрібен висновок фахівця, що добре знається на підривній справі.",al={"навіщо досліджувати порошок","порошок гіндервейра","кому потрібен порошок"}},{q="Хто може розпізнати порошок?",a="Головний Інженер Гіндервір посилає мандрівників віднести зразок Ешланові Стоунсмерку — знавцеві вибухівки, що служить далеко на півночі з полком у Дун Модрі, біля Мосту Тандол.",al={"хто впізнає порошок","куди нести порошок","знавець порошку"}},{q="Чому перевозити порошок небезпечно?",a="Окрім природної нестійкості невідомої вибухової речовини, доведеться ще й пройти небезпечний шлях крізь Браму Алґаз на болотисті, ворожі дороги Багнокраю.",al={"чи небезпечний порошок","чому небезпечно"}}},fp="23,268,20.427.0,14.358.1,32.197.0,52.214.0,28.180.0,41.189.0"}
P.entries["item:strangely-marked-box"] = {n="Дивно Помічена Скриня",s="Дивно Помічена Скриня — вантаж, знайдений у збруї, пристебнутій до мертвих морських черепах на березі Темного Узбережжя. На її таємничій поверхні — рунічні письмена зміїстих наг, і це доводить ученим нічних ельфів, що морські створіння викидалися на берег не випадково.",h="Дивно Помічена Скриня — вантаж, знайдений у збруї, пристебнутій до мертвих морських черепах на березі Темного...",kw={"дивно помічена скриня","наги","морські черепахи","ґвенніт блай'леґґонд","храм місяця","темне узбережжя"},ang={["class:Priest"]="Рятуючи реліквії з берега, ви допомагаєте вченим Храму Місяця в Обердайні вберегти узбережжя від морської порчі.",["race:NightElf"]="Скрині з припасами наг, прив'язані до місцевих морських черепах на Темному Узбережжі, попереджають калдореїв: їхні давні спотворені родичі планомірно виходять на берег із Великого Моря."},sec={{t="Трофеї глибин",b="Кількох велетенських морських черепах та інших морських створінь просто викидає на оповиті імлою пляжі Темного Узбережжя, та інші туші розповідають куди зловіснішу історію. На деяких — уламки верхової збруї та покинуті ноші, прив'язані просто до панцирів. Серед решток цих погнутих пристосувань лежать запечатані скрині, вкриті чужими звивистими рунами. Мурлоки Сірої Імли, що шукають поживи, часто оселяються в порожніх грудних кошиках і розбитих возах, обгризають падло й стережуть усе, що там лишилося."},{t="Докази наступу наг",b="Коли скриню приносять Ґвенніт Блай'Леґґонд, дослідниці, що представляє Храм Місяця в Обердайні, знаки на ній відкривають своє справжнє походження. Письмена й прив'язані ноші належать нагам, які використовують величезних черепах як в'ючних тварин, щоб переправляти на суходіл припаси й військове спорядження. Знайдені скрині з припасами підтверджують, що наги навмисно діють на північних берегах і, можливо, женуть своїх тварин на південь, до Ашенвалю, тож жрецтво Обердайна відсилає реліквії просто до Дарнасуса для подальшого вивчення."}},faq={{q="Де знайти Дивно Помічену Скриню?",a="Скриню дістають із покинутих вантажних кошів, прив'язаних до панцирів мертвих морських черепах, викинутих на берег Темного Узбережжя. Довкола цих туш часто товчуться мурлоки з племені Сірої Імли, що ласують падлом і захищають його.",al={"де знайти дивно помічену скриню","місце скрині","скриня черепашачого візка"}},{q="Хто зробив Дивно Помічену Скриню?",a="Скриню й написи на ній зробили наги. Вони прилаштовують вантажні коші до живих морських черепах, щоб перевозити провізію, зброю й спорядження з морських глибин на береги Калімдору.",al={"хто зробив скриню","позначки на скрині","руни на скрині","що за позначки"}},{q="Кому в Обердайні потрібна ця скриня?",a="Ґвенніт Блай'Леґґонд, дослідниця, що працює в Обердайні для Храму Місяця, забирає скриню, щоб розібратися в дивних викидах на берег і зрозуміти, наскільки зросла загроза від наг.",al={"кому віддати скриню","здати скриню","хто хоче скриню"}},{q="Чому морські черепахи несли ці скрині?",a="Наги приручають або поневолюють гігантських морських черепах як в'ючних тварин: прив'язують їм на спини упряж і коші, щоб іти в бій і доставляти припаси на суходіл. Ґвенніт підозрює, що одну таку черепаху вбили, коли вона прямувала далі на південь — можливо, до Ашенвалю.",al={"чому черепахи мають скрині","черепашачі візки","чому черепахи з ременями"}},{q="Що стається зі скринею, коли віддати її Ґвенніт?",a="Ґвенніт Блай'Леґґонд пересилає скриню й решту знахідок з узбережжя до Храму Місяця в Дарнасусі, щоб провідники нічних ельфів могли з'ясувати масштаби вторгнення наг.",al={"куди йде скриня","скриня надіслана до дарнасуса"}}},fp="20,303,20.544.0,26.575.1,40.224.0,34.200.0,32.183.0,46.269.0,52.196.0"}
P.entries["item:strigid-owl-feather"] = {n="Перо Стригідної Сови",s="Пера Стригідної Сови збирають із диких сов-стригід, що гніздяться у вітті Тельдрассила. Хоч це природне лісове пір'я, його шукають сумнівні постаті, яким потрібна сировина для таємних оборудок.",h="Пера Стригідної Сови збирають із диких сов-стригід, що гніздяться у вітті Тельдрассила.",kw={"перо стригідної сови","сова-стригіда","пір'я","зенн фаулгуф","сатир","доланаар","тельдрассил"},ang={["class:Druid"]="Друїди високо шанують крилатих мисливців Тельдрассила, тож бачити, як їхнє пір'я збирають під облудним приводом на підозрілі складники, — прикро.",["race:NightElf"]="Сов Тельдрассила мають за створіння Елуни, тож їхній визиск застарілим сатиром на кшталт Зенна Фаулгуфа — образа священному лісу."},sec={{t="Лісове пір'я й темні оборудки",b="У шатрах Тельдрассила живуть сови-стригіди й верескуни — корінні хижі птахи, що полюють по всій Короні Землі. Їхній пух і пера — звична знахідка на лісовій долівці, та часом вони привертають око тих, хто шукає живі складники. За Доланааром сатир-відступник Зенн Фаулгуф користається з недосвідчених мандрівників, що спускаються дорогою з Тінедолу, і підбурює їх здобувати пера стригід разом із павутинним шовком та іклами нічних шаблезубів для своїх тіньових справ."}},faq={{q="Де знайти Пір'я Стригідної Сови?",a="Це пір'я збирають, полюючи на сову-стригіду та верескливу стригіду, що живуть у лісах довкола Доланаара та по всьому Тельдрассилу.",al={"місце пера","де падає пір'я стригідної сови","фарм пір'я сови"}},{q="Кому потрібне Пір'я Стригідної Сови?",a="Сатир на ім'я Зенн Фаулгуф, що причаївся біля стежки до Доланаара, просить наївних шукачів пригод принести це пір'я, а також павутинний шовк Вебвуда й ікла нічних шаблезубів.",al={"кому потрібне пір'я сови","здати пір'я сови","зенн пір'я сови"}},{q="Для чого Зенн Фаулгуф використовує пір'я?",a="Зенн запевняє, що це реагенти для його таємних справ у лісі, хоча насправді найбільше він тішиться тим, що обдурює довірливих новачків і змушує їх робити за нього брудну роботу.",al={"навіщо зенн пір'я","призначення реагента зенна"}}},fp="19,226,32.519.1,38.139.0,31.160.0,45.165.0"}
P.entries["item:sturdy-dragonmaw-shinbone"] = {n="Міцна Гомілкова Кістка Драконячої Пащі",s="Міцні Гомілкові Кістки Драконячої Пащі — тривкі кістяні трофеї, зібрані з орків-ренегатів Драконячої Пащі в Багнокраї. Їх потребує майстриня обладунків Велора Найтлі в Андерсіті: ці кістки стають опорними розпірками для обладунків, які вона кує для воїнів на замовлення.",h="Міцні Гомілкові Кістки Драконячої Пащі — тривкі кістяні трофеї, зібрані з орків-ренегатів Драконячої Пащі в...",kw={"міцна гомілкова кістка драконячої пащі","драконяча паща","орки","велора найтлі","багнокрай","табір анґерфанґ","воїн"},ang={["class:Warrior"]="Здобути ці щільні орківські кістки й перевірити їх голими руками — так ви доводите свою фізичну силу й водночас збираєте основу для обладунків на замовлення.",["race:Undead"]="Велора Найтлі — взірець типового прагматизму Відступників: кістки ворогів вона перетворює на корисне спорядження для героїв Темної Леді."},sec={{t="Кістки для каркаса",b="Куючи грізні наголінники для воїнів передової, ковалі потребують сировини, що витримає найсуворіші удари. В Андерсіті Велора Найтлі цінує щільні кістки орків-ренегатів Драконячої Пащі, які окопалися в Таборі Анґерфанґ на півночі Багнокраю. Орки Драконячої Пащі славляться кремезною, міцною статурою, тож їхні гомілки чудово підходять як опорні скоби. Та не кожна зібрана кістка витримає навантаження: воїни мусять перевіряти кожну голіруч і відкидати ті, що ламаються під тиском."}},faq={{q="Чим ці гомілкові кістки міцніші за звичайні?",a="Орки Драконячої Пащі від природи мають масивний кістяк, але через дрібні тріщини чи крихкість багато кісток не годяться для обладунків. Щоб переконатися, що кістка міцна, воїн згинає її голими руками: лише ті, що не ламаються, вважають досить міцними для каркаса захисних наголінників.",al={"чому гомілкові кістки міцні","міцність кісток драконячої пащі","перевірка гомілкових кісток"}},{q="Кому потрібні Міцні Гомілкові Кістки Драконячої Пащі?",a="Їх шукає Велора Найтлі, майстриня обладунків з Андерсіті. Вона використовує їх як основні розпірки каркаса, коли виготовляє грізні наголінники для перспективних воїнів Орди.",al={"кому потрібні гомілкові кістки","кістки велори найтлі","здати гомілкові кістки драконячої пащі"}},{q="Де збирають ці кістки?",a="Їх здобувають з орків-ренегатів Драконячої Пащі, що захопили Багнокрай на південь від Аратійського нагір'я, — передусім у Таборі Анґерфанґ серед пагорбів на південний захід від Мосту Тандол.",al={"де взяти гомілкові кістки драконячої пащі","місце гомілкової кістки драконячої пащі","кістки енґерфенґа"}},{q="Чому Велора Найтлі робить обладунки з орківських кісток?",a="Ремесло Відступників часто поєднує кістки, сухожилля й метал у моторошне, але надзвичайно міцне бойове спорядження. Клан Драконячої Пащі ворогує з Ордою Тралла, тож його рештки — законна здобич для ковалів-Відступників, яким потрібен міцний, витривалий матеріал.",al={"чому орківські кістки","відступники обладунки з кісток","велора кісткове ремесло"}}},fp="25,235,19.551.0,58.307.0,37.166.0,31.194.0,47.265.0"}
P.entries["item:sully-balloo-s-letter"] = {n="Лист Саллі Баллу",s="Лист Саллі Баллу — розмокле, ніжне послання, знайдене біля затонулих останків дворфійського воїна під Мостом Тандол. Адресований його дружині Сарі в Айронфорджі, він утілює тихі особисті трагедії, що ховаються за великими конфліктами Каз Модану.",h="Лист Саллі Баллу — розмокле, ніжне послання, знайдене біля затонулих останків дворфійського воїна під Мостом...",kw={"лист саллі баллу","саллі баллу","сара баллу","міст тандол","удова","айронфордж","багнокрай"},ang={["faction:Alliance"]="Доставити лист — скорботна мить співчуття: останні думки полеглого воїна дійдуть до його вдови, а не будуть забуті під мостом.",["race:Dwarf"]="Для дворфів цей лист утілює болісні жертви, на які йдуть звичайні горяни й воїни, щоб стерегти високі мости й гірські перевали Каз Модану."},sec={{t="Останнє прощання під хвилями",b="Під велетенськими кам'яними опорами Мосту Тандол, що з'єднує Багнокрай з Аратійським нагір'ям, лежить скелет дворфа, придавлений глибоко під бурхливою водою. У його руці затиснутий крихкий, розмоклий конверт із цим листом. Написаний із болісною старанністю в його останні дні чи години, він починається зворушливими словами: «Моя люба Саро…». Хоч пергамент і постраждав від довгого перебування у воді, чорнило досі береже незгасну любов дворфійського захисника, який так і не повернувся додому, до міста Айронфордж."},{t="Доставка до Айронфорджа",b="Принести лист Сарі Баллу в Айронфордж — означає принести їй скорботне, спустошливе завершення. Живучи в дворфійській столиці, Сара зносить болісну невідомість, знайому багатьом, чиї рідні пішли на війну. Останні думки її чоловіка Саллі підтверджують найгірші побоювання — він загинув далеко від дому, під крижаними течіями північної переправи, — але й зберігають його відданість, що пережила смерть."}},faq={{q="Де знайти Лист Саллі Баллу?",a="Лист дістають із розмоклого конверта, затиснутого в руці кістяка дворфа на дні під Мостом Тандол, що відділяє Багнокрай від Аратійського нагір'я.",al={"місце листа","де лист саллі","де знайти лист саллі баллу"}},{q="Хто такий Саллі Баллу?",a="Саллі Баллу — дворф-солдат, що загинув біля Мосту Тандол, захищаючи важливу північну переправу; його рештки так і лишилися притиснуті течією на дні річки.",al={"хто такий саллі баллу","історія саллі баллу","що сталося з саллі"}},{q="Кому адресовано лист?",a="Лист адресовано пані Сарі Баллу, засмученій дружині Саллі, що живе у великому дворфському гірському місті Айронфорджі.",al={"кому лист","хто така сара баллу","куди здати лист саллі"}},{q="Що стається, коли віддати лист Сарі Баллу?",a="Отримавши лист, Сара Баллу з болем дізнається, що її чоловік лежить мертвий під крижаною водою, але дорожить нагодою прочитати останні слова, які він із любов'ю їй написав.",al={"реакція сари баллу","здати лист","завершення завдання листа саллі"}}},fp="21,272,34.545.0,21.404.1,37.212.0,21.178.0,31.130.0,56.203.1"}
P.entries["item:sunscorched-shell"] = {n="Обпалена Сонцем Шкаралупа",s="Обпалена сонцем шкаралупа — міцні рештки яєць віверн, які збирають під гніздовищами Високосіду в Тисячі Голок. Загартована пекучою пустельною спекою, вона дуже цінна для вправних майстрів обладунків, які вміють перетворити її на захисний лак для кольчужних кілець.",h="Обпалена сонцем шкаралупа — міцні рештки яєць віверн, які збирають під гніздовищами Високосіду в Тисячі Голок.",kw={"обпалена сонцем шкаралупа","віверни","високосід","тисяча голок","матіель","фурен лонґбірд","кольчуга","лак"},ang={["class:Warrior"]="Воїни, яким потрібна кольчуга на замовлення, допомагають Матіелю збирати цю міцну шкаралупу, щоб викувати зміцнений обладунок.",["profession:Blacksmithing"]="Ця шкаралупа показує, як кмітливі ковалі дивляться далі звичайної руди й перетворюють природні мінеральні покриття на захисний лак для кольчуг."},sec={{t="Пустельні кладки",b="Віверни Високосіду гніздяться високо на скелях-голках південного Калімдору, і їхні яйця витримують нещадне пустельне сонце й пекучі вітри. Уламки шкаралупи накопичуються під гніздовищами, і сухе підсоння випікає їх до дивовижної твердості. Випадковому мандрівникові вони здаються лише крихким сміттям, але ці обпалені сонцем рештки мають природну міцність, тож для майстрів особливого ремесла це цікавий реагент."},{t="Лак майстра",b="У Дарнасусі майстер обладунків Матіель вивчає ремісничі прийоми, які першим опанував його колега, дворф-коваль Фурен Лонґбірд. Зацікавлений відкриттями Фурена, Матіель виготовляє з цієї шкаралупи тонкий лак, що зміцнює кольчужні обладунки. Правильно оброблене й нанесене, це багате на мінерали покриття зростається з металевими кільцями й робить броню значно витривалішою, не обтяжуючи того, хто її носить."}},faq={{q="Де знайти Обпалену Сонцем Шкаралупу?",a="Вона розкидана на землі під гніздами віверн по всьому Високосіду — високій столовій горі, що здіймається з дна каньйону на заході Тисячі Голок.",al={"де знайти обпалену сонцем шкаралупу","де шкаралупа","шкаралупа хайперча"}},{q="З якого створіння ця шкаралупа?",a="Це уламки шкаралупи яєць віверн Високосіду, що гніздяться на вершинах плато в Тисячі Голок.",al={"яке створіння знесло яйця","яйця виверн","походження шкаралупи"}},{q="Навіщо Матіелю Обпалена Сонцем Шкаралупа?",a="Матіель хоче випробувати прийоми виготовлення обладунків, які відкрив Фурен Лонґбірд. Він перетоплює затверділу шкаралупу на міцний лак, яким покриває й зміцнює кільця кольчуги.",al={"шкаралупа матіеля","для чого шкаралупа","лак для броні"}},{q="Хто такий Фурен Лонґбірд і до чого він тут?",a="Фурен Лонґбірд — колега Матіеля по ковальському ремеслу з Дворфійського Кварталу Стормвінда. Його досліди з незвичними реагентами й прийомами гартування надихнули Матіеля експериментувати з лаком зі шкаралупи віверн.",al={"зв'язок фурена","шкаралупа фурена лонґбірда"}}},fp="17,257,15.447.0,21.390.0,35.143.0,40.104.0,41.174.0,46.223.0"}
P.entries["item:super-reaper-6000-blueprints"] = {n="Креслення Суперкосаря 6000",s="Креслення Суперкосаря 6000 — технічні схеми велетенської механізованої лісорубки, яку Венчурна Компанія застосовує в Горах Кам'яного Кігтя. Розроблені під наглядом гнома-інженера Ґерензо Ренчвісла, ці плани дуже жадані для його незадоволених суперників-гоблінів.",h="Креслення Суперкосаря 6000 — технічні схеми велетенської механізованої лісорубки, яку Венчурна Компанія...",kw={"креслення суперкосаря 6000","суперкосар 6000","ґерензо ренчвісл","венчурна компанія","круча вітрорізу","зіз фіззікс"},ang={["profession:Engineering"]="Креслення відбивають химерне поєднання грубої гоблінської корпоративної сили й скрупульозної гномської механіки — з технічними схемами, від яких губляться звичайні винахідники.",["race:Gnome"]="Креслення Ґерензо Ренчвісла доводять, що навіть безжальні гоблінські синдикати на кшталт Венчурної Компанії зрештою покладаються на гномську кмітливість, щоб будувати складні важкі машини."},sec={{t="Промислове шпигунство на Кручі Вітрорізу",b="Невпинна суцільна вирубка Венчурної Компанії на Кручі Вітрорізу тримається на велетенських механізованих лісозаготівельних машинах — Суперкосарях. На превеликий жаль традиційних гоблінських інженерів, компанія доручила розробку моделі Суперкосар 6000 гномові на ім'я Ґерензо. Ці креслення містять схеми машини, і їх носять оператори Венчурної Компанії, що працюють на ній по всій кручі. Коли гоблінського інженера Зіза Фіззікса вигнали з робіт, його швидко найняв Спаттервалв, щоб викрасти розробки. Проте розшифрувати заплутані, химерні гномські технічні позначки Ґерензо виявляється майже так само важко, як відібрати креслення силою."}},faq={{q="Що таке Суперкосар 6000?",a="Це величезна механічна лісорубна машина, створена для суцільної вирубки лісу Венчурною Компанією в Горах Кам'яного Кігтя: вона валить і переробляє деревину з нещадною промисловою ефективністю.",al={"що таке суперкосар","машина суперкосар"}},{q="Хто сконструював Суперкосар 6000?",a="Креслення розробили під керівництвом Ґерензо Ренчвісла — гнома-інженера, якого Венчурна Компанія найняла очолити механічні роботи на Кручі Вітрорізу, на превелике невдоволення місцевих гоблінів-механіків.",al={"хто зробив креслення","хто сконструював суперкосар"}},{q="Навіщо Зізові Фіззіксу ці креслення?",a="Зіза вигнали з Венчурної Компанії, і його одразу найняв Спаттервалв. Викрадені креслення Суперкосаря — для Зіза нагода довести новому босові, чого він вартий і який він геніальний механік.",al={"навіщо зізу плани","кому потрібні креслення"}},{q="У кого на Кручі Вітрорізу креслення?",a="Креслення носять оператори Венчурної Компанії, що наглядають за машинами й вирубують ліс по всій Кручі Вітрорізу.",al={"де падають креслення","хто дропає креслення"}}},fp="28,296,38.695.0,30.210.0,35.198.0,43.186.0,43.140.0"}
P.entries["item:supplies-for-sven"] = {n="Припаси для Свена",s="Припаси для Свена — пакунок найнеобхіднішого, зібраний у Даркширі для відлюдного табору Свена Йорґена. Серед жахіть Сутінколісся Свен і його невеличкий загін тримаються лише завдяки співчутливим містянам, як-от родина Каревінів, і продовжують нести варту проти тіней.",h="Припаси для Свена — пакунок найнеобхіднішого, зібраний у Даркширі для відлюдного табору Свена Йорґена.",kw={"припаси для свена","свен йорґен","табір свена","даркшир","каревіни","сутінколісся"},ang={["class:Paladin"]="Непохитний опір Свена темряві Сутінколісся побожні люди вважають справжньою справою Світла, тож ці припаси — важлива послуга братові по вірі.",["faction:Alliance"]="Нічна Варта ледве встигає захищати Даркшир, тож мандрівники Альянсу часто стають єдиним надійним гінцем до віддалених застав на кшталт табору Свена."},sec={{t="Рятівна нитка для табору",b="Нести через Сутінколісся спорядження для виживання й найпотрібніші речі — справа непроста. Свен Йорґен і жменька його прибічників таборують у північно-західній глушині лісу, далеко від безпеки Даркшира. Їх так мало, а варта така виснажлива, що вони не можуть відпустити до міста жодного бійця. Цей пакунок — рятівна нитка від родини Каревінів: він дає відрізаному таборові їжу, бинти й матеріали, щоб устояти."}},faq={{q="Хто надіслав ці припаси?",a="Припаси передає родина Каревінів із Даркширу. Знаючи, як відчайдушно бореться Свен Йорґен у глушині, вони зібрали ці харчі, щоб підтримати його табір.",al={"хто надіслав припаси для свена","хто спакував припаси свена","припаси родини каревін"}},{q="Чому Свен не може сам забрати припаси?",a="Загін Свена надто малий. Лише кілька вцілілих товаришів захищають табір на північному заході Сутінколісся від звірів і нежиті, тож вони не можуть відпустити нікого небезпечними дорогами до Даркширу.",al={"чому свен не бере їжу","чому доставка для свена","навіщо припаси"}},{q="Де табір Свена?",a="Табір Свена розташований на північно-західній околиці Сутінколісся, серед пагорбів, далеко за межами прямого захисту Нічної Варти.",al={"де свен йорґен","місце табору свена","знайти свена в сутінколіссі"}},{q="Хто такий Свен Йорґен?",a="Свен Йорґен — поселенець із прикордоння й палкий вірянин Світла, що колись фермерував у Сутінколіссі. Коли його оселю спіткало лихо, він заснував на прикордонні озброєний табір, щоб завдавати ударів темним силам, які мучать край.",al={"хто такий свен","історія свена йорґена"}}},fp="17,280,23.494.0,24.185.0,38.210.0,29.140.0,19.227.0"}
P.entries["item:surena-s-choker"] = {n="Намисто Сурени",s="Намисто Сурени — зачароване намисто з кровавика, яке Ґакін Зв'язувач Темряви подарував своїй колишній учениці Сурені Каледон. Після того як Сурена зрадила Ґакіна й утекла до Братства Дефіас, майстер-чорнокнижник послав послушників-початківців силою повернути прикрасу.",h="Намисто Сурени — зачароване намисто з кровавика, яке Ґакін Зв'язувач Темряви подарував своїй колишній учениці...",kw={"намисто сурени","сурена каледон","ґакін","ерлан драджмур","братство дефіас","кровавик"},ang={["class:Warlock"]="Повернення цього намиста від Сурени Каледон — засадниче випробування для чорнокнижників із людей і гномів: доказ того, що сентиментам немає місця в гонитві за демонічною силою."},sec={{t="Утрачений вклад майстра",b="Ґакін Зв'язувач Темряви, що тихо працює під «Зарізаним Ягням» у Стормвінді, узяв Сурену Каледон перспективною ученицею темних мистецтв. Зачарований її юною привабливістю й магічним хистом, Ґакін подарував їй цінне намисто з кровавика на поміч у навчанні. Та Сурена покинула навчання й утекла з Ерланом Драджмуром, розбійником, пов'язаним із Братством Дефіас. Не бажаючи лишати такий могутній артефакт у руках зрадниці, Ґакін доручає новачкам, що прагнуть влади над порожнечею, вистежити Сурену на Гарбузовій Ділянці Брекуеллів, повернути намисто й показати, де лежить справжня вірність."}},faq={{q="Чому Ґакін Зв'язувач Темряви хоче повернути Намисто Сурени?",a="Ґакін подарував Сурені намисто з кривавиком, коли вона ще була його ученицею. Коли ж вона кинула навчання й утекла з членом Братства Дефіас, Ґакін не захотів лишати зрадниці такий цінний артефакт темної магії.",al={"чому ґакін хоче намисто","ґакін намисто сурени","чому повертати намисто"}},{q="Хто така Сурена Каледон?",a="Сурена Каледон — колишня учениця чорнокнижника зі Стормвінда, що виявляла природний хист під наглядом Ґакіна Зв'язувача Темряви. Вона відвернулася від наставника, щоб утекти з Ерланом Драджмуром і переховуватися серед розбійників Дефіасу в Лісі Елвінн.",al={"хто така сурена","лор сурени каледон","у кого намисто"}},{q="Де знайти намисто?",a="Намисто носить сама Сурена Каледон, що переховується серед бандитів Дефіасу на Гарбузовій Ділянці Брекуеллів на сході Лісу Елвінн.",al={"де сурена","місце намиста","де сурена каледон"}},{q="Для чого намисто, коли його повернуто?",a="Повернене намисто доводить безжальність і відданість учня Ґакінові Зв'язувачу Темряви. Ґакін так і не каже, що з ним зробить, — лише шкодує про змарнований талант Сурени й сподівається, що вкладене в нового учня дасть інші плоди.",al={"що ґакін робить з намистом","призначення намиста","навіщо чорнокнижникам намисто"}}},fp="15,266,26.637.0,56.237.0,22.241.0,30.146.0,50.245.0"}
P.entries["item:swoop-gizzard"] = {n="Шлунок Стрімкокрила",s="Шлунок стрімкокрила — орган хижих птахів, що ширяють над Малгором. Його високо цінують у традиційних народних ліках як важливий складник для очищення від смертельних отрут.",h="Шлунок стрімкокрила — орган хижих птахів, що ширяють над Малгором.",kw={"шлунок стрімкокрила","стрімкокрил","маур рейнколлер","маззранаш","село бладгуф","малгор","ліки"},ang={["race:Tauren"]="Для мисливців і шаманів-тауренів збирання таких частин — шана традиції, за якою кожна частина звірів Малгору служить для прожитку й зцілення племені."},sec={{t="Рідкісний народний складник",b="Стрімкокрили — хижі птахи, що живуть на рівнинах і столових горах Малгору; вони славляться гострим зором і звичкою живитися падлом. Їхнє пір'я й м'ясо таурени використовують у побуті, а от нутрощі — надто шлунок — особливо цінують травники й цілителі. У поєднанні з іншими сильнодійними частинами звірів, як-от кістки кугуарів і серця вовків, цей щільний м'язистий орган допомагає знешкоджувати отруту від укусів звірів і зупиняти гнійне зараження, що поширюється тілом."},{t="Ліки від укусу Маззранаша",b="У Селі Бладгуф знахар Маур Рейнколлер став жертвою легендарного степового довгоступа Маззранаша й дістав люту отруйну рану в плече. Впадаючи в маячню від отрути, що повільно розходиться тілом, Маур покладається на шлунок стрімкокрила разом із серцем степового вовка, стегновою кісткою рівнинного кугуара й лускою степового довгоступа, щоб приготувати цілющу припарку, здатну вигнати смертельну отруту звіра."}},faq={{q="Для чого потрібен Шлунок Стрімкокрила?",a="Це важливий лікарський інгредієнт для Маура Рейнколлера в Селі Бладгуф. Разом із трьома іншими частинами звірів він дає ліки, що можуть очистити від отруйної зарази, спричиненої лютим степовим довгоступом Маззранашем.",al={"використання шлунка стрімкокрила","навіщо мені шлунок стрімкокрила","призначення шлунка"}},{q="Звідки беруться шлунки стрімкокрилів?",a="Їх здобувають із різних стрімкокрилів, що ширяють над рівнинами Малгору: звичайних, жилавих і кігтистих.",al={"де знайти шлунок стрімкокрила","хто дропає шлунок стрімкокрила","полювання на стрімкокрилів"}},{q="Навіщо Маурові Рейнколлеру саме ця частина?",a="Маура вкусив Маззранаш — надзвичайно лютий степовий довгоступ, чий укус несе отруту, що спричиняє шалену гарячку й жахіття. Традиційна тауренська медицина використовує сильнодійні частини звірів, зокрема шлунок, щоб протидіяти саме тій отруті, що тече в його жилах.",al={"ліки маура","чому шлунок","ліки від мазранаш"}},{q="Чи використовують шлунок для чогось іще, крім ліків для Маура?",a="Ні. Поза особливими народними ліками Маура Рейнколлера в Селі Бладгуф шлунки стрімкокрилів не мають звичного застосування ні в кулінарії, ні в алхімії, ні в ремеслах.",al={"інше використання шлунка стрімкокрила","приготування шлунка стрімкокрила","алхімія шлунка стрімкокрила"}}},fp="13,198,22.479.0,31.402.0,33.239.0,34.151.0,49.284.0,56.158.0"}
P.entries["item:tablet-of-verga"] = {n="Скрижаль Верги",s="Скрижаль Верги — магічний камінь із викарбуваними демонічними рунами, без яких не скорити темних сутностей. Її викрав зловісний культ Палаючого Клинка й заховав глибоко у своєму лігві в Череп-скелі. Повернувши артефакт, адепти темних мистецтв в Оргріммарі зможуть розгадати ритуали, потрібні, щоб скорити блукача Порожнечі.",h="Скрижаль Верги — магічний камінь із викарбуваними демонічними рунами, без яких не скорити темних сутностей.",kw={"скрижаль верги","палаючий клинок","череп-скеля","блукач порожнечі","чорнокнижник","тіньова розколина"},ang={["class:Warlock"]="Для чорнокнижників, що навчаються в Оргріммарі, повернути цю скрижаль — важлива віха, що доводить їхню цінність для Орди й відкриває таємниці, потрібні, щоб скорити блукача Порожнечі, вірного захисника.",["faction:Horde"]="Палаючий Клинок так близько від брам Оргріммара — постійна загроза молодій державі Тралла; вириваючи з його рук викрадені реліквії, Орда б'є по впливу культу."},sec={{t="Викрадена реліквія",b="На Скрижалі Верги викарбувано особливі ритуальні руни, потрібні, щоб прикликати істот Нижнього Світу й підкорити їх волі господаря. Коли культові Палаючого Клинка вдалося викрасти скрижаль, він заховав її в потаємній скрині в Череп-скелі, трохи на схід від Оргріммара. Для чорнокнижників, що нишком працюють у тінях Тіньової Розколини, повернути реліквію вкрай важливо — не лише щоб вивчити її давні знаки для прикликання блукача Порожнечі, а й щоб позбавити фанатиків-культистів їхньої власної темної переваги."}},faq={{q="Де знаходиться Скрижаль Верги?",a="Скрижаль зберігається в Схованці Палаючого Клинка в Череп-скелі — печерному комплексі, де аж кишить культистами, просто на схід від Оргріммара в Дуротарі.",al={"місце скрижалі верги","де знайти скрижаль верги","де скрижаль верги"}},{q="Хто хоче повернути Скрижаль Верги?",a="Ґан'рул Бладай, майстер-чорнокнижник із Тіньової Розколини під Оргріммаром, доручає новачкам повернути скрижаль, щоб навчити їх викликати могутніших прислужників.",al={"хто хоче скрижаль верги","кому віднести скрижаль верги","скрижаль ґан'рула"}},{q="Яку силу містить скрижаль?",a="На камені вирізьблено давні руни, без яких не завершити ритуал виклику й підкорення блукача Порожнечі — створіння, витягнутого з Викривленого Нижнього Світу.",al={"що робить скрижаль","лор скрижалі верги","руни скрижалі верги"}},{q="Навіщо Палаючий Клинок її викрав?",a="Культ Палаючого Клинка невтомно шкодить Орді й нарощує власну демонічну силу. Позбавити чорнокнижників Оргріммара ключових ритуальних текстів, а знання зберегти для себе — прямо на руку культистам.",al={"чому палаючий клинок має скрижаль","палаючий клинок верга"}}},fp="15,316,14.500.0,37.158.0,40.180.0,35.158.0,35.225.0"}
P.entries["item:tainted-heart"] = {n="Опоганене Серце",s="Опоганене Серце — уражене пошестю рослинне осердя, видобуте зі споганеної рослинності Тельдрассила. Передане шукачам пригод ботаніком Деналаном, воно потребує магічного й живильного очищення, щоб позбутися залишків огидних сил.",h="Опоганене Серце — уражене пошестю рослинне осердя, видобуте зі споганеної рослинності Тельдрассила.",kw={"опоганене серце","осквернене осердя","деналан","скверна","грядка","ґрунт","тельдрассил"},ang={["class:Druid"]="Для друїдів Кола Кенарія робота над очищенням Опоганеного Серця дає пряме розуміння повзучої скверни, що загрожує здоров'ю молодого Світового Дерева.",["profession:Herbalism"]="Травники й ботаніки оцінять майстерність Деналана в змішуванні особливо збагаченого ґрунту, здатного витягати неприродну гниль із живої рослинної тканини."},sec={{t="Осквернене Осердя",b="Природна рівновага Тельдрассила потерпає від неприродної недуги, що спотворює корінні рослини й звірів. Зчистивши огидний мох, який обліпив уражений наріст, Деналан показує залишене осердя — Опоганене Серце. Хоч і звільнене від зовнішньої гнилі, воно досі просякнуте темрявою. Деналан прагне з'ясувати, чи може особливо приготована, багата на поживу земля побороти залишки скверни й повернути життя споганеному."},{t="Ліки Деналана",b="Покладене в зачаровану грядку Деналана, серце виявляє дивну, невгасиму життєву силу. Воно жадібно вривається в багатий ґрунт і вбирає цілющу поживу. За мить земля випалює скверну, і очищене серце постає живим, пульсуючи чистою силою й пориваючись захищати тих, хто його зцілив."}},faq={{q="Що таке Опоганене Серце?",a="Це серцевина оскверненої рослини з Тельдрассила. Ботанік Деналан зняв зовнішній мерзенний мох, але саме серце просякнуте скверною, доки його не очистять.",al={"що таке опоганене серце","предмет опоганене серце"}},{q="Хто очищує Опоганене Серце?",a="Деналан просить шукачів пригод посадити його в особливо підготовлений вазон біля Озера Ал'Амет. Поживний ґрунт сам очищує серце від неприродної скверни.",al={"хто очищає серце","як очистити опоганене серце"}},{q="Що стається, коли серце посаджено?",a="Серце заривається в ґрунт вазона. За мить воно з'являється знову — цілком очищене, сповнене життя й готове поєднатися з тим, хто його відродив.",al={"що буде з серцем","результат посадженого серця"}},{q="Чому серце взагалі осквернене?",a="Світовим Древом Тельдрассил шириться дивна хвороба, що оскверняє місцеві рослини, деревляників і звірів по всіх його гілках.",al={"чому осквернене","скверна тельдрассила серце"}}},fp="13,219,16.438.0,16.326.1,26.180.0,31.187.0,33.166.1,46.143.0"}
P.entries["item:tainted-keg"] = {n="Опоганене Барильце",s="Опоганене Барильце — барило викраденого дворфійського темного пива, отруєного смертоносним варивом Відступників, яке зготував Аптекар Лайдон. Під виглядом частунку його доставляють полоненим людським фермерам у Таррен Міллі, і воно стає моторошним польовим випробуванням отрут, які розробляє Королівське Аптекарське Товариство.",h="Опоганене Барильце — барило викраденого дворфійського темного пива, отруєного смертоносним варивом...",kw={"опоганене барильце","еліксир агонії","аптекар лайдон","таррен мілл","дарталія","темне пиво шіндіґера"},ang={["race:Human"]="Убивство полонених селян отруєним пивом показує моторошну, безжальну тактику, з якою стикаються рештки живих по всьому Гілсбреду.",["race:Undead"]="Для Королівського Аптекарського Товариства отруєне пиво — практичний етап у створенні біологічної зброї, здатної винищити людство."},sec={{t="Смертоносний урожай",b="Спершу це барильце було барилом Темного Пива Шіндіґера, награбованим у дворфійських стрільців, що окопалися в Дун Ґароку. Замість випити його, Аптекар Лайдон отруїв міцне пиво своїм щойно вдосконаленим Еліксиром Агонії. Отруївши звичайний напій, Відступники створили підступний переносник, що не викликає підозри, — і звична втіха живих стала швидким смертним вироком."},{t="Випробування на приречених",b="На горішньому поверсі таверни Таррен Мілла тримали кількох людських фермерів, схоплених після того, як Верховний Екзекутор Дарталія запідозрила, що серед них ховається військовий стратег зі Стормвінда. Коли надійшла звістка, що стратег загинув деінде, полонені робітники стали непотрібними. Дарталія віддала їх Лайдонові, і той влаштував жорстоке «свято», звелівши поставити отруєне барильце на килим у їхній кімнаті. Спраглі й зневірені, бранці пили вволю — і довели миттєву смертельну силу еліксиру."}},faq={{q="Що в Опоганеному Барильці?",a="У ньому — темне пиво Шіндіґера, міцний дворфський ель, викрадений із Дун Ґарока й змішаний з Еліксиром Агонії, експериментальною отрутою, яку створив Аптекар Лайдон у Таррен Міллі.",al={"вміст барильця","яка отрута в барильці","що в бочці"}},{q="Звідки взялося пиво?",a="Основу забрали в дворфів-горян і стрільців, що тримають Дун Ґарок — добре укріплену дворфську фортецю на південному сході Передгір'я Гілсбреда.",al={"хто зварив пиво","звідки вкрали стаут","джерело стауту шіндіґера"}},{q="Хто п'є з барильця?",a="З барильця п'ють фермери-люди, яких тримають заручниками в кімнаті нагорі корчми Таррен Мілла: випивши отруєного пива, вони падають і майже одразу помирають.",al={"хто п'є з барильця","жертви опоганеного барильця","полонені фермери"}},{q="Чому фермерів тримали в полоні?",a="Верховний Екзекутор Дарталія заарештувала їх, підозрюючи, що серед них ховається військовий стратег Альянсу зі Стормвінда. Коли підтвердилося, що цей стратег загинув у Чумних Землях, полонених фермерів визнали непотрібними й віддали аптекарям.",al={"чому фермери в полоні","чому дарталія захопила фермерів","чому фермери в таррен міллі"}}},fp="11,292,16.408.0,24.504.1,31.171.0,39.169.0,24.165.1,41.264.0"}
